INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('008fbf19-eeda-4e3b-a3a2-79c668c8592e', 'Tenho uma pedra viva', '163', 'Autor Desconhecido', 'Guarânia', 'E', 'Dedicação', 'TENHO UMA PEDRA VIVA,
PEDRA DE ESQUINA,
PEDRA ANGULAR; 
CRISTO É ROCHA DURA,
TODA CRIATURA PODE SEGURAR.

CANTAR 2X
ESTA ROCHA É CRISTO,
TODO IMPREVISTO PODE RESOLVER,
PORÉM TEUS PECADOS SERÃO PERDOADOS,
CRISTO TEM PODER.

*CORO
CRISTO TEM PODER E SABE LUTAR,
ELE É PODEROSO,
ELE É O LEÃO DA TRIBO DE JUDÁ,
CRISTO TEM PODER E SABE LUTAR,
ELE É PODEROSO,
ELE É O LEÃO DA TRIBO DE JUDÁ.

ESTA ROCHA É ÁGUA
E QUEM TEM SUAS MÁGOAS ELE VAI TIRAR.
NUNCA ESTOU SOZINHO,
CRISTO É MEU CAMINHO, NELE TENHO PAZ.

CANTAR 2X
TEM PAZ VERDADEIRA
QUEM NESTA ROCHA FIRMADO ESTÁ.
CRISTO É A VERDADE
E, SE CRERES NELE, TE LIBERTARÁ.

*CORO
CRISTO TEM PODER E SABE LUTAR,
ELE É PODEROSO,
ELE É O LEÃO DA TRIBO DE JUDÁ,
CRISTO TEM PODER E SABE LUTAR,
ELE É PODEROSO,
ELE É O LEÃO DA TRIBO DE JUDÁ.
/FINAL
ELE É PODEROSO,
ELE É O LEÃO DA TRIBO DE JUDÁ.
');
