INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0093e325-8b55-4134-9845-97712e16c402', 'Quanto tempo faz', '042', '', '', '', '', 'QUANTO TEMPO FAZ QUE VOCÊ NÃO ORA?
QUANTO TEMPO FAZ QUE VOCÊ NÃO ENTRA
NO SEU QUARTO E CHORA?
QUANTO TEMPO FAZ QUE VOCÊ
NÃO CANTA MAIS UM HINO DE VITÓRIA?
QUANTO TEMPO FAZ?
JÁ FAZ MUITO TEMPO,
NEM SE LEMBRA MAIS.

*CORO
MAS HOJE CHEGOU PARA TI UM
GRANDE RENOVO,
DEUS VAI COLOCAR EM SUA BOCA
UM CÂNTICO NOVO,
COMECE A GLORIFICAR
O SEU SANTO NOME, POIS ELE ESTÁ
PRESENTE E VAI TE ALEGRAR.

QUANTO TEMPO FAZ,
QUE NÃO TENS ALEGRIA?
QUANTO TEMPO FAZ QUE VOCÊ PERDEU
O DOM DE PROFECIA?
QUANTO TEMPO FAZ QUE A SUA VIDA
É TRISTE E VAZIA?
QUANTO TEMPO FAZ?
JÁ FAZ MUITO TEMPO,
NEM SE LEMBRA MAIS.

*CORO 2X
MAS HOJE CHEGOU PARA TI
UM GRANDE RENOVO,
DEUS VAI COLOCAR EM SUA BOCA
UM CÂNTICO NOVO,
COMECE A GLORIFICAR
O SEU SANTO NOME, POIS ELE ESTÁ
PRESENTE E VAI TE ALEGRAR.
');
