INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('01a2c719-4386-4ba6-b269-d57c6c03e0b1', 'O espírito de Deus', '', '', '', '', '', 'SANTO ESPÍRITO DE AMOR,
VEM MOSTRAR-NOS TEU FAVOR!
Ó CONSOLADOR REAL,
DÁ-NOS GRAÇA DIVINAL.
GRANDE INSTRUTOR VERAZ
DÁ-NOS SEMPRE TUA PAZ.
ENCHA O MUNDO A TUA LUZ,
GUIE TODOS A JESUS.

OH, NUNCA, NUNCA,
CESSARÃO MEUS LÁBIOS,
DE BENDIZER-TE, DE ENTOAR-TE GLÓRIA.
POIS EU CONSERVO DE TEU BEM IMENSO
GRATA MEMÓRIA
AMÉM.
');
