INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('01cd300a-558c-4498-b301-d0139bc15467', 'Como uma folha ao vento', '142', 'M.L.M.B.O.', 'Balada', 'D', 'Crianças e Adolescentes', 'COMO UMA FOLHA AO VENTO
VOA PRA LÁ E PRA CÁ,
EU TAMBÉM QUERO ESTAR
AONDE O ESPÍRITO SANTO MANDAR.

NÃO FAÇO MAIS O QUE EU QUERO,
MAS O QUE DEUS REVELAR;
COMO UMA FOLHA AO VENTO,
VOANDO VAI SEMPRE ONDE O VENTO SOPRAR,
/FINAL 2X
EU TAMBÉM QUERO ESTAR
AONDE O ESPÍRITO SANTO MANDAR.
');
