INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0208cb3d-c868-4511-a099-8e87bcb7ec4e', 'Eu vim aqui, Senhor', '225', 'J.L.M.M.', 'Básico', 'D', 'Crianças e Adolescentes', 'EU VIM AQUI, SENHOR, PARA AGRADECER
POR TUDO O QUE TENS FEITO POR MIM;
ALEGRE ESTOU POR MAIS UM DIA
NA TUA PRESENÇA, Ó DEUS.

CORO 2X
GLÓRIA A JESUS,
MARAVILHOSO ÉS PRA MIM,
ÉS FORTE E PODEROSO
E CUMPRE SUAS PROMESSAS.

O MEU PRAZER É TE LOUVAR
PORQUE O SENHOR É FIEL;
EU SEI QUE APENAS PEQUENO SOU,
MAS SIRVO A TI POR AMOR.
');
