INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0212391b-30ab-40e2-8c21-ad9de593065f', 'Majestade gloria e majestade', '595', 'Let. e Mús.: Jack W. Hayford', 'Fox', 'G', 'Louvor', 'MAJESTADE, GLÓRIA E MAJESTADE,
JESUS CRISTO MERECE TODO LOUVOR;
MAJESTADE, GLÓRIA E MAJESTADE,
SEU É O LOUVOR, SEU É O PODER,
GLÓRIA A ELE!

EXALTAI, ENGRANDECEI SEU SANTO NOME!
ADORAI, MAGNIFICAI A CRISTO REI!
MAJESTADE, GLÓRIA E MAJESTADE,
CRISTO MORREU, RESSUSCITOU
E HOJE É SENHOR.
');
