INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('026db05a-b158-4c3b-931b-eeae153ee9dc', 'Deus forte como Jeová', '126', 'Autor Desconhecido', 'Country', 'Dm', 'Crianças e Adolescentes', 'CANTAR 2X
DEUS FORTE COMO JEOVÁ,
NÃO HÁ OUTRO QUE EU CONHEÇA.
/CANTAR 2X
DEUS DE VITÓRIA, VARÃO DE GUERRA,
DEUS PODEROSO É O SENHOR.

CANTAR 2X
ONDE, ONDE ESTÁ O TEU DEUS?
ONDE, ONDE ESTÁ O TEU DEUS?

FINAL 2X
MEU DEUS ESTÁ NO CÉU,
TAMBÉM NO MEU CORAÇÃO,
O DO MUNDO ESTÁ MORTO
MAS O MEU RESSUSCITOU.
');
