INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('027dee98-af11-4e87-a08d-08e25c3737d9', 'Jesus ia Subindo o Monte', '203', 'João Batista dos Santos', 'Básico', 'Em', 'Morte, Ressureição e Salvação', 'JESUS IA SUBINDO O MONTE,
CARREGANDO A NOSSA CRUZ;
NOSSO FARDO DE PECADO,
SOBRE SI ELE LEVOU.
ELE NÃO TINHA PECADO, 
MAS POR NÓS JESUS MORREU,
PRA NOS DAR A LIBERDADE, 
SUA VIDA ELE DEU.

POR NÓS JESUS MORREU, FOI POR AMOR
QUE ELE SE ENTREGOU,
AS NOSSAS DORES LEVOU
E O PECADO PERDOOU.

TODA LUZ SE ESCURECEU,
O DIA EM TREVAS SE TORNOU,
POIS NAQUELA DURA CRUZ
MORREU O FILHO DE DEUS.

CANTAR 2X
MAS ELE RESSUSCITOU,
VENCEU A MORTE E A CRUZ,
VENCEU O MAL, ME LIBERTOU DO PESO
QUE ANTES CARREGUEI,
LEVOU AS NOSSAS DORES
E A SALVAÇÃO NOS DEU.

CANTAR 2X
POR NÓS JESUS MORREU,
POR NÓS RESSUSCITOU,
O PREÇO DA LIBERDADE,
COM SEU SANGUE ELE PAGOU;
/FINAL
AMÉM! AMÉM!
');
