INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('02d49e79-48f1-43ca-8166-c92649d7c760', 'Espera no Senhor, anima-te', '348', 'Raquel Toscano de Freitas', 'Básico', 'C', 'Consolo e Encorajamento', 'ESPERA NO SENHOR, ANIMA-TE,
E ELE FORTALECERÁ TEU CORAÇÃO;
/CANTAR 2X
O SENHOR É A FORÇA DO SEU POVO,
O SENHOR É A FORÇA DO SEU POVO.

CONHECES MINHA ALMA NAS ANGÚSTIAS
E AS ÂNSIAS DO MEU CORAÇÃO;
EM TI PONHO MINHA CONFIANÇA
POIS TU, SENHOR, ÉS A FORÇA DO SEU POVO.
/O SENHOR É A FORÇA DO SEU POVO. (4X)
');
