INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('031eabb4-d340-48fe-bc25-cb4a00d273bb', 'Você não está sozinho', '', '', '', '', '', 'VOCÊ NÃO ESTÁ SOZINHO
COMO PODE IMAGINAR,
DESPERTE E SINTA O CARINHO
QUE O SENHOR TEM PRA LHE DAR;
AMOR IMENSO QUE NO HOMEM
NÃO SE PODE ACHAR,
QUE GRAÇA INCOMPARÁVEL!

*CORO 2X
QUANDO EU PENSO QUE ESTE DEUS
QUE FEZ A TERRA E O MAR
ESTÁ COMIGO, AO MEU LADO,
EU COMEÇO A CHORAR,
A CHORAR PORQUE O SENHOR ESTÁ COMIGO,
AO MEU LADO, A CADA INSTANTE, ELE É O MEU
MAIOR AMIGO,
NÃO ME DEIXA SÓ.
');
