INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('032317f0-cbee-4d21-a5d5-4d43a33c5d41', 'Te exaltaremos', '633', 'José Elias Simora', 'Básico', 'A', 'Louvor', 'TE EXALTAREMOS PARA SEMPRE, Ó DEUS,
ETERNAMENTE COM NOSSO LOUVOR,
AGRADECIDOS PELO QUE TENS FEITO,
PELOS LIVRAMENTOS E PROVAÇÕES.

CORO
NÓS TE ADORAMOS E ENTREGAMOS
EM GRATIDÃO, SENHOR, AS NOSSAS VIDAS,
EM SACRIFÍCIO VIVO DE LOUVOR
OFERECEMOS SEMPRE A TI, SENHOR.

COM NOSSOS LÁBIOS EXPRESSAREMOS
NOSSA GRATIDÃO A TI, SENHOR,
E A NOSSA ALEGRIA SERÁ RENOVADA
A CADA INSTANTE POR TEU LOUVOR.

FINAL
NÓS TE ADORAMOS E ENTREGAMOS
EM GRATIDÃO, SENHOR,
AS NOSSAS VIDAS,
E A NOSSA ALEGRIA SERÁ RENOVADA
A CADA INSTANTE POR TEU LOUVOR.
');
