INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('03889b1a-3848-4808-8db3-f114b8eb88bf', 'Jesus falou que o céu é pra mim', '076', 'A.F.C.J.', 'Fox', 'D', 'Crianças e Adolescentes', 'JESUS FALOU QUE O CÉU É PRA MIM,
O CÉU É PRA MIM, O CÉU É PRA MIM.
JESUS FALOU QUE O CÉU É PRA MIM,
O CÉU É PRA MIM, EU VOU COM ELE, SIM.

CORO
E SE VOCÊ QUISER O CÉU TAMBÉM
PRECISA ACEITAR JESUS EM SEU CORAÇÃO,
PARA PODER LHE TRANSFORMAR E O CÉU LHE DAR
E LÁ VOCÊ MORAR.

EU SOU FIEL E JESUS ME QUER BEM,
JESUS ME QUER BEM,
JESUS ME QUER BEM.
POR ISSO EU SEI QUE O CÉU É PRA MIM,
O CÉU É PRA MIM,
EU VOU PRA GLÓRIA, SIM.
');
