INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('03e25972-436e-4676-89ee-293b027b7231', 'Eu quero andar sempre com Jesus', '036', 'E.H.M.R.', 'Fox', 'D', 'Crianças e Adolescentes', 'EU QUERO ANDAR SEMPRE COM JESUS,
À ETERNIDADE ELE ME CONDUZ;
E QUANDO A LUTA TIVER QUE ENFRENTAR
ELE ESTARÁ A ME PROTEGER.

SUSTENTA-ME, PEGA A MINHA MÃO,
LEVANTA-ME, DÁ-ME A SALVAÇÃO;
CRESCER COM ELE É O MAIOR TESOURO,
TRABALHAR PRA ELE É A MINHA ADORAÇÃO.
/FINAL
TRABALHAR PRA ELE É A MINHA ADORAÇÃO.
');
