INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('03e3a1a7-58ab-4ca9-8d6e-8e76e7a44ee5', 'Assim como a noite espera o dia', '481', 'Edison Coelho', 'Balada', 'D', 'Volta de Jesus e Eternidade', 'ASSIM COMO A NOITE ESPERA PELO DIA,
ASSIM COMO A PRAIA ESPERA PELO MAR,
ASSIM COMO AS NUVENS ESPERAM PELO VENTO,
COM MAIS ANSIEDADE EU ESTOU A TE ESPERAR.

*CORO
TE ESPERO, CHORANDO,
TE ESPERO, MESTRE QUERIDO,
ESTOU ME ENCURVANDO
ANTE O PESO NA CRUZ;
ME AJUDA A CHEGAR AO MEU LAR PROMETIDO,
SEM TI NÃO CONSIGO VIVER, MEU JESUS.

BEM MAIS QUE AS FLORES ESPERAM PELO ORVALHO,
BEM MAIS QUE O PERDIDO ESPERA SE ENCONTRAR,
BEM MAIS QUE O FILHO ESPERA A MÃE QUERIDA,
COM MAIS ANSIEDADE EU ESTOU A TE ESPERAR.

*CORO
TE ESPERO, CHORANDO,
TE ESPERO, MESTRE QUERIDO,
ESTOU ME ENCURVANDO
ANTE O PESO NA CRUZ;
ME AJUDA A CHEGAR AO MEU LAR PROMETIDO,
SEM TI NÃO CONSIGO VIVER, MEU JESUS.
/FINAL
Ó, MEU JESUS.
');
