INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('03ffccf9-de03-479e-985d-01cf486401da', 'Se andarmos na luz', '016', 'I Jo1:7; Adap. Let. Everaldo Cavalcante Lima, Mús. Everaldo Cavalcante Lima e Edmar Cavalcante Lima', 'Básico', 'E', 'Clamor', 'CANTAR 2X
SE ANDARMOS NA LUZ,
COMO NA LUZ ELE ESTÁ,
/TEMOS COMUNHÃO COM O SENHOR
E TAMBÉM COM OS IRMÃOS,
SE ANDARMOS NA LUZ,
COMO NA LUZ ELE ESTÁ.

FINAL 2X
E ASSIM O SANGUE DE JESUS
TEM PODER PARA SALVAR,
TEM PODER PARA CURAR,
TEM PODER PRA PERDOAR
E TAMBÉM PURIFICAR.
');
