INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('04327b69-5aaf-409e-b457-62202dd1ed45', 'Aqui Chegamos Pela Fé (Coro Masculino)', '', '', '', '', '', 'AQUI CHEGAMOS PELA FÉ,
CONFIANDO EM DEUS.
A PALAVRA É FIEL,
NÃO OLHAREMOS PARA TRÁS.
VAMOS COM FÉ,
NÃO VOLTAREMOS.
AQUI CHEGAMOS PELA FÉ.

EU RELEMBRO O QUE DEUS
FEZ POR MIM.
AS COISAS IMPOSSÍVEIS,
NAS MÃOS DE MEU
BOM MESTRE ENTREGUEI.

AQUI CHEGAMOS PELA FÉ,
CONFIANDO EM DEUS.
A PALAVRA É FIEL.
NÃO OLHAREMOS PARA TRÁS.
VAMOS COM FÉ, NÃO VOLTAREMOS.
AQUI CHEGAMOS PELA FÉ.
AQUI CHEGAMOS PELA FÉ.
CHEGAMOS PELA FÉ.
');
