INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('04713c81-5202-430b-b04a-3224ce5ca410', 'Como tu queres', '401', 'Autor Desconhecido', 'Básico', 'D', 'Santificação e Derramamento', 'COMO TU QUERES, SENHOR, SOU TEU,
TU ÉS OLEIRO, VASO SOU EU;
QUEBRA E TRANSFORMA ATÉ QUE, ENFIM,
TUA VONTADE SE CUMPRA EM MIM.
');
