INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('047c1e30-4af3-41cd-a702-c506f9e78dc1', 'É teu sangue', '', '', '', '', '', 'EM TEU SANGUE JESUS, EU ENCONTRO A PAZ,
NO TEU SANGUE SENHOR, SEI QUE A DEUS SATISFAZ.
MEUS PECADOS LAVOU, VIDA NOVA ME DEU,
TENS ME DADO O PERDÃO, VIDA E COMUNHÃO.
FOI NA CRUZ, QUE MORREU.
FOI NA CRUZ,
FOI NA CRUZ QUE ELE VENCEU.

EU AGORA JESUS, QUERO TE ADORAR.
DAR-TE TODO O LOUVOR SANTO NESTE LUGAR.
SEI QUE TU VOLTARÁS PARA,
NO MUNDO REINAR, TUA IGREJA
TE ESPERA, MARANATA VEM JÁ!
MEU JESUS VOLTARÁ
MEU JESUS, PARA SEMPRE,
REINARÁ!
');
