INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0584564b-edff-4a11-8477-d30a2cbcd9da', 'Jesus Cristo voltará com seu grande esplendor', '511', 'Jorgemar Souza Madeira', 'Básico', 'E', 'Volta de Jesus e Eternidade', 'JESUS CRISTO VOLTARÁ
COM SEU GRANDE ESPLENDOR,
A IGREJA SUBIRÁ AO ENCONTRO DO SENHOR.

*CORO
MARANATA, MARANATA, VEM, JESUS!
MARANATA, MARANATA, VEM, JESUS!

ESSE DIA CHEGARÁ, ESTAREMOS NAS MANSÕES,
TUDO AQUI HÁ DE FINDAR, 
JESUS CRISTO VOLTARÁ.

*CORO
MARANATA, MARANATA, VEM, JESUS!
MARANATA, MARANATA, VEM, JESUS!

CANTAREMOS LOUVORES JUNTO COM OS ANJOS
A JESUS, O REI.
TODOS OS SEUS REMIDOS NO CÉU ESTARÃO
LOUVANDO A CRISTO, O REI.

*CORO
MARANATA, MARANATA, VEM, JESUS!
MARANATA, MARANATA, VEM, JESUS!
/FINAL
MARANATA, MARANATA, VEM, JESUS!
');
