INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0597b3ed-80e2-4a34-9b8e-f8901fceeeff', 'Buscou-me com ternura', 97, 'W.S.W', 'Balada', 'G', 'Dedicação', 'BUSCOU-ME COM TERNURA
JESUS, O BOM PASTOR;
ACHOU-ME NA MISÉRIA,
SALVOU-ME COM AMOR;
NO CÉU CANTARAM DE ALEGRIA
OS ANJOS, SIM, EM HARMONIA.

CORO
OH! QUE AMOR GLORIOSO!
PREÇO TÃO GRANDIOSO,
QUE JESUS POR MIM NA CRUZ PAGOU;
INAUDITA GRAÇA ME MOSTROU! 

FERIDO, ABANDONADO, 
JESUS ME SOCORREU; 
E SEGREDOU-ME: “ACHEI-TE;
DE AGORA EM DIANTE ÉS MEU”.
TÃO MEIGA VOZ JAMAIS OUVI, 
PRAZER MAIOR JAMAIS SENTI.

JESUS MOSTROU-ME AS CHAGAS QUE 
EM MEU LUGAR SOFREU, COROA, 
MAS DE ESPINHOS, A CRUZ QUE PADECEU.
QUE PODERIA EM MIM ACHAR,
PRA TAIS AFRONTAS SUPORTAR?

ENQUANTO AS HORAS PASSAM, 
EU TENHO GOZO E PAZ, E AGUARDO 
MEU BOM MESTRE, QUE TÃO FELIZ ME FAZ!
JESUS A MIM VIRÁ BUSCAR,
E ENTÃO PRA SEMPRE IREI GOZAR!
');
