INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('05c7b662-25ab-4158-9d55-7ab92e7b412c', 'O mesmo Deus', '337', 'Jackson de Halley Fernandes Fontes', 'Valseado', 'C', 'Consolo e Encorajamento', 'O MESMO DEUS QUE ONTEM
DE MIM CUIDOU,
VIVO ESTÁ HOJE EM MEU VIVER,
MISERICÓRDIAS ME SEGUIRÃO
CADA DIA DO MEU VIVER;

NADA TENHO QUE TEMER
POIS JESUS ME GUARDARÁ,
NADA TENHO QUE TEMER
POIS JESUS ME GUIARÁ;
E ME LEVARÁ À FONTE DA VIDA
E NO CÉU ME RECEBERÁ.

O MESMO DEUS QUE ONTEM
DE MIM CUIDOU,
VIVO ESTÁ HOJE EM MEU VIVER,
MISERICÓRDIAS ME SEGUIRÃO
CADA DIA DO MEU VIVER;

NADA TENHO QUE TEMER
POIS JESUS ME GUARDARÁ,
NADA TENHO QUE TEMER
POIS JESUS ME GUIARÁ;
E ME LEVARÁ À FONTE DA VIDA
E NO CÉU ME RECEBERÁ. (3X)
');
