INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('061572f5-0a2f-4145-89d8-f974267b865c', 'Careço de Jesus', '713', '', 'Canção', 'Ab', 'Grupo de Louvor', 'CAREÇO DE JESUS!
SEMPRE DE TI, SENHOR!
SOMENTE A TUA VOZ
TEM PARA MIM VALOR!

CORO
DE TI, SENHOR, CAREÇO,
SEMPRE DE TI CAREÇO!
OH! DÁ-ME A TUA BÊNÇÃO,
ASPIRO A TI!

CAREÇO DE JESUS!
UNIDO A TI, SENHOR,
PECADO E TENTAÇÃO
PERDEM O SEU VIGOR.

CAREÇO DE JESUS!
REGE MEU CORAÇÃO!
ENSINA-ME A VIVER
EM SANTA RETIDÃO!

CAREÇO DE JESUS!
NAS TREVAS E NA LUZ!
SEM TI A VIDA É VÃ;
SOU POBRE SEM JESUS.
');
