INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('061f4822-fcf6-4e2b-8a51-e76582bbae8b', 'Ele é exaltado', '', '', '', '', '', 'ELE É EXALTADO, O REI É EXALTADO
NO CÉU, EU O LOUVAREI!
ELE É EXALTADO, PRA SEMPRE
EXALTADO, SEU NOME LOUVAREI.
ELE É O SENHOR, SUA VERDADE
VAI SEMPRE REINAR.

TERRA E CÉU GLORIFICAM SEU SANTO NOME.
ELE É EXALTADO,
O REI É EXALTADO NO CÉU.
/INSTRUMENTOS

ELE É EXALTADO, O REI É EXALTADO
NO CÉU, EU O LOUVAREI!
ELE É EXALTADO, PRA SEMPRE
EXALTADO, SEU NOME LOUVAREI.
ELE É O SENHOR, SUA VERDADE
VAI SEMPRE REINAR.

TERRA E CÉU GLORIFICAM SEU SANTO NOME.
ELE É EXALTADO,
O REI É EXALTADO NO CÉU.
ELE É EXALTADO,
O REI É EXALTADO NO CÉU.
');
