INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0657ade2-5a11-4ada-b3da-2b27681ba051', 'Somos Teu Povo, Tua Igreja', '216', 'Eloísa Helena Malavasi Ribeiro', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'SOMOS TEU POVO, TUA IGREJA,
MORRESTE POR NÓS, SENDO REI, SENHOR!
QUISESTE SALVAR O MUNDO,
MAS O MUNDO NÃO QUIS.

A TUA IGREJA TE AMA
E FAZ DO TEU SANGUE ESCUDO FORTE.
A TUA PALAVRA É ALIMENTO FORTE
QUE FAZ NOSSA VIDA FELIZ!

FINAL 2X
A TUA IGREJA TE ESPERA, NÃO SE APRESSA,
PORQUE TU, JESUS, VOLTARÁS
E A LEVARÁS PARA UM LAR DE PAZ,
ONDE REINA O AMOR.
');
