INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('081ac90e-ec4d-44b3-a469-b2a13fb57980', 'Amor, que por amor desceste!', '689', 'Let.: George Matheson; Mús.: Albert Lister Peace', 'Básico', 'Ab', 'Grupo de Louvor', 'AMOR, QUE POR AMOR DESCESTE!
AMOR, QUE POR AMOR MORRESTE!
AH! QUANTA DOR NÃO PADECESTE,
MEU CORAÇÃO PRA CONQUISTAR
E MEU AMOR GANHAR!

AMOR, QUE COM AMOR SEGUIAS A MIM,
QUE SEM AMOR TU VIAS!
OH! QUANTO AMOR POR MIM SENTIAS,
MEU SALVADOR, MEU BOM JESUS,
SOFRENDO SOBRE A CRUZ!
/INSTRUMENTOS

AMOR, QUE TUDO ME PERDOAS!
AMOR, QUE ATÉ MESMO ABENÇOAS
UM RÉU A QUEM TU TE AFEIÇOAS!
POR TI VENCIDO, Ó SALVADOR,
EIS-ME AOS TEUS PÉS, SENHOR.

AMOR QUE NUNCA, NUNCA MUDA,
QUE EM TUA GRAÇA ME SEGURA,
CERCANDO-ME DE MIL VENTURAS;
ACEITA AGORA, Ó SALVADOR,
O MEU HUMILDE AMOR!
');
