INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0854f78e-30d9-4577-847c-ad948f2a99c8', 'Deixa Meu Povo Ir Vai, Moisés', '011', '', '', 'D', 'Avulsos', 'VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!

NO EGITO ESTAVA ISRAEL
(DEIXA MEU POVO IR!)
OPRESSO E SEM SUPORTAR
(DEIXA MEU POVO IR!)

*CORO
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!

AO EGITO DESCEU POIS MOISÉS
(DEIXA MEU POVO IR!)
A  FARAÓ PERSUADIU
(DEIXA MEU POVO IR!)

*CORO
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!

ASSIM FALOU DEUS A MOISÉS
(DEIXA MEU POVO IR!)
OS PRIMOGÊNITOS MATAREI
(DEIXA MEU POVO IR!)

*CORO
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!
/INSTRUMENTOS

FINAL
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!
VAI, MOISÉS!
DEIXA MEU POVO IR!
');
