INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('088071a3-c7fb-4405-97e8-03edfe8762f5', 'Sobre as nuvens descerá (Ele virá)', '216', 'I.L.S.P.', 'Básico', 'A', 'Crianças e Adolescentes', 'SOBRE AS NUVENS DESCERÁ
NOSSO REI E SALVADOR;
COM PODER E GRANDE GLÓRIA
AO SOAR DA TROMBETA ELE VIRÁ.

*CORO
ELE VIRÁ (ARREBATAR)
ELE VIRÁ (NÃO TARDARÁ)
ELE VIRÁ PARA BUSCAR A IGREJA FIEL.

TUDO AQUI HÁ DE FINDAR,
TUDO NOVO ELE FARÁ!
QUEM VENCER TUDO HERDARÁ
E NO CÉU COM JESUS VAMOS MORAR.

*CORO
ELE VIRÁ (ARREBATAR)
ELE VIRÁ (NÃO TARDARÁ)
ELE VIRÁ PARA BUSCAR A IGREJA FIEL.

A NOVA JERUSALÉM
O CORDEIRO ILUMINARÁ,
RIO PURO HAVERÁ
E A ÁRVORE DA VIDA ALI ESTARÁ.

*CORO 2X
ELE VIRÁ (ARREBATAR)
ELE VIRÁ (NÃO TARDARÁ)
ELE VIRÁ PARA BUSCAR A IGREJA FIEL.
/FINAL
ELE VIRÁ PARA BUSCAR A IGREJA FIEL.
');
