INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('08a2ecaa-c395-4841-91bc-9e63543ae87b', 'Agradecidos somos a ti', '646', 'Angela Karla Ribeiro Pereira dos Santos', 'Básico', 'C', 'Crianças e Adolescentes', 'AGRADECIDOS SOMOS A TI, MEU REI JESUS,
PELA GRAÇA E PELA VIDA QUE HOJE HÁ EM NÓS;
GRATOS SOMOS POR TÃO GRANDE AMOR
DEMONSTRADO NO MADEIRO,
TU ÉS MEU SALVADOR.

CORO
ALELUIA TE DAMOS, Ó MEU SENHOR,
PELA PAZ QUE HOJE HABITA
EM NOSSOS CORAÇÕES;
POR NÓS JESUS MORREU,
QUE DOR ELE SENTIU,
MAS AO TERCEIRO DIA ELE RESSURGIU.

ALELUIA TE DAMOS, Ó MEU SENHOR,
PELA PAZ QUE HOJE HABITA
EM NOSSOS CORAÇÕES;
E HOJE VIVO ESTÁ À DESTRA DE DEUS PAI
AGUARDANDO A HORA CERTA
PARA VIR NOS BUSCAR.

FINAL
AGRADECIDOS SOMOS A TI,
MEU REI JESUS,
PELA GRAÇA E PELA VIDA
QUE HOJE HÁ EM NÓS;
QUE HOJE HÁ EM NÓS.
');
