INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('08a66eb2-f5d7-4dce-8915-19d0024b6096', 'És o pão da vida', '429', 'Sérgio Paulo Ferreira de Matos', 'Básico 2', 'Bm', 'Santificação e Derramamento', 'ÉS O PÃO DA VIDA, CELESTIAL MANÁ,
DELE, QUEM COMER, PRA SEMPRE VIVERÁ;
EM TEU CORPO REPARTIDO,
SOMOS UM SÓ POVO UNIDO
PELOS LAÇOS DE AMOR NO TEU SANTO ESPÍRITO.

ÉS JESUS, DA VIDE, O DOCE FRUTO,
VIDA ABUNDANTE QUE NOS SATISFAZ;
/FINAL 2X
PELO SANGUE DA TUA CRUZ
ALCANÇAMOS VIDA E LUZ,
CÁLICE TRANSBORDANTE DE ALEGRIA E DE PAZ
');
