INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('08bf6ac5-4172-42d7-ba20-0b56bc080058', 'Meu barco é pequeno', '132', 'Autor Desconhecido', 'Balada', 'A', 'Crianças e Adolescentes', 'MEU BARCO É PEQUENO E GRANDE É O MAR,
