INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('08d9c715-7768-4aef-8911-0f11857f673b', 'Uma certa vez Jesus Cristo', '148', 'Napoleão', 'Balada', 'G', 'Dedicação', 'UMA CERTA VEZ JESUS CRISTO,
PARA UMA GRANDE MULTIDÃO
NA PRAIA DA GALILEIA,
FEZ UMA MULTIPLICAÇÃO:
COM DOIS PEIXES E CINCO PÃES,
TODOS JULGAVAM QUE NÃO;
A MAIS DE CINCO MIL PESSOAS
DEU COMIDA BOA, DEU PEIXE E DEU PÃO.

CORO
ESTE QUE É DEUS,
DEUS PODEROSO, DO CELESTE LAR;
ESTE QUE É DEUS,
QUE VENDO O POVO TODO A PECAR
MANDOU SEU FILHO
PARA QUE O MUNDO VIESSE SALVAR,
ESTE DEUS MARAVILHOSO DÁ PAZ E DÁ GOZO
A QUEM O ACEITAR.

JESUS ORDENOU AO POVO
QUE SE ASSENTASSE NO CHÃO,
E RECEBENDO UMA CESTA
COM DOIS PEIXES E CINCO PÃES,
DEU GRAÇAS AO PAI DIVINO,
DISSE: "TENDE COMPAIXÃO."
OS DISCÍPULOS, NAQUELE MOMENTO,
TIVERAM ALIMENTO PARA A MULTIDÃO.

PARA QUE NADA PERDESSE,
MANDOU AS SOBRAS JUNTAR:
DOZE CESTOS DE PEDAÇOS
FOI O QUE VEIO A SOBRAR;
JESUS AINDA É O MESMO,
OH! QUE ALEGRIA SEM PAR;
ESTE JESUS PODEROSO, LÁ DO CÉU DE GOZO
ESTÁ A NOS CONTEMPLAR.
');
