INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('08f336b1-881e-41f8-b2ad-0a72cc53afbf', 'Jesus vem nos buscar', 82, 'S.G.D.', 'Fox Abafado', 'D', 'Crianças e Adolescentes', 'JESUS VEM NOS BUSCAR,
PROMETEU E NÃO FALHARÁ,
PORÉM ELE NOS DISSE:
DOIS CAMINHOS HAVERÁ.

UM CAMINHO É CERTO,
É ESTREITO E APERTADO,
É O CAMINHO DE  JESUS,
FIRMADO NELE QUERO ESTAR.

OUTRO CAMINHO TAMBÉM HÁ,
É LARGO, ESPAÇOSO E CONDUZ À PERDIÇÃO,
POR ELE MUITOS VÃO,
POIS REJEITAM DE JESUS A SALVAÇÃO.

JESUS A TODOS CONVIDA:
"EU SOU CAMINHO A VERDADE E A VIDA"
/FINAL 2X
VEM DEPRESSA, VEM DEPRESSA, VEM!
A PORTA ABERTA UM DIA FECHARÁ.
');
