INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('097221c2-1a75-4b59-b141-82dcb3b08ec4', 'Breve voltará o Messias', '534', 'Sérgio Paulo Ferreira de Matos', 'Fox Abafado', 'A', 'Volta de Jesus e Eternidade', 'BREVE VOLTARÁ O MESSIAS,
O UNGIDO DE DEUS, O REI, O SENHOR,
O QUE É DIGNO DE TODO O LOUVOR.

O SOL PERDERÁ O SEU BRILHO
E A LUA NÃO DARÁ MAIS A SUA LUZ
QUANDO O FILHO DO HOMEM VOLTAR.

TODOS OS POVOS DA TERRA VERÃO
VINDO SOBRE AS NUVENS DO CÉU,
/FINAL 2X
COM GLÓRIA, COM GLÓRIA,
COM GLÓRIA JESUS VOLTARÁ!
');
