INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0a2a4640-8562-4036-9280-9b164c10c6c4', 'Vem, Senhor visita tua vinha', '463', 'Hélcio Duarte Salles', 'Básico', 'C', 'Santificação e Derramamento', 'VEM, SENHOR, VISITA TUA VINHA,
QUE PLANTASTE EM NOSSAS VIDAS
COM TUA DESTRA.
VEM, SENHOR, VISITA TUA VINHA,
QUE COMPRASTE COM TEU PRECIOSO SANGUE.

*CORO
VEM VISITA-ME;
Ó VEM, PURIFICA-ME,
SONDA O MEU CORAÇÃO
E DÁ-ME O TEU SANTO PERDÃO
E FAZE-ME REPOUSAR EM TI, SENHOR.

QUERO SER, SENHOR, TEU SERVO AMADO
POIS CONFIO EM TEU PODER, Ó MEU JESUS;
PODER QUE PARA MIM É INFINITO
E É DADO A TODO AQUELE QUE EM TI CRER.

*CORO
VEM VISITA-ME;
Ó VEM, PURIFICA-ME,
SONDA O MEU CORAÇÃO
E DÁ-ME O TEU SANTO PERDÃO
E FAZE-ME REPOUSAR EM TI, SENHOR.
/FINAL
E FAZE-ME REPOUSAR EM TI, SENHOR.
');
