INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0a4af1ea-35f7-4e46-abde-2063869311f7', 'Mais uma vez', 83, 'Paulo Emanuel dos Santos Teixeira', 'Básico', 'A', 'Invocação e Comunhão', 'CANTAR 2X
MAIS UMA VEZ,
ESTAMOS AQUI, SENHOR,
MAIS UMA VEZ PEDINDO COMUNHÃO
PARA TE LOUVAR, TE GLORIFICAR,
PARA TE EXALTARMOS,
SENHOR JESUS.

FINAL
PARA TE EXALTARMOS,
SENHOR JESUS.
');
