INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0a7de57b-fd56-439b-a265-600cba9c4bb3', 'Fonte da vida', '585', 'Paulo Emanuel dos Santos Teixeira', 'Balada', 'E', 'Louvor', 'FONTE DA VIDA, ESTRELA DA MANHÃ,
JESUS, O REI DOS REIS, SENHOR, EMANUEL!
CORDEIRO DE DEUS, O LEÃO DE JUDÁ,
CRISTO JESUS.

TE ADORAMOS POIS TU ESTÁS AQUI,
OS NOSSOS CORAÇÕES
ESTÃO CHEIOS DE LOUVOR;

CANTAR 2X
TU ÉS TUDO PRA NÓS, TU ÉS O SENHOR,
CRISTO JESUS.
/FINAL
CRISTO JESUS.
');
