INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0bbaada5-a126-4b35-bf8e-fd15af839966', 'Aleluia Muitas Vozes de Anjos', '592', 'Jorgemar Souza Madeira', 'Valseado', 'C', 'Louvor', 'ALELUIA!
MUITAS VOZES DE ANJOS EXALTAM O NOME
DO CORDEIRO VIVO, JESUS;
AQUELE QUE UM DIA NA AMARGA CRUZ
MORREU COMO PROVA DE AMOR.

*CORO
E SÓ ELE É DIGNO DE TODO O LOUVOR!
GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,
GLÓRIA AO REDENTOR!
GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,
GLÓRIA AO SALVADOR!
/INSTRUMENTOS

ALELUIA!
NÓS TAMBÉM ESTAREMOS NAS LINDAS MANSÕES
LOUVANDO PRA SEMPRE AO SENHOR;
E COM GRANDE ALEGRIA VEREMOS JESUS,
QUE DIA TÃO LINDO SERÁ.

*CORO
E SÓ ELE É DIGNO DE TODO O LOUVOR!
GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,
GLÓRIA AO REDENTOR!
GLÓRIA, GLÓRIA, GLÓRIA, GLÓRIA,
GLÓRIA AO SALVADOR! (2X)
');
