INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0c6684e4-94d4-4f65-9d4b-cd32e2d1923f', 'Vencer, Vencer', '355', 'Jorgemar Souza Madeira', 'Básico', 'D', 'Consolo e Encorajamento', 'VENCER, VENCER,
EU FUI CHAMADO PRA VENCER,
VENCER O MAL, VENCER O MUNDO
POR AMOR, AO MEU DEUS, (2X)

PORQUE SEREI,
SEREI COMO OS ANJOS QUE LOUVAM
A CRISTO JESUS, O MEU REI,
E ESTAREI NAS LINDAS MANSÕES CELESTIAIS,
PELAS RUAS DE OURO ANDAREI.

VENCER, VENCER,
EU FUI CHAMADO PRA VENCER
ATÉ CHEGAR O LINDO DIA
ONDE O MAL CESSARÁ,
ONDE A PAZ REINARÁ.

PORQUE JESUS 
JÁ VENCEU A MORTE NA CRUZ
E DEU SUA GRAÇA, SUA LUZ;
PORQUE SEREI,
SEREI COMO OS ANJOS QUE LOUVAM
A CRISTO JESUS, O MEU REI.

VENCER, VENCER,
EU FUI CHAMADO PRA VENCER,
VENCER O MAL, VENCER O MUNDO
POR AMOR, AO MEU DEUS, (3X)
');
