INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0cebb7ef-496b-41f3-80fb-b61640a125f6', 'Confia e ora - Coro Misto', '', '', '', '', '', 'A VIDA TEM TRISTEZAS MIL,
NEM TUDO É UM CÉU DE ANIL,
MAS CONTRA A DOR,
QUE É TÃO SUTIL,
HÁ UM CAMINHO SÓ:

CONFIA EM DEUS QUE ELE SEMPRE TE OUVIRÁ.
CONFIA EM DEUS QUE ELE NUNCA FALHARÁ.
CONFIA EM DEUS QUE A NEGRA NUVEM PASSARÁ.
OH NÃO DUVIDES, MAS CONFIA EM DEUS.

QUANDO O TEU CÉU ESCURECER,
E A SÓS PENARES TEU SOFRER, NÃO DESANIMES,
PRA VENCER HÁ UM CAMINHO SÓ:
E SE TUA FÉ PROVADA FOR,
E TE ESQUECERES DO SENHOR,
NECESSITANDO UM SALVADOR,
HÁ UM CAMINHO SÓ:
');
