INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0d61ce97-76d2-40bc-a449-aea61675617e', 'Se Você Quiser Saber', '248', 'Raquel Toscano de Freitas', 'Básico', 'C', 'Morte, Ressureição e Salvação', 'SE VOCÊ QUISER SABER
COMO PODE SER FELIZ,
BASTA ABRIR SEU CORAÇÃO
E ACEITAR JESUS.

SE VOCÊ QUER CONHECER
ESTE DEUS MARAVILHOSO
QUE DE BÊNÇÃOS VAI ENCHER SEU CORAÇÃO.

*CORO
NELE HÁ TANTA VIDA,
CERTEZAS E ESPERANÇAS,
VIDA ETERNA E PAZ SEM FIM;
NELE HÁ SALVAÇÃO.

SE VOCÊ QUISER GOZAR
DESTA GRANDE SALVAÇÃO,
VENHA HOJE A JESUS SE ENTREGAR.

*CORO
NELE HÁ TANTA VIDA,
CERTEZAS E ESPERANÇAS,
VIDA ETERNA E PAZ SEM FIM;
NELE HÁ SALVAÇÃO.

FINAL
SE VOCÊ QUISER SABER
COMO PODE SER FELIZ,
BASTA ABRIR SEU CORAÇÃO
E ACEITAR JESUS.
');
