INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0db43aa7-678f-4490-a6d3-3b2ecfd3ea51', 'Todo louvor seja dado a Deus', '643', 'Fábio Andrade', 'Básico', 'E', 'Grupo de Louvor', 'TODO LOUVOR SEJA DADO A DEUS
POR TUDO QUE TENS FEITO EM NOSSAS VIDAS,
NOSSA GRATIDÃO A JESUS, O REI,
FOI ELE QUEM NOS SUSTENTOU ATÉ AQUI,

POR ISSO RENDEMOS 
UM LOUVOR AO REI JESUS
E ENTREGAMOS NOSSAS
VIDAS AO SEU DISPOR.

*CORO
LOUVEMOS AO SENHOR
QUE É JUSTO E PODEROSO,
É QUEM NOS GUIA,
A SUA GRAÇA ESTÁ EM NOSSO MEIO,
A SUA PRESENÇA É VIVA A CADA INSTANTE.
/INSTRUMENTOS

TODO LOUVOR SEJA DADO A DEUS
POR TUDO QUE TENS FEITO EM NOSSAS VIDAS,
NOSSA GRATIDÃO A JESUS, O REI,
FOI ELE QUEM NOS SUSTENTOU ATÉ AQUI,

POR ISSO RENDEMOS 
UM LOUVOR AO REI JESUS
E ENTREGAMOS NOSSAS 
VIDAS AO SEU DISPOR.

*CORO 2X
LOUVEMOS AO SENHOR
QUE É JUSTO E PODEROSO,
É QUEM NOS GUIA,
A SUA GRAÇA ESTÁ EM NOSSO MEIO,
A SUA PRESENÇA É VIVA A CADA INSTANTE.
/FINAL
DE NOSSAS VIDAS.
');
