INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0e5c0359-7e76-41a2-8ab5-bf6bdd5b9cda', 'Se a Vida Parece Pesada', '302', 'Célia Maria Vasconcelos da Costa e Silva', 'Toada', 'E', 'Consolo e Encorajamento', 'SE A VIDA PARECE PESADA
E ACHAS QUE CHEGOU AO FIM;
Ó VEM A JESUS SEM DEMORA,
PORQUE ELE DIZ ASSIM:

*CORO
"VINDE A MIM, CANSADOS, 
SOBRECARREGADOS,
E EU VOS ALIVIAREI;
VINDE A MIM ENTREGAI O VOSSO CORAÇÃO,
E VIDA ETERNA VOS DAREI."

TÃO CEDO A TRISTEZA TE ABATE
E ENTRA EM TEU CORAÇÃO;
NÃO TEMAS, CONFIA EM CRISTO
TERÁS PLENA PAZ, SALVAÇÃO.

*CORO 2X
"VINDE A MIM, CANSADOS, 
SOBRECARREGADOS,
E EU VOS ALIVIAREI;
VINDE A MIM, ENTREGAI O VOSSO CORAÇÃO,
E VIDA ETERNA VOS DAREI."
/FINAL
"E VIDA ETERNA VOS DAREI."
');
