INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0ec28ebd-fcd9-4cce-a246-2f53c13f5496', 'Só o Poder de Deus', '781', 'Autor Desconhecido', 'Balada', 'A', 'Dedicação', 'CANTAR 2X
SÓ O PODER DE DEUS PODE MUDAR TEU SER.
A PROVA QUE EU TE DOU: ELE MUDOU O MEU;
NÃO VÊS QUE SOU FELIZ SEGUINDO AO SENHOR?
NOVA CRIATURA SOU, NOVA SOU!
');
