INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0ef3bffc-220b-41c0-8061-7a6b0b16dd9e', 'O Senhor é a Alegria', '273', 'Jorgemar Souza Madeira', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'O SENHOR É A ALEGRIA, 
É A PAZ E A REDENÇÃO,
ELE É O AUTOR DA SALVAÇÃO;
O SENHOR É A FORTALEZA
DOS QUE CRÊEM NELE ASSIM;
E A VOCÊ ESTÁ CHAMANDO: "VENHA A MIM".

CANTAR 2X
PODE TUDO CONFIAR
A JESUS SE ENTREGAR
SUA VIDA ELE PODERÁ MUDAR.

O SENHOR É A ALEGRIA, 
É A PAZ E A REDENÇÃO,
ELE É O AUTOR DA SALVAÇÃO;
O SENHOR É A FORTALEZA
DOS QUE CRÊEM NELE ASSIM;
E A VOCÊ ESTÁ CHAMANDO: "VENHA A MIM".

CANTAR 2X
PODE TUDO CONFIAR
A JESUS SE ENTREGAR
SUA VIDA ELE PODERÁ MUDAR.

CANTAR 2X
"VINDE A MIM", DISSE JESUS,
"VÓS TODOS QUE ESTAIS CANSADOS,
Ó VINDE A MIM".
/FINAL
DISSE JESUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('0ef3bffc-220b-41c0-8061-7a6b0b16dd9e', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
