INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0f1bb563-2eea-49ff-9914-bee988726961', 'Morri na Cruz por Ti', '204', 'Let.: Frances Ridley Hevergal; Trad.: D.M.Hazlett; Mús.:Philip Paul Bliss', 'Balada', 'A', 'Morte, Ressureição e Salvação', 'MORRI NA CRUZ POR TI,
MORRI PRA TE LIVRAR;
MEU SANGUE, SIM, VERTI
E POSSO TE SALVAR.

CORO 2X
MORRI, MORRI NA CRUZ POR TI, 
QUE FAZES TU POR MIM?

VIVI ASSIM POR TI, 
COM DOR, COM DISSABOR;
SIM, TUDO FIZ AQUI
PRA SER TEU SALVADOR.

EU TROUXE A SALVAÇÃO, 
DOS ALTOS CÉUS LOUVOR,
É LIVRE MEU PERDÃO,
É GRANDE MEU AMOR.
');
