INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0f29d7ad-9686-48ea-83b5-b82c4966fcdd', 'Na nova Jerusalém', '194', 'M.M.F.', 'Balada', 'D', 'Crianças e Adolescentes', 'NA NOVA JERUSALÉM
COM CRISTO IREI MORAR,
POIS ELE ME PROMETEU
QUE UM DIA VIRÁ ME BUSCAR.

*CORO
NA NOVA JERUSALÉM, (3X)
COM CRISTO QUERO ESTAR.

SE VOCÊ QUISER MORAR
NA NOVA JERUSALÉM,
É SÓ A CRISTO ACEITAR
E CANTAR COMIGO TAMBÉM.

NA NOVA JERUSALÉM
COM CRISTO IREI MORAR,
POIS ELE ME PROMETEU
QUE UM DIA VIRÁ ME BUSCAR.

*CORO
NA NOVA JERUSALÉM, (3X)
COM CRISTO QUERO ESTAR.
');
