INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('0f72d337-72ad-4e8e-add7-32dd67909610', 'O Como e grande e doce a promessa', '', '', '', '', '', 'O SENHOR NOS ESCOLHEU
PARA JUNTOS CRESCERMOS
E VENCERMOS O MAL
O AMOR QUE HÁ EM NÓS
É PROMESSA DE DEUS
E NADA PODERÁ NOS SEPARAR.

*CORO
O AMOR DE JESUS É CONSTANTE EM NÓS
POR ISSO SELAMOS DIANTE DELE
O NOSSO AMOR
QUANDO ÀS MINHAS PROVAÇÕES,
VIRÃO MAS SE DEUS É POR NÓS,
QUEM SERÁ CONTRA NÓS?
/INSTRUMENTOS

DE JOELHOS ESTAMOS COM MUITA ALEGRIA
ESSE AMOR VEM DE DEUS SOMOS UM SÓ
EM JESUS ALIANÇA É ETERNA E QUE SEMPRE
ESTEJA EM NOSSOS CORAÇÕES.
/INSTRUMENTOS

*CORO
O AMOR DE JESUS É CONSTANTE EM NÓS
POR ISSO SELAMOS DIANTE
DELE O NOSSO AMOR
QUANDO ÀS MINHAS PROVAÇÕES,
VIRÃO MAS SE DEUS É POR NÓS,
QUEM SERÁ CONTRA NÓS?
');
