INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('115b7eac-ffed-436c-9d95-704de442cdee', 'Meu louvor é só pra Ti', '640', 'Jorgemar Souza Madeira', 'Novo', 'F', 'Louvor', 'MEU LOUVOR É SÓ PRA TI, SENHOR,
MEU SALVADOR, GRANDE AUTOR DA MINHA FÉ;
TODA A MINHA ADORAÇÃO, SENHOR,
PERTENCE A TI, MEU ETERNO REDENTOR.

PORQUE MUDASTE O MEU VIVER
E ME GUIASTE NA TUA LUZ,
PORQUE COMPRASTE A MINHA VIDA,
MEU SENHOR,
SOU GRATO, SENHOR.

MEU LOUVOR É SÓ PRA TI, SENHOR,
MEU SALVADOR, GRANDE AUTOR DA MINHA FÉ;
TODA A MINHA ADORAÇÃO, SENHOR,
PERTENCE A TI, MEU ETERNO REDENTOR.

PORQUE MUDASTE O MEU VIVER
E ME GUIASTE NA TUA LUZ,
PORQUE COMPRASTE A MINHA VIDA,
MEU SENHOR,
SOU GRATO, JESUS, (SOU GRATO, JESUS)
SOU GRATO, JESUS, (SOU GRATO, JESUS)
SOU GRATO, JESUS.
');
