INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('11a78b61-5b11-4998-8c85-a8613a954aba', 'Transborda-me, Senhor', 29, 'Miriam Samú Amiel', 'Básico', 'G', 'Clamor', 'CANTAR 2X
TRANSBORDA-ME, SENHOR, 
DÁ-ME COMUNHÃO;
SENTIR TUA PRESENÇA EU QUERO, Ó PAI;
FALA AO MEU CORAÇÃO, NO SANGUE HÁ VIDA,
HÁ LIBERTAÇÃO, SEGURANÇA E PAZ,
TOCA-ME, SENHOR.

FINAL
HÁ LIBERTAÇÃO,
SEGURANÇA E PAZ,
TOCA-ME, SENHOR.
');
