INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('11d0fd9a-9975-45f6-9fa6-5ad5f9aa0c15', 'Em Tuas mãos, Senhor', 90, 'Autor Desconhecido', 'Básico', 'D', 'Consolo e Encorajamento', 'EM TUAS MÃOS, SENHOR,
EU ME COLOCO AGORA;
FALA COMIGO NESTA HORA
EM QUE MEU CORAÇÃO SUPLICA O TEU AMOR.

EU PEÇO SALVAÇÃO, PEÇO TEU PERDÃO, AGORA.
VEM ME DIZER QUE A DOR FINDOU
E QUE A FELICIDADE NÃO DEMORA.
/FINAL 2X
FALA COMIGO, AGORA,
FALA COMIGO, AGORA.
');
