INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('11dedd6c-700a-4e10-baf7-b20140f9c525', 'Se, Da Vida, As Vagas Procelosas São', '312', 'Let.: Johnson Oatman Jr.; Trad. Elisa Rivers Smart; Mús.Edwin Othello Excell', 'Country', 'D', 'Consolo e Encorajamento', 'SE, DA VIDA, AS VAGAS PROCELOSAS SÃO,
SE, COM DESALENTO, JULGAS TUDO VÃO,
CONTA AS MUITAS BÊNÇÃOS, DIZE-AS DE UMA VEZ,
VERÁS, COM SURPRESA, QUANTO DEUS JÁ FEZ.

CORO
CONTA AS BÊNÇÃOS, CONTA QUANTAS SÃO
RECEBIDAS DA DIVINA MÃO;
VEM DIZÊ-LAS, TODAS DE UMA VEZ,
E VERÁS SURPRESO QUANTO DEUS JÁ FEZ.

TENS ACASO MÁGOA? TRISTE É O TEU LIDAR?
É A CRUZ PESADA QUE TENS DE LEVAR?
CONTA AS MUITAS BÊNÇÃOS, NÃO DUVIDARÁS,
E EM CANTO ALEGRE OS DIAS PASSARÁS.

QUANDO VIRES OUTROS COM SEU OURO E BENS,
LEMBRA QUE TESOUROS PROMETIDOS TENS;
NUNCA OS BENS DA TERRA PODERÃO COMPRAR
A MANSÃO CELESTE QUE VAIS HABITAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('11dedd6c-700a-4e10-baf7-b20140f9c525', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
