INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('11e81c74-20fe-47c8-8ced-4b11b28e5d8f', 'Jesus prometeu nos buscar', '207', 'P.H.R.', 'Básico', 'E', 'Crianças e Adolescentes', 'JESUS PROMETEU NOS BUSCAR
ARREBATAR SUA IGREJA FIEL
COM ELE IREMOS MORAR
HABITAR LÁ NO CÉU
NAS RUAS DE OURO IREMOS ANDAR.

CORO
OH! QUANTO ANSEIO ESTAR ALI
VER FACE A FACE O MEU REI
ENFIM, VOU ADORAR JESUS.

NÃO HÁ ALI TRISTEZAS OU DOR
NEM MORTE, NEM PRANTO OU CLAMOR
SÓ HAVERÁ SEU AMOR
POIS CONOSCO ESTARÁ
COM O CORDEIRO IREMOS AO LAR.

ESSE DIA ESTÁ PRA CHEGAR
A TROMBETA ESTÁ PRA SOAR
QUEM VENCER TUDO HERDARÁ
COM JESUS REINARÁ
AO CORDEIRO IREMOS LOUVAR.

FINAL
ENFIM, VOU CONTEMPLAR JESUS.
ENFIM, VOU ABRAÇAR JESUS.
');
