INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('123ab1f5-5a0d-4aa8-bf80-2c0e20e916ac', 'A vitória da igreja', '', '', 'Básico', '', '', 'NA BATALHA EU ORO AO SENHOR,  
NA BATALHA EU SUPLICO O SEU FAVOR  
E DE JOELHOS EU SOU MAIS QUE VENCEDOR,  
GLORIFICO A DEUS, QUE ATENDE AO MEU CLAMOR.  

BATALHA, ORAÇÃO, VITÓRIA, GLÓRIA A JESUS, (3X)  
GLORIFICO A DEUS, QUE ATENDE AO MEU CLAMOR.  

NA BATALHA EU ORO AO SENHOR,  
NA BATALHA SUPLICO O SEU FAVOR  
E DE JOELHOS EU SOU MAIS QUE VENCEDOR,  
GLORIFICO A DEUS, QUE ATENDE AO MEU CLAMOR.  

FINAL  
BATALHA, ORAÇÃO, VITÓRIA, GLÓRIA A JESUS, (3X)  
GLORIFICO A DEUS, QUE ATENDE AO MEU CLAMOR.  
');
