INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('13417726-bd43-4589-a8ef-c7bf8a970395', 'Senhor Se Estivesses Aqui', '704', 'L.C.M.S', 'Básico', 'F', 'Grupo de Louvor', 'SENHOR, SE ESTIVESSES AQUI
O MEU IRMÃO NÃO TERIA MORRIDO.
FOI O QUE DISSE AQUELA MULHER,
LANÇANDO-SE AOS PÉS DE JESUS,
QUE AO OUVIR O CHORO 
QUE HAVIA NAQUELE LUGAR,
MOVEU-SE EM ESPÍRITO, 
JESUS CHOROU.

*CORO
TIRAI A PEDRA, DISSE JESUS,
E NÃO PODIAM COMPREENDER O QUE IRIA FAZER, 
ENTÃO A LÁZARO ELE CHAMOU E O RESSUSCITOU.
TODOS VIRAM A GLÓRIA DE DEUS.
/CANTAR 2X
ELE TROUXE A ESPERANÇA, 
ELE TROUXE A VIDA, 
POIS ELE É O AUTOR DA VIDA. 
/INSTRUMENTOS

SE ESTÁS COMO AQUELA MULHER,
SE PARA O TEU PROBLEMA NÃO TEM SOLUÇÃO,
CHORA AOS PÉS DE JESUS,
E ELE ENXUGARÁ AS TUAS LÁGRIMAS.
VERÁS A GLÓRIA DE DEUS.

*CORO 2X
TIRAI A PEDRA, DISSE JESUS,
E NÃO PODIAM COMPREENDER O QUE IRIA FAZER, 
ENTÃO A LÁZARO ELE CHAMOU E O RESSUSCITOU. 
TODOS VIRAM A GLÓRIA DE DEUS.
/CANTAR 2X
ELE TROUXE A ESPERANÇA, 
ELE TROUXE A VIDA, 
POIS ELE É O AUTOR DA VIDA.
');
