INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('13e1a8af-b2ad-4932-baa5-730f865122b0', 'Sempre vou lembrar', '', '', '', '', '', 'SEMPRE VOU LEMBRAR DA CORAGEM,
DO AMOR DA FIRMEZA E VONTADE,
DA FÉ E DEVOÇÃO, DA IGREJA DO TEMPO
DE PAULO, DE PEDRO E JOÃO,
ENFRENTAVAM A FÚRIA DE ROMA, MAS
NUNCA DEIXARAM SUA FÉ DE CRISTÃOS,
É UM EXEMPLO PRA MIM,
VERDADEIRA LIÇÃO.

SEMPRE VOU LEMBRAR DA BRAVURA DOS
SANTOS EM PLENA ARENA ENFRENTANDO
OS LEÕES, QUANTO MAIS A FOGUEIRA
QUEIMAVA MAIS SE OUVIA O LOUVOR
DOS NOSSOS IRMÃOS,
SOBRE O SANGUE TOMBAVAM NAS RUAS
CHEGAVAM NOS CÉUS COM A VITÓRIA NAS
MÃOS, É UM EXEMPLO PRA MIM,
VERDADEIRA LIÇÃO.

*CORO
Ó MEU DEUS, REAVIVA TUA IGREJA
DE NOVO, FAZ A CHAMA ARDER NESTE
POVO, COMO FORAM OS PRIMEIROS
CRISTÃOS; Ó MEU DEUS,
REAVIVA TUA IGREJA DE NOVO,
FAZ A CHAMA ARDER NESTE POVO,
COMEÇANDO EM MEU CORAÇÃO!
/INSTRUMENTOS

SEMPRE VOU LEMBRAR DA BRAVURA DOS
SANTOS EM PLENA ARENA ENFRENTANDO
OS LEÕES, QUANTO MAIS A FOGUEIRA
QUEIMAVA MAIS SE OUVIA O LOUVOR
DOS NOSSOS IRMÃOS,
SOBRE O SANGUE TOMBAVAM NAS RUAS
CHEGAVAM NOS CÉUS COM A VITÓRIA NAS
MÃOS, É UM EXEMPLO PRA MIM,
VERDADEIRA LIÇÃO.

*CORO
Ó MEU DEUS, REAVIVA TUA IGREJA
DE NOVO, FAZ A CHAMA ARDER NESTE
POVO, COMO FORAM OS PRIMEIROS
CRISTÃOS; Ó MEU DEUS,
REAVIVA TUA IGREJA DE NOVO,
FAZ A CHAMA ARDER NESTE POVO,
COMEÇANDO EM MEU CORAÇÃO!

FINAL
Ó MEU DEUS,
REAVIVA TUA IGREJA DE NOVO,
FAZ A CHAMA ARDER NESTE POVO,
COMEÇANDO EM MEU CORAÇÃO!
');
