INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('13fd9214-8ce3-4c5e-9320-b8be42da1db8', 'Onipotente Deus', '662', 'Gérson Beluci Miguel', 'Básico', 'C', 'Salmos de Louvor', 'ONIPOTENTE DEUS,
TUAS OBRAS TE EXALTAM, SENHOR;
ONIPOTENTE DEUS,
CÉUS E TERRA TE RENDEM LOUVOR.

QUE É O HOMEM QUE DELE TE LEMBRES
E O FILHO DO HOMEM PARA O VISITAR?
PORÉM, HONRA DESTE PRA GOVERNAR.
/INSTRUMENTOS

SENHOR JESUS CRISTO,
MINHA VIDA VIESTE SALVAR;
SENHOR JESUS CRISTO,
COM TEU SANGUE ME PURIFICAR.

COMO SERVO VIESTE,
NA CRUZ TE HUMILHASTE
MAS VIVO NA GLÓRIA HOJE ESTÁS,
ÉS MEU REI, SENHOR, E, SEI, VOLTARÁS.
/INSTRUMENTOS

ESPÍRITO SANTO,
Ó VEM E HABITA EM MEU SER,
ESPÍRITO SANTO,
VIVIFICA-ME COM TEU PODER;

TAL COMO ÁGUA QUE JORRA
E O VENTO QUE SOPRA
E O FOGO ARDEN TE, EN-FIM,
SANTO ESPÍRITO DE DEUS, VIVE EM MIM, (2X)
');
