INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('14239f10-7968-4706-8a91-6e215492fd65', 'Se Cansado Tu Estás', '240', 'Gérson Beluci Miguel, Carmem Darlene Rempel Michna', 'Fox Abafado', 'E', 'Morte, Ressureição e Salvação', 'SE CANSADO TU ESTÁS,
SOBRECARREGADO, SIM,
DEIXA TUDO AGORA, DIGO:
VEM A MIM!
EU TE ALIVIAREI,
PÕE TEU FARDO SOBRE MIM,
DEIXA TUDO AGORA, DIGO:
VEM A MIM!

FINAL 2X
VEM A MIM, Ó PECADOR;
QUERO SER TEU SALVADOR,
POIS SOU MANSO E HUMILDE DE CORAÇÃO.
VEM A MIM, DESCANSARÁS,
TUA ALMA REPOUSARÁ,
QUE SUAVE É MEU JUGO E LEVE O MEU FARDO.
');
