INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1425097c-c10b-4aed-b0aa-2add0dead4be', 'Clamo a ti, meu Senhor e Pai (Uma nova Canção)', '011', 'M.D.', 'Básico', 'A', 'Crianças e Adolescentes', 'CLAMO A TI, MEU SENHOR E PAI
E PROSTRADO AOS TEUS PÉS PEÇO PERDÃO.
CLAMO PELO SANGUE DE JESUS SOBRE MIM
E COM LOUVORES E CÂNTICOS TE ADORAREI.
A TUA GRAÇA SEJA SOBRE MIM, MEU SENHOR,
A TUA LUZ RESPLANDEÇA EM MIM.
/COLOCA NOS MEUS LÁBIOS UMA NOVA CANÇÃO,
UM HINO DE LOUVOR A DEUS PAI, A DEUS PAI.

CANTAR 2X
E PROSTRADO AOS TEUS PÉS
EM PLENA COMUNHÃO,
MEU SENHOR,
RENOVA TEU ESPÍRITO SOBRE MIM.
/FINAL
SOBRE NÓS.
');
