INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1465ac29-e67c-498d-8238-40a22fc8ccd3', 'Meu barquinho', '121', 'C.A.', 'Fox', 'D', 'Crianças e Adolescentes', 'MEU BARQUINHO NAVEGA NO MAR,
MUI FELIZ VIVO SEMPRE A CANTAR,
GRANDES ONDAS VÊM PARA O NAUFRAGAR,
NÃO TENHO MEDO, VOU A ÂNCORA LANÇAR.

CORO
VOU A JESUS, VOU A ÂNCORA LANÇAR.
VOU A JESUS, POR SEU SANGUE VOU CLAMAR
E FELIZ VOU AO PORTO CHEGAR.
ALELUIA! ALELUIA É O MEU CANTAR!

MEU JESUS É AMIGO FIEL,
POR SUA MÃO ME CONDUZ ''TÉ AO CÉU
E SE UM DIA VIER A AFLIÇÃO,
NÃO TENHO MEDO, POIS É ELE O CAPITÃO.
');
