INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('14d83ce8-daab-4602-ae78-d450c7a6bdb4', 'Jesus, a minhalma tem sede de Ti', 91, 'E.H.M.R', 'Básico', 'Cm', 'Consolo e Encorajamento', 'JESUS, A MINH''ALMA TEM SEDE DE TI,
OUVE-ME QUANDO A TI CLAMO,
LIVRA-ME DOS MEUS ADVERSÁRIOS,
POIS ELES ESTÃO QUERENDO ROUBAR
A MINHA SALVAÇÃO.

COBRE-ME COM O TEU SANGUE,
DÁ-ME ESTA PROTEÇÃO,
JESUS, EU QUERO ESTAR EM PERFEITA COMUNHÃO,
JESUS, EU QUERO ESTAR EM CONSTANTE COMUNHÃO.
