INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('150caf2d-8c10-4611-bc35-a32e9d51bc41', 'Ouvi como que a voz (561)', '', '', 'Basico', '', '', 'OUVI COMO QUE A VOZ DE UMA GRANDE MULTIDÃO,
COMO VOZ DE MUITAS ÁGUAS, COMO VOZ DE GRANDES TROVÕES;
