INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1575ed68-fce2-42f2-9681-965edce44005', 'Nunca mais, nunca mais', '759', 'Autor Desconhecido', 'Country', 'D', 'Corinhos', 'NUNCA MAIS, NUNCA MAIS
