INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('15ce6445-83a7-4bc3-91f8-dc5a645a0819', 'Senhor suplico a ti em oração', '042', 'Jorgemar Souza Madeira', 'Marcha', 'Em', 'Clamor', 'SENHOR, SUPLICO A TI EM ORAÇÃO:
FAZE DE MIM UM VASO NOVO,
DERRAMA O SANGUE DE JESUS EM MIM.

*CORO
PERMITE-ME QUE ENTRE 
NO SANTO DOS SANTOS,
PERDOA-ME DO VIL PECADO,
ESTENDE A TUA MÃO.

PRECISO CONTEMPLAR A TUA GLÓRIA,
CONCEDE-ME TUA VITÓRIA,
DERRAMA O SANGUE DE JESUS EM MIM.

*CORO
PERMITE-ME QUE ENTRE 
NO SANTO DOS SANTOS,
PERDOA-ME DO VIL PECADO,
ESTENDE A TUA MÃO.
/FINAL
SENHOR, SENHOR.
SENHOR, SENHOR, SENHOR.
');
