INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('15e5425e-8d04-40c0-82e0-36e96f082ebd', 'Você sabe o que é salvação', 69, 'E.H.M.R.', 'Balada', 'G', 'Crianças e Adolescentes', 'VOCÊ SABE O QUE É SALVAÇÃO?
É SENTIR UMA GRANDE ALEGRIA
QUE O MUNDO NÃO CONHECE,
NELE HÁ TREVAS E SOLIDÃO.

JESUS NOS DEU SALVAÇÃO
QUANDO LÁ NA CRUZ MORREU,
LEVOU OS NOSSOS PECADOS,
LIBERTOS AGORA ESTAMOS.

CANTAR 2X
DÊ A ELE O SEU LOUVOR,
UMA VIDA DE GRATIDÃO;
VEM AGORA E ENTREGUE
A JESUS SEU CORAÇÃO.
/FINAL
VEM AGORA E ENTREGUE
A JESUS SEU CORAÇÃO.
');
