INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('15eed418-8072-472f-8af0-0b52be134831', 'Adorarei', '574', 'Let. e Mús. André Kempen; Trad. Sérgio Paulo Ferreira de Matos', 'Básico', 'D', 'Louvor', 'CANTAR 2X
ADORAREI O GRANDE EU SOU,
DEUS SEM PRINCÍPIO, DEUS SEM FIM,
EXALTAREI O REI QUE VIVE EM MIM.

FINAL 2X
A DEUS DE PRATA E OURO
JAMAIS EU ME ENCURVAREI,
SÓ TU ÉS MEU TESOURO,
A TI SOMENTE SERVIREI,
ACEITA O MEU SACRIFÍCIO DE LOUVOR.
');
