INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('15f5d608-918c-40f5-aeb6-30f2c9f64a2a', 'Onde nasceu Jesus', '065', 'R.T.F.', 'Fox', 'D', 'Crianças e Adolescentes', 'ONDE NASCEU JESUS?
EU LOGO TE RESPONDO:
EM BELÉM, O MEU JESUS NASCEU.

QUEM É SEU PAI?
EU LOGO TE RESPONDO:
DE DEUS É FILHO E ELE TAMBÉM É DEUS.

EM QUE CIDADE CRESCEU?
EU LOGO TE RESPONDO:
EM NAZARÉ O MEU JESUS CRESCEU.

QUEM O BATIZOU?
EU LOGO TE RESPONDO:
FOI JOÃO BATISTA, NO RIO JORDÃO.

E DIGO MAIS, ELE ESTÁ VIVO,
FALA CONOSCO,
NOS TRAZENDO A PAZ.
');
