INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1631eba0-a3a7-409e-b554-59d83ec020b2', 'Jesus cura e salva', 92, 'K.V.L.', 'Básico', 'D', 'Crianças e Adolescentes', 'JESUS CURA E SALVA,
JESUS É O MEU SALVADOR;
JESUS É O MEU AMIGO,
E ELE É O MEU REDENTOR.

CANTAR 2X
QUANDO ESTOU DOENTE, CURA ELE DÁ.
QUANDO ESTOU TRISTE, A PAZ VEM REINAR.

FINAL 2X
JESUS É FORÇA E ESPERANÇA!
JESUS É O PRÍNCIPE DA PAZ!
');
