INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('164645b1-6fdc-4d6d-bbd9-a3047fe21c6b', 'Irei cantar e adorar o Rei Jesus', '226', 'C.M.V.C.S.', 'Fox', 'E', 'Crianças e Adolescentes', 'IREI CANTAR E ADORAR
AO REI JESUS
QUE POR AMOR MORREU
NA CRUZ PRA ME SALVAR;
ALEGRE SOU POIS SALVO ESTOU
E ETERNAMENTE COM O SENHOR
NAS MANSÕES CELESTIAIS IREI MORAR.

FINAL 2X
OH! ALELUIA,
HONRA E GLÓRIA AO REI JESUS!
LÁ NO CÉU ETERNAMENTE IREI CANTAR!
ADORAREI AO MEU SENHOR,
PROSTRADO AOS PÉS DO SALVADOR
QUE ENTRONIZADO ESTÁ
POIS ELE É O REI DOS REIS.
');
