INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('16613d7f-558c-44f4-9cde-fe2ef902bb03', 'Celebrai com júbilo ao Senhor', '659', 'Sl.100; Adapt. Let. e Mús. Nelson Marialva Bomílcar, Guilherme Kerr Neto', 'Country', 'C#m', 'Salmos de Louvor', 'CELEBRAI COM JÚBILO AO SENHOR
TODAS AS TERRAS,
SERVI AO SENHOR COM ALEGRIA;
APRESENTAI-VOS DIANTE 
DELE COM CÂNTICOS,
SABEI QUE O SENHOR É DEUS.

CANTAR 2X
FOI ELE QUEM NOS FEZ E DELE SOMOS,
SOMOS O SEU POVO
E REBANHO DO SEU PASTO.

ENTRAI EM SUAS PORTAS
COM AÇÕES DE GRAÇAS
E NOS SEUS ÁTRIOS COM HINOS DE LOUVOR;
RENDEI-LHE GRAÇAS E BENDIZEI-LHE O NOME
PORQUE O SENHOR É BOM.

FINAL 2X
SUA MISERICÓRDIA DURA PARA SEMPRE,
DE GERAÇÃO EM GERAÇÃO,
SUA FIDELIDADE.
');
