INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('166bfc24-93ab-4ce3-b1d4-3b6465c078e0', 'Quatro coisas tão pequeninas', '172', 'E.H.M.R.', 'Fox', 'C', 'Crianças e Adolescentes', 'QUATRO COISAS TÃO PEQUENINAS
UMA GRANDE LIÇÃO NOS DÃO:
EMBORA TÃO FRÁGEIS,
MUITO SÁBIAS SÃO.

AS FORMIGAS SÃO TRABALHADORAS,
CADA UMA EXERCE A SUA FUNÇÃO;
É COMO A IGREJA DE CRISTO,
TRABALHANDO PRA MANTER A SALVAÇÃO.

EM SEGURANÇA O COELHO CONSTRÓI
SUA CASA SOBRE A ROCHA;
E, PARA ESTARMOS BEM SEGUROS,
CONSTRUÍMOS NA ROCHA,
QUE É JESUS.

OS GAFANHOTOS, TODOS SAEM,
E EM GRUPOS SE REPARTEM,
SAÍMOS PROCLAMANDO A PALAVRA,
SEMPRE UNIDOS EM UM SÓ CORAÇÃO.

E, NO FINAL DA CAMINHADA,
HERDEIROS DAS PROMESSAS DE DEUS,
TAL QUAL A ARANHA MORA NO PALÁCIO,
MORAREMOS NAS MANSÕES COM JESUS!
');
