INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('170cb30f-c5ec-4554-920a-04b34820335a', 'Lâmpada para os meus pés', '136', 'M.L.M.B.O.; F.B.O.G.', 'Básico', 'G', 'Crianças e Adolescentes', 'LÂMPADA PARA MEUS PÉS,
O CAMINHO ILUMINA,
REVELADA POR DEUS,
GUIARÁ O MEU CORAÇÃO.

CORO
A BÍBLIA É UM TESOURO DESCOBERTO
PARA AQUELES QUE DE JESUS ESTÃO PERTO;
A MINHA BÍBLIA VOU SEMPRE LER
PARA MAIS DE JESUS CONHECER.

QUERO AMAR TUA PALAVRA,
GUARDÁ-LA SEMPRE EM MEU CORAÇÃO,
ENSINAR AS PESSOAS
QUE SÓ JESUS É A SALVAÇÃO.
');
