INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('170cc373-3452-4919-ade3-4127b124faf1', 'Tenho um Senhor muito forte', '034', 'E.H.M.R.', 'Valseado', 'B', 'Crianças e Adolescentes', 'TENHO UM SENHOR MUITO FORTE, VENCEU A MORTE
PARA ME DAR UM LUGAR LÁ NO CÉU.
ESTE SENHOR É JESUS QUE ME CONDUZ
PARA UM LAR DE GOZO E DE PAZ.

QUERO SERVI-LO, QUERO LOUVÁ-LO,
JUSTO SENHOR, DEUS FORTE, MARAVILHOSO,
CONSELHEIRO, PAI DA ETERNIDADE,
PRÍNCIPE DA PAZ, JESUS.
');
