INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1716acc2-420a-4052-86d2-e1a0d1e4cc0c', 'Levantai - vos, ó Portais Eternos Sl 24', '652', 'Everaldo Cavalcante Lima', 'Básico', 'A', 'Salmos de Louvor', 'LEVANTAI-VOS, Ó PORTAIS ETERNOS,
PRA QUE ENTRE O REI DA GLÓRIA;
QUEM É ESSE REI DA GLÓRIA?
O SENHOR DOS EXÉRCITOS,
ELE É O REI DA GLÓRIA,
ELE É O REI DA GLÓRIA.

LEVANTAI-VOS, Ó PORTAIS ETERNOS,
E ENTRARÁ O REI DA GLÓRIA;
O DEUS FORTE E PODEROSO,
PODEROSO NA BATALHA;
ELE É O REI DA GLÓRIA,
ELE É O REI DA GLÓRIA.
/INSTRUMENTOS

LEVANTAI-VOS, Ó PORTAIS ETERNOS,
E ENTRARÁ O REI DA GLÓRIA;
QUEM É ESSE REI DA GLÓRIA?
É JESUS, O REI DA GLÓRIA.
');
