INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('18099d84-39e9-4359-9c8a-ec47d8d10b8a', 'Jesus ressuscitou! (Meu amigo Jesus)', '045', 'I.E.R.A; A.S.M', 'Balada', 'G', 'Crianças e Adolescentes', '*CORO 2X
JESUS RESSUSCITOU!
CANTAREI EM MEU CORAÇÃO
TODA GLÓRIA, HONRA E LOUVOR,
A JESUS, POR SUA PAZ E PERDÃO.

NO MEU CORAÇÃO NÃO HÁ TRISTEZAS,
POIS JESUS, COM SEU SANGUE, O LAVOU.
HOJE EU CANTO COM MUITA ALEGRIA,
ADORANDO AO MEU REI E SENHOR.

HOJE POSSO TESTEMUNHAR
DE UM AMIGO QUE SÓ ME QUER BEM.
DEU, NA CRUZ, SUA VIDA POR MIM,
PRA QUE EU VÁ NO CÉU MORAR TAMBÉM.

*CORO
JESUS RESSUSCITOU!
CANTAREI EM MEU CORAÇÃO
TODA GLÓRIA, HONRA E LOUVOR,
A JESUS, POR SUA PAZ E PERDÃO.

