INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('185983c5-27c2-4932-8681-366bb5d470f3', 'Com meu coração', '', '', '', '', '', 'COM MEU CORAÇÃO VENHO AGORA,
EM TUA PRESENÇA PARA CLAMAR.
POR TEU SACRIFÍCIO BENDITO,
ENCHE DE BÊNÇÃOS ESTE LUGAR.

POR TEU SANGUE VOU CLAMAR,
Ó SENHOR VEM A VIDA ME DAR.
ESTE SANGUE REMIDOR,
VEM TOCAR-ME COM TEU AMOR,
E AGORA, EM TUA CASA,
A ALEGRIA INVADIRÁ.

POIS O SOM DA TUA VOZ,
ENTRE NÓS SE ESPALHARÁ,
DANDO VIDA,
DANDO PAZ ONDE ECOAR.

POR TEU SANGUE VOU CLAMAR,
Ó SENHOR VEM A VIDA ME DAR.
ESTE SANGUE REMIDOR,
VEM TOCAR-ME COM TEU AMOR,
E AGORA, EM TUA CASA,
A ALEGRIA INVADIRÁ.

POIS O SOM DA TUA VOZ,
ENTRE NÓS SE ESPALHARÁ,
/FINAL 3X
DANDO VIDA, DANDO
PAZ ONDE ECOAR.
');
