INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('196aba6f-6595-4137-bdee-9c9fd93e5786', 'Novo Caminho', '272', 'Jorgemar Souza Madeira', 'Toada', 'G', 'Morte, Ressureição e Salvação', 'NOVO CAMINHO É O MEU JESUS,
OUTRO CAMINHO NÃO PODES ENCONTRAR.
PODES ENCONTRAR A PAZ, VIDA, EM JESUS.
SEGUE ESTE CAMINHO E TERÁS A LUZ.

*CORO
PAZ, PAZ, VIDA, AMOR E LUZ,
SE NÃO HÁ PAZ, PEDE A JESUS.

DEIXA CRISTO SE REVELAR EM TEU CORAÇÃO,
ELE TE DARÁ A PAZ,
VIDA E SALVAÇÃO.

*CORO 2X
PAZ, PAZ, VIDA, AMOR E LUZ,
SE NÃO HÁ PAZ, PEDE A JESUS.
');
