INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1a202311-6d4e-481a-9b60-e2f478cf7e3c', 'Em Obediência, Servi ao Senhor', '', 'Rebeca Bravim - (I Samuel 17.47)', 'Balada', 'D', 'Avulsos', 'EM OBEDIÊNCIA, SERVI AO SENHOR
E EM HUMILDADE, BUSCAI AO SENHOR;
DAS RIQUEZAS DO REINO DE DEUS, ENCHEI O CORAÇÃO.
E CHEIOS DO ESPÍRITO, NA BATALHA TEREIS VITÓRIA.

CORO
O SENHOR SALVA,
O SENHOR LIVRA,
NÃO COM ESPADA,
POIS DELE É A GUERRA;
TOMA O CAJADO,
DESCE AO RIBEIRO,
DIANTE DA PELEJA
O SENHOR É CONTIGO.

PRUDENTEMENTE, ANDAI NO CAMINHO
E TENDE ZELO COM A OBRA DO ESPÍRITO.
CRIA EM MIM UM CORAÇÃO PURO
E RENOVA-ME COM UM ESPÍRITO RETO.

CORO 2X
O SENHOR SALVA,
O SENHOR LIVRA,
NÃO COM ESPADA,
POIS DELE É A GUERRA;
TOMA O CAJADO,
DESCE AO RIBEIRO,
DIANTE DA PELEJA
O SENHOR É CONTIGO.

FINAL
DIANTE DA PELEJA
O SENHOR É CONTIGO.
');
