INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1acd4610-fa42-4858-8488-5e900e7c10d7', 'Eis a Escrava Resgatada', '679', 'Let. e Mús. Robert Lowry; Trad. José Joaquim Pereira Rodrigues', 'Fox Abafado', 'D', 'Grupo de Louvor', 'EIS A ESCRAVA RESGATADA!
GRANDE PREÇO CRISTO DEU;
NÃO FOI OURO, NEM FOI PRATA;
PRÓPRIO SANGUE ELE VERTEU.

CORO
TANTO FOI O TEU AMOR
QUE POR MIM ASSIM MOSTRASTE;
PRA REMIR MEU CATIVEIRO
TUA VIDA NÃO POUPASTE!

JÁ AGORA QUE SOU TUA,
SEM JAMAIS A TI PERDER,
QUERO, MEU SENHOR, SERVIR-TE
GRATA, E SÓ PARA TI VIVER.

QUERO RECEBER TEU JUGO,
E EM TEUS PASSOS CAMINHAR;
SE POR TI EU SOFRO TUDO,
VOU CONTIGO EM PAZ REINAR.

ESTÁS NO CÉU! VIVO EU NA TERRA,
ESPERANDO O TEU VOLTAR;
LEVARÁS ENTÃO A ESCRAVA
PRA CONTIGO ALI FICAR.

TODO O AMOR POR MIM SENTIAS,
PADECENDO A DOR DA CRUZ,
VESTE-ME DA TUA GLÓRIA!
VEM, Ó VEM, SENHOR JESUS.
');
