INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1b03120e-00f4-4a92-8b77-357697b4aacb', 'O povo que andava em trevas viu uma grande luz', '111', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'G', 'Dedicação', 'O POVO QUE ANDAVA EM TREVAS VIU
UMA GRANDE LUZ, 
E SOBRE OS QUE ANDAVAM NA SOMBRA DA MORTE
RESPLANDECEU A LUZ;
PORQUE UM MENINO NOS NASCEU,
UM FILHO SE NOS DEU;
O PRINCIPADO ESTÁ SOBRE OS SEUS OMBROS,
ELE É JESUS, JESUS, A LUZ DO MUNDO.
/INSTRUMENTOS

MARAVILHOSO, CONSELHEIRO,
SEU NOME SERÁ,
DEUS FORTE, PAI DA ETERNIDADE,
PRÍNCIPE DA PAZ;
DO PRINCIPADO E DA PAZ NÃO HAVERÁ FIM
E SOBRE O TRONO DE DAVI REINARÁ JESUS,
JESUS, A LUZ DO MUNDO.
');
