INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1b94116b-382b-468f-83b0-0118ab37c7cb', 'Jesus nome precioso', '119', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Dedicação', 'JESUS, NOME PRECIOSO,
JESUS, REI E SENHOR,
JESUS, POR ESTE NOME
SOU MAIS QUE VENCEDOR!

JESUS, LÍRIO DOS VALES,
JESUS, FLOR DO JARDIM,
JESUS, COM TEU AMOR VEM
HOJE TOCAR EM MIM!

UMA PALAVRA SÓ BASTA, SENHOR, 
E TODO O MAL SE VAI E TODA A DOR;
UMA PALAVRA SÓ DO TEU PODER
E EM NOME DE JESUS EU VOU VENCER!

JESUS, NOME DE VIDA,
JESUS, FILHO DE DEUS,
A TI TUDO SE INCLINA
NA TERRA E NOS CÉUS! (2X)
');
