INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1bc5ac5c-058b-4cf7-b0b6-f597299e0716', 'Eu clamo, eu oro', '', '', '', '', '', 'EU CLAMO, EU ORO PELO SANGUE LÁ DA CRUZ,
EU CLAMO, EU ORO PELO ESPÍRITO QUE RELUZ.

QUANDO EU OLHO PARA A CRUZ,
SEI QUE A VITÓRIA CHEGARÁ,
POIS POR MIM MORREU JESUS
QUE NÃO ME ABANDONA NEM ME ABANDONARÁ.

EU CLAMO, EU ORO PELO SANGUE LÁ DA CRUZ,
EU CLAMO, EU ORO PELO ESPÍRITO QUE RELUZ.
FINAL
EU CLAMO, EU ORO PELO SANGUE LÁ DA CRUZ,
EU CLAMO, EU ORO PELO ESPÍRITO QUE RELUZ.
');
