INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1c421f64-e74f-499c-a1c3-dc1f8360d078', 'Deus ama você', 79, 'J.J.G.', 'Fox', 'E', 'Crianças e Adolescentes', 'DEUS AMA VOCÊ E ELE QUER LHE SALVAR,
ELE VAI OPERAR EM SEU CORAÇÃO.
A VIDA QUE UM DIA VOCÊ NÃO CONHECIA,
GOZO, PAZ E ALEGRIA EM JESUS ENCONTROU.

CANTAR 2X
ELE É O CAMINHO,
A VERDADE E A VIDA
E OFERECE A VOCÊ SALVAÇÃO.
BASTA ABRIR A PORTA DO CORAÇÃO,
PRA SENTIR A SUA PAZ E PERDÃO.
/FINAL
PRA SENTIR A SUA PAZ E PERDÃO.
');
