INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1c73d801-5cc6-4d57-ad23-dfa9104ce9dc', 'Nossa Gratidão', '728', '', 'Balada', 'Eb', 'Grupo de Louvor', 'NOSSA GRATIDÃO E NOSSO LOUVOR
IREMOS DEIXAR NO TEU ALTAR.
QUE DAREMOS A TI, SENHOR,
PELOS TEUS FEITOS
E POR TUA OBRA AQUI NESTE LUGAR?

GLÓRIA, SEMPRE GLÓRIA,
COM TEUS ANJOS PARA SEMPRE ADORAR.
GLÓRIA, SEMPRE GLÓRIA,
A TEUS PÉS, SENHOR, IREMOS EXALTAR.

O SENHOR É JUSTO, É FIEL,
SUA MISERICÓRDIA NÃO TEM FIM.
TODAS AS TUAS OBRAS, SENHOR,
TE LOUVARÃO
E OS TEUS SANTOS TE BENDIRÃO.

CANTAR 2X
GLÓRIA (OS CÉUS MANIFESTAM),
SEMPRE GLÓRIA (SUA GLÓRIA E PODER).
OS ANJOS TE LOUVAM SEM CESSAR (GLÓRIA).
GLÓRIA (EM NOSSOS LÁBIOS),
SEMPRE GLÓRIA (HÁ SEMPRE UM LOUVOR),
DE EXALTAÇÃO POR TUA GLÓRIA, SENHOR.

FINAL
GLÓRIA (GLÓRIA) 
PARA SEMPRE AO SENHOR,
GLÓRIA (GLÓRIA), 
O TEU NOME EXALTAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('1c73d801-5cc6-4d57-ad23-dfa9104ce9dc', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
