INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1c90fb56-15c1-47e5-8827-86c93ae89169', 'Rocha minha', '342', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'Bm', 'Consolo e Encorajamento', 'ROCHA MINHA, LIBERTADOR MEU,
EM TI EU CONFIAREI;
O PODER NA TERRA E NO CÉU
SÓ A TI PERTENCE, MEU DEUS E REI.

CORO
ESPERO EM TI, Ó MEU DEUS,
TUDO ESTÁ EM TUAS MÃOS!
ROCHA MINHA, LIBERTADOR MEU,
SÓ TU ÉS, SENHOR, MINHA SALVAÇÃO.

COM LOUVOR EM TUA CASA ENTRAREI
E CANTAREI AO SENHOR,
NA ALEGRIA OU TRISTEZA, EU SEI,
SEMPRE ESTÁS COMIGO, MEU GRANDE AMOR.
');
