INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1c9b51d1-576d-4223-979e-fb6b0d9298ba', 'Nossa gratidão', '', '', '', '', '', 'NOSSA GRATIDÃO E O NOSSO LOUVOR,
IREMOS DEIXAR NO TEU ALTAR.
QUE DAREMOS A TI, SENHOR,
PELOS TEUS FEITOS
E POR TUA OBRA AQUI NESTE LUGAR.

GLÓRIA, SEMPRE GLÓRIA,
COM TEUS ANJOS PARA SEMPRE ADORAR.
GLÓRIA, SEMPRE GLÓRIA
AOS TEUS PÉS, SENHOR, IREMOS EXALTAR.

O SENHOR É JUSTO, É FIEL,
SUA MISERICÓRIDA NÃO TEM FIM,
TODAS AS SUAS OBRAS, SENHOR,
TE LOUVARÃO E OS TEUS SANTOS
TE BENDIRÃO.

GLÓRIA,
(OS CÉUS MANIFESTAM)
SEMPRE GLÓRIA
(TUA GLÓRIA E PODER)
AO ANJOS TE LOUVAM SEM CESSAR
(GLÓRIA, GLÓRIA)
GLÓRIA,
(EM NOSSOS LÁBIOS)
SEMPRE GLÓRIA
(HÁ SEMPRE UM LOUVOR)
DE EXALTAÇÃO POR TUA GLÓRIA
SENHOR

FINAL
GLÓRIA
(GLÓRIA)
PARA SEMPRE AO SENHOR.
GLÓRIA
(GLÓRIA)
O TEU NOME EXALTAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('1c9b51d1-576d-4223-979e-fb6b0d9298ba', '377b4956-8af4-40b5-90ce-868956eab5c2');
