INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1d253cf9-4c1a-47d1-9c19-135e8ac7a86e', 'Louvando a Deus (At 2.47)', '792', '', 'Novo', 'D', 'Corinhos', 'CANTAR 2X
