INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1d99059a-8575-4f48-ab2e-938bfe077546', 'O Senhor é o meu pastor Bondade', '357', 'Jackson de Halley Fernandes Fontes', 'Básico', 'G', 'Consolo e Encorajamento', 'O SENHOR É O MEU PASTOR, NADA ME FALTARÁ,
POR VERDES CAMPOS ME CONDUZIRÁ,
EM PLANAS CAMPINAS,
JUNTO ÀS ÁGUAS TRANQUILAS,
DO SEU AMOR ELE ME DARÁ.

CORO
BONDADE E MISERICÓRDIA
CERTAMENTE ME SEGUIRÃO
E HABITAREI COM MEU SENHOR
PRA TODO O SEMPRE;
AINDA QUE EU ANDASSE
PELO VALE DA SOMBRA DA MORTE,
NÃO TEMERIA MAL ALGUM
PORQUE COMIGO ESTÁS.

ME UNGES COM ÓLEO DA ALEGRIA,
EM TUA PRESENÇA ME ALEGRO, SENHOR;
UMA MESA FARTA TU ME DARÁS,
TUA DESTRA EM VERDADE ME SUSTENTARÁ.

FINAL
O SENHOR É O MEU PASTOR,
NADA ME FALTARÁ,
POR VERDES CAMPOS ME CONDUZIRÁ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('1d99059a-8575-4f48-ab2e-938bfe077546', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
