INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1de8a6ed-676b-49df-a83a-ddfb5f298f7b', 'Bendita a hora de oração', '094', 'W.W.W', 'Balada', 'D', 'Invocação e Comunhão', 'BENDITA A HORA DE ORAÇÃO
QUE ACALMA O AFLITO CORAÇÃO.
QUE LEVA AO TRONO DE JESUS
OS ROGOS PARA AUXÍLIO E LUZ!
EM TEMPOS DE CUIDADO E DOR,
REFÚGIO TENHO EM MEU SENHOR.
VENCENDO O ARDIL E A TENTAÇÃO,
BENDIGO A HORA DE ORAÇÃO.

BENDITA A HORA DE ORAÇÃO,
QUANDO A FERVENTE PETIÇÃO
SOBE AO BENIGNO SALVADOR,
QUE ATENDE A VOZ DO MEU CLAMOR!
JESUS ME ORDENA A RECORRER
AO SEU AMOR, AO SEU PODER.
CONTENTE E SEM PERTURBAÇÃO
EU BUSCO A HORA DE ORAÇÃO.

BENDITA A HORA DE ORAÇÃO,
DE SANTA PAZ E COMUNHÃO!
DESEJO ENQUANTO AQUI ME ACHAR,
COM FÉ CONSTANTE HUMILDE ORAR.

E ENFIM, NO RESPLENDOR DE DEUS,
NA GLÓRIA DOS MAIS ALTOS CÉUS,
LEMBRAR-ME-EI COM GRATIDÃO
DAS HORAS SUAVES DE ORAÇÃO.
/FINAL
AMÉM
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('1de8a6ed-676b-49df-a83a-ddfb5f298f7b', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('87dc553b-0215-4442-8bff-871bf9aa97ae', '1de8a6ed-676b-49df-a83a-ddfb5f298f7b', 'c4ddecbd-ef4d-4e20-bece-4261201bccc8', 'mp3', 'assets/praises/1de8a6ed-676b-49df-a83a-ddfb5f298f7b/87dc553b-0215-4442-8bff-871bf9aa97ae.mp3', 'Coletânea /094 - Bendita a hora de oração/Vozes-cantadas/Bendita hora de Oraçao -Baixo.mp3', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1e0fde3a-ec44-4ddb-addb-afb3b8dba276', 'Eu Não Saberia Caminhar', '326', 'Marciel Denadai', 'Básico', 'C', 'Consolo e Encorajamento', 'EU NÃO SABERIA CAMINHAR SEM TI, SENHOR,
PORQUE TU ÉS O MEU AUXÍLIO E FORTALEZA;
/CANTAR 2X
REFÚGIO NA TRIBULAÇÃO 
QUANDO OS MEUS JOELHOS  
DOBRAM EM ORAÇÃO.

SENHOR, TU ÉS O MEU AUXÍLIO NA TRIBULAÇÃO,
AMIGO BEM PRESENTE QUE NÃO FALHA;
/CANTAR 2X
TENHO DESEJADO A TUA SALVAÇÃO,
Ó SENHOR,
O TEU QUERER É TODO O MEU PRAZER.

FINAL 2X
REFÚGIO NA TRIBULAÇÃO
QUANDO OS MEUS JOELHOS
DOBRAM EM ORAÇÃO.
');
