INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1e2f603c-a5db-4584-a84c-66bd5db5d1ad', 'Sete Castiçais', '485', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Volta de Jesus e Eternidade', 'SETE CASTIÇAIS O ESPÍRITO ACENDEU
E DO MEIO DA IGREJA NOS FALOU;
TODO MUNDO OUVIU A VOZ
DO CORDEIRO QUE VENCEU,
VAI CUMPRIR-SE AGORA O QUE ELE PROMETEU:
CRISTO VAI VOLTAR!

O QUE É DIGNO JÁ OS SELOS DESATOU,
A TROMBETA DA VITÓRIA VAI SOAR;
A VIDEIRA FLORESCEU, A FIGUEIRA JÁ BROTOU,
VAI CUMPRIR-SE O QUE ELE UM DIA NOS FALOU:
CRISTO VAI VOLTAR!

*CORO
MARANATA! CRISTO VAI VOLTAR!
O ESPÍRITO E A ESPOSA DIZEM:
VEM! ORA VEM JESUS!

HÁ SINAIS NO CÉU, NA TERRA E NO MAR,
O JUÍZO DO SENHOR NÃO VAI TARDAR;
ESTÁS PRONTO MEU IRMÃO,
SE DEUS HOJE TE CHAMAR?
SÓ NO SANGUE DO CORDEIRO HÁ SALVAÇÃO,
CRISTO VAI VOLTAR!

*CORO 2X
MARANATA! CRISTO VAI VOLTAR!
O ESPÍRITO E A ESPOSA DIZEM:
VEM! ORA VEM JESUS!
');
