INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1e634899-8ae5-44e5-8ceb-6bb66c8e1417', 'Subindo para o céu eu vou', '775', '', 'Marcha', 'D', 'Corinhos', 'CANTAR 2X
SUBINDO, SUBINDO,
SUBINDO PARA O CÉU EU VOU.
/TRISTEZA NÃO VAI COMIGO
PORQUE JESUS CRISTO ME SALVOU:
JOGUEI A TRISTEZA FORA
E COM JESUS PARA O CÉU EU VOU!

CANTAR 2X
SUBINDO, SUBINDO,
SUBINDO PARA O CÉU EU VOU.
/FINAL
TRISTEZA NÃO VAI COMIGO
PORQUE JESUS CRISTO ME SALVOU:
JOGUEI A TRISTEZA FORA
E COM JESUS PARA O CÉU EU VOU!
');
