INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1edeacbf-1107-425e-ac6b-2d34281db8fd', 'Eis-me, ó Salvador, aqui', '013', '', '', '', '', 'EIS-ME, Ó SALVADOR AQUI,
CORPO E ALMA OFERTO A TI;
SERVO INÚTIL, SEM VALOR
MAS PERTENÇO AO MEU SENHOR.

FRACO EM OBRAS E NO PENSAR,
MUI PROPENSO A TROPEÇAR;
SALVO ESTOU POR TEU AMOR
E ME VOLTO A TI SENHOR.

SUBJUGADO EM TODO O SER,
ME SUBMETO AO TEU PODER;
GRANDE É O PREÇO DO PERDÃO,
INTEIRA CONSAGRAÇÃO.

EU, REMIDO PECADOR,
ME DEDICO AO REDENTOR;
TEU É ESTE CORAÇÃO,
TEU, EM PLENA COMUNHÃO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('1edeacbf-1107-425e-ac6b-2d34281db8fd', '45ab58b2-d293-45c7-aa75-090fcd968b24');
