INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1ee4adcd-34fb-41d6-834d-2be5ea1fd538', 'Jesus voltará pra me buscar! (Maranata)', '210', 'P.H.R.', 'Básico', 'D', 'Crianças e Adolescentes', 'JESUS VOLTARÁ PRA ME BUSCAR!
O MEU CORAÇÃO ANSEIA
POR ESSE ENCONTRO TÃO ESPECIAL,
ONDE TODA LÁGRIMA ELE VAI ENXUGAR.

A MINHA CANDEIA ESTÁ ACESA
E O ÓLEO NA BOTIJA TAMBÉM HÁ.
POR ISSO EU CLAMO, (2X)

MARANATA! VEM, SENHOR JESUS!
MARANATA! VEM, SENHOR JESUS!
A TUA IGREJA TE ESPERA,
A TUA IGREJA PROCLAMA:
VEM, SIM, VEM JESUS.

*CORO 2X
MARANATA É O GRITO DA IGREJA,
MARANATA É UMA FORMA DE VIDA,
MARANATA É O DESPERTAR DO SONO,
É A ESPERANÇA DA ALMA REMIDA.
/INSTRUMENTOS

POR ISSO EU CLAMO. (2X)
/*CORO 2X
MARANATA É O GRITO DA IGREJA,
MARANATA É UMA FORMA DE VIDA,
MARANATA É O DESPERTAR DO SONO,
É A ESPERANÇA DA ALMA REMIDA.

FINAL 2X
ELE VEM! MARANATA!
JESUS VEM! MARANATA!
');
