INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1f2d367a-3854-4cbb-a091-5202a7cf4e1a', 'Senhor, eu te louvarei', '235', 'M.M.F.', 'Fox', 'D', 'Crianças e Adolescentes', 'SENHOR, EU TE LOUVAREI,
EM TI ME ALEGRAREI,
DE TODO O MEU CORAÇÃO
LOUVORES A TI DAREI.

POIS TU NOS TENS SUSTENTADO
COM TUA MÃO DE PODER,
GOZO E ALEGRIA TENS DADO
A TODO QUE EM TI CRER.
');
