INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1f3ed7d1-e7e8-45a8-b4d4-2deb842a3d11', 'Posso sentir o seu toque em mim (Glorifica)', '380', 'W.S.C', 'Básico', 'A', 'Consolo e Encorajamento', 'POSSO SENTIR O SEU TOQUE EM MIM,
SINTO O SEU CALOR AQUECENDO O CORAÇÃO.
POSSO OUVIR SUA VOZ A SOAR:
“MEU SERVO, NÃO TEMAS! VOU TE AJUDAR. 
QUANDO AS LUTAS CHEGAREM, 
NÃO OLHES PARA TRÁS
OLHA PARA O ALTO E A VITÓRIA ALCANÇARÁS!”

*CORO 2X
É DO ALTO QUE VÊM NOSSAS VITÓRIAS,
CRISTO ESTÁ PRONTO A TE ESCUTAR.
NÃO ACHES QUE TUDO TERMINOU,
POIS DEUS TRAVA UMA BATALHA EM TEU FAVOR!
GLORIFICA, SÓ GLORIFICA!
ERGUE A VOZ E AGRADECE AO REI SENHOR.
GLORIFICA, SÓ GLORIFICA!
ERGUE A VOZ E AGRADECE AO REI SENHOR.
/FINAL
GLORIFICA!
');
