INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('1f64d3d5-6b90-4399-bb0a-96f4070c6bbf', 'Príncipe da paz', '032', 'C.M.V.', 'Balada', 'G', 'Crianças e Adolescentes', 'PRÍNCIPE DA PAZ, QUERO TE AMAR,
TEUS MANDAMENTOS, SIM, TODOS GUARDAR;
Ó DEUS, VEM AJUDAR-ME
A FAZER TUA VONTADE
E EM TUDO TEU NOME LOUVAR.

JESUS REDENTOR, QUERO TE ADORAR
EM ESPÍRITO E EM VERDADE;
Ó DEUS, VEM ENSINAR-ME
A LOUVAR TUA GRANDEZA
E BENDIZER TEU NOME,
Ó SENHOR!
');
