INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2022355b-4359-4a53-b23a-846e45787040', 'Bendito seja o Cordeiro', '', '', '', '', '', 'BENDITO SEJA DEUS,
POIS TANTO NOS AMOU,
QUE SEU AMADO FILHO,
AO MUNDO ENVIOU;
BENDITO O CORDEIRO,
POR TANTA COMPAIXÃO,
BENDITO PELO SANGUE,
DA ETERNA REDENÇÃO.

CORO
BENDITO SEJA DEUS POR SEU TÃO GRANDE AMOR,
A ELE EU RENDO TODO O MEU LOUVOR;
JAMAIS ESQUECEREI O AMOR QUE TENS POR MIM,
POR ISSO EU CANTO ASSIM:
BENDITO PARA SEMPRE SEJA DEUS!

A CADA DIA ESTÁ ATENTO
AO MEU VIVER,
TÃO PRONTO SEMPRE A OUVIR
E A ME SOCORRER;
ELE É A MINHA ROCHA,
MEU SÁBIO CONSELHEIRO,
ELE É MEU PAI QUERIDO,
AMIGO E COMPANHEIRO.
