INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('20265d13-7c0a-4a1a-8415-510006214a7a', 'Há um só que é digno', '598', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Louvor', 'HÁ UM SÓ QUE É DIGNO DE SOBRE NÓS REINAR
E NO TRONO DE DAVI COM GLÓRIA SE SENTAR;
O QUE ELE FALA PRA NÓS É SANTA LEI,
A ELE ACLAMAMOS: VIVA O NOSSO REI!

CORO
VIVA O REI! VIVA O REI!
O FILHO DE DAVI,
O LEÃO DE JUDÁ,
O REI DOS REIS QUE BREVE VOLTARÁ.

MUITOS SE LEVANTAM QUERENDO SE IMPOR,
COM SEUS VÃOS PROJETOS AO POVO DO SENHOR;
MAS DEUS TEM SUA OBRA E NELA SERVIREI;
FRACO SOU, MAS CLAMO: VIVA O NOSSO REI!

EIS AQUI QUEM REINA, MAIOR QUE SALOMÃO,
COMO ESPADA AGUDA SÃO OS CONSELHOS SEUS;
E A NÓS, IGREJA, DEU GRAÇA E SALVAÇÃO,
FEZ-NOS SEUS VALENTES, EXÉRCITO DE DEUS.
');
