INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('203f5b2b-5bed-474f-b2b1-0a124d101861', 'Deus Está Presente Aqui Neste Lugar', '260', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Morte, Ressureição e Salvação', 'DEUS ESTÁ PRESENTE AQUI NESTE LUGAR,
ELE QUER O SEU AMOR NOS REVELAR,
TUDO ELE CONHECE, TUDO ELE PODE,
MESMO TRANSFORMAR A TREVA EM LUZ.

ABRE O TEU CORAÇÃO A JESUS,
DEIXA SOBRE TI BRILHAR SUA LUZ,
TUDO ELE CONHECE, TUDO ELE PODE,
DEUS ESTÁ AQUI NESTE LUGAR.
/INSTRUMENTOS

ABRE O TEU CORAÇÃO A JESUS,
DEIXA SOBRE TI BRILHAR SUA LUZ,
TUDO ELE CONHECE, TUDO ELE PODE,
DEUS ESTÁ AQUI NESTE LUGAR.
/FINAL
DEUS ESTÁ AQUI NESTE LUGAR.
');
