INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('208ca703-c224-4057-a89d-f5bf2b390957', 'Jesus Cristo é o amado', 48, 'E.H.M.R.', 'Básico', 'E', 'Crianças e Adolescentes', 'JESUS CRISTO É O AMADO
QUE MORREU PELO PECADOR
O SEU SANGUE CLAMA AO PAI
PARA REDENÇÃO.
PARA OBTERMOS PERDÃO,
SEGUNDO AS RIQUEZAS DE SUA GRAÇA.

*CORO
POR ESSE MOTIVO ESCOLHEMOS
FICAR CONTIGO, JESUS.
E HONRAR TEU SACRIFÍCIO
FEITO NO ALTAR DA CRUZ.
ESCOLHEMOS A VIDA E A BÊNÇÃO
PARA NÓS E A NOSSA HERANÇA
VIVERMOS SOB A TUA PROTEÇÃO.
/INSTRUMENTOS

JESUS CRISTO É O AMADO
QUE MORREU PELO PECADOR
O SEU SANGUE CLAMA AO PAI
PARA REDENÇÃO.
PARA OBTERMOS PERDÃO,
SEGUNDO AS RIQUEZAS DE SUA GRAÇA.

*CORO 2X
POR ESTE MOTIVO ESCOLHEMOS
FICAR CONTIGO, JESUS.
E HONRAR TEU SACRIFÍCIO
FEITO NO ALTAR DA CRUZ.
ESCOLHEMOS A VIDA E A BÊNÇÃO
PARA NÓS E A NOSSA HERANÇA
VIVERMOS SOB A TUA PROTEÇÃO.
');
