INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('20a7b451-fbd9-45f9-9880-19fecd4d3e79', 'Esforça-te, Tem Bom Ânimo', '368', 'Luciana Monteiro Carneiro Simora', 'Novo', 'C', 'Consolo e Encorajamento', '"ESFORÇA-TE, TEM BOM ÂNIMO!"
ASSIM DIZ O SENHOR TEU DEUS,
O DEUS DE ISRAEL,
O DEUS QUE TE AMA,
O DEUS QUE CONTIGO SEMPRE ESTÁ;
TÃO SOMENTE ESFORÇA-TE.

*CORO 2X
ELE CONTIGO IRÁ
POR ONDE QUER QUE VÁS,
SUA BOA MÃO TE SUSTERÁ;
O SENHOR CONTIGO ESTARÁ.

NÃO TEMAS, NÃO TE APAVORES
QUANDO A LUTA SURGIR,
LEMBRA QUE O TEU DEUS
É MAIS FORTE E PODE TE AJUDAR;
TÃO SOMENTE ESFORÇA-TE.

*CORO 2X
ELE CONTIGO IRÁ
POR ONDE QUER QUE VÁS,
SUA BOA MÃO TE SUSTERÁ;
O SENHOR CONTIGO ESTARÁ.
/FINAL
TÃO SOMENTE ESFORÇA-TE.
');
