INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('20d07a34-7732-4cca-bec5-f841bbc23bff', 'O fim Vem (A Trombeta Está Pra Soar)', '', '', '', '', '', 'A TROMBETA ESTA PRA SOAR
ANUCIANDO QUE CRISTO VOLTARÁ
ALERTA IGREJA AMADA, TUDO JÁ SE CUMPRIU.
OS ANJOS JÁ ESTÃO PREPARADOS
ESPERANDO O MOMENTO DE SOAR A TROMBETA,
PORQUE O SENHOR JÁ VEM

*CORO
IGREJA O FIM VEM! O FIM VEM!
JESUS SIM VEM, JESUS VEM!
É O MOMENTO DE PREPARADOS JÁ ESTARMOS
PORQUE O FIM VEM!

FINAL
IGREJA O FIM VEM! O FIM VEM!
JESUS SIM VEM, JESUS VEM!
TUDO JÁ SE CUMPRIU. JESUS QUE UM DIA PARTIU,
VOLTARÁ! O FIM VEM! IGREJA O FIM VEM!
');
