INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('21205214-acdd-4aa2-822b-a1c0be2209cf', 'Não se turbe os vossos corações', '563', 'Durval Firme; Luciana Monteiro Carneiro Simora', 'Básico', 'Dm', 'Grupo de Louvor', 'NÃO SE TURBEM OS VOSSOS CORAÇÕES,
BREVE SE CUMPRIRÁ A PROMESSA DE JESUS;
TODO PRANTO CESSARÁ
E OS SANTOS SUBIRÃO
LEVADOS PELOS ANJOS AO SENHOR.

*CORO
ERGUEI AS VOSSAS CABEÇAS E CONTEMPLAI
OS ANJOS LOUVANDO A DEUS, O PAI;
O DIA DA VITÓRIA BREVE VAI CHEGAR,
REGOZIJAI-VOS, Ó ESCOLHIDOS DO SENHOR.

ANTES MESMO QUE NASCESSEIS
VOS ESCOLHI E VOS CONSAGREI
PARA ANUNCIARDES AS MINHAS PALAVRAS,
PORQUE VOLTAREI E SOMENTE OS FIÉIS LEVAREI.

*CORO 2X
ERGUEI AS VOSSAS CABEÇAS E CONTEMPLAI
OS ANJOS LOUVANDO A DEUS, O PAI;
O DIA DA VITÓRIA BREVE VAI CHEGAR,
REGOZIJAI-VOS, Ó ESCOLHIDOS DO SENHOR.
/FINAL
REGOZIJAI-VOS, Ó ESCOLHIDOS DO SENHOR.
');
