INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('219c010b-876f-478f-b38c-d58386cb4b18', 'Na expressão deste louvor', '594', 'Everaldo Cavalcante Lima; Jorgemar Souza Madeira', 'Básico', 'G', 'Louvor', 'NA EXPRESSÃO DESTE LOUVOR
QUERO DAR AO MEU SENHOR
TODA A MINHA GRATIDÃO
POR SER MUI FELIZ.

DEVO MUITO AO SALVADOR,
NELE TENHO O PERDÃO,
NELE TENHO A SALVAÇÃO,
EU SOU TÃO FELIZ.

*CORO
NÓS TE ADORAMOS, MEU SENHOR,
PORQUE VENCESTE NA CRUZ;
NÓS TE ADORAMOS, MEU SENHOR,
PORQUE TU HÁS DE VOLTAR;
NÓS TE ADORAMOS, MEU SENHOR,
POIS TU ÉS A RAZÃO
E O MOTIVO DA NOSSA ADORAÇÃO.

LÁ NA CRUZ MORREU JESUS,
O SEU SANGUE DERRAMOU,
O MEU FARDO ELE LEVOU
E HOJE LIVRE SOU.

*CORO 2X
NÓS TE ADORAMOS, MEU SENHOR,
PORQUE VENCESTE NA CRUZ;
NÓS TE ADORAMOS, MEU SENHOR,
PORQUE TU HÁS DE VOLTAR;
NÓS TE ADORAMOS, MEU SENHOR,
POIS TU ÉS A RAZÃO
E O MOTIVO DA NOSSA ADORAÇÃO.
');
