INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('22023964-9e61-4513-a9f2-49539dc9fcb2', 'Estou alegre', '752', 'Autor Desconhecido', 'Marcha', 'A', 'Corinhos', 'ESTOU ALEGRE, ALEGRE, MUI ALEGRE,
ESTOU ALEGRE, ALEGRE EU ESTOU,
ESTOU ALEGRE, ALEGRE, MUI ALEGRE,
ESTOU ALEGRE PORQUE CRISTO ME SALVOU.

POR ISSO EU CANTO, EU CANTO ALELUIA,
POR ISSO EU CANTO,
EU CANTO GLÓRIA A DEUS,
POR ISSO EU CANTO, EU CANTO ALELUIA,
POR ISSO EU CANTO
PORQUE CRISTO ME SALVOU.

CANTAR 3X
NÃO SOU DO MUNDO,
DO MUNDO EU NÃO SOU,
/NÃO SOU DO MUNDO
PORQUE CRISTO ME SALVOU.

CANTAR 3X
VOU PARA O CÉU
E PARA O CÉU EU VOU,
/VOU PARA O CÉU
PORQUE CRISTO ME SALVOU.
');
