INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2235d361-4ed7-46c4-8c52-9a5a860d9642', 'Cristo, nome mais alto', '153', 'Autor Desconhecido', 'Balada', 'C', 'Dedicação', 'CRISTO, NOME MAIS ALTO,
SALVADOR NOSSO, GLORIOSO SENHOR;
EMANUEL É DEUS CONOSCO,
NOME DE VIDA, DIVINO SENHOR.

FINAL 2X
EMANUEL, EMANUEL,
SEU NOME É EMANUEL!
ELE ME AMOU,
ME TRANSFORMOU
E VIVE EM MIM, EMANUEL.
');
