INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('226312d1-722b-4bf8-89dc-5732ad9e28b8', 'Quando Dobro os Joelhos', '', '', '', '', '', 'É DE JOELHOS,
QUE TE OFERTAMOS AS NOSSAS VIDAS.
É DE JOELHOS, QUE TE ENTREGAMOS
O NOSSO CORAÇÃO, Ó DEUS.

*CORO
EM GRATIDÃO A TI, POR TEU TÃO
GRANDE AMOR; POR ENVIAR JESUS,
PRA SER O NOSSO SALVADOR.
E TODA GRATIDÃO DE AMOR, QUE HÁ
NESTE LOUVOR É PARA DEMONSTRAR
AO MUNDO QUE ÉS SENHOR.
/INSTRUMENTOS

É DE JOELHOS, QUE RECONHECEMOS
TODA A NOSSA LIMITAÇÃO.
É NESTA CONDIÇÃO, QUE TU OPERAS
E SONDAS O NOSSO CORAÇÃO.

TUA ALIANÇA TU CONCEDES ÀS NOSSAS
VIDAS, E A ESPERANÇA DE UM NOVO LAR
NO CÉU.
RECONHECEMOS, NÃO MERECEMOS,
TEU GRANDE AMOR.
E A NOSSA ALMA EXPRESSA ASSIM,
UM SINCERO LOUVOR.

*CORO
EM GRATIDÃO A TI, POR TEU TÃO
GRANDE AMOR; POR ENVIAR JESUS,
PRA SER O NOSSO SALVADOR.
E TODA GRATIDÃO DE AMOR, QUE HÁ
NESTE LOUVOR É PARA DEMONSTRAR
AO MUNDO QUE ÉS SENHOR.
/FINAL
É PARA DEMONSTRAR AO MUNDO
QUE ÉS O EU SOU.
');
