INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('226d5368-b796-4e10-ab7f-7021998b4c15', 'Louvai, servos do Senhor', '655', 'José Elias Simora', 'Básico', 'G', 'Salmos de Louvor', 'LOUVAI, SERVOS DO SENHOR,
LOUVAI, SERVOS DO SENHOR.
/SEJA BENDITO O NOME DO SENHOR,
SEJA BENDITO O NOME DO SENHOR.
/LOUVAI, LOUVAI, LOUVAI AO SENHOR.

SEJA EXALTADO O NOME DO SENHOR,
SEJA GRANDIOSO O NOME DO SENHOR,
DE ETERNIDADE PARA SEMPRE, AMÉM,
A ETERNIDADE, PARA SEMPRE, AMÉM.

CANTAR 2X
LOUVAI, LOUVAI, LOUVAI AO SENHOR
(SEJA BENDITO O NOME DO SENHOR)

FINAL 2X 
LOUVAI, LOUVAI,
LOUVAI AO SENHOR,
LOUVAI AO SENHOR.
');
