INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('22737709-af88-4502-80d0-fcec9adcc84c', 'Quero estar ao pé da cruz', '279', 'Let.: Fanny Jane Crosby; Trad.: Júlio César Ribeiro; Mús.: Willian Howard Doane', 'Balada', 'F', 'Morte, Ressureição e Salvação', 'QUERO ESTAR AO PÉ DA CRUZ,
DE ONDE RICA FONTE
CORRE FRANCA, SALUTAR,
DO CALVÁRIO, MONTE.

CORO
SIM, NA CRUZ, SIM, NA CRUZ,
SEMPRE ME GLORIO
E ENFIM VOU DESCANSAR
SALVO, ALÉM DO RIO.

A TREMER AO PÉ DA CRUZ,
GRAÇA ETERNA ACHOU-ME;
MATUTINA ESTRELA ALI
RAIOS SEUS MANDOU-ME.

SEMPRE A CRUZ, JESUS, MEU DEUS,
QUEIRAS RECORDAR-ME;
DELA À SOMBRA, SALVADOR,
QUEIRAS ABRIGAR-ME.

JUNTO À CRUZ, ARDENDO EM FÉ,
SEM TEMOR VIGIO,
POIS À TERRA SANTA IREI,
SALVO, ALÉM DO RIO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('22737709-af88-4502-80d0-fcec9adcc84c', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
