INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2306d7d8-7f80-4aaa-9ab4-ea272207eeeb', 'Cristo Cura, Sim!', '', '', '', '', '', 'CONTRA OS MALES DESDE MUNDO,
DEUS NOS VALE SÓ
NÃO HA MAL QUE DEUS NÃO CURE
POS DE NÓS TEM DÓ.

CORO
CRISTO, CURA SIM
CRISTO, CURA SIM
SEU AMOR POR NÓS É IMENSO
CRISTO CURA SIM.

DERRAMOU SEU SANGUE PURO
PRA REMIR A MIM
QUANDO O UNGIDO,
SOU DE AZEITE
SOU CURADO ENFIM.

SÓ NOSSA ALMA É BEM SEGURA
OCULTA EM JESUS
ELE O BALSAMO DA VIDA
DERRAMOU NA CRUZ.

GLORIA DEUS ETERNO
GLORIA DEMOS-LHE LOUVOR
GLORIA CÂNTICOS DE HOSANAS
DAI AO REDENTOR.
');
