INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('237223ad-af57-460e-a2a7-d2e129762392', 'Se As Lutas da Vida', '367', 'José Elias Simora', 'Valseado', 'A', 'Consolo e Encorajamento', 'SE AS LUTAS DA VIDA TE FAZEM CHORAR
E ÀS VEZES TE FALTAM FORÇAS PRA VENCER,
EXISTE UM DEUS QUE AO TEU LADO ESTÁ,
ELE É DEUS FORTE, POR TI VENCERÁ;
EXISTE UM DEUS QUE AO TEU LADO ESTÁ,
ELE É FIEL E NÃO FALHARÁ.

DEUS CUIDA DE TI, (2X)
É TEU AMIGO, ESTÁ CONTIGO, 
DEUS CUIDA DE TI.

SÓ EXISTE UM DEUS E AO TEU LADO ESTÁ,
ELE É DEUS FORTE, POR TI VENCERÁ;
SIM, EXISTE UM DEUS E AO TEU LADO ESTÁ,
ELE É FIEL E NÃO FALHARÁ. (2X)
');
