INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('243344ab-7595-44f7-8bf7-c1973f651653', 'As muitas águas não poderiam apagar', '193', 'Jorgemar Souza Madeira', 'Balada', 'C', 'Grupo de Louvor', 'AS MUITAS ÁGUAS NÃO PODERIAM APAGAR ESTE AMOR,
NEM OS RIOS O AFOGARÃO;
AINDA QUE ALGUÉM DESSE OS BENS DE SUA CASA,
POR ESTE AMOR, OS DESPREZARIA.

*CORO 2X
E É ASSIM O AMOR DE DEUS,
INDESCRITÍVEL, INSONDÁVEL É ESTE AMOR.
/INSTRUMENTOS

AS MUITAS ÁGUAS NÃO PODERIAM APAGAR ESTE AMOR,
NEM OS RIOS O AFOGARÃO;
AINDA QUE ALGUÉM DESSE OS BENS DE SUA CASA,
POR ESTE AMOR, OS DESPREZARIAM.

*CORO 2X
E É ASSIM O AMOR DE DEUS,
INDESCRITÍVEL, INSONDÁVEL É ESTE AMOR.
/FINAL
DO MEU JESUS.
');
