INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('244e1768-9225-4286-bed7-bbd3ef0683db', 'Jesus tão belo', '589', 'Let. e Mús.: Autor Desconhecido; Versão da letra: Hoffman Fallersleben; Versão de Mús. Tradicional Polonesa', 'Básico', 'E', 'Louvor', 'JESUS TÃO BELO,
Ó, REI DA TERRA,
NASCESTE IGUAL A DEUS SENHOR,
ÉS DE MINH''ALMA, SOL, ALEGRIA,
COROA, GLÓRIA, LUZ, AMOR.

DOS CÉUS A GLÓRIA, A MAJESTADE,
EM TI, SENHOR, EU POSSO VER,
DE MIM MAIS PERTO OU MAIS QUERIDO,
Ó, MEU JESUS, NINGUÉM VOU TER.

JESUS AMADO,
Ó, REI GLORIOSO,
AO PECADOR SÓ QUERES BEM,
POIS SEJA SEMPRE,
LOUVOR E GLÓRIA A TI,
Ó, SALVADOR, AMÉM.
');
