INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('24e2c8a0-0cad-4159-88de-873ac9dfdf16', 'Uma Voz Mansa e Delicada', 78, 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Invocação e Comunhão', 'UMA VOZ MANSA E DELICADA
FALA AO MEU CORAÇÃO,
VOZ TÃO SUAVE, MARAVILHOSA,
TRAZ PAZ E CONSOLAÇÃO.
OH! QUE VOZ MANSA E DELICADA,
QUE FALA AO MEU CORAÇÃO.

ESTA VOZ DOCE QUE EU ESCUTO
É A VOZ DO MEU SENHOR,
ELE ESTÁ VIVO, FALA COMIGO,
ELE É O MEU CONSOLADOR.
/FINAL 2X
OH! QUE VOZ MANSA E DELICADA,
QUE FALA AO MEU CORAÇÃO.
');
