INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('256a6058-5074-4a14-8ffa-44a754f23124', 'Por Amor Jesus Morreu', '218', 'Roberto Cézar Fernandes', 'Básico', 'A', 'Morte, Ressureição e Salvação', 'CANTAR 2X
POR AMOR JESUS MORREU,
VEIO PARA ME SALVAR,
POR AMOR SEU SANGUE VERTEU,
NAQUELA AMARGA CRUZ,
POR AMOR SE FEZ MEU PRESENTE,
TORNANDO-SE AMIGO ME FEZ SEU PARENTE.

POR AMOR SE FEZ MEU PRESENTE,
TORNANDO-SE AMIGO
ME FEZ SEU PARENTE.
VIVA O REI, (JESUS)
VIVA O REI, (VIVA O REI)
VIVA O REI, (VIVA O REI)
VIVA O REI.
');
