INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('25b865b1-1f10-4211-9b64-e2e87e140aeb', 'Jesus é a Rocha Inabalável', '370', 'Olcimar Rubens de Carvalho', 'Básico', 'A', 'Consolo e Encorajamento', 'JESUS É A ROCHA INABALÁVEL,
REFÚGIO E FORTALEZA DOS FIÉIS;
MESMO QUE TEU CHORO DURE TODA A NOITE,
MAS AO AMANHECER A ALEGRIA
ENCHERÁ TEU CORAÇÃO,
PORQUE JESUS TE FALARÁ:
"NÃO CHORES, ÉS MEU FILHO MUITO AMADO".

AINDA QUE AS PROVAS SEJAM MUITAS,
NÃO TEMAS, CONFIA EM JESUS;
MESMO QUE TEU PRANTO SE CONVERTA EM DOR,
MAS AO ROMPER DO DIA A FELICIDADE
ENCHERÁ TEU CORAÇÃO
PORQUE JESUS TE FALARÁ:
"NÃO CHORES, ÉS MEU FILHO MUITO AMADO".

JESUS É A ROCHA INABALÁVEL,
REFÚGIO E FORTALEZA DOS FIÉIS;
AINDA QUE AS PROVAS SEJAM MUITAS,
NÃO TEMAS, CONFIA EM JESUS.
/FINAL
NÃO TEMAS, CONFIA EM JESUS.
');
