INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('26298119-e573-4ff6-a813-616001321a72', 'Deus o Seu Filho Enviou', '209', 'Autor Desconhecido', 'Repique', 'D', 'Morte, Ressureição e Salvação', 'CANTAR 2X
DEUS O SEU FILHO ENVIOU
PARA MORRER NUMA CRUZ;
NUM DESEJO PROFUNDO DO SEU CORAÇÃO,
QUIS O HOMEM SALVAR.

NESTE CAMINHO DA VIDA, ACONTECE QUE,
SE DE DEUS, LONGE ESTOU,
TENHO QUE IR A JESUS;
LEMBRO QUE ELE SOFREU LÁ NA CRUZ.

CANTAR 2X
PARA RESGATAR MINHA VIDA,
PARA TRANSFORMAR MEU CORAÇÃO,
DANDO-ME PERDÃO, VIDA ETERNA,
SEU AMOR.
/FINAL
SEU AMOR.
');
