INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('265d1c8f-a87c-4495-aec7-4caccf20be43', 'A Obra do Senhor é Perfeita', '421', 'Sérgio Paulo Ferreira de Matos', 'Marcha', 'G', 'Santificação e Derramamento', 'A OBRA DO SENHOR É PERFEITA,
É COMO A LUZ DO SOL
EM SEU ESPLENDOR,
É CHUVA SOBRE A TERRA,
SEMENTE QUE PROSPERA,
A OBRA DO SENHOR. (2X)

A OBRA DO SENHOR É PERFEITA,
É COMO A LUZ DO SOL EM SEU ESPLENDOR,
É CHUVA SOBRE A TERRA,
SEMENTE QUE PROSPERA,
A OBRA DO SENHOR.
A OBRA DO SENHOR É PERFEITA,
A OBRA DO SENHOR É PRECIOSA.
');
