INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2675ce5f-be51-4a4f-87bc-c0adf7ae139b', 'A Minha Herança', '422', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Santificação e Derramamento', 'A MINHA HERANÇA ÉS TU, SENHOR,
E TUA OBRA É PARA MIM MEU BEM MAIOR;
EM CADA DIA TE CONHECER
E DESCOBRIR TEU PLANO PARA O MEU VIVER.

CORO
DAS MÃOS DO MEU JESUS HERANÇA RECEBI,
ESTA VINHA QUE ME DEU PARA GUARDAR;
POR OUTRO BEM QUALQUER DO MUNDO AQUI
JAMAIS EU PODEREI MINHA HERANÇA TROCAR.

E SE VIER A TENTAÇÃO
RESISTIREI FIRMADO EM TUA SALVAÇÃO;
A VIDA AQUI POSSO PERDER,
MAS UMA HERANÇA ETERNA
VOU NO CÉU RECEBER.
');
