INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2697252b-1455-4a93-8202-e700d9162ae1', 'Meu amado Filho', '241', 'Jorgemar Souza Madeira', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'MEU AMADO FILHO, TE ESCOLHI,
NÃO TEMAS, MAS ESFORÇA-TE,
ASSIM DIZ O SENHOR;
MINHA MÃO ESTENDIDA PARA TI,
POR ONDE QUER QUE FORES,
NÃO TE DEIXAREI.

CORO 2X
MINHA PAZ 
EU TE DOU,
NÃO TE DEIXAREI, 
DIZ O SENHOR.

A TERRA PROMETIDA TE DAREI,
A ÁRVORE DA VIDA TE CONCEDEREI;
RIOS DE ÁGUA VIVA FLUIRÃO
E O MEU IMENSO AMOR NO TEU CORAÇÃO.

FINAL 3X
NÃO TE DEIXAREI, 
DIZ O SENHOR.
');
