INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('27dc02ed-72cc-4860-84b6-38ff3402797e', 'Glória e Aleluia', '577', 'José Manuel Carvalho', 'Básico', 'D', 'Louvor', '(M) GLÓRIA E ALELUIA NÓS TE DAMOS, SENHOR,
(H) BENDITO SEJA O TEU SANTO NOME;
(M) GRAÇAS E LOUVORES TE RENDEMOS, SENHOR,
(H) EXALTADA SEJA A TUA SALVAÇÃO.

POIS O SENHOR É MINHA ROCHA E MINHA FORÇA
E O MEU ALTO REFÚGIO;
A ELE CLAMAREI E ELE ME SALVARÁ,
É ELE QUEM ME TEM DADO A VITÓRIA.

(M) GLÓRIA E ALELUIA NÓS TE DAMOS, SENHOR,
(H) BENDITO SEJA O TEU SANTO NOME;
(M) GRAÇAS E LOUVORES TE RENDEMOS, SENHOR,
(H) EXALTADA SEJA A TUA SALVAÇÃO.

POIS O SENHOR É MINHA ROCHA E MINHA FORÇA
E O MEU ALTO REFÚGIO;
A ELE CLAMAREI E ELE ME SALVARÁ,
É ELE QUEM ME TEM DADO A VITÓRIA.

(M) GLÓRIA E ALELUIA NÓS TE DAMOS, SENHOR,
(H) BENDITO SEJA O TEU SANTO NOME;
(M) GRAÇAS E LOUVORES TE RENDEMOS, SENHOR,
(H) EXALTADA SEJA A TUA SALVAÇÃO.
/FINAL
EXALTADA SEJA A TUA SALVAÇÃO.
');
