INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('284443d9-dac3-405b-b7d2-f0b5d9357e1d', 'Regozijai - vos', '527', 'Olcimar Rubens de Carvalho', 'Básico', 'Em', 'Volta de Jesus e Eternidade', '(VARÕES)"REGOZIJAI-VOS, Ó MEUS AMADOS,
(VARÕES)ESPERAI UM POUCO MAIS,
(VARÕES)O MEU FILHO VIRÁ EM BREVE,
(VARÕES)SOBRE AS NUVENS ELE VIRÁ,
(VARÕES)JESUS VIRÁ!"

