INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('28ff683a-208f-4d4d-ac23-5b5a1cf46c6d', 'Tenho nova vida', '782', 'Autor Desconhecido', 'Fox Abafado', 'D', 'Dedicação', 'TENHO NOVA VIDA, AGORA SOU FELIZ,
NUNCA ESTOU SOZINHO, CRISTO MORA EM MIM;
CANTO COM AMOR, CANTO COM ALEGRIA,
LOUVANDO SEMPRE A JESUS 
QUE VIRÁ UM DIA.

TUDO É NOVO EM MIM, TUDO É TÃO BELO,
SER IGUAL A CRISTO É O QUE MAIS ANELO;
CANTO COM ALEGRIA, CANTO COM AMOR,
LOUVANDO SEMPRE A JESUS, O MEU SALVADOR.
');
