INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('293975f4-8bd1-4b8f-ba4b-3fc0b610d13d', 'Ó profundidade de riquezas', '586', 'Gérson Beluci Miguel', 'Balada', 'C', 'Louvor', 'Ó PROFUNDIDADE DAS RIQUEZAS,
TANTO DA SABEDORIA
COMO DO CONHECIMENTO DE DEUS,
QUÃO INSONDÁVEIS SÃO SEUS JUÍZOS,
QUÃO INESCRUTÁVEIS OS SEUS CAMINHOS!
/INSTRUMENTOS

AH! POR QUE QUEM COMPREENDEU
OS INTENTOS DO SENHOR?
OU QUEM FOI SEU CONSELHEIRO?
OU QUEM LHE DEU PRIMEIRO A ELE?
PRA QUE LHE SEJA RECOMPENSADO.

CANTAR 2X
PORQUE DELE E POR ELE E PARA ELE
SÃO TODAS AS COISAS;
GLÓRIA, GLÓRIA, GLÓRIA POIS A ELE
ETERNAMENTE, AMÉM.
/FINAL
AMÉM!
');
