INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('295bf0f7-1e32-4a04-8fbd-4fefa814d073', 'Quero prosseguir', '126', 'Raquel Toscano de Freitas', 'Básico', 'D', 'Dedicação', 'QUERO PROSSEGUIR NESTA JORNADA,
EU FUI CHAMADO,
COM LAÇOS DE AMOR ABENÇOADO,
TENHO MEU JESUS SEMPRE AO MEU LADO.

NÃO TEMER, PROSSEGUIR,
E VENCER TODA LUTA, ENFIM;
MEU DEUS ESTÁ COMIGO,
SINTO SUA PRESENÇA;
DEU-ME CONFIANÇA, ESTE É MEU SENHOR!

FINAL 2X
AMIGO VERDADEIRO,
SINCERO E AMOROSO,
LEAL E COMPANHEIRO, 
JESUS TENS MEU AMOR.
');
