INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('29c483d4-33a0-4131-b031-de6c9ca7c10c', 'Aleluia', '653', 'Sl.113; Adapt.Let. e Mús.: Gérson Beluci Miguel', 'Básico', 'Am', 'Salmos de Louvor', '*CORO
ALELUIA! LOUVAI, SERVOS DO SENHOR!
LOUVAI O NOME DO SENHOR!
/BENDITO SEJA O NOME DO SENHOR
DESDE AGORA E PARA SEMPRE,
DO NASCER DO SOL ATÉ O OCASO,
LOUVADO SEJA O NOME DO SENHOR!

EXCELSO É O NOME DO SENHOR,
SUA GLÓRIA ESTÁ ACIMA DOS CÉUS,
QUEM HÁ SEMELHANTE AO SENHOR,
O NOSSO DEUS?
NAS ALTURAS ESTÁ SEU TRONO!
/*CORO
ALELUIA! LOUVAI, SERVOS DO SENHOR!
LOUVAI O NOME DO SENHOR!

O SENHOR SE INCLINA DESDE O CÉU
PARA VER O QUE HÁ NA TERRA.
ELE ERGUE DO PÓ O DESVALIDO
PARA O ASSENTAR COM OS PRÍNCIPES
DO SEU POVO.

FINAL
ALELUIA! (LOUVAI!)
LOUVAI, SERVOS DO SENHOR!
LOUVAI O NOME DO SENHOR!
ALELUIA! (LOUVAI!)
');
