INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2a0e713d-f2cd-4919-92dd-fab5381e4c7b', 'Eu quero ir para o céu', '208', 'R.C.B.Z.; E.H.M.R.', 'Básico', 'Am', 'Crianças e Adolescentes', 'EU QUERO IR PARA O CÉU
VER O MEU SALVADOR.
QUE ME RESGATOU,
SEU SANGUE ME COMPROU

EU QUERO IR PARA O CÉU
VIVER COM MEU JESUS
ANDAR NA SUA LUZ,
PASSEAR NO SEU JARDIM.

EU QUERO IR PARA O CÉU
NAS RUAS DE OURO ANDAR
VER AS BELAS MANSÕES,
SUA GLÓRIA CONTEMPLAR.
/INSTRUMENTOS

EU QUERO IR PARA O CÉU
MORAR COM MEU SENHOR
DA ÁRVORE DA VIDA
EU QUERO DESFRUTAR.

FINAL 2X
ADORAR O MEU JESUS,
COM OS ANJOS VOU CANTAR.
');
