INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2a140bee-3715-4d0a-9e0c-1d58031723ca', 'Se Orarmos ao Senhor', 59, 'Jorgemar Souza Madeira', 'Básico', 'D', 'Invocação e Comunhão', 'SE ORARMOS AO SENHOR,
SE CANTARMOS SEUS LOUVORES,
SUA GLÓRIA ENCHERÁ
ESTE LUGAR, ESTE LUGAR;

RIOS DE ÁGUAS VIVAS FLUIRÃO
NO MEU, NO TEU CORAÇÃO.
E O GRANDE AMOR DE DEUS,
REVELADO EM JESUS,
SIM, ENCHERÁ ESTE LUGAR.
/INSTRUMENTOS

SE ORARMOS AO SENHOR,
SE CANTARMOS SEUS LOUVORES,
SUA GLÓRIA ENCHERÁ
ESTE LUGAR, ESTE LUGAR;

RIOS DE ÁGUAS VIVAS FLUIRÃO
NO MEU, NO TEU CORAÇÃO.
E O GRANDE AMOR DE DEUS,
REVELADO EM JESUS,
SIM, ENCHERÁ ESTE LUGAR.

FINAL
RIOS DE ÁGUAS VIVAS FLUIRÃO
NO MEU, NO TEU CORAÇÃO.
E O GRANDE AMOR DE DEUS,
REVELADO EM JESUS,
SIM, ENCHERÁ ESTE LUGAR. (3X)
');
