INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2a38bd78-fc2e-4af2-94d2-ddbafb141f65', 'Quando oro ao Senhor', '020', 'C.M.V.C.S.', 'Valseado', 'C', 'Crianças e Adolescentes', 'QUANDO ORO AO SENHOR
SINTO PAZ EM MEU CORAÇÃO.
SUA PRESENÇA É TÃO REAL,
SUA GRAÇA ME SATISFAZ.
/PORQUE JESUS POR MIM MORREU
E VIVO ESTÁ A INTERCEDER AO PAI POR MIM.

CANTAR 2X
POSSO ENTÃO DESCANSAR,
PORQUE EU SEI QUE O SENHOR
TODO BEM FARÁ PRA MIM.
/FINAL
TODO BEM FARÁ PRA MIM.
');
