INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2aa5bb83-e51a-4ab7-80d7-47afabd53bd8', 'Careço de Jesus', '', '', '', '', '', 'CAREÇO DE JESUS, SEMPRE DE TI, SENHOR.
SOMENTE A TUA VOZ TEM PARA MIM VALOR.

CORO
DE TI SENHOR CAREÇO,
SEMPRE DE TI CAREÇO,
OH! DA-ME A TUA BÊNÇÃO
ASPIRO A TI.

CAREÇO DE JESUS! UNIDO A TI SENHOR
PECADO E TENTAÇÃO, PERDEM O SEU VIGOR.
/CAREÇO DE JESUS! REGE MEU CORAÇÃO.
ENSINA-ME A VIVER EM SANTA RETIDÃO
/CAREÇO DE JESUS! NAS TREVAS E NA LUZ.
SEM TI A VIDA É VÃ, SOU POBRE SEM JESUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('2aa5bb83-e51a-4ab7-80d7-47afabd53bd8', '377b4956-8af4-40b5-90ce-868956eab5c2');
