INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2b309bf1-50a0-48fc-8607-8ccce0031500', 'Tu és Maravilhoso', '', '', '', '', 'Avulsos das Senhoras', 'O MEU MAIOR DESEJO É TE ADORAR;
E O MEU AMOR EM CANTO DERRAMAR;
UNGIR-TE COM PERFUME MAIS PRECIOSO;
E AOS TEUS PÉS CONFESSAR, QUE ÉS MARAVILHOSO.

COM LÁGRIMAS TE ADORO, MEU AMADO;
NA CRUZ PAGASTE PELO MEU PECADO;
E HOJE ME ABRAÇAS AMOROSO.
JESUS, JESUS, TU ÉS PRA MIM MARAVILHOSO. (2X)

COMO HEI DE AGRADECER O TEU AMOR,
QUE ESPANTA OS CÉUS DE TÃO ENCANTADOR
NÃO TENHO NADA DIGNO PRA TE DAR;
SÓ MEU VASO, QUE QUEBRO PARA TE ADORAR.

COM GRATIDÃO, SENHOR, TEUS PÉS EU BEIJO;
ÉS TUDO QUANTO TENHO E QUE DESEJO.
CONTIGO SOU; SEREI SEMPRE DITOSO.
/FINAL 2X 
JESUS, TU ÉS PRA MIM MARAVILHOSO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('2b309bf1-50a0-48fc-8607-8ccce0031500', '377b4956-8af4-40b5-90ce-868956eab5c2');
