INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2b4f6431-dc64-473e-ab68-06b7e4abde59', 'Sempre imaginei em minha vida', '', '', '', '', '', 'SEMPRE IMAGINEI EM MINHA VIDA QUE EXISTIRIA UM
LUGAR, ONDE EU NÃO PUDESSE MAIS SOFRER E A
MINHA DOR EU PODERIA ESQUECER.
NÃO MAIS LEMBRAR DE TUDO O QUE PASSOU
E UMA NOVA VIDA COMEÇAR.

*CORO
O CÉU É O LUGAR ONDE EU VOU MORAR,
NÃO HÁ TRISTEZA LÁ, TODA A ANGÚSTIA ACABARÁ.
QUANDO JESUS VOLTAR E JUNTO ME LEVAR
TODA A LÁGRIMA SECARÁ POIS O SENHOR ENXUGARÁ.

SE NÃO HÁ ESPERANÇA EM TUA VIDA, QUE UM DIA
PODERIA SER FELIZ, SAIBA QUE POR TI MORREU JESUS E
TODO O SOFRIMENTO FOI VENCIDO LÁ NA CRUZ. PARA
PODER MUDAR O TEU SOFRER E ALEGRIA ETERNA
CONHECER.

O CÉU É O LUGAR ONDE TU VAIS MORAR,
NÃO HÁ TRISTEZA LÁ, TODA A ANGÚSTIA ACABARÁ.
QUANDO JESUS VOLTAR E JUNTO TE LEVAR
TODA A LÁGRIMA SECARÁ POIS O SENHOR ENXUGARÁ.

*CORO
O CÉU É O LUGAR ONDE VAMOS MORAR,
NÃO HÁ TRISTEZA LÁ, TODA A ANGÚSTIA ACABARÁ.
QUANDO JESUS VOLTAR E JUNTO NOS LEVAR
TODA A LÁGRIMA SECARÁ POIS O SENHOR ENXUGARÁ.
/ENXUGARÁ (ENXUGARÁ), (2X)
ENXUGARÁ.
');
