INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2ba91169-cd4d-483e-ac33-af1ab7dc8660', 'O meu amado desceu ao seu jardim', '424', 'Vanias Jeamond Luz', 'Country', 'Em', 'Santificação e Derramamento', 'CANTAR 2X
