INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c0cb601-4aed-44ac-ba6a-ee60e99d8b05', 'Nós te adoramos, Senhor', '627', 'Let.:Everaldo Cavalcante Lima, Luciana Monteiro Carneiro Simora; Mús. Luciana Monteiro Carneiro Simora', 'Básico', 'E', 'Louvor', 'NÓS TE ADORAMOS, SENHOR,
POIS ÉS DIGNO DE LOUVOR,
NOSSO REI E SALVADOR, NOSSO SENHOR.
A TUA GLÓRIA ESTÁ NESTE LUGAR,
A TUA PRESENÇA FAZ TRANSBORDAR
O NOSSO CORAÇÃO DE LOUVOR.
/INSTRUMENTOS

*CORO 2X
A TUA GLÓRIA (GLÓRIA)
SE ESTENDE SOBRE OS CÉUS
(SE ESTENDE SOBRE OS CÉUS)
E O TEU LOUVOR (E O TEU LOUVOR)
AOS CONFINS DA TERRA (SE FAZ OUVIR)
/INSTRUMENTOS

EM SANTIDADE, Ó SENHOR,
QUEREMOS TE ADORAR,
EM UMA SÓ VOZ TUA GLÓRIA EXALTAR.

*CORO
A TUA GLÓRIA (GLÓRIA)
SE ESTENDE SOBRE OS CÉUS
(SE ESTENDE SOBRE OS CÉUS)
E O TEU LOUVOR (E O TEU LOUVOR)
AOS CONFINS DA TERRA (SE FAZ OUVIR)

*CORO
A TUA GLÓRIA (GLÓRIA)
SE ESTENDE SOBRE OS CÉUS
(SE ESTENDE SOBRE OS CÉUS)
E O TEU LOUVOR (E O TEU LOUVOR)
AOS CONFINS DA TERRA

FINAL
A TUA GLÓRIA ESTÁ NESTE LUGAR,
A TUA PRESENÇA FAZ TRANSBORDAR
O NOSSO CORAÇÃO DE LOUVOR.
');
