INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c108487-e9cb-4b75-9908-e2e92f000bce', 'Há Vitória Sempre em Ti, Senhor', '054', 'Geraldo Gomes Pinheiro', 'Fox Abafado', 'D', 'Clamor', 'HÁ VITÓRIA SEMPRE EM TI, SENHOR, (2X)
PELO SANGUE DE JESUS DERRAMADO POR MIM,
HÁ VITÓRIA SEMPRE EM TI, SENHOR.

HÁ VITÓRIA SEMPRE EM TI, SENHOR, (2X)
CONTRA AS TREVAS TENHO LUZ,
SOU REMIDO POR JESUS,
HÁ VITÓRIA SEMPRE EM TI, SENHOR.

HÁ VITÓRIA SEMPRE EM TI, SENHOR, (2X)
PELA VOLTA DE JESUS,
PELA PAZ NO CORAÇÃO,
HÁ VITÓRIA SEMPRE EM TI, SENHOR.
');
