INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c39563e-6849-4baa-88b7-e930f320a784', 'Pela fé eu posso contemplar Jesus', '179', 'Jorgemar Souza Madeira', 'Básico', 'G', 'Dedicação', 'PELA FÉ EU POSSO CONTEMPLAR JESUS,
(PELA FÉ EU POSSO VER)
PELA FÉ EU VEJO O BRILHO DA SUA LUZ,
PELA FÉ EU POSSO VER OS ANJOS CANTANDO,
EXALTANDO O NOSSO REI, O SALVADOR.

PELA FÉ EU SINTO NO MEU CORAÇÃO
(PELA FÉ POSSO SENTIR)
A PRESENÇA DO ESPÍRITO DE DEUS,
PELA FÉ EU SINTO SUA MÃO TOCAR EM MIM,
PELA FÉ POSSO SENTIR SEU GRANDE AMOR.

FINAL 2X
E PELA FÉ VOU CAMINHANDO
ATÉ CHEGAR À TERRA PROMETIDA,
E PELA FÉ JÁ OUÇO O CANTO DE VITÓRIA:
CRISTO REINANDO COM OS FIÉIS NA SUA GLÓRIA.
');
