INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c412d31-7a3e-4fe4-a16f-a0a9a98aee6e', 'A terra semeamos', '717', '', 'Marcha Marcial', 'G', 'Grupo de Louvor', 'A TERRA SEMEAMOS 
A FIM DE NOS DAR PÃO,
MAS DEUS É QUEM A NUTRE
COM BENFAZEJA MÃO.
É DEUS QUEM MANDA O FRIO,
A CHUVA E O BOM CALOR
E FAZ SURGIR DA TERRA 
O FRUTO APÓS A FLOR.

CORO
DE TODO BEM A FONTE
É NOSSO BOM SENHOR!
LOUVAI A DEUS, LOUVAI A DEUS
POR TODO O SEU AMOR!

O CRIADOR DE TUDO, 
QUE PERTO OU LONGE ESTÁ
COLORE A FLOR SILVESTRE
E À ESTRELA O BRILHO DÁ.
OS VENTOS LHE OBEDECEM,
O BRAVO MAR TAMBÉM;
AS FRÁGEIS AVEZINHAS 
O SEU CUIDADO TÊM!

A NÓS, PORÉM, SEUS FILHOS,
REVELA MAIS AMOR;
O FILHO ETERNO DEU-NOS,
JESUS, O SALVADOR,
A NÓS FAZENDO HERDEIROS
DE TUDO QUANTO TEM,
NA REDENÇÃO PERFEITA
QUE DELE NOS PROVÉM.
');
