INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c557f02-5f04-4037-af4f-fe94054c585e', 'Ouve a Voz de Jesus', '236', 'Jorgemar Souza Madeira', 'Básico 2', 'G', 'Morte, Ressureição e Salvação', 'OUVE A VOZ DE JESUS
QUE É TÃO LINDA E TÃO CALMA
E ESTÁ CHAMANDO: "VEM JÁ!"
SE ESTÁS CANSADO, DISSE ELE ASSIM:
"MEU FILHO, VEM HOJE A MIM!"

SE ESTÁS CANSADO, DISSE ELE ASSIM:
"MEU FILHO, VEM HOJE A MIM!"
/MANSO E SUAVE É JESUS,
QUÃO DOCE E MEIGO É OUVI-LO!
VEM JÁ OUVIR SUA VOZ;

FINAL 2X
SE ESTÁS CANSADO, DISSE JESUS:
"EU SOU O CAMINHO E A LUZ."
');
