INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c57a558-3cc9-4317-bedb-475d32eb9da2', 'Deus é nosso amparo', '359', 'Sl.46; Autor Desconhecido', 'Country', 'Dm', 'Consolo e Encorajamento', 'DEUS É NOSSO AMPARO, NOSSA FORTALEZA,
NOSSO PRONTO AUXÍLIO NA TRIBULAÇÃO,
AINDA QUE SE MUDEM
OS MONTES PARA O MAR,
/CANTAR 2X
AINDA QUE A TERRA TREMA,
TEREMOS QUE CONFIAR.

CANTAR 2X
CÉUS E TERRA PODERÃO PASSAR,
MAS SUA PALAVRA NÃO PASSARÁ.
/NÃO, NÃO, NÃO PASSARÁ. (2X)

SANTO, SANTO, SANTO, DIZ O SERAFIM,
SANTO, SANTO, SANTO, É O SENHOR JEOVÁ,
SANTO, SANTO, SANTO,
É O DEUS QUE NOS REDIME,
/CANTAR 2X
PORQUE TRÊS VEZES SANTO,
A TERRA TREME ONDE DEUS ESTÁ;

CANTAR 2X
CÉUS E TERRA PODERÃO PASSAR,
MAS SUA PALAVRA NÃO PASSARÁ.
/FINAL
NÃO, NÃO, NÃO PASSARÁ,
NÃO, NÃO, NÃO PASSARÁ.
');
