INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c684831-3563-4364-99e8-891d1632479f', 'Jesus, Tu és o meu Deus (SCTB)', '039', 'Let: Sérgio Carlos de Souza; Mús. Emanoel Aleixo Júnior', 'Básico', 'Dm', 'Clamor', 'JESUS, TU ÉS O MEU DEUS,
A MINH''ALMA TEM SEDE DE TI, 
EU TE DESEJO, Ó DEUS,
NECESSITADO ESTOU.

NO TEU SANGUE HÁ RENOVO,
PODER PARA TRANSFORMAR,
PARA LIBERTAR E PERDOAR,
DERRAMA DESTE SANGUE EM MIM.

CANTAR 2X
E ASSIM TE BENDIREI
ENQUANTO EU VIVER,
EM TEU NOME FALAREI,
OS MEUS LÁBIOS TE LOUVARÃO.
/FINAL
ALELUIA, AMÉM. (2X)
');
