INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2c92e4f6-4660-498f-ae88-a3a1958ccf87', 'Vou contar-vos de Jesus', '077', 'S.G.D.', 'Fox', 'E', 'Crianças e Adolescentes', 'VOU CONTAR-VOS DE JESUS
O QUE JOÃO NOS ENSINOU:
ELE, POR AMOR, SE FEZ NOSSO SALVADOR.

DE ALUNOS QUE CHAMOU:
PEDRO, ANDRÉ, TIAGO E JOÃO,
FELIPE, BARTOLOMEU E MATEUS,
TIAGO, SIMÃO, TOMÉ,
JUDAS, O BOM AMIGO,
OUTRO JUDAS, O TRAIDOR.

JESUS A TODOS CHAMOU:
"EU SOU O CAMINHO, A VERDADE E A LUZ",
A ELES ENSINOU.

VOU CONTAR-VOS DE JESUS
O QUE JOÃO NOS ENSINOU:
ELE, POR AMOR, SE FEZ NOSSO SALVADOR.

DE ALUNOS QUE CHAMOU:
