INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2cfe2e7a-ba5f-4a7a-bd01-e7bd1bddabdd', 'Ainda há tempo', '001', '', 'Básico', 'Dm', 'Dm', 'COMO É FORTE OUVIR
COMO SERÁ O FIM;
O MOMENTO CHEGARÁ,
O CLAMOR DA MEIA-NOITE
SE OUVIRÁ.

A IGREJA FIEL
PREPARADA ESTÁ
E A IGREJA INFIEL,
SUA OPORTUNIDADE ACABARÁ.

AINDA HÁ TEMPO,
JESUS CRISTO NÃO VOLTOU,
AINDA HÁ TEMPO
DO SEU SONO DESPERTAR.

AINDA HÁ TEMPO,
TEMPO DE SE ARREPENDER,
TEMPO DE BUSCAR A DEUS,
DE BATER À PORTA E ELA SE ABRIRÁ.

AINDA HÁ TEMPO
DO AZEITE IR COMPRAR,
AINDA HÁ TEMPO,
TEMPO DE SANTIFICAR;

AINDA HÁ TEMPO
DA CANDEIA SE ENCHER,
DO ESPOSO ENCONTRAR
E COM ELE,
PARA AS BODAS DO CORDEIRO, ENTRAR.
INSTRUMENTOS

AINDA HÁ TEMPO,
JESUS CRISTO NÃO VOLTOU,
AINDA HÁ TEMPO
DO SEU SONO DESPERTAR.

AINDA HÁ TEMPO,
TEMPO DE SE ARREPENDER,
TEMPO DE BUSCAR A DEUS,
DE BATER À PORTA E ELA SE ABRIRÁ.

AINDA HÁ TEMPO
DO AZEITE IR COMPRAR,
AINDA HÁ TEMPO,
TEMPO DE SANTIFICAR;

AINDA HÁ TEMPO
DA CANDEIA SE ENCHER,
DO ESPOSO ENCONTRAR
E COM ELE,
PARA AS BODAS DO CORDEIRO, ENTRAR.
FINAL
AINDA HÁ TEMPO.
');
