INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2d1172c2-5780-4391-8491-10ee9ac5caa8', 'Quando Ao Fim da Jornada Eu Chegar (Masculino)', '', '', '', '', '', 'HAVERÁ LUZ NOS CÉUS DAS MORADAS DE DEUS?
QUANDO AO FIM DA JORNADA EU CHEGAR
E DELÍCIAS SEM PAR VOU PRA SEMPRE SONHAR
QUANDO AO FIM DA JORNADA EU CHEGAR.

CORO
QUANDO O DIA FINDAR DESTE MEU LABUTAR
COM OS SALVOS NOS CÉUS HEI DE ENTRAR
DE JESUS EU TEREI BÊNÇÃOS MIL EU BEM SEI
QUANDO AO FIM DA JORNADA EU CHEGAR.

MINHAS LUTAS ENTÃO DESAPARECERÃO
QUANDO AO FIM DA JORNADA EU CHEGAR
E O MEU PADECER DEUS FARÁ ESQUECER
QUANDO AO FIM DA JORNADA EU CHEGAR.

UM PORTAL SE ABRIRÁ, CRISTO ME SALVARÁ
QUANDO AO FIM DA JORNADA EU CHEGAR
RECOMPENSAS IREI RECEBER DO MEU REI
QUANDO AO FIM DA JORNADA EU CHEGAR.
');
