INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2d19f2d6-6e9c-4c1b-8930-803200b74e3c', 'Cantarei a bondade e a justiça', '391', 'Fernanda Silva', 'Balada', 'Dm', 'Santificação e Derramamento', 'CANTAREI A BONDADE E A JUSTIÇA,
A TI, SENHOR,
CANTAREI, CANTAREI, CANTAREI,
CANTAREI, CANTAREI.

CANTAR 2X
ATENTAREI SABIAMENTE
AO TEU CAMINHO, SENHOR,
ATENTAREI, ATENTAREI;
Ó, QUANDO VIRÁS TER COMIGO, SENHOR?
Ó, QUANDO, SENHOR?
MAS CANTAREI, CANTAREI,
CANTAREI, CANTAREI.

FINAL
MAS CANTAREI, CANTAREI,
CANTAREI, CANTAREI.
');
