INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2d61e27c-7c67-4319-b553-8531d9901468', 'Um novo lar me espera', '519', 'Raquel Toscano de Freitas', 'Básico', 'Fm', 'Volta de Jesus e Eternidade', 'UM NOVO LAR ME ESPERA,
VOU COM JESUS MORAR;
QUE ALEGRIA SEM PAR,
VOU PRA GLÓRIA,
É A VITÓRIA.

FINAL 2X
ANDAR PELAS RUAS DE OURO
COM OS ANJOS E O REI JESUS,
A QUEM ENTREGUEI A MINHA VIDA
POIS POR MIM MORREU NA CRUZ.
');
