INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2dc5c6f0-fcb9-4763-a562-7cb5f95bb62c', 'Por Amor', '219', 'Sérgio Paulo Ferreira de Matos', 'Valseado', 'A', 'Morte, Ressureição e Salvação', 'POR AMOR, POR AMOR JESUS ME SALVOU.
FOI NA CRUZ, FOI NA CRUZ QUE O PREÇO PAGOU,
NÃO COM PRATA, NEM OURO,
MAS COM SANGUE MOSTROU
O INFINITO AMOR COM QUE AO MUNDO AMOU.

*CORO
TÃO GRANDE AMOR ME TRANSFORMOU;
BASTA CRER E ACEITAR,
POR SEU SANGUE CLAMAR
E O AMOR DE MEU DEUS VAI TUA VIDA INUNDAR.
/INSTRUMENTOS

DO IMENSO AMOR NINGUÉM VAI SEPARAR,
É MAIS FORTE QUE A MORTE,
ARDE EM MIM SEM CESSAR;
TUDO CRÊ E SUPORTA ATÉ O DIA CHEGAR,
E O AMOR DE MEU DEUS LÁ NO CÉU VOU GOZAR.

*CORO
TÃO GRANDE AMOR ME TRANSFORMOU;
BASTA CRER E ACEITAR,
POR SEU SANGUE CLAMAR
E O AMOR DE MEU DEUS VAI TUA VIDA INUNDAR.
');
