INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2de7624a-00bf-4b04-a5a9-24d34a44ba44', 'Jesus, o mistério revelado', '022', 'Let / Mús. Aline Aparecida Ferreira Artini e Ramon Artini', 'Básico', 'A', 'Avulsos', 'JESUS, O MISTÉRIO REVELADO,
QUE ALIMENTA A MINHA ALMA;
ELE É O MEU TESOURO,
É A MINHA ESPERANÇA.

CORO
ESTE MISTÉRIO ME TRANSFORMOU,
ESTE MISTÉRIO MINHA VIDA MUDOU,
ESTE MISTÉRIO É TUDO PRA MIM: JESUS!
INSTRUMENTOS

JESUS QUER A TI SE REVELAR,
QUER ALIMENTAR TUA ALMA;
ABRA O TEU CORAÇÃO
E RECEBA A SALVAÇÃO.

CORO 2X
ESTE MISTÉRIO ME TRANSFORMOU,
ESTE MISTÉRIO MINHA VIDA MUDOU,
ESTE MISTÉRIO É TUDO PRA MIM: JESUS!
FINAL
ESTE MISTÉRIO É TUDO PRA MIM: JESUS!
');
