INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2e095bcf-2da3-4703-8b4b-af376cfcb2ef', 'Quando chego em tua casa', 39, '', '', '', '', 'QUANDO CHEGO EM TUA CASA
DOBRO OS MEUS JOELHOS,
COMEÇO A ORAR, SINTO ALGO
TÃO DIVINO, TÃO MARAVILHOSO,
COMEÇO A CHORAR, SINTO UM
CALOR TÃO FORTE QUE VAI
AQUECENDO O MEU CORAÇÃO,
SEI QUE É O MEU JESUS E
JÁ OUVIU MINHA ORAÇÃO.

CORO
JESUS, VEM TOCAR EM MINHA VIDA
TRAZENDO UM POUCO DE ALEGRIA
PARA ESTE POBRE, POBRE CORAÇÃO;
JESUS, PELA FÉ AGORA EU VEJO
O ANJO TRAZENDO A VITÓRIA E
ELE ENTREGA EM MINHAS MÃOS.

SE ESTÁ AMARGURADO,
SE ESTÁ CANSADO DE TANTO SOFRER,
SUAS FORÇAS JÁ SE FORAM,
VOCÊ ATÉ PENSA QUE NÃO VAI VENCER,
LEVANTE SEUS OLHOS AGORA,
VEJA A VITÓRIA PERTO DE VOCÊ,
JESUS CRISTO ESTÁ AQUI E ESTÁ
DIZENDO: VOCÊ VAI VENCER.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('2e095bcf-2da3-4703-8b4b-af376cfcb2ef', '45ab58b2-d293-45c7-aa75-090fcd968b24');
