INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2e2fc33d-45a5-43a8-b6f4-bab4171ff41b', 'Grandioso para mim', '162', 'Autor Desconhecido', 'Fox Abafado', 'G', 'Dedicação', 'GRANDIOSO PARA MIM É JESUS,
MEU SALVADOR,
SUA GRAÇA NÃO TEM FIM,
COM SEU DIVINAL FULGOR;
SUA GRAÇA SE ESTENDEU,
DANDO-ME A SALVAÇÃO;
GRANDE PAZ E ALEGRIA
EU DESFRUTAREI UM DIA
NA CELESTIAL SIÃO.

O TEU NOME É AMOR, EU CONFESSO A TI, SENHOR;
O TEU NOME É PURO E BOM, PERDOADO AGORA ESTOU;
NESTE MUNDO DE ILUSÃO, ENQUANTO EU AQUI VIVER,
/FINAL 2X
MINHA BOCA ENTOARÁ ALELUIA,
SEM CESSAR EXALTANDO O TEU PODER.
');
