INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2e593a7a-0c3d-473d-be8e-d76d02c166db', 'Em Breve, Mui Breve', '509', 'Paulo Emanuel dos Santos Teixeira', 'Balada', 'D', 'Volta de Jesus e Eternidade', 'EM BREVE, MUI BREVE IREMOS VER
AS PORTAS DO CÉU SE ABRIREM,
O CORDEIRO DESCENDO EM GLÓRIA
NO MONTE DAS OLIVEIRAS.

*CORO 2X
HOSANA, HOSANA,
HOSANA AO FILHO DE DAVI.
/JUNTO COM OS ANJOS
LOUVAREMOS O SEU SANTO NOME,
TODOS OS SEUS REMIDOS
EXALTARÃO O REI NA SUA GLÓRIA.

*CORO 2X
HOSANA, HOSANA,
HOSANA AO FILHO DE DAVI.
/FINAL
HOSANA AO FILHO DE DAVI.
');
