INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2e63e35f-c25c-4bde-9c7f-72fd51cd039e', 'Gloria pra sempre ao Cordeiro de Deus', '591', 'André Torres', 'Balada', 'E', 'Louvor', 'GLÓRIA PRA SEMPRE AO CORDEIRO DE DEUS,
A JESUS, O SENHOR, AO LEÃO DE JUDÁ,
À RAIZ DE DAVI, QUE VENCEU
E O LIVRO ABRIRÁ.

O CÉU, A TERRA E O MAR,
E TUDO O QUE NELES HÁ,
O ADORARÃO E CONFESSARÃO:
JESUS CRISTO É O SENHOR.

ELE É O SENHOR, ELE É O SENHOR;
RESSURRETO DENTRE OS MORTOS,
ELE É O SENHOR;
TODO JOELHO SE DOBRARÁ,
TODA LÍNGUA CONFESSARÁ
QUE JESUS CRISTO É O SENHOR.

GLÓRIA PRA SEMPRE AO CORDEIRO DE DEUS,
A JESUS, O SENHOR, AO LEÃO DE JUDÁ,
À RAIZ DE DAVI, QUE VENCEU
E O LIVRO ABRIRÁ.

O CÉU, A TERRA E O MAR,
E TUDO O QUE NELES HÁ,
O ADORARÃO E CONFESSARÃO:
JESUS CRISTO É O SENHOR.
');
