INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2e66d28b-d46b-4818-a26c-e0fbbd7e723c', 'Meu servo, não temas', '672', 'Mauro Sérgio dos Santos Loureiro', 'Balada', 'E', 'Grupo de Louvor', 'CANTAR 2X
MEU SERVO, NÃO TEMAS,
NÃO TEMAS POIS TE ESCOLHI
PRA FAZER A MINHA OBRA,
SERVO, TU ÉS MEU.

QUANDO EU TE ENVIAR, TU FALARÁS;
QUANDO EU MANDAR, TU CALARÁS,
E ASSIM FARÁS MINHA OBRA
E TE ALEGRARÁS.

QUANDO A OBRA FIZERES
E TUDO SE COMPLETAR,
/CANTAR 3X
TE TRAREI À MINHA PRESENÇA
E TE ALEGRARÁS.
');
