INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2ebdc2f3-7a3c-4a9e-997e-aabe9a7a0c3a', 'Muitos motivos tenho', '237', 'J.L.M.M.', 'Básico', 'F', 'Crianças e Adolescentes', 'MUITOS MOTIVOS TENHO
PARA TE ADORAR, OH, DEUS!
TU ÉS PARA MIM O MARAVILHOSO,
O PRÍNCIPE DA PAZ.

*CORO
JESUS, TU ÉS PARA MIM O DEUS FIEL,
MARAVILHOSO,
OUTRO DEUS COMO O SENHOR NÃO HÁ.
/INSTRUMENTOS

HOJE AQUI ESTOU A TE GLORIFICAR
PELAS BÊNÇÃOS RECEBIDAS,
POR TUDO O QUE ME FAZ.

*CORO 2X
JESUS,
TU ÉS PARA MIM O DEUS FIEL,
MARAVILHOSO
OUTRO DEUS COMO O SENHOR NÃO HÁ.
/FINAL 2X
OUTRO DEUS COMO O SENHOR NÃO HÁ.
');
