INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2f369034-c199-45bb-95c1-e99468150f88', 'Meu pecado resgatado', 87, 'Let.:Guilherme Luiz dos Santos Ferreira; Mús.: Ira David Sankey', 'Valseado', 'D', 'Morte, Ressureição e Salvação', 'MEU PECADO RESGATADO
FOI NA CRUZ, POR TEU AMOR,
E DA MORTE, TRISTE SORTE,
ME LIVRASTE TU, SENHOR!

CORO
VEM! INFLAMA VIVA CHAMA
EM MEU PEITO, BEM SEM FIM!
EU TE ADORO, SEMPRE IMPLORO:
Ó JESUS, HABITA EM MIM!

SE HESITANTE, VACILANTE,
OUÇO A VOZ DO TENTADOR,
TU ME GUIAS, ME AUXILIAS
E ME TORNAS VENCEDOR.

REDIMIDA, SÓ TEM VIDA
A MINHA ALMA EM TEU AMOR;
COM APREÇO, RECONHEÇO
QUANTO DEVO A TI, SENHOR!
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('2f369034-c199-45bb-95c1-e99468150f88', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
