INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('2f67f384-3e9d-424f-bb9a-5228748baf9e', 'Quando Jesus seu Sangue Verteu', '267', 'Jorgemar Souza Madeira', 'Balada', 'Dm', 'Morte, Ressureição e Salvação', 'QUANDO JESUS SEU SANGUE VERTEU,
TUDO SE FEZ NOVO,
O VÉU SE RASGOU, A TERRA TREMEU,
MORREU NA CRUZ O FILHO DE DEUS.
/INSTRUMENTOS

ELE RESTAUROU O MEU CORAÇÃO,
DEU-ME UMA NOVA VIDA.
OH! QUANTO ME AMOU,
MEU MESTRE E SENHOR,
PERTENCE A ELE TODO MEU LOUVOR.
/INSTRUMENTOS

FOI POR AMAR-ME QUE JESUS SOFREU,
TUDO DEVO A CRISTO;
O QUE DAREI AO MEU SALVADOR?
LOUVÁ-LO-EI POR SEU INFINITO AMOR.
');
