INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('30b08734-8809-46e9-b94d-03ef330ef239', 'Jesus Me Ama', '', '', '', '', '', 'ENSINA-ME AMAR,
MESMO QUANDO SÓ HÁ ÓDIO
AO MEU REDOR.
ENSINA-ME A DAR,
MESMO QUANDO NÃO HÁ
NADA A RECEBER.

ENSINA-ME A ACEITAR,
TUDO O QUE TENS PREPARADO PARA MIM,
CONFIANDO QUE TUDO ESTÁ EM TUAS MÃOS,
E QUE TUDO VEM DE TI,
JESUS.

ENSINA-ME ADORAR,
MESMO QUANDO HÁ PRANTO
EM MEU CORAÇÃO.
TAMBÉM A PERDOAR,
COMO A MIM TENS REVELADO
O TEU PERDÃO.

E QUE EU POSSA TER MAIS
SEDE DE TI CONHECER MELHOR,
CADA MAIS VONTADE
DE ESTAR AO TEU REDOR,
ESCUTANDO O TEU FALAR,
SENTINDO O TEU AMOR,
VIVENDO JUNTO A TI SENHOR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('30b08734-8809-46e9-b94d-03ef330ef239', '45ab58b2-d293-45c7-aa75-090fcd968b24');
