INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('30cae6c1-7d2d-4930-a837-ed61c1aa4bb3', 'O espírito do Senhor está sendo derramado', '438', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'Am', 'Santificação e Derramamento', 'O ESPÍRITO DO SENHOR
ESTÁ SENDO DERRAMADO,
PREPARANDO A NOIVA AMADA
PARA AS BODAS DO CORDEIRO!
MARANATA! MARANATA!
ORA VEM, JESUS!
MARANATA! MARANATA!
ORA VEM, JESUS!
');
