INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('30d25d07-2788-4d21-a0e1-5746a9d5c7b4', 'Proclamai a todo o mundo que o Senhor é Rei', '721', '', 'Marcha Marcial', 'G', 'Grupo de Louvor', 'CORO
PROCLAMAI A TODO O MUNDO
QUE O SENHOR É REI!
PROCLAMAI! PROCLAMAI!
PROCLAMAI QUE SUAVE E DOCE
É SUA SANTA LEI!
PROCLAMAI! PROCLAMAI!

PROCLAMAI COMO ELE SE CHAMA
O SALVADOR JESUS,
COMO ELE POR NÓS MORREU
NA ENSANGUENTADA CRUZ;
COMO ELE, O CORDEIRO, 
SOBRE O TRONO ESTÁ,
O DEUS DE TODA A GRAÇA
QUE MORREU EM MEU LUGAR.

PROCLAMAI QUE REINA EM GRAÇA
NOSSO SALVADOR!
QUE POR CETRO DE SEU REINO
ELE TEM O AMOR!
ANUNCIAI AOS TRISTES QUE ELE VIVO ESTÁ,
E A TODOS OS CANSADOS
QUE DESCANSO ELE DÁ.

PROCLAMAI QUE ELE DO CÉU
EM BREVE DESCERÁ!
E COM TODOS OS SEUS SANTOS APARECERÁ!
QUE SEM DEMORA VENHAM
TODOS SE RENDER,
E COM AMOR, EM TUDO A CRISTO OBEDECER.
');
