INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3187ef77-6f6f-46c5-bcb3-1d572c097b0c', 'É o amor de Deus', '145', 'Rose Margareth Silva Mendes', 'Básico', 'E', 'Dedicação', 'CANTAR 2X
É O AMOR DE DEUS
A CAUSA DE NÃO SERMOS CONSUMIDOS.

POIS AINDA QUE FAÇAMOS PRA MERECER,
NUNCA MERECEMOS ESTE AMOR
QUE É LINDO E PURO,
É O AMOR QUE DEUS TE OFERECE AGORA.

É O AMOR DE DEUS QUE TE LIVRA
DE TODA CILADA E INVESTIDA,
ESTÁ SEMPRE AO NOSSO LADO
PRA CUIDAR DE NÓS
EMBORA NÃO MEREÇAMOS ESSE AMOR.
/INSTRUMENTOS

ELE NOS GUARDA EM TODOS OS MOMENTOS
DE NOSSAS VIDAS
E ÀS VEZES SOMOS INGRATOS,
/FINAL 2X
MAS ELE NOS AMA
E É POR CAUSA DESSE AMOR
QUE NÃO SOMOS CONSUMIDOS.
');
