INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3189d405-db2e-4d31-976f-1808f57bd1f7', 'Não Há O Que Temer', '', '', '', '', '', 'EU SOU O SENHOR, REI DE ISRAEL
SANTO REDENTOR, COMEÇO E O FIM
SOU O CRIADOR, O VERDADEIRO DEUS
EU SOU A CURA, SOU O PODER.
EU SOU O AMÉM, ESTRELA DA MANHÃ
EU MORRI NA CRUZ, TROUXE SALVAÇÃO
CONHEÇO A TUA DOR, OUÇO O TEU CLAMOR
E MINHA DESTRA, NÃO FALHARÁ.

*CORO
NÃO HÁ O QUE TEMER, CONTIGO EU ESTOU
NÃO TE ASSOMBRES, PORQUE EU SOU
O TEU DEUS TE FORTALECEREI,
TE SUSTENTAREI COM A MINHA MÃO,
EU SEREI FIEL.
/INTRUMENTOS

EU SOU O SENHOR, REI DE ISRAEL
SANTO REDENTOR, COMEÇO E O FIM
SOU O CRIADOR, O VERDADEIRO DEUS
EU SOU A CURA, SOU O PODER.
EU SOU O AMÉM, ESTRELA DA MANHÃ
EU MORRI NA CRUZ, TROUXE SALVAÇÃO
CONHEÇO A TUA DOR, OUÇO O TEU CLAMOR
E MINHA DESTRA, NÃO FALHARÁ.

*CORO
NÃO HÁ O QUE TEMER, CONTIGO EU ESTOU
NÃO TE ASSOMBRES, PORQUE EU SOU
O TEU DEUS TE FORTALECEREI,
TE SUSTENTAREI COM A MINHA MÃO,
EU SEREI FIEL.
');
