INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('31904e9f-1b41-4aa4-9831-5c724ba18d38', 'Deus está aqui', '778', 'Autor Desconhecido', 'Country', 'G', 'Invocação e Comunhão', 'DEUS ESTÁ AQUI,
QUÃO GLORIOSO É!
ELE PROMETEU, ONDE HÁ DOIS OU TRÊS.
FICA, SENHOR, FICA, SENHOR,
FICA, SENHOR, AQUI.

Ó CRISTO MEU, FAZE DE MIM UM ALTAR
PARA ADORAR-TE COM DEVOÇÃO,
PARA BEBER DA ÁGUA DA VIDA
E SACIAR, SENHOR, MEU CORAÇÃO.
/FINAL 2X
FICA, SENHOR, FICA, SENHOR,
FICA, SENHOR, AQUI.
');
