INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('32039e1e-2824-4ce5-96d9-27d99a75bfce', 'Jerusalém anseio ver', '188', 'J.S.M.', 'Fox Abafado', 'C', 'Crianças e Adolescentes', 'JERUSALÉM ANSEIO VER,
CIDADE SANTA CHEIA DE AMOR,
OH! COMO É LINDO SEU ESPLENDOR;
A LUZ QUE BRILHA, LUZ DO MEU SENHOR;

RUAS DE OURO ANDAREI,
JUNTO COM OS ANJOS TRILHAREI,
VEREI A FACE DE JESUS
E VIVEREI NA SUA LUZ.

IREI MORAR, COM JESUS VOU HABITAR
EM GRANDE GLÓRIA E ESPLENDOR
COM MEU SENHOR;
LÁ DOR NÃO HAVERÁ,
TRISTEZAS NEM DESILUSÕES,
SEMPRE ESTAREI
BEM PERTINHO DO MEU REI.
/INSTRUMENTOS

JERUSALÉM ANSEIO VER,
CIDADE SANTA CHEIA DE AMOR,
OH! COMO É LINDO SEU ESPLENDOR;
A LUZ QUE BRILHA, LUZ DO MEU SENHOR;

RUAS DE OURO ANDAREI,
JUNTO COM OS ANJOS TRILHAREI,
VEREI A FACE DE JESUS
E VIVEREI NA SUA LUZ.

IREI MORAR, COM JESUS VOU HABITAR
EM GRANDE GLÓRIA E ESPLENDOR
COM MEU SENHOR;
LÁ DOR NÃO HAVERÁ,
TRISTEZAS NEM DESILUSÕES,
SEMPRE ESTAREI
BEM PERTINHO DO MEU REI.

FINAL
SEMPRE ESTAREI
BEM PERTINHO DO MEU REI.
');
