INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('32733fb7-0652-4f2c-ab51-db07bf044bf6', 'Deixa-me Chorar Aos Teus Pés', '', '', '', '', '', 'A TEUS PÉS, JESUS, NOS PROSTRAMOS,
TU QUE A MORTE JÁ VENCESTE COM PODER;
PELO ESPÍRITO TE ADORAMOS,
TUA PRESENÇA AQUI PODEMOS PERCEBER.

CORO
AO CORDEIRO, AO REI
QUE ALCANÇOU NA CRUZ VITÓRIA,
SEJA O LOUVOR, PODER E GLÓRIA.

ENTRE OS CASTIÇAIS NÓS TE VEMOS,
COMO CHAMA FORTE É O TEU OLHAR;
BRANCOS COMO A LÃ, TEUS CABELOS,
VOZ DE MUITAS ÁGUAS É O TEU FALAR.

FINAL
TU ÉS O FIEL CAVALEIRO
QUE SAIU VITORIOSO E VAI VOLTAR;
JUSTO JUIZ TU ÉS, VERDADEIRO,
QUE OS VIVOS E OS MORTOS VAI JULGAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('32733fb7-0652-4f2c-ab51-db07bf044bf6', '45ab58b2-d293-45c7-aa75-090fcd968b24');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('32733fb7-0652-4f2c-ab51-db07bf044bf6', 'd369f950-5259-483c-9412-b0a37d90042c');
INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('3805676f-110c-453b-93de-f554a73e719b', '32733fb7-0652-4f2c-ab51-db07bf044bf6', 'c2fb644f-697c-4d43-9d5f-22319fa0ce79', 'pdf', 'assets/praises/32733fb7-0652-4f2c-ab51-db07bf044bf6/3805676f-110c-453b-93de-f554a73e719b.pdf', 'Avulsos Migrados/Deixa-me Chorar Aos Teus Pés/coro.pdf', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3283cdc8-fd74-45ad-91b2-890d2bb54333', 'Ao Poço de Jacó Chegou Jesus', '229', 'Autor Desconhecido', 'Guarânia', 'A', 'Morte, Ressureição e Salvação', 'AO POÇO DE JÁCÓ CHEGOU JESUS,
ESTAVA CANSADO, 
ALI CHEGOU PRA DESCANSAR;
CHEGOU TAMBÉM ALI UMA MULHER,
COM SEU CÂNTARO ÁGUA FOI BUSCAR.

JESUS PEDIU-LHE ÁGUA PRA BEBER,
MAS A MULHER FEZ EXCEÇÃO
E NÃO LHE DEU,
POR SER SAMARITANA JESUS ERA JUDEU,
MAS DA ÁGUA QUE JESUS DIZIA, ELA BEBEU.

*CORO
SE TU CONHECERAS O DOM DE DEUS,
TU PEDIRIAS, ELE DARIA PRA BEBER
DA ÁGUA MUI SUPERNA,
QUE SALTA PRA VIDA ETERNA,
DESTA ÁGUA SÓ JESUS TEM PARA DAR.

JESUS É MAIS QUE O POÇO DE JÁCÓ,
ELE É A FONTE DE BASTANTE ÁGUA,
É SÓ TOMAR;
TODOS QUE TÊM PECADO É SÓ CHEGAR,
ESTA ÁGUA TEM PODER PRA LIBERTAR.

A ÁGUA QUE JESUS DÁ, ELA É SUAVE,
ACONSELHÁVEL, E JESUS MANDA BEBER;
QUEM TOMA DESTA ÁGUA VIDA ETERNA TEM,
VIVER COM CRISTO, AQUI E NO ALÉM.

*CORO
SE TU CONHECERAS O DOM DE DEUS,
TU PEDIRIAS, ELE DARIA PRA BEBER
DA ÁGUA MUI SUPERNA,
QUE SALTA PRA VIDA ETERNA,
DESTA ÁGUA SÓ JESUS TEM PARA DAR.
');
