INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('32af8718-fb19-495f-b146-9a1f628ed25a', 'No expresso viajamos', '184', 'A.D.', 'Country', 'E', 'Crianças e Adolescentes', 'NO EXPRESSO VIAJAMOS
PARA O BOM PAÍS DA LUZ,
É NOSSO PASSAPORTE O NOME DE JESUS;
É HORA DA PARTIDA E ENSEJO AINDA TÊM
AQUELES QUE QUISEREM
TER PASSAGEM NESSE TREM.

BEM-VINDOS SEJAM TODOS
PARA O TREM QUE PARTE JÁ,
ENTRADA PARA A PÁTRIA
JESUS A TODOS DÁ;

EIS O SINAL DE MARCHA,
SE QUERES IR TAMBÉM,
RECEBE O TEU BILHETE
DE PASSAGEM NESSE TREM.
');
