INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('32e2ed2b-5540-4d99-8702-3c5797ef2213', 'Com o Espírito de Deus em minha vida', '154', 'C.M.V.C.S.', 'Fox Abafado', 'E', 'Crianças e Adolescentes', 'CORO
COM O ESPÍRITO DE DEUS EM MINHA VIDA,
SOU FELIZ, SOU FELIZ!
TENHO PAZ, CONSOLO, GRAÇA E ALEGRIA,
SOU FELIZ, SIM, SOU FELIZ!

CRISTO PROMETEU DEIXAR-NOS O CONSOLADOR
PARA ESTAR CONOSCO SEMPRE
ONDE QUER QUE FOR.
O ESPÍRITO DE VERDADE, QUE ACONSELHARÁ
MINHA VIDA,
ENSINANDO COMO DEVO ANDAR.

QUERO SER OBEDIENTE
AO ESPÍRITO DE DEUS,
SEGUIR SUA PALAVRA
E OS ENSINOS SEUS,
TESTEMUNHAR QUE TENHO DEUS EM MEU VIVER,
MINHA VIDA É TRANSFORMADA, VOU DIZER PORQUÊ:
');
