INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('33332ff5-696e-4cea-9d45-35417f7c8b74', 'Em Nossos Lábios', '642', 'Marciel Denadai', 'Básico', 'F', 'Grupo de Louvor', 'EM NOSSOS LÁBIOS SEMPRE
HAVERÁ UM CANTO A TI, JESUS, 
POR TUDO QUE TENS FEITO
E POR TUDO QUE FARÁS 
EM NOSSAS VIDAS.

QUEREMOS EXPRESSAR
NOSSO AMOR E GRATIDÃO
A TI, JESUS, PELA TUA SALVAÇÃO
E PELO TEU PERDÃO,
RESGATANDO-NOS PRA TUA ADORAÇÃO.
O TEU AMOR NOS SUSTENTA, SENHOR,
A TUA GRAÇA RENOVA OS CORAÇÕES
E NOS BASTA.

*CORO
TODO LOUVOR E ADORAÇÃO
PERTENCEM A TI ETERNAMENTE,
NOSSAS VIDAS, Ó SENHOR, ENTREGAMOS
EM TEU ALTAR PRA TE ADORAR, JESUS.
/INSTRUMENTOS

FAZ DE NÓS, SENHOR,
UM VASO EM TUAS MÃOS
PARA EXPRESSAR.

*CORO
TODO LOUVOR E ADORAÇÃO
PERTENCEM A TI ETERNAMENTE,
NOSSAS VIDAS, Ó SENHOR, ENTREGAMOS
EM TEU ALTAR PRA TE ADORAR, JESUS.

EM NOSSOS LÁBIOS SEMPRE
HAVERÁ UM CANTO A TI, JESUS, 
POR TUDO QUE TENS FEITO
E POR TUDO QUE FARÁS 
EM NOSSAS VIDAS.
');
