INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3336be5b-c58b-43a2-80a5-60b2b7c53341', 'Ó Vem Logo, Jesus', '547', 'Jorgemar Souza Madeira', 'Valseado', 'D', 'Volta de Jesus e Eternidade', 'Ó VEM LOGO, JESUS!
Ó VEM LOGO, JESUS!
A MINH''ALMA TE ESPERA, 
Ó VEM LOGO, JESUS!
/INSTRUMENTOS

QUANTO ALMEJO TE VER,
MEU AMADO JESUS,
O TEU ROSTO TÃO LINDO,
BRILHANDO TUA LUZ.
ORA VEM (VEM), 
VEM (VEM), JESUS!
/INSTRUMENTOS

A MINH''ALMA TE ESPERA,
GLORIOSO JESUS,
COROADO DE GLÓRIA,
BRILHANDO TUA LUZ.
ORA VEM (VEM), 
VEM (VEM), JESUS!
/INSTRUMENTOS

Ó VEM LOGO, JESUS!
Ó VEM LOGO, JESUS!
A MINH''ALMA TE ESPERA,
Ó VEM LOGO, JESUS!

CANTAR 2X
Ó VEM LOGO, JESUS!
(VEM, VEM, VEM VEM!)
Ó VEM LOGO, JESUS!
(VEM, VEM, VEM VEM!)
A MINH''ALMA TE ESPERA
(VEM, VEM, VEM VEM!),
Ó VEM LOGO, JESUS!
/FINAL
VEM JESUS!
');
