INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('337dfd25-ad2e-4b2c-a97c-3c2061905655', 'Envia a Tua luz', 85, 'Sl.43:3,4/Adapt. Let. e mús. Jesiel Correia', 'Toada', 'D', 'Invocação e Comunhão', 'ENVIA A TUA LUZ, Ó DEUS,
ENVIA A TUA VERDADE, MEU SENHOR,
PRA QUE ME GUIEM AO TEU SANTO MONTE,
AOS TEUS TABERNÁCULOS, MEU SENHOR,
MEU CRIADOR, MEU REI, Ó MEU SENHOR.

