INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3483c775-5bdd-4a9a-ad0d-149552b14035', 'Eu Sou', '', '', '', '', '', '(M) EU SOU A RAIZ DE DAVI,
(M) A ESTRELA DA MANHÃ;
(M) LEÃO DA TRIBO DE JUDÁ,
(M) EU SOU, EU SOU.
/(H) EU SOU O ALFA E O ÔMEGA,
(H) O COMEÇO E O FIM.

PRIMEIRO E O ÚLTIMO. EU SOU!
EU SOU A VERDADE FIEL,
PALAVRA DE DEUS, SOU O CORDEIRO,
EU SOU, EU SOU.

FINAL 2X
EU SOU A RESSURREIÇÃO,
AQUELE QUE VIVE, POIS VIVO
ETERNAMENTE, AMÉM, AMÉM!
EU SOU O REI DOS REIS,
SENHOR DOS CÉUS. 
EU SOU O SANTO, SANTO DEUS.
PODEROSO QUE ERA,
QUE É E SEMPRE SERÁ.
EU SOU, EU SOU, EU SOU O
QUE EU SOU, EU SOU!
');
