INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('34a6db4d-3c5d-40ea-8cf3-9d7537515848', 'Cristo é o Senhor', '056', 'Autor Desconhecido', 'Básico', 'C', 'Crianças e Adolescentes', 'CRISTO É O SENHOR, DONO DO MEU VIVER,
ELE ME SALVOU, COM SEU SANGUE ME LAVOU;
BREVE VOLTARÁ E AO CÉU ME LEVARÁ,
PRA SEMPRE COM ELE VOU ESTAR.
/INSTRUMENTOS

CRISTO É O SENHOR, DONO DO MEU VIVER,
ELE ME SALVOU, COM SEU SANGUE ME LAVOU;
BREVE VOLTARÁ E AO CÉU ME LEVARÁ,
PRA SEMPRE COM ELE VOU ESTAR.
/FINAL
PRA SEMPRE COM ELE VOU ESTAR.
');
