INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('34e32e24-cae4-42a9-8681-25d6c84eef58', 'Grande é o Senhor e Mui Digno de ser Louvado Sl 48', '654', 'Autor Desconhecido', 'Country', 'D', 'Salmos de Louvor', 'GRANDE É O SENHOR
E MUI DIGNO DE SER LOUVADO,
NA CIDADE DO NOSSO DEUS,
SEU SANTO MONTE,
BELO E SOBRANCEIRO,
É A ALEGRIA DE TODA A TERRA;

FINAL 2X
O MONTE DE SIÃO PARA OS LADOS
DO NORTE, A CIDADE DO GRANDE REI.
');
