INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('34f903e9-4254-4bbe-9e73-1189c34de1df', 'A minha herança é o Senhor', '174', 'Antônio Lopes da Silva,', 'Básico', 'A', 'Dedicação', 'CANTAR 2X
A MINHA HERANÇA É O SENHOR
(É O SENHOR)
NÃO TENHO OUTRO BEM MAIOR;
AINDA QUE ME OFEREÇAM.
TODA RIQUEZA DESTE MUNDO,
NÃO TROCAREI A MINHA HERANÇA,
POIS CUSTOU UM ALTO PREÇO
E ESTE PREÇO FOI O SANGUE DE JESUS.

FINAL 2X
E ESTE ALTO PREÇO
FOI O SANGUE DE JESUS.
');
