INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('352fb507-e1fa-42ab-8015-b57664a9f46a', 'A minha alegria', '183', 'Leonardo Jundi Eto', 'Básico', 'D', 'Dedicação', 'A MINHA ALEGRIA
É PERTENCER AO GRANDE SALVADOR;
SABER QUE MUITO EM BREVE O VEREI;
SABER QUE COM OS ANJOS EU O LOUVAREI.
A MINHA ALEGRIA É SABER QUE PARA SEMPRE
COM CRISTO VIVEREI.

*CORO
EXISTE UM LUGAR DE PAZ CELESTIAL
(CELESTIAL).
QUANDO OS MEUS PÉS ALI TOCAREM,
SEI QUE AS LUTAS VÃO CESSAR,
POIS ALI É LUGAR SANTO, MORADA DO SENHOR.
E AQUELE QUE VENCER DE JESUS IRÁ OUVIR:
"VINDE, BENDITOS DE MEU PAI".

A FORÇA PARA PROSSEGUIR
EU SEMPRE ENCONTRO QUANDO BUSCO A TI;
SABER QUE ESTÁS COMIGO A ME GUARDAR;
SABER QUE TUDO TU FARÁS PRA ME PRESERVAR.
A FORÇA PARA PROSSEGUIR 
É SABER QUE PARA SEMPRE CONTIGO VIVEREI.

*CORO 2X
EXISTE UM LUGAR DE PAZ CELESTIAL
(CELESTIAL).
QUANDO OS MEUS PÉS ALI TOCAREM,
SEI QUE AS LUTAS VÃO CESSAR,
POIS ALI É LUGAR SANTO, MORADA DO SENHOR.
E AQUELE QUE VENCER DE JESUS IRÁ OUVIR:
"VINDE, BENDITOS DE MEU PAI".
');
