INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('354f6685-1658-40a2-8b2b-7f7a2528f7a3', 'Os teus anjos te exaltam', '729', '', 'Novo', 'A', 'Grupo de Louvor', 'OS TEUS ANJOS TE EXALTAM, 
MEU SENHOR E REI,
COMO ALMEJO ESTAR NA TUA GLÓRIA.
DEIXAR ESTE MUNDO DE TREVAS, 
CHEIO DE TRIBULAÇÕES,
E SOMENTE TE LOUVAR, MEU SENHOR.

SENHOR, TU PASSASTE UM DIA POR AFLIÇÕES
E SABES QUE NÃO É FÁCIL VIVER AQUI.
MAS, COMO TU VENCESTE O MUNDO,
EU TAMBÉM POSSO VENCER,
POIS, NÃO HÁ NADA QUE SEJA 
IMPOSSÍVEL PARA TI.

SINTO-ME FELIZ QUANDO OUÇO TUA VOZ
A FALAR A MEU CORAÇÃO: 
"NÃO TARDAREI, EM BREVE VOLTAREI
(VOLTAREI)
PARA VOS LEVAR (SIM, VOLTAREI),
EM BREVE VOLTAREI."
/FINAL
E NÓS TE ESPERAMOS, SENHOR.
');
