INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('359d7041-2b1a-41c8-9ed9-7daa05d3d99e', 'No meu coração há um tesouro (Príncipe da Vida)', '037', 'E.H.M.R.', 'Marcha', 'Em', 'Crianças e Adolescentes', 'NO MEU CORAÇÃO HÁ UM TESOURO,
O MAIOR QUE POSSA EXISTIR;
A MELHOR COISA QUE FIZ FOI ENCONTRÁ-LO
POIS VIDA ETERNA ADQUIRI.

CANTAR 2X
PRINCIPE DA VIDA, PAI DA ETERNIDADE,
É O MEU TESOURO.
/FINAL
É O MEU JESUS.
');
