INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('35f2865e-7599-4394-83f5-0591ad36bbb6', 'Quando Davi ao Senhor orava', 19, 'C.M.V.C.S.', 'Fox Abafado', 'D', 'Crianças e Adolescentes', 'QUANDO DAVI AO SENHOR ORAVA,
PRA JERUSALÉM ESTAVA O SEU OLHAR,
PORQUE ELE SABIA QUE EM JERUSALÉM
O NOME DO SENHOR FIRMADO ESTÁ.

IGUAL A DAVI, TAMBÉM VOU ORAR
OLHANDO PRA JERUSALÉM CELESTIAL,
A CIDADE DE MEU REI E SENHOR,
QUE DO SEU TRONO IRÁ RESPONDER
À ORAÇÃO DE SEU SERVO FIEL.

CANTAR 2X
EU VOU ORAR, EU VOU ORAR,
PORQUE EU SEI QUE MEU SENHOR
VAI ME ESCUTAR.

QUANDO DAVI AO SENHOR ORAVA,
PRA JERUSALÉM ESTAVA O SEU OLHAR,
PORQUE ELE SABIA QUE EM JERUSALÉM
O NOME DO SENHOR FIRMADO ESTÁ.

IGUAL A DAVI, TAMBÉM VOU ORAR
OLHANDO PRA JERUSALÉM CELESTIAL,
A CIDADE DE MEU REI E SENHOR,
QUE DO SEU TRONO IRÁ RESPONDER
À ORAÇÃO DE SEU SERVO FIEL.

FINAL 2X
EU VOU ORAR, EU VOU ORAR,
PORQUE EU SEI QUE MEU SENHOR
VAI ME ESCUTAR.
');
