INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('363aab0d-e8b7-4bba-b6c5-14aff575e251', 'Amo ao meu Senhor', '167', 'Paulo Eduardo Rodrigues Mariano', 'Básico', 'A', 'Dedicação', 'AMO AO MEU SENHOR
PORQUE ELE OUVE A MINHA VOZ
E O MEU CLAMOR, REFÚGIO MEU;
NAS DIFICULDADES DESTA VIDA
SEI QUE ME OUVIRÁ;
O SENHOR ME GUARDARÁ.

PORQUE DA MORTE LIVRASTE A MINH''ALMA,
REFÚGIO EM TI ENCONTREI,
QUERO SEGUIR-TE, MEU SENHOR E REI, (2X)
/INSTRUMENTOS

QUERO OUVIR TUA VOZ, QUE É SOBERANA,
AUXILIANDO O MEU ANDAR,
PARA O ALVO ALCANÇAR;
MESMO QUE HAJA PROVAS E DIAS DIFÍCEIS,
Ó SENHOR, SEI QUE TU ME CONDUZIRÁS.

PORQUE DA MORTE LIVRASTE A MINH''ALMA, 
DANDO-ME ASSIM SALVAÇÃO
E BENDIREI TEU NOME SEMPRE, AMÉM, (2X)
');
