INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('366a3920-c23a-4aa5-be18-824fc67cc07e', 'Profundos Vales eu Terei de Passar', '308', 'Jackson de Halley Fernandes Fontes', 'Básico 2', 'D', 'Consolo e Encorajamento', 'PROFUNDOS VALES EU TEREI DE PASSAR
E MUITAS LUTAS EU TEREI DE VENCER,
MAS SEI QUE SÓ EU NÃO ESTOU,
COMIGO ESTÁS AO MEU REDOR,
A TUA GRAÇA ME SATISFAZ.

SE UM DIA, ACASO, TRISTE EU ME ENCONTRAR,
SE SOLITÁRIO NO DESERTO A CAMINHAR,
ENTÃO ALI ME FALARÁS
E A TUA MÃO ME ESTENDERÁS;
MOSTRAR-ME-ÁS A CELESTE MANSÃO.

A TUA GRAÇA ME SUSTERÁ,
POIS FRACO SOU,
SEM TI NÃO POSSO CAMINHAR;
/FINAL 2X
REVELA-ME O TEU AMOR,
COM TUA MÃO VEM ME GUIAR,
POIS JUNTO A TI SEMPRE QUERO ESTAR.
');
