INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('36a8cccc-3974-45f1-bfdc-d0c583255346', 'Entrega o Teu Caminho ao Senhor', '228', 'José Elias Simora', 'Básico', 'G', 'Morte, Ressureição e Salvação', 'ENTREGA O TEU CAMINHO AO SENHOR
E O MAIS ELE FARÁ;
FARÁ SOBRESSAIR A SUA JUSTIÇA 
COMO A LUZ E O SEU JUÍZO.
CUMPRIRÁ O TEU DESEJO,
ELE TE MOSTRARÁ O SEU PERDÃO, A SALVAÇÃO, 
A REVELAÇÃO DA PALAVRA DE JESUS
(EM TEU SER).

CANTAR 2X
ENTREGA O TEU CAMINHO AO SENHOR
E O MAIS ELE FARÁ;
/FARÁ SOBRESSAIR A SUA JUSTIÇA 
COMO A LUZ E O SEU JUÍZO,
O SEU PERDÃO, A SALVAÇÃO,
A REVELAÇÃO DA PALAVRA DE JESUS
(EM TEU SER).

FINAL
ENTREGA O TEU CAMINHO AO SENHOR.
(ENTREGA O TEU CAMINHO AO SENHOR)
AO SENHOR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('36a8cccc-3974-45f1-bfdc-d0c583255346', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
