INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('379c33b1-ff1d-48cf-b47a-13972b4bf122', 'Quando te prostrares', '004', 'Ronaldo Duarte Barroso', 'Básico 2', 'Em', 'Clamor', '(2X)
QUANDO TE PROSTRARES DIANTE DE DEUS
LEMBRA QUE JESUS ESTÁ CONTIGO.
PEDE SEU AUXÍLIO, PEDE SEU PERDÃO,
LEMBRA QUE JESUS É TEU ABRIGO.
DEIXA QUE O SENHOR
MUDE O TEU VIVER;
LEMBRA QUE JESUS É TEU AMIGO.
FINAL 2X
VENHA SOBRE NÓS, (Ó DEUS)
VENHA SOBRE NÓS,
SEJA SOBRE NÓS A TUA GRAÇA.
');
