INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('37ce34fa-02a6-453c-a7c8-d4580403f229', 'A Salvação', 99, 'Nicolas Louzada e Anandreia Simeões Louzada', 'Básico', 'Básico', 'Avulso', 'EU VIVIA NA ESCURIDÃO,
MAS JESUS UM DIA ME VIU;
ELE ME SALVOU E ME PERDOOU,
PARA SEMPRE EM MINHA VIDA
VOU LHE ADORAR.

CANTAR 2X
JESUS ME ACONSELHOU
A SEGUIR O SEU CAMINHO,
E NO CÉU UM DIA ESTAREI
/E NO LIVRO DA VIDA
O MEU NOME ENCONTRAREI.

A ALEGRIA NUNCA ACABARÁ,
POIS COM JESUS PRA SEMPRE EU VIVEREI.
EU ME LEMBRO QUANDO JESUS ME DISSE:
"FILHO MEU, NÃO ME ESQUECEREI DE TI,
ME ESCUTASTE E ME SEGUISTE
E EM TUA VIDA MILAGRES OPERAREI;
EU SOU TEU DEUS E TE DIGO:
NÃO TEMAS, TU ÉS MEU".

FINAL
ME ESCUTASTE E ME SEGUISTE
E EM TUA VIDA MILAGRES OPERAREI;
EU SOU TEU DEUS E TE DIGO:
NÃO TEMAS, TU ÉS MEU".
');
