INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('386a2abd-bb76-4ff5-a8dc-e67d73079897', 'Como Agradecer', '', '', '', '', '', 'COMO AGRADECER PELO BEM
QUE TENS FEITO A MIM?
QUE VEM DEMONSTRAR QUANTO
AMOR TU TENS, Ó DEUS, POR MIM.

AS VOZES DE MILHÕES DE ANJOS
NÃO PODERIAM EXPRESSAR
A GRATIDÃO DO MEU PEQUENO
SER, QUE SÓ PERTENCE A TI.

A DEUS DEMOS GLÓRIA (3X),
QUE POR NÓS TANTO FEZ.
FOI NA CRUZ QUE SALVOU-ME,
SEU PODER RESTAUROU-ME,
A DEUS DEMOS GLÓRIA,
QUE POR NÓS TANTO FEZ.

QUERO VIVER AQUI
PARA ADORAR-TE, MEU SENHOR,
E SE SURGIR UM LOUVOR,
AO CALVÁRIO SEJA SIM, SEJA SIM.

*FINAL
FOI NA CRUZ QUE SALVOU-ME,
SEU PODER RESTAUROU-ME,
A DEUS DEMOS GLÓRIA,
QUE POR NÓS TANTO FEZ.
');
