INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('393ecff2-3baf-4878-bd09-04dd69c03e44', 'Voltará', '', '', '', '', '', 'EMANUEL, SALVADOR, DEUS FORTE,
PRÍNCIPE DA PAZ É JESUS O NOSSO REI E SENHOR.
VOLTARÁ, PRA NOS LEVAR PARA UM LAR DE PAZ
E JUNTOS VAMOS COM OS ANJOS PRA SEMPRE
O ADORAR.

CORO
VOLTARÁ! EU SEI QUE CRISTO
VEM ME BUSCAR,
VOLTARÁ! SIM,
VOLTARÁ. MARANATA!
ORA VEM SENHOR JESUS!

EMANUEL, SALVADOR, DEUS FORTE,
PRÍNCIPE DA PAZ É JESUS O NOSSO REI E SENHOR.
VOLTARÁ, PRA NOS LEVAR PARA UM LAR DE PAZ
E JUNTOS VAMOS COM OS ANJOS PRA SEMPRE
O ADORAR.

HOMEM SE FEZ E SOBRE SI OS MEUS PECADOS,
CARREGOU, NAQUELA CRUZ PARA DAR-ME
LIBERTAÇÃO E SALVAÇÃO.
');
