INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3a3b346a-0e26-4792-b992-998fdd97de01', 'Ouvi o Salvador Dizer', '', '', '', '', '', 'OUVI O SALVADOR DIZER:
“VEM DESCANSAR EM MIM
E CONFIANTE RECEBER CONFORTO
E PAZ SEM FIM”.
FUI A JESUS E LHE ENTREGUEI
MEU TRISTE CORAÇÃO;
ABRIGO, PAZ E GOZO ACHEI;
ACHEI CONSALAÇÃO.

OUVI O SALVADOR DIZER:
“DE GRAÇA É O MEU AMOR
AS ÁGUAS VIVAS VEM BEBER,
DA VIDA A FONTE SOU”.
FUI A JESUS E ME PROSTEI
DA FONTE, ENFIM, BEBI
JAMAIS A SEDE SENTIREI,
ESTANDO SEMPRE ALI.

OUVI O SALVADOR DIZER:
“DO MUNDO EU SOU A LUZ;
OH! VEM A MIM, POIS SENTIRÁS
QUE TE AMO DESDE A CRUZ”.
FUI A JESUS E NELE ACHEI
O SOL QUE BRILHA EM MIM;
E NESSA LUZ EU ANDAREI
ATÉ DA VIDA O FIM.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('3a3b346a-0e26-4792-b992-998fdd97de01', '45ab58b2-d293-45c7-aa75-090fcd968b24');
