INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3aedf9d7-c293-4dfb-b26b-7b4e38866929', 'Chuvas de bençãos teremos', '456', 'Let: D. W. Whittle; Trad. Salomão Luiz Ginsburg; Música: James McGranaham', 'Balada', 'Bb', 'Santificação e Derramamento', 'CHUVAS DE BÊNÇÃOS TEREMOS;
É A PROMESSA DE DEUS.
TEMPOS BENDITOS TRAZENDO,
CHUVAS DE BÊNÇÃOS DOS CÉUS.

*CORO
CHUVAS DE BÊNÇÃOS,
CHUVAS DE BÊNÇÃOS DOS CÉUS;
GOTAS BENDITAS JÁ TEMOS,
CHUVAS ROGAMOS A DEUS.

CHUVAS DE BÊNÇÃOS TEREMOS;
DE VIDA PAZ E PERDÃO. 
OS PECADORES INDIGNOS
GRAÇA DOS CÉUS OBTERÃO.

*CORO
CHUVAS DE BÊNÇÃOS,
CHUVAS DE BÊNÇÃOS DOS CÉUS;
GOTAS BENDITAS JÁ TEMOS,
CHUVAS ROGAMOS A DEUS.

CHUVAS DE BÊNÇÃOS TEREMOS;
MANDA-NOS JÁ, Ó SENHOR!
DÁ-NOS O GOZO DOS FRUTOS
DOS TEUS ENSINOS DE AMOR.

*CORO
CHUVAS DE BÊNÇÃOS,
CHUVAS DE BÊNÇÃOS DOS CÉUS;
GOTAS BENDITAS JÁ TEMOS,
CHUVAS ROGAMOS A DEUS.
/FINAL
AMÉM!
');
