INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3b43dc07-2f55-4ac5-8699-39a9eacc2d03', 'Oh que precioso sangue', '030', 'Let: Henry Maxwel Wright; Mús. Ethelbert Willian Bullinger', 'Balada', 'G', 'Clamor', 'OH! QUE PRECIOSO SANGUE
O SENHOR VERTEU.
QUANDO PARA RESGATAR-NOS PADECEU!

OH! QUE PRECIOSO SANGUE,
SANGUE DE JESUS,
QUE POR NÓS FOI DERRAMADO 
SOBRE A CRUZ!

OH! QUE PRECIOSO SANGUE,
SACRIFICIAL,
POIS APAGA DE NOSSA ALMA 
TODO O MAL!

OH! QUE PRECIOSO SANGUE,
FALA-NOS DE PAZ,
TUDO QUANTO A LEI EXIGE SATISFAZ!
');
