INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3bcf41f7-076d-4db4-af08-34fa516f37dc', 'Para Quem Iremos Nós', '186', 'Josué Plantickow Sant’ana', 'Toada', 'Dm', 'Morte, Ressureição e Salvação', 'PARA QUEM IREMOS NÓS?
SÓ TU, SENHOR, TENS AS PALAVRAS
DE VIDA ETERNA.

CANTAR 2X
NÃO HÁ OUTRO AMOR MAIOR
QUE O TEU AMOR, JESUS,
DEMONSTRADO ALI NA CRUZ
/PARA NOS SALVAR.
/INSTRUMENTOS

MEU CORAÇÃO A TI ENTREGO,
A MINHA VIDA DEPOSITO EM TEU ALTAR.
/CANTAR 2X
TODA A MINHA ADORAÇÃO
QUERO TE OFERTAR,
EM SACRIFÍCIO (EM SACRIFÍCIO)
VIVO EM TEU ALTAR. (EM TEU ALTAR)

FINAL
EM SACRIFÍCIO (EM SACRIFÍCIO)
VIVO EM TEU ALTAR.
