INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3bf11d75-aad1-4b8f-b8fa-0b323d37c7d4', 'Lá do doce porvir', '213', 'Autor Desconhecido', 'Balada', 'A', 'Crianças e Adolescentes', 'LÁ NO DOCE PORVIR,
LÁ NO DOCE PORVIR,
MANSÃO DE LUZ IREI TER COM JESUS,
AH! QUE PRAZER ME ENCONTRAR ALI!

SIM, NO DOCE PORVIR,
SIM, NO DOCE PORVIR,
QUANDO A LUTA FINDAR
E A VITÓRIA ALCANÇAR,
SIM, NO DOCE PORVIR.
');
