INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3c146ff4-2d77-4f3c-8c0b-69dc4d48c0b1', 'Quero que Você Conheça', '262', 'Let. Antônio Carlos Rodrigues de Oliveira e Everaldo Cavalcante Lima; Mús. Everaldo Cavalcante Lima', 'Básico', 'G', 'Morte, Ressureição e Salvação', 'QUERO QUE VOCÊ CONHEÇA
(QUERO QUE VOCÊ CONHEÇA)
JESUS, O AUTOR DA NOSSA FÉ;
QUERO QUE VOCÊ CONHEÇA
(QUERO QUE VOCÊ CONHEÇA)
TODO O SEU AMOR QUE TEM.

CORO
ELE SALVA, ELE CURA,
ELE DÁ VIDA ETERNA,
E TUDO O QUE ELE FAZ É POR AMOR.
/CANTAR 2X
ABRE A BOCA DO MUDO,
DÁ VISTA AO CEGO,
DÁ PALAVRA AO UNGIDO.

OH! JESUS MARAVILHOSO,
(OH! JESUS MARAVILHOSO)
JESUS, O AUTOR DA NOSSA FÉ;
E TUDO QUE ELE FAZ É POR AMOR.

FINAL 3X
OH! JESUS MARAVILHOSO,
(OH! JESUS MARAVILHOSO)
JESUS, O AUTOR DA NOSSA FÉ.
');
