INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3c3adcdd-5181-4d65-9825-5080fa670bab', 'Sou um soldado do bom salvador', '138', 'S.G.D.', 'Fox', 'D', 'Crianças e Adolescentes', 'SOU UM SOLDADO 
DO BOM SALVADOR,
POR JESUS LUTANDO
COM FÉ E AMOR.

ESPADA SEGURANDO
BEM FIRME EM MINHA MÃO,
A JESUS SEGUINDO
O GRANDE CAPITÃO.

AO CÉU EU VOU MARCHANDO,
JESUS ME ESPERA LÁ,
PRA FRENTE EU VOU ANDANDO,
AO CÉU EU VOU CHEGAR.
/UM, DOIS, TRÊS, QUATRO.

SOU UM SOLDADO
DO BOM SALVADOR,
POR JESUS LUTANDO
COM FÉ E AMOR.
');
