INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3c578141-0988-4ea3-86e7-ce1701ce3b49', 'Há Momentos Que As Palavras Não Resolvem', '299', 'Autor Desconhecido', 'Repique', 'E', 'Consolo e Encorajamento', 'CANTAR 2X
HÁ MOMENTOS QUE AS PALAVRAS
NÃO RESOLVEM
MAS O GESTO DE JESUS, NA CRUZ,
DEMONSTRA AMOR POR NÓS.

CORO 2X
FOI NO CALVÁRIO,
QUE ELE SEM FALAR,
MOSTROU AO MUNDO INTEIRO 
O QUE É AMAR.

CANTAR 2X
AQUI NO MUNDO
AS DESILUSÕES SÃO TANTAS,
MAS EXISTE UMA ESPERANÇA:
QUE CRISTO VAI VOLTAR.
');
