INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3c68040f-b76a-4b92-911d-42584604aefe', 'Jesus Cristo voltará', '683', 'Jorgemar Souza Madeira', 'Básico', 'C', 'Grupo de Louvor', 'JESUS CRISTO VOLTARÁ PRA NOS LEVAR,
SUA IGREJA FIEL SUBIRÁ PRA GLÓRIA;
DEIXAREMOS ESTE MUNDO DE TRISTEZA,
PARA ESTAR COM NOSSO AMADO SALVADOR.

*CORO
LOUVAREMOS A JESUS, O REI,
CANTAREMOS UM HINO DE VITÓRIA,
COM OS ANJOS ESTAREMOS
NAS MAIS BELAS MANSÕES CELESTIAIS.

CANTAR 2X
ALELUIA, VAMOS TODOS ADORAR
A JESUS, O LEÃO DA TRIBO DE JUDÁ,
QUE FOI MORTO MAS RESSUSCITOU,
VAMOS CANTAR (VAMOS CANTAR)
ESSE GRANDE AMOR DO NOSSO SALVADOR.

*CORO 2X
LOUVAREMOS A JESUS, O REI,
CANTAREMOS UM HINO DE VITÓRIA,
COM OS ANJOS ESTAREMOS
NAS MAIS BELAS MANSÕES CELESTIAIS.
');
