INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3ceee6df-1f9d-41b7-b4b4-ca1140a0809a', 'Na hora em que eu quiser', '', '', '', '', '', 'EU, O SENHOR,
O SENHOR TEU DEUS
TE TOMO PELA TUA MÃO DIREITA.
TE TOMO PELA MÃO,
A TUA MÃO DIREITA
E TE DIGO: NÃO TEMAS.

*CORO
NÃO TEMAS, EU SOU CONTIGO
NÃO TE ASSOMBRES,
PORQUE EU SOU O TEU DEUS
EU TE ESFORÇO, EU TE AJUDO
EU TE SUSTENTO,
COM A DESTRA DA MINHA JUSTIÇA.
NÃO TEMAS, EU SOU CONTIGO
NÃO TE ASSOMBRES,
PORQUE SOU TEU DEUS.

EU, O SENHOR,
O SENHOR TEU DEUS
TE TOMO PELA TUA MÃO DIREITA.
TE TOMO PELA MÃO,
A TUA MÃO DIREITA
E TE DIGO: NÃO TEMAS.

*CORO
NÃO TEMAS, EU SOU CONTIGO
NÃO TE ASSOMBRES,
PORQUE EU SOU O TEU DEUS
EU TE ESFORÇO, EU TE AJUDO
EU TE SUSTENTO,
COM A DESTRA DA MINHA JUSTIÇA.
NÃO TEMAS, EU SOU CONTIGO
NÃO TE ASSOMBRES,
PORQUE SOU TEU DEUS.

FINAL
NÃO TEMAS, EU SOU CONTIGO
NÃO TE ASSOMBRES
PORQUE EU SOU TEU DEUS
');
