INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3d32aa4e-e41d-460a-a683-f8c0dfdf4fc8', 'Pai, estou a te clamar', '002', 'C.M.V.', 'Fox', 'G', 'Clamor', 'PAI, ESTOU A TE CLAMAR
PEDINDO PERDÃO, SOCORRO,
EU QUERO TE OUVIR.
PAI, ENSINA-ME A ADORAR
E A GLORIFICAR TEU NOME,
EU QUERO TE AMAR.
PAI, EU QUERO TE SERVIR
OH! DÁ-ME DA TUA GRAÇA
E ME BASTARÁ,
E ME BASTARÁ, E ME BASTARÁ!
');
