INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3d5e63d2-15dd-4857-8b52-b5bc3f9d3531', 'Não há Deus acima do Senhor', '361', 'Autor Desconhecido', 'Balada', 'E', 'Consolo e Encorajamento', 'NÃO HÁ DEUS ACIMA DO SENHOR,
NÃO HÁ ROCHA COMO NOSSO DEUS;
/CANTAR 2X
É FORÇA E PROTEÇÃO,
ELE É A TORRE DE LIBERTAÇÃO
AOS QUE CONFIAM NO SENHOR.

NÃO HÁ DEUS ACIMA DO SENHOR,
NÃO HÁ ROCHA COMO NOSSO DEUS;
ME TREINA PRA LUTAR,
ME MOSTRA ONDE DEVO EU ANDAR,
GLÓRIA AO NOME DE JESUS.

ME TREINA PRA LUTAR,
ME MOSTRA ONDE DEVO EU ANDAR,
GLÓRIA AO NOME DE JESUS.
/FINAL
GLÓRIA AO NOME DE JESUS.
