INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3d6e3720-ea18-454b-b879-ec90db9ef0ab', 'No Trono Da Cidade de Deus', '520', 'José Elias Simora', 'Balada', 'A', 'Volta de Jesus e Eternidade', 'NO TRONO DA CIDADE DE DEUS, JERUSALÉM,
OS ANJOS CANTAM ALELUIA,
LOUVANDO A JESUS, REI DOS REIS,
O SALVADOR, O LEÃO DE JUDÁ.

*CORO
GLÓRIA AO QUE VENCEU
E VIVO ESTÁ ENTRE NÓS,
GLÓRIA, MILHARES DE VOZES NO CÉU
PROCLAMAM EM UMA SÓ VOZ:
SANTO, SANTO.
/INSTRUMENTOS

EM BREVE O MEU JESUS VOLTARÁ
PARA LEVAR A IGREJA FIEL
E TODOS JUNTOS NA ETERNIDADE,
COM O SALVADOR NA ETERNA SIÃO!

*CORO
GLÓRIA AO QUE VENCEU
E VIVO ESTÁ ENTRE NÓS,
GLÓRIA, MILHARES DE VOZES NO CÉU
PROCLAMAM EM UMA SÓ VOZ:
SANTO, SANTO.
/FINAL
(SANTO), SANTO, SANTO, (SANTO),
SANTO, SANTO.
');
