INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3dc59bee-e62b-4538-afdb-e7fd7ca3b4f2', 'Como Noé', '153', 'C.M.V.C.S.', 'Fox', 'E', 'Crianças e Adolescentes', 'COMO NOÉ, QUERO OBEDECER
A DOCE VOZ DE DEUS,
A ARCA VOU FAZER;
COMO NOÉ NA ARCA VOU ENTRAR
E SALVAÇÃO VOU ALCANÇAR.

PELA FÉ NOÉ EM TUDO OBEDECEU,
SEGUINDO O PROJETO,
NADA ELE TEMEU.
HERDEIRO COM JESUS
DEUS ASSIM O FEZ,
POIS A SALVAÇÃO É PRA TODO O QUE CRÊ.

COMO NOÉ, QUERO OBEDECER
A DOCE VOZ DE DEUS
A ARCA VOU FAZER.
/FINAL 2X
COMO NOÉ NA ARCA VOU ENTRAR.
E SALVAÇÃO VOU ALCANÇAR.
');
