INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3ec970c8-b949-4dcc-baa7-80f35699800b', 'Mais Perto de Jesus', '152', 'Let. W.C.Martin; Trad. Samuel Nyström; Mús.C. Austin Miles', 'Fox Abafado', 'G', 'Dedicação', 'MAIS PERTO DE JESUS PROCURO SEMPRE EU CHEGAR,
MAIS BELO DO QUE O OURO DO SOL NADO É A TI MIRAR;
EM PENSAMENTOS, SONHOS,
TANTA GLÓRIA NUNCA VI!
POIS ELE É MAIS BELO DO QUE EU JAMAIS PREVI!

CORO
NÃO POSSO EXPLICAR QUÃO MEIGO ÉS, JESUS;
MAS FACE A FACE NO TEU LAR
EU TE VEREI, JESUS!

A ESTRELA RESPLANDENTE DA MANHÃ É MINHA LUZ,
O LÍRIO DOS VALES É O BOM SENHOR JESUS;
SUAVE E DOCE É O CHEIRO QUE SÓ VEM DE SI,
POIS ELE É MAIS BELO DO QUE EU JAMAIS PREVI!

SE MÁGOAS VÊM ME PERTURBAR, O BÁLSAMO ELE TEM,
ME TOMA NOS SEUS BRAÇOS E ASSIM DESCANSO BEM;
NA CRUZ LEVOU JESUS O MEU PECADO SOBRE SI,
POIS ELE É MAIS BELO DO QUE EU JAMAIS PREVI!
');
