INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('3fdd8622-efe1-4216-aaeb-9672d7467b3f', 'As Lágrimas Falam, Jesus Te Escuta', '366', 'Jorgemar Souza Madeira', 'Novo', 'D', 'Consolo e Encorajamento', 'AS LÁGRIMAS FALAM, JESUS TE ESCUTA
AS LÁGRIMAS FALAM PRA JESUS A TUA DOR
"BEM-AVENTURADO É O HOMEM QUE CHORA,
SERÁ CONSOLADO", POIS ASSIM DIZ O SENHOR.

DOBRA OS TEUS JOELHOS PERANTE O ALTAR DO SENHOR
E A VITÓRIA VIRÁ.
ENTREGA TUA ALMA, CONFIA EM CRISTO JESUS
E AS TUAS LÁGRIMAS JESUS ENXUGARÁ.
/INSTRUMENTOS

AS LÁGRIMAS FALAM, JESUS TE ESCUTA
