INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('401dc10b-5e8e-4aa5-8824-edebfeb1a082', 'Sonda-me, ó Deus', '', '', '', '', '', 'SENHOR, EU SEI QUE TU ME SONDAS,
SEI TAMBÉM QUE ME CONHECES
SE ME ACENTO OU ME LEVANTO
CONHECES MEUS PENSAMENTOS.
QUER DEITADO OU QUER ANDANDO
SABES TODOS OS MEUS PASSOS.

E ANTES QUE HAJA EM MIM
PALAVRAS, SEI QUE EM TUDO ME CONHECES.
SENHOR EU SEI QUE TU ME SONDAS (4X)
/DEUS TU ME CERCASTE EM VOLTA,
TUAS MÃOS EM MIM REPOUSAM.
TAL CIÊNCIA É GRANDIOSA
NÃO ALCANÇO DE TÃO ALTA.

SE EU SUBIR ATÉ O CÉU,
SEI QUE ALI TAMBÉM TE ENCONTRO.
SE NO ABISMO ESTÁ MINH´ALMA
SEI QUE AÍ TAMBÉM ME AMAS.
SENHOR EU SEI QUE TU ME SONDAS. (4X)
');
