INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4028a53e-2084-4cd7-9556-1f04496f2e19', 'Quando As Lutas Me Cercam', '363', 'Eliana Aguiar Maia Simião', 'Básico', 'Cm', 'Consolo e Encorajamento', 'QUANDO AS LUTAS ME CERCAM,
ME ENTRISTECEM E ME FAZEM CHORAR,
EU CORRO PARA O TEU ALTAR.

*CORO 2X
DE JOELHOS COMEÇO A ORAR
SINTO A MÃO DE JESUS ME TOCAR.
/INSTRUMENTOS

O RENOVO ASSIM VEM,
TEU ESPÍRITO A ME CONSOLAR.
DE ALEGRIA, QUERO TE LOUVAR.

*CORO 2X
DE JOELHOS COMEÇO A ORAR
SINTO A MÃO DE JESUS ME TOCAR.
/FINAL
DE ALEGRIA, QUERO TE LOUVAR.
');
