INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('404a3d68-7066-48c8-8e63-66ca36804ecc', 'Ó Senhor, Deus de Israel', '', '', '', '', '', 'QUANDO ISRAEL SAIU DO EGITO,
ISRAEL CANTOU, CANTOU:
O SENHOR É A MINHA FORÇA.
ELE ME FOI POR SALVAÇÃO,
ESTE É O MEU DEUS,
LHE FAREI UMA HABITAÇÃO.

*CORO
AO SENHOR TAMBÉM LOUVAREI
PORQUE É A MINHA SALVAÇÃO,
MEU REFÚGIO, MINHA FORTALEZA,
LHE FAREI UMA HABITAÇÃO
NO MEU CORAÇÃO.
/INSTRUMENTOS

QUANDO ISRAEL SAIU DO EGITO,
ISRAEL CANTOU, CANTOU:
O SENHOR É A MINHA FORÇA.

ELE ME FOI POR SALVAÇÃO,
ESTE É O MEU DEUS,
LHE FAREI UMA HABITAÇÃO.

*CORO
AO SENHOR TAMBÉM LOUVAREI
PORQUE É A MINHA SALVAÇÃO,
MEU REFÚGIO, MINHA FORTALEZA,
LHE FAREI UMA HABITAÇÃO
NO MEU CORAÇÃO.

QUANDO ISRAEL SAIU DO EGITO,
ISRAEL CANTOU, CANTOU:
O SENHOR É A MINHA FORÇA.
');
