INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('40952ea7-446c-474d-b5f9-090596deecf4', 'Esta obra é de Deus', '476', 'J.J.M', 'Marcha', 'Dm', 'Santificação e Derramamento do Espírito Santo', 'CANTAR 2X
ESTA OBRA É DE DEUS, 
NINGUÉM A PODE IMPEDIR, 
FOI JESUS QUEM CONVOCOU 
ESTÁ NA HORA DE AGIR.

VAMOS TODOS! VAMOS TODOS!
TRABALHAR PARA A GLÓRIA DE JESUS.
ALELUIA! ALELUIA!
LOUVANDO AQUELE QUE POR NÓS
MORREU NA CRUZ, GLÓRIA A JESUS!
ALELUIA! ALELUIA!
GLORIFICADO SEJA O NOME DO SENHOR.

FINAL 2X
VIVO CONTENTE, VIVO ALEGRE, 
PORQUE JESUS JÁ ME LIBERTOU.
');
