INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('40ed3a53-8305-4676-ad4d-cf04c7250c02', 'Nem sempre entendemos', '298', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'D', 'Consolo e Encorajamento', 'NEM SEMPRE ENTENDEMOS
POR QUE DEUS AGE ASSIM,
O ESPINHO QUE A BELA ROSA TEM;
MAS PELA FÉ SABEMOS QUE TUDO QUE ELE FAZ
É SEMPRE, SEMPRE PARA O NOSSO BEM.

*CORO
NADA ME SEPARA DESSE AMOR,
SEMPRE CONFIAREI NO MEU SENHOR;
SEI QUE CUIDARÁ DE MIM,
COM DESVELO ATÉ O FIM,
NADA ME SEPARARÁ DO AMOR DE DEUS.

A DOR E O SOFRIMENTO, A MORTE TÃO CRUEL,
VENCEU NA CRUZ O NOSSO EMANUEL;
DE CINZAS AS VESTES TROCA
POR VESTES DE LOUVOR
E ÓLEO DE ALEGRIA DÁ-NOS O SENHOR.

*CORO
NADA ME SEPARA DESSE AMOR,
SEMPRE CONFIAREI NO MEU SENHOR;
SEI QUE CUIDARÁ DE MIM,
COM DESVELO ATÉ O FIM,
NADA ME SEPARARÁ DO AMOR DE DEUS. (2X)
');
