INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4182e7dc-1e8e-49d3-bfad-b0f4cb148776', 'Espírito Santo, ó consolador', '441', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'D', 'Santificação e Derramamento', 'CANTAR 2X
ESPÍRITO SANTO, Ó CONSOLADOR,
VISITA O TEU POVO COM GRAÇA E AMOR;
Ó VENTO QUE SOPRAS
NOS JARDINS DE DEUS,
DERRAMA PODER,
ESPALHA ENTRE NÓS O AROMA DOS CÉUS!
/FINAL
DERRAMA PODER, ESPALHA ENTRE NÓS
O AROMA DOS CÉUS!
');
