INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('41f7cfd3-398a-4b02-9a53-a5300bd91856', 'Toca Em Mim, Senhor', '', '', '', '', '', 'TOCA EM MIM SENHOR
TOCA EM MIM AGORA
PRECISO DE TI, NÃO POSSO FICAR
SEM TUAS MÃOS SOBRE MIM.

TOCA EM MIM MEU SENHOR,
PRECISO TANTO DE TI
SEI QUE O MOMENTO É DIFÍCIL,
MAS COM JESUS VOU VENCER.

SEI QUE COMIGO ESTÁS,
POR ISSO NÃO TEMEREI
POIS COM JESUS AO MEU LADO
SEI QUE ENTÃO VENCEREI.

*CORO 2X
JESUS COMIGO ESTÁ
POR ISSO VENCEREI
ELE É A MINHA VITÓRIA
JESUS É O MEU REI.

TOCA EM MIM SENHOR
TOCA EM MIM AGORA
PRECISO DE TI, NÃO POSSO FICAR
SEM TUAS MÃOS SOBRE MIM.

TOCA EM MIM MEU SENHOR,
PRECISO TANTO DE TI
SEI QUE O MOMENTO É DIFÍCIL,
MAS COM JESUS VOU VENCER.

SEI QUE COMIGO ESTÁS,
POR ISSO NÃO TEMEREI
POIS COM JESUS AO MEU LADO
SEI QUE ENTÃO VENCEREI.

*CORO 2X
JESUS COMIGO ESTÁ
POR ISSO VENCEREI
ELE É A MINHA VITÓRIA
JESUS É O MEU REI.
/FINAL
E ENTÃO VENCEREI.
');
