INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('42280518-fb32-4a51-9a15-364f6a83b8c7', 'Canta, alegremente, ó filha de Sião', '109', 'S.G.D.', 'Country', 'E', 'Crianças e Adolescentes', 'CANTA ALEGREMENTE,
Ó FILHA DE SIÃO;
REJUBILA, Ó ISRAEL;
REGOZIJA-TE E EXULTA
DE TODO O CORAÇÃO,
Ó FILHA DE JERUSALÉM.

O SENHOR AFASTOU OS TEUS JUÍZOS,
EXTERMINOU O TEU INIMIGO;
O SENHOR, O REI DE ISRAEL,
ESTÁ NO MEIO DE TI;
TU NÃO VERÁS MAIS MAL ALGUM.

NAQUELE DIA SE DIRÁ A JERUSALÉM;
NÃO TEMAS, Ó SIÃO,
NÃO ENFRAQUEÇAM AS TUAS MÃOS.

O SENHOR TEU DEUS ESTÁ NO MEIO DE TI,
PODEROSO PARA TE SALVAR;
SE DELEITARÁ EM TI COM ALEGRIA;
CALAR-SE-Á POR SEU AMOR,
REGOZIJAR-SE-Á EM TI COM JÚBILO
Ó FILHA DE JERUSALÉM. (2X)
');
