INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('42663e2f-30e3-46b0-8b04-19fb71de83c9', 'Sobre as ondas', '116', 'M.L.M.B.O.', 'Fox', 'G', 'Crianças e Adolescentes', 'SOBRE AS ONDAS PODEREI ANDAR.
JESUS ESTÁ COMIGO,
NENHUM MAL ME ATINGIRÁ.
SOPRA O VENTO, DEIXA-O SOPRAR.
JESUS ACALMA AS ONDAS
E A PAZ VOLTA A REINAR.

AS ONDAS VÃO SUBINDO,
FORMANDO UM MONTÃO,
ESTE MUNDO MAL QUER
NAUFRAGAR MEU CORAÇÃO.
MAS NÃO TEMO, OLHO PRA JESUS.
/AO SOM DA SUA VOZ ATÉ AS TREVAS VIRAM LUZ. (2X)
');
