INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('429d9fa9-0958-4b12-8ccf-a31df9e67f13', 'Louvarei ao meu Senhor', '603', 'Jorgemar Souza Madeira', 'Básico', 'A', 'Louvor', 'LOUVAREI AO MEU SENHOR ENQUANTO EU VIVER,
SEU LOUVOR PRA SEMPRE ESTARÁ COMIGO;
SUA GRAÇA ME SUSTÉM,
SEU AMOR É TÃO PROFUNDO,
SEU ESPÍRITO ME DÁ FORÇAS PRA LUTAR.

*CORO 2X
SIM, LOUVAREI AO MEU SENHOR,
POIS É DIGNO DE LOUVOR,
SUA GRAÇA ME SUSTÉM,
LOUVAREI PRA SEMPRE, AMÉM.

LOUVAREI AO MEU SENHOR,
SUA GRAÇA ME SALVOU (SIM, LOUVAREI),
PÔS UM NOVO CÂNTICO EM MEUS LÁBIOS 
(SIM, LOUVAREI),
SUA GRAÇA ME SUSTÉM,
SEU AMOR É TÃO PROFUNDO (SIM, LOUVAREI),
SEU ESPÍRITO ME DÁ FORÇAS PRA LUTAR.

*CORO 2X
SIM, LOUVAREI AO MEU SENHOR,
POIS É DIGNO DE LOUVOR,
SUA GRAÇA ME SUSTÉM,
LOUVAREI PRA SEMPRE, AMÉM.
/FINAL
SIM, LOUVAREI.
');
