INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('42fde804-8625-4966-9f2f-541cf308a289', 'Na Hora em que eu quiser Falar com Deus', '049', 'Adriano de Souza Andrade', 'Básico', 'A', 'Clamor', 'NA HORA EM QUE EU
