INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4366d1f8-cf08-45d2-9dbb-8e69d5e1d2c9', 'Está chegando a hora', '', '', 'Valsa', 'E', '', 'ESTÁ CHEGANDO A HORA, O TREM JÁ VAI PARTIR
LEVANDO OS CORDEIRINHOS QUE VÃO AO CÉU SUBIR.
INSTRUMENTOS

JESUS ESTÁ CHAMANDO, A TODOS CONVIDANDO:
"VENHAM SEM DEMORA PRA NOVA JERUSÁLEM".
INSTRUMENTOS

VOCÊ, Ó PEQUENINO, POR QUE NÃO VEM TAMBÉM?
RECEBA O SEU BILHETE E ENTRE NESSE TREM.
INSTRUMENTOS
FINAL
E ALI JUNTOS ESTAREMOS NA CELESTIAL CIDADE,
COM CRISTO ANDAREMOS, SERÁ SÓ FELICIDADE.
INSTRUMENTOS
');
