INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('43db84c0-c3e5-48cb-bb39-b7170e338658', 'Jesus, agora eu bem sei', '144', 'Let.: Ethelbert William Bullinger; Trad. Joseph Jones; Mús.: James McGranahan', 'Básico', 'E', 'Dedicação', 'JESUS, AGORA EU BEM SEI
QUÃO GRANDE É TEU AMOR,
POIS SALVAÇÃO EM TI ACHEI,
A CRISTO DOU LOUVOR.

CORO
É CRISTO, SÓ, MEU SALVADOR,
POR ELE EU TENHO PAZ;
JESUS, A TI LOUVOR DAREI,
POIS TUDO TU ME DÁS.

DESCANSO NUNCA CONHECI,
INÚTIL SEMPRE SOU;
MAS CRISTO SE LEMBROU DE MIM,
SUA GRAÇA ME CHAMOU.

COMIGO, CRENTES, EXALTAI
O GRANDE SALVADOR,
POIS TUDO CRISTO ME SUPRIU
EMBORA PECADOR.

LOUVOR, LOUVOR A TI DAREI,
Ó CRISTO, MEU SENHOR!
PROFETA, SACERDOTE, REI,
DO MUNDO, O SALVADOR.
');
