INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4447db11-e5c7-46be-9dd7-ea4553142a80', 'Eu Quero Sentir', '', '', '', '', '', 'SENHOR, EU QUERO DEPOSITAR
A MINHA VIDA NO TEU ALTAR;
SENHOR, DE MIM NÃO TENHO NADA
MAS TU TENS TUDO PARA ME DAR.

SENHOR, EU QUERO TE ADORAR,
O MEU LOUVOR TE DAR;
SENHOR, DE MIM NÃO TENHO NADA
/FINAL 2X
MAS TU TENS TUDO
PARA ME DAR.
');
