INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('448c7d76-abe3-4d7b-825d-160f5e255fb1', 'O que os olhos nunca viram', '290', 'M.F.G.C.F', 'Básico', 'G', 'Morte, Ressurreição e Salvação', 'O QUE OS OLHOS NUNCA VIRAM,
E O CORAÇÃO NUNCA SENTIU,
DEUS PREPAROU EM SEU FAVOR,
PARA O ABENÇOAR
ABRA SEU CORAÇÃO E DEIXE QUE A LUZ,
VENHA BRILHAR EM SEU VIVER, 
ETERNAMENTE.

*CORO
ENTÃO COMECE A GLORIFICAR
PELO QUE AINDA NÃO VIU.
SE DEUS PROMETEU, VAI SE CUMPRIR
SUA BÊNÇÃO VAI CHEGAR.
/ABRA SEU CORAÇÃO 
E DEIXE QUE A LUZ,
VENHA BRILHAR EM SEU VIVER, 
ETERNAMENTE

*CORO 2X
ENTÃO COMECE A GLORIFICAR
PELO QUE AINDA NÃO VIU.
SE DEUS PROMETEU, VAI SE CUMPRIR
SUA BÊNÇÃO VAI CHEGAR.

CANTAR 2X
DEUS TEM SEMPRE O MELHOR, 
MESMO QUE A LUZ 
NÃO BRILHE EM SEUS OLHOS. 
VÊ, DEUS AMA VOCÊ! 
JÁ DECRETOU A SUA VITÓRIA. 
/FINAL
BASTA CRER, BASTA CRER.
');
