INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('452af7ce-0aef-48d6-9613-b809d4855635', 'Totalmente desejável é o meu amado', '156', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'D', 'Dedicação', 'TOTALMENTE DESEJÁVEL É O MEU AMADO,
PRECIOSO PARA MIM ELE É;
O SEU FALAR É MUITÍSSIMO SUAVE,
ASSIM ELE É, JESUS, O AMADO SALVADOR.

FINAL 2X
TODO O SEU SER É DELEITÁVEL À MINH''ALMA,
DELE QUERO SEMPRE MAIS CONHECER;
NÃO HÁ PRAZER MAIS REAL
QUE SUA PRESENÇA,
TOTALMENTE DESEJÁVEL É JESUS.
');
