INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('456caed1-19c7-46bd-9b19-0cf89ef4d386', 'Minhalma Cantará O Senhor é o meu pastor', '648', 'M.S.A', 'Básico', 'A', 'Louvor', '(M) O SENHOR É O MEU PASTOR 
(M) E NADA ME FALTARÁ,  
(H) O DESERTO OU O VALE 
(H) ELE OS TRANSFORMARÁ, 
EM MANANCIAIS DE ÁGUAS,
MINHA VIDA FARTARÁ.

CORO 2X
MINH’ALMA CANTARÁ,
E ANUNCIARÁ O TEU LOUVOR,
SENHOR, MEU REI!

DAVI OROU, LUTOU, SALMODIOU, VENCEU.
SENHOR, MEU DEUS, ESTOU AQUI
PARA TE HONRAR.

JESUS, FILHO DE DEUS, 
O NOSSO BOM PASTOR,
NOS RESGATOU PARA HERDARMOS 
A GLÓRIA ETERNA

FINAL
O TEU LOUVOR, SENHOR, 
MEU REI!
');
