INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4585f426-16a6-4660-869a-9010847eed76', 'Eis que estou a porta e bato', '560', 'Olcimar Rubens de Carvalho', 'Básico', 'D', 'Grupo de Louvor', 'EIS QUE ESTOU À PORTA E BATO,
SE ABRIRES ENTRAREI E CONTIGO VIVEREI,
ABRE A PORTA DO TEU CORAÇÃO.

O MEU NOME É JESUS,
O AUTOR DA PRÓPRIA VIDA,
SOU O TEU LIBERTADOR,
O CORDEIRO QUE RESSUSCITOU.

EIS QUE VENHO SOBRE AS NUVENS,
EIS QUE VENHO VENCEDOR;
NADA MAIS ME DETERÁ,
O MEU POVO VOU ARREBATAR,
A TROMBETA BREVE SOARÁ;

TUDO NOVO SE FARÁ
NO MEU REINO DE JUSTIÇA E PAZ,
MARANATA, JESUS VEM!
/INSTRUMENTOS

ESTE DIA ESTÁ CHEGANDO,
A FIGUEIRA JÁ BROTOU E A IGREJA FIEL
ORA E VIGIA SEM CESSAR.

O MEU NOME É JESUS,
SOU A FONTE DE ÁGUA VIVA,
QUEM TEM SEDE VEM A MIM,
VEM BEBER DE GRAÇA DESTA ÁGUA.
/EIS QUE VENHO SOBRE AS NUVENS,
EIS QUE VENHO VENCEDOR;

CANTAR 2X
NADA MAIS ME DETERÁ
O MEU POVO VOU ARREBATAR,
A TROMBETA BREVE SOARÁ;
TUDO NOVO SE FARÁ 
NO MEU REINO DE JUSTIÇA E PAZ,
MARANATA, JESUS VEM!
/FINAL
(MARANATA, JESUS!)
MARANATA, JESUS VEM!
');
