INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('465a10cd-b51d-4235-b892-ca149e6ca34c', 'O Sangue do Cordeiro de Deus', '053', 'Olcimar Rubens de Carvalho', 'Básico', 'C', 'Clamor', 'O SANGUE DO CORDEIRO DE DEUS
FOI VERTIDO ALI NA CRUZ,
NOS TRAZENDO REDENÇÃO
E COMUNHÃO COM DEUS.

*CORO
PURIFICA-NOS, SENHOR,
SANTIFICA-NOS PELO SANGUE REMIDOR, 
SÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,
POIS COM FÉ NÓS CLAMAMOS.
/INSTRUMENTOS

O SUMO SACERDOTE, JESUS,
FOI PERFEITO NO SEU GESTO
E PAGOU COM O SEU SANGUE 
A NOSSA SALVAÇÃO.

*CORO
PURIFICA-NOS, SENHOR,
SANTIFICA-NOS PELO SANGUE REMIDOR, 
SÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,
POIS COM FÉ NÓS CLAMAMOS.

FINAL
PURIFICA-NOS, SENHOR,
SANTIFICA-NOS PELO SANGUE REMIDOR, 
SÊ PROPÍCIO, Ó, VEM PERDOAR-NOS,
POIS COM FÉ (POIS COM FÉ)
NÓS CLAMAMOS. (NÓS CLAMAMOS)
POIS COM FÉ (POIS COM FÉ)
NÓS CLAMAMOS.
');
