INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('46d430fd-d562-4abb-8ddf-644d447a0acd', 'Um dia Eu Quis te Deixar', '286', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'E', 'Grupo de Louvor', 'UM DIA EU QUIS TE DEIXAR,
PARTIR E SER LIVRE PARA VIVER;
ABANDONEI-TE, TÃO CEGO NÃO VI
COMO ENTÃO FERI TEU CORAÇÃO DE PAI.

BEM CEDO TUDO PERDI,
A SOLIDÃO TOMOU CONTA DE MIM;
ENTÃO LEMBREI-ME DA CASA DO PAI
E CONTRITO VIM, VOLTANDO PARA TI.

*CORO
VOLTEI, MEU PAI,
AO TEU AMOR INCONDICIONAL!
ÉS MINHA HERANÇA,
CONTIGO SOU TÃO FELIZ, MEU DEUS!

DE LONGE VISTE CHEGAR
E ME ABRAÇASTE COM TANTO AMOR,
E HOUVE CÂNTICOS, FESTA NOS CÉUS,
POIS VOLTOU À CASA UM POBRE PECADOR!

*CORO
VOLTEI, MEU PAI,
AO TEU AMOR INCONDICIONAL!
ÉS MINHA HERANÇA,
CONTIGO SOU TÃO FELIZ, MEU DEUS!
/FINAL
TÃO FELIZ!
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('46d430fd-d562-4abb-8ddf-644d447a0acd', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
