INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('46f63c2e-a6ff-40c4-bf48-24a0a5e03a7f', 'Ó Jesus, exaltar-te-ei', '587', 'Gérson Beluci Miguel', 'Básico', 'Dm', 'Louvor', 'Ó JESUS, EXALTAR-TE-EI! (2X)
/A MINH''ALMA TE ENALTECE,
A MINH''ALMA E TODO O MEU SER
TE GLORIFICAM.

Ó JESUS, EXALTAR-TE-EI! (2X)
/CANTAR 2X
A MINH''ALMA TE ENALTECE,
A MINH''ALMA E TODO O MEU SER
TE GLORIFICAM.
');
