INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('46f917cb-ba49-4ada-928e-1094b0a2f7ea', 'Senhor ouve a minha oração', '023', 'Jorgemar Souza Madeira', 'Básico 2', 'C', 'Clamor', 'SENHOR, OUVE A MINHA ORAÇÃO
E DÁ-ME PLENA COMUNHÃO,
LIBERTA DO MEU VIL PECADO;
SENHOR, OUVE A MINHA ORAÇÃO.

TRANSBORDA, INUNDA O MEU SER,
TRANSFORMA, FAZE EM MIM TEU QUERER,
DERRAMA DO SANGUE DE CRISTO;
SENHOR, OUVE A MINHA ORAÇÃO.
');
