INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('479e38d1-19ec-4b59-aec8-c1b94dcac89a', 'Senhor, guia-nos', '447', 'Let. e Mús. Bill Mastrototaro; Trad.: Luiz Fernando de Amorim Coelho e Rogério Galuban', 'Toada', 'E', 'Santificação e Derramamento', 'SENHOR, GUIA-NOS
À TUA PRESENÇA ONDE O TEU SANGUE PURIFICA;
FAZE-NOS UM, UM SÓ CORPO, 
UMA SÓ MENTE, UM CORAÇÃO.

*CORO
SOMOS TEUS, REUNIDOS,
PRA LOUVAR TEU SANTO NOME,
ADORAMOS SÓ A TI;
GUIA-NOS À TUA GLÓRIA, 
TEU ESPÍRITO DERRAMADO REVELANDO O TEU QUERER;
GUIA-NOS À TUA GLÓRIA, 
NÃO HÁ NADA MAIS PRECIOSO,
NADA QUE QUEIRAMOS MAIS, GUIA-NOS.

JÁ SOMOS UM, 
UM SÓ CORPO, UMA SÓ MENTE, UM CORAÇÃO;
PRA TE OFERTAR
TÃO-SOMENTE NOSSO AMOR E GRATIDÃO.

*CORO
SOMOS TEUS, REUNIDOS,
PRA LOUVAR TEU SANTO NOME,
ADORAMOS SÓ A TI;
GUIA-NOS À TUA GLÓRIA, 
TEU ESPÍRITO DERRAMADO REVELANDO O TEU QUERER;
GUIA-NOS À TUA GLÓRIA,
NÃO HÁ NADA MAIS PRECIOSO,
NADA QUE QUEIRAMOS MAIS, GUIA-NOS.
/FINAL
GUIA-NOS.
');
