INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('47f80b90-00a7-4ead-b75a-6f6421d0ebdc', 'Sou o santo', '171', 'N.R.R.A.', 'Básico', 'G', 'Crianças e Adolescentes', 'CANTAR 2X
SOU O SANTO, O VERDADEIRO,
TENHO A CHAVE DE DAVI;
A PORTA ABERTA ESTÁ,
PRA QUE POSSAS ME ADORAR!

GUARDASTE AS MINHAS PALAVRAS,
NÃO NEGASTE O MEU NOME;
TAMBÉM EU TE GUARDAREI,
EIS QUE VENHO SEM DEMORA.

FINAL 2X
ENTÃO, GUARDA O QUE TENS,
PARA QUE NINGUÉM
TOME A TUA COROA.
');
