INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4857aa9e-3d09-4ff1-a7a7-a5ac06e7cd4d', 'O céu é um lugar maravilhoso', '762', '', 'Fox', 'E', 'Corinhos', 'O CÉU É UM LUGAR MARAVILHOSO,
CHEIO DE GLÓRIA E GOZO!
EU QUERO VER MEU SALVADOR:
O CÉU É UM LUGAR MARAVILHOSO.

O CÉU É UM LUGAR MARAVILHOSO,
CHEIO DE GLÓRIA E GOZO!
EU QUERO VER MEU SALVADOR:
O CÉU É UM LUGAR, LUGAR PRA ONDE VOU;
O CÉU É UM LUGAR MARAVILHOSO.
');
