INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('485acaa5-154f-4b58-997d-230de261135c', 'Maravilha é o amor de Deus', '067', 'E.H.M.R.', 'Fox', 'G', 'Crianças e Adolescentes', 'MARAVILHA, MARAVILHA,
MARAVILHA É O AMOR DE DEUS
REVELADO NO CALVÁRIO,
JESUS POR NÓS MORREU.

MARAVILHA É ANUNCIAR ESSE AMOR
PRA VOCÊ QUE HOJE ESTÁ AQUI;
VEM CONHECÊ-LO, VEM RECEBÊ-LO
E A ALEGRIA INUNDARÁ TEU SER.

MARAVILHA, MARAVILHA,
MARAVILHA É A SALVAÇÃO.
NÃO MORREREMOS! SIM ESTAREMOS!
ETERNAMENTE COM O NOSSO DEUS!
/FINAL
ETERNAMENTE COM O NOSSO DEUS!
');
