INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('48f4262d-95ca-4dea-bb60-dc903d8b8f4d', 'Se hoje escutares', '325', 'Sérgio Paulo Ferreira de Matos', 'Básico 2', 'D', 'Consolo e Encorajamento', 'SE HOJE ESCUTARES
A VOZ MANSA E SUAVE DE DEUS,
O TEU CORAÇÃO ABRE
A ELE SEM HESITAÇÃO.

CORO
E DIZ: EIS-ME AQUI, SENHOR, COMO ESTOU,
TÃO NECESSITADO DE TI;
E PODES CONFIAR, DEUS VAI OPERAR
MUITO ACIMA DO QUE PODES PENSAR.

DEPENDE DE TI
ELE AGORA EM TUA VIDA ENTRAR;
ESCUTA SUA VOZ
E ABRE A PORTA HOJE, 
SEM HESITAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('48f4262d-95ca-4dea-bb60-dc903d8b8f4d', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
