INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('495a0a77-0a49-42d9-b108-799c590d6232', 'Quão amáveis são', '664', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'B', 'Salmos de Louvor', 'QUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS,
SENHOR DOS EXÉRCITOS!
A MINH''ALMA ESTÁ ANELANTE E DESFALECE
PELOS ÁTRIOS DO SENHOR.

CORO
O MEU CORAÇÃO E A MINHA CARNE
CLAMAM PELO DEUS VIVO!
QUÃO AMÁVEIS SÃO OS TEUS TABERNÁCULOS,
SENHOR DOS EXÉRCITOS!

ATÉ O PARDAL ENCONTROU CASA
E A ANDORINHA ENCONTROU NINHO PARA SI
JUNTO AO TEU ALTAR,
SENHOR DOS EXÉRCITOS,
REI MEU E DEUS MEU.
');
