INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('495debcb-d4c8-402a-885e-482fdcfd9522', 'Clamando estou', '005', 'Sara Gueiros Dodd', 'Fox', 'G', 'Clamor', 'CLAMANDO ESTOU, Ó MEU JESUS,
POR TEU SANGUE REMIDOR;
SOCORRO EU SEI QUE MANDARÁS
E LIVRAMENTO A MIM.

TEU SANGUE PURO DERRAMASTE
PARA ME PURIFICAR;
ENTÃO ADORAREI A TI,
Ó MEU SENHOR.
');
