INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('49f18672-8c2d-42b4-b058-4eeb942b1de3', 'Achei salvação', '116', 'Autor Desconhecido', 'Valseado', 'E', 'Dedicação', 'ACHEI SALVAÇÃO EM JESUS, MEU SENHOR,
PERDÃO, LIBERDADE ENCONTREI;
SUA ALMA RESIDE EM MEU CORAÇÃO
E NO SEU AMOR TENHO PAZ.

CORO
PAZ DO SENHOR, CÉLICA PAZ,
PAZ QUE ESTE MUNDO NÃO DÁ;
QUANDO PENSO NA LUZ QUE CENTELHA DA CRUZ,
TENHO PAZ, UMA CÉLICA PAZ.

A CRISTO, MEU REI, EU DAREI UMA CANÇÃO,
TALENTO, SERVIÇO E LOUVOR.
CONTENTE AOS SEUS PÉS, MEU FIEL CORAÇÃO 
DIRÁ: TENHO PAZ NO SENHOR.
');
