INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4a00835d-6b61-41e4-9e5f-b9703c850d5c', 'Senhor, Meu Deus e Pai', '055', 'Let.: Dalmir Cuel; Mús.:Manoel Vitor Pratte Santos', 'Básico', 'Dm', 'Clamor', 'SENHOR, MEU DEUS E PAI
EU ME PROSTRO DIANTE DE TI:
PERDÃO TE PEÇO, AGORA,
PELO SANGUE DE JESUS.

CANTAR 2X
LIBERTA-ME, SENHOR;
PURIFICA-ME, Ó PAI
POR JESUS, QUE É O MEU REI,
AMIGO E REMIDOR.
/INSTRUMENTOS

SENHOR, MEU DEUS E PAI
EU ME PROSTRO DIANTE DE TI:
PERDÃO TE PEÇO, AGORA,
PELO SANGUE DE JESUS.

FINAL 2X
LIBERTA-ME, SENHOR;
PURIFICA-ME, Ó PAI
POR JESUS, QUE É O MEU REI,
AMIGO E REMIDOR.
');
