INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4a2fdb0d-eb55-454f-af6e-ce7ece0bb4de', 'Buscai ao Senhor', 18, 'C.M.V.C.S.', 'Balada', 'A', 'Crianças e Adolescentes', 'CANTAR 2X
"BUSCAI AO SENHOR ENQUANTO SE PODE ACHAR,
INVOCAI-O ENQUANTO ESTÁ PERTO."

"DEIXE O ÍMPIO O SEU CAMINHO,
E O HOMEM MALIGNO OS SEUS PENSAMENTOS
E SE CONVERTA AO SENHOR,
QUE DELE SE COMPADECERÁ;
TORNE PARA O NOSSO DEUS,
PORQUE GRANDIOSO É EM PERDOAR."

FINAL
"BUSCAI AO SENHOR ENQUANTO SE PODE ACHAR,
INVOCAI-O ENQUANTO ESTÁ PERTO."
');
