INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4aa6fa1c-1084-46b4-a1df-93760cfa8a0c', 'Vigiai e sempre orai, ó crentes', '487', 'Let.: W. Snikes; Mús. W.J.Kirkpatrik', 'Fox', 'D', 'Volta de Jesus e Eternidade', 'VIGIAI E SEMPRE ORAI, Ó CRENTES,
BREVE CRISTO VOLTARÁ;
PARA O CÉU, O SEU DESCANSO ETERNO,
OS REMIDOS LEVARÁ.

CORO
VIGIAI! É ORDEM SANTA.
VIGIAI EM ORAÇÃO!
BREVE CRISTO VOLTARÁ,
PARA O CÉU NOS LEVARÁ!

VIGIAI, GUARDANDO SEMPRE LIMPO,
DO PECADO, O CORAÇÃO;
CONFIANDO NO DIVINO MESTRE,
VENCEREIS A TENTAÇÃO.

VIGIANDO E SEMPRE TRABALHANDO,
NESTE MUNDO VIL LUTAI,
AGUARDANDO A VOZ DE JESUS CRISTO:
"NO MEU DOCE LAR ENTRAI!"
');
