INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4ad93b59-1433-4d6b-a1af-32adcb61be20', 'Existe um lugar', 80, 'M.M.F.', 'Valsa', 'C', 'Crianças e Adolescentes', 'EXISTE UM LUGAR
QUE MEU JESUS FOI PREPARAR.
SE VOCÊ QUISER CHEGAR LÁ,
É SÓ A ELE SE ENTREGAR.
ESSE LUGAR É O CÉU DE LUZ,
ONDE HABITA O MEU JESUS.
SE QUISER PAZ, ALEGRIA E PERDÃO,
ENTREGUE A ELE O SEU CORAÇÃO.
');
