INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4ae05f24-2d32-4c0f-8e02-b25653c89042', 'Há Uma Pátria No Além (Coro Masculino)', '', '', '', '', '', 'HÁ UMA PÁTRIA NO ALÉM,
QUE DEUS PARA NÓS TEM,
UMA TERRA DE GOZO E LUZ,
NELA NÃO HÁ TEMOR,
NEM LEMBRANÇAS NEM DOR,
DESSA PÁTRIA O REI É JESUS.

CORO
COMO ANSEIO ENTRAR,
NESSA PÁTRIA MEU LAR,
ONDE ENFIM EU IREI DESCANSAR,
TUDO QUANTO LUTEI, PELA FÉ ESPEREI,
NESSA TERRA EU IREI CONTEMPLAR.

E SE CHEGA O TEMOR,
OUÇO A VOZ DO SENHOR,
ME FALAR DESSA PÁTRIA FELIZ,
MAIS UM POUCO E ENTRARÁS,
NAS MORADAS DE PAZ,
É A PALAVRA QUE O ESPÍRITO DIZ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('4ae05f24-2d32-4c0f-8e02-b25653c89042', '45ab58b2-d293-45c7-aa75-090fcd968b24');
