INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4b5d6b12-f7d3-49f0-bc4b-2c27a2388eee', 'Há tanta terra', '468', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Consolo e Encorajamento', 'HÁ TANTA TERRA PRA POSSUIR,
MAS NA BATALHA NÃO ESTAMOS SÓS;
MUITAS PROMESSAS SE VÃO CUMPRIR
SE O SENHOR SE AGRADAR DE NÓS.

*CORO 2X
ASSIM NÓS VAMOS COM FÉ
NO TEU PODER,
SE FORES CONOSCO, SENHOR,
IREMOS VENCER!
/INSTRUMENTOS

CERCA A CIDADE COM ORAÇÃO,
LEVANTA, IGREJA, A TUA VOZ;
DIANTE DE TI MUROS RUIRÃO
SE O SENHOR SE AGRADAR DE NÓS.

*CORO 2X
ASSIM NÓS VAMOS COM FÉ
NO TEU PODER,
SE FORES CONOSCO, SENHOR,
IREMOS VENCER!
');
