INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4c81c96c-e5f1-455d-a518-aa585793930e', 'Cantarei ao meu Senhor enquanto eu viver', '618', 'Donya Brookway', 'Balada', 'D', 'Louvor', 'CANTAREI AO MEU SENHOR ENQUANTO EU VIVER,
CANTAREI LOUVORES ENQUANTO EXISTIR;
ENTÃO ME ALEGRAREI NO MEU SENHOR,
MUI SUAVE SERÁ A MINHA MEDITAÇÃO!

FINAL 4X
LOUVA, MINH''ALMA, AO SENHOR,
BENDIZE-O JÁ.
');
