INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4e243c45-8120-47e1-bd61-688da9afeffc', 'Ao Teu Lado', '', '', '', '', '', 'EU ESTAREI SEMPRE AQUI,
AO TEU LADO Ó MEU FILHO
E QUANDO CHORARES SEM SOLUÇÃO,
AS TUAS LÁGRIMAS COLHO PRA MIM
LEMBRAS DE QUANDO EU TE FALEI:
"MEU FILHO TU ÉS MEU"
MAIS SERÁ QUE ESQUECESTE,
DAS PROMESSAS DO TEU DEUS?

*CORO
PODES CLAMAR, PODES CHORAR,
EU ESTAREI PRONTO PRA TE AJUDAR,
E SE O CORAÇÃO DESFALECER,
CONFIA EM MIM SOU JESUS
E TE FAÇO VENCER.

QUANDO SOFRESTE PENSANDO ESTAR SÓ,
EU FUI A TUA COMPANHIA,
E QUANDO CHORASTE LEVANTANDO DO PÓ,
EU TE ABRACEI, TE DEI ALEGRIA,
OLHA MEU FILHO EU NÃO
TE ESQUECI, E NUNCA TE ESQUECEREI,

LÁ NO CALVÁRIO EU MUITO SOFRI
MAS POR TE AMAR, TUDO SUPORTEI,
LEMBRAS DE QUANDO EU TE FALEI:
"MEU FILHO TU ÉS MEU"
MAIS SERÁ QUE ESQUECESTE,
DAS PROMESSAS DO TEU DEUS?

*CORO 2X
PODES CLAMAR, PODES CHORAR,
EU ESTAREI PRONTO PRA TE AJUDAR,
E SE O CORAÇÃO DESFALECER,
CONFIA EM MIM SOU JESUS
E TE FAÇO VENCER.
/FINAL
SOU JESUS E TE FAÇO VENCER.
');
