INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4e44629d-5a23-4166-b4a9-5a2795f0c837', 'Meu Deus Vence Batalhas', '', '', '', '', '', 'MEU DEUS VENCE BATALHAS
MEU DEUS QUEBRA MURALHAS
E QUANDO EU ESTOU A FRAQUEJAR,
SUAS MÃOS ESTÃO A ME SUSTENTAR.

MEU DEUS É MUITO FORTE
SEU NOME É EMANUEL
E QUANDO TUDO PARECE MAL,
A VITÓRIA EU SEI QUE ELE ME DARÁ.

*CORO
CLAMEI NA ANGÚSTIA
E OUVIU O MEU CLAMOR
MEU DEUS ESTÁ COMIGO,
NÃO TEMO O PERIGO,
ELE É O MEU SALVADOR.

NÃO SE COMPARA À PRATA,
NEM SE COMPARA AO OURO,
JESUS É O MEU TESOURO,
COM ELE VOU VENCER.

MEU DEUS VENCE BATALHAS
MEU DEUS QUEBRA MURALHAS
E QUANDO EU ESTOU A FRAQUEJAR,
SUAS MÃOS ESTÃO A ME SUSTENTAR.

MEU DEUS É MUITO FORTE
SEU NOME É EMANUEL
E QUANDO TUDO PARECE MAL,
A VITÓRIA EU SEI QUE
ELE ME DARÁ.

*CORO
CLAMEI NA ANGÚSTIA
E OUVIU O MEU CLAMOR
MEU DEUS ESTÁ COMIGO,
NÃO TEMO O PERIGO,
ELE É O MEU SALVADOR.

NÃO SE COMPARA À PRATA,
NEM SE COMPARA AO OURO,
JESUS É O MEU TESOURO,
COM ELE VOU VENCER.

*CORO
CLAMEI NA ANGÚSTIA
E OUVIU O MEU CLAMOR
MEU DEUS ESTÁ COMIGO,
NÃO TEMO O PERIGO,
ELE É O MEU SALVADOR.

NÃO SE COMPARA À PRATA,
NEM SE COMPARA AO OURO,
JESUS É O MEU TESOURO,
COM ELE VOU VENCER.
/FINAL
MEU DEUS VENCE BATALHAS.
');
