INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4e450941-627e-4733-98aa-f4b4cc97ac8f', 'Como desistir deste grande amor', '117', 'Jorgemar Souza Madeira', 'Básico', 'E', 'Dedicação', 'COMO DESISTIR DESTE GRANDE AMOR?
SE NÃO HÁ OUTRO AMOR IGUAL;
NÃO DESISTIREI, PRA ONDE IREI?

NÃO POSSO PARAR NEM DESANIMAR,
TENS ME DADO FORÇAS PRA VENCER;
NÃO DESISTIREI, PRA ONDE IREI?

SENHOR, TU ÉS A PORÇÃO
DA MINHA HERANÇA, DO MEU CÁLICE;
SENHOR, ÉS MEU AMOR,
PRA ONDE IREI, SE SÓ TU ÉS MEU SALVADOR?
/INSTRUMENTOS

COMO DESISTIR DESTE GRANDE AMOR?
SE NÃO HÁ OUTRO AMOR IGUAL;
NÃO DESISTIREI, PRA ONDE IREI?

NÃO POSSO PARAR NEM DESANIMAR,
TENS ME DADO FORÇAS PRA VENCER;
NÃO DESISTIREI, PRA ONDE IREI?

SENHOR, TU ÉS A PORÇÃO
DA MINHA HERANÇA, DO MEU CÁLICE;
SENHOR, ÉS MEU AMOR,
PRA ONDE IREI, SE SÓ TU ÉS MEU SALVADOR?
/FINAL
ÉS MINHA HERANÇA, SENHOR.
');
