INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4f3375f0-aadc-4da3-9453-dbcebd847556', 'Rosa Vermelha', 89, '', '', '', '', 'OLHANDO ESTE MUNDO ELE VIU GRANDE MULTIDÃO,
ANDANDO SOZINHO SEM NADA NA MÃO.
SUA VIDA FOI ROSA VERMELHA CRAVADA NA CRUZ,
QUEM PASSOU POR ELE SENTIU COMPAIXÃO.

A ROSA MURCHANDO, SANGRANDO,
ESVAINDO EM DOR (SE ESVAINDO EM DOR),
PERDENDO A COR (PERDENDO A COR),
SEM RESPIRAÇÃO.
MAS O SEU PERFUME SE APEGA
À MÃO QUE ESMAGOU
E QUEM A FERIU (E QUEM A FERIU)
CONCEDEU PERDÃO.

AGORA SEU SANGUE VERTENDO,
CAINDO NO CHÃO,
TRÊS DIAS MORRENDO, OH, QUE SOLIDÃO!
NO TERCEIRO DIA O MUNDO
ENCHEU-SE DE FLORES,
E A ROSA VERMELHA, DE NOVO BROTOU.

JESUS É O LÍRIO DOS VALES,
ROSA DE SAROM (ROSA DE SAROM).
ATÉ SEUS ESPINHOS (ATÉ SEUS ESPINHOS),
SÃO MARCAS DE AMOR.
E AGORA ELE VIVE A PLANTAR UM GRANDE JARDIM,
SE VOCÊ QUISER (SE VOCÊ QUISER),
SERÁ UMA FLOR.

AGORA SEU SANGUE VERTENDO,
CAINDO NO CHÃO,
TRÊS DIAS MORRENDO, OH, QUE SOLIDÃO!
NO TERCEIRO DIA O MUNDO
ENCHEU-SE DE FLORES,
E A ROSA VERMELHA, DE NOVO BROTOU.

CANTAR 2X
JESUS É O LÍRIO DOS VALES,
ROSA DE SAROM (ROSA DE SAROM).
ATÉ SEUS ESPINHOS (ATÉ SEUS ESPINHOS),
SÃO MARCAS DE AMOR.
E AGORA ELE VIVE A PLANTAR UM GRANDE JARDIM,
SE VOCÊ QUISER (SE VOCÊ QUISER),
SERÁ UMA FLOR.
');
