INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4f54c201-84fd-44ee-b6e9-7398c4261b97', 'Vós, Criaturas De Deus Pai', '', '', '', '', '', 'MEU DEUS, MEU PAI ESTOU AQUI
PRA TE FALAR, PRA TE OUVIR.
ME SINTO SÓ NO CAMINHAR,
EM TI PRECISO ME ANCORAR.
SEI QUEM TU ÉS E QUEM EU SOU,
APENAS SERVO E NADA MAIS.
EU RECONHEÇO QUE ÉS SENHOR,
MAS TE PROCURO COMO PAI.

*CORO
UM POUCO SÓ DO TEU AMOR
VAI ME ERGUER, ME PÔR DE PÉ,
SÓ UM INSTANTE JUNTO A TI
VAI ME BASTAR E RENOVAR
A MINHA FÉ.

MOMENTOS HÁ QUE O CORAÇÃO
FICA INSEGURO, FRÁGIL ATÉ.
E NO CALOR DA AFLIÇÃO
É QUE SE VIVE PELA FÉ.
UM GESTO TEU, UM SÓ OLHAR
E A ALMA INTEIRA SE REFAZ.
ESTOU SEGURO EM TI SENHOR
SALVOU-ME O TEU AMOR DE PAI.

*CORO 2X
UM POUCO SÓ DO TEU AMOR
VAI ME ERGUER, ME PÔR DE PÉ
SÓ UM INSTANTE JUNTO A TI
VAI ME BASTAR E RENOVAR
A MINHA FÉ
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('4f54c201-84fd-44ee-b6e9-7398c4261b97', '45ab58b2-d293-45c7-aa75-090fcd968b24');
