INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('e8a37e3a-0723-4f1e-b66b-f74615a5b018', '4f54c201-84fd-44ee-b6e9-7398c4261b97', 'c2fb644f-697c-4d43-9d5f-22319fa0ce79', 'pdf', 'assets/praises/4f54c201-84fd-44ee-b6e9-7398c4261b97/e8a37e3a-0723-4f1e-b66b-f74615a5b018.pdf', 'Avulsos Migrados/Vós, Criaturas De Deus Pai/coro.pdf', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4f63a376-3c12-4660-8b31-e5010b4a64cc', 'Oh Pensai nesse lar lá do céu', '540', 'Let.: Witt Clinton Huntington; Trad. Leônidas P. G. da Silva; Mús.Tullius Clinton O’Kane', 'Marcha', 'G', 'Volta de Jesus e Eternidade', 'OH! PENSAI NESSE LAR LÁ DO CÉU,
BEM AO LADO DO RIO DE LUZ,
ONDE OS SANTOS PRA SEMPRE JÁ GOZAM
DA PRESENÇA DO NOSSO JESUS.

CORO 2X
LÁ DO CÉU! LÁ DO CÉU!
OH! PENSAI NESSE LAR LÁ DO CÉU!

OH! PENSAI NOS AMIGOS DO CÉU
QUE A JORNADA JÁ TÊM ACABADO
E NOS CANTOS QUE SOAM NOS ARES,
NO PALÁCIO POR DEUS PREPARADO.

HEI DE VER LÁ NO CÉU MEU JESUS,
FACE A FACE SEU ROSTO MIRAR;
LONGE, LONGE, CUIDADOS, TRISTEZAS!
COM JESUS VOU PRA SEMPRE MORAR.

CEDO, CEDO NO CÉU LÁ ESTAREI,
VEJO O FIM DA JORNADA CHEGAR;
MEU JESUS ALI ESTÁ ME ESPERANDO,
É MELHOR ESTAR ALI QUE AQUI ESTAR.
');
