INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4fbeaf6e-3010-4042-b51a-ae3ae5040803', 'Andai na minha presença', '162', 'F.S.P.', 'Fox', 'C', 'Crianças e Adolescentes', 'CORO 2X
ANDAI NA MINHA PRESENÇA,
ANDAI NA MINHA PRESENÇA
E VOS GUIAREI.

E VOS LEVAREI A UM LUGAR
CHEIO DE GOZO E DE PAZ.
FOME E SEDE JAMAIS TEREIS,
POIS COMEREIS DO PÃO DA VIDA.

E O MEU ESPÍRITO VOZ CONDUZIRÁ
À PÁTRIA CELESTIAL.
LUTAS E DORES NUNCA MAIS TEREIS,
POIS VIVEREIS COM O VOSSO REI.
');
