INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4fcb8dd8-7b23-440e-b787-c6684b4f2a5e', 'Em Suas Mãos', '', '', '', '', '', 'MUITAS VEZES NESTA VIDA EU PENSEI EM DESISTIR,
MESMO ESTANDO AO TEU LADO,
DESFRUTANDO OS TEUS CUIDADOS.
AINDA SIM, SENHOR, FALHEI NÃO TENDO FÉ
NO TEU PODER, NO TEU BEM QUERER
NÃO SOU MERECEDOR.

QUANTAS VEZES NO SILÊNCIO EU PENSEI
NÃO TER NINGUÉM QUE OUVISSE O MEU LAMENTO,
QUE COLHESSE O MEU PRANTO.
AINDA ASSIM, SENHOR, ESTAVAS TODO TEMPO
AO MEU REDOR COM AMOR MAIOR,
CHAMOU-ME: " FILHO MEU".

PÕE TUAS MÃOS NAS MÃOS DE CRISTO
QUE NA CRUZ FORAM CRAVEJADAS POR TI
PRA DAR-TE O PERDÃO, A LIBERTAÇÃO,
PRA DAR-TE PAZ. PÕE TUAS MÃOS NAS MÃOS
DE CRISTO, TOCA NAS FERIDAS E TENHAS FÉ
QUE O ANJO DO SENHOR ESTÁ AQUI
PRA PÔR-TE DE PÉ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('4fcb8dd8-7b23-440e-b787-c6684b4f2a5e', '45ab58b2-d293-45c7-aa75-090fcd968b24');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('4fcb8dd8-7b23-440e-b787-c6684b4f2a5e', 'd369f950-5259-483c-9412-b0a37d90042c');
INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('c034fc8a-e855-4b22-890c-f7bdd74591d1', '4fcb8dd8-7b23-440e-b787-c6684b4f2a5e', 'c2fb644f-697c-4d43-9d5f-22319fa0ce79', 'pdf', 'assets/praises/4fcb8dd8-7b23-440e-b787-c6684b4f2a5e/c034fc8a-e855-4b22-890c-f7bdd74591d1.pdf', 'Avulsos Migrados/Em Suas Mãos/coro.pdf', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4fcf0944-b7d4-4bb5-8564-07c4108df6ef', 'Em tua presença entramos', '017', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Clamor', 'EM TUA PRESENÇA ENTRAMOS
CLAMANDO A TI, Ó SENHOR,
LAVA-NOS COM O TEU SANGUE,
RENOVA EM NÓS TEU AMOR.

COM TEU ESPÍRITO SANTO
VEM ENTRE NÓS PRESIDIR.
SEJA ESTE CULTO UM INCENSO
QUE POSSA AOS CÉUS SUBIR.

EM TEU ALTAR ENTREGAMOS
AS NOSSAS VIDAS, SENHOR,
DE CORAÇÃO OFERTAMOS
A TI O NOSSO LOUVOR.

Ó CRISTO VIVO, REVELA
TUA PRESENÇA ENTRE NÓS,
COM TUA GRAÇA OPERA,
FAZE-NOS OUVIR TUA VOZ.

EM TUA PRESENÇA ENTRAMOS
CLAMANDO A TI, Ó SENHOR,
LAVA-NOS COM O TEU SANGUE,
RENOVA EM NÓS TEU AMOR.
