INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('4fd3793a-bdc6-4be7-8661-11f449208627', 'Além do Céu Azul', '535', 'Alfred B. Smith', 'Básico 2', 'D', 'Volta de Jesus e Eternidade', 'ALÉM DO CÉU AZUL FOI JESUS PREPARAR
UM LAR, PRA DAR A QUEM A VITÓRIA ALCANÇAR;
ANELO CONSEGUIR A VIDA NO PORVIR,
COM FÉ NO MEU SENHOR JESUS.

BEM SEI QUE EU, DE MIM,
NADA TENHO PRA DAR,
MAS SEI QUE MEU JESUS
JÁ ME VEIO SALVAR;
AGORA QUERO EU TER FÉ NO CORAÇÃO,
ATÉ SEU ROSTO VER ALÉM.
');
