INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('508fa31a-2d58-40f4-86f3-b45711109550', 'Quando Jesus um dia', '173', 'Sara Gueiros Dodd', 'Guarânia', 'C', 'Dedicação', 'QUANDO JESUS UM DIA,
MEU PECADO CARREGOU,
PELO SANGUE DERRAMADO,
MINHA VIDA ELE LAVOU.

ALGO NOVO ACONTECEU,
TÃO SUBLIME E TÃO REAL;
CHORAR EU NÃO SABIA,
SÓ DE AGONIA E DOR.

CHORO AGORA DE ALEGRIA,
ALELUIA AO MEU SENHOR;
MEU PECADO RESGATOU,
MINHA VIDA TRANSFORMOU.

ALGO NOVO ACONTECEU,
TÃO SUBLIME E TÃO REAL;
CHORO AGORA DE ALEGRIA,
ALELUIA AO MEU SENHOR.
');
