INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('51ba1467-9888-48e1-99cc-1fdd66bc0ee6', 'Uma luz resplandecente', '140', 'C.M.V.', 'Balada', 'A', 'Crianças e Adolescentes', 'UMA LUZ RESPLANDECENTE
HÁ EM VOLTA DO TEU OLHAR,
TUA FACE RELUZENTE
VEM HOJE ME MOSTRAR.

SEI QUE UM DIA TU VIRÁS
E ENTÃO ME LEVARÁS
ANTES MESMO QUE EU PEÇA:
SENHOR, VEM ME BUSCAR!

SEGURA-ME PELA MÃO
QUANDO A VIDA ATRAVESSAR,
SEI QUE TU ESTÁS COMIGO
QUANDO O MAL ME ENCONTRAR.
');
