INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('51e6d57f-04ba-43da-9827-74c56169b8c0', 'Os Céus Proclamam', '657', 'Everaldo Cavalcante Lima', 'Básico', 'E', 'Salmos de Louvor', 'OS CÉUS PROCLAMAM A SUA GLÓRIA
E O FIRMAMENTO AS OBRAS DAS SUAS MÃOS;
UM DIA PASSA, O OUTRO VEM,
É ELE QUEM DÁ VITÓRIAS AO SEU POVO;

CANTAR 2X
DO ALTO VEIO A SUA MÃO,
TOCOU-ME E DEU-ME ALEGRIA DE VIVER.

*CORO 2X
GLÓRIA AO MEU JESUS
POIS DELE SOU E ELE É MEU.
/INSTRUMENTOS

SE FAZ OUVIR A SUA VOZ
POR TODA A TERRA E AOS CONFINS DO MUNDO;
SINTO A PRESENÇA DE DEUS TÃO CALMA
POIS QUEM É DEUS SENÃO O NOSSO DEUS?

CANTAR 2X
COMIGO ESTÁ, NÃO VOU DEIXAR
QUE QUALQUER COISA QUEBRE ESSA COMUNHÃO.

*CORO 2X
GLÓRIA AO MEU JESUS
POIS DELE SOU E ELE É MEU.
');
