INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5240e81d-ccb7-4963-a684-12bd93a95e17', 'Proclame a Glória Do Senhor', '', '', '', '', '', 'PROCLAME A GLÓRIA DO SENHOR,
CONFESSE O SEU AMOR
E CONTE A TODOS QUE SEU REINO
É PRA SEMPRE;
PROCLAME A GLÓRIA DO SENHOR,
DEMOSNTRE O SEU AMOR,
A TODOS FAÇA CONHECIDO
O SEU PODER.

*CORO
REINARÁ PRA SEMPRE
O GRANDE REI DOS REIS,
O NOSSO SALVADOR
QUE JUNTOS VAMOS PROCLAMAR;
GLÓRIA AO SENHOR,
O GRANDE REDENTOR,
QUE CADA RAÇA EM SEU LOUVOR
PROCLAME A GLÓRIA DO SENHOR.
/INSTRUMENTOS

PROCLAME A GLÓRIA DO SENHOR,
CONFESSE O SEU AMOR
E CONTE A TODOS QUE SEU REINO
É PRA SEMPRE;
PROCLAME A GLÓRIA DO SENHOR,
DEMONSTRE O SEU AMOR,
A TODOS FAÇA CONHECIDO
O SEU PODER.

*CORO 3X
REINARÁ PRA SEMPRE
O GRANDE REI DOS REIS,
O NOSSO SALVADOR
QUE JUNTOS VAMOS PROCLAMAR;
GLÓRIA AO SENHOR,
O GRANDE REDENTOR,
QUE CADA RAÇA EM SEU LOUVOR
PROCLAME A GLÓRIA DO SENHOR.
');
