INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('52797019-6e4d-49fa-af17-5052c854e3c0', 'Vem, derrama a paz', '619', 'Carlos R. Sider', 'Básico', 'D', 'Louvor', 'VEM, DERRAMA A PAZ,
VEM, DERRAMA AS BÊNÇÃOS
SOBRE ESTE POVO QUE SE CHAMA POVO TEU;
DÁ-NOS TEU AMOR, DÁ-NOS TUA FORÇA
PRA QUE TENTAÇÕES NÃO VENHAM
A NOS DESVIAR.

E A GLÓRIA SEJA DADA A TI
PELO QUE TENS FEITO,
PELO QUE TENS SIDO,
PELO QUE FARÁS EM NÓS. 
/INSTRUMENTOS

VEM, DERRAMA A PAZ,
VEM, DERRAMA AS BÊNÇÃOS
SOBRE ESTE POVO QUE SE CHAMA POVO TEU;
DÁ-NOS TEU AMOR, DÁ-NOS TUA FORÇA
PRA QUE TENTAÇÕES NÃO VENHAM
A NOS DESVIAR.

E A GLÓRIA SEJA DADA A TI
PELO QUE TENS FEITO,
PELO QUE TENS SIDO,
PELO QUE FARÁS EM NÓS. 
/FINAL
PELO QUE FARÁS EM NÓS.
');
