INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('52991aa9-4a8d-4709-9863-806d5d3ff1d5', 'Aquele que tem sede', 94, 'E.H.M.R.', 'Fox', 'Dm', 'Crianças e Adolescentes', 'AQUELE QUE TEM SEDE
VÁ À FONTE E BEBA,
SUAS ÁGUAS DESSEDENTAM
E TRAZEM VIDA.

RIOS DE ÁGUAS CORRERÃO 
NO SEU INTERIOR,
E A ALEGRIA QUE SALTA
PARA A VIDA ETERNA.

JESUS É ESSA FONTE DE VIDA,
QUE SACIA A SEDE DA ALMA.
VENHA A ELE E BEBA,
E UMA VIDA ETERNA LHE DARÁ.

AQUELE QUE TEM SEDE
VÁ À FONTE E BEBA,
SUAS ÁGUAS DESSEDENTAM
E TRAZEM VIDA.

FINAL
RIOS DE ÁGUAS CORRERÃO 
NO SEU INTERIOR,
E A ALEGRIA QUE SALTA
PARA A VIDA ETERNA.
');
