INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('52a3a0c3-23f9-4899-8397-b5f92b57a413', 'Ó Vinde e Adoremos Sl 95', '650', 'José Elias Simora', 'Básico', 'A', 'Salmos de Louvor', 'Ó VINDE E ADOREMOS
E PROSTREMOS DIANTE DO SENHOR;
SE OUVIRDES A SUA VOZ
NÃO ENDUREÇAIS OS VOSSOS CORAÇÕES.

CANTAR 2X
Ó VINDE A JESUS,
NÃO ENDUREÇAIS OS VOSSOS CORAÇÕES,
ACEITAI A CRISTO, A SALVAÇÃO.
/INSTRUMENTOS

Ó VINDE E ADOREMOS
E PROSTREMOS DIANTE DO SENHOR;
SE OUVIRDES A SUA VOZ
NÃO ENDUREÇAIS OS VOSSOS CORAÇÕES.

CANTAR 2X
Ó VINDE E ADOREMOS,
Ó VINDE E CANTEMOS AO SENHOR,
ADORAI A CRISTO, O SALVADOR.
/FINAL
JESUS, SÓ JESUS, O SALVADOR, JESUS.
');
