INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('52d823de-bca0-4968-aeb9-0a98e7a29709', 'Como é bom te adorar', '573', 'Leila Gomes Pereira', 'Básico', 'A', 'Louvor', 'COMO É BOM TE ADORAR, SENHOR JESUS,
COMO É BOM ESTAR NA TUA PRESENÇA,
CANTAR LOUVORES E BENDIZER
DE TODO O MEU CORAÇÃO.

CORO
(M) OH! SENHOR,
(H) (OH! SENHOR)
(M) GRANDIOSO É O TEU NOME;
(H) OH! SENHOR,
(M) (OH! SENHOR)
TEU ESPÍRITO SANTO NOS TEM CONSOLADO.

TENS ABENÇOADO O TEU POVO,
TENS ABENÇOADO, Ó DEUS,
TENS ALEGRADO OS CORAÇÕES,
TENS NOS DADO A LIBERTAÇÃO.

CANTAR 2X
LOUVAREI AO SENHOR, (LOUVAREI)
COM GRANDE ALEGRIA, (LOUVAREI)
LOUVAREI AO SENHOR,
LOUVAREI AO SENHOR JESUS.
/FINAL
LOUVAREI AO SENHOR JESUS.
');
