INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('53ac9683-60d9-4623-a923-c1ec647632ee', 'Abre a porta do teu coração', '779', 'Autor Desconhecido', 'Fox', 'A', 'Morte, Ressureição e Salvação', 'ABRE A PORTA DO TEU CORAÇÃO 
E DEIXA CRISTO ENTRAR,
ELE TE DARÁ SALVAÇÃO, 
AO CÉU TE LEVARÁ.

ABRE A PORTA DO TEU CORAÇÃO
E DEIXA CRISTO EM TI HABITAR.
ABRE A PORTA DO TEU CORAÇÃO,
QUE JESUS TE ABENÇOARÁ.

ABRE A PORTA, ABRE A PORTA,
ABRE A PORTA DO TEU CORAÇÃO;
ABRE A PORTA, ABRE A PORTA,
QUE JESUS TE DARÁ SALVAÇÃO.
');
