INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('53bfcdfb-e0f4-4b4a-9b02-288b955edf21', 'Uma voz mansa e delicada (I Reis 19)', '056', '', '', 'G', 'Avulsos', 'UMA VOZ MANSA E DELICADA,
