INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5403ea87-b7fa-4765-930f-e0a6b38db7c7', 'Deitada na relva uma feliz ovelha', '117', 'M.L.M.B.O.; E.H.M.R.', 'Novo', 'E', 'Crianças e Adolescentes', 'DEITADA NA RELVA UMA FELIZ OVELHA
JUNTO AO PASTOR ESTÁ A DESCANSAR,
NAS ÁGUAS TRANQUILAS SACIA SUA SEDE,
DA RELVA BEM VERDE PODE SE ALIMENTAR.

CORO
OVELHA, JAMAIS DEIXE ESTE APRISCO.
TENS O BOM PASTOR PARA DE TI CUIDAR.
NO MUNDO LÁ FORA HÁ TRISTEZA E GUERRA,
JESUS É A ALEGRIA, VERDADE E PAZ.

E QUANDO AS TREVAS CAEM SOBRE O MUNDO,
O TENTADOR VEM DISPOSTO A TRAGAR.
JESUS EM SEUS BRAÇOS, OVELHA, TE ACOLHE
PARA QUE TU POSSAS A VIDA HERDAR.
');
