INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5488ae6c-0d57-48f2-b8c7-3505273f633a', 'A Paz Que Tu Procuras', '251', 'Fábio Henrique Barros Ramos, Márcia Castro de Freitas', 'Básico', 'G', 'Morte, Ressureição e Salvação', 'A PAZ QUE TU PROCURAS,
A ALEGRIA QUE ALMEJAS
HOJE PODES ENCONTRAR,
AQUELE QUE POR TI MORREU
HOJE AQUI ESTÁ E QUER TE SALVAR.

*CORO
LOUVAI A JESUS
E JUNTOS EXALTEMOS O SEU NOME,
PROCLAMAI, (MARANATA!)
PROCLAMAI: ELE VOLTARÁ!
/INSTRUMENTOS

ELE ESTÁ A TE CONTEMPLAR
E COM SUA DOCE VOZ IRÁ FALAR
AO TEU CORAÇÃO:
"VEM, FILHO MEU, RECEBE A VIDA
QUE ESTAVAS A PROCURAR."

*CORO 2X
LOUVAI A JESUS
E JUNTOS EXALTEMOS O SEU NOME,
PROCLAMAI, (MARANATA!)
PROCLAMAI: ELE VOLTARÁ!
/FINAL
PROCLAMAI, (MARANATA!),
PROCLAMAI: ELE VOLTARÁ!
');
