INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('54defe04-27af-4a44-970d-89be2a444b5a', 'Nova aliança', '144', 'E.H.M.R.', 'Fox Abafado', 'D', 'Crianças e Adolescentes', 'NOVA ALIANÇA FEZ O MEU SENHOR
COM O SEU POVO NUM ATO DE AMOR;
"EIS QUE FAÇO NOVA 
TODAS AS COISAS",
ASSIM FALOU O SENHOR.

PREPARO O MEU CORAÇÃO
PARA O ARREBATAMENTO
NÃO SERÁ FÁCIL, LUTAS VIRÃO,
MAS NA BUSCA AO SENHOR,
ELE DARÁ A SOLUÇÃO.

COM O ESPÍRITO SANTO
QUER BATIZAR
E EXPERIÊNCIAS
COM OS DONS QUER DAR,
EU NÃO TEMEREI,
COM CRISTO ANDAREI
NA DIREÇÃO DO ESPÍRITO SANTO.

QUANDO EU CAMINHAR COM MEU JESUS
VAI RAIAR A LUZ E VIDAS
SE ENTREGARÃO,
RECEBENDO A SALVAÇÃO;
E JUNTOS NUM CORPO UNIDO
VAMOS RUMO À 
TÃO ESPERADA SIÃO. (2X)
');
