INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('55504a9a-2bb7-421a-8f2b-bd4877d7ad4e', 'A Tua Palavra', '446', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'F', 'Santificação e Derramamento', 'A TUA PALAVRA É TESOURO ESCONDIDO
QUE ALGUÉM ENCONTROU;
MISTÉRIOS SELADOS QUE O ESPÍRITO SANTO
A NÓS REVELOU
A TUA PALAVRA É TRIGO GUARDADO,
MALHADO NO LAGAR DE DEUS,
NOSSO PÃO DO CÉU!

*CORO
BENDITA PALAVRA QUE CURA E SALVA
A QUEM NELA CRÊ,
PALAVRA DE DEUS!

A TUA PALAVRA É ABRIGO SEGURO
QUE VIDA NOS TRAZ,
A ROCHA DOS SÉCULOS, BEM FIRME ALICERCE,
ETERNA E VERAZ.
FELIZ QUEM SOBRE ELA EDIFICA SUA CASA,
TORMENTAS ELA VENCERÁ, NÃO VACILARÁ!

*CORO
BENDITA PALAVRA QUE CURA E SALVA
A QUEM NELA CRÊ,
PALAVRA DE DEUS!
/INSTRUMENTOS
/FINAL
PALAVRA DE DEUS.
');
