INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('557a5740-f037-42bd-b5c7-dee866e923c2', 'Certo homem, príncipe dos judeus (Nicodemos)', 89, 'A.V.Q.S.', 'Básico', 'Cm', 'Crianças e Adolescentes', 'CERTO HOMEM, PRÍNCIPE DOS JUDEUS,
FOI AO MESTRE PERGUNTAR-LHE ASSIM:
BEM SABEMOS QUE ÉS MESTRE
VINDO DE DEUS.

COMO PODE ALGUÉM NASCER DE NOVO?
AQUELE QUE NÃO NASCER DA ÁGUA 
E DO ESPÍRITO
NÃO PODE VER O REINO DE DEUS.
MAS AQUELE QUE PERMANECER FIEL
ATÉ O FIM, O VERÁ.
');
