INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5584c422-5fa1-4678-9c8c-f85091489781', 'Ouve, pois, Israel', '', '', '', '', '', 'OUVE, Ó DEUS, MINHA ORAÇÃO
POIS MEU SER SE ABATE DENTRO EM MIM,
LEVA-ME À ROCHA, SÊ MEU REFÚGIO,
POIS MUITOS SÃO CONTRA MIM.

*CORO
FAZ-ME INABALÁVEL, FIRME E SEGURO
NO VALE DA MORTE;
FAZ-ME VER (FAZ-ME VER)
TUA LUZ, (TUA LUZ)
LOUVAR TEU NOME PRA SEMPRE, AMÉM!

OUVE, Ó DEUS, MINHA ORAÇÃO
POIS MEU SER SE ABATE DENTRO EM MIM,
LEVA-ME À ROCHA, SÊ MEU REFÚGIO,
POIS MUITOS SÃO CONTRA MIM.

*CORO
FAZ-ME INABALÁVEL, FIRME E SEGURO
NO VALE DA MORTE;
FAZ-ME VER (FAZ-ME VER)
TUA LUZ, (TUA LUZ)
LOUVAR TEU NOME PRA SEMPRE, AMÉM!

FINAL
PRA SEMPRE, LOUVAR TEU NOME
PRA SEMPRE, AMÉM!
');
