INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('558a2fac-9b3c-49c9-931b-3e006a2af624', 'Nesta Hora Esqueço o Mundo', '037', 'Gérson Beluci Miguel', 'Balada', 'D', 'Clamor', 'NESTA HORA ESQUEÇO O MUNDO,
TODA A PREOCUPAÇÃO.
ME COLOCO EM TUA PRESENÇA,
SOU CARENTE DO TEU PERDÃO.

CONSIDERO O MEU PECADO,
RECONHEÇO O TEU AMOR.
TEU ESPÍRITO ME TEM LEVADO
A ADORAR-TE MEU SALVADOR.

*CORO
OH! QUE SANGUE REMIDOR
QUE RETIRA A MINHA DOR
E ME LIVRA DO PECADO,
Ó JESUS, TU ÉS AMADO.
/INSTRUMENTOS

POR TEU SANGUE ESTOU LIBERTO,
POSSO TE GLORIFICAR,
DE MEU PAI, SIM, AGORA ESTOU PERTO,
ALELUIA, VOU TE LOUVAR.

*CORO
OH! QUE SANGUE REMIDOR,
QUE RETIRA A MINHA DOR
E ME LIVRA DO PECADO,
Ó JESUS, TU ÉS AMADO.
/FINAL 2X
E ME LIVRA DO PECADO,
Ó JESUS, TU ÉS AMADO.
');
