INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('562c9834-959c-4329-b2a7-44ce352157a6', 'Jerusalém Eterna', '694', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'Gm', 'Grupo de Louvor', 'JERUSALÉM ETERNA, EM BREVE TU VIRÁS,
DESCENDO COMO NOIVA
ATAVIADA PARA O SEU MARIDO.
JERUSALÉM, MINHA CIDADE,
COMO ANSEIO ENTRAR

CANTAR 2X
E ANDAR POR TUAS RUAS,
SAUDAR OS TEUS REMIDOS
E ADORAR TEU REI.
/INSTRUMENTOS

JERUSALÉM ETERNA,
ESPOSA DO CORDEIRO,
EM TI HABITARÁ DEUS COM OS HOMENS
PARA TODO SEMPRE.
NAÇÕES VIRÃO PARA ADORAR
E REIS TRARÃO SUA GLÓRIA

FINAL 2X
AO FILHO DE DAVI,
AO PRÍNCIPE DA PAZ,
TEU REI, JERUSALÉM.
/JERUSALÉM.
');
