INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5631112f-f3d7-4b7f-a53d-3897a4c69c2b', 'Não Vai Tardar', '496', 'Let. e Mús. Andrae Crouch;Trad. Sandra Alencar', 'Básico', 'A', 'Volta de Jesus e Eternidade', 'CANTAR 2X
NÃO VAI TARDAR E CRISTO HÁ DE VOLTAR;
NÃO VAI TARDAR E VEREMOS JESUS.
EU QUERO ME PREPARAR,
POIS QUERO LOGO SUBIR;
E QUERO JUNTO A VOCÊ,
LÁ NO CÉU,
CONVERSAR COM JESUS.
');
