INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5640d408-9526-4b1a-85e3-5132a7e1502e', 'Uma ovelhinha de Jesus eu sou', '024', 'C.M.V.C.S.', 'Country', 'D', 'Crianças e Adolescentes', 'UMA OVELHINHA DE JESUS EU SOU,
SEMPRE ESTÁ COMIGO, É MEU BOM PASTOR;
ME MOSTRA O CAMINHO EM QUE DEVO ANDAR,
É MEU AMADO SALVADOR.

ME LIVRA DO PERIGO,
ESTENDE O SEU CAJADO,
É MEU MELHOR AMIGO,
DO MAL ESTOU GUARDADO.
EM TODA A MINHA VIDA EU O AMAREI,
E PARA SEMPRE VIVEREI COM JESUS.
/FINAL
E PARA SEMPRE VIVEREI COM JESUS.
');
