INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('568fb0d9-af7d-44c5-8db9-a66ba898f90f', 'Há uma obra que Deus quer fazer', '419', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Santificação e Derramamento', 'HÁ UMA OBRA QUE DEUS QUER FAZER,
OBRA DE SANTIDADE E DE PODER;
QUEM ESTÁ DISPOSTO A SE CONSAGRAR
E A ARCA DE DEUS AOS OMBROS CARREGAR?

CORO
O ESPÍRITO DE DEUS QUER A TI,
COMO ELE UM DIA POSSUIU DAVI, SIM,
HÁ UMA OBRA A REALIZAR
ANTES QUE VENHA O FIM.

DESCE AO RIBEIRO E ENCHE O CORAÇÃO,
TERÁS VITÓRIA NA REVELAÇÃO;
COM ÓLEO DE PODER DEUS TE UNGIRÁ,
JAMAIS VAZIA A ESPADA VOLTARÁ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('568fb0d9-af7d-44c5-8db9-a66ba898f90f', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
