INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('56bf97bb-c56e-4566-99dd-85a524c12c2b', 'Quando a Angústia Vem', '318', 'Autor Desconhecido', 'Fox', 'G', 'Consolo e Encorajamento', 'QUANDO A ANGÚSTIA VEM
E NOS OLHOS LÁGRIMAS,
PARECE, ENTÃO,
QUE TU NÃO PODES SUPORTAR;
JESUS TE AJUDARÁ E TUDO ELE VERÁ,
AS LÁGRIMAS FALAM, DEUS OUVIRÁ.

CORO
DEUS VÊ NOS OLHOS O AFLITO CORAÇÃO, 
É O SENHOR
QUEM VÊ AS LÁGRIMAS EM ORAÇÃO.
COM O HOMEM ELE VIVERÁ,
PELAS MÃOS O TOMARÁ.
AS LÁGRIMAS FALAM, DEUS OUVIRÁ.

QUANDO NÃO PUDERES MAIS
SONHO ALGUM REALIZAR,
E TUDO, ENFIM, DIANTE DE TI, DESMORONAR,
MEU DEUS NÃO TE ESQUECERÁ,
PROMESSAS CUMPRIRÁ.
AS LÁGRIMAS FALAM, DEUS OUVIRÁ.
');
