INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('56d64bf6-a79b-4784-ac5f-7d4eafb77e29', 'Além do Véu eu quero está', '041', 'Sérgio Paulo Ferreira de Matos', 'Guarânia', 'D', 'Clamor', 'ALÉM DO VÉU EU QUERO ESTAR,
ALÉM DO VÉU COM JESUS,
PELO CAMINHO QUE ELE ABRIU NAQUELA CRUZ.

COM OUSADIA VOU ENTRAR
E POR SEU SANGUE VOU CLAMAR,
ALÉM DO VÉU ONDE ELE QUER ME ABENÇOAR.

ALÉM DO VÉU A SUA GLÓRIA 
POSSO AGORA CONTEMPLAR;
DO AMOR DE DEUS 
QUEM PODERÁ ME SEPARAR?
COM QUERUBINS E SERAFINS
MIL ALELUIAS VOU CANTAR,

FINAL 2X
ALÉM DO VÉU,
ONDE PRA SEMPRE QUERO ESTAR.
');
