INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5768b925-163d-4188-8b2f-ce54b94d409a', 'Este mundo jamais pode me separar', '557', 'Richard Dick Torrans', 'Valseado', 'E', 'Dedicação', 'ESTE MUNDO JAMAIS PODE ME SEPARAR
DOS VALORES CELESTIAIS QUE EU VOU RECEBER.
MEU TESOURO E ESPERANÇA
ESTÃO NO MEU NOVO LAR,
SOU HERDEIRO COM CRISTO,
VOU COM ELE MORAR.

CORO
CÉU, LINDO CÉU! (2X)
HÁ MANSÕES CELESTIAIS,
TODAS FEITAS POR DEUS!
CÉU, LINDO CÉU! (2X)
EU VOU PRO CÉU, LINDO CÉU,
COM CRISTO VOU MORAR NO LINDO CÉU!

JÁ ESTANDO ALÉM RIO, MINHA LUTA FINDOU,
EU NÃO TEMO MAIS PECADO,
POIS JESUS ME LAVOU.
OH! QUE GLÓRIA NA SUBIDA
PRAS ALTURAS DOS CÉUS,
CANTAREI A LINDA HISTÓRIA
DO CORDEIRO DE DEUS!
');
