INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5869585d-d04e-4083-b90c-e1f8bdff37a3', 'Sei, Senhor', '074', 'Raquel Toscano de Freitas', 'Básico', 'D', 'Invocação e Comunhão', 'SEI, SENHOR, QUE CARINHOSAMENTE
