INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('58bac5be-7cc8-4a2d-a17d-366c163ab721', 'Jesus Está as Portas', '545', 'Jorgemar Souza Madeira', 'Básico', 'G', 'Volta de Jesus e Eternidade', 'CANTAR 2X
JESUS ESTÁ ÀS PORTAS,
JESUS EM BREVE VEM
NAS NUVENS COM OS ANJOS,
EM GLÓRIA E ESPLENDOR.

VEM (VEM) AMADO JESUS,
TUA IGREJA ESPERA
ANSIOSA POR VER
TUA FACE EM ESPLENDOR,
ESTAMOS A TE ESPERAR.

VEM (VEM) AMADO JESUS,
TUA IGREJA ESPERA
ANSIOSA POR VER
TUA FACE EM ESPLENDOR,
ESTAMOS A TE ESPERAR.
/FINAL
(JESUS) ESTAMOS A TE ESPERAR (2X)
');
