INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('58c44902-cc50-4213-8d48-a9f458124591', 'Ouço uma voz tão suave', '499', 'Jakeline Viana Bahiense', 'Básico', 'Am', 'Volta de Jesus e Eternidade', 'OUÇO UMA VOZ TÃO SUAVE,
UMA VOZ COMO DAS ÁGUAS,
QUE SAI DO TRONO DO SENHOR
DIZENDO ASSIM COM AMOR:

*CORO
"IGREJA, BREVEMENTE VOLTAREI,
TUAS LÁGRIMAS EU ENXUGAREI,
TENHO OUVIDO O TEU CLAMOR,
TENHO ACEITO O TEU LOUVOR";
COMO EU TE AMO, TU ÉS O MEU AMOR.
/INSTRUMENTOS

"ESTOU À DESTRA DE MEU PAI,
INTERCEDENDO, POR TODOS VÓS."
E QUERO OUVI-LO DIZER:
"EIS O MOMENTO DA IGREJA SUBIR."

*CORO
"IGREJA, BREVEMENTE VOLTAREI,
TUAS LÁGRIMAS EU ENXUGAREI,
TENHO OUVIDO O TEU CLAMOR,
TENHO ACEITO O TEU LOUVOR";
COMO EU TE AMO, TU ÉS O MEU AMOR.
/FINAL
COMO EU TE AMO, TU ÉS O MEU AMOR.
');
