INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5902a4a7-85d4-4ccd-ae4a-d53e9d2c8f29', 'No caminho, ele me guiará', '104', 'J. Camargo Jr', 'Fox', 'E', 'Crianças e Adolescentes', 'NO CAMINHO ELE ME GUIARÁ,
ELE QUER BEM A TODO PECADOR,
O SEU AMOR POR MIM, VOCÊ OUVIU?
DEUS GOSTA DE VOCÊ.

CORO
DEUS GOSTA DE VOCÊ (2X)
O SEU AMOR VOCÊ VERÁ
POR TODA A PARTE QUE OLHAR;
DEUS GOSTA DE VOCÊ.

O SOL DOURADO ELE FAZ NASCER,
AS LINDAS FLORES ELE FAZ ABRIR,
QUANDO O DESERTO CHORA A CHUVA CAI,
DEUS GOSTA DE VOCÊ.
');
