INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('593b0444-5954-4642-b46d-7dff28357cd1', 'Como Cristo Ensinou', '430', 'Sérgio Paulo Ferreira de Matos', 'Básico 2', 'Dm', 'Santificação e Derramamento', 'COMO CRISTO ENSINOU PARTILHAMOS DESTE PÃO,
O SEU CORPO REPARTIDO EM COMUNHÃO,
E DO CÁLICE BEBAMOS,
QUE É SEU SANGUE DERRAMADO,
PREÇO PAGO PELA NOSSA SALVAÇÃO;

E LEMBRAMOS ESSE DIA,
ESSA NOITE TÃO SOMBRIA
EM QUE ELE NO JARDIM AO PAI CLAMOU;
E TRAÍDO E ABANDONADO
FOI NA CRUZ SACRIFICADO,
O CORDEIRO NOSSA CULPA EXPIOU.

DO SEU LADO TRASPASSADO
PELO NOSSO VIL PECADO,
NOS GEROU PRA SERMOS SUA POSSESSÃO;
UM SÓ CORPO FEZ DE NÓS,
UM SÓ POVO, UM SÓ PÃO,
BATIZOU-NOS COM A MESMA SANTA UNÇÃO;

NO LUGAR DA SUA DOR HÁ PRA NÓS GOZO E LOUVOR,
NOSSO CÁLICE TRANSBORDA DE ALEGRIA;
POIS A VIDA NOS FOI DADA, A VITÓRIA ALCANÇADA
POR JESUS, O NOSSO AMADO SALVADOR.

POR ESPELHO NÓS JÁ VEMOS,
POR ENIGMA PERCEBEMOS
MARAVILHAS QUE ELE VAI NOS REVELAR,
AS MORADAS ETERNAIS NOS LUGARES CELESTIAIS
QUE JESUS JUNTO DO PAI FOI PREPARAR.
');
