INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5996c4bc-f0d4-4565-b847-187c7ec7c7ff', 'Como é bom servir ao Senhor', '182', 'Antônio Lopes da Silva,', 'Básico', 'C', 'Dedicação', 'CANTAR 2X
COMO É BOM SERVIR AO SENHOR,
OUVIR SUA VOZ A ORIENTAR:
"VAI, MEU SERVO, FALAR DO MEU AMOR"
E PODER DIZER DE TODO O CORAÇÃO:
EIS-ME AQUI.

CANTAR 2X
E MELHOR AINDA É SABER
QUE NÃO VOU SOZINHO.
O SENHOR VAI ADIANTE, ME DANDO CONDIÇÃO
PARA A SUA OBRA REALIZAR.
/FINAL
PARA A SUA OBRA REALIZAR.
');
