INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('59aab823-7478-4bb9-bf3d-3d4aea544995', 'O amor de Deus por nós', '141', 'Jackson de Halley Fernandes Fontes', 'Novo', 'A', 'Dedicação', 'O AMOR DE DEUS POR NÓS
É COMO O SOL QUE BRILHA EM SEU PODER;
/CANTAR 2X
EM JESUS MOSTROU TODO O SEU AMOR,
REVELANDO ASSIM O SEU QUERER.
/INSTRUMENTOS

QUANDO DEUS TOCOU MEU SER,
EU LHE ENTREGUEI TODO O MEU CORAÇÃO;
/FINAL 2X
SUA PAZ SENTI INUNDAR MEU SER
E O SEU AMOR ME TRANSFORMAR.
');
