INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('59c41f1b-285d-49c4-b50c-a8975047c711', 'Jesus De Nazaré (Coro Masculino)', '', '', '', '', '', 'QUE GRANDE REUNIÃO CONVOCADA ALÍ,
DA COLINA SE ACHAVA AO PÉ,
OLHANDO MELHOR ENTRE ELES VI
A JESUS DE NAZARÉ.
VI CEGO EM MOMENTOS TORNAR A VER,
ENTREVADO FICAR DE PÉ,
E TODOS GOZAVAM REAL PRAZER,
EM JESUS DE NAZARÉ.

CORO
JESUS CRISTO, MEU MESTRE DIVINO
PRA SEMPRE POR TI VIVEREI
A VIDA SERÁ QUAL UM HINO
EM TI MUI AMADO REI.

INDAGAM OS PRÍNCIPES ENTRE SI,
TODOS QUEREM SABER QUEM É,
O HOMEM HUMILDE QUE ESTÁ ALÍ,
É JESUS DE NAZARÉ.
O MAR SE AQUIETA AO MANDO SEU,
O OPRIMIDO LIBERTA ATÉ,
ELE É O NOSSO PÃO
QUE DESCEU DO CÉU,
JESUS DE NAZARÉ.

SE GRANDE QUAIS ONDAS AS LUTAS SÃO,
SE JÁ QUASE VACILA A FÉ,
ACALMA À TORMENTA NO CORAÇÃO,
JESUS DE NAZARÉ.
A ÁGUA DA VIDA A TODOS DÁ,
AO CONTRITO ELE SALVARÁ,
MEU RUDE CAMINHO EM SUA MÃO
ESTÁ, JESUS DE NAZARÉ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('59c41f1b-285d-49c4-b50c-a8975047c711', '45ab58b2-d293-45c7-aa75-090fcd968b24');
