INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('59cebd65-d240-441c-93a2-2325adc7429b', 'Como é bom saber', '054', 'H. H. Lemmel', 'Fox', 'G', 'Crianças e Adolescentes', 'COMO É BOM SABER QUE JESUS CRISTO
FOI MENINO ASSIM COMO EU,
QUE BRINCAVA E TRABALHAVA
COMO UM JOVEM GALILEU.

CORO
QUE PRAZER CONHECER CRISTO
QUE TAMBÉM FOI MENINO AQUI
E SABER QUE NO CÉU LINDO,
QUER TER-ME JUNTO A SI!

E É MELHOR SABER QUE JESUS CRISTO
JÁ SUBIU LÁ PARA O CÉU
E PREPARA UM LUGARZINHO
DE UM MENINO, ASSIM, COMO EU.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('59cebd65-d240-441c-93a2-2325adc7429b', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
