INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('59d84bec-c850-4477-8ae0-22f6cdea07fe', 'Estende tua mão', '289', 'Ronaldo Duarte Barroso', 'Canção', 'A', 'Grupo de Louvor', 'CANTAR 2X
ESTENDE TUA MÃO
AO DEUS QUE TE AMA,
ABRE O CORAÇÃO
AO DEUS QUE TE GUARDA;
SÓ ELE SABERÁ
TEUS PROBLEMAS RESOLVER,
Ó ABRE O TEU CORAÇÃO A DEUS.

ELE SERÁ TEU PASTOR,
SÓ ELE TE GUIARÁ
JUNTO ÀS ÁGUAS TRANQUILAS,
REFRIGERA TUA VIDA,
ELE TE MOSTRARÁ A SALVAÇÃO.

SÓ ESTENDE TUA MÃO
AO DEUS QUE TE AMA,
ABRE O CORAÇÃO
AO DEUS QUE TE GUARDA;
SÓ ELE SABERÁ
TEUS PROBLEMAS RESOLVER,
/Ó ABRE O TEU CORAÇÃO A DEUS. (2X)
');
