INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5a41b043-c5db-4580-98ec-00ab9c74ce66', 'Quem tem ouvidos', '', '', 'Fox/Toada', '', 'Avulso Cias', 'QUEM TEM OUVIDOS
OUÇA O QUE O ESPÍRITO DIZ ÀS IGREJAS;
QUEM TEM OUVIDOS
OUÇA O QUE O ESPÍRITO DIZ ÀS IGREJAS.

JESUS VIRÁ, EM BREVE VIRÁ!
JESUS VIRÁ, À PORTA ELE ESTÁ!

QUEM TEM OUVIDOS
OUÇA O QUE O ESPÍRITO DIZ ÀS IGREJAS.
/
GUARDA O QUE TENS PARA QUE NINGUÉM
TOME A TUA COROA.

GUARDA O QUE TENS,
EM BREVE ELE VEM!
GUARDA O QUE TENS,
JESUS PRESTO VEM!
FINAL
QUEM TEM OUVIDOS
OUÇA O QUE O ESPÍRITO DIZ ÀS IGREJAS.
');
