INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5b9f8e39-79eb-4513-aaf8-ff90f5a45150', 'Vou para o meu lar', '200', 'K.D.O.', 'Fox', 'D', 'Crianças e Adolescentes', 'CORO 2X
VOU PARA O MEU LAR,
JESUS JÁ PREPAROU O MEU LUGAR.

ESTÁ CHEGANDO A HORA DA PARTIDA,
JESUS JÁ VEM ME BUSCAR.
A TROMBETA VAI ECOAR
E VOU PARA O MEU LAR.

MINHA CANDEIA ESTÁ BEM ACESA
E ÓLEO NA BOTIJA TAMBÉM HÁ.
A TROMBETA VAI ECOAR
E VOU PARA O MEU LAR.
');
