INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5baf9caa-490e-4a86-8e90-c366de620821', 'Nas batalhas sou um vencedor (Armadura de Deus)', '152', 'C.M.V.C.S.', 'Marcha Marcial', 'C', 'Crianças e Adolescentes', 'NAS BATALHAS SOU UM VENCEDOR,
USO AS ARMAS ESPIRITUAIS.
REVESTIDO DE TODA ARMADURA DE DEUS,
SEREI FORTALECIDO NO SENHOR.

TENHO CINGIDOS
OS LOMBOS COM A VERDADE,
E VESTIDA A COURAÇA DA JUSTIÇA,
E CALÇADOS OS PÉS
NA PREPARAÇÃO DO EVANGELHO DA PAZ.

TENHO SOBRE TUDO, O ESCUDO DA FÉ,
E TAMBÉM O CAPACETE DA SALVAÇÃO,
E A ESPADA DO ESPÍRITO,
QUE É A PALAVRA DE DEUS.

NAS BATALHAS SOU UM VENCEDOR,
USO AS ARMAS ESPIRITUAIS,
REVESTIDO DE TODA ARMADURA DE DEUS,
SEREI FORTALECIDO NO SENHOR
E NA FORÇA DO SEU PODER.
');
