INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5bd1d53a-236c-4b26-bf5d-ff4a1cf8e63b', 'Cidade Eternal', 9, '', 'Básico', 'Em', 'Avulsos', 'CONSTRANGIDOS PELO AMOR DO NOSSO DEUS,
CAMINHAMOS PARA A NOVA JERUSALÉM;
PERSEGUIDOS, MAS NÃO DESAMPARADOS,
SEGUIREMOS SEGUROS PARA A CIDADE ETERNAL.

*CORO
EM RUAS DE OURO, SENHOR, ANDAREMOS,
ÀS MARGENS DO RIO DA VIDA TE BENDIREMOS,
RIO CLARO COMO CRISTAL PROCEDENDO DO TRONO,
DO TRONO DE DEUS E DO CORDEIRO.
INIGUALÁVEL, INCOMPARÁVEL, INDESCRITÍVEL,
O QUE DEUS PREPAROU PARA OS SEUS SALVOS E REMIDOS.
/INSTRUMENTOS

DESTE MUNDO NÓS SEREMOS ARREBATADOS,
COM O CORDEIRO NAS NUVENS NOS ENCONTRAREMOS;
NÃO HAVERÁ MAIS DOR E NÃO HAVERÁ PRANTO,
SÃO PALAVRAS FIÉIS E VERDADEIRAS PROFERIDAS POR DEUS.

*CORO
EM RUAS DE OURO, SENHOR, ANDAREMOS,
ÀS MARGENS DO RIO DA VIDA TE BENDIREMOS,
RIO CLARO COMO CRISTAL PROCEDENDO DO TRONO,
DO TRONO DE DEUS E DO CORDEIRO.
INIGUALÁVEL, INCOMPARÁVEL, INDESCRITÍVEL,
O QUE DEUS PREPAROU PARA OS SEUS SALVOS E REMIDOS.
/FINAL
INIGUALÁVEL, INCOMPARÁVEL, INDESCRITÍVEL,
O QUE DEUS PREPAROU PARA OS SEUS SALVOS E REMIDOS. (2X)
');
