INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5bff07bb-12f4-4502-90d1-65f4254f7ece', 'Tua graça me basta, ó Senhor', '', '', '', '', 'Avulso', 'CANTAR 2X
A TUA GRAÇA ME BASTA
A TUA GRAÇA ME SUSTENTA SENHOR
QUANDO SINTO QUE A LUTA COMEÇA ME DESANIMAR
CLAMO AO SENHOR E DIGO: QUE A TUA GRAÇA ME BASTA

*CORO
AGRADEÇO, SENHOR POR ME SUSTENTAR.
AGRADEÇO, SENHOR, SEM TI NÃO SABERIA CAMINHAR.
TUA FORÇA ME AUXILIA, TEU ESPÍRITO ME GUIA
E ME DIZ: "MEU SERVO LEVANTA E CONTINUE A CAMINHAR."

EU SOU CONTIGO, FILHO, NA JORNADA ATÉ O FIM.
NÃO DESISTA SE ESPINHOS NO CAMINHO TE FERIR.
DERRAMO SOBRE TI MEU ÓLEO PRA TUAS FERIDAS SARAR.
TE ABRAÇO COM CARINHO E TE FAÇO LEMBRAR
QUE A MINHA GRAÇA TE BASTA
/INSTRUMENTOS

*CORO
AGRADEÇO, SENHOR POR ME SUSTENTAR.
AGRADEÇO, SENHOR, SEM TI NÃO SABERIA CAMINHAR.
TUA FORÇA ME AUXILIA, TEU ESPÍRITO ME GUIA
E ME DIZ: "MEU SERVO LEVANTA E CONTINUE A CAMINHAR."
FINAL
PORQUE A MINHA GRAÇA TE BASTA
');
