INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5c344383-bf05-4277-8eca-01ef0ef88708', 'Só Tu és Senhor', '388', 'Jorgemar Souza Madeira', 'Básico', 'E', 'Santificação e Derramamento', 'CANTAR 2X
SÓ TU ÉS, SENHOR,
SÓ TU ÉS, SENHOR,
A RAZÃO DO MEU VIVER.
/SONDA, Ó PAI, TODO O MEU CORAÇÃO,
FAZ-ME OUVIR TUA DOCE VOZ, SENHOR.

*CORO
DO TEU SANTO ESPÍRITO, EM MIM,
Ó VEM TRANSBORDAR,
VEM EM MIM REALIZAR
TODO O TEU QUERER.
/VEM, Ó JESUS, DERRAMAR TUA PAZ,
ENCHE-ME DE GOZO, TUA LUZ ME SATISFAZ.

*CORO
DO TEU SANTO ESPÍRITO, EM MIM,
Ó VEM TRANSBORDAR,
VEM EM MIM REALIZAR
TODO O TEU QUERER.

SEM TEU AMOR NÃO SEI VIVER, SENHOR;
SEM TUA GRAÇA EU NÃO SOU FELIZ,
/CANTAR 2X
POIS TU ÉS TODA A RAZÃO
E O SENTIDO DE VIVER,
/INSTRUMENTOS

FINAL 2X
SÓ TU ÉS, SENHOR,
SÓ TU ÉS, SENHOR,
A RAZÃO DO MEU VIVER.
');
