INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5c964353-736c-40c6-b393-d644839fcb52', 'Jesus, somente tu', '', '', '', '', '', 'JESUS, SOMENTE TU,
A MINHA SEDE PODE SACIAR,
NADA TEM MAIS VALOR,
DO QUE BUSCAR TUA FACE
E TE ADORAR.

*CORO
SÓ TU ÉS A LUZ DA MINHA VIDA,
SÓ TU DÁS SENTIDO AO MEU VIVER,
SÓ TU VÊS A MINHA ALMA FERIDA,
SÓ TU TENS PODER PRA EU VENCER.

JESUS, EU TE AMO,
VEM MINHA SEDE AGORA SACIAR;
ENCHE MINH’ALMA COM TEU AMOR
ATÉ EU TRANSBORDAR.

*CORO 2X
SÓ TU ÉS A LUZ DA MINHA VIDA,
SÓ TU DÁS SENTIDO AO MEU VIVER,
SÓ TU VÊS A MINHA ALMA FERIDA,
SÓ TU TENS PODER PRA EU VENCER.
');
