INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5d72a585-e246-4671-86fe-a54189d34a29', 'Jerusalém, cidade do meu Rei', '181', 'E.H.M.R.', 'Country', 'Gm', 'Crianças e Adolescentes', 'JERUSALÉM, CIDADE DO MEU REI,
A CADA DIA ANSEIO ESTAR ALI;
CONTEMPLAREI A FACE DO SENHOR,
AQUELE QUE ENTREGOU
SUA VIDA POR MIM.

CANTAR 2X
JAMAIS A MORTE VEREI,
POIS VIDA ETERNA ALCANCEI
QUANDO ENTREGUEI
MEU CORAÇÃO PARA JESUS.
');
