INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5d976429-f92f-4c14-97d4-e85ace8df44f', 'Há Um Amigo Sempre Junto', '322', 'Autor Desconhecido', 'Básico', 'D', 'Consolo e Encorajamento', 'HÁ UM AMIGO SEMPRE JUNTO A MIM,
HÁ UM AMIGO QUE ME OUVE,
HÁ UM AMIGO TÃO QUERIDO, SIM,
PRECIOSO ELE É.

CORO
QUANDO OUÇO A VOZ DO VENTO,
QUANDO TODA AFLIÇÃO ME SOBREVEM,
ELE DIZ: "ESTOU CONTIGO",
PRECIOSO É JESUS.

SUAS PROMESSAS ELE CUMPRE;
NÃO HÁ COMO ELE FALHAR;
MINHA PARTE QUERO EU FAZER,
PRECIOSO ELE É.
');
