INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5dc0db34-4388-4669-a2e8-d8331409c863', 'Medo tens que o tentador te vá vencer', '306', 'Let.: Ada Blenkhorn; Trad: Antônio Querino Lomba; Mús.: Charles Hutchinson Gabriel', 'Fox', 'E', 'Consolo e Encorajamento', 'MEDO TENS QUE O TENTADOR TE VÁ VENCER?
LUZ TE FALTA E ONDE ESTÁS NÃO PODES VER?
ABRE O CORAÇÃO E DEIXA CRISTO ENTRAR
E O SOL EM TI RAIAR.

CORO
DEIXA A LUZ DO CÉU ENTRAR,
DEIXA O SOL EM TI NASCER;
ABRE O CORAÇÃO E DEIXA CRISTO ENTRAR,
E O SOL EM TI NASCER.

FRACA ESTÁ A TUA FÉ NO SALVADOR?
DEUS NÃO OUVE AS TUAS PRECES COM FAVOR?
ABRE O CORAÇÃO E DEIXA CRISTO ENTRAR
E O SOL EM TI RAIAR.

QUERES IR ANDANDO ALEGRE PARA O CÉU?
IGNORANDO TODO O NEGRO E DENSO VÉU?
ABRE O CORAÇÃO E DEIXA CRISTO ENTRAR
E O SOL EM TI RAIAR.
');
