INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5e00eb0b-7a9f-4268-add8-5ed64f60f3b9', 'Das profundezas clamo a ti, Senhor', '295', 'Sl.130; Adapt. Let. Ademar Hugo Rosa; Mús.: Ariosvaldo', 'Balada', 'Am', 'Consolo e Encorajamento', 'DAS PROFUNDEZAS A TI CLAMO, Ó SENHOR,
SENHOR, ESCUTA A MINHA VOZ; 
SEJAM OS TEUS OUVIDOS ATENTOS
À VOZ DAS MINHAS SÚPLICAS;

SE TU, SENHOR,
OBSERVARES AS INIQUIDADES,
SENHOR, QUEM SUBSISTIRÁ?
MAS CONTIGO ESTÁ O PERDÃO
PARA QUE SEJAS TEMIDO,
AGUARDO O SENHOR,
A MINHA ALMA O AGUARDA.

E ESPERO NA SUA PALAVRA,
A MINH''ALMA ANSEIA PELO SENHOR
MAIS DO QUE OS GUARDAS
PELO ROMPER DA MANHÃ,
SIM, DO QUE AQUELES
QUE ESPERAM PELA MANHÃ.

ESPERA, ISRAEL, NO SENHOR,
PORQUE NO SENHOR HÁ MISERICÓRDIA
/CANTAR 2X
E NELE HÁ ABUNDANTE REDENÇÃO,
E ELE REMIRÁ A ISRAEL
DE TODAS AS SUAS INIQUIDADES.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('5e00eb0b-7a9f-4268-add8-5ed64f60f3b9', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
