INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5e2477d1-8b4c-463e-bc97-0f65b167fb45', 'Se Deus é Por Nós', '331', 'Márcia Castro de Freitas', 'Básico', 'G', 'Consolo e Encorajamento', 'SE DEUS É POR NÓS,
QUEM SERÁ CONTRA NÓS?
AQUELE QUE NEM MESMO
O SEU FILHO POUPOU
ANTES O ENTREGOU À CRUZ.

SE O SENHOR CONOSCO ESTÁ,
QUEM NOS CONDENARÁ?
AQUELE QUE NOS ESCOLHEU
É QUEM NOS JUSTIFICA.

*CORO
JESUS RESSUSCITOU, RESSUSCITOU,
VIVO ESTÁ AQUI ENTRE NÓS;
QUEM IRÁ NOS SEPARAR DO AMOR DE DEUS?

*CORO
NEM A MORTE OU TRIBULAÇÃO,
NEM ALTURA OU PROFUNDIDADE
PODEM NOS SEPARAR DO AMOR DE DEUS,
QUE ESTÁ EM CRISTO JESUS,
CRISTO JESUS, NOSSO SENHOR,
CRISTO JESUS.

MAS EM TODAS ESTAS COISAS
SOMOS MAIS DO QUE VENCEDORES
POR AQUELE QUE NOS AMOU
E A JESUS NOS REVELOU.

*CORO
JESUS RESSUSCITOU, RESSUSCITOU,
VIVO ESTÁ AQUI ENTRE NÓS;
QUEM IRÁ NOS SEPARAR DO AMOR DE DEUS?

*CORO
NEM A MORTE OU TRIBULAÇÃO,
NEM ALTURA OU PROFUNDIDADE
PODEM NOS SEPARAR DO AMOR DE DEUS,
QUE ESTÁ EM CRISTO JESUS,
CRISTO JESUS, NOSSO SENHOR,
CRISTO JESUS.

FINAL
NOSSO SALVADOR, CRISTO JESUS,
NOSSO SALVADOR.
');
