INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5e4e82a2-d3af-4200-8739-d4bf90a44217', 'Quando a Tristeza Surgir', '301', 'Amadeu Loureiro Lopes/Everaldo Cavalcante Lima', 'Marcha', 'Em', 'Consolo e Encorajamento', 'QUANDO A TRISTEZA SURGIR
E O MUNDO TE ENGANAR,
LEMBRA-TE QUE JESUS CRISTO
COM SEU SANGUE TE PODE SALVAR.

CORO 2X
CANTA FELIZ E ORA COM FERVOR,
O SANGUE DE JESUS
MOSTROU-NOS SEU AMOR.

QUANDO A ALEGRIA VOLTAR
E A PAZ INVADIR O TEU SER,
DIZE ALELUIA A JESUS
POIS SEU SANGUE TEM ESSE PODER.
');
