INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5e5ad797-2997-4763-b633-d20fe08596b2', 'No Silêncio da Noite', '062', 'Clarício Ribeiro do Rosário; Everaldo Cavalcante Lima', 'Novo', 'G', 'Invocação e Comunhão', 'NO SILÊNCIO DA NOITE,
EU ORO AO SENHOR;
NO SILÊNCIO DA NOITE,
SUPLICO AO SENHOR;

MURMURO, BAIXINHO,
ESTA LINDA CANÇÃO;
NO SILÊNCIO DA NOITE,
EU FAÇO A MINHA ORAÇÃO.

AS ESTRELAS DO CÉU ESTÃO A CINTILAR,
E EU, AO SENHOR, ESTOU A SUPLICAR;
MURMURO, BAIXINHO,
ESTA LINDA CANÇÃO;
NO SILÊNCIO DA NOITE,
EU FAÇO A MINHA ORAÇÃO.

E QUANDO PELA ALVORADA RETORNO AO SENHOR,
DELE RECEBO BÊNÇÃOS E PODER PRA VENCER;
ENTREGO MINHA VIDA AO SERVIÇO DO REI;
NO SILÊNCIO DA NOITE,
EU FAÇO A MINHA ORAÇÃO.
');
