INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5ed4de0f-e006-4fd2-80ba-b4c0bd359244', 'Senhor me chego a Ti', 9, 'Fábio Gueiros Samú', 'Balada', 'A', 'Clamor', 'SENHOR, ME CHEGO A TI,
NESTA HORA DE ORAÇÃO;
SENHOR, ME CHEGO A TI,
PRA PEDIR-TE MAIS COMUNHÃO E AMOR.

HUMILDE E FRACO SOU,
FAZE-ME VIVER NA TUA LUZ;
LIBERTA-ME, SENHOR,
Ó VEM PASSAR O TEU SANGUE
E PURIFICA-ME, SENHOR.
');
