INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5ee83a45-c62c-4ed5-805d-26c5953a98e8', 'Somos Teu Povo e Queremos', '420', 'Paulo Luis de Carvalho', 'Balada', 'D', 'Santificação e Derramamento', 'SOMOS TEU POVO E QUEREMOS
TUA VONTADE FAZER;
LIVRA-NOS DO VELHO HOMEM
E CONCEDE-NOS UM NOVO VIVER,
PARA QUE POSSAMOS
SEMPRE TE OBEDECER

CANTAR 2X
E DEFINIR NOSSAS VIDAS EM TI
E SERMOS TUA IGREJA FIEL.

ESTA É UMA OBRA ETERNA
QUE O TEU ESPÍRITO NOS TRAZ,
/FINAL 2X
TODOS EM UM SÓ LOUVOR CANTARÃO:
MARANATA, JESUS VOLTARÁ!
');
