INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5f96a05b-082d-4ac0-81f4-4d6f131a26ad', 'Vem Espirito de Deus', '471', 'Autor Desconhecido', 'Básico', 'C', 'Corinhos', 'CANTAR 2X
VEM, ESPÍRITO DE DEUS,
EU PRECISO DE TI.

CORO
DE JESUS SERÁ A GLÓRIA
E DELE SERÁ O LOUVOR,
VEM, ESPÍRITO DE DEUS,
EU PRECISO DE TI.

CANTAR 2X
MESMO SENDO PEQUENINO
EU PRECISO DE TI,
');
