INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5fe338e7-22c9-49a1-b5fc-3eb0b2115a2f', 'Nas lindas moradas', '548', 'Jorgemar Souza Madeira', 'Novo', 'D', 'Volta de Jesus e Eternidade', 'NAS LINDAS MORADAS EM BREVE ESTAREI
LOUVANDO PRA SEMPRE A JESUS,
MEU GRANDE REI;
NAS RUAS DE OURO SEI QUE VOU ANDAR
E JUNTO COM OS ANJOS LOUVAR.

*CORO
A JESUS, O REI, O LEÃO DA TRIBO DE JUDÁ,
QUE VENCEU E O LIVRO ABRIRÁ.

O SEU ROSTO LINDO NO CÉU HEI DE VER,
NO SEU MEIGO OLHAR SENTIREI
QUANTO ME AMOU;
SUAS MARAVILHAS IREI CONTEMPLAR
E JUNTO COM OS ANJOS LOUVAR.

*CORO 2X
A JESUS, O REI, O LEÃO DA TRIBO DE JUDÁ,
QUE VENCEU E O LIVRO ABRIRÁ.
/FINAL
E O LIVRO ABRIRÁ, E O LIVRO ABRIRÁ.
');
