INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('5ffc1838-f3db-410c-b00e-99d66f73bcb4', 'Santo é seu nome', '628', 'Autor Desconhecido', 'Valseado', 'G', 'Louvor', 'SANTO É SEU NOME,
TAL QUAL ESSE EXCELSO NOME JAMAIS OUVI;
DOCE, PURO E PERFEITO É,
ESSE NOME SE TRADUZ EM LUZ,
EM CHORAR E EM SORRIR.

*CORO
SANTO NOME DE JESUS,
MAIS MARAVILHOSO QUE OUTRO QUALQUER.
SANTO NOME DE JESUS,
DÁ CONSOLAÇÃO E DOCE AMOR
SEJA NO LUGAR QUE FOR,
SANTO É O NOME DE JESUS.
/INSTRUMENTOS

SANTO É SEU NOME,
MAIS PRECIOSO QUE RIQUEZAS
DO MUNDO, SIM;
SOA EM MIM EM PERFEITO TOM
TAL QUAL EM CELESTIAL CORO QUE
NUNCA UM HOMEM PÔDE OUVIR.

*CORO 2X
SANTO NOME DE JESUS,
MAIS MARAVILHOSO QUE OUTRO QUALQUER.
SANTO NOME DE JESUS,
DÁ CONSOLAÇÃO E DOCE AMOR
SEJA NO LUGAR QUE FOR,
SANTO É O NOME DE JESUS.
');
