INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6043cb2b-c1b8-4adb-b45a-d9d0617732b4', 'Vitória Sobre Vitória', '056', 'Cristina Manera Vianna', 'Balada', 'Dm', 'Crianças e Adolescentes', 'VITÓRIA SOBRE VITÓRIA A TI PERTENCE
POIS O PREÇO LÁ NA CRUZ TU JÁ PAGASTE;
TEU SANGUE PURO DERRAMASTE,
ALELUIA, GLÓRIA AO REI!
SANTO É O DEUS FORTE! (2X)

O ESPÍRITO ESTÁ LUTANDO CONTRA A CARNE,
MAS A VITÓRIA JÁ FOI DECRETADA;
TUA VONTADE PREVALECEU,
ALELUIA, GLÓRIA AO REI!
SANTO É O DEUS FORTE! (2X)
');
