INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6049ed46-fc35-4bb4-801f-9393f7be52f7', 'Tenho grande gozo', '130', 'Francisco Custódio da Veiga', 'Fox Abafado', 'D', 'Dedicação', 'TENHO GRANDE GOZO 
DESDE QUE REPOUSO
NESTE CRISTO AMADO 
QUE POR MIM FOI DADO;

CANTAR 2X
QUE DESCEU DA GLÓRIA,
SUPORTOU POBREZA
PRA ME DAR VITÓRIA
E ME DAR RIQUEZA.

QUANTA DOR SENTIA
LÁ NA CRUZ SOMBRIA
QUANDO PENDURADO 
PELO MEU PECADO;

CANTAR 2X
NESSA CRUZ ERGUIDA,
OH! QUE AMOR PROFUNDO!
ENTREGOU SUA VIDA
PRA DAR VIDA AO MUNDO.

MEU DESEJO AGORA, 
PELA VIDA AFORA,
É SEGUIR AO LADO 
DESSE CRISTO AMADO;

CANTAR 2X
QUERO, DIA A DIA,
MAIS E MAIS AMÁ-LO
E, COM ALEGRIA, PARA SEMPRE HONRÁ-LO.
');
