INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6107db3b-82d4-46d6-a19d-dfade4579a66', 'Neste dia especial', 85, 'I.B.J.', 'Country', 'C', 'Crianças e Adolescentes', 'NESTE DIA ESPECIAL,
VOU LHE APRESENTAR JESUS,
QUE DISSIPA TODO MAL
E FAZ RAIAR EM NÓS SUA LUZ.

CORO
JESUS É O BOM AMIGO,
ABRIGO NO TEMPORAL,
QUE NOS LIVRA DO PERIGO
E POR NÓS VENCEU O MAL.

ABRA SEU CORAÇÃO
E VENHA CONHECER JESUS,
COM AMOR E SEGURANÇA
À VIDA ETERNA NOS CONDUZ.

FINAL
SIM, POR NÓS VENCEU O MAL.
');
