INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('611d9f52-726f-4cba-a796-62bae71a6b0b', 'Este mundo não tem a sua paz', '281', 'Luciana Monteiro Carneiro Simora', 'Básico', 'E', 'Dedicação', 'ESTE MUNDO NÃO TEM A SUA PAZ,
ESTE MUNDO NÃO CONHECE O QUE É AMOR,
ESTE MUNDO NÃO SABE O QUE É SER FELIZ,
EU TAMBÉM NÃO SABIA,
MAS JESUS UM DIA ME ENCONTROU.

JESUS BUSCOU-ME
COM SEUS BRAÇOS DE TERNURA,
FALOU-ME DE UM AMOR QUE JAMAIS CONHECI,
FEZ-ME ENTENDER O QUE É A SALVAÇÃO,
ENTÃO, ABRI O MEU CORAÇÃO.

*CORO
ELE É JESUS, (ELE É JESUS) (2X)
O AMOR VERDADEIRO QUE O HOMEM PODE TER.
/INSTRUMENTOS

JESUS BUSCOU-ME COM SEUS BRAÇOS DE TERNURA,
FALOU-ME DE UM AMOR QUE JAMAIS CONHECI,
FEZ-ME ENTENDER O QUE É A SALVAÇÃO,
ENTÃO, ABRI O MEU CORAÇÃO.

*CORO 2X
ELE É JESUS, (ELE É JESUS) (2X)
O AMOR VERDADEIRO QUE O HOMEM PODE TER.
');
