INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('61623189-b2d4-4eed-9e7b-85b4ba66ea4d', 'Cristo Me Dará', '354', 'Autor Desconhecido', 'Básico', 'D', 'Consolo e Encorajamento', 'CRISTO ME DARÁ A SUA PAZ,
SIM, GUARDARÁ MEU CAMINHO;
POR ONDE QUER QUE EU ANDAR, SENHOR,
A TUA LUZ ME GUIARÁ.

CORO
SÓ EM JESUS (SÓ EM JESUS)
EU POSSO CONFIAR, (EU POSSO CONFIAR)
ETERNAMENTE E EXALTAR (E EXALTAR)
COM ALEGRIA SEU SANTO NOME,
(GLORIOSO JESUS)
COMO É BOM VIVER O AMOR DE DEUS,
QUE PRECIOSO É TER JESUS EM MIM.

JESUS ME DARÁ O SEU AMOR,
MESMO EM LUTAS OU PROVAÇÕES,
COM SEU ESPÍRITO EM MINHA VIDA
NADA TEMEREI, SEMPRE O LOUVAREI, ATÉ O FIM.

FINAL
AMO AO SENHOR; LOUVO A JESUS!
CRISTO ESTÁ EM MIM!
');
