INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('61702185-5e16-4d72-b932-12c4a1adba3d', 'O nome do meu Senhor!', 59, 'I.L.S.P.', 'Básico', 'F', 'Crianças e Adolescentes', 'O NOME DO MEU SENHOR,
O QUE VENCEU A MORTE E A CRUZ,
O ÚNICO QUE É DIGNO DE LOUVOR,
O SEU NOME É JESUS!

*CORO
É FIEL, É A PAZ, É AMOR, É O SALVADOR!
É A ESPERANÇA ETERNA.

O MEU SENHOR DERRAMOU
O SEU PRECIOSO SANGUE NA CRUZ,
PERDOOU MEUS PECADOS, LAVOU-ME,
O SEU NOME É JESUS!

*CORO
É FIEL, É A PAZ, É AMOR, É O SALVADOR!
É A ESPERANÇA ETERNA.

AGORA VOU, FELIZ, TE ADORAR
POIS O TEU SANGUE ME LIMPOU.
CAMINHANDO VOU PARA A PÁTRIA,
Ó JESUS, VEM ME BUSCAR!

*CORO 2X
É FIEL, É A PAZ, É AMOR, É O SALVADOR!
É A ESPERANÇA ETERNA.
/FINAL
MINHA ESPERANÇA É JESUS!
');
