INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6186f9b1-5c8a-4a21-ac33-68376a2f37e5', 'Jerusalém (Suas ruas são de ouro)', '554', 'Jorgemar Souza Madeira', 'Balada', 'Dm', 'Volta de Jesus e Eternidade', 'JERUSALÉM, JERUSALÉM,
