INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('61d42e98-4a3b-42e1-b438-c73a15bd8bcd', 'Se Te Encontrares Triste e Cansado', '333', 'Fárell Farias Oliveira', 'Balada', 'A', 'Consolo e Encorajamento', 'SE TE ENCONTRARES TRISTE E CANSADO
E SE VACILARES NO TEU CAMINHAR,
NÃO TE DETENHAS, POIS NOS TEUS PASSOS,
EM TEUS CAMINHOS, DEUS PROVERÁ;
NÃO DESANIMES, À TUA VOLTA
ELE ESTARÁ, DEUS PROVERÁ.

*CORO 2X
CONFIA E ANDA, SEMPRE ORANDO,
SEMPRE CANTANDO, DEUS PROVERÁ.

NÃO TE DETENHAS, (DEUS PROVERÁ)
POIS NOS TEUS PASSOS,
(DEUS PROVERÁ)
EM TEUS CAMINHOS, DEUS PROVERÁ;
NÃO DESANIMES, (DEUS PROVERÁ)
À TUA VOLTA (DEUS PROVERÁ)
ELE ESTARÁ, DEUS PROVERÁ.
/INSTRUMENTOS

*CORO 2X
CONFIA E ANDA, SEMPRE ORANDO,
SEMPRE CANTANDO, DEUS PROVERÁ.
');
