INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('61d501de-1249-4f48-810e-014cb68c3951', 'Eu te amo, meu Jesus', '584', 'Amadeu Loureiro Lopes', 'Básico', 'C', 'Louvor', 'EU TE AMO, MEU JESUS,
POIS TU ÉS O REMIDOR,
RESGATASTE A MINHA ALMA
DA TRISTEZA E DA DOR,
EU TE AMO, MEU JESUS,
COMO É FORTE O MEU AMOR,
ALEGRASTE A MINHA ALMA
COM TUA PAZ E O TEU AMOR.

*CORO
EU TE AMO, MEU JESUS,
POIS ABRISTE PARA MIM
A PORTA DO JARDIM DA VIDA
QUE É SEM FIM;
A MINH''ALMA CANTA AGORA
O AMOR QUE VIVE EM MIM,
POIS MUDASTE O MEU SER, 
NÃO MAIS EU, CRISTO EM MIM.
/INSTRUMENTOS

EU TE AMO, MEU JESUS,
POIS TU ÉS O MEU PASTOR,
LEVA-ME COM ALEGRIA
AO BANQUETE DO AMOR;
A MINH''ALMA REJUBILA
POIS ÉS TUDO PARA MIM,
SOU HERDEIRO DE UM REINO,
DE UM REINO QUE É SEM FIM.

*CORO
EU TE AMO, MEU JESUS,
POIS ABRISTE PARA MIM
A PORTA DO JARDIM DA VIDA
QUE É SEM FIM;
A MINH''ALMA CANTA AGORA
O AMOR QUE VIVE EM MIM,
POIS MUDASTE O MEU SER, 
NÃO MAIS EU, CRISTO EM MIM. (3X)
');
