INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('61ee5ee1-7eeb-4cef-9978-b365dc609ce7', 'Ó grande Deus', '583', 'J. R. Silva Leite', 'Balada', 'G', 'Louvor', 'Ó GRANDE DEUS,
A TUA GRAÇA ENCHE O MEU CORAÇÃO,
TEU É O CÉU E NA TERRA TU ÉS SALVAÇÃO,
TEU É O MAR E AS FONTES DAS ÁGUAS TAMBÉM,
SÓ TU, SENHOR, ÉS A LUZ, ÉS A VIDA TAMBÉM.

CORO
NÃO SE ENCONTRA ENTRE OS POVOS DA TERRA
TÃO GRANDE AMOR,
NEM TAMBÉM NAS ESCARPAS DAS SERRAS
TÃO RICO AMOR,
NEM NAS NUVENS QUE PASSAM NOS ARES
HÁ TANTO AMOR,
MAS NO TRONO DA GLÓRIA SE ENCONTRA
ESTE SANTO AMOR.

Ó GRANDE DEUS, ME AJUDA NA TRIBULAÇÃO,
DÁ-ME PODER PRA PREGAR E FAZER ORAÇÃO,
DÁ-ME SABER PARA AQUI NESTA VIDA TRILHAR
E COMPREENDER
TEU AMOR, TUA GRAÇA SEM PAR.
');
