INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('61fc9206-6609-486c-ae83-a054af65410d', 'Jesus, o lírio do vales', '158', 'Cláudio Costa; Ernane Hott', 'Básico', 'D', 'Dedicação', 'JESUS, O LÍRIO DOS VALES,
JESUS, O GRANDE AMOR,
JESUS, O AMOR SUBLIME,
JESUS, O NOSSO SENHOR.

ELE É A PUREZA,
É O AMOR MAIOR,
É VIDA EM ABUNDÂNCIA,
É A PAZ SEM FIM.

JESUS, A ESTRELA DA MANHÃ,
A ROSA PERFUMADA,
UM RIO QUE TRANSBORDA
DE AMOR INFINITO.
');
