INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('62497d53-0540-437c-b091-f5172c1096cc', 'Em tuas pisadas', '147', 'M.L.M.B.O.', 'Fox', 'E', 'Crianças e Adolescentes', 'EM TUAS PISADAS 
COLOCO OS MEUS PÉS,
ASSIM BEM FIRMADO, NÃO VACILAREI;
OS TEUS PRECEITOS, SENHOR, OS GUARDEI.
AS TUAS PALAVRAS SÃO MEU ALIMENTO
VIVER NA TUA OBRA É O MEU SUSTENTO.

CANTAR 2X
QUE BOM SENHOR, CONHECER A JESUS.
CAMINHO, VIDA, VERDADE E LUZ.
/INSTRUMENTOS

EM TUAS PISADAS 
COLOCO OS MEUS PÉS,
ASSIM BEM FIRMADO, NÃO VACILAREI;
OS TEUS PRECEITOS, SENHOR, OS GUARDEI.
AS TUAS PALAVRAS SÃO MEU ALIMENTO
VIVER NA TUA OBRA É O MEU SUSTENTO.

CANTAR 2X
QUE BOM SENHOR, CONHECER A JESUS.
CAMINHO, VIDA, VERDADE E LUZ.
');
