INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6276ed52-6898-4c15-a961-7d0c4e42ef56', 'Confia e Ora', '378', 'E.M', 'Básico', 'D', 'Consolo e Encorajamento', 'CONFIA E ORA, CERTAMENTE
O SENHOR TE OUVIRÁ.
ENTREGA AGORA, EM SUAS MÃOS,
E TUDO VAI PASSAR, TUDO ELE MUDARÁ. (2X)

O TEU DEUS PODEROSO É
EM SUAS MÃOS VOCÊ AGORA ESTÁ.
MESMO EM TEMPESTADES,
OU NA FÚRIA DO MAR,
O SENHOR TE ESCONDERÁ.

O TEU DEUS ESTARÁ CONTIGO 
ONDE QUER QUE FOR
ELE É FIEL E NÃO FALHARÁ. 
CONFIA NO SENHOR,
ELE É FIEL E NÃO FALHARÁ,
CONFIA NO SENHOR.
/INSTRUMENTOS

FINAL
CONFIA E ORA,
CERTAMENTE O SENHOR TE OUVIRÁ.
ENTREGA AGORA, EM SUAS MÃOS,
E TUDO VAI PASSAR, TUDO ELE MUDARÁ. (2X)
QUE TUDO VAI PASSAR.
');
