INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('62f3a6b7-4d1f-4935-9bec-d1dea6bdd2d0', 'Perdoa-me, Senhor, segundo o Seu amor', '012', 'F.S.P.', 'Básico', 'C', 'Crianças e Adolescentes', 'PERDOA-ME SENHOR, SEGUNDO O SEU AMOR,
LAVA-ME COM O SANGUE DE JESUS
E ENVIA A TUA LUZ.
PURIFICA-ME, SENHOR, COM O SANGUE DE JESUS
NOVA CRIATURA EM TI EU SOU
PRONTO PARA O TEU LOUVOR.

FINAL 2X
POSSO AGORA TE ADORAR,
POSSO TE GLORIFICAR,
MEU CORAÇÃO LIBERTO ESTÁ
CHEIO DE ALEGRIA E PAZ.
');
