INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('639cbbd6-aadc-481c-90e5-c6ed7e5c669f', 'Fluirá como um rio', '435', 'James Beall', 'Básico 2', 'G', 'Santificação e Derramamento', 'FLUIRÁ COMO UM RIO,
COMO A CHUVA CAIRÁ,
COMO ORVALHO, SOBRE OS MONTES
E VALES COBRIRÁ!

E A GLÓRIA DO SENHOR, TODA TERRA ENCHERÁ
E O ESPÍRITO DE DEUS VIRÁ!
E O ESPÍRITO DE DEUS, E O ESPÍRITO DE DEUS,
E O ESPÍRITO DE DEUS VIRÁ!
');
