INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('63df03fd-0fde-4abf-aa66-81bb316e8562', 'Louvai Ao Senhor', '', '', '', '', '', 'LOUVAI AO SENHOR PORQUE ELE É BOM,
PORQUE A SUA BENIGNIDADE É PARA SEMPRE!
DIGA AGORA ISRAEL QUE A SUA BENIGNIDADE
É PARA SEMPRE!

INVOQUEI AO SENHOR NA ANGÚSTIA
E ELE ME OUVIU, O SENHOR ESTÁ COMIGO,
NÃO TEMEREI.

A MINHA ALMA TE BUSCOU PELA NOITE,
NA ALVORADA A TI CLAMEI,
TU OUVISTE A MINHA VOZ,
TE LOUVAREI.
');
