INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('63f82990-8b96-4ac6-9c04-7fe64f7c33b0', 'A Meu Senhor', '035', 'José Manuel Carvalho', 'Básico 2', 'C', 'Clamor', 'A MEU SENHOR E CRISTO JESUS
VENHO AGORA CLAMAR;
VEM COM TEU SANGUE LAVAR MINHAS VESTES,
VEM ME PURIFICAR.

CANTAR 2X
VEM LIBERTAR A MINH''ALMA,
JESUS, DE MIM VEM CUIDAR;
VEM COM TEU SANGUE LAVAR MINHAS VESTES,
VEM ME PURIFICAR.
/FINAL
VEM ME PURIFICAR.
');
