INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('642034d6-5fa3-4635-bbbf-104822e70bf3', 'Suba a Minha Oração', '061', 'Sérgio Paulo Ferreira de Matos', 'Básico 2', 'C', 'Invocação e Comunhão', 'SUBA A MINHA ORAÇÃO,
PERANTE A TUA FACE, COMO INCENSO; 
SEJA O LEVANTAR DE MINHAS MÃOS
COMO SACRIFÍCIO DA TARDE.

*CORO
ESCUTA-ME, SENHOR!
INCLINA OS TEUS OUVIDOS À MINHA VOZ,
QUANDO A TI CLAMAR.

NÃO ME DEIXES CAMINHAR
SEM TER TUA PRESENÇA,
Ó SENHOR, MEU DEUS!
"SIM, CONTIGO IRÁ MINHA PRESENÇA
PARA TE FAZER DESCANSAR."

*CORO 2X
ESCUTA-ME, SENHOR!
INCLINA OS TEUS OUVIDOS À MINHA VOZ,
QUANDO A TI CLAMAR.
');
