INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6474622e-098c-4d1e-9690-3a93fd5e5514', 'Consolai, Consolai o Meu Povo', '328', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'E', 'Consolo e Encorajamento', 'CORO
"CONSOLAI, CONSOLAI O MEU POVO"
DIZ O VOSSO DEUS;
"PREPARAI, PREPARAI
O CAMINHO DO SENHOR."

FALAI BENIGNAMENTE A JERUSALÉM:
SUA INIQUIDADE PERDOADA ESTÁ
E JÁ RECEBEU EM DOBRO DO SENHOR
POR TODOS OS SEUS PECADOS.

ENDIREITAI NO ERMO VEREDA AO NOSSO DEUS
E A GLÓRIA DO SENHOR SE MANIFESTARÁ,
LEVANTA A TUA VOZ, PROCLAMA FORTEMENTE:
EIS AQUI ESTÁ O VOSSO DEUS.
');
