INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('64fef8eb-93dc-4ec8-abef-58ea7c43b488', 'Como Ovelhas Perdidas', '', '', '', '', '', 'COMO OVELHAS PERDIDAS,
EM NOSSOS PRÓPRIOS
CAMINHOS DE DOR,
TODOS PECAMOS E ESTAMOS
LONGE DA GLÓRIA;
MAS SUA GLÓRIA É O QUE
QUEREMOS VER,
E EM SUA PRESENÇA
QUEREMOS, SIM, VIVER.

*CORO
SENHOR, VEM TUA GRAÇA MOSTRAR
NESTE TEU SANTO LUGAR,
VEM PERDOAR E RESTAURAR
EM MEU VIVER
TUA PRESENÇA OUTRA VEZ.
/INSTRUMENTOS

LEVOU AS DORES E O SOFRER,
CRISTO JESUS,
O CORDEIRO DE DEUS,
NOSSO PECAR TOMOU SOBRE SI,
POR NÓS MORREU;
SIM, LOUVEMOS AO PAI POR SEU
FILHO JESUS, E POR SEU SANGUE
DERRAMADO NA CRUZ.

*CORO
SENHOR, VEM TUA GRAÇA MOSTRAR
NESTE TEU SANTO LUGAR,
VEM PERDOAR E RESTAURAR
EM MEU VIVER
TUA PRESENÇA OUTRA VEZ.

VEM TUA GRAÇA MOSTRAR
NESTE TEU SANTO LUGAR,
VEM PERDOAR E RESTAURAR
EM MEU VIVER TUA PRESENÇA
OUTRA VEZ.
');
