INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('650b6f0b-081f-4a56-8eca-6363bd611533', 'Quero andar em Teu caminho, Senhor', '194', 'Luciana Monteiro Carneiro Simora', 'Novo', 'Bbm', 'Grupo de Louvor', 'QUERO ANDAR EM TEU CAMINHO, SENHOR,
MAIS E MAIS TE CONHECER
E FAZER TUA VONTADE, SENHOR;
TUA VOZ OBEDECER
E VIVER SOMENTE PRA TEU LOUVOR,
DESFRUTANDO DO TEU GRANDE AMOR;
QUERO SER FIEL, QUERO SER FIEL
A TI, SENHOR.

CORO
TE AGRADEÇO POR PRIMEIRO ME AMAR,
TE AGRADEÇO POR ME ESCOLHER,
TE AGRADEÇO (TE AGRADEÇO, MEU SENHOR),
TE AGRADEÇO, POIS NÃO SOU MERECEDOR.

FAZE EM MIM (FAZE EM MIM)
O TEU QUERER, Ó SENHOR (TEU QUERER),
QUERO SER UM VENCEDOR (VENCEDOR),
PRA QUE EU POSSA DIZER
(PRA QUE EU POSSA DIZER)
QUE TU VIVES EM MIM
E DA MINHA VIDA TU ÉS O SENHOR.

FINAL
TE AGRADEÇO (TE AGRADEÇO, MEU SENHOR),
TE AGRADEÇO, POIS NÃO SOU MERECEDOR.
');
