INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6539ebdf-b908-43e2-8d61-05eb63ed13ac', 'Santo Deus dos exércitos', '', '', '', '', '', 'CANTAR 2X
SANTO, SANTO, SANTO,
DEUS DOS EXÉRCITOS
OS CÉUS E A TERRA ESTÃO CHEIOS DA
TUA GLÓRIA.

HOSANA, HOSANA, HOSANA
NAS ALTURAS,
/(M) BENDITO O QUE VEM EM NOME
(M) DO SENHOR BENDITO,
(M) BENDITO SENHOR.

FINAL
(H) HOSANA
HOSANA, HOSANA, NAS ALTURAS.
');
