INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('655cb64b-042d-4c05-855c-f489ea9430c2', 'O fogo renovador', '', '', '', '', '', 'UM FOGO NOS AQUECERÁ
COM CHAMAS IMORTAIS
E TODO O QUE ALI PASSAR
IRÁ PURIFICAR,
TAL QUAL OURO SE REFINA
NO CALOR ABRASADOR,
NÓS IREMOS POR SUA GRAÇA
UM CARÁTER NOVO TER.

*CORO
O RENOVADOR, SEU FOGO ATUARÁ EM
NÓS, LIMPARÁ OS CORAÇÕES
E DAREMOS GLÓRIA A DEUS;
REFINARÁ NOSSO SER
E TRANSFORMARÁ O VIVER
E TODO O QUE IMPLORAR
IRÁ PURO SE TORNAR.
/INSTRUMENTOS

SABEMOS DAS VERDADES
QUE O CRISTO ENSINOU,
NÃO HÁ MAIS VIL PECADO
QUE JESUS NÃO PERDOOU,
SE ACEITARMOS O SEU SANGUE
NOS TRARÁ A SALVAÇÃO,
SEU PODER FAZ FORTE
AOS FRACOS, TODA ALMA
SUSTERÁ.

*CORO
O RENOVADOR, SEU FOGO ATUARÁ
EM NÓS, LIMPARÁ OS CORAÇÕES
E DAREMOS GLÓRIA A DEUS;
REFINARÁ NOSSO SER
E TRANSFORMARÁ O VIVER
E TODO O QUE IMPLORAR
IRÁ PURO SE TORNAR.
/FINAL
AMÉM!
');
