INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('65661fb0-cc86-4898-b34c-566d2a38e9f8', 'Olhar Unicamente a Jesus', '', '', '', '', '', 'E ERGUENDO ELES OS OLHOS, NINGUÉM VIRAM, 
SENÃO A JESUS, UNICAMENTE;
E ERGUENDO ELES OS OLHOS, NINGUÉM VIRAM, 
SENÃO A JESUS, UNICAMENTE;

ELE OS TOMOU, OS CONDUZIU
AO SEU SANTO MONTE,
SE REVELOU ÀS SUAS VIDAS;
CONTEMPLARAM O SEU ROSTO,
COMO O SOL DA JUSTIÇA,
E AS VESTES BRANCAS, COMO A LUZ.
E PROFESSARAM AO SENHOR JESUS:

*CORO
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
CONTEMPLANDO O SENHOR JESUS,
AUTOR E CONSUMADOR DA MINHA FÉ;
BOM É ESTAR AQUI EM TUA PRESENÇA,
CONTEMPLANDO O SENHOR JESUS.
/INSTRUMENTOS

E, ERGUENDO ELES OS OLHOS, NINGUÉM VIRAM
SENÃO A JESUS, UNICAMENTE;
E, ERGUENDO ELES OS OLHOS, NINGUÉM VIRAM
SENÃO A JESUS, UNICAMENTE;

A NUVEM DE LUZ DO SENHOR OS COBRIU,
CONTEMPLARAM SUA GLÓRIA E O SEU MISTÉRIO,
OUVIRAM A SUA VOZ: “ESTE É O MEU FILHO AMADO
EM QUEM ME COMPRAZO.

*CORO
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
CONTEMPLANDO O SENHOR JESUS,
AUTOR E CONSUMADOR DA MINHA FÉ;
BOM É ESTAR AQUI EM TUA PRESENÇA,
CONTEMPLANDO O SENHOR JESUS.

QUEM OLHA UNICAMENTE PARA JESUS
NÃO O DEIXA JAMAIS,
QUEM OLHA UNICAMENTE PARA JESUS 
NÃO O DEIXA JAMAIS;

FINAL
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
CONTEMPLANDO O SENHOR JESUS,
AUTOR E CONSUMADOR DA MINHA FÉ;
BOM É ESTARMOS AQUI EM TUA PRESENÇA,
CONTEMPLANDO O SENHOR JESUS, 
A JESUS.
');
