INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('663cbf81-770f-4cf3-9649-676f7417b0ee', 'O Grande Dia Está Chegando', '571', 'N.Jr.M.S', 'Repique', 'D', 'Volta de Jesus e Eternidade', 'O GRANDE DIA ESTÁ CHEGANDO,
FALTA TÃO POUCO
PARA O ENCONTRO COM MEU REI.
POSSO ATÉ IMAGINAR O QUE VOU SENTIR
QUANDO EU PASSAR PELOS PORTAIS CELESTIAIS
OUVINDO A MAIS BELA CANÇÃO DE LOUVOR!
LÁ PODEREI DIZER ASSIM:

*CORO
JERUSALÉM, COMO ÉS LINDA!
JERUSALÉM, QUANTO TEMPO,
EU ESPEREI PARA VER A TUA BELEZA!
JERUSALÉM, NA CIDADE DO MEU REI EU ESTOU!
POSSO AGORA MEU MESTRE JESUS ABRAÇAR!

O GRANDE DIA ESTÁ CHEGANDO,
FALTA TÃO POUCO
PARA O ENCONTRO COM MEU REI.
POSSO ATÉ IMAGINAR O QUE VOU SENTIR
QUANDO EU PASSAR PELOS PORTAIS CELESTIAIS
OUVINDO A MAIS BELA CANÇÃO DE LOUVOR!
LÁ PODEREI DIZER ASSIM:

*CORO 2X
JERUSALÉM, COMO ÉS LINDA!
JERUSALÉM, QUANTO TEMPO,
EU ESPEREI PARA VER A TUA BELEZA!
JERUSALÉM, NA CIDADE DO MEU REI EU ESTOU!
POSSO AGORA MEU MESTRE JESUS ABRAÇAR!
/FINAL
POSSO AGORA MEU MESTRE JESUS ABRAÇAR!
');
