INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6644f510-5abf-492a-839f-3c914392a2f4', 'Maravilhoso é servir a Deus', '', '', '', '', 'Avulso', 'ESTOU PASSANDO POR PROVAS MAIS UMA VEZ
MAS EM DEUS SEMPRE CONFIO
SEI QUE NUNCA ME ABANDONARÁ
O FOGO ESTÁ FORTE, ÀS VEZES PENSO SÓ ME RESTA A MORTE
MAS COMO DEUS LIVROU A DANIEL
SEI QUE DEUS TAMBÉM ME LIVRARÁ

O SENHOR É MINHA ROCHA
O SENHOR É MINHA FORTALEZA
O SENHOR VENCE AS BATALHAS
O SENHOR É A MINHA CERTEZA DE QUE VENCEREI

MARAVILHOSO É SERVIR A DEUS
QUE NUNCA DEIXA A SÓS OS SEUS
NÃO REJEITA A ORAÇÃO DO SERVO
MINHA LÁGRIMA ENXUGARÁ

MARAVILHOSO É SERVIR A DEUS
QUE TEM PRAZER EM ME ABENÇOAR
NÃO IMPORTA O FOGO DESSA PROVA
A MÃO DE DEUS IRÁ ME SUSTENTAR
ATÉ A PROVA PASSAR
/INSTRUMENTOS

O SENHOR É MINHA ROCHA
O SENHOR É MINHA FORTALEZA
O SENHOR VENCE AS BATALHAS
O SENHOR É A MINHA CERTEZA DE QUE VENCEREI

MARAVILHOSO É SERVIR A DEUS
QUE NUNCA DEIXA A SÓS OS SEUS
NÃO REJEITA A ORAÇÃO DO SERVO
MINHA LÁGRIMA ENXUGARÁ

MARAVILHOSO É SERVIR A DEUS
QUE TEM PRAZER EM ME ABENÇOAR
NÃO IMPORTA O FOGO DESSA PROVA
A MÃO DE DEUS IRÁ ME SUSTENTAR
ATÉ A PROVA PASSAR
/FINAL
IRÁ ME SUSTENTAR
ATÉ A PROVA PASSAR
');
