INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('66e649dd-4394-4759-ae08-5f2301f8a1cc', 'Cada dia me dirige', '772', '', 'Fox', 'C', 'Corinhos', 'CANTAR 2X
CADA DIA ME DIRIGE,
CADA DIA ME PROTEGE.
CADA DIA, SINTO SEU AMOR POR MIM,
ALELUIA!
CADA DIA BOAS NOVAS,
CADA DIA VEJO A PROVA
DO PODER DO GRANDE AMOR
DO MEU SENHOR E REI!
');
