INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('66eac25a-2a96-44ec-bd1f-ab24a9c098e2', 'Quando o Dia Amanhece', '065', 'Paulo Lucas Rohr; Carlos Augusto Kohls; Clauber Luiz Kohls', 'Básico', 'A', 'Invocação e Comunhão', 'QUANDO O DIA AMANHECE, 
EU BUSCO AO SENHOR,
ELE ME FAZ SENTIR O SEU GRANDE AMOR.
ENSINA-ME, Ó SENHOR, CONTIGO CAMINHAR,
OUVIR A TUA DOCE VOZ A ME CHAMAR.

OUVE A MINHA ORAÇÃO, SENHOR,
POIS EU QUERO TE SERVIR, 
SENHOR DE AMOR, DE AMOR.

QUANDO O DIA AMANHECE, 
EU BUSCO AO SENHOR,
ELE ME FAZ SENTIR O SEU GRANDE AMOR.
ENSINA-ME, Ó SENHOR, CONTIGO CAMINHAR,
OUVIR A TUA DOCE VOZ A ME CHAMAR.

OUVE A MINHA ORAÇÃO, SENHOR,
POIS EU QUERO TE SERVIR, 
SENHOR DE AMOR, DE AMOR.
/FINAL
DE AMOR.
