INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('674ec83c-b390-4de4-9200-257aad77b780', 'Basta Dizeres o Que Queres', '288', 'Olcimar Rubens de Carvalho', 'Balada', 'G', 'Grupo de Louvor', 'BASTA DIZERES O QUE QUERES,
JESUS PRONTO ESTÁ A TE OUVIR,
BASTA COM O SENHOR SERES SINCERO
E ELE TE RESPONDERÁ.

A ALEGRIA QUE NO MUNDO
JAMAIS PUDESTE ENCONTRAR,
EM CRISTO TERÁS O PRAZER,
SIM, DELA GOZAR.

*CORO
SENTE OS BRAÇOS DE JESUS
QUERENDO TE SOCORRER,
OUVE A VOZ SUAVE DO FILHO DE DEUS
DIZENDO: "TE AMO E QUERO TE SALVAR,
TE AMO E QUERO TE SALVAR."

CRISTO QUER QUE ESTEJAS CONOSCO
QUANDO VIER NOS BUSCAR
PROCLAMANDO: "VINDE BENDITOS DE MEU PAI
COMIGO NO CÉU MORAR."

*CORO
SENTE OS BRAÇOS DE JESUS
QUERENDO TE SOCORRER,
OUVE A VOZ SUAVE DO FILHO DE DEUS
DIZENDO: "TE AMO E QUERO TE SALVAR,
TE AMO E QUERO TE SALVAR."
/FINAL
"TE AMO E QUERO TE SALVAR."
');
