INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6756e463-a5f2-4a39-bc41-c941ccaa32c3', 'Há um povo que te adora', '418', 'Let.:Everaldo Cavalcante Lima, Luciana Monteiro Carneiro Simora; Mús. Luciana Monteiro Carneiro Simora', 'Básico', 'E', 'Santificação e Derramamento', 'HÁ UM POVO QUE TE ADORA EM ESPÍRITO,
ATENDENDO A TUA VOZ, SENHOR,
QUE TEM UMA NOVA FORMA DE VIDA,
LUTA COM AS ARMAS CELESTIAIS
E VENCE PELO PODER DE JESUS.

*CORO
O SENHOR É QUEM DIRIGE,
O SENHOR É QUEM CONDUZ,
DEPENDENTE SOU DO SEU AMOR;
QUERO VIVER UMA NOVA FORMA DE VIDA
NO AMOR, NO AMOR DE JESUS.

NO PROJETO DE DEUS ESTOU
LUTANDO COM AS ARMAS CELESTIAIS,
VENCENDO PELO PODER DO SENHOR JESUS,
COM SEU PERDÃO, NA SALVAÇÃO,
NA REVELAÇÃO DE JESUS.

*CORO
O SENHOR É QUEM DIRIGE,
O SENHOR É QUEM CONDUZ,
DEPENDENTE SOU DO SEU AMOR;
QUERO VIVER UMA NOVA FORMA DE VIDA
NO AMOR, NO AMOR DE JESUS.
/INSTRUMENTOS

FINAL
QUERO VIVER UMA NOVA FORMA DE VIDA
NO AMOR, NO AMOR DE JESUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('6756e463-a5f2-4a39-bc41-c941ccaa32c3', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
