INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('67b2d821-72a4-4e6e-98e2-cbcfce359abb', 'Faz - me Inabalável', '350', 'Jackson de Halley Fernandes Fontes', 'Básico', 'F', 'Consolo e Encorajamento', 'FAZE-ME INABALÁVEL,
SENHOR, EM TEU CAMINHO,
FIRMA OS MEUS PASSOS
E NÃO TRIUNFE O INIMIGO;
OUVE A MINHA ORAÇÃO
E SEJA EU SOCORRIDO.

POR QUE TE ABATES DENTRO EM MIM,
Ó MINH''ALMA?
ESPERA EM TEU DEUS,
ELE É TUA FORÇA E GLÓRIA; 
NÃO TE DESAMPAROU,
SEMPRE ESTEVE AO TEU LADO.

A DEUS TODA A GLÓRIA, 
ELE NOS FAZ TRIUNFANTES,
SUA GRAÇA É FORTE
E SUA PALAVRA É VERDADE, AMÉM!
');
