INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('67da4b72-38b0-48aa-80cc-50ab9d3f6812', 'Do pão do céu', 95, 'Autor Desconhecido', 'Básico', 'C', 'Crianças e Adolescentes', 'DO PÃO DO CÉU ME NUTRIREI,
DA FONTE ETERNA BEBEREI;
"E QUEM BEBER," NOS DIZ JESUS,
"JAMAIS DE SEDE SOFRERÁ."

CANTAR 2X
NÃO MAIS SEDE? QUE DIZEIS?
NÃO MAIS SEDE, ASSIM SERÁ!
/"E QUEM BEBER," NOS DIZ JESUS,
"JAMAIS DE SEDE SOFRERÁ."
SEDE NÃO TERÁ!
');
