INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('680f127e-a0fe-4dd5-ad1e-0c9e0b564c70', 'Tenho uma candeia (Candeia acesa)', '143', 'S.G.D.', 'Fox Abafado', 'A', 'Crianças e Adolescentes', 'CORO
TENHO UMA CANDEIA,
DE ÓLEO ESTÁ CHEIA,
ELA ANUNCIA QUE JESUS VOLTARÁ;
LUZ BRILHANTE REFULGENTE,
É O GRITO DA IGREJA:
JESUS VAI VOLTAR.

CANTAR 2X
ACENDE TUA CANDEIA
NÃO A DEIXES APAGAR,
ILUMINANDO O TEU ROSTO
JESUS TE VERÁ.

CANTAR 2X
CANDEIA VAZIA
EU NÃO QUERO, NÃO,
CANDEIA CHEIA
EU QUERO, SIM,
CANDEIA COM FOGO
PRONTA PRA SUBIR.
');
