INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('685fb177-24ca-4d4e-8889-adfdf05f55e3', 'Abriga-me', '', '', '', '', '', 'ABRIGA-ME, EM TUA MÃO,
EM TUAS ASAS DE CURA E SALVAÇÃO.

E SE A TEMPESTADE A MIM CHEGAR VOU
CONTIGO ANDAR POR SOBRE O MAR.
NADA TEMEREI COMIGO ESTÁS AO SOM
DA TUA VOZ A PAZ.
/SOMENTE EM TI VOU DESCANSAR
NO MEU DEUS EU POSSO ME ABRIGAR.

CANTAR 3X
E SE A TEMPESTADE A MIM CHEGAR VOU
CONTIGO ANDAR POR SOBRE O MAR.
NADA TEMEREI COMIGO ESTÁS AO SOM
DA TUA VOZ A PAZ.
/FINAL
AO SOM DA TUA VOZ A PAZ.
');
