INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('68625c52-c26e-463f-b794-0038748ffa70', 'Imutável Deus', '021', '', 'Balada', 'Em', 'Avulsos', 'É TEMPO DE RECONSTRUIR,
REERGUER AS MURALHAS
DISPONDO-SE A TRABALHAR,
E NÃO OLHAR ATRÁS.

*CORO
IMUTÁVEL DEUS!
IGUAL A TI NÃO HÁ OUTRO.
O TEU NOME É “EU SOU”,
O GRANDE EL SHADDAI.

ELE É O ALFA, (ELE É O ALFA)
ELE É O ÔMEGA, (ELE É O ÔMEGA)
O PRIMEIRO E O ÚLTIMO, (O PRIMEIRO E O ÚLTIMO)
IMUTÁVEL DEUS.

ONIPOTENTE, (ONIPOTENTE)
ONISCIENTE, (ONISCIENTE)
ONIPRESENTE, (ONIPRESENTE)
IMUTÁVEL DEUS.

DISPÕE-TE PARA PELEJAR
DEFENDENDO ESTA OBRA.
NÃO TEMAS, POIS O TEU DEUS
A VITÓRIA JÁ TE DEU.

*CORO
IMUTÁVEL DEUS!
IGUAL A TI NÃO HÁ OUTRO.
O TEU NOME É “EU SOU”,
O GRANDE EL SHADDAI.

ELE É O ALFA, (ELE É O ALFA)
ELE É O ÔMEGA, (ELE É O ÔMEGA)
O PRIMEIRO E O ÚLTIMO, (O PRIMEIRO E O ÚLTIMO)
IMUTÁVEL DEUS.

ONIPOTENTE, (ONIPOTENTE)
ONISCIENTE, (ONISCIENTE)
ONIPRESENTE, (ONIPRESENTE)
IMUTÁVEL DEUS.

*CORO 2X
IMUTÁVEL DEUS!
IGUAL A TI NÃO HÁ OUTRO.
O TEU NOME É “EU SOU”,
O GRANDE EL SHADDAI.
/FINAL
O GRANDE EL SHADDAI. (2X)
');
