INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('691c7919-5dd3-42e3-bc77-c5192f9a6b29', 'Hoje o Senhor derramou', '578', 'Emanoel Aleixo Júnior', 'Básico', 'A', 'Louvor', 'HOJE O SENHOR DERRAMOU
DO SEU PODER SOBRE NÓS,
COMO A CADA MANHÃ E ENTARDECER
SENTIMOS SEU AMOR;
POR ISSO DAMOS GRAÇAS
POR TUDO O QUE TEM FEITO A NÓS,
LOUVORES E HONRAS AO GRANDE SALVADOR.

*CORO
MEU SENHOR, A TI LOUVAMOS
POR TUA MÃO QUE NOS SUSTÉM,
E APESAR DAS LUTAS E PROVAS, SENHOR,
SABEMOS QUE CONOSCO SEMPRE ESTARÁS.

O QUE TE DAR, MEU SENHOR,
POR TANTAS BÊNÇÃOS CELESTIAIS?
EM SANTIDADE, Ó SENHOR,
TE OFERECEMOS CORAÇÕES FIÉIS,

PURIFICADOS EM JESUS,
BUSCANDO A SALVAÇÃO,
POIS BEM SABEMOS
QUE O SANGUE DE CRISTO TRAZ PERDÃO.

*CORO 2X
MEU SENHOR, A TI LOUVAMOS
POR TUA MÃO QUE NOS SUSTÉM,
E APESAR DAS LUTAS E PROVAS, SENHOR,
SABEMOS QUE CONOSCO SEMPRE ESTARÁS.
/FINAL
CONOSCO SEMPRE ESTARÁS.
');
