INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6a0694ad-af0f-4195-a81c-2b09ae431a2a', 'Deus criou os céus e a terra', '224', 'E.H.M.R.', 'Básico', 'A', 'Crianças e Adolescentes', 'DEUS CRIOU OS CÉUS E A TERRA,
O UNIVERSO, TUDO ELE FEZ;
A TERRA ERA VAZIA,
COBERTA DE TREVAS,
SEMELHANTE AO CORAÇÃO
DO HOMEM SEM DEUS.

ELE TROUXE A LUZ,
SEPAROU AS ÁGUAS,
CRIOU A TERRA FIRME,
AS ERVAS FEZ BROTAR,
ILUMINOU OS CÉUS
COM O BRILHO DO SOL, 
LUA E ESTRELAS,

ENCHEU O MAR DE VIDA, 
CRIOU OS ANIMAIS,
PREPAROU TUDO TÃO BELO
PARA DEPOIS O HOMEM CRIAR.

*CORO
DO NADA ELE FEZ TUDO.
COM SUA PALAVRA OS CRIOU.
ELE É O DEUS DA VIDA
E TUDO ESTÁ EM SUAS MÃOS;
É ELE QUEM MOVE OS CORAÇÕES
PARA CONHECERMOS O SEU AMOR.
NOS REVELANDO JESUS, NOSSO SALVADOR.

ESTA TERRA UM DIA PASSARÁ,
NÃO MAIS EXISTIRÁ,
O NOVO CÉU E A NOVA TERRA
JESUS NOS DARÁ.

*CORO
DO NADA ELE FEZ TUDO.
COM SUA PALAVRA OS CRIOU.
ELE É O DEUS DA VIDA
E TUDO ESTÁ EM SUAS MÃOS;
É ELE QUEM MOVE OS CORAÇÕES
PARA CONHECERMOS O SEU AMOR.
NOS REVELANDO JESUS, NOSSO SALVADOR.

FINAL 2X
NOS REVELANDO JESUS, NOSSO SALVADOR.
');
