INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6a24524d-395f-4a83-aaa7-d5c07136cea4', 'Imutável Deus', '', '', 'Balada', 'Em', 'Avulsos', 'É TEMPO DE RECONSTRUIR,
REERGUER AS MURALHAS
DISPONDO-SE A TRABALHAR,
E NÃO OLHAR ATRÁS.

*CORO
IMUTÁVEL DEUS!
IGUAL A TI NÃO HÁ OUTRO.
O TEU NOME É “EU SOU”,
O GRANDE EL SHADDAI.

ELE É O ALFA, (ELE É O ALFA)
ELE É O ÔMEGA, (ELE É O ÔMEGA)
O PRIMEIRO E O ÚLTIMO, (O PRIMEIRO E O ÚLTIMO)
IMUTÁVEL DEUS.

ONIPOTENTE, (ONIPOTENTE)
ONISCIENTE, (ONISCIENTE)
ONIPRESENTE, (ONIPRESENTE)
IMUTÁVEL DEUS.

DISPÕE-TE PARA PELEJAR
DEFENDENDO ESTA OBRA.
NÃO TEMAS, POIS O TEU DEUS
A VITÓRIA JÁ TE DEU.

*CORO
IMUTÁVEL DEUS!
IGUAL A TI NÃO HÁ OUTRO.
O TEU NOME É “EU SOU”,
O GRANDE EL SHADDAI.

ELE É O ALFA, (ELE É O ALFA)
ELE É O ÔMEGA, (ELE É O ÔMEGA)
O PRIMEIRO E O ÚLTIMO, (O PRIMEIRO E O ÚLTIMO)
IMUTÁVEL DEUS.

ONIPOTENTE, (ONIPOTENTE)
ONISCIENTE, (ONISCIENTE)
ONIPRESENTE, (ONIPRESENTE)
IMUTÁVEL DEUS.

*CORO 2X
IMUTÁVEL DEUS!
IGUAL A TI NÃO HÁ OUTRO.
O TEU NOME É “EU SOU”,
O GRANDE EL SHADDAI.
/FINAL
O GRANDE EL SHADDAI. (2X)
');
