INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6a38af2e-7e15-4ba9-a027-942ffe51e4d7', 'Se não fosse o Senhor', '349', 'Everaldo Cavalcante Lima', 'Básico', 'G', 'Consolo e Encorajamento', 'SE NÃO FOSSE O SENHOR
(SE NÃO FOSSE O SENHOR)
QUE ESTIVESSE AO NOSSO LADO
QUANDO OS HOMENS SE LEVANTARAM,
SE LEVANTARAM CONTRA NÓS.

O SOCORRO ESTÁ NO SENHOR
QUE FEZ O CÉU E A TERRA.
OS LAÇOS SÃO QUEBRADOS 
E NÓS ESCAPAMOS.
BENDITO SEJA O SENHOR
QUE FEZ O CÉU E A TERRA.
/INSTRUMENTOS

SE NÃO FOSSE O SENHOR
(SE NÃO FOSSE O SENHOR)
QUE ESTIVESSE AO NOSSO LADO
QUANDO OS HOMENS SE LEVANTARAM,
SE LEVANTARAM CONTRA NÓS.

O SOCORRO ESTÁ NO SENHOR
QUE FEZ O CÉU E A TERRA.
OS LAÇOS SÃO QUEBRADOS 
E NÓS ESCAPAMOS.
BENDITO SEJA O SENHOR
QUE FEZ O CÉU E A TERRA.
/INSTRUMENTOS

FINAL 2X
SE NÃO FOSSE O SENHOR,
(SE NÃO FOSSE O SENHOR)
(SE NÃO FOSSE O SENHOR)
O SENHOR!
');
