INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6b004217-4d0b-4a8f-80b1-c08f7e8af426', 'Sei Que o Senhor', '500', 'Ednilton Andrade Pires', 'Básico', 'Em', 'Volta de Jesus e Eternidade', 'SEI QUE O SENHOR AO MEU LADO ESTÁ,
SEI QUE UM DIA ENCONTRÁ-LO-EI.
/*CORO
NESSE DIA ALEGRAR-ME-EI,
COM OS ANJOS CANTAREI LOUVOR
E ADORAREI PROSTRADO DIANTE DO SENHOR.

SEI QUE ESTA VIDA LOGO PASSARÁ,
SEI QUE O SENHOR TAMBÉM ME LEVARÁ,
SEI QUE AMANHÃ HÁ UM NOVO ALVORECER
QUE APAGARÁ AS DORES NO AMANHECER.

*CORO
NESSE DIA ALEGRAR-ME-EI,
COM OS ANJOS CANTAREI LOUVOR
E ADORAREI PROSTRADO DIANTE DO SENHOR.

SEI QUE A ALEGRIA LOGO VOLTARÁ,
O AMOR DO SENHOR EM MIM FLORESCERÁ.
/*CORO
NESSE DIA ALEGRAR-ME-EI,
COM OS ANJOS CANTAREI LOUVOR
E ADORAREI PROSTRADO DIANTE DO SENHOR.
/INSTRUMENTOS

FINAL
ALEGRAR-ME-EI, COM OS ANJOS
CANTAREI LOUVOR E ADORAREI
PROSTRADO DIANTE DO SENHOR.
');
