INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6b1f1585-8b94-4881-89ba-62e078c1411e', 'Nesta batalha não tereis que pelejar', '123', 'I.B.S.A.', 'Fox', 'C', 'Crianças e Adolescentes', 'NESTA BATALHA NÃO TEREIS QUE PELEJAR;
AGUARDAI, FICAI PARADOS,
E VEDE A SALVAÇÃO DO SENHOR
PARA CONVOSCO, Ó JUDÁ E JERUSALÉM.

NÃO TEMAIS, NEM VOS ASSUSTEIS;
AMANHÃ SAÍ-LHES AO ENCONTRO,
PORQUE O SENHOR SERÁ CONVOSCO.
NESTA BATALHA NÃO TEREIS QUE PELEJAR.
');
