INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6c373901-8869-4d21-91ac-2620b2a427b4', 'Ele é a Minha Força', '', '', '', '', '', 'MESMO QUE O CAMINHO SEJA INCERTO,
E DESCONHECIDO O TRILHO FOR.
DEUS TEM NOS DADO SEGURANÇA,
NÓS TEMPOS PAZ,
GOZO NOS VEM, FORÇA NOS TRAZ.

CORO
ELE É PODER, É MINHA FORÇA.
CERTO EU ESTOU QUE ME AMPARA
COM SUAS MÃOS.
MINHA ESPERANÇA DE UMA VIDA ETERNA.
ELE É A ROCHA QUE ESTÁ A ME SUSTER.

MESMO QUANDO O AMANHÃ NÃO VEJO,
EM SUA PALAVRA ENCONTRO A LUZ.
E QUANDO AS DORES TOMAM CONTA,
AO ME ABRAÇAR SE FRACO ESTOU,
ENCONTRO PAZ.

E QUANDO O TEMPORAL ME
CERCA E O VENTO AS MÁGOAS VEM TRAZER,
JUNTO A ROCHA EU ESPERAREI.
PORQUE EU SEI QUE SALVO ESTAREI.

FINAL
ELE É A ROCHA QUE NOS SUSTÉM
NOSSA ESPERANÇA DE UMA VIDA ETERNA,
SENHOR JESUS
SENHOR JESUS,
ROCHA FIEL
ROCHA FIEL,
QUE NOS SUSTEM,
ROCHA DA SALVAÇÃO
ROCHA DA SALVAÇÃO,
QUE ME SUSTÉM.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('6c373901-8869-4d21-91ac-2620b2a427b4', '45ab58b2-d293-45c7-aa75-090fcd968b24');
