INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6c721be3-72a5-4580-9563-837dfc9142dc', 'Guia, ó Cristo, minha nau', '718', '', 'Valseado', 'Ab', 'Grupo de Louvor', 'GUIA, Ó CRISTO, A MINHA NAU
SOBRE O REVOLTOSO MAR.
TÃO ENFURECIDO E MAU;
QUER FAZÊ-LA NAUFRAGAR
VEM JESUS, Ó VEM GUIAR
MINHA NAU VEM PILOTAR.

SE, NO PORTO QUANDO ENTRAR,
MAIS O MAR SE ENFURECER,
QUE ME POSSA DELEITAR
EM OUVIR JESUS DIZER:
“ENTRA POBRE VIAJOR
NO DESCANSO DO SENHOR!”
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('6c721be3-72a5-4580-9563-837dfc9142dc', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
