INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6c97081f-b29b-4661-abd7-4e7a0156d17b', 'Deus Está Presente Sempre', '323', 'Let.:Gildásio Martins dos Reis; Mús.: Hudson Brazil Santos', 'Balada', 'A', 'Consolo e Encorajamento', 'DEUS ESTÁ PRESENTE
SEMPRE PRONTO A NOS AJUDAR,
COM SEUS OUVIDOS
SEMPRE VOLTADOS A NOS ESCUTAR;
BUSCA A JESUS PARA O TEU CORAÇÃO ALEGRAR,
PARA ENCHER TEU CORAÇÃO DE GOZO E PAZ.

*CORO
AGORA SOMOS POVO TRANSFORMADO
PELA GRAÇA DE CRISTO JESUS,
PELO SEU GRANDIOSO AMOR,
SOMOS POVO DE CRISTO JESUS, O SENHOR.
/INSTRUMENTOS

ESTAMOS CONSCIENTES
DE SUA SANTA PRESENÇA AQUI,
COM SEU PODER E COM GRAÇA ELE VAI OPERAR;
NÃO FICARÁ QUALQUER LUTA OU TRISTEZA AQUI
POIS O SENHOR NOS LEVARÁ
A SENTIR O SEU AMOR.

*CORO
AGORA SOMOS POVO TRANSFORMADO
PELA GRAÇA DE CRISTO JESUS,
PELO SEU GRANDIOSO AMOR,
SOMOS POVO DE CRISTO JESUS, O SENHOR.
/FINAL
SOMOS POVO DE CRISTO JESUS,
O SENHOR.
');
