INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6d0b70d4-cc32-4424-9ed9-bda73aa49c23', 'Quando a mão de Deus em mim veio tocar', '128', 'Jorgemar Souza Madeira', 'Básico', 'D', 'Dedicação', 'QUANDO A MÃO DE DEUS EM MIM VEIO TOCAR,
A ALEGRIA TRANSBORDOU MEU VIVER,
SUA VOZ SUAVE E MEIGA EM MIM SOOU,
PUDE ENTÃO SENTIR O SEU IMENSO AMOR.

CORO 2X
SOU FELIZ,
SOU FELIZ EM JESUS,
SIM, EU SOU FELIZ.

QUANDO O TOQUE DO ESPÍRITO SENTI,
DEU-ME PAZ E TRANSFORMOU A MINHA VIDA;
COMO O SOL NO SEU ALTO ESPLENDOR,
CRISTO INUNDOU-ME COM O SEU AMOR.

FINAL
SOU FELIZ EM JESUS,
POSSO ENTÃO DIZER: FELIZ, SOU FELIZ.
');
