INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6d348daa-04ef-4c17-8178-228ae099c939', 'Exaltado, ó Deus, Seja o Teu Nome', '', '', '', '', '', 'EXALTADO, EXALTADO, EXALTADO, Ó DEUS.
LOUVAREI COM GRATIDÃO O TEU NOME
ENTRE OS POVOS,
(M) CANTAREI ENTRE AS NAÇÕES
(M) OS TEUS LOUVORES

POIS É GRANDE O TEU AMOR
E A TUA VERDADE ULTRAPASSA OS CÉUS,
ULTRAPASSA OS CÉUS MEU SENHOR.
EXALTADO, Ó DEUS, SEJA O TEU NOME,
TUA GLÓRIA SE ESTENDA SOBRE NÓS.

EXALTADO, Ó DEUS, SEJA O TEU NOME,
TUA GLÓRIA SE ESTENDA SOBRE NÓS.
EXALTADO!
LOUVAREI COM GRATIDÃO
O TEU NOME ENTRE OS POVOS,

(M) CANTAREI ENTRE AS NAÇÕES
(M) OS TEUS LOUVORES
/POIS É GRANDE O TEU AMOR E A TUA VERDADE
ULTRAPASSA OS CÉUS, ULTRAPASSA OS CÉUS,
MEU SENHOR.

EXALTADO, Ó DEUS SEJA O TEU NOME,
TUA GLÓRIA ESTENDA SOBRE NÓS.
EXALTADO, Ó DEUS, SEJA O TEU NOME,
TUA GLÓRIA SE ESTENDA SOBRE NÓS.
EXALTADO, EXALTADO, Ó DEUS!
');
