INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6d40264a-183b-4b86-9c12-c591249415c6', 'Eu verei a árvore da vida', '754', 'Jorgemar Souza Madeira', 'Novo', 'C', 'Corinhos', 'EU VEREI A ÁRVORE DA VIDA,
EU VEREI O MEU LINDO PAÍS,
EU VEREI AS PEDRAS PRECIOSAS,
EU VEREI AS MAIS BELAS MANSÕES,

EU VEREI MILHÕES DE ANJOS CANTANDO,
EU VEREI O MEU AMADO JESUS,
EU VEREI O LINDO CORO CELESTIAL
LOUVANDO O GRANDE REI JESUS.
/INSTRUMENTOS

EU VEREI A ÁRVORE DA VIDA,
EU VEREI O MEU LINDO PAÍS,
EU VEREI AS PEDRAS PRECIOSAS,
EU VEREI AS MAIS BELAS MANSÕES,

EU VEREI MILHÕES DE ANJOS CANTANDO,
EU VEREI O MEU AMADO JESUS,
EU VEREI O LINDO CORO CELESTIAL
LOUVANDO O GRANDE REI JESUS.
/FINAL
EU VEREI O LINDO CORO CELESTIAL
LOUVANDO O GRANDE REI JESUS.
');
