INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6d93eebc-01fd-47f9-bb8a-2ffacf16f2c8', 'Dá-me um coração cheio do teu amor', '163', 'M.L.M.B.O.', 'Básico', 'C', 'Crianças e Adolescentes', 'DÁ-ME UM CORAÇÃO
CHEIO DO TEU AMOR,
QUE SEMPRE RECONHEÇA
TUA BONDADE, Ó MEU SENHOR.

UM CORAÇÃO QUE ESTREMEÇA
AO OUVIR TUA VOZ ASSIM
E QUE NUNCA SE ESQUEÇA
O QUE TU FAZES POR MIM.

CANTAR 2X
UM CORAÇÃO OBEDIENTE
À TUA REVELAÇÃO,
PURO E RENOVADO
PELA TUA SALVAÇÃO.
/FINAL
Ó SENHOR, AMÉM.
');
