INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6da04894-f11b-422d-a7da-ce37a7a08b9a', 'Ouço a voz do meu amado a me chamar', '432', 'Jorgemar Souza Madeira', 'Novo', 'G', 'Santificação e Derramamento', '*CORO
OUÇO A VOZ DO MEU AMADO ME CHAMAR:
"FILHO, VEM COMIGO À MESA A CEAR;
TUDO FIZ, NA CRUZ MORRI POR AMOR,
PRA DAR VIDA AO PERDIDO PECADOR."

"ESTE PÃO QUE EU VOS DOU
REPRESENTA O MEU CORPO
QUE ENTREGUEI NA CRUZ POR AMOR."

*CORO
OUÇO A VOZ DO MEU AMADO ME CHAMAR:
"FILHO, VEM COMIGO À MESA A CEAR;
TUDO FIZ, NA CRUZ MORRI POR AMOR,
PRA DAR VIDA AO PERDIDO PECADOR."

"ESTE CÁLICE VOS DOU,
REPRESENTA O MEU SANGUE
QUE DERRAMEI NA CRUZ POR AMOR."

*CORO
OUÇO A VOZ DO MEU AMADO ME CHAMAR:
"FILHO, VEM COMIGO À MESA A CEAR;
TUDO FIZ, NA CRUZ MORRI POR AMOR,
PRA DAR VIDA AO PERDIDO PECADOR."
/FINAL
OUÇO A VOZ DO MEU AMADO ME CHAMAR:
"FILHO, VEM COMIGO À MESA A CEAR."
');
