INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6da1ad37-a860-43ff-9917-f231c15395e1', 'Senhor, a ti clamo', '025', 'Eloísa Helena Malavasi Ribeiro', 'Básico', 'A', 'Clamor', 'CANTAR 2X
SENHOR, A TI CLAMO,
INCLINA OS TEUS OUVIDOS À MINHA VOZ;
