INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6deaaa50-631a-44ac-a6e5-59484dece374', 'Purificado com sangue estou', '013', 'Mr. & Mrs. Seth Sykes', 'Fox', 'D', 'Crianças e Adolescentes', 'PURIFICADO COM SANGUE ESTOU,
QUAL NEVE ME TORNOU;
ÁGUA DA VIDA EM JESUS BEBI,
SATISFEITO ME SENTI.

PARA JESUS, LÁ NA CRUZ, EU OLHEI,
E O MEU FARDO AO CHÃO DEIXEI;
CANTANDO VOU: GLÓRIA AO SENHOR!
GLÓRIA A CRISTO, NOSSO DEUS!

PURIFICADO COM SANGUE ESTOU,
QUAL NEVE ME TORNOU;
ÁGUA DA VIDA EM JESUS BEBI,
SATISFEITO ME SENTI.

FINAL
PARA JESUS, LÁ NA CRUZ, EU OLHEI,
E O MEU FARDO AO CHÃO DEIXEI;
CANTANDO VOU: GLÓRIA AO SENHOR!
GLÓRIA A CRISTO, NOSSO DEUS!
');
