INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6e2273a3-ea9e-46c2-81f7-8a51bbbb3960', 'Pelo Vale Escuro Seguirei Jesus', '034', '', '', '', '', 'PELO VALE ESCURO,
SEGUREI JESUS
MAS POR TI SEGURO,
VENDO A SUA LUZ.
O MEU PASSO INCERTO,
TU DIRIGIRÁS
E AO SENTIR-TE PERTO,
NUNCA PERCO A PAZ.

OS ESPINHOS TANTOS,
QUE NOS VEM SANGRAR
SÃO REMÉDIOS SANTOS,
PARA NOS CURAR
ONDE EXISTE A GRAÇA
DO BONDOSO DEUS
TUDO O QUE SE PASSA,
NOS CONDUZ AO CÉU.

NÃO HÁ DOR QUE SEJA,
SEM DIVINO FIM
FAZE Ó DEUS QUE A IGREJA,
COMPREENDA ASSIM.
E APESAR DAS TREVAS,
POSSO VER SENHOR
QUE TU MESMO A LEVAS
COM IMENSO AMOR.

BREVE A NOITE DESCE,
NOITE DE EMAÚS
E MEU SER CARECE
DE TE VER JESUS
COMPANHEIRO AMIGO,
AO MEU ALDO VEM
FICA Ó DEUS COMIGO,
INFINITO BEM.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('6e2273a3-ea9e-46c2-81f7-8a51bbbb3960', '45ab58b2-d293-45c7-aa75-090fcd968b24');
