INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6e232b3a-9e24-4acd-9124-de280112085e', 'Há um ser que vive em mim', '155', 'Autor Desconhecido', 'Básico', 'E', 'Dedicação', 'HÁ UM SER QUE VIVE EM MIM
E SEMPRE ESTÁ COMIGO, SIM,
PROPORCIONANDO PAZ E AMOR,
ALIVIANDO TODA A MINHA DOR.

UM DIA MORREU PARA ME SALVAR,
RESSUSCITOU E VAI VOLTAR,
UM DIA ENTÃO VAI ME LEVAR
PARA COM ELE ETERNAMENTE MORAR.

O NOME DELE É SIMPLES
E POR ISSO É SUBLIME,
É O FILHO DE DEUS,
ELE É JESUS, ELE É JESUS, (2X)
');
