INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6efb5ccb-79b4-4219-bae1-5c582676592b', 'Andando em espírito (Fruto do Espírito)', '148', 'C.M.V.C.S.', 'Balada', 'D', 'Crianças e Adolescentes', 'ANDANDO EM ESPÍRITO 
VENCEREI A TENTAÇÃO,
AGRADAREI A DEUS
EM PERFEITA COMUNHÃO,

"POIS O FRUTO DO ESPÍRITO É:
AMOR, GOZO, PAZ,
LONGANIMIDADE, BENIGNIDADE,
BONDADE, FÉ, MANSIDÃO, TEMPERANÇA”.

FINAL 2X
VIVENDO EM ESPÍRITO,
ANDANDO EM ESPÍRITO,
ASSIM SOMOS SERVOS FIÉIS DE CRISTO.
');
