INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6f493e08-ca2e-45f6-bf3f-df988e9c3111', 'Mais do teu Santo Espírito', '442', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'D', 'Santificação e Derramamento', 'MAIS DO TEU SANTO ESPÍRITO, DÁ-NOS, SENHOR,
MAIS DOS TESOUROS ESCONDIDOS DO TEU AMOR;
MAIS, MUITO MAIS TU TENS PARA NOS DAR
SE TEU POVO TE BUSCAR,
MAIS, MUITO MAIS, TU QUERES ABENÇOAR.

CORO
POR ISSO TE ROGAMOS,
COM FÉ ORAMOS,
MANIFESTA TUA GRAÇA HOJE AQUI;
DÁ-NOS PORÇÃO DOBRADA
DO TEU SANTO ESPÍRITO,
/CANTAR 2X
PARA QUE MAIS, MUITO MAIS,
POSSAMOS TE SERVIR,

VEM REVELAR A ESTA GERAÇÃO
AS MARAVILHAS E SINAIS DA SALVAÇÃO;
TAL COMO A NOSSOS PAIS MOSTRASTE
ABUNDANTE GRAÇA E AMOR,
MAIS, MUITO MAIS,
CONCEDE-NOS, SENHOR.
');
