INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('6ff4ea4e-1e8b-48d1-b36b-03bddf61cfd7', 'Ele é Jeová', '', '', '', '', '', '(M) ELE É O SENHOR JEOVÁ,
(M) O DEUS DA CRIAÇÃO,
(M) ELE É O SENHOR JEOVÁ,
(M) DEUS PODEROSO,
(M) SENHOR DE GILEAD,
(M) A ROCHA ETERNA,
(M) ELE É O SENHOR QUE
(M) TE PODE RESTAURAR.

(H) ELE É O GRANDE EU SOU,
(H) O DEUS DE ABRAÃO,
(H) SENHOR JEOVÁ SHALOM,
(H) O DEUS DA PAZ EU SOU,
(H) O DEUS DE ISRAEL,
(H) QUE É ETERNO,
(H) ELE É O SENHOR QUE
(H) TE PODE RESTAURAR.

*CORO
CANTE ALELUIA, CANTE ALELUIA,
CANTE ALELUIA, CANTE ALELUIA!
ELE É O SENHOR JEOVÁ,
DEUS PODEROSO,
ELE É O SENHOR
QUE TE PODE RESTAURAR.
/INSTRUMENTOS

ELE É O PROVEDOR, JEOVÁ JIREH,
O NOSSO SALVADOR,
NOSSO MESSIAS;
SEU FILHO ENVIOU,
E AQUI TESTEMUNHOU,
ELE É O SENHOR QUE
TE PODE RESTAURAR.

*CORO 2X
CANTE ALELUIA, CANTE ALELUIA,
CANTE ALELUIA, CANTE ALELUIA!
ELE É O SENHOR JEOVÁ,
DEUS PODEROSO,
ELE É O SENHOR
QUE TE PODE RESTAURAR.
/FINAL
ELE É O SENHOR QUE TE
PODE RESTAURAR
');
