INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7065b3ab-22c8-4ba6-bfa1-e2863e5085ce', 'Aos pés de Jesus', '', '', '', '', '', 'NESTA VIDA O SERVO É PROVADO
MAS TEM AO SEU LADO O AUXÍLIO
DIVINO, E LEVANDO SUA CRUZ TÃO
PESADA À BEIRA DA ESTRADA
LAMENTA O DESTINO,

O SENHOR TEM PROVADO O SEU
POVO, MAS É VITORIOSO QUEM
LEVA SUA CRUZ, SE NÃO TENS
ESPERANÇA DE VIDA PROCURA
GUARIDA AOS PÉS DE JESUS.

*CORO
CHORA AOS PÉS DE JESUS PORQUE
ELE ENXUGA TEUS OLHOS TAMBÉM,
CONFIA SOMENTE E ESPERA,
NO AMANHECER TUA VITÓRIA VEM;
CHORA AOS PÉS DE JESUS, DERRAMA
EM PRANTOS O TEU CORAÇÃO, E
QUANDO O SENHOR RESPONDER
SABERÁS QUE O SERVO
NÃO CHORA EM VÃO.

MUITAS VEZES A NOITE É SOMBRIA,
NÃO TRAZ ALEGRIA E TUDO É
TRISTEZA, E O SERVO COM O ROSTO
EM TERRA, CLAMANDO E CHORANDO
NÃO PERDE A CERTEZA.

DE QUE DEUS NÃO DESPREZA O SEU
POVO, NA ÁGUA E NO FOGO ELE
ESTENDE SUAS MÃOS. QUANDO
TUDO PARECE PERDIDO, PARA OS TEUS
PROBLEMAS DEUS TRAZ SOLUÇÃO.

*CORO
CHORA AOS PÉS DE JESUS PORQUE
ELE ENXUGA TEUS OLHOS TAMBÉM,
CONFIA SOMENTE E ESPERA,
NO AMANHECER TUA VITÓRIA VEM;
CHORA AOS PÉS DE JESUS, DERRAMA
EM PRANTOS O TEU CORAÇÃO, E
QUANDO O SENHOR RESPONDER
SABERÁS QUE O SERVO
NÃO CHORA EM VÃO.

FINAL
E QUANDO O SENHOR RESPONDER,
SABERÁS QUE O SERVO
NÃO CHORA EM VÃO.
');
