INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('70885179-cbc3-4882-93ef-9cbf3158378f', 'Justos e Santos', '', '', '', '', '', 'JUSTOS E SANTOS SÃO OS CAMINHOS TEUS,
HONRA E LOUVORES VIEMOS TE DAR.
AQUI ESTAMOS PRA TI ADORAR
HONRA E LOUVORES QUEREMOS TE DAR.

*CORO
REI DO UNIVERSO, TÚ ÉS JUSTO E FIEL!
BRILHA SOBRE NÓS ESTRELA DA MANHÃ.
JUSTOS E SANTOS SÃO OS CAMINHOS TEUS,
HONRA E LOUVORES VIEMOS TE DAR.
/INSTRUMENTOS

QUE TUA GRAÇA E TEU GRANDE AMOR,
CERQUEM-NOS SEMPRE ONDE QUER QUE FOR.
E ASSIM POSSAMOS NA VIDA TRILHAR,
SÓ TEUS CAMINHOS EM HONRA E LOUVOR.

*CORO
REI DO UNIVERSO, TÚ ÉS JUSTO E FIEL!
BRILHA SOBRE NÓS ESTRELA DA MANHÃ.
JUSTOS E SANTOS SÃO OS CAMINHOS TEUS,
HONRA E LOUVORES VIEMOS TE DAR.
/FINAL
VIEMOS TE DAR. (3X)
