INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('70c5b64d-3202-47f3-9023-78a128e64c23', 'Quando será_', '', '', '', '', '', 'QUANDO SERÁ O GRANDE DIA
EM QUE O SENHOR VIRÁ NOS
BUSCAR? NINGUÉM SABE O DIA,
NINGUÉM SABE A HORA MAS
A TROMBETA ESTÁ PRA SOAR.

EIS QUE OS SINAIS JÁ SE CUMPRIRAM
EM TODA A TERRA, RIOS E MARES
A SUA IGREJA OUVE A VOZ DO
ESPÍRITO: MARANATA! JESUS VOLTARÁ!
SIM VOLTARÁ!

*CORO
MARANATA! MARANATA!
A IGREJA CLAMA: MARANATA!
O SENHOR VEM!
O SENHOR VEM!
/INSTRUMENTOS

DIAS DIFÍCEIS, DIAS DE DORES,
DIAS DE LUTAS ESTÃO SE PASSANDO;
A SUA IGREJA OLHA PRO ALTO.
MARANATA! JESUS VOLTARÁ!
SIM VOLTARÁ!

*CORO
MARANATA! MARANATA!
A IGREJA CLAMA: MARANATA!
O SENHOR VEM!
O SENHOR VEM!
');
