INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('71277be0-b922-4b62-9093-e70eba7aabce', 'Ele virá no meio da noite', '219', 'W.V.K.', 'Repique', 'D', 'Crianças e Adolescentes', 'ELE VIRÁ NO MEIO DA NOITE,
O NOIVO VEM BUSCAR
A NOIVA AMADA, ELE VEM!
PRA IR À NOVA JERUSALÉM,
RESGATARÁ O POVO QUE ANDA NA LUZ.

OS DIAS SÃO DE TREVAS, EU SEI,
MAS PARA A IGREJA BRILHA
A GLÓRIA DE CRISTO JESUS!
ENCHE TUA CANDEIA, DEIXA BRILHAR,
DEIXA O ESPÍRITO SANTO BRILHAR!

*CORO
BRILHA EM NÓS
O ESPÍRITO SANTO DE DEUS,
NOS LEVANDO A ENCONTRAR COM JESUS!
NAQUELE GRANDE DIA SUBIRÁ
QUEM ESTIVER NA LUZ,
ENCHE A CANDEIA
E BRILHA O FOGO DO SENHOR!
/INSTRUMENTOS

ELE VIRÁ NO MEIO DA NOITE,
O NOIVO VEM BUSCAR
A NOIVA AMADA, ELE VEM!
PRA IR À NOVA JERUSALÉM,
RESGATARÁ O POVO QUE ANDA NA LUZ.

OS DIAS SÃO DE TREVAS, EU SEI,
MAS PARA A IGREJA BRILHA
A GLÓRIA DE CRISTO JESUS!
ENCHE TUA CANDEIA, DEIXA BRILHAR,
DEIXA O ESPÍRITO SANTO BRILHAR!

*CORO 2X
BRILHA EM NÓS
O ESPÍRITO SANTO DE DEUS,
NOS LEVANDO A ENCONTRAR COM JESUS!
NAQUELE GRANDE DIA SUBIRÁ
QUEM ESTIVER NA LUZ,
ENCHE A CANDEIA
E BRILHA O FOGO DO SENHOR!
');
