INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('715b33fd-5286-4213-b4a2-37fb99474e76', 'Cristo é vitória', '127', 'Wendell P. Lovelles', 'Marcha', 'G', 'Crianças e Adolescentes', 'CRISTO É VITÓRIA!
PROCLAMAI COM REAL PRAZER;
CRISTO É VITÓRIA!
