INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('71909420-d432-40ee-8e1e-6158c70988a2', 'Bom é o Senhor', '320', 'Vítor Silva', 'Básico', 'C', 'Consolo e Encorajamento', 'CANTAR 2X
BOM É O SENHOR
PARA AQUELE QUE O BUSCA
E QUE ESPERA EM SILÊNCIO
A SUA SALVAÇÃO;

*CORO
PORQUE O SENHOR NÃO REJEITARÁ PRA SEMPRE,
NEM TEM PRAZER NA NOSSA DOR;
BOM É O SENHOR.

CANTAR 2X
POIS AINDA QUE ENTRISTEÇA
USARÁ DE COMPAIXÃO,
SEGUNDO A SUA MISERICÓRDIA;

*CORO
PORQUE O SENHOR NÃO REJEITARÁ PRA SEMPRE,
NEM TEM PRAZER NA NOSSA DOR;
BOM É O SENHOR (3X)
');
