INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('719dcabc-fb74-4fb4-a86b-831aa323c59e', 'Pega tua parte, irmão', '032', '', 'Básico', '', 'Avulsos', 'PEGA TUA PARTE, IRMÃO,
A MESA ESTÁ BEM FARTA.
PEGUE EM ABUNDÂNCIA,
POIS A TUA ESPERANÇA,
CRISTO NÃO DEIXOU MORRER.

ENCHA O TEU CELEIRO
DE BÊNÇÃOS ESPIRITUAIS.
DEIXA QUE TRANSBORDE,
QUE DERRAME ATÉ QUE SOBRE.
BÊNÇÃOS NUNCA SÃO DEMAIS.

A MESA PREPARADA EM NOSSA FRENTE,
O ANJO COM A BANDEJA EM SUAS MÃOS.
DOS CRENTES, A CABEÇA É UNGIDA,
BRASAS VIVAS QUEIMAM CORAÇÕES.
CRISTO, A CADA UM, VAI PERGUNTANDO:
"QUE QUERES QUE EU TE FAÇA, MEU IRMÃO?"
HOJE AS BÊNÇÃOS VÊM EM ABUNDÂNCIA.
ESTENDE A JESUS CRISTO A TUA MÃO.

PEGA TUA PARTE, IRMÃO,
A MESA ESTÁ BEM FARTA.
PEGUE EM ABUNDÂNCIA,
POIS A TUA ESPERANÇA,
CRISTO NÃO DEIXOU MORRER.

ENCHA O TEU CELEIRO
DE BÊNÇÃOS ESPIRITUAIS.
DEIXA QUE TRANSBORDE,
QUE DERRAME ATÉ QUE SOBRE.
BÊNÇÃOS NUNCA SÃO DEMAIS.

O ALIMENTO DESTA FESTA É MUITO PURO.
AS BÊNÇÃOS VÃO DE CURA À SALVAÇÃO.
BASTA CRER NO NOME DE JESUS,
ELE TE DARÁ A PERFEIÇÃO.
CRISTO, A CADA UM, VAI PERGUNTANDO:
"QUE QUERES QUE EU TE FAÇA, MEU IRMÃO?"
HOJE AS BÊNÇÃOS VÊM EM ABUNDÂNCIA.
É SÓ CLAMAR O SANGUE DE JESUS.

CANTAR 2X
PEGA TUA PARTE, IRMÃO,
A MESA ESTÁ BEM FARTA.
PEGUE EM ABUNDÂNCIA,
POIS A TUA ESPERANÇA,
CRISTO NÃO DEIXOU MORRER.
ENCHA O TEU CELEIRO
DE BÊNÇÃOS ESPIRITUAIS.
DEIXA QUE TRANSBORDE,
QUE DERRAME ATÉ QUE SOBRE.
BÊNÇÃOS NUNCA SÃO DEMAIS.

FINAL
DEIXA QUE TRANSBORDE,
QUE DERRAME ATÉ QUE SOBRE.
BÊNÇÃOS NUNCA SÃO DEMAIS.
');
