INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('71b3b3a1-5c1b-4e4b-b634-5e8cb0f038f7', 'Cristo Jesus é o meu bom Salvador', '151', 'Jayro Trench Gonçalves', 'Básico', 'A', 'Dedicação', 'CRISTO JESUS É O MEU BOM SALVADOR;
DESEJO AMÁ-LO MAIS,
TODOS OS DIAS É MEU SENHOR.

CORO
A CRISTO EU AMO,
OH! QUANTO EU AMO,
POIS POR MIM MORREU;
COM O SEU SANGUE, 
JESUS SALVOU-ME;
EM GRATIDÃO SOU SEU.
/INSTRUMENTOS

BEM CEDO AO CÉU
ELE ME LEVARÁ,
DE-SEJO AMÁ-LO MAIS,
ETERNAMENTE ME GUIARÁ.
');
