INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('71c88a3f-8087-4e9f-8b31-0a07489aea7f', 'Salmo Dos Salmos', '', '', '', '', '', 'O SENHOR É MEU PASTOR
O MEU GUIA E REI
O SENHOR É A FORÇA E A LUZ DO VIVER
AO SEU LADO EU SEMPRE ESTAREI.

O SEUS OLHOS VIGIAM
SEU AMOR NOS CONDUZ
MINHA VIDA DAREI AO SENHOR
CONFIAREI EM SEUS BRAÇOS DE AMOR.

A BONDADE DO SENHOR,
NOS DÁ FORÇA E VIGOR
SUA PALAVRA É QUAL LUZ
QUE MEUS PASSOS CONDUZ
NÃO TEMEREI POIS COMIGO
VAI JESUS

O SENHOR É MEU PASTOR
O MEU GUIA E REI
O SENHOR É A FORÇA E A LUZ DO VIVER
AO SEU LADO EU SEMPRE ESTAREI.

SEU PERDÃO É COMPLETO
SEU AMOR SEM IGUAL
SOB SUAS ASAS SEGURO ESTAREI
SEU AMOR TRANSFORMOU O MEU SER.

A BONDADE DO SENHOR,
NOS DÁ FORÇA E VIGOR
SUA PALAVRA É QUAL LUZ
QUE MEUS PASSOS CONDUZ
NÃO TEMEREI POIS COMIGO VAI JESUS
QUE DAREI AO MEU SENHOR
POR SEU TÃO GRANDE AMOR.

POIS ME FEZ RENASCER E EU NÃO
POSSO ENTENDER
NEM EXPLICAR TAL MILAGRE DO CÉU
DAR A VIDA AO MAIOR PECADOR
QUE SOU EU.
');
