INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('71e22ca4-edf7-408e-a381-3ed4ce5feff1', 'Jesus, Deus santo, santo, santo!', '611', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Louvor', 'CANTAR 2X
JESUS, DEUS SANTO, SANTO, SANTO!
DEUS DE PERDÃO E AMOR,
DEUS DE PAZ, EMANUEL!
Ó FILHO DE DAVI, ESTRELA DA MANHÃ,
REI DOS REIS, EU TE ADORO, LOUVO,
TE ESPERO, AMADO MEU, MEU JESUS!
');
