INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7265fdf8-cb23-4ce6-9231-cee9791f308a', 'Abre o Coração', '', '', '', '', '', 'ABRE O CORAÇÃO
DEIXA O SENHOR ENTRAR,
E MODIFICAR PRA SEMPRE
O TEU VIVER, 
E NESTE LOUVOR DEUS VAI
SE REVELAR, PARA
RESTAURAR TEU CORAÇÃO.

*CORO
O SENHOR SÓ QUER DE TI
SINCERIDADE,
(ELE VÊ TEU CORAÇÃO)
PRA PODER AGIR EM TEU FAVOR.
(PARA AGIR EM TEU FAVOR)
O SENHOR SÓ QUER DE TI
SINCERIDADE,
(ELE VÊ TEU CORAÇÃO)
PARA DERRAMAR O SEU AMOR.

ABRE O CORAÇÃO,
DEIXA O SENHOR ENTRAR,
(DEIXA ENTRAR)
E MODIFICAR PRA SEMPRE
O TEU VIVER.
(O TEU VIVER) 
E NESTE LOUVOR DEUS VAI
SE REVELAR,
(SE REVELAR)
PARA RESTAURAR TEU CORAÇÃO.

*CORO 2X
O SENHOR SÓ QUER DE TI
SINCERIDADE,
(ELE VÊ TEU CORAÇÃO)
PRA PODER AGIR EM TEU FAVOR.
(PARA AGIR EM TEU FAVOR)
O SENHOR SÓ QUER DE TI
SINCERIDADE,
(ELE VÊ TEU CORAÇÃO)
PARA DERRAMAR O SEU AMOR.
');
