INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('72aa650f-559f-4976-a2b0-0d2c60188fc2', 'Tenho algo pra você', 91, 'P.L.C.', 'Fox', 'G', 'Crianças e Adolescentes', 'TENHO ALGO PRA VOCÊ NESTA CANÇÃO:
TEM ALGUÉM QUE MORA EM MEU CORAÇÃO.
ESTE ALGUÉM DESEJA DAR A VOCÊ O PERDÃO.

FINAL 2X
ESTE ALGUÉM É MUITO IMPORTANTE!
ESTÁ BEM PERTO DE VOCÊ
A TODO INSTANTE.
ELE SÓ POR NÓS MORREU NUMA CRUZ.
ESTE ALGUÉM, LHE DIGO, É: JESUS!
');
