INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('732d6058-e74a-4c17-b48e-40a30801f98e', 'Tu, Ó Senhor Aviva a Tua Obra', '461', 'Sérgio Paulo Ferreira de Matos', 'Canção', 'F', 'Santificação e Derramamento', 'TU, Ó SENHOR, TU ÉS TÃO PURO DE OLHOS
E NÃO PODES VER O MAL,
NEM INJUSTIÇA PODES CONTEMPLAR.
ESCUTA, SENHOR, A NOSSA ORAÇÃO VEM OUVIR
E AVIVA, SENHOR, A TUA OBRA!

A TUA VOZ ESCUTAMOS COM TEMOR,
POIS SABEMOS QUE O TEU
JUÍZO BREVE VEM A TODA TERRA.
NA IRA, Ó DEUS,
VEM TER MISERICÓRDIA DE NÓS
E AVIVA, SENHOR, A TUA OBRA!

SENHOR, NA TUA IRA, Ó DEUS,
VEM TER MISERICÓRDIA DE NÓS
E AVIVA, SENHOR, A TUA OBRA! (2X)
');
