INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('735f3826-cb03-4816-8a17-d5cd76705e09', 'Daniel na cova dos leões', '167', 'J. P.', 'Fox', 'D', 'Crianças e Adolescentes', 'DANIEL TRÊS VEZES AO DIA
BUSCAVA AO SENHOR,
DE JOELHOS ELE ORAVA
E GLORIFICAVA A DEUS.

CERTO DIA O ENCONTRARAM ORANDO
PROSTRADO AO SEU DEUS,
SEUS INIMIGOS CONTARAM AO REI
E PEDIRAM PARA QUE CUMPRISSE A LEI.

*CORO
DANIEL NA COVA DOS LEÕES,
UM ANJO APARECEU.
DANIEL NA COVA DOS LEÕES,
O SEU DEUS O PROTEGEU.
/INSTRUMENTOS

DANIEL FOI SALVO POR SEU DEUS
E O REI COMPREENDEU.
SEUS INIMIGOS FORAM PUNIDOS
E O REI LOGO DECRETOU
QUE O DEUS DE DANIEL
É DEUS VIVO E SALVADOR.

*CORO 2X
DANIEL NA COVA DOS LEÕES,
UM ANJO APARECEU.
DANIEL NA COVA DOS LEÕES,
O SEU DEUS O PROTEGEU.
');
