INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('73ae1bf6-dde1-485e-8ad0-4550f82d8964', 'Eu sou uma ovelhinha de Jesus', '026', 'M.C.H.O.', 'Fox', 'D', 'Crianças e Adolescentes', 'EU SOU UMA OVELHINHA DE JESUS.
EU SOU UMA OVELHINHA DE JESUS.
JESUS É O BOM PASTOR,
JESUS CUIDA DE MIM
EU SOU UMA OVELHINHA DO SENHOR.

BEM CEDO AO LEVANTAR EU VOU ORAR,
AGRADECER A NOITE QUE ME DEU;
EU LOUVOR COM AMOR
E DIGO SEMPRE ASSIM:
EU SOU UM PEQUENINO DO SENHOR. (2X)
');
