INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('747ffd64-071b-4418-8456-0254b0648eba', 'Aguardando a orientação do salvador', '199', 'M.D.', 'Marcha Marcial', 'G', 'Crianças e Adolescentes', 'AGUARDANDO A ORIENTAÇÃO DO SALVADOR,
COM JESUS MARCHAMOS,
SEGUINDO SEM PARAR.
A BANDEIRA DA VITÓRIA CONOSCO ESTÁ.
OH! GLÓRIA, HOSANA AO REI!
JESUS VENCENDO VEM!

PELA FÉ AVISTAMOS NOSSO LAR,
ANSIOSOS PARA O ENCONTRO
COM JESUS.
TODA LÁGRIMA ELE ENXUGARÁ.
OH! GLÓRIA, HOSANA AO REI!
JESUS VENCENDO VEM!
/INSTRUMENTOS

COM OS ANJOS CANTAREMOS LÁ NO CÉU
LOUVORES AO CORDEIRO QUE VENCEU.
A COROA ELE NOS DARÁ.

FINAL 2X
OH! GLÓRIA, JESUS VENCENDO VEM!
(GLÓRIA, GLÓRIA, GLÓRIA)
OH! GLÓRIA, JESUS VENCENDO VEM!
');
