INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7495838d-94bc-4688-88cc-90821c3e45ee', 'Eu não sei qual será meu louvor', '', '', '', '', '', 'CORO 2X
NÃO A NÓS, SENHOR, (2X)
MAS AO TEU NOME DÁ GLÓRIA!
POR AMOR DA TUA MISERICÓRDIA
E DA TUA FIDELIDADE.

POR QUE PERGUNTAM AS NAÇÕES:
ONDE ESTÁ O VOSSO DEUS?
NO CÉU ESTÁ O NOSSO DEUS,
E TUDO FAZ COMO LHE AGRADA.

POR QUE CONFIAM AS NAÇÕES
EM OURO, PRATA E RIQUEZAS?
E SE AFASTAM DO SENHOR,
QUE É FONTE DE TODAS AS BÊNÇÃOS!

FINAL
NÃO A NÓS, SENHOR, (2X)
MAS AO TEU NOME DÁ GLÓRIA!
');
