INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7521632d-d8fb-44ef-9888-4a21c1917e99', 'Eis o Cordeiro de Deus', '024', 'Antônio Augusto Thomazini Malaquias', 'Básico', 'C', 'Clamor', 'EIS O CORDEIRO DE DEUS
QUE TIRA O PECADO DO MUNDO,
QUE MORREU NO MEU LUGAR,
ENTÃO PODE ME PERDOAR.

*CORO
CLAMO AGORA PEDINDO:
VEM PERDOAR, (VEM PERDOAR)
PURIFICAR, (PURIFICAR)
VEM TRANSFORMAR E RENOVAR,
VEM RESTAURAR.

DIANTE DO TEU ALTAR
DEIXO A MINHA ANSIEDADE,
PELO SANGUE DE JESUS,
TENHO VIDA.

*CORO
CLAMO AGORA PEDINDO:
VEM PERDOAR, (VEM PERDOAR)
PURIFICAR, (PURIFICAR)
VEM TRANSFORMAR E RENOVAR,
VEM RESTAURAR.
/FINAL
VEM RESTAURAR.
');
