INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7567db30-825e-4897-895b-9952db1ec37c', 'Há um óleo', '', '', '', '', '', 'HÁ UM ÓLEO QUE PROCEDE LÁ DO ALTO,
ELE DESCE LÁ DAS MÃOS DO MEU JESUS.
SEPANDO O ESCOLHIDO, E ENCHENDO
COM O ESPÍRITO, PARA SER USADO COM
PODER DE DEUS.

HÁ UM ÓLEO QUE PROCEDE LÁ DO ALTO,
ELE DESCE LÁ DAS MÃOS DO MEU JESUS.
É O ÓLEO DA UNÇÃO, TRÁS DO CÉU A
CONDIÇÃO, PARA SER USADO COM
PODER DE DEUS.

FINAL 2X
ATENDE AO CHAMADO,
SERÁS SEPARADO PRA SERVIR
COM SUBMISSÃO AO REI JESUS.
NÃO TEMAS MEU FILHO,
TEU DEUS É CONTIGO.
É SÓ ANDAR NA DIREÇÃO
E OBEDECER.
');
