INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('75721372-eee7-4e79-ad93-bd3829526ec8', 'Clamo, ó Senhor', '004', 'E.H.M.R.', 'Balada', 'E', 'Crianças e Adolescentes', 'CLAMO, Ó SENHOR, PELO SANGUE DE JESUS,
NA TUA PRESENÇA LIMPO QUERO ESTAR,
E SÓ LAVADO NESTE SANGUE
NO SANTO DOS SANTOS POSSO ENTRAR.
(2X)
LAVA-ME, SENHOR
VISITA-ME SENHOR,
COM O ESPÍRITO SANTO
O CONSOLADOR
TEREI PLENA COMUNHÃO
E A TUA PROTEÇÃO
');
