INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('757d19e4-7c07-46ba-99ef-6e97611c9621', 'Perdoa-me, Senhor', '006', 'J.J.G.', 'Básico', 'G', 'Crianças e Adolescentes', 'PERDOA-ME, SENHOR,
CLAMO PELO SANGUE DE JESUS;
QUERO RENOVAR A MINHA COMUNHÃO.
PERDOA-ME, SENHOR,
QUERO DEPOSITAR O MEU CORAÇÃO
SEMPRE EM TEU ALTAR.

VISITA-ME COM O TEU ESPÍRITO
E FAZE-ME HABITAR
AO TEU LADO ETERNAMENTE!
');
