INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('760589ac-6c25-4be5-852d-0a95f1e9fd4c', 'O dia está chegando', '198', 'A.V.', 'Básico', 'D', 'Crianças e Adolescentes', 'O DIA ESTÁ CHEGANDO,
AS HORAS ESTÃO PASSANDO,
O DIA JÁ VAI CHEGAR
E JESUS VAI VOLTAR!
O TEMPO SE APRESSA,
O AMOR SE ESFRIANDO,

PESSOAS NÃO SE FALANDO.
MAS JESUS VAI VOLTAR!
POIS ASSIM SERÁ QUANDO JESUS VOLTAR.
ASSIM SERÁ QUANDO JESUS VOLTAR.
VAI VOLTAR, VAI VOLTAR!
/INSTRUMENTOS

MENSAGENS REVELADAS,
ESCRITAS POR JESUS,
PARA NOS PREPARAR,
PORQUE JESUS VAI VOLTAR.

PREPARANDO OS CORAÇÕES
PARA JESUS ENCONTRAR,
JESUS, MEU BOM PASTOR,
QUE ME FAZ VENCEDOR.

ESTAMOS PREPARANDO,
ESTAMOS PREPARANDO OS CORAÇÕES.
ESTAMOS PREPARANDO,
PREPARANDO OS CORAÇÕES.
PORQUE JESUS VAI VOLTAR, VAI VOLTAR,
VAI VOLTAR! VAI VOLTAR!
');
