INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7662e393-ff91-4d43-ac28-75f9552b946e', 'Ele Voltará Pra Buscar a Sua Igreja', '490', 'Autor Desconhecido', 'Balada', 'C', 'Volta de Jesus e Eternidade', 'ELE VOLTARÁ PRA BUSCAR A SUA IGREJA,
QUE AQUI NO MUNDO FOI FIEL;
ELE VOLTARÁ E MUITOS NÃO ACREDITAM,
ESSES TAIS FICARÃO,
SOFRENDO, SEM TER SALVAÇÃO.

*CORO
ELE PODE VOLTAR AGORA,
NINGUÉM SABE O DIA NEM A HORA
QUE ELE VOLTARÁ.
ELE PODE VOLTAR HOJE MESMO,
PREPARA-TE, IRMÃO, PRA NÃO FICAR.

ELE VOLTARÁ, POIS ASSIM
NOS AFIRMA A BÍBLIA,
MAIS PERTO DE DEUS DEVEMOS FICAR.
ELE VOLTARÁ, ACERTA A TUA VIDA
DIANTE DE DEUS, DE SEU SANTO ALTAR.

*CORO
ELE PODE VOLTAR AGORA,
NINGUÉM SABE O DIA NEM A HORA
QUE ELE VOLTARÁ.
ELE PODE VOLTAR HOJE MESMO,
PREPARA-TE, IRMÃO, PRA NÃO FICAR.
/FINAL
PREPARA-TE, IRMÃO, PRA NÃO FICAR.
');
