INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('76e4d61d-2909-4507-b4d0-3218ab30cad8', 'Já Não Tarda o Amanhecer', '517', 'Sérgio Paulo Ferreira de Matos', 'Fox Abafado', 'C', 'Volta de Jesus e Eternidade', 'JÁ NÃO TARDA O AMANHECER,
A ALVORADA DE UM NOVO SER;
PELOS MONTES DE LUZ
JÁ VEM O MEU JESUS!

ELE MANDA ME LEVANTAR,
HÁ UMA FESTA A CELEBRAR;
COM AMOR EU IREI CANTAR
LOUVORES AO REI!
ALELUIA, ALELUIA, ALELUIA,
NÃO TARDA O AMANHECER!

A FIGUEIRA SEUS FRUTOS DÁ,
A VIDEIRA EM FLOR ESTÁ,
O INVERNO PASSOU
E A CHUVA JÁ CESSOU;
TODA A TERRA RENASCE EM FLOR,
PRIMAVERA, CANTANDO AMOR;

ESTÁ TÃO PERTO DE NÓS,
JÁ OUÇO A SUA VOZ!
ALELUIA, ALELUIA, ALELUIA,
JÁ OUÇO A SUA VOZ!

SOPRA O VENTO NO MEU JARDIM,
QUERO A TEMPO TER FLOR EM MIM,
SEU PERFUME SEM PAR
DESEJO DERRAMAR;

SE DESCESSES DO ALTO CÉU
E VIESSES, AMADO MEU,
E COMESSES DO FRUTO
QUE TE QUERO DAR!
ALELUIA, ALELUIA, ALELUIA,
O MEU AMADO VEM!
');
