INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('77d3a581-0d9a-4bf2-9745-834f90847fcd', 'Transborda-me, Senhor', '029', 'Miriam Samú Amiel', 'Básico', 'G', 'Clamor', 'CANTAR 2X
TRANSBORDA-ME, SENHOR, 
DÁ-ME COMUNHÃO;
SENTIR TUA PRESENÇA EU QUERO, Ó PAI;
FALA AO MEU CORAÇÃO, NO SANGUE HÁ VIDA,
HÁ LIBERTAÇÃO, SEGURANÇA E PAZ,
TOCA-ME, SENHOR.

FINAL
HÁ LIBERTAÇÃO,
SEGURANÇA E PAZ,
TOCA-ME, SENHOR.
');
