INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('77d5f71f-ebab-4248-8a59-8b14df3467dd', 'Bendizei ao Senhor', '665', 'Waldemiro Duque da Silva', 'Básico', 'Cm', 'Salmos de Louvor', 'BENDIZEI AO SENHOR
VÓS TODOS, SERVOS DO SENHOR,
QUE ASSISTIS NA CASA DO SENHOR
NAS HORAS DA NOITE.

ERGUEI AS MÃOS NO SANTUÁRIO
E BENDIZEI AO SENHOR;
DE SIÃO TE ABENÇOE O SENHOR,
CRIADOR DO CÉU E DA TERRA.

BENDIZEI AO SENHOR
VÓS TODOS, SERVOS DO SENHOR,
QUE ASSISTIS NA CASA DO SENHOR
NAS HORAS DA NOITE.

FINAL
ERGUEI AS MÃOS NO SANTUÁRIO
E BENDIZEI AO SENHOR;
DE SIÃO TE ABENÇOE O SENHOR,
CRIADOR DO CÉU E DA TERRA.
');
