INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('782a3bc5-911b-4678-8e35-63b909232646', 'Toda terra te exalta', '637', 'Rodrigo Assis Barbosa', 'Básico', 'F', 'Louvor', 'TODA A TERRA TE EXALTA,
ENGRANDECE O TEU NOME
PELAS GRANDES MARAVILHAS QUE TENS FEITO;
COM PODER DOMINAS O MUNDO,
REINAS SOBRE CÉU E MAR,
ÉS O CORDEIRO PROMETIDO QUE VEIO PRA SALVAR.

*CORO 2X
ENGRANDECIDO SEJA O TEU NOME
POIS ÉS GRANDE ENTRE AS NAÇÕES,
TE EXALTAREI ENQUANTO EU VIVER.
/INSTRUMENTOS

OS MEUS LÁBIOS PRONUNCIAM
TUA VERDADE DIA E NOITE,
ÉS O GRANDE EU SOU, ETERNO EL-SHADAI;
POR AMOR VERTESTE SANGUE
PRA DAR VIDA AO PECADOR;
LOUVAREMOS AO TEU NOME,
POIS ÉS DIGNO DE LOUVOR.

*CORO 2X
ENGRANDECIDO SEJA O TEU NOME
POIS ÉS GRANDE ENTRE AS NAÇÕES,
TE EXALTAREI ENQUANTO EU VIVER.

TE EXALTAREI ENQUANTO EU VIVER!
ENGRANDECIDO SEJA O TEU NOME,
SENHOR REI, SENHOR, REDENTOR;
LOUVAREI PARA SEMPRE O TEU NOME
ENQUANTO EM MIM HOUVER
FÔLEGO DE VIDA;

ENTRONIZADO ESTÁS ENTRE OS QUERUBINS,
TE LOUVAREI ATÉ O FIM, (SIM, EU LOUVAREI)
TE LOUVAREI ATÉ O FIM, (HONRA E LOUVOR)
TE LOUVAREI, SENHOR, ATÉ O FIM.
');
