INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7934287a-0f0f-4cb6-8c68-afd301b9cc4f', 'Tua, ó Deus, é toda a grandeza', '698', 'João Gomes da Rocha', 'Balada', 'D', 'Grupo de Louvor', 'TUA, Ó DEUS, É TODA A GRANDEZA, (3X)
E O PODER, E A GLÓRIA, E A VITÓRIA,
E OS LOUVORES. VITÓRIA E LOUVORES.

TUA, Ó DEUS, TUA, Ó DEUS;
É A GRANDEZA, E O PODER,
(A GRANDEZA E O PODER),
E A GLÓRIA, E A VITÓRIA,
EE OS LOUVORES ETERNOS;

POIS TUDO O QUE ESTÁ NO MAR,
E ESTÁ NO CÉU E NA TERRA É TEU!
TEU É O IMPÉRIO. 
TEU É O IMPÉRIO, Ó SENHOR!
E TU ÉS ACIMA DE TODOS OS REIS,
DE TODOS OS REIS.
AMÉM. AMÉM. ALELUIA!
');
