INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('796b5a18-f2af-4a97-b7e4-be9f541344a4', 'Queres ser feliz', 84, 'M.S.A.', 'Country', 'G', 'Crianças e Adolescentes', 'CANTAR 2X
QUERES SER FELIZ,
CONHECER JESUS?
ELE VAI TE DAR ALEGRIA,
VIDA E PAZ.
EU JÁ SOU FELIZ,
DEI MEU CORAÇÃO
E JESUS EM MIM VEIO HABITAR
