INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('797e9106-5fcc-48f2-811f-aaa6f8f015c0', 'Ó Pastor de Israel', '423', 'Sérgio Paulo Ferreira de Matos', 'Básico 2', 'C', 'Santificação e Derramamento', 'Ó PASTOR DE ISRAEL, QUE GUIAS TEU POVO
E TE ASSENTAS ENTRE OS QUERUBINS,
RESPLANDECE!

*CORO
VEM, VISITA A TUA VINHA
QUE PLANTASTE COM TUA DESTRA,
RESPLANDECE SOBRE NÓS O TEU ROSTO;
DOS QUE A QUEREM DEVORAR,
TUA VINHA VEM GUARDAR,
RESPLANDECE SOBRE NÓS O TEU ROSTO!

Ó PASTOR DE ISRAEL,
FAZE BRILHAR TUA GLÓRIA
E DESPERTA O TEU PODER
NO MEIO DO TEU POVO.

*CORO
VEM, VISITA A TUA VINHA
QUE PLANTASTE COM TUA DESTRA,
RESPLANDECE SOBRE NÓS O TEU ROSTO;
DOS QUE A QUEREM DEVORAR,
TUA VINHA VEM GUARDAR,
RESPLANDECE SOBRE NÓS O TEU ROSTO!
/INSTRUMENTOS

*CORO
VEM, VISITA A TUA VINHA
QUE PLANTASTE COM TUA DESTRA,
RESPLANDECE SOBRE NÓS O TEU ROSTO;
DOS QUE A QUEREM DEVORAR,
TUA VINHA VEM GUARDAR,
RESPLANDECE SOBRE NÓS O TEU ROSTO!
/FINAL
O TEU ROSTO
');
