INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('799c5a46-1a28-4171-a187-c00080677dcb', 'Meu Deus meu Bom Pastor', '414', 'Everaldo Cavalcante Lima', 'Balada', 'G', 'Santificação e Derramamento', 'MEU DEUS, MEU BOM PASTOR,
GUIAR-ME VEM PELA MÃO
PORQUE SOU FRACO, SENHOR;
DÁ-ME TUA PROTEÇÃO!
JESUS, MEU SALVADOR,
TRANSBORDA-ME DE AMOR
E EU SEREI TEU FIEL SERVIDOR!

DE MANHÃ, LOGO CEDO,
TUA FACE BUSCAR
QUERO, SENHOR, E EM SEGREDO,
MINHA VIDA TE DAR;
E QUANDO O DIA FINDAR
POR TEU SANGUE VOU CLAMAR,
QUERO TORNAR-ME UM FIEL SERVIDOR!
/INSTRUMENTOS

SENDO AGORA TEU SOMENTE,
VEM DE PODER E AMOR
ENCHER-ME, Ó ONIPOTENTE,
E GLÓRIA TE DOU, MEU SENHOR;
MEU DEUS, MEU GUARDADOR,
GLÓRIA E ALELUIA COM ARDOR,
EIS-ME TORNADO UM FIEL SERVIDOR! (2X)
');
