INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7a734986-54c0-4461-935e-6f6591838b47', 'É tão triste não ver a luz (Cego bastimeu)', '062', 'M.L.M.B.O.', 'Novo', 'G', 'Crianças e Adolescentes', 'É TÃO TRISTE NÃO VER A LUZ,
A ESCURIDÃO DESSA VIDA VIVER,
À BEIRA DO CAMINHO
BARTIMEU VIVIA A SOFRER.

MAS UMA VOZ DE ESPERANÇA
AOS SEUS OUVIDOS UM DIA CHEGOU,
A MULTIDÃO O IMPEDIA
E O CEGO BEM ALTO GRITOU:

"OH! JESUS, FILHO DE DAVI,
TEM MISERICÓRDIA DE MIM;"
QUERIA VER O SOL NASCER,
A LUZ DA VIDA RESPLANDECER.

E JESUS TEVE COMPAIXÃO,
DEU-LHE CURA E REDENÇÃO,
E FELIZ PELO CAMINHO A JESUS SEGUIU.

É TÃO TRISTE NÃO VER A LUZ,
A ESCURIDÃO DESSA VIDA VIVER,
À BEIRA DO CAMINHO
BARTIMEU VIVIA A SOFRER.

MAS UMA VOZ DE ESPERANÇA
AOS SEUS OUVIDOS UM DIA CHEGOU,
A MULTIDÃO O IMPEDIA
E O CEGO BEM ALTO GRITOU:

"OH! JESUS, FILHO DE DAVI,
TEM MISERICÓRDIA DE MIM;"
QUERIA VER O SOL NASCER,
A LUZ DA VIDA RESPLANDECER.

E JESUS TEVE COMPAIXÃO,
DEU-LHE CURA E REDENÇÃO,
E FELIZ PELO CAMINHO A JESUS SEGUIU.
