INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7afd2215-1c13-447b-a87c-9748b3bbb414', 'Quando ouvi Jesus me chamar', 81, 'E.A.Jr.', 'Novo', 'C', 'Crianças e Adolescentes', 'QUANDO OUVI JESUS ME CHAMAR
PENSEI QUE ERA IRREAL,
SUA VOZ DOCE E MEIGA A DIZER:
"VINDE PEQUENINOS DO PAI".

ENTÃO PUDE CRER QUE JESUS
QUER USAR-ME TAMBÉM.
AINDA PEQUENINO SOU,
MAS POSSO LEVAR,
DE DEUS, A MENSAGEM DE AMOR.

*CORO
QUEM QUER SUBIR PARA O CÉU
PEQUENO SE FAÇA TAMBÉM,
ENTREGA TUA VIDA A JESUS,
O PAI CELESTE
QUE DESEJA A TI TODO BEM.

SE QUERES TER DE CRISTO O PERDÃO
ABRE HOJE O TEU CORAÇÃO.
DEIXE CRISTO ENTRAR E REINAR
E A PAZ EM TUA VIDA NUNCA IRÁ FALTAR.

*CORO 2X
QUEM QUER SUBIR PARA O CÉU
PEQUENO SE FAÇA TAMBÉM,
ENTREGA TUA VIDA A JESUS,
O PAI CELESTE
QUE DESEJA A TI TODO BEM.
/FINAL
O PAI CELESTE
QUE DESEJA A TI TODO BEM.
');
