INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7b3536f9-fefa-4cf1-86c6-d84d2c31a226', 'Eu preciso de ti', '', '', '', '', '', 'SENHOR, EU ME AJOELHO
A TEUS PÉS, (SENHOR)
TE PEÇO PERDÃO, COMUNHÃO.
(TE PEÇO, SENHOR)
EU QUERO A CADA DIA ESTAR,
(CONTIGO MEU DEUS)
POR ONDE QUER QUE EU VÁ.

EU PRECISO DE TI (DE TI)
SENHOR, OUVE A MINHA ORAÇÃO.
(MEU DEUS, MEU PAI)
ATENDE A MINHA SÚPLICA, (SENHOR)
PORQUE PRECISO TANTO DE TI,
(TANTO DE TI)
TANTO DE TI, NA MINHA VIDA.

EU PRECISO DE TI (DE TI)
SENHOR, OUVE A MINHA ORAÇÃO.
(MEU DEUS, MEU PAI)
ATENDE A MINHA SÚPLICA, (SENHOR)

FINAL 2X
PORQUE PRECISO TANTO DE TI,
(TANTO DE TI)
TANTO DE TI, NA MINHA VIDA.
');
