INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7bd659d2-38a7-4d2f-962e-544372279826', 'Cortaram o madeiro', '211', 'Catarino Varjão', 'Balada', 'E', 'Morte, Ressureição e Salvação', 'CORTARAM O MADEIRO, FIZERAM UMA CRUZ
PARA O MEU SALVADOR; 
MADEIRO LAVRADO, COM PREGOS CRAVADOS,
PESADA FICOU.
ELE CARREGOU A CRUZ, NO CAMINHO CAIU,
MAS DEUS DEU-LHE GRAÇA
MORRENDO NA CRUZ POR TI E POR MIM.

CORO
FOI FEITA ASSIM A CRUZ DO SALVADOR;
MADEIRO LAVRADO, COM PREGOS CRAVADOS,
PESADA FICOU.

PERANTE PILATOS,
JESUS FOI LEVADO COMO UM MALFEITOR;
CHEGANDO A ELE,
OLHANDO O MESTRE, ASSIM PERGUNTOU:
ÉS O REI DOS JUDEUS? DISSE JESUS:
NA VERDADE EU SOU, 
O MEU REINO É ETERNO,
NÃO É DESTE MUNDO, DAQUI EU NÃO SOU.

CHEGANDO AO CALVÁRIO,
PREGARAM NA CRUZ O MEU SALVADOR;
UMA COROA DE ESPINHOS,
NA FRONTE SANGRANDO, AO PAI SUPLICOU;
TRANSPASSADO DE DOR FICOU
O MEU SALVADOR.
ÀS TRÊS HORAS DA TARDE,
INCLINOU A CABEÇA E ALI EXPIROU.
');
