INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7c6c5bd2-9b57-45b9-a86b-a0bba8e9ca24', 'Resplandece, ó Jerusalém', '709', 'L.C.M.S', 'Balada', 'Gm', 'Grupo de Louvor', 'RESPLANDECE Ó JERUSALÉM!
PORQUE NASCE SOBRE TI A TUA LUZ.
JERUSALÉM, ÉS ILUMINADA
PELA GLÓRIA DO SENHOR,
AS TUAS RUAS SÃO DE OURO, 
Ó QUANTO ALMEJO NELAS ANDAR.

JERUSALÉM, Ó QUANTO ALMEJO ESTAR
AO LADO DO MEU SENHOR
PRA SEMPRE O ADORAR.
JERUSALÉM, POR TUAS PORTAS VOU ENTRAR
E EM CORO CELESTIAL,
A JESUS ADORAR.
/INSTRUMENTOS

(H) DENTRO DOS TEUS MUROS,
(M) (Ó JERUSALÉM),
(H) ASSENTA-SE NO TRONO
À DESTRA DE DEUS PAI,
O NOSSO REI, O CORDEIRO QUE VENCEU.

CANTAR 3X
JERUSALÉM, QUERO CONTEMPLAR,
A TUA GLÓRIA COMO A GLÓRIA DO SENHOR, 
QUERO HABITAR DENTRO
DOS TEUS MUROS.
/FINAL
Ó JERUSALÉM (JERUSALÉM).
');
