INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7ca36b77-78b4-4835-acc6-b08968adc637', 'Um novo céu, uma nova terra se fará', '183', 'E.H.M.R.', 'Valseado', 'C', 'Crianças e Adolescentes', 'UM NOVO CÉU,
UMA NOVA TERRA SE FARÁ,
NOVO NOME NUMA PEDRA BRANCA RECEBEREI,
NA CIDADE DE LUZ ETERNA IREI MORAR
PARA SEMPRE COM O SALVADOR;
RUAS DE OURO ANDAREI,
RIO DA VIDA CONTEMPLAREI
E MUITO LOUVOR ALI ENTOAREI,

NÃO HAVERÁ DOR, PRANTO OU CLAMOR,
TODA LÁGRIMA JESUS VAI ENXUGAR.
NÓS SEREMOS O SEU POVO ETERNAMENTE
E DEUS NOSSO TABERNÁCULO PARA SEMPRE;
SE VOCÊ QUISER VIR A CRISTO,
ABRA AGORA O SEU CORAÇÃO
E DEIXA JESUS FAZER DA SUA VIDA
MORADA ETERNA DE DEUS.
');
