INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7cf98f00-274e-48da-ad0a-b4bc061bc79c', 'O Senhor é Minha Luz', '', '', '', '', '', 'O SENHOR É MINHA LUZ,
E MINHA SALVAÇÃO.
A QUEM EU TEMEREI?
A QUEM EU TEMEREI?
O SENHOR É O PODER
DE MINHA VIDA.
O SENHOR É TODO O
PODER DA MINHA VIDA.

MESMO QUE UM EXÉRCITO ME CERQUE,
MEU CORAÇÃO JAMAIS TEMERÁ.
INDA QUE A GUERRA SE ERGA CONTRA
MIM, SE ERGA CONTRA MIM,
NÃO TEMEREI, EU NÃO TEMEREI.

EU CONFIAREI EM DEUS, SIM,
CONFIAREI EM DEUS.
POIS AO CHEGAR À PROVA, HÁ DE
OCULTAR-ME EM SEU TABERNÁCULO,
SIM, NO SECRETO E OCULTO
PAVILHÃO ME ESCONDERÁ.

E POR-ME-Á EM CIMA DE UMA ROCHA.
E POR-ME-Á EM CIMA DE UMA ROCHA.
EM CIMA DE UMA ROCHA.
O SENHOR É MINHA LUZ,
E MINHA SALVAÇÃO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('7cf98f00-274e-48da-ad0a-b4bc061bc79c', '45ab58b2-d293-45c7-aa75-090fcd968b24');
