INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7d367352-9dea-428f-9253-2950e0986296', 'Jesus viu a multidão (A multiplicação)', '071', 'M.L.M.B.O.', 'Fox', 'Bm', 'Crianças e Adolescentes', 'JESUS VIU A MULTIDÃO
E NÃO OS DEIXOU IR
ESTAVAM TÃO FAMINTOS,
COMO PODIAM PARTIR?
ENTÃO ELE ORDENOU;
"DAI-LHES DE COMER",
OS DISCÍPULOS PERGUNTARAM:
SENHOR, O QUE VAMOS FAZER?
/INSTRUMENTOS

CINCO PÃES E DOIS PEIXINHOS
CINCO MIL ALIMENTOU,
ASSENTADOS SOBRE A RELVA,
TODO O POVO SE FARTOU.

FINAL 2X
JESUS É A SOLUÇÃO,
ELE É A PROVISÃO,
O FILHO DO DEUS VIVO
FAZ A MULTIPLICAÇÃO.
');
