INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7d8d1048-b46b-4bf1-8a16-3e01021aafdb', 'Vem para o meio (Águas de salvação)', 68, 'E.H.M.R.', 'Country', 'G', 'Crianças e Adolescentes', 'VEM PARA O MEIO
DE UM POVO QUE SABE
O CAMINHO DA ETERNIDADE,
ONDE A PROFECIA APONTA A DIREÇÃO;
ESSE POVO SEGUE E ALCANÇA SALVAÇÃO.

VEM PARA O MEIO, JESUS ESTÁ AQUI.
MERGULHA NESSAS ÁGUAS DA SALVAÇÃO;
ESSAS ÁGUAS CURAM E NOVA CRIATURA
SERÁS, ENTÃO, PARA O LOUVOR DE DEUS.
/INSTRUMENTOS

VEM PARA O MEIO
DE UM POVO QUE SABE
O CAMINHO DA ETERNIDADE.
ONDE A PROFECIA APONTA A DIREÇÃO,
ESSE POVO SEGUE E ALCANÇA SALVAÇÃO.

VEM PARA O MEIO, JESUS ESTÁ AQUI.
MERGULHA NESSAS ÁGUAS DA SALVAÇÃO.
ESSAS ÁGUAS CURAM E NOVA CRIATURA
SERÁS, ENTÃO, PARA O LOUVOR DE DEUS.
');
