INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7dd67fad-d064-4276-9f17-277819a5b4b4', 'Senhor, eu quero servir-te', '448', 'Geraldo Gomes Pinheiro', 'Balada', 'E', 'Santificação e Derramamento', 'SENHOR, EU QUERO SERVIR-TE,
SERVIR-TE COM TODO O MEU SER,
CANTANDO, SEMPRE CANTANDO,
LOUVANDO COM TODO O PRAZER.

CORO
JESUS, JESUS,
FIRMADO EM TI QUERO ESTAR,
JESUS, JESUS,
NÃO QUERO, NÃO QUERO FALHAR.

PERMITE QUE EU FALE SOMENTE
DA GRAÇA E DO AMOR DIVINAL,
PROCLAME AS TUAS VERDADES
ATÉ A VITÓRIA FINAL.
');
