INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7e49a278-460a-470c-ad5e-caba112c0fef', 'O Sangue de Jesus, Vertido ali na Cruz', '032', 'Wilson Belchior', 'Básico 2', 'G', 'Clamor', 'O SANGUE DE JESUS,
VERTIDO ALI NA CRUZ,
TEM PODER PARA ME PURIFICAR;
O SANGUE DE JESUS,
VERTIDO ALI NA CRUZ,
TEM PODER PARA ME LIBERTAR.

PÕE TEU SANGUE EM MIM, SENHOR,
PÕE TEU SANGUE EM MIM!
E DÁ-ME LIBERTAÇÃO
E UMA PLENA COMUNHÃO.
');
