INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7e69fd62-8026-44a1-b0ab-b3c3793fac36', 'Ardendo em fogo minh’alma está', '787', 'Autor Desconhecido', 'Marcha', 'A', 'Santificação e Derramamento', 'ARDENDO EM FOGO MINH''ALMA ESTÁ!
ARDENDO EM FOGO MINH''ALMA ESTÁ!
GLORIOSA CHAMA ME LIMPARÁ.
OH! ALELUIA! MINH''ALMA ARDENDO ESTÁ!

OH! SENHOR, QUERO QUE ARDAS EM MEU SER
E COMO A SARÇA QUERO ARDER COM TEU PODER;
EM NOVAS LÍNGUAS VOU FALAR COMO SINAL,
ESTOU ARDENDO COM O FOGO CELESTIAL.

QUERO ADORAR-TE E AMAR-TE SÓ A TI,
COMO SE ADORA EM ESPÍRITO E EM VERDADE;
OH! SENHOR, QUERO QUE ARDAS EM MEU SER
E COMO A SARÇA QUERO ARDER COM TEU PODER.

FINAL
ARDENDO EM FOGO MINH''ALMA ESTÁ!
ARDENDO EM FOGO MINH''ALMA ESTÁ!
GLORIOSA CHAMA ME LIMPARÁ.
OH! ALELUIA! MINH''ALMA ARDENDO ESTÁ!
');
