INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7ea65a57-09f3-465e-8b97-913c1fbd7cb6', 'A minha alma espera', '205', 'N.R.R.A.', 'Country', 'D', 'Crianças e Adolescentes', 'A MINHA ALMA ESPERA,
NO SENHOR ESPERA E JUNTOS VAMOS ADORAR,
O GRANDE REI SENHOR, O NOSSO EMANUEL.
E JUNTOS VAMOS ADORAR.

VEM SENHOR!
A TUA IGREJA ESPERA E NÃO VAI TARDAR.
/CANTAR 2X
A NOIVA PREPARADA ESTÁ
E A IGREJA SUBIRÁ.
/INSTRUMENTOS

A MINHA ALMA ESPERA,
NO SENHOR ESPERA E JUNTOS VAMOS ADORAR,
O GRANDE REI SENHOR, O NOSSO EMANUEL.
E JUNTOS VAMOS ADORAR.

VEM SENHOR!
A TUA IGREJA ESPERA E NÃO VAI TARDAR.
/FINAL 2X
A NOIVA PREPARADA ESTÁ
E A IGREJA SUBIRÁ.
');
