INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7f1db64e-23ff-4bab-a78f-6aadb7330e56', 'seguir-te-ei', '123', 'Jorgemar Souza Madeira', 'Básico', 'C', 'Dedicação', 'CANTAR 2X
SEGUIR-TE-EI POR ONDE QUER QUE EU VÁ,
LOUVAR-TE-EI DE TODO CORAÇÃO;
ÉS PRECIOSO, AMADO E BOM JESUS,
ÉS MINHA VIDA, ÉS MINHA LUZ.

TEU GRANDE AMOR POR MIM
NÃO POSSO COMPARAR,
POR ISSO EU TE LOUVO,
SOFRESTE EM MEU LUGAR;
POR ISSO EU TE LOUVO,
MORRESTE PRA ME SALVAR.
/INSTRUMENTOS

FINAL
SEGUIR-TE-EI POR ONDE QUER QUE EU VÁ,
LOUVAR-TE-EI DE TODO CORAÇÃO;
ÉS PRECIOSO, AMADO E BOM JESUS,
ÉS MINHA VIDA, ÉS MINHA LUZ.
');
