INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7f54c330-1203-40d0-86dc-613e02f8aa09', 'Este mundo não é meu lugar', '157', 'C.M.V.C.S.', 'Fox Abafado', 'E', 'Crianças e Adolescentes', 'ESTE MUNDO NÃO É MEU LUGAR,
PEREGRINO, ESTOU A CAMINHAR.
MAS PARA O CÉU IREI
MORAR COM MEU BOM REI,
JESUS JÁ PREPAROU MEU NOVO LAR.

TORNOU-ME CIDADÃO DO CÉU POR SEU AMOR,
COM O SEU SANGUE ME COMPROU,
ETERNAMENTE AO SENHOR DAREI LOUVOR,
TODA GLÓRIA, HONRA, GRAÇA E AMOR.

SOU CIDADÃO DO CÉU,
A PÁTRIA CELESTIAL,
O GRANDE AMOR DE DEUS,
SUA GRAÇA ETERNAL,
ME CONCEDEU PERDÃO,
ME DEU A SALVAÇÃO,

POR ISSO, SOU CIDADÃO DO CÉU,
ALELUIA! SOU CIDADÃO DO CÉU.
ALELUIA! SOU CIDADÃO DO CÉU!
');
