INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7f87ba14-6980-48fb-9a9e-fa4686b8cb0d', 'Se não fosse o amor', '143', 'Ronaldo Duarte Barroso', 'Básico', 'A', 'Dedicação', 'SE NÃO FOSSE O AMOR
QUE DEUS POR MIM REVELOU,
EU NÃO ESTARIA AQUI;
ELE INCLINOU SEUS OLHOS
E PÔDE CONTEMPLAR
TODO SOFRIMENTO QUE PASSEI.

SE NÃO FOSSE O AMOR
QUE DEUS POR MIM MOSTROU,
JAMAIS CONSEGUIRIA ENTENDER
O GRANDE SACRIFÍCIO DE JESUS
POR MIM E POR TI.

SE NÃO FOSSE O AMOR
QUE DEUS POR MIM REVELOU,
EU NÃO ESTARIA AQUI;
ELE INCLINOU SEUS OLHOS
E PÔDE CONTEMPLAR
TODO SOFRIMENTO QUE PASSEI.

SE NÃO FOSSE O AMOR
QUE DEUS POR MIM MOSTROU,
JAMAIS CONSEGUIRIA ENTENDER
O GRANDE SACRIFÍCIO DE JESUS
POR MIM E POR TI.

FINAL 2X
A PAZ QUE TENHO EM JESUS
NÃO SE PODE COMPARAR
A TESOUROS DESTA VIDA AQUI,
A PAZ QUE FOI COMPRADA
COM SANGUE E COM DOR;
E HOJE É DADA A MIM E A TI,
A MIM E A TI POR CRISTO JESUS.
');
