INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7f8fd0d5-6896-44ca-a8b8-fd6247af4ef0', 'Um dia morreu o meu Jesus', 86, 'A.V.', 'Toada', 'D', 'Crianças e Adolescentes', 'UM DIA MORREU O MEU JESUS
NAQUELA CRUZ POR MIM,
O SANGUE DERRAMADO 
LIMPOU OS MEUS PECADOS.
EU VOU CANTAR, 
PORQUE JESUS ESTÁ AQUI.

*CORO
AGORA MEU JESUS VOU ADORAR,
EU VOU CANTAR (EU VOU CANTAR)
EU VOU LOUVAR COMO DAVI
AO DERROTAR OS QUE QUERIAM O ATINGIR.
/INSTRUMENTOS

JESUS, EU QUERO A MINHA VIDA TE ENTREGAR
E QUERO MAIS A TUA OBRA REALIZAR,
SERVI-LO SEMPRE DE TODO O CORAÇÃO
E SEMPRE EU CANTAREI ESTA CANÇÃO.

*CORO 2X
AGORA MEU JESUS VOU ADORAR,
EU VOU CANTAR (EU VOU CANTAR)
EU VOU LOUVAR COMO DAVI
AO DERROTAR OS QUE QUERIAM O ATINGIR.
');
