INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7fa4675e-550a-4beb-924e-670d55764ddf', 'Há Uma Luz a Brilhar', '397', 'Sérgio Paulo Ferreira de Matos', 'Valseado', 'G', 'Santificação e Derramamento', 'HÁ UMA LUZ A BRILHAR,
UMA ESTRELA A CINTILAR
GUIANDO O CRENTE EM JESUS;
HÁ UMA VOZ A SOAR
PELOS SÉCULOS SEM CESSAR,
QUE À VIDA ETERNA CONDUZ.

CORO
OH! EU QUERO ANDAR NESSA LUZ DIVINAL,
NA REVELAÇÃO QUE VEM DESDE OS CÉUS;
SÓ ASSIM VIVEREI,
NÃO NO TEMPO MORTAL,
MAS NA ETERNIDADE DE DEUS.

NÃO MAIS PELA RAZÃO 
QUE DITAR MEU CORAÇÃO,
MAS POR TUA PALAVRA IREI;
SEJA MEU TEU QUERER,
MINHA MENTE A DE JESUS,
NO TEMPO DE DEUS VIVEREI.

FINAL
SÓ ASSIM VIVEREI,
NÃO NO TEMPO MORTAL,
MAS NA ETERNIDADE DE DEUS.
');
