INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('7ff3793f-2d3c-4a46-9c9a-c8dbc1dacf4e', 'Junto a Ti (Minha Possessão Eterna)', '', '', '', '', '', 'JUNTO A TI, QUERO ESTAR,
EM TUA CASA HABITAR,
TEU AMOR EM MIM SENTIR,
TUA VOZ SUAVE OUVIR, JESUS!

*CORO
TU ÉS TUDO QUE EU
ALMEJO MINHA VIDA E LUZ,
CADA DIA TE DESEJO MAIS
E MAIS, JESUS.

PELO ALTAR JÁ PASSEI
E NO SANGUE ME LAVEI,
POSSO AGORA TE ADORAR
MINHA SEDE SACIAR, JESUS!

*CORO 3X
TU ÉS TUDO QUE EU
ALMEJO MINHA VIDA E LUZ,
CADA DIA TE DESEJO MAIS
E MAIS, JESUS.
');
