INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('80196f3e-f6da-4f26-a74e-1a8f7af7ce94', 'Enquanto, ó Salvador', '', '', '', '', '', 'ENQUANTO, Ó SALVADOR, TEU LIVRO LER,
MEUS OLHOS VEM ABRIR, TE QUERO VER;
À BEIRA MAR, JESUS, PARTISTE O PÃO,
SATISFAZENDO ALI A MULTIDÃO;

DÁ-ME A LETRA ALÉM, A TI, SENHOR,
DA VIDA O PÃO ÉS TU;
VEM, POIS, ASSIM,
EU BUSCO A TI, JESUS,
MEU REDENTOR.
SATISFAZER, SENHOR, A MIM!
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('80196f3e-f6da-4f26-a74e-1a8f7af7ce94', '45ab58b2-d293-45c7-aa75-090fcd968b24');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('80196f3e-f6da-4f26-a74e-1a8f7af7ce94', 'd369f950-5259-483c-9412-b0a37d90042c');
INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('c1e29cad-1e46-4dc3-8e0b-b1ee842e5089', '80196f3e-f6da-4f26-a74e-1a8f7af7ce94', 'c2fb644f-697c-4d43-9d5f-22319fa0ce79', 'pdf', 'assets/praises/80196f3e-f6da-4f26-a74e-1a8f7af7ce94/c1e29cad-1e46-4dc3-8e0b-b1ee842e5089.pdf', 'Avulsos Migrados/Enquanto, ó Salvador/coro.pdf', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8048c1bf-a8f7-4696-8d1b-90d8d5be72fd', 'Não Desanimes Deus Proverá', '335', 'Let.: Cecília Durffe Martin; Trad: Cecília Rodrigues Siqueira; Mus.: Walter Stillman Martin', 'Balada', 'A', 'Consolo e Encorajamento', 'NÃO DESANIMES! DEUS PROVERÁ,
DEUS VELARÁ POR TI;
SOB SUAS ASAS TE ACOLHERÁ,
DEUS VELARÁ POR TI.

CORO
DEUS CUIDARÁ DE TI, 
NA TUA DOR, COM TODO AMOR;
JAMAIS TE DEIXARÁ,
DEUS VELARÁ POR TI.

SE NO TEU PEITO VIBRAR ADOR,
DEUS VELARÁ POR TI;
TU JÁ PROVASTE SEU GRANDE AMOR,
DEUS VELARÁ POR TI.

NOS DESALENTOS, NAS PROVAÇÕES,
DEUS VELARÁ POR TI;
NAS DESVENTURAS, NAS TENTAÇÕES,
DEUS VELARÁ POR TI.

COMO ESTIVERES, NÃO TEMAS, VEM!
DEUS VELARÁ POR TI;
TEU PAI BONDOSO TE ESPERA ALÉM,
DEUS VELARÁ POR TI.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('8048c1bf-a8f7-4696-8d1b-90d8d5be72fd', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
