INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('80989ac0-c00a-47a4-a09e-c2099ebaa2bd', 'Oh Por que duvidar', '309', 'Let.: Erik Jason, F. da Silva; Mús. A. F. F.', 'Balada', 'D', 'Consolo e Encorajamento', 'OH! POR QUE DUVIDAR
SOBRE AS ONDAS DO MAR
QUANDO CRISTO O CAMINHO ABRIU?
QUANDO FORÇADO ÉS
CONTRA AS ONDAS LUTAR,
SEU AMOR A TI QUER REVELAR.

CORO
SOLTA O CABO DA NAU,
TOMA OS REMOS NAS MÃOS
E NAVEGA COM FÉ EM JESUS;
E ENTÃO TU VERÁS QUE BONANÇA SE FAZ,
POIS COM ELE SEGURO SERÁS.

TREVAS VEM TE ASSUSTAR,
TEMPESTADES NO MAR?
DA MONTANHA O MESTRE TE VÊ,
E NA TRIBULAÇÃO ELE VEM SOCORRER,
SUA MÃO BEM TE PODE SUSTER.

PODES TU RECORDAR,
MARAVILHAS SEM PAR?
NO DESERTO AO POVO FARTOU;
E O MESMO PODER
ELE SEMPRE TERÁ,
POIS NÃO MUDA E NÃO FALHARÁ.

QUANDO PEDES MAIS FÉ,
ELE OUVE, OH! CRÊ!
MESMO SENDO EM TRIBULAÇÃO;
QUANDO A MÃO DE PODER
O TEU EGO TIRAR
SOBRE AS ONDAS PODERÁS ANDAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('80989ac0-c00a-47a4-a09e-c2099ebaa2bd', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
