INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8246e73b-843b-47da-8a49-a7486c0a6699', 'Sei que sou amado do meu Salvador', '234', 'C.M.V.C.S.', 'Fox Abafado', 'D', 'Crianças e Adolescentes', 'SEI QUE SOU AMADO 
DO MEU SALVADOR,
SEI QUE ESTOU GUARDADO
PELO SEU AMOR.

DIA A DIA CAMINHANDO
ESTOU INDO A JERUSALÉM.
SEGUINDO O MEU JESUS EU SEI
QUE EM BREVE CHEGAREI.

CORO
SOU FELIZ COM MEU SENHOR,(2X)
DIA A DIA CAMINHANDO
ESTOU, INDO A JERUSALÉM,
SEGUINDO MEU JESUS,
EU SEI QUE EM BREVE CHEGAREI.

NAS MANSÕES CELESTIAIS IREI MORAR,
COM OS ANJOS DO SENHOR IREI CANTAR;
SEU AMOR JESUS MOSTROU POR MIM,
UM POBRE PECADOR, EM MEU LUGAR
MORREU NA CRUZ, AGORA SALVO ESTOU.
');
