INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('82925ded-867a-4d11-a3b1-904b77df7cf4', 'Há Vitória para mim', '012', 'Autor Desconhecido', 'Fox Abafado', 'E', 'Clamor', 'HÁ VITÓRIA PARA MIM,
HÁ VITÓRIA PARA MIM,
PELO SANGUE DO CORDEIRO,
HÁ VITÓRIA PARA MIM.

VENCER! VENCER! VENCER! VENCER!
PELO SANGUE DO CORDEIRO,
EU IREI VENCER.
');
