INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('82cd59bb-cdec-49c0-b149-533a6fe8ea19', 'És majestade o rei da gloria', '596', 'José Elias Simora', 'Balada', 'C', 'Louvor', 'ÉS MAJESTADE, Ó REI DA GLÓRIA,
ÉS O SENHOR, O REI DOS REIS;
TUA É SENHOR A MAGNIFICÊNCIA
E O PODER, E A HONRA, E A VITÓRIA.

CORO 2X
JESUS, JESUS ÉS O SENHOR,
O REI DOS REIS.

DIGNO ÉS DE ABRIR O LIVRO DA VIDA,
DIGNO É O CORDEIRO QUE FOI MORTO
DE RECEBER PODER E RIQUEZAS,
SABEDORIA, GLÓRIA E LOUVOR.
');
