INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('831d7851-60bf-489d-9ead-26a9a6ce79c3', 'O Amor de Deus é Grande', '284', 'Márcia Castro de Freitas', 'Balada', 'E', 'Grupo de Louvor', 'O AMOR DE DEUS É GRANDE,
MANDOU SEU FILHO À CRUZ
A MORRER POR MIM E POR TI
E TAMBÉM PARA VENCER,
VENCER A MORTE, VENCER A DOR;
ELE É JESUS, UNIGÊNITO FILHO,
REI, SENHOR, SALVADOR.

CORO
TE CHAMA PRA VIDA,
TE CHAMA PRA LUZ,
VENCEU A MORTE, ELE É JESUS,
QUER TE SALVAR, VIDA TE DAR,
VEM A JESUS.

UM ALTO PREÇO ELE PAGOU
SÓ POR AMOR AO PECADOR,
ALI NA CRUZ JESUS MORREU
E DEPOIS RESSUSCITOU,
VENCEU A MORTE, VENCEU A DOR;
ELE É JESUS, UNIGÊNITO FILHO,
REI, SENHOR, SALVADOR.

FINAL
TE CHAMA PRA VIDA,
(TE CHAMA PRA VIDA)
TE CHAMA PRA LUZ,
(TE CHAMA PRA LUZ)
VENCEU A MORTE, (ELE VENCEU)
ELE É JESUS, (ELE É JESUS)
QUER TE SALVAR, (QUER TE SALVAR)
VIDA TE DAR, 
VEM A JESUS. (2X)
');
