INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('83275797-d649-4426-97d6-c665fb117ff2', 'Há um Lindo País', '525', 'Jorgemar Souza Madeira', 'Básico', 'G', 'Volta de Jesus e Eternidade', 'HÁ UM LINDO PAÍS
ONDE OS ANJOS NÃO CESSAM
DE ENTOAR LOUVORES AO GRANDE REI.

*CORO
UM CORO CELESTIAL ÀQUELE QUE É DIGNO
DE ABRIR O LIVRO,
A JESUS, O LEÃO DA TRIBO DE JUDÁ.

NO MEU NOVO LAR
AS LÁGRIMAS JÁ NÃO CORREM
POIS O SENHOR
COM SEU AMOR ENXUGOU.

*CORO
UM CORO CELESTIAL ÀQUELE QUE É DIGNO
DE ABRIR O LIVRO,
