INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('83c2dcab-a5d6-49ca-8e21-736f682acc12', 'Âncora segura', '118', 'S.G.D.', 'Country', 'A', 'Crianças e Adolescentes', 'UMA ÂNCORA SEGURA 
TENHO NO SENHOR,
QUEM NELE CONFIOU
JAMAIS PERDIDO SE ACHOU.

EU CONFIO NO SENHOR,
SEGURO NELE ESTOU,
SEI DE FATOS GRANDIOSOS,
RESPOSTAS DO SENHOR;

ELIAS PEDIU A DEUS,
FOGO DO CÉU DESCEU,
CONSUMINDO O HOLOCAUSTO,
O POVO SE ALEGROU:
SÓ O SENHOR É DEUS! (2X)

PEDRO SUBIU AO TEMPLO,
VIU UM COXO A ESMOLAR.
MELHOR QUE PRATA E OURO
É O NOME DE JESUS.
GRAÇA SE DERRAMOU,
O COXO SE LEVANTOU.
O POVO SE ALEGROU: 
“SÓ O SENHOR É DEUS!”

PAULO VIU A TORMENTA DESTRUIR
A NAU SEM RUMO.
TODOS DESANIMADOS,
PAULO ANUNCIOU:
O ANJO DE DEUS FALOU:
NINGUÉM SE PERDERÁ.
TODOS CHEGARAM VIVOS,
SÓ O SENHOR É DEUS!
