INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('83cd0027-e7bd-4676-994d-bca62119c246', 'Há uma igreja que aguarda o Senhor', '193', 'M.M.F.', 'Fox Abafado', 'E', 'Crianças e Adolescentes', 'HÁ UMA IGREJA QUE AGUARDA O SENHOR,
POIS CONFIA NO SEU GRANDE AMOR
QUE JESUS POR NÓS DEMONSTROU:
POR NOSSA VIDA UM PREÇO PAGOU!

CORO
VEM, SENHOR, TUA IGREJA TE ESPERA, (2X)
AGUARDAMOS A TUA PROMESSA.
VEM, SENHOR, TUA IGREJA TE ESPERA.

QUANDO CRISTO NAS NUVENS VOLTAR
E AOS CÉUS SUA IGREJA LEVAR,
QUE ALEGRIA ENTÃO SENTIREMOS
POIS COM ELE PRA SEMPRE ESTAREMOS.
');
