INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('83f4905c-50e2-4862-b479-0b7e2713acad', 'Se Meu Povo Orar', '', '', '', '', '', 'SE MEU POVO QUE TEM MEU NOME
SE HUMILHAR E ORAR
SE MEU POVO SE ARREPENDER
DOS SEUS CAMINHOS MAUS.

*CORO
ENTÃO OS OUVIREI E OS PERDOAREI
SARAREI A TERRA E SUAS FERIDAS
EU ME LEVANTAREI PARA OS DEFENDER
DEFENDEREI O POVO QUE LEVA O MEU NOME.

SE BUSCARES A MINHA FACE
AO INVÉS DAS MINHAS MÃOS
SE ORARES UNS PELOS OUTROS
E NÃO POR COISAS VÃS.

*CORO
ENTÃO EU OS OUVIREI E OS PERDOAREI
SARAREI A TERRA E SUAS FERIDAS
EU ME LEVANTAREI PARA OS DEFENDER
DEFENDEREI O POVO QUE LEVA O MEU NOME.

ENTÃO ME LEMBRAREI DAS MINHAS PROMESSAS
OUVIREI AS PRECES E SARAREI A TERRA
OS ERGUEREI DE NOVO AINDA NESSE TEMPO
COMO UM SÓ POVO QUE PEDE POR RENOVO.

*CORO
ENTÃO EU OS OUVIREI E OS PERDOAREI
SARAREI A TERRA E SUAS FERIDAS
EU ME LEVANTAREI PARA OS DEFENDER
DEFENDEREI O POVO QUE LEVA O MEU NOME.

ENTÃO ME LEMBRAREI DAS MINHAS PROMESSAS
OUVIREI AS PRECES E SARAREI A TERRA
OS ERGUEREI DE NOVO AINDA NESSE TEMPO
COMO UM SÓ POVO QUE PEDE POR RENOVO.
/FINAL
EM NOME DE JESUS.
');
