INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('843b393d-2d26-46d3-9923-d58501898556', 'Eu não posso fugir do teu espírito_', '', '', '', '', '', '(M) EU NÃO POSSO FUGIR DO TEU ESPÍRITO,
(H) NEM FICAR DISTANTE DO TEU AMOR;
SE EU SUBIR ATÉ OS CÉUS,
SE AO ABISMO EU DESCER,
SEI QUE ALI TU ESTÁS.

*CORO
MESMO SE EU TOMAR
AS ASAS DA ALVORADA,
TUA MÃO AINDA ASSIM ME GUIARÁ,
MESMO VINDO A NOITE ESCURA
TUA LUZ BRILHARÁ,
E COMIGO ESTARÁS.

(M) EU NÃO POSSO FUGIR DO TEU ESPÍRITO,
(H) NEM FICAR DISTANTE DO TEU AMOR;
