INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('848d70bb-8667-4e55-b9b2-f1bc164529ac', 'Ja não estou sozinho', '132', 'Autor Desconhecido; Abedias (Jovens da Verdade)', 'Fox Abafado', 'E', 'Dedicação', 'JÁ NÃO ESTOU SOZINHO, AGORA SOU FELIZ,
COM CRISTO NO MEU CORAÇÃO;
ELE É MEU GRANDE AMIGO,
NÃO TEMO O PERIGO,
COM CRISTO NO MEU CORAÇÃO.

*CORO
OH! EU SOU FELIZ, AGORA VOU CANTAR,
POIS CONTENTE ESTOU COM MEU SALVADOR,
FELIZ AGORA ENTÃO EU VIVEREI.

JESUS, HÁ MUITO TEMPO MORREU EM UMA CRUZ,
MORREU SÓ PARA ME SALVAR;
SEU SANGUE DERRAMOU,
LAVANDO OS MEUS PECADOS,
E DESTA FORMA AGORA SALVO ESTOU.

*CORO
OH! EU SOU FELIZ, AGORA VOU CANTAR,
POIS CONTENTE ESTOU COM MEU SALVADOR,
