INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('84be7136-e7da-42d4-a03c-64cf7d6856ef', 'Não há Deus tão grande como tu', '741', 'Zc.4:6; Autor Desconhecido', 'Marcha', 'E', 'Corinhos', 'CANTAR 2X
NÃO HÁ DEUS TÃO GRANDE COMO TU,
NEM UM SÓ, NEM UM SÓ.
/CANTAR 2X
NÃO HÁ DEUS
QUE FAZ AS MESMAS OBRAS,
COMO AS QUE FAZES TU.

CANTAR 2X
JESUS DISSE: "SE TU CRERES,
TU VERÁS A GLÓRIA DE DEUS."
/FINAL 2X
VERÁS A GLÓRIA DE DEUS, (2X)
JESUS DISSE: "SE TU CRERES,
TU VERÁS A GLÓRIA DE DEUS."
');
