INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('84fa8089-7241-4e88-963d-2fb9bb6950b3', 'Que importa', '314', 'Autor Desconhecido', 'Balada', 'Dm', 'Consolo e Encorajamento', 'QUE IMPORTA SE O SOL NÃO BRILHAR?
QUE IMPORTA SE DAS ESTRELAS O BRILHO CESSAR?
O QUE IMPORTA, PARA MIM,
É DE JESUS NÃO ESQUECER;
ELE É A RAZÃO DE TODO O MEU VIVER.

É JESUS MINHA PAZ,
É JESUS MINHA FORÇA,
É JESUS MEU AMIGO,
É JESUS A MINHA ALEGRIA,
É JESUS MEU COMPANHEIRO,
É JESUS MEU AMOR VERDADEIRO,
ELE É A RAZÃO DE TODO O MEU VIVER.
');
