INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('85429a38-5faa-4b96-9a4e-dd32c7caa31a', 'Eu me Prostro em Teu Altar', '033', 'Gérson Beluci Miguel', 'Básico', 'C', 'Clamor', 'EU ME PROSTRO EM TEU ALTAR
NESTA HORA DE CLAMOR,
LEMBRO-ME DE TUA DOR
QUE SOFRESTE POR ME AMAR,
O TEU SANGUE TEM PODER
PARA ME PURIFICAR.

NESSE SANGUE HÁ COMUNHÃO,
CURA E LIBERTAÇÃO;
VISITA-ME COM TUA PAZ,

TEU ESPÍRITO RELUZ, VIVIFICA-ME, JESUS, 
E MINH''ALMA SATISFAZ.
TEU ESPÍRITO RELUZ, VIVIFICA-ME, JESUS, 
E MINH''ALMA SATISFAZ.
/FINAL
E MINH''ALMA SATISFAZ.
');
