INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8545cc80-7b28-4a33-8f28-ebe69a41bd74', 'Se não puderes mais', '303', 'Marciel Denadai', 'Novo', 'A', 'Consolo e Encorajamento', 'SE NÃO PUDERES MAIS
SENTIR O TOQUE DO SENHOR JESUS,
É PORQUE TU ALMA NÃO SE ABRIU,
TEU CORAÇÃO NÃO SENTIU
A PRESENÇA DO SENHOR JESUS.

*CORO
SE HOJE OUVIRDES A SUA VOZ
NÃO ENDUREÇAIS OS VOSSOS CORAÇÕES A JESUS.
/INSTRUMENTOS

QUANDO A LUTA SE TRAVAR,
DO CÉU DEUS OUVIRÁ
E ENVIARÁ UM ANJO PRA TE LIVRAR;
CONFIA SOMENTE NO SENHOR,
O MESMO DEUS DE ONTEM E HOJE
JAMAIS TE ABANDONARÁ.

*CORO 2X
SE HOJE OUVIRDES A SUA VOZ
NÃO ENDUREÇAIS OS VOSSOS CORAÇÕES A JESUS.
');
