INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('86050ff6-2bab-419e-92e0-95ec557c4513', 'Se eu falo do grande amor do Pai', '209', 'N.R.R.A.', 'Básico', 'A', 'Crianças e Adolescentes', 'SE EU FALO DO GRANDE AMOR DO PAI
GRANDES BÊNÇÃOS PODEREI CONTAR.
SE EU CANTO
AS MARAVILHAS QUE ELE FAZ,
O LOUVAREI ETERNAMENTE.

GRANDE É O AMOR DO PAI,
MARAVILHAS ELE FAZ
QUANDO A IGREJA CANTA
E ORA SEM CESSAR.
SANTO, JUSTO E FIEL,
SUA PROMESSA CUMPRIRÁ
BREVE VEM NOS BUSCAR!

CANTAR 2X
MARANATA, JESUS VEM!
MARANATA, JESUS VEM!
BREVE VEM NOS BUSCAR!
/BREVE VEM NOS BUSCAR!
BREVE VEM NOS BUSCAR!
');
