INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8633cc98-f9ae-4812-aa0e-74955facf8a4', 'O Caminho que nos Leva ao Céu é Jesus', '271', 'Olcimar Rubens de Carvalho', 'Básico', 'A', 'Morte, Ressureição e Salvação', 'O CAMINHO QUE NOS LEVA AO CÉU É JESUS,
O ÚNICO MEDIADOR ENTRE DEUS E OS HOMENS.

*CORO
FOI ELE QUEM SE DEU A MORRER NA CRUZ
ELE É O NOSSO SALVADOR
O SEU NOME É MARAVILHOSO,
CONSELHEIRO, NOBRE, PRÍNCIPE DA PAZ,
ELE ERA, É, SEMPRE SERÁ
O AUTOR DA NOSSA REDENÇÃO.

O AMIGO QUE NUNCA FALHA É JESUS,
AQUELE QUE NOS GARANTE A VIDA ETERNA.

*CORO
FOI ELE QUEM SE DEU A MORRER NA CRUZ
ELE É O NOSSO SALVADOR
O SEU NOME É MARAVILHOSO,
CONSELHEIRO, NOBRE, PRÍNCIPE DA PAZ,
ELE ERA, É, SEMPRE SERÁ
O AUTOR DA NOSSA REDENÇÃO.
/FINAL 2X
(O AUTOR DA NOSSA REDENÇÃO)
O AUTOR DA NOSSA REDENÇÃO.
');
