INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('86379ef1-2524-4875-972f-965cee638504', 'Do alto céu', '050', 'F.S.P.', 'Novo', 'A', 'Crianças e Adolescentes', 'DO ALTO CÉU ELE ME AMOU,
DO MUNDO MAU ME RETIROU;
FIZ A ESCOLHA DA SALVAÇÃO,
EU ACEITEI O CORDEIRO DE DEUS.

SEU SANGUE LAVOU O MEU CORAÇÃO,
DE TODO PECADO ME PERDOOU;
SEU SANTO ESPÍRITO ME ALCANÇOU,
E HOJE SOU SALVO PELA GRAÇA DE DEUS.
/FINAL
E HOJE SOU SALVO PELA GRAÇA DE DEUS.
');
