INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('863f106e-4b4f-4f43-ad13-e255ab6c43cb', 'Eu tenho um Deus mui, mui, mui grande', '740', 'Autor Desconhecido', 'Marcha', 'C', 'Corinhos', 'CANTAR 2X
EU TENHO UM DEUS
MUI, MUI, MUI GRANDE,
MARAVILHOSO ELE É,
SEMPRE AMOROSO, SEMPRE VITORIOSO,
MARAVILHOSO ELE É.

E QUANDO NAS LUTAS OU PROVAS,
SEMPRE CONOSCO ESTÁ,
NOS LEVANTA QUANDO CAÍMOS,
SUA MÃO NOS SUSTERÁ.

EU TENHO UM DEUS
MUI, MUI, MUI GRANDE,
MARAVILHOSO ELE É,
SEMPRE AMOROSO, SEMPRE VITORIOSO,
MARAVILHOSO ELE É.
MARAVILHOSO, MARAVILHOSO,
MARAVILHOSO ELE É.
');
