INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('86d1997e-f562-4f30-b1a0-dc9a30b53cf1', 'Jesus, Te Entronizamos', '600', 'Paul Kyle', 'Básico', 'G', 'Louvor', 'JESUS, TE ENTRONIZAMOS,
DECLARAMOS QUE ÉS REI,
TU ESTÁS NO MEIO DE NÓS,
