INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('86e598eb-a8a1-4cb0-8b42-f6efc0a8a3c9', 'Quando andava no mundo escravizado', '107', 'A.D.', 'Guarânia', 'A', 'Dedicação', 'QUANDO ANDAVA NO MUNDO ESCRAVIZADO,
EU VIVIA PRESO NO PECADO,
MAS UM HOMEM CERTO DIA ME COMPROU
E UM ALTO PREÇO PAGOU,
E HOJE LIBERTO ESTOU.

CORO
HOJE EU NÃO SOU MAIS ESCRAVIZADO,
UM HOMEM CHAMADO JESUS TEM ME LIBERTADO;
LIBERDADE JESUS TEM PROCLAMADO,
E VIDA NOVA TEM DADO,
SOU FELIZ COM JESUS AO MEU LADO.

ERA ESCRAVO E VIVIA SEMPRE CANSADO,
NA ANGÚSTIA E NA TRISTEZA SUBJUGADO,
LIBERDADE EU NÃO TINHA, CRISTO DEU,
NA CRUZ POR MIM JÁ MORREU E VIDA NOVA ME DEU.

FINAL
LIBERDADE JESUS TEM PROCLAMADO,
E VIDA NOVA TEM DADO,
SOU FELIZ COM JESUS AO MEU LADO.
');
