INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('87403fac-19aa-4baa-b271-702e55d41c09', 'Varões galileus', '187', 'R.D.B.', 'Balada', 'Dm', 'Crianças e Adolescentes', 'VARÕES GALILEUS
NÃO VOS MARAVILHEIS,
/CANTAR 2X
ESTE MESMO JESUS
QUE HOJE VISTES SUBIR
VOLTARÁ OUTRA VEZ.

VARÕES GALILEUS
NÃO VOS MARAVILHEIS,
/CANTAR 2X
ESTE MESMO JESUS
QUE HOJE VISTES SUBIR
VOLTARÁ OUTRA VEZ.

E VOS LEVARÁ (E VOS LEVARÁ)
PARA UM LAR DE PAZ (UM LAR DE PAZ),
A CIDADE DE LUZ ONDE A DOR CESSARÁ;
PRANTO NÃO TEREIS (PRANTO NÃO TEREIS),
QUAIS OS ANJOS SEREIS (ANJOS SEREIS).
/CANTAR 2X
ESTE MESMO JESUS QUE HOJE VISTES SUBIR
VOLTARÁ OUTRA VEZ.
');
