INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8764d7e5-2c95-47c5-926e-0d4ce8007891', 'Cheguemos ao altar de Deus', '572', 'Marciel Denadai', 'Básico', 'C', 'Louvor', 'CHEGUEMOS AO ALTAR DE DEUS
COM A NOSSA ADORAÇÃO;
NA SUA MÃO HÁ FORÇA E PODER.

*CORO 2X
ADOREMOS, ADOREMOS E CANTEMOS
AO AUTOR DA NOSSA SALVAÇÃO.
/INSTRUMENTOS

CHEGUEMOS AO ALTAR DE DEUS
COM A NOSSA ADORAÇÃO;
TUA É, SENHOR, A HONRA E A MAJESTADE,
PORQUE TEU É TUDO QUANTO HÁ
NOS CÉUS E NA TERRA;
TEU, SENHOR, É O REINO E TU TE EXALTASTE;
NA TUA MÃO HÁ FORÇA E PODER. (2X)

*CORO 2X
ADOREMOS, ADOREMOS E CANTEMOS
AO AUTOR DA NOSSA SALVAÇÃO.
/INSTRUMENTOS
/FINAL
E CANTEMOS AO AUTOR DA NOSSA SALVAÇÃO.
');
