INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8767965b-8ac6-48bc-ba3e-2a069102a378', 'Jesus, Tu és o meu Deus (Solo)', '039', 'Let: Sérgio Carlos de Souza; Mús. Emanoel Aleixo Júnior', 'Básico', 'Dm', 'Clamor', 'JESUS, TU ÉS O MEU DEUS,
A MINH''ALMA TEM SEDE DE TI, 
EU TE DESEJO, Ó DEUS,
NECESSITADO ESTOU.

NO TEU SANGUE HÁ RENOVO,
PODER PARA TRANSFORMAR,
PARA LIBERTAR E PERDOAR,
DERRAMA DESTE SANGUE EM MIM.

CANTAR 2X
E ASSIM TE BENDIREI
ENQUANTO EU VIVER,
EM TEU NOME FALAREI,
OS MEUS LÁBIOS TE LOUVARÃO.
/FINAL
ALELUIA, AMÉM. (2X)
');
