INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8771907f-291e-476e-b517-e85882dfd8c5', 'Toca pela fé', '067', 'Luciana Monteiro Carneiro Simora', 'Básico', 'G', 'Invocação e Comunhão', 'TOCA PELA FÉ NO VESTIDO DE JESUS
E DELE VAI SAIR VIRTUDE,
PEDE SEM TEMER, ELE VAI TE OUVIR.
TOCA PELA FÉ EM JESUS.

*CORO 2X
POIS TODO O QUE PEDE, RECEBE,
E O QUE BUSCA, ENCONTRA O SENHOR.
/INSTRUMENTOS

PODE O PAI NEGAR AO FILHO SEU
E DAR PEDRA AO INVÉS DE PÃO?
QUANTO MAIS O PAI QUE ESTÁ NO CÉU,
TUDO QUE PEDIRES TE DARÁ.

*CORO 2X
POIS TODO O QUE PEDE, RECEBE,
E O QUE BUSCA, ENCONTRA O SENHOR.
/FINAL
PEDE SEM TEMER,
ELE VAI TE OUVIR,
TOCA PELA FÉ EM JESUS.
');
