INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('87d17376-6089-4df6-8fa5-aac374f35ac8', 'Cantarei, cantarei as misericórdias', '780', 'Geraldo Gomes Pinheiro', 'Fox Abafado', 'A', 'Dedicação', 'CANTAREI, CANTAREI 
AS MISERICÓRDIAS DO SENHOR,
CANTAREI, CANTAREI 
AS MISERICÓRDIAS DO SENHOR;

REVELADAS EM JESUS,
CUJA MORTE LÁ NA CRUZ
NOS TIROU DA PERDIÇÃO
COM ETERNA SALVAÇÃO;
CANTAREI, CANTAREI 
AS MISERICÓRDIAS DO SENHOR.
');
