INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('87ee8bc9-38ce-4247-964d-d1f5713248bf', 'És um remido De Deus', '', '', '', 'E', 'Avulso', 'ÉS UM REMIDO DE DEUS,
TU ÉS UM DOS MEUS
ÉS AQUELE A QUEM ESCOLHI
UM DIA OUVI MINHA VOZ
A VOZ DO FILHO DE DEUS
A CHAMAR: "VEM AQUI ME SERVIR"

SENHOR NADA TENHO PRA TE OFERECER
SABES O EU SOU, SABES QUEM SOU EU
O TEU QUERER EM MIM SERÁ
O MEU PRAZER TEUS MISTÉRIOS CONHECER
TUA OBRA REALIZAR
MINHA VIDA ENTREGAR

CANTAR 2X
AS LUTAS VÊM,
MAS VITÓRIAS TAMBÉM VEM
E O TEU AMOR É MAIS FORTE
E SEM ELE NÃO ESTARIA AQUI
COM TEU PODER, TUA GRAÇA TUA LUZ
SOU UM VENCEDOR, SOU UM SERVO,
SOU UM VASO,
A SERVIÇO DO SENHOR.
/FINAL
A SERVIÇO DO SENHOR.
');
