INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('882c845a-35a8-4942-bd5e-b87e3532a649', 'Deixa a glória de Deus brilhar', '750', 'D.R.', 'Marcha', 'E', 'Corinhos', 'DEIXA A GLÓRIA DE DEUS BRILHAR, (5X)
/DEIXA A GLÓRIA EM SEU ROSTO BRILHAR.
DEIXA A GLÓRIA DE DEUS BRILHAR
EM SEU ROSTO, 
DEIXA A GLÓRIA DE DEUS BRILHAR.

FOI LÁ NO CUME DO MONTE
QUE O NOSSO DEUS COM MOISÉS FALAVA;
QUANDO ELE DESCEU DO MONTE
NÃO SABIA QUE SEU ROSTO BRILHAVA,
BRILHAVA, BRILHAVA, O SEU ROSTO BRILHAVA;

FINAL 2X
FOI LÁ NO CUME DO MONTE SINAI
QUE O NOSSO DEUS COM MOISÉS FALAVA.
');
