INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('88427073-a569-4944-958f-68be99c2e950', 'Venho clamar', '100', '', '', '', '', 'VENHO CLAMAR A TI, Ó PAI,
PELO SANGUE DE JESUS.
SOU PECADOR, NECESSITADO,
MAS CONFIO NO MEU DEUS.

MEU REDENTOR, JESUS AMADO,
EM TUA PRESENÇA ESTÁ MEU SER,
A TUA GLÓRIA REVELADA
EU QUERO SENTIR, SENHOR.

(2X)
MEU CORAÇÃO SE REFUGIA EM TI.
NESTE SANGUE,
VIDA ETERNA EU JÁ POSSO TER
E NA ALEGRIA DA TUA SALVAÇÃO
EU HEI, SENHOR, DE PERMANECER.
/FINAL
EU HEI, SENHOR, DE PERMANECER.
');
