INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('88be5911-fb17-4623-b4d7-ac844928e377', 'Estou a caminhar', '127', 'Silas Cezar', 'Básico 2', 'E', 'Dedicação', 'ESTOU A CAMINHAR
PARA O MEU LAR NO CÉU;
SOU PEREGRINO AQUI,
O VIVER ETERNO É MEU.
DE GRAÇA RECEBI DE DEUS A SALVAÇÃO,
BENDITO O SANGUE QUE ME LAVOU,
CREIO EM MEU CORAÇÃO.
');
