INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('88fffbea-62d2-4ab6-8c61-555f7c51be17', 'A noiva amada do Cordeiro', '191', 'E.H.M.R.', 'Fox', 'G', 'Crianças e Adolescentes', 'A NOIVA AMADA DO CORDEIRO
ESTÁ SENDO PREPARADA
PARA O ENCONTRO COM SEU NOIVO
NA LINDA FESTA NO CÉU.

*CORO
DIANTE DO TRONO DO CORDEIRO
EXPRESSARÁ TODO AMOR;
ALELUIA! HONRA E GLÓRIA
AO NOSSO SALVADOR!

SEGUE O CORDEIRO
PARA ONDE ELE VAI,
LÁ ESTÁ ELA, TÃO FORMOSA!
PREPARADA JÁ ESTÁ.

*CORO
DIANTE DO TRONO DO CORDEIRO
EXPRESSARÁ TODO AMOR;
ALELUIA! HONRA E GLÓRIA
AO NOSSO SALVADOR!

CANTARÁ UM CANTO NOVO
E SÓ ELA SABERÁ
POIS SOMENTE OS REMIDOS
ESTE CANTO ENTOARÃO.

*CORO
DIANTE DO TRONO DO CORDEIRO
EXPRESSARÁ TODO AMOR;
ALELUIA! HONRA E GLÓRIA
AO NOSSO SALVADOR!
/FINAL
AO NOSSO SALVADOR!
');
