INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('89594a06-5160-40da-87cd-db65dd4ca8c9', 'Estamos aqui, ó Deus', '620', 'Autor Desconhecido', 'Básico', 'G', 'Louvor', 'ESTAMOS AQUI, Ó DEUS,
PRA LOUVAR O TEU NOME,
POIS TU NOS TORNASTE SERVOS TEUS.
LOUVEMOS A DEUS!

A CAMINHO ESTAMOS DA NOVA JERUSALÉM,
CIDADE ETERNAL QUE O PAI NOS PREPAROU.
MARANATA! ORA VEM, SENHOR JESUS,
VEM NOS BUSCAR.
/INSTRUMENTOS

ESTAMOS AQUI, Ó DEUS, 
PRA LOUVAR O TEU NOME,
POIS TU NOS TORNASTE SERVOS TEUS.
LOUVEMOS A DEUS!

A CAMINHO ESTAMOS DA NOVA JERUSALÉM,
CIDADE ETERNAL QUE O PAI NOS PREPAROU.
MARANATA! ORA VEM, SENHOR JESUS,
VEM NOS BUSCAR.

FINAL 2X
MARANATA! LOUVEMOS A DEUS,
LOUVEMOS A DEUS, LOUVEMOS A DEUS.
/MARANATA!
');
