INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('89d51e1d-d80f-4177-8765-001c56405a86', 'Minha vida e meu coração', '042', 'C.M.V.C.S.', 'Fox', 'E', 'Crianças e Adolescentes', 'MINHA VIDA E MEU CORAÇÃO PERTENCEM A JESUS,
DIA A DIA EM MEU VIVER VOU ANDAR EM SUA LUZ.
À PALAVRA VOU OBEDECER,
COM AMOR TESTEMUNHAR.

E PRA SEMPRE, SEMPRE O LOUVAREI,
NA ETERNIDADE EU VOU MORAR.
E PRA SEMPRE, SEMPRE O LOUVAREI,
NA ETERNIDADE EU VOU MORAR.
');
