INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8a035c3a-6fe2-4277-baa4-79a1132d4c5d', 'Da linda pátria', '555', 'Let.: Justus Henry Nelson; Mús.: Stephen Collins Foster', 'Básico', 'C', 'Volta de Jesus e Eternidade', 'DA LINDA PÁTRIA ESTOU MUI LONGE, 
TRISTE EU ESTOU;
EU TENHO DE JESUS SAUDADE;
QUANDO SERÁ QUE VOU? 
PASSARINHOS, BELAS FLORES, 
QUEREM ME ENCANTAR,
OH! VÃOS TERRESTRES ESPLENDORES, 
NÃO QUERO AQUI FICAR!

JESUS ME DEU FIEL PROMESSA, 
VEM ME BUSCAR;
MEU CORAÇÃO ESTÁ COM PRESSA, 
EU QUERO AO CÉU VOAR.
MEUS PECADOS SÃO MUI GRANDES 
E CULPADO SOU;
MAS O SEU SANGUE PÕE-ME LIMPO 
E PARA A PÁTRIA VOU.

QUAL FILHO DO SEU LAR SAUDOSO, 
EU QUERO IR;
QUAL PASSARINHO PARA O NINHO, 
EU QUERO AO CÉU SUBIR.
SUA VINDA AO MUNDO É CERTA, 
QUANDO NÃO O SEI,
MAS ELE ME ACHARÁ ALERTA 
E PARA O CÉU IREI.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('8a035c3a-6fe2-4277-baa4-79a1132d4c5d', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
