INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8a1de6d8-9fa4-46b9-848f-bc60e22f017f', 'Há um rio de águas vivas', '443', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Santificação e Derramamento', 'HÁ UM RIO DE ÁGUAS VIVAS
QUE PROCEDEM DO TRONO DO SENHOR,
ONDE PASSAM NASCE A VIDA,
DOS DESERTOS FAZEM JARDINS DE AMOR.

CORO
OH! EU QUERO ESTAR ONDE CORREM
ESSAS ÁGUAS DE PROFUNDA PAZ.

ESSE RIO É O ESPÍRITO
DERRAMADO SOBRE TODO O QUE CRÊ;
ELE PASSA HOJE POR AQUI
E TE QUER ENCHER DE GOZO E PODER.

SE QUERES JUBILAR POR TUA SALVAÇÃO,
ENTRA NESSE RIO E VEM SEM TEMOR;
DEIXA SUBMERGIR TODO O TEU SER
NAS PROFUNDAS ÁGUAS DO SEU AMOR.
');
