INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8a98d873-2b69-4e98-ae8d-12b3be7d5428', 'A Beleza da tua Santidade', '622', 'Gérson Beluci Miguel', 'Básico', 'C', 'Louvor', 'A BELEZA DA TUA SANTIDADE É MAIOR
