INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8a9b88e0-deba-4973-9631-97fa0278e28c', 'O Senhor é o Meu Pastor', '358', 'Vicente de Paula Barcellos Duarte', 'Country', 'Dm', 'Consolo e Encorajamento', 'CANTAR 2X
O SENHOR É MEU PASTOR,
NADA ME FALTARÁ,
PELOS PASTOS VERDEJANTES
ELE ME CONDUZIRÁ.

REFRIGERA A MINHA ALMA
COM SUA PAZ E SEU AMOR,
SEU CAJADO ME CONSOLA,
ELE É O MEU PASTOR.

QUANDO NO VALE DA MORTE
MAL ALGUM EU TEMEREI,
/FINAL 2X
O SENHOR É MEU PASTOR,
EM SUA CASA HABITAREI.
');
