INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8afa80bf-e7d0-47b1-8889-ee4d54cd08d9', 'Em breve estaremos na glória', '195', 'E.H.M.R.', 'Marcha', 'Dm', 'Crianças e Adolescentes', 'EM BREVE ESTAREMOS NA GLÓRIA,
A CANTAR: ALELUIA AO CORDEIRO,
AGUARDAMOS DIA E NOITE OUVIR O TOQUE
DA TROMBETA DE DEUS ECOAR.

VAMOS TER UMA GRANDE REUNIÃO
NO CÉU COM O SALVADOR.
O MOMENTO SE APROXIMA
E A NOIVA SE APRONTA,
AGUARDA O CHAMADO DO SENHOR.

CANTAR 2X
FELIZES SERVOS CHAMADOS
PARA A GRANDE FESTA            
QUE ACONTECERÁ BREVEMENTE:
SERÃO AS BODAS DO CORDEIRO.
/FINAL
SERÃO AS BODAS DO CORDEIRO.
');
