INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8b1dc3b1-95d6-45e9-8259-e2e5b374a8cd', 'Ó Vem Logo, Jesus', '', '', '', '', '', 'Ó CORAÇÃO NÃO SE TURBE,
CREDES SEMPRE EM DEUS, CREDE EM MIM;
HÁ MANSÕES NA CASA DE MEU PAI
E VOU PREPARAR-VOS UM LUGAR.

CORO
JESUS VEM LOGO, ESTAIS VÓS PRONTOS?
JESUS VEM LOGO, ESTAIS VÓS PRONTOS?
SE HOJE A NOITE VIER, COMO O ENCONTRAREIS?
JESUS VEM LOGO, ESTAIS VÓS PRONTOS?

POR QUE AINDA ESPERAS?
SÃO FIÉIS PROMESSAS DE DEUS.
SE JESUS COMPROU-TE NO CALVÁRIO,
BUSCAR LOGO VEM OS FILHOS TEUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('8b1dc3b1-95d6-45e9-8259-e2e5b374a8cd', '45ab58b2-d293-45c7-aa75-090fcd968b24');
