INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8b6df0d4-e9d7-4fb9-b8ff-25df5b347d24', 'Eu sou tão feliz', '170', 'José Elias Simora', 'Básico', 'E', 'Dedicação', 'EU SOU TÃO FELIZ COM O MEU JESUS,
ELE MORREU NUMA CRUZ
PRA SALVAR O PECADOR;
ELE É O CAMINHO, A VERDADE E A VIDA,
ELE É JESUS, O SENHOR,
NOSSO ETERNO REDENTOR!

*CORO 2X
NOVA CRIATURA SOU, PELO SANGUE DE JESUS,
REDIMIDO PARA HERDAR A VIDA ETERNA!

EU SOU TÃO FELIZ 
COM O MEU JESUS,
ELE MORREU NUMA CRUZ
PRA SALVAR O PECADOR.

*CORO 2X
NOVA CRIATURA SOU, PELO SANGUE DE JESUS,
REDIMIDO PARA HERDAR A VIDA ETERNA!
/FINAL
REDIMIDO PARA HERDAR A VIDA ETERNA.
');
