INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8bb2d131-426f-4d46-a4ce-d1cae8a8f580', 'Sou servo do Senhor', '044', 'C.M.V.C.S.', 'Balada', 'A', 'Crianças e Adolescentes', 'SOU SERVO DO SENHOR,
SERVI-LO É O MEU PRAZER,
POIS SALVO EM SUA GRAÇA,
POR SEU FILHO JESUS,
TORNOU-ME LIVRE.
EM JESUS POSSO IR DIRETO AO PAI,
COM OUSADIA ENTRAR
NO SANTO DOS SANTOS.

COMO REI E SACERDOTE
O SENHOR ME COLOCOU.
POSSO GOVERNAR, POSSO MINISTRAR,
AO SENHOR SEMPRE ADORAR,
EM ESPÍRITO E VERDADE
HOJE E ETERNAMENTE.

SOU SERVO DO SENHOR,
SERVI-LO É O MEU PRAZER,
POIS SALVO EM SUA GRAÇA,
POR SEU FILHO JESUS,
TORNOU-ME LIVRE.
EM JESUS POSSO IR DIRETO AO PAI,
COM OUSADIA ENTRAR
NO SANTO DOS SANTOS.

COMO REI E SACERDOTE
O SENHOR ME COLOCOU.
POSSO GOVERNAR, POSSO MINISTRAR,
AO SENHOR SEMPRE ADORAR,
EM ESPÍRITO E VERDADE
HOJE E ETERNAMENTE.
/FINAL
HOJE E ETERNAMENTE.
');
