INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8c548ca1-ec2f-4691-95d0-1b7c7f6be782', 'Pai de amor', '581', 'Autor Desconhecido', 'Valseado', 'G', 'Louvor', 'PAI DE AMOR, GOSTO TANTO DE TI! (2X)
TE AMO, TE QUERO E PROSTRADO TE ADORO!
PAI DE AMOR, GOSTO TANTO DE TI!

MEU JESUS, AMOROSO TU ÉS! (2X)
MINH''ALMA LIMPASTE
E O ESPÍRITO ENVIASTE!
MEU JESUS, AMOROSO TU ÉS!

SANTO ESPÍRITO CONSOLADOR! (2X)
TU NOS SANTIFICAS
E EM NÓS SEMPRE HABITAS!
SANTO ESPÍRITO CONSOLADOR!
