INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8c8d3a0f-6faf-4068-8e73-52153f126705', 'Jesus fez a promessa', '149', 'Enoch Alves de Melo', 'Balada', 'G', 'Dedicação', 'JESUS FEZ A PROMESSA,
CONOSCO ESTARIA ATÉ O FIM;
E OS SINAIS SEGUIRIAM A TODOS 
QUE CRESSEM, ELE FALOU ASSIM.
CAIAM OS MONTES E OS HOMENS,
MAS SUA PROMESSA ESTÁ DE PÉ,
ELE NOS TEM PROVADO QUE NÃO MUDOU,
PODEROSO ELE É!

*CORO
PODEROSO ELE É
E EM NADA MUDOU.
NELE ESTÁ NOSSA FÉ,
PODEROSO ELE É!

ELE DEU VISTA AOS CEGOS
E OS OPRIMIDOS ELE LIBERTOU;
CINCO PÃES E DOIS PEIXES
A MAIS DE DOIS MIL ELE ALIMENTOU.
OPEROU NA JUDEIA, EM CAFARNAUM E EM NAZARÉ;
CONTINUA OPERANDO AQUI EM NOSSO MEIO,
PODEROSO ELE É!

*CORO 2X
PODEROSO ELE É
E EM NADA MUDOU.
NELE ESTÁ NOSSA FÉ,
PODEROSO ELE É!
');
