INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8ce7090a-5a21-422a-bbaa-5779f8f78e98', 'Como Um Bom Pastor', '259', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'G', 'Morte, Ressureição e Salvação', 'COMO UM BOM PASTOR
PROCURA UMA OVELHA PERDIDA,
JESUS ME BUSCOU E DEU LUZ À MINHA VIDA;
COM TANTO AMOR FALOU AO MEU CORAÇÃO,

CANTAR 2X
LIVROU-ME DO MAL, 
CUROU MINHAS CHAGAS,
DEU-ME SALVAÇÃO!

EM SEUS FORTES BRAÇOS
DESCANSO E REFÚGIO ACHEI,
ELE É MEU PASTOR 
E CUIDA DE MIM, EU SEI!
COMO UMA OVELHA, 
NO PASTO SEU, CAMINHO;

CANTAR 2X
SEGUINDO A JESUS, 
OUVINDO SUA VOZ,
SENTINDO SEU AMOR!

AMIGO, POR QUE, SEM RUMO,
VIVER NESTE MUNDO?
POR QUE TANTA DOR,
SE EXISTE ESSE AMOR PROFUNDO?
Ó, VEM A JESUS,
TU ÉS UMA OVELHA PERDIDA;

FINAL 2X
SÓ CRISTO TE PODE DAR SALVAÇÃO,
ENTREGA-LHE TUA VIDA!
');
