INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8d2545f3-ca75-4989-9868-cabcbc5b50e4', 'Sê Exaltado, ó Deus', '631', 'Fábio Henrique Barros Ramos', 'Básico', 'G', 'Louvor', '*CORO
SÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,
SEJA TUA GLÓRIA SOBRE TODA A TERRA.

GRANDE E MAJESTOSO,
TODA A TERRA E O MAR PERTENCEM SÓ A TI;
JUSTO, TÃO PODEROSO,
MESMO DIANTE DE TUA GLÓRIA POSSO DIZER
QUE TU VIVES EM MIM.

*CORO
SÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,
SEJA TUA GLÓRIA SOBRE TODA A TERRA.
/INSTRUMENTOS

TU ÉS PERFEITO, SANTO E SOBERANO DEUS,
DE TODA A TERRA TU ÉS REI;
ETERNO E TRIUNO, SUPREMO CRIADOR,
A TI PRA SEMPRE CANTAREI;
LOUVAR-TE-EI, SENHOR, ENTRE OS POVOS,
CANTAR-TE-EI LOUVORES ENTRE AS NAÇÕES.

*CORO
SÊ EXALTADO, Ó DEUS, SOBRE OS CÉUS,
SEJA TUA GLÓRIA SOBRE TODA A TERRA.
');
