INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8d395df5-094c-4a30-8d45-12f6150fce57', 'Com Jesus vencedor serei', '125', 'S.D.A.', 'Fox', 'E', 'Crianças e Adolescentes', 'COM JESUS VENCEDOR SEREI! (2X)
VENCEDOR, VENCEDOR, VENCEDOR SEREI!
COM JESUS VENCEDOR SEREI!

NAS BATALHAS ELE ME ACOMPANHA. (2X)
MEU JESUS, MEU JESUS,
SEMPRE ME ACOMPANHA.
COM JESUS VENCEDOR SEREI!

ELE É O MEU SALVADOR. (2X)
SALVADOR, SALVADOR É O MEU JESUS!
COM JESUS VENCEDOR SEREI!
');
