INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8d577ae1-dcac-4ff0-8854-4b680ed208a1', 'Jesus, Senhor, me Chego a Ti', '185', 'Let.: Eliza H. Hamilton; Adap. Sarah P. Kalley; Adapt. atual: Jurama Barros Gueiros; Mús.: Ira David Sankey', 'Balada', 'D', 'Dedicação', 'JESUS, SENHOR, ME CHEGO A TI,
PERDÃO SUPLICO AGORA A TI,
OH! DÁ-ME ALÍVIO MESMO AQUI,
ACEITA UM PECADOR!

CORO
EU VENHO COMO ESTOU; (2X)
PORQUE JESUS POR MIM MORREU;
EU VENHO COMO ESTOU.

EU NADA POSSO MERECER,
TU VÊS-ME PRESTES A MORRER,
OH! NÃO ME DEIXES PERECER,
ACEITA UM PECADOR!

OH! SEM DEMORA, SALVADOR,
SOCORRE-ME POR TEU AMOR,
POIS TU, Ó CRISTO, ÉS MEU SENHOR,
ACEITA UM PECADOR!

NADA DE BOM SE ACHA EM MIM,
DE MEUS ESFORÇOS BREVE HÁ FIM;
SE NÃO ME ACEITAS, AI DE MIM,
ACEITA UM PECADOR!
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('8d577ae1-dcac-4ff0-8854-4b680ed208a1', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
