INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8d776fe2-309e-4f06-968d-d3e1fb971f37', 'Pelo Sangue de Jesus', 8, 'Sérgio Paulo Ferreira de Matos', 'Balada', 'G', 'Clamor', 'PELO SANGUE DE JESUS
CLAMO A TI, MEU SENHOR;
NELE HÁ PERDÃO, PAZ, COMUNHÃO,
VIDA PARA O MEU SER!

NOS TEUS ÁTRIOS QUERO ENTRAR
COBERTO POR ESTE SANGUE,
PARA TUA GLÓRIA VER
E TE ADORAR!

PELO SANGUE DE JESUS
CLAMO A TI, MEU SENHOR;
NELE HÁ PERDÃO, PAZ, COMUNHÃO,
VIDA PARA O MEU SER!

NOS TEUS ÁTRIOS QUERO ENTRAR
COBERTO POR ESTE SANGUE,
PARA TUA GLÓRIA VER
E TE ADORAR!
/FINAL
PARA TUA GLÓRIA VER
E TE ADORAR!
');
