INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8dc296fa-c3fe-4058-b35d-403c76f67d89', 'Aleluia ao Cordeiro (Pai, reunidos estamos)', '', '', '', '', '', 'PAI, REUNIDOS ESTAMOS
PRA TE ADORAR,
LOUVANDO EM UMA SÓ VOZ,
TEUS FILHOS SOMOS,
REMIDOS POR TI,
DA MORTE SALVOS, ENFIM.

NÃO HÁ PALAVRAS PARA
AGRADECER-TE,
NEM EXPRESSAR TÃO
IMENSO AMOR,
MAS ERGUEREI MINHA VOZ
EM UM SÓ LOUVOR,
COM TODO O MEU SER.

*CORO
ALELUIA, ALELUIA,
ALELUIA AO CORDEIRO,
ALELUIA, ALELUIA
PELO SANGUE QUE VERTEU;
TODA TERRA, TODA TRIBO,
TODA LÍNGUA, TODO CÉU,
DANDO GLÓRIA, DANDO HONRA
E LOUVANDO AO NOSSO SALVADOR.

PAI, POR TEU INFINDO
E IMENSO AMOR,
NOS DESTE A SALVAÇÃO,
TEUS FILHOS SOMOS
SALVOS POR TI,
PROSTRADOS EM ORAÇÃO.

VEM DERRAMAR TEU SANTO
E DOCE AMOR EM NÓS
PRA SERMOS LUZ NESTE MUNDO AQUI,
NAÇÕES E POVOS VERÃO
TUA GLÓRIA REINAR E TE ADORARÃO.

*CORO
ALELUIA, ALELUIA,
ALELUIA AO CORDEIRO,
ALELUIA, ALELUIA
PELO SANGUE QUE VERTEU;
TODA TERRA, TODA TRIBO,
TODA LÍNGUA, TODO CÉU,
DANDO GLÓRIA, DANDO HONRA
E LOUVANDO AO NOSSO SALVADOR.

CHEIOS DE GRATIDÃO,
TODOS PROCLAMEM QUE
TU ÉS SENHOR E REI.

*CORO
ALELUIA, ALELUIA,
ALELUIA AO CORDEIRO,
ALELUIA, ALELUIA
PELO SANGUE QUE VERTEU;
TODA TERRA, TODA TRIBO,
TODA LÍNGUA, TODO CÉU,
DANDO GLÓRIA, DANDO HONRA
E LOUVANDO AO NOSSO REI.

*CORO
ALELUIA, ALELUIA,
ALELUIA AO CORDEIRO,
ALELUIA, ALELUIA
PELO SANGUE QUE VERTEU;
TODA TERRA, TODA TRIBO,
TODA LÍNGUA, TODO CÉU,
DANDO GLÓRIA, DANDO HONRA
E LOUVANDO AO NOSSO SALVADOR.

FINAL
E LOUVANDO AO NOSSO SALVADOR.
E LOUVANDO AO NOSSO SALVADOR.
NOSSO DEUS REINARÁ.
');
