INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8e256459-22ab-4144-9a52-a40a1228d856', 'Ouve pois, Israel', '671', 'Adelinda Simões Lopes', 'Básico', 'C', 'Grupo de Louvor', 'OUVE, POIS, ISRAEL!
O SENHOR É O TEU DEUS,
ELE É O ÚNICO SENHOR,
"AMARÁS O SENHOR TEU DEUS
DE TODA A TUA ALMA,"
ESTAS PALAVRAS TE ORDENO.

ATA-AS EM TEU CORAÇÃO,
AOS TEUS FILHOS FALARÁS
E SERÁ POR SINAL NAS TUAS MÃOS
E NOS UMBRAIS DE TUA CASA.

E ASSIM VOSSAS CASAS
ESTARÃO CHEIAS DE TODO BEM,
DOS POÇOS TIRAREIS ÁGUAS DE SALVAÇÃO.

CANTAR 2X
COMEREIS E VOS FARTAREIS DAS VINHAS,
COMEREIS E VOS FARTAREIS.
/INSTRUMENTOS

GUARDA AS MINHAS PALAVRAS,
NÃO ESQUEÇAS DO SENHOR, TEU DEUS
QUE TE TIROU DA SERVIDÃO
E HOJE LIVRE ESTÁS,
AO TEU DEUS TEMERÁS
E SÓ A ELE SERVIRÁS,
/POIS EM BREVE VIRÁ. (4X)
');
