INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8e428db9-80f3-4dec-98cf-fb0c655247ef', 'Se Um Dia Deus Prometeu', '373', 'Mike Michaele Kunert Deps', 'Básico', 'C', 'Grupo de Louvor', 'SE UM DIA DEUS PROMETEU
A VITÓRIA TE CONCEDER,
SE IMPOSSÍVEL PARECE SER
TUA BÊNÇÃO ACONTECER,
SABE QUE O QUE ELE PROMETEU
É PODEROSO PRA CUMPRIR,
O TEMPO DE DEUS VAI CHEGAR,
ELE NÃO FALHARÁ.

*CORO
SOMENTE CRER (SOMENTE CRER)
E DESCANSAR (E DESCANSAR),
CONFIA EM DEUS E TUDO MAIS
(E TUDO MAIS)
ELE FARÁ, NÃO TARDARÁ.

SE NÃO PODES IMAGINAR
COMO DEUS PODE OPERAR,
DEIXA DIANTE DO ALTAR
PRA QUE DEUS POSSA TE PROVAR
QUE NÃO HÁ NADA IMPOSSÍVEL
QUE DEUS NÃO POSSA RESOLVER,
O SEU ANJO ENVIARÁ E A VITÓRIA ELE TRARÁ.

*CORO
SOMENTE CRER (SOMENTE CRER)
E DESCANSAR (E DESCANSAR),
CONFIA EM DEUS E TUDO MAIS
(E TUDO MAIS)
ELE FARÁ, NÃO TARDARÁ.
/FINAL
ELE FARÁ.
');
