INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8f299167-f72e-40a2-8d34-582a7b553759', 'Expirou', '014', '', '', '', '', 'EXPIROU! NÃO MAIS PADECE
DE DEUS PAI O FILHO AMADO,
MAS O SOLO SE ESTREMECE
COM SEU SANGUE DERRAMADO.

FOI ENTÃO QUE A DEUS BENDITO
IMPLOROU O SALVADOR.
EIS O AMOR VASTO, INFINITO,
PELO POVO TRANSGRESSOR.
ENTREGOU A SUA VIDA!
GRANDE PROVA DE AMOR!
MESMO ALI CRUCIFICADO
AMA A QUEM O CONDENOU!

AOS SEUS PÉS EU VOU, ENQUANTO
SOFRE ASSIM O CRISTO AMADO,
PARA AO MENOS DAR-LHE O PRANTO,
POIS POR MIM DEU O SEU SANGUE.
PARA AO MENOS DAR-LHE O PRANTO,
POIS POR MIM DEU O SEU SANGUE.
');
