INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8fb606ea-d8f7-40fe-bb74-ace70e53f45a', 'Entrega', '', '', '', '', '', 'PRECISO ME ENTREGAR SENHOR
PRECISO A TI ME ENTREGAR
PRECISO OUVIR TUA VOZ A ME FALAR
NÃO TENHO NADA A TE OFERECER
SOMENTE UM CORAÇÃO IMPURO
E PECADOR MAS AQUI ESTOU
ME ACEITA SENHOR.

CORO
TOMA OS MEUS PENSAMENTOS,
MEUS DONS E MEUS BENS
TOMA O MEU CORAÇÃO
E TUDO QUE ELE TEM
RENOVA, SENHOR, MEU VIVER
DERRAMA EM MIM TEU AMOR
QUERO PRA SEMPRE SERVIR-TE
POR ONDE FOR.

PRECISO ME ENTREGAR SENHOR
PRECISO A TI ME ENTREGAR
PRECISO OUVIR TUA VOZ A ME FALAR
NÃO TENHO NADA A TE OFERECER
SOMENTE UM CORAÇÃO IMPURO
E PECADOR MAS AQUI ESTOU
ME ACEITA SENHOR.
');
