INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8fd07dc7-7a36-4df1-b5b8-0eb3d02422d9', 'Leva tu contigo o nome', '265', 'Let.: Lydia Baxter; Trad. Benjamim Rufino Duarte; Mus. William Howard Doane', 'Marcha', 'G', 'Morte, Ressureição e Salvação', 'LEVA TU CONTIGO O NOME
DE JESUS, O SALVADOR;
ESTE NOME DÁ CONFORTO
SEMPRE, SEJA ONDE FOR.

CORO
NOME BOM, DOCE À FÉ,
A ESPERANÇA DO PORVIR,
NOME BOM, DOCE À FÉ,
A ESPERANÇA DO PORVIR.

ESSE NOME LEVA SEMPRE
PARA BEM TE DEFENDER,
ELE É A ARMA AO TEU ALCANCE
QUANDO O MAL TE APARECER.

OH! QUE NOME PRECIOSO!
GOZO TRAZ AO CORAÇÃO;
SENDO POR JESUS ACEITO,
TU TERÁS O SEU PERDÃO.

SANTO NOME, ADORÁVEL,
TEM JESUS, O AMADO TEU;
"REI DOS REIS, SENHOR ETERNO,"
TU O ACLAMARÁS NO CÉU.
');
