INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('8fd6eced-524c-437e-a608-71bcb333668c', 'Molda-me, Senhor', '', '', '', '', '', 'MOLDA-ME SENHOR CONFORME TEU QUERER
FAÇA RESPLANDECER TUA LUZ EM MEU VIVER
OUÇA MINHA VOZ PEDINDO PERDÃO
TU ME SONDAS, ME CONHECES
TOMA O MEU CORAÇÃO.

*CORO
TOMA-ME SENHOR EM TUAS MÃOS SARA AS FERIDAS
DO VIVER MOSTRA-ME O CAMINHO A SEGUIR
PARA QUE EU VEJA O TEU PODER QUERO EM TEUS
BRAÇOS SEMPRE ESTAR QUERO A TUA FACE
CONTEMPLAR ÉS O MEU OLEIRO CRIADOR
MOLDA-ME MEU MESTRE SALVADOR.

MOLDA-ME SENHOR CONFORME TEU QUERER
FAÇA RESPLANDECER TUA LUZ EM MEU VIVER
OUÇA MINHA VOZ PEDINDO PERDÃO
TU ME SONDAS, ME CONHECES
TOMA O MEU CORAÇÃO.

*CORO
TOMA-ME SENHOR EM TUAS MÃOS SARA AS FERIDAS
DO VIVER MOSTRA-ME O CAMINHO A SEGUIR
PARA QUE EU VEJA O TEU PODER QUERO EM TEUS
BRAÇOS SEMPRE ESTAR QUERO A TUA FACE
CONTEMPLAR ÉS O MEU OLEIRO CRIADOR
MOLDA-ME MEU MESTRE SALVADOR.

QUEBRA SENHOR MINHA VIDA
EM TUAS MÃOS
MOLDA O MEU VIVER.

*CORO 2X
TOMA-ME SENHOR EM TUAS MÃOS SARA AS FERIDAS
DO VIVER MOSTRA-ME O CAMINHO A SEGUIR
PARA QUE EU VEJA O TEU PODER QUERO EM TEUS
BRAÇOS SEMPRE ESTAR QUERO A TUA FACE
CONTEMPLAR ÉS O MEU OLEIRO CRIADOR
MOLDA-ME MEU MESTRE SALVADOR.

FINAL
MOLDA-ME SENHOR
(CONFORME O TEU QUERER)
MOLDA-ME SENHOR
(CONFORME O TEU QUERER)
MOLDA-ME SENHOR.
');
