INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('901be376-d85a-4480-ab3b-7c8064284113', 'Se Em Tua Vida Falta Paz', '249', 'Gérson Beluci Miguel; Veimar Jeamond Luz', 'Repique', 'Dm', 'Morte, Ressureição e Salvação', 'SE EM TUA VIDA FALTA PAZ,
SE EM TEU VIVER NÃO EXISTE AMOR,
QUERO TE FALAR DO MEU SENHOR,
E UMA VIDA NOVA ENCONTRARÁS.

CORO
CRISTO É A VIDA, ELE É A PAZ,
FONTE DE ÁGUA VIVA
QUE A TODOS SATISFAZ.

SÊ UMA NOVA CRIATURA,
ENTREGA OS TEUS PECADOS A JESUS,
ARREPENDE-TE E COMEÇA A VIVER,
ANUNCIANDO QUE JESUS É A SALVAÇÃO.
');
