INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('912d442a-0552-47af-9f38-5a18a868fa91', 'Sua Glória', '', '', '', '', '', 'DESCEU DA SUA GLÓRIA
E HABITOU ENTRE NÓS, PECADORES;
MORREU EM UMA CRUZ,
O SEU NOME É JESUS, O SENHOR.

*CORO
ELE É O PÃO DA VIDA
QUE DÁ VIDA AO PECADOR;
ELE É A FONTE DE ÁGUA VIVA
QUE SACIA OS SALVOS DO SENHOR.

PORQUE DEUS AMOU O MUNDO
DE TAL MANEIRA
QUE DEU SEU FILHO UNIGÊNITO PARA SALVAR;
ELE DISSE: “QUEM CRER TERÁ
VIDA ETERNA PARA GOZAR”.

ELE É O PÃO DA VIDA
QUE DÁ VIDA AO PECADOR;
/CANTAR 3X
ELE É A FONTE DE ÁGUA VIVA
QUE SACIA OS SALVOS DO SENHOR.

*CORO
ELE É O PÃO DA VIDA
QUE DÁ VIDA AO PECADOR;
/FINAL 3X
ELE É A FONTE DE ÁGUA VIVA
QUE SACIA OS SALVOS DO SENHOR.
');
