INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('917024e5-9deb-4990-8f74-0b2c980b0369', 'Jesus libertou', '794', 'Mariana Martins Barros', 'Básico', 'C', 'Corinhos', 'JESUS LIBERTOU
MINH''ALMA DO MEU VIL PECADO
ELE ESTÁ FALANDO A TI,
QUER SALVAR, QUER TE PERDOAR.

ELE SE FEZ CARNE AQUI
E NA CRUZ, PURO, SE ENTREGOU
E VENCEU A MORTE POR NÓS.
PIEDOSO, VAI TE LIBERTAR,
BASTA NO SEU NOME CRER
E A ELE RECEBER.
');
