INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('91f2a5fd-fe0f-43aa-9ecb-b1110348278a', 'Tudo está pronto', '060', 'Jones fabem', 'Balada', 'Eb', 'Grupo de Louvor', 'TUDO ESTÁ PRONTO,
O NOIVO VIRÁ PRA BUSCAR A ESPOSA,
LEVARÁ PARA A CEIA QUE O PAI PREPAROU,
BREVE ELE VEM!
AO SOM DA TROMBETA, AOS SEUS ANJOS DARÁ
ORDEM CELESTIAL, (ENTRAI!)
E A IGREJA ENTÃO ENTRARÁ NA FESTA ETERNAL.

*CORO 2X
ENTRAI, ENTRAI (ENTRAI!)
TODOS OS REMIDOS,
QUE CALÇARAM OS SAPATOS,
LAVARAM SUAS VESTES
NO SANGUE DO CORDEIRO.
INSTRUMENTOS

COMEI DO MANÁ, O MANÁ ESCONDIDO,
ALIMENTO CELESTIAL,
DO FRUTO DA ÁRVORE DA VIDA,
ENTÃO PODEIS PROVAR,

A MORTE VENCIDA, COROA DA VIDA,
NOVOS NOMES, NOVOS CORPOS,
ASSENTADOS NO TRONO,
ADORANDO PRA SEMPRE
AQUELE QUE É O AMÉM.

*CORO 2X
ENTRAI, ENTRAI (ENTRAI!)
TODOS OS REMIDOS,
QUE CALÇARAM OS SAPATOS,
LAVARAM SUAS VESTES
NO SANGUE DO CORDEIRO.
FINAL
O ESPÍRITO E A ESPOSA DIZEM: VEM! (3X)
');
