INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('91fe0aa1-a7f2-4243-b18a-610288475061', 'Como aconteceu em Jerusalém', '757', 'Autor Desconhecido', 'Marcha', 'D', 'Corinhos', 'COMO ACONTECEU EM JERUSALÉM,
AOS SEUS DISCÍPULOS DEUS MANDOU PODER,
OH! MANDA JÁ PODER A NÓS TAMBÉM
POR ISSO DAMOS GLÓRIA, GLÓRIA COM PODER.

*CORO
GLÓRIA, GLÓRIA, GLÓRIA A JESUS (2X)
GLÓRIA, GLÓRIA, GLÓRIA COM PODER
GLÓRIA, GLÓRIA, O FOGO VAI DESCER.

A NOSSA IGREJA VAI ESTREMECER
QUANDO O PODER DE DEUS AQUI DESCER
E QUANDO O FOGO SANTO AQUI CAIR,
A VOZ DE CRISTO TODOS VÃO OUVIR.

*CORO
GLÓRIA, GLÓRIA, GLÓRIA A JESUS (2X)
GLÓRIA, GLÓRIA, GLÓRIA COM PODER
GLÓRIA, GLÓRIA, O FOGO VAI DESCER.
/INSTRUMENTOS

*CORO
GLÓRIA, GLÓRIA, GLÓRIA A JESUS (2X)
GLÓRIA, GLÓRIA, GLÓRIA COM PODER
GLÓRIA, GLÓRIA, O FOGO VAI DESCER.
');
