INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('91fe7b5d-44fc-4440-85a2-cd946ae86611', 'Deixa me chorar', '353', 'Jorgemar Souza Madeira', 'Básico', 'C', 'Consolo e Encorajamento', 'DEIXA-ME CHORAR AOS TEUS PÉS,
DEIXA-ME SENTIR O TEU AMOR,
SENHOR, SENHOR.
/SEM O TEU AMOR NÃO SEI VIVER,
SEM A TUA GRAÇA EU NÃO SOU
FELIZ, FELIZ.

TE AMO, Ó SENHOR,
AUTOR DA MINHA FÉ.
POIS CONSOLAS MINH''ALMA,
O TEU SER ME ACALMA, Ó SENHOR.

DEIXA-ME CHORAR AOS TEUS PÉS,
DEIXA-ME SENTIR O TEU AMOR,
SENHOR, SENHOR.
/SEM O TEU AMOR NÃO SEI VIVER,
SEM A TUA GRAÇA EU NÃO SOU
FELIZ, FELIZ.

TE AMO, Ó SENHOR,
AUTOR DA MINHA FÉ.
POIS CONSOLAS MINH''ALMA,
O TEU SER ME ACALMA, Ó SENHOR.
/FINAL
DEIXA-ME CHORAR AOS TEUS PÉS.
');
