INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9288d5b3-4153-410c-b851-9414b6458505', 'Muito em breve o Rei vem', '', '', '', 'A', '', 'CANTAR 2X
MUITO EM BREVE O REI VEM,
(SIM! JESUS VEM!)
MUITO EM BREVE O REI VEM,
(SIM! JESUS VEM!)
MUITO EM BREVE O REI VEM, MEU SENHOR JESUS VEM.

VEM DEPRESSA, POIS ELE TE CHAMA.
TE CONVIDA A PARTICIPAR DA FESTA,
TUDO JÁ ESTÁ PREPARADO,
MEU SENHOR JESUS VEM.
VEM BUSCAR UM POVO PREPARADO,
O ESPÍRITO NOS TEM REVELADO,
VIGIAI, O REI VEM, ELE VEM!
');
