INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('93106c34-0ed1-4ba6-a634-12d531ef42df', 'Onde vive o Rei da Glória', '220', 'E.H.M.R.', 'Balada', 'G', 'Crianças e Adolescentes', 'ONDE VIVE O REI DA GLÓRIA?
VIVE EM MEU CORAÇÃO.
ONDE REINA O REI DA GLÓRIA?
REINA EM MEU CORAÇÃO.

ELE FALA, ELE GUIA
NOSSOS PASSOS A JERUSALÉM,
PARA JUNTOS HABITARMOS
COM JESUS, NOSSO REI.

O NOSSO REI DA GLÓRIA
OPERA MARAVILHAS
NO MEIO DA IGREJA,
LIBERTA CORAÇÕES;

E HOJE QUER TRANSFORMAR
A SUA VIDA,
VEM AGORA E SINTA
O PODER DO SALVADOR,
ALELUIA! OH! GLÓRIA!
LOUVEMOS AO SENHOR.

ONDE VIVE E REINA 
O REI DA GLÓRIA?
VIVE, REINA EM NOSSOS CORAÇÕES
EM NOSSOS CORAÇÕES.
');
