INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('931a50b1-269a-4d6f-a26d-591b73ca16a2', 'Amo Ao Senhor', '651', 'Let: Sérgio Carlos de Souza; Mús. Emanoel Aleixo Júnior', 'Básico', 'G', 'Salmos de Louvor', 'AMO AO SENHOR, O DEUS DOS DEUSES,
SENHOR DOS SENHORES,
QUE OUVE A MINHA VOZ
E AS MINHAS SÚPLICAS,
MESMO NO MEIO DA ANGÚSTIA
INVOCO O NOME DO SENHOR E SOU SALVO.

QUE DAREI EU AO SENHOR
POR TUDO O QUE ME TEM FEITO?
TOMAREI O CÁLICE DA SALVAÇÃO,
OFERECEREI SACRIFÍCIOS DE LOUVOR
NOS ÁTRIOS DA CASA DO SENHOR.

LOUVAI AO SEU NOME, LOUVAI, LOUVAI,
LOUVAI AO SEU NOME, LOUVAI, LOUVAI. 
/INSTRUMENTOS

AMO AO SENHOR, O DEUS DOS DEUSES,
SENHOR DOS SENHORES,
QUE OUVE A MINHA VOZ
E AS MINHAS SÚPLICAS,
MESMO NO MEIO DA ANGÚSTIA
INVOCO O NOME DO SENHOR E SOU SALVO.

FINAL
AO SEU NOME LOUVAI, LOUVAI,
LOUVAI AO SEU NOME, LOUVAI, LOUVAI.
