INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('93e5b296-9bc5-4cce-9b98-fcc9f1a6e341', 'Jerusalém de ouro', '', '', '', '', '', 'JERUSALÉM, EM TUAS RUAS
EU OUÇO A ECOAR
O SOM DA HARPA DE DAVI,
MINHA ALMA A ACALENTAR
POR ENTRE AS TUAS OLIVEIRAS,
O VENTO VEM CONTAR
HISTÓRIAS DA VELHA CIDADE
QUE OS MUROS VÃO GUARDAR.

CORO 2X
JERUSALÉM, JERUSALÉM,
BELEZA E COR DE ISRAEL,
TU ÉS O ORGULHO DO TEU DEUS,
EMANUEL.

AINDA OUÇO EM TUAS RUAS
O SOM DA MULTIDÃO,
DE PEREGRINOS E AMANTES
EM BUSCA DE OBLAÇÃO,
NO SANTO TEMPLO E EM TUAS FONTES
SE ENCONTRAVA A PAZ,
JERUSALÉM, QUEM TE CONHECE
NÃO TE ESQUECE MAIS.

JERUSALÉM, EM TUAS PRECES
LEMBRA DOS FILHOS TEUS
QUE AINDA NÃO TE CONHECERAM
MAS AMAM O TEU DEUS,
SÃO VELHOS, JOVENS E MENINOS
DISTANTES DO SEU LAR,
QUE NÃO PISARAM TUAS RUAS
MAS VIVEM POR TE AMAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('93e5b296-9bc5-4cce-9b98-fcc9f1a6e341', '45ab58b2-d293-45c7-aa75-090fcd968b24');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('93e5b296-9bc5-4cce-9b98-fcc9f1a6e341', '8d5f147b-a28c-425f-9ba8-101434030af9');
INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('d1819211-2176-4b9f-adb8-5f347a84e40e', '93e5b296-9bc5-4cce-9b98-fcc9f1a6e341', 'ac66b2d8-814c-42a0-8210-1b767ac609f7', 'pdf', 'assets/praises/93e5b296-9bc5-4cce-9b98-fcc9f1a6e341/d1819211-2176-4b9f-adb8-5f347a84e40e.pdf', 'Avulsos PES/Jerusalém de ouro/Jerusalem de Ouro - Cordas.pdf', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('93e9e7ee-4a22-47bc-b6e1-9f17b65ba122', 'A Vida No Mundo É Cruel', '316', 'Jair', 'Básico 2', 'E', 'Consolo e Encorajamento', 'A VIDA NO MUNDO É CRUEL,
TORMENTO E LUTAS SEM FIM;
CAMINHO ALMEJANDO O CÉU;
JESUS, TU TE LEMBRAS DE MIM!

CORO
JESUS, TU TE LEMBRAS DE MIM! (2X)
NA VIDA, NA MORTE E NA DOR:
JESUS, TU TE LEMBRAS DE MIM!

NAVEGANDO VAI MINHA NAU,
NO MAR DESTA VIDA AQUI;
ABRIGA-ME NO TEMPORAL;
JESUS, TU TE LEMBRAS DE MIM!

JESUS, O QUE HEI DE FAZER
SE O MUNDO ESTÁ CONTRA MIM?
ENVIA-ME O TEU PODER;
JESUS, TU TE LEMBRAS DE MIM!
');
