INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9443e411-69e8-4b6f-8afc-9c307b1cbcc6', 'Quem é Que Dá Água ao Sedento', '282', 'Jorgemar Souza Madeira', 'Balada', 'C', 'Consolo e Encorajamento', 'QUEM É QUE DÁ ÁGUA AO SEDENTO
E UMA SOMBRA FRESCA?
QUEM É QUE RETIRA DO HOMEM TODO ARDOR?
QUEM É QUE ABRIU NO CALVÁRIO
UM NOVO CAMINHO?
QUEM É A FONTE DA VIDA, O GRANDE AMOR?

*CORO
É O FILHO DE DEUS, É JESUS, O SENHOR,
É O GRANDE EU SOU, ELE É O CORDEIRO DE DEUS,
O AUTOR DA ETERNA VIDA, ELE É JESUS.
/INSTRUMENTOS

QUEM É QUE DÁ ÁGUA AO SEDENTO
NUMA TERRA SECA?
QUEM É A FLOR MAIS QUERIDA DO LINDO JARDIM?
QUEM É QUE TRAZ PAZ E CONSOLO
DENTRO DA ALMA?
QUEM É O AMIGO EXCELENTE, O SALVADOR?

*CORO
É O FILHO DE DEUS, É JESUS, O SENHOR,
É O GRANDE EU SOU, ELE É O CORDEIRO DE DEUS,
O AUTOR DA ETERNA VIDA, ELE É JESUS.
/INSTRUMENTOS

*CORO 
É O FILHO DE DEUS, É JESUS, O SENHOR,
É O GRANDE EU SOU, ELE É O CORDEIRO DE DEUS,
O AUTOR DA ETERNA VIDA, ELE É JESUS.
');
