INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('948fa0f7-3615-4cc1-b9c9-56053a22277a', 'Se Tu Estás Tão Longe do Senhor', '258', 'José Elias Simora', 'Básico', 'F#m', 'Morte, Ressureição e Salvação', 'SE TU ESTÁS TÃO LONGE DO SENHOR,
SE ESQUECESTE DE TUDO O QUE ELE FEZ POR TI,
AINDA HÁ TEMPO PARA VOLTARES
AOS BRAÇOS DAQUELE QUE TE AMA.

*CORO
"VOLTA, FILHO MEU, PARA OS BRAÇOS MEUS,
PORQUE JAMAIS ME ESQUECI DE TI,
O TEU NOME TENHO GRAVADO
EM MINHAS MÃOS."

"EU SOU JESUS QUEM FALA CONTIGO,
O TEU CONSOLO QUANDO ESTÁS ABATIDO,
O REFÚGIO EM MOMENTOS DIFÍCEIS,
EU TE LEVANTO QUANDO ESTÁS CAÍDO."

*CORO 2X
"VOLTA, FILHO MEU, PARA OS BRAÇOS MEUS,
PORQUE JAMAIS ME ESQUECI DE TI,
O TEU NOME TENHO GRAVADO
EM MINHAS MÃOS."
/FINAL
"EM MINHAS MÃOS."
');
