INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('94afa862-def7-40bb-accc-d4a16e1ec56f', 'Felicidade é ter Cristo', '129', 'Autor Desconhecido', 'Fox Abafado', 'A', 'Dedicação', 'FELICIDADE É TER CRISTO AO MEU LADO
E POR ELE SER GUARDADO,
TER MEU NOME ESCRITO NO CÉU;
MEU NOME ESTÁ ESCRITO NAS MÃOS
DO MEU JESUS,
QUANDO MORREU ALI NA CRUZ,
E ASSIM MUI FELIZ SOU EU.

CORO
FELICIDADE É POSSUIR O MEU JESUS,
E TODO DIA LEVAR A CRUZ
ATÉ O DIA EM QUE ELE VOLTAR;
FELICIDADE É SER LAVADO NO SANGUE DE JESUS,
E SEMPRE ANDAR NA SUA LUZ,
ATÉ O DIA EM QUE ELE VOLTAR.

FELICIDADE É IR MORAR NUMA CIDADE,
ONDE HÁ PAZ E VERDADE,
É JESUS QUEM MORA LÁ!
EU SOU FELIZ E EM JESUS EU TENHO ALGO,
E POR ELE JÁ SOU SALVO,
ELE PODE ME GUARDAR!
');
