INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9526ef27-0c68-4d60-9b83-aa1a6618d61c', 'Rude Cruz', '212', 'Let. e Mús.: George Bennard; Trad. Finis Alma Morgan', 'Básico 2', 'A', 'Morte, Ressureição e Salvação', 'RUDE CRUZ SE ERIGIU, DELA O DIA FUGIU,
COMO EMBLEMA DE VERGONHA E DOR;
MAS EU AMO ESSA CRUZ, 
PORQUE NELA, JESUS
DEU A VIDA POR MIM, PECADOR.

CORO
SIM, EU AMO A MENSAGEM DA CRUZ,
''TÉ MORRER EU A VOU PROCLAMAR;
LEVAREI EU TAMBÉM MINHA CRUZ,
''TÉ POR UMA COROA TROCAR.

DESDE A GLÓRIA DOS CÉUS,
O CORDEIRO DE DEUS
AO CALVÁRIO HUMILHANTE BAIXOU;
TEM A CRUZ PARA MIM ATRATIVOS SEM FIM,
PORQUE NELA JESUS ME SALVOU.

LÁ NA CRUZ PADECEU,
DESPREZADO MORREU
MEU JESUS PARA DAR-ME O PERDÃO;
DELA AGORA PROVÉM PARA MIM TODO O BEM,
TENHO NELA REAL SALVAÇÃO.

EU AQUI COM JESUS,
A VERGONHA DA CRUZ
QUERO SEMPRE LEVAR E SOFRER;
QUANDO CRISTO VOLTAR,
PARA AQUI ME BUSCAR,
SUA GLÓRIA EU IREI RECEBER.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('9526ef27-0c68-4d60-9b83-aa1a6618d61c', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
