INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('95fe5e63-d5af-4453-b181-2d5437abde14', 'Eu confio em Ti Senhor', '707', 'H.S.C', 'Básico', 'G', 'Grupo de Louvor', 'EU CONFIO EM TI, SENHOR!
MESMO QUANDO TUDO NÃO VAI BEM,
E A ESPERANÇA FUGIR,
EU OLHAREI SÓ PRA TI.
ACALMA O MEU CORAÇÃO,
SEGURA MINHA MÃO
E ME FAZ UM VENCEDOR,
SIM, ME FAZ UM VENCEDOR.

PORQUE NUNCA SE OUVIU, 
E NUNCA SE VIU UM DEUS ALÉM DE TI. 
E EU APRENDI A CONFIAR
NO DEUS PROVEDOR QUE NÃO FALHARÁ.

ROCHA INABALÁVEL,
MEU ABRIGO E BOM PASTOR. 
SOCORRO BEM PRESENTE, 
MESMO NA TRISTEZA E DOR.
EU CONFIO EM TI, SENHOR! (2X)
JESUS!
/INSTRUMENTOS

EU CONFIO EM TI, SENHOR!
MEU CAMINHO PONHO EM TEU ALTAR.
TUA VOZ EU QUERO OUVIR,
TUA PRESENÇA, SIM, QUERO SENTIR.
ENSINA-ME A CAMINHAR E A TE HONRAR, 
SENHOR, 
E ME FAZ UM VENCEDOR,
SIM, ME FAZ UM VENCEDOR.

PORQUE NUNCA SE OUVIU, 
E NUNCA SE VIU UM DEUS ALÉM DE TI. 
E EU APRENDI A CONFIAR
NO DEUS PROVEDOR QUE NÃO FALHARÁ.

ROCHA INABALÁVEL,
MEU ABRIGO E BOM PASTOR. 
SOCORRO BEM PRESENTE, 
MESMO NA TRISTEZA E DOR.
EU CONFIO EM TI, SENHOR! (2X)

ACALMA O MEU CORAÇÃO,
SEGURA MINHA MÃO
E ME FAZ UM VENCEDOR,
SIM, ME FAZ UM VENCEDOR.

ROCHA INABALÁVEL,
MEU ABRIGO E BOM PASTOR.
SOCORRO BEM PRESENTE,
MESMO NA TRISTEZA E DOR.
EU CONFIO EM TI, SENHOR! (2X)
JESUS!
/FINAL
ABRIGO SEGURO, JESUS!
');
