INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9626417d-be26-4dc5-9f6d-d27d8e64a689', 'No Getsêmani', '470', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'Am', 'Grupo de Louvor', 'NO GETSÊMANI JESUS OROU:
"PASSA DE MIM ESTE CÁLICE,"
MAS O ALTAR ESTAVA PRONTO
PARA O RECEBER;
O CUTELO, A LENHA E O FOGO
AGUARDAVAM O CORDEIRO
QUE DARIA A SUA VIDA PELO MUNDO.

CORO
AO LAGAR DESCEU O FRUTO DA VIDEIRA
E CORREU DA COR DO SANGUE O SEU MOSTO
/CANTAR 2X
PRA QUE EU PUDESSE ENCHER MEU CÁLICE
DE SALVAÇÃO.
/INSTRUMENTOS

HOJE AQUI NÓS CELEBRAMOS
ESTA PÁSCOA VERDADEIRA,
POIS DO JUGO LIBERTADOS
TEMOS PAZ COM DEUS;
COMO MEMBROS DE UM SÓ CORPO
PARTILHAMOS DE UM MESMO PÃO
E BEBEMOS DESTE CÁLICE DO SEU SANGUE.
');
