INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('962c3f5f-f306-49eb-a400-89394e94a5e9', 'Jesus é tudo pra mim', '763', '', 'Balada', 'G', 'Corinhos', 'JESUS É TUDO PRA MIM.
ELE É TUDO PRA MIM.
/CANTAR 2X
JESUS É O TESOURO QUE EU TENHO
GUARDADO NO PEITO,
ELE É TUDO PRA MIM.

JESUS É TUDO PRA MIM.
ELE É TUDO PRA MIM.
/FINAL 2X
JESUS É O TESOURO QUE EU TENHO
GUARDADO NO PEITO,
ELE É TUDO PRA MIM.
