INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('96f59a47-a46b-41dd-90ca-9f56681df147', 'Hoje eu não quero pedir', '232', 'C.M.V.', 'Marcha', 'Bm', 'Crianças e Adolescentes', 'HOJE EU NÃO QUERO PEDIR NADA A TI,
EU SÓ QUERO LOUVAR, MEU SENHOR,
POIS GRANDES COISAS FIZESTE POR MIM,
POR ISSO ALEGRE ESTOU.

A NOITE JÁ ACABOU, FOI-SE A DOR,
A ALEGRIA VOLTOU EM LOUVOR;
TUA PALAVRA É FIEL, CREIO ASSIM,
POR ISSO ALEGRE ESTOU.
');
