INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('96f59d1c-4fac-46e9-9f3d-3716144adebd', 'Clamando estou', '005', 'Sara Gueiros Dodd', 'Fox', 'G', 'Clamor', 'CLAMANDO ESTOU, Ó MEU JESUS,
POR TEU SANGUE REMIDOR;
SOCORRO EU SEI QUE MANDARÁS
E LIVRAMENTO A MIM.

TEU SANGUE PURO DERRAMASTE
PARA ME PURIFICAR;
ENTÃO ADORAREI A TI,
Ó MEU SENHOR.
');
