INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('974240d4-9b0e-49c2-a463-4e5c18b43873', 'Minha alma, pois, alegre canta', '533', 'Jorgemar Souza Madeira', 'Básico', 'D', 'Volta de Jesus e Eternidade', 'MINHA ALMA, POIS, ALEGRE CANTA:
VOU PRA JERUSALÉM;
É UMA CIDADE SANTA,
NOVA JERUSALÉM.

*CORO
SE VOCÊ QUISER A VIDA
E CAMINHAR TAMBÉM,
/CANTAR 2X
SEGURA NA MÃO DE CRISTO
E VAI PRA NOVA JERUSALÉM.
/INSTRUMENTOS

LÁ NÃO HÁ PRANTO,
TRISTEZAS E NEM DOR,
SÓ HÁ A PAZ DE CRISTO,
ALEGRIA E MUITO AMOR.

*CORO
SE VOCÊ QUISER A VIDA
E CAMINHAR TAMBÉM,
/CANTAR 2X
SEGURA NA MÃO DE CRISTO
E VAI PRA NOVA JERUSALÉM.
');
