INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('975850a2-1fd1-499c-a34f-d1769c2ce127', 'O dias estão passando', '211', 'P.H.R.', 'Básico', 'E', 'Crianças e Adolescentes', 'OS DIAS ESTÃO PASSANDO,
O MOMENTO SE APROXIMA
DO ENCONTRO TRIUNFAL.
A TROMBETA VAI TOCAR,
A PALAVRA ME DIRIGE,
APONTA O CAMINHO,
OLHO PARA O ALTO
E VEJO A REDENÇÃO.

*CORO
EU IREI CONTEMPLAR OS CÉUS ABERTOS,
OUVIREI JESUS CHAMAR PELO MEU NOME,
EU TEREI O MEU CORPO TRANSFORMADO,
PARA ENCONTRAR O SALVADOR.
EU IREI ANDAR NAS RUAS DE OURO,
EU IREI CANTAR NUM LINDO CORAL,
EU IREI VER A ÁRVORE DA VIDA,
ESTAREI EM MEU NOVO LAR
(ESTAREI EM JERUSALÉM)
/INSTRUMENTOS

QUERO ESTAR CONTIGO, MEU SENHOR,
(VEM, MEU SENHOR) VEM ME BUSCAR!
TIRA TODA DOR E O MEU SOFRER,
TRANSFORMA O MEU CHORO EM ALEGRIA.

*CORO 2X
EU IREI CONTEMPLAR OS CÉUS ABERTOS,
OUVIREI JESUS CHAMAR PELO MEU NOME,
EU TEREI O MEU CORPO TRANSFORMADO,
PARA ENCONTRAR O SALVADOR.
EU IREI ANDAR NAS RUAS DE OURO,
EU IREI CANTAR NUM LINDO CORAL,
EU IREI VER A ÁRVORE DA VIDA,
ESTAREI EM MEU NOVO LAR
(ESTAREI EM JERUSALÉM)
');
