INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('977692f9-ea28-4367-9130-28dd6860c97f', 'Sete cartas', '169', 'H.D.S.', 'Fox', 'A', 'Crianças e Adolescentes', 'SETE CARTAS JOÃO ESCREVEU,
AO ANJO DAS IGREJAS DEUS MANDOU,
"CONHEÇO AS TUAS OBRAS",
ASSIM DIZ O SENHOR,
"QUEM TEM OUVIDOS
OUÇA A VOZ DO MEU ESPÍRITO".

CANTAR 2X
ÉFESO, ESMIRNA, PÉRGAMO, TIATIRA,
SARDES, FILADÉLFIA E LAODICÉIA.

SÃO SETE CARTAS, SETE IGREJAS,
SETE ESPÍRITOS DE DEUS
A FALAR NO MEIO DAS IGREJAS.

