INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9822331e-3ca0-4590-8b18-f19354d0696c', 'Uma voz mansa e Delicada', '', '', '', 'G', 'Avulsos', 'UMA VOZ MANSA E DELICADA,
SINTA AGORA A MINHA PAZ EM TEU CORAÇÃO.
SEI PORQUE ESTÁS AQUI,
PENSAS QUE EU NÃO TE VI.
SAI DA ESCURIDÃO!
EU VOU TIRAR O MEDO DO TEU CORAÇÃO.

PENSAS ESTAR SÓ
E OLHAS AO TEU REDOR.
SEI QUE HÁ MUITOS
QUE ME DEIXARAM,
DESTRUÍRAM MEUS ALTARES,
DESPREZARAM A PROFECIA DO TEU DEUS

*CORO 2X
EU QUERO TE DIZER
QUE EU LIVREI, SALVEI
TODOS QUE NÃO ME NEGARAM
JOELHOS QUE NÃO SE DOBRARAM

TEU FIM NÃO É AQUI
TU VAIS PROSSEGUIR
POIS GRANDES COISAS,SIM,
TU VIVERÁS POR MIM
/INSTRUMENTOS

