INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('99105f65-5c8d-470d-aa97-68aa42c8b7de', 'Dons do Espírito Santo', '', '', '', '', '', 'ESPÍRITO SANTO, ORE POR MIM
LEVE PRA DEUS TUDO AQUILO QUE EU PRECISO
ESPÍRITO SANTO, USE AS PALAVRAS
QUE EU NECESSITO USAR, MAS NÃO CONSIGO
ME AJUDE NAS MINHAS FRAQUEZAS
NÃO SEI COMO DEVO PEDIR ESPÍRITO SANTO,
VEM INTERCEDER POR MIM.

TODAS AS COISAS COOPERAM PRA O BEM
DAQUELES QUE AMAM A TI ESPÍRITO SANTO,
VEM ORAR POR MIM.

*CORO
ESTOU CLAMANDO,
ESTOU PEDINDO
SÓ DEUS SABE A DOR
QUE ESTOU SENTINDO
MEU CORAÇÃO ESTÁ FERIDO
MAS O MEU CLAMOR ESTÁ SUBINDO.

TODAS AS COISAS COOPERAM PRA O BEM
DAQUELES QUE AMAM A TI ESPÍRITO SANTO,
VEM ORAR POR MIM.

*CORO 2X
ESTOU CLAMANDO,
ESTOU PEDINDO
SÓ DEUS SABE A DOR
QUE ESTOU SENTINDO
MEU CORAÇÃO ESTÁ FERIDO
MAS O MEU CLAMOR ESTÁ SUBINDO.
');
