INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('997fbaf0-3275-43d3-a4a7-5fbec1f42ed0', 'Na Eternidade', '675', 'Olcimar Rubens de Carvalho', 'Valseado', 'Em', 'Grupo de Louvor', 'NA ETERNIDADE, AO LADO DE JESUS,
ANSEIO LOGO ESTAR E ESTE MUNDO DEIXAR;
QUERO COM OS ANJOS FORMAR UM GRANDE CORO
E CANTAR LOUVORES DE ADORAÇÃO AO SENHOR.
O CORO DOS ANJOS E AS VOZES DOS ARCANJOS
JÁ LOUVAM A JESUS.

*CORO
BREVE OS REMIDOS NA GLÓRIA ESTARÃO
E JUNTO COM OS ANJOS E ARCANJOS
VÃO PARA SEMPRE LOUVAR, LOUVAR A JESUS.
/INSTRUMENTOS

O MEU CORAÇÃO TRANSBORDA DE ALEGRIA
AO IMAGINAR QUE GRANDE DIA SERÁ;
O CORDEIRO SANTO VIRÁ SOBRE AS NUVENS
E A SUA IGREJA AO SEU ENCONTRO SUBIRÁ.
SAUDAI A JESUS! ELE É O REI DA GLÓRIA
QUE VIRÁ NOS BUSCAR.

*CORO
BREVE OS REMIDOS NA GLÓRIA ESTARÃO
E JUNTO COM OS ANJOS E ARCANJOS
VÃO PARA SEMPRE LOUVAR, LOUVAR A JESUS.
/SAUDAI A JESUS! ELE É O REI DA GLÓRIA
QUE VIRÁ NOS BUSCAR.

*CORO
BREVE OS REMIDOS NA GLÓRIA ESTARÃO
E JUNTO COM OS ANJOS E ARCANJOS
VÃO PARA SEMPRE LOUVAR, LOUVAR A JESUS.
/FINAL 
LOUVAR A JESUS.
');
