INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9a331555-8276-4a53-b7ae-bf37b4bdaacf', 'O Que Habita No Abrigo de Deus', '313', 'Márcia Costa Capli', 'Básico 2', 'Em', 'Consolo e Encorajamento', 'O QUE HABITA NO ABRIGO DE DEUS
MORARÁ SOB SOMBRAS DE AMOR,
SOBRE ELE NÃO VIRÁ NENHUM MAL,
EM SUAS ASAS FELIZ VIVERÁ.

OH! EU QUERO HABITAR
NO ABRIGO DE DEUS,
SÓ ALI ACHAREI PAZ E PROFUNDO AMOR;
MEU DESEJO É COM ELE
COMUNHÃO DESFRUTAR
E PRA SEMPRE O SEU NOME LOUVAR.
');
