INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9a8a6376-07aa-483f-aea1-e4d08fd607a0', 'A Luz do mundo', '641', 'Fábio Henrique Barros Ramos', 'Básico', 'D', 'Dedicação', 'A LUZ DO MUNDO,
O LÍRIO DOS VALES
A FONTE DE ÁGUAS VIVAS, EMANUEL;
O VERBO VIVO, RAIZ DE DAVI,
ESTRELA DA MANHÃ, REI DOS REIS. 
COMO CANTAR O NOSSO AMOR
E NOSSA GRATIDÃO POR TEU FAVOR?

*CORO
GLÓRIA, HONRA E TODO LOUVOR
SEJAM A CRISTO, NOSSO SENHOR;
GLÓRIA, HONRA E TODO LOUVOR
DAI A CRISTO, ETERNO SENHOR.

(M) VENCEU A MORTE
(H) (VENCEU A MORTE)
(M) NOS RESGATOU,
(H) (NOS RESGATOU)
MOSTROU A TODA A TERRA QUE É SENHOR;

(M) NADA NO MUNDO
(H) (NADA NO MUNDO)
(M) O IMPEDIRÁ.
(H) (O IMPEDIRÁ)
JESUS RESSUSCITOU E VAI VOLTAR.

*CORO 2X
GLÓRIA, HONRA E TODO LOUVOR
SEJAM A CRISTO, NOSSO SENHOR;
GLÓRIA, HONRA E TODO LOUVOR
DAI A CRISTO, ETERNO SENHOR.
/FINAL
ETERNO SENHOR.
');
