INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9aef65aa-c91f-4d14-81aa-8c30bf1aea05', 'Eu sei que Jesus', '504', 'Everaldo Cavalcante Lima', 'Balada', 'D', 'Volta de Jesus e Eternidade', 'EU SEI QUE JESUS NÃO TARDA EM VIR,
O MEU CORAÇÃO PREPARADO ESTÁ.
/INSTRUMENTOS

EM CRISTO JESUS, A GLÓRIA POR VIR,
JESUS É A ESPERANÇA
DO MEU CORAÇÃO.

*CORO
JESUS, TU ÉS O MEU REI,
JESUS É A ESPERANÇA DA GLÓRIA POR VIR,
POR VIR, DA GLÓRIA POR VIR, 
JESUS É A ESPERANÇA DO MEU CORAÇÃO.
/INSTRUMENTOS

EM BREVE HÁ DE VIR, JESUS, O SENHOR,
ETERNA ESPERANÇA DO MEU CORAÇÃO,
A GLÓRIA POR VIR, REVELADA, ENTÃO,
IREI COM JESUS PARA SEMPRE MORAR.

*CORO
JESUS, TU ÉS O MEU REI,
JESUS É A ESPERANÇA DA GLÓRIA POR VIR,
POR VIR, DA GLÓRIA POR VIR, 
JESUS É A ESPERANÇA DO MEU CORAÇÃO.
/FINAL
JESUS É A ESPERANÇA
DO MEU CORAÇÃO.
');
