INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9b61b902-8faf-4873-8376-e02c20e0e155', 'Jesus é a nossa vitória', '239', '', 'Toada', 'A', 'Crianças e Adolescentes', 'JESUS É A NOSSA VITÓRIA
ELE NOS LEVA PARA A SUA GLÓRIA
NOS GUARDA DE TODO O PERIGO
JESUS É NOSSO GRANDE AMIGO.

EU SOU FELIZ, POIS CONHECI A JESUS
E HOJE EU CAMINHO EM SUA LUZ
NA ETERNIDADE COM JESUS VOU MORAR
E COM OS ANJOS PARA SEMPRE O ADORAR:

VIVA O REI, VIVA O REI
VIVA O REI, VIVA O REI
VIVA O REI,
VIVA O REI JESUS!
VIVA O REI JESUS!
');
