INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9ca6dfcb-79af-4bd2-89d2-7e73c1993f7d', 'Jesus, a luz divina', '113', 'Autor Desconhecido', 'Guarânia', 'E', 'Dedicação', 'JESUS, A LUZ DIVINA
QUE NÃO CESSA DE BRILHAR;
DE DIA E DE NOITE E SEMPRE
RELUZ SEM APAGAR.

CANTAR 2X
SÓ ELE É A LUZ QUE BRILHA,
E PERMANECE SOBRE O ALTAR,
E CONTINUA SEMPRE A ILUMINAR.

JESUS, A LUZ QUE BRILHA
EM NOSSOS CORAÇÕES,
TIRANDO DAS NOSSAS MENTES
AS NOSSAS ILUSÕES.

FINAL 2X
SÓ ELE É A LUZ QUE BRILHA
EM TODO CÉU, NA TERRA E MAR,
E CONTINUA SEMPRE A ILUMINAR.
');
