INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9d9dd7a9-861b-437e-a3f3-18423dc13c3e', 'Faz De Nós Um', '', '', '', '', '', 'FAZ DE NÓS UM,
COMO ÉS COM O PAI NO CÉU,
SÊ O CABEÇA E NÓS O CORPO TEU;
FAZ–NOS UM SÓ EM TI,
TUA IGREJA, TUA GREI;
ONDE O FRATERNO AMOR
SEJA PERFEITA LEI.
FAZ DE NOS UM!

SOMOS OS RAMOS E TU ÉS A VIDEIRA,
TEU SANGUE DÁ-NOS A VIDA VERDADEIRA.
NINGUÉM PODE IMPEDIR A BENÇÃO
DESTA UNIÃO,
DE TANTOS POVOS, LÍNGUAS,
CHAMASTE PARA TI UMA NAÇÃO.

*CORO
VEM REINAR SOBRE NÓS,
FAZ OUVIR A TUA VOZ!
FAZ-NOS UM SÓ REBANHO,
SENHOR,
SÓ TU ÉS NOSSO PASTOR,
FAZ DE NÓS UM!
/INSTRUMENTOS

VÊ COMO TANTAS OVELHAS SEM PASTOR,
SÃO PRESAS FÁCEIS DO ASTUTO ENGANADOR
TEM COMPAIXÃO, SENHOR,
CONGREGA O POVO TEU,
COM FOGO E GLÓRIA
NOS CONDUZ ALÉM DO VÉU!
FAZ DE NÓS UM!

*CORO 2X
VEM REINAR SOBRE NÓS,
FAZ OUVIR A TUA VOZ!
FAZ-NOS UM SÓ REBANHO,
SENHOR,
SÓ TU ÉS NOSSO PASTOR,
FAZ DE NÓS UM.
/FINAL
FAZ DE NÓS UM (2X)
');
