INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9e7117f2-3817-4237-aa65-1e47e5969b7b', 'Não sei quando Cristo Jesus há de vir', '494', 'Let.: Philip Paul Bliss; Trad. Ricardo Pitrowsky; Mus. James McGranahan', 'Balada', 'G', 'Volta de Jesus e Eternidade', 'NÃO SEI QUANDO CRISTO JESUS HÁ DE VIR
E NEM QUAL O DIA EM QUE EU HEI DE PARTIR,
MAS EU SEI QUANDO A SUA PRESENÇA LUZIR
SERÁ GRANDE GLÓRIA PRA MIM, (3X)
MAS EU SEI QUANDO A SUA PRESENÇA LUZIR,
SERÁ GRANDE GLÓRIA PRA MIM.

NÃO SEI QUE MORADA JESUS VAI ME DAR,
E NEM QUAL O NOME QUE EU HEI DE GANHAR,
MAS EU SEI QUE O BEM-VINDO DELE HEI DE ESCUTAR,
SÓ ISSO SERÁ CÉU PRA MIM. (3X)
MAS EU SEI QUE O BEM VINDO DELE HEI DE ESCUTAR,
SÓ ISSO SERÁ CÉU PRA MIM.

O CANTO DOS ANJOS AINDA NÃO SEI
NEM QUE SINFONIAS EU LÁ OUVIREI,
MAS EU SEI QUE O FALAR DE JESUS, O MEU REI
SERÁ SINFONIA PRA MIM. (3X)
MAS EU SEI QUE O FALAR DE JESUS, O MEU REI,
SERÁ SINFONIA PRA MIM.
');
