INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9ea8325e-5b80-49f8-b46f-6d4dd8a5079f', 'Dependo de Ti, Senhor', '189', 'Paulo Luis de Carvalho', 'Valseado', 'D', 'Santificação e Derramamento', 'DEPENDO DE TI, SENHOR,
QUE SEJAS ASSIM EM MEU VIVER:
TOMA O MEU CORAÇÃO,
TOTALMENTE DOMINA, Ó SENHOR!

NÃO QUERO ANDAR INDEPENDENTE, SENHOR,
POIS TUA VONTADE É VIDA PARA O MEU CORAÇÃO.
/DEPENDO DE TI, SENHOR,
NÃO POSSO ANDAR SEM TEU BRAÇO FORTE;
SEM TUA VONTADE HAVERÁ AGONIA,
TRISTEZA E MORTE.

FINAL 2X
DEPENDO DE TI, SENHOR,
DEPENDO DE TI,
DEPENDO DE TI, AMÉM.
');
