INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('9ef27b4d-dd7f-4c13-b55d-cfc20e09fb7c', 'Quão difícil é, Senhor (Faze-me um vencedor)', '385', 'M.D', 'Básico', 'A', 'Consolo e Encorajamento', 'QUÃO DIFÍCIL É, SENHOR,
VIVER NESTE MUNDO DE AFLIÇÕES.
É TEU AMOR QUE ME SUSTÉM
E PELO TEU PODER.

*CORO 2X
FAZE-ME UM VENCEDOR,
FAZE-ME, SENHOR,
UM INSTRUMENTO PRA TEU LOUVOR.
/E ADORAÇÃO ÀQUELE 
QUE É MAIS QUE VENCEDOR!
/INSTRUMENTOS

SE PROVADO EU ESTOU
E ESTAS PROVAÇÕES 
TENHO QUE PASSAR;
EIS-ME AQUI, AJUDA-ME,
APROVADO QUERO SER.

*CORO 2X
FAZE-ME UM VENCEDOR,
FAZE-ME, SENHOR,
UM INSTRUMENTO PRA TEU LOUVOR.
/E ADORAÇÃO ÀQUELE 
QUE É MAIS QUE VENCEDOR!
/FINAL
AQUELE QUE É MAIS QUE VENCEDOR!
');
