INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a010e17d-6426-425c-9627-faebdc8f7a93', 'Os Segredos do Teu Coração', '375', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'Bb', 'Santificação e Derramamento', 'OS SEGREDOS DO TEU CORAÇÃO
DEUS CONHECE, DEUS CONHECE.
TUA DOR, TUA INDAGAÇÃO
DEUS CONHECE, SIM, DEUS CONHECE.

CORO
CRISTO QUER SEU AMOR REVELAR,
OPERAR MARAVILHAS NESTE LUGAR;
VIVO ESTÁ JESUS, PRONTO A AJUDAR
AQUELE QUE QUER SUA LUZ.

O QUE TU NÃO CONSEGUES FAZER
CRISTO PODE, TUDO PODE;
IMPOSSÍVEIS NÃO HÁ PRA QUEM CRER,
CRISTO PODE, SIM, TUDO PODE.
');
