INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a03e253a-3e41-4fac-851c-e96ae4c0640e', 'Eu tenho um tesouro', '739', 'Autor Desconhecido', 'Fox Abafado', 'D', 'Corinhos', 'EU TENHO UM TESOURO, EU TENHO, SIM;
EU TENHO UM TESOURO DENTRO DE MIM;
ESTE MEU TESOURO TEM MUITO VALOR,
ESTE MEU TESOURO É JESUS CRISTO,
MEU SALVADOR.

FINAL 2X
VALE MAIS QUE O CÉU, 
VALE MAIS QUE O MAR, 
VALE MAIS QUE O MUNDO, 
VALE MAIS QUE EU. 
OH! QUE GLORIOSO, QUE GLÓRIA SEM FIM! 
ESTE MEU TESOURO 
É JESUS CRISTO QUE VIVE EM MIM.
');
