INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a05c5a90-2bb6-49f7-8b0b-feb0c3fb949e', 'Cristo é tudo para mim', '147', 'Everaldo Cavalcante Lima', 'Repique', 'D', 'Dedicação', 'CORO
CRISTO É TUDO PARA MIM,
AMOR E PAZ, PERDÃO SEM FIM;
SEM ELE A VIDA É TÃO RUIM,
CRISTO JESUS É TUDO PARA MIM.

CEDINHO SINTO O SEU AMOR,
DE NOITE SINTO TAMBÉM;
COM CRISTO ANDO SEM TEMOR,
AS TREVAS NUNCA ME VÊM.

O MUNDO NÃO ME ATRAI,
JESUS, TEU SER, JÁ ME ATRAIU;
SEGURANÇA TENHO NO PAI,
VIDA NESTE MUNDO VIL.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('a05c5a90-2bb6-49f7-8b0b-feb0c3fb949e', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
