INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a08213ec-a5b3-4f15-bfba-a52947016486', 'Conta pra Jesus onde é a tua dor', '767', '', 'Country', 'C', 'Corinhos', 'CONTA PRA JESUS ONDE É A TUA DOR.
ELE TE AJUDA A CARREGAR A CRUZ.
COM INSISTÊNCIA ORA, QUE TU VAIS VENCER:
O QUE TU PRECISAS CONTA PRA JESUS!

SE DESANIMARES COM A TUA CRUZ
LEMBRA QUE MAIOR LEVOU O MEU JESUS.
COM INSISTÊNCIA ORA, ELE VAI TE OUVIR:
O QUE TU PRECISAS CONTA PRA JESUS!

SE EM LÍNGUA ESTRANHA AINDA NÃO FALASTE
COM DEUS EM MISTÉRIOS PODES CONVERSAR.
E O ESPÍRITO SANTO, TOMARÁ TEU SER:
O QUE TU PRECISAS, CONTA PRA JESUS!
');
