INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a086d1d5-d43a-4010-9eb8-2916769c82ce', 'Jerusalém eterna', '', '', '', '', '', 'JERUSALÉM ETERNA, EM BREVE TU VIRÁS
DESCENDO COMO NOIVA ATAVIADA
PARA O SEU MARIDO;
JERUSALÉM, MINHA CIDADE
OH! COMO EU ANSEIO ENTRAR

CANTAR 2X
E ANDAR POR TUAS RUAS,
SAUDAR OS TEUS REMIDOS
E ADORAR TEU REI.
/INSTRUMENTOS

JERUSALÉM ETERNA,
ESPOSA DO CORDEIRO,
EM TI HABITARÁ
DEUS COM OS HOMENS
PARA TODO O SEMPRE!
NAÇÕES VIRÃO PARA ADORAR
E REIS TRARÃO SUA GLÓRIA

CANTAR 2X
AO FILHO DE DAVI,
AO PRÍNCIPE DA PAZ,
TEU REI, JERUSALÉM!
/FINAL
JERUSALÉM!
');
