INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a09a733e-c8ce-4ceb-9d33-7f9a95d95881', 'A Raabe veio a ordem', '202', 'S.G.D.', 'Fox', 'A', 'Crianças e Adolescentes', 'A RAABE VEIO A ORDEM:
NA JANELA DE SUA CASA COLOCAR,
UM CORDÃO DE FIO DE ESCARLATA
PRA DA MORTE SE LIVRAR.

ELA CREU E OBEDECEU.
VIU MUROS, CASAS ROLAREM,
MAS SUA CASA NÃO CAIU
FIO DE ESCARLATA A DEFENDEU.

ESTE MUNDO UM DIA PASSARÁ,
A TERRA TREMERÁ,
CASAS, PEDRAS VÃO ROLAR,
MAS COM JESUS FIRME ESTAREI.

SEU SANGUE É ESTE FIO
E NELE VOU CONFIAR.
ESTAMOS PRONTOS, MARANATA!
ORA VEM, SENHOR JESUS! (2X)
/FINAL
ESTAMOS PRONTOS, MARANATA!
ORA VEM, SENHOR JESUS!
');
