INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a1118b9e-9580-4fe4-88fc-cf64927e7013', 'A minha alegria é crescer com o meu Senhor', 49, 'A.A.F.A.', 'Country', 'C', 'Crianças e Adolescentes', 'A MINHA ALEGRIA É CRESCER COM O MEU SENHOR!
SENHOR DA MINHA VIDA, O MEU GRANDE AMOR!
A TI EU RENDEREI TODA GLÓRIA E LOUVOR,
AQUI TRABALHAREI NA TUA OBRA COM AMOR.

USA-ME SENHOR, PRA PREGAR AO PECADOR,
USA-ME SENHOR, NA TUA OBRA DE AMOR.
USA-ME SENHOR, PRA MINHA CASA EDIFICAR,

USA-ME SENHOR, QUERO A TI GLORIFICAR!
USA-ME SENHOR, EM TODO E QUALQUER LUGAR,
USA-ME SENHOR, ATÉ MEU JESUS VOLTAR.
');
