INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a19ddd57-7147-431e-b309-a2652f7a9fe6', 'Jesus Cristo mudou meu viver', '120', 'Let. e Mús.: Autor Desconhecido; Trad. Joan Suttone', 'Básico', 'A', 'Dedicação', 'JESUS CRISTO MUDOU MEU VIVER, (2X)
É A LUZ QUE ILUMINA MEU SER,
SIM, JESUS CRISTO MUDOU MEU VIVER.

DIFERENTE HOJE É O MEU CORAÇÃO, (2X)
CRISTO DEU-ME PAZ E PERDÃO,
SIM, DIFERENTE HOJE É O MEU CORAÇÃO.

O AMOR QUE CONHECI EM CANÇÕES
ME FALAVA DE ILUSÕES;
HOJE TUDO É DIFERENTE,
ISSO FALO A TODA A GENTE,
QUE CRISTO SALVA O PECADOR.

FINAL
JESUS CRISTO MUDOU MEU VIVER, (2X)
É A LUZ QUE ILUMINA MEU SER,
SIM, JESUS CRISTO MUDOU MEU VIVER.
');
