INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a1ae7b5f-faa0-43ed-99c5-7d00d4a275b9', 'Na presença de Jesus', '789', 'Autor Desconhecido', 'Country', 'C', 'Corinhos', 'CANTAR 2X
NA PRESENÇA DE JESUS
NÃO HÁ DOR NEM PRANTO:
FICO CHEIO DE ALEGRIA,
CHEIO DO ESPÍRITO SANTO!

*CORO
CRISTO VEM NA SUA GLÓRIA;
QUERO IR TAMBÉM, QUERO IR TAMBÉM.
QUERO PERTENCER À GLÓRIA
QUE OS REMIDOS TEM.
QUERO SUBIR COM JESUS
PARA A MANSÃO DE ALÉM.
VOU MORAR NA GLÓRIA PARA SEMPRE, AMÉM.

CANTAR 2X
O DEVER DE TODO CRENTE
É VIGIAR E ORAR.
CRISTO VEM BUSCAR A IGREJA,
OLHA QUE TU VAIS FICAR.

*CORO
CRISTO VEM NA SUA GLÓRIA;
QUERO IR TAMBÉM, QUERO IR TAMBÉM.
QUERO PERTENCER À GLÓRIA
QUE OS REMIDOS TEM.
QUERO SUBIR COM JESUS
PARA A MANSÃO DE ALÉM.
VOU MORAR NA GLÓRIA PARA SEMPRE, AMÉM.

CANTAR 2X
TODO CRENTE QUE VIGIA
VIVE COM JESUS:
FICA CHEIO DE ALEGRIA
QUANDO MANIFESTA A LUZ.

*CORO
CRISTO VEM NA SUA GLÓRIA;
QUERO IR TAMBÉM, QUERO IR TAMBÉM.
QUERO PERTENCER À GLÓRIA
QUE OS REMIDOS TEM.
QUERO SUBIR COM JESUS
PARA A MANSÃO DE ALÉM.
VOU MORAR NA GLÓRIA PARA SEMPRE, AMÉM. (2X)
');
