INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a219217c-fff7-4366-8041-b48775ab12a5', 'O meu louvor é fruto', '604', 'Asaph Roque de Souza Borba', 'Básico', 'Dm', 'Louvor', '*CORO 2X
O MEU LOUVOR É FRUTO
DO MEU AMOR POR TI, JESUS,
DE LÁBIOS QUE CONFESSAM O TEU NOME;
É FRUTO DE TUA GRAÇA
E DA PAZ QUE ENCONTRO EM TI
E DO TEU ESPÍRITO QUE HABITA EM MIM,
QUE HABITA EM MIM.

AINDA QUE AS TREVAS VENHAM ME CERCAR,
AINDA QUE OS MONTES DESABEM SOBRE MIM,
MEUS LÁBIOS NÃO SE FECHARÃO,
PRA SEMPRE HEI DE TE LOUVAR!

*CORO
O MEU LOUVOR É FRUTO
DO MEU AMOR POR TI, JESUS,
DE LÁBIOS QUE CONFESSAM O TEU NOME;
É FRUTO DE TUA GRAÇA
E DA PAZ QUE ENCONTRO EM TI
E DO TEU ESPÍRITO QUE HABITA EM MIM,
QUE HABITA EM MIM.

AINDA QUE CADEIAS VENHAM ME PRENDER,
AINDA QUE OS HOMENS
SE LEVANTEM CONTRA MIM,
MEUS LÁBIOS NÃO SE FECHARÃO,
PRA SEMPRE HEI DE TE LOUVAR!

*CORO
O MEU LOUVOR É FRUTO
DO MEU AMOR POR TI, JESUS,
DE LÁBIOS QUE CONFESSAM O TEU NOME;
É FRUTO DE TUA GRAÇA
E DA PAZ QUE ENCONTRO EM TI
E DO TEU ESPÍRITO QUE HABITA EM MIM,
QUE HABITA EM MIM.
');
