INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a35e06a1-a6f5-4760-9ec8-1c2227efa9ac', 'É somente teu meu coração', '055', 'Cristina Manera Vianna', 'Básico 2', 'D', 'Crianças e Adolescentes', 'É SOMENTE TEU MEU CORAÇÃO, SENHOR,
É SOMENTE TEU MEU CORPO E MEU LOUVOR;
É SOMENTE TEU, MEU PAI, O MEU AMOR,
SOU SOMENTE TEU, MEU REDENTOR.

QUERO TE AMAR, MEU DEUS, Ó MEU SENHOR,
QUERO TE ADORAR, PRA SEMPRE, COM ARDOR;
QUERO A TI ORAR COM FÉ E COM FERVOR,
SOU SOMENTE TEU, MEU REDENTOR.
');
