INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a3812b37-cc11-408f-b2ad-776fcddfd63f', 'Quando a última trombeta ecoar', '515', 'Ednéia Aparecida Ranção Horst', 'Básico', 'A', 'Volta de Jesus e Eternidade', 'QUANDO A ÚLTIMA TROMBETA ECOAR
O MEU NOME OUVIREI JESUS CHAMAR,
REVESTIDO EM NOVO CORPO
ELE ME TRANSFORMARÁ,
PODEREI ENTÃO SEU ROSTO CONTEMPLAR.

*CORO
ALELUIA, ALELUIA, ALELUIA,
ELE ME TRANSFORMARÁ;
ALELUIA, ALELUIA,
PODEREI ENTÃO SEU ROSTO CONTEMPLAR.
/INSTRUMENTOS

QUANDO A ÚLTIMA TROMBETA ECOAR
O MEU NOME OUVIREI JESUS CHAMAR,
REVESTIDO EM NOVO CORPO
ELE ME TRANSFORMARÁ,
PODEREI ENTÃO SEU ROSTO CONTEMPLAR.

*CORO
ALELUIA, ALELUIA, ALELUIA,
ELE ME TRANSFORMARÁ;
ALELUIA, ALELUIA,
PODEREI ENTÃO SEU ROSTO CONTEMPLAR.
/FINAL
PODEREI ENTÃO SEU ROSTO CONTEMPLAR.
');
