INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a3b81206-d625-47f4-b714-5f703367d023', 'Cinco seixos', '150', 'C.M.V.C.S', 'Fox', 'F', 'Crianças e Adolescentes', 'CINCO SEIXOS DO RIBEIRO DAVI COLOCOU
EM SEU ALFORJE DE PASTOR
QUANDO GOLIAS FOI A ENFRENTAR.
SEM MEDO DAVI FOI LUTAR.

DAVI OROU, CONFIOU EM DEUS,
PARA ASSIM VENCER O FILISTEU.
EM SEU CORAÇÃO HAVIA O LOUVOR,
A PALAVRA, O JEJUM E A ORAÇÃO
E NA MADRUGADA, SEMPRE A DEUS BUSCAVA
DEIXANDO O SENHOR SUA VIDA DIRIGIR.

E QUANDO GOLIAS FOI ENCONTRAR
SÓ UMA PEDRA EM SUA FUNDA COLOCOU.
E MIROU, GIROU, LANÇOU
NA TESTA DO GIGANTE A PEDRA CRAVOU
(TRUMMMM)
O GIGANTE CAIU, DAVI FOI VENCEDOR.
NO NOME DO SENHOR, NO NOME DO SENHOR.
');
