INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a3da93b3-ff11-466f-98e3-b8440f1eec10', 'Jesus, Tu és o meu Deus', 39, 'Let: Sérgio Carlos de Souza; Mús. Emanoel Aleixo Júnior', 'Básico', 'Dm', 'Clamor', 'JESUS, TU ÉS O MEU DEUS,
A MINH''ALMA TEM SEDE DE TI, 
EU TE DESEJO, Ó DEUS,
NECESSITADO ESTOU.

NO TEU SANGUE HÁ RENOVO,
PODER PARA TRANSFORMAR,
PARA LIBERTAR E PERDOAR,
DERRAMA DESTE SANGUE EM MIM.

CANTAR 2X
E ASSIM TE BENDIREI
ENQUANTO EU VIVER,
EM TEU NOME FALAREI,
OS MEUS LÁBIOS TE LOUVARÃO.
/FINAL
ALELUIA, AMÉM. (2X)
');
