INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a3e6b4f8-99ee-4282-a608-9835f76ec7d7', 'Vinde após mim', '', '', '', '', '', 'VINDE A MIM OS OPRIMIDOS,
CANSADOS E AFLIGIDOS,
O MEU JUGO DIZ JESUS:
“É SUAVE E LEVE,
DE BONDADE E DE AMOR”.

*CORO
MINHAS MÃOS DE MISERICÓRDIA,
ESTÃO CHEIAS DE PODER,
A ESPERA DE ALGUÉM PARA AJUDAR.
O MEU REINO É DE PAZ,
DE JUSTIÇA E DE LUZ,
VENHA LOGO SEM DEMORA,
EU SOU JESUS.
/INSTRUMENTOS

VAMOS LOGO A JESUS,
VAMOS COM JESUS FALAR,
VAMOS A JESUS AMAR.

VINDE A MIM OS OPRIMIDOS,
CANSADOS E AFLIGIDOS,
O MEU JUGO DIZ JESUS:
“É SUAVE E LEVE,
DE BONDADE E DE AMOR”.

*CORO
MINHAS MÃOS DE MISERICÓRDIA,
ESTÃO CHEIAS DE PODER,
A ESPERA DE ALGUÉM PARA AJUDAR.
O MEU REINO É DE PAZ,
DE JUSTIÇA E DE LUZ,
VENHA LOGO SEM DEMORA,
EU SOU JESUS.

VAMOS LOGO A JESUS,
VAMOS COM JESUS FALAR,
VAMOS A JESUS AMAR,
VAMOS COM JESUS ANDAR,
VAMOS COM JESUS MORAR.
');
