INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a417da63-c20f-4e0c-a5d2-7928573d3c82', 'Oh que sangue poderoso', '040', 'Olcimar Rubens de Carvalho', 'Básico', 'C', 'Clamor', 'OH! QUE SANGUE PODEROSO!
OH! QUE SANGUE CHEIO DE VIRTUDE,
SANGUE QUE POR NÓS FOI DERRAMADO;
QUE NOS DÁ PLENO PERDÃO,
COMUNHÃO, TOTAL LIBERTAÇÃO,
ROMPENDO AS BARREIRAS DO PECADO.

CANTAR 2X
CLAMAMOS A TI, SENHOR,
PELO PODER QUE HÁ NO SANGUE DE JESUS
PARA PEDIR O TEU PERDÃO E TOTAL LIBERTAÇÃO.
/FINAL
E TOTAL LIBERTAÇÃO.
');
