INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a43a1c4f-4f1b-4e09-be7c-9e4645f85a5f', 'Regozijai-vos', '527', 'Olcimar Rubens de Carvalho', 'Básico', 'Em', 'Volta de Jesus e Eternidade', '(VARÕES)"REGOZIJAI-VOS, Ó MEUS AMADOS,
(VARÕES)ESPERAI UM POUCO MAIS,
(VARÕES)O MEU FILHO VIRÁ EM BREVE,
(VARÕES)SOBRE AS NUVENS ELE VIRÁ,
(VARÕES)JESUS VIRÁ!"

*CORO
DESPERTAI, (DESPERTAI)
Ó FILHOS DE SIÃO.
CONFIAI (CONFIAI)
NO DEUS DE ABRAÃO.
DEUS PROVERÁ, DEUS DE ISRAEL.
EXULTAI (EXULTAI)
NA VOSSA SALVAÇÃO, (SALVAÇÃO) 
POIS JESUS VIRÁ!
/INSTRUMENTOS

(VARÕES)"SANTIFICAI-VOS COMO EU SOU SANTO,
(VARÕES)RENOVAI VOSSAS CANDEIAS
(VARÕES)COM O ÓLEO DO MEU ESPÍRITO.
(VARÕES)PREPARAI-VOS, ELE VIRÁ,
(VARÕES)JESUS VIRÁ!"

*CORO 2X
DESPERTAI, (DESPERTAI)
Ó FILHOS DE SIÃO.
CONFIAI (CONFIAI)
NO DEUS DE ABRAÃO.
DEUS PROVERÁ, DEUS DE ISRAEL.
EXULTAI (EXULTAI)
NA VOSSA SALVAÇÃO, (SALVAÇÃO)
POIS JESUS VIRÁ!
/FINAL
POIS JESUS VIRÁ!
ELE VIRÁ, JESUS VIRÁ!
');
