INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a4d0d63d-4d6d-4f4a-b1b6-814e890317d7', 'Deus Enviou Seu Filho Amado', '207', 'Let.: William J. Gaither e Glória S. Gaither; Trad.: James F. Spam e Jaubas F. de Alencar; Mus: William J. Gaither', 'Fox', 'G', 'Morte, Ressureição e Salvação', 'DEUS ENVIOU SEU FILHO AMADO
PARA MORRER EM MEU LUGAR;
NA CRUZ SOFREU POR MEUS PECADOS,
MAS O SEPULCRO VAZIO ESTÁ
PORQUE ELE VIVE.

CORO
PORQUE ELE VIVE,
POSSO CRER NO AMANHÃ;
PORQUE ELE VIVE, TEMOR NÃO HÁ.
MAS EU BEM SEI (EU SEI)
QUE A MINHA VIDA
ESTÁ NAS MÃOS DO MEU JESUS,
QUE VIVO ESTÁ.

E QUANDO, ENFIM, CHEGAR A HORA
EM QUE A MORTE ENFRENTAREI;
SEM MEDO, ENTÃO, TEREI VITÓRIA,
VEREI NA GLÓRIA O MEU JESUS
QUE VIVO ESTÁ.
');
