INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a4e89411-7bdb-4836-abc4-1b8f80ea1296', 'Quantos Fieis, Senhor', '462', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'A', 'Santificação e Derramamento', 'QUANTOS FIÉIS, SENHOR,
MÁRTIRES E HERÓIS DA FÉ,
DERAM SUA VIDA, POR TUA VINHA,
TOMBARAM, MAS DE PÉ.

OUVIU-SE NAS ARENAS
SEU CANTO DE LOUVOR;
MAIS QUE AS FOGUEIRAS,
NELES ARDIA O AMOR DO SALVADOR.

CORO
GRAÇAS DOU POR TANTOS FIÉIS, SENHOR,
QUE FORAM MAIS FORTES DO QUE A MORTE
E NOS LEGARAM DA FÉ A HERANÇA.
FAZE DE NÓS VALENTES EM TUAS MÃOS
E AVIVA TUA OBRA, Ó DEUS, REVELA
O TEU PODER NESTA GERAÇÃO.

RAMOS DE MIRRA FOSTE
PRA TEUS FIÉIS, JESUS;
FAMÍLIA, AMIGOS, BENS, MESMO A VIDA,
TROCARAM PELA CRUZ;
NUVENS DE TESTEMUNHAS
QUE O CÉU VAI RECEBER
COM PALMAS DE OURO, COROA E GLÓRIA
A TODO QUE VENCER.
');
