INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a54774dc-c7ae-4161-8650-8dc62d2495fb', 'Atende, Senhor, a minha oração', 84, 'Antônio Lopes da Silva,', 'Valseado', 'C', 'Invocação e Comunhão', 'ATENDE, SENHOR, A MINHA ORAÇÃO,
A TI, LEVANTO AS MINHAS MÃOS;
A MINHA ALMA ANSEIA POR TI,
DÁ-TE PRESSA EM ME SOCORRER.

CANTAR 2X
FAZE-ME OUVIR NA MANHÃ, DA TUA GRAÇA,
ENSINA-ME A FAZER A TUA VONTADE,
POIS EU SOU TEU E TU ÉS MEU,
EM TI CONFIO, SENHOR.

FINAL
POIS EU SOU TEU E TU ÉS MEU,
EM TI CONFIO, SENHOR. (3X)
');
