INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a60a012d-a1b1-401e-b151-b577f8928dc9', 'Senhor, eu nem sei contar', '579', 'Luciana Monteiro Carneiro Simora', 'Básico', 'G', 'Louvor', 'SENHOR, EU NEM SEI CONTAR
AS GRANDES BÊNÇÃOS
QUE TENS DADO AO MEU CORAÇÃO,
POIS O TEU AMOR ME FAZ TÃO FELIZ
E A TUA GRAÇA ME SATISFAZ,

CANTAR 2X
EM SABER QUE A CADA MANHÃ
EU POSSO SENTIR JESUS 
TÃO PERTO DE MIM.

*CORO
EU QUERO AGRADECER AO MEU SENHOR,
EU QUERO AGRADECER POR SEU AMOR,
QUE ME FAZ SER VENCEDOR E ME FAZ FELIZ,
QUE ME FAZ SER UM SERVO DO SENHOR.
/INSTRUMENTOS

TÃO PERTO DE MIM...
/*CORO
EU QUERO AGRADECER AO MEU SENHOR,
EU QUERO AGRADECER POR SEU AMOR,
QUE ME FAZ SER VENCEDOR E ME FAZ FELIZ,
QUE ME FAZ SER UM SERVO DO SENHOR,
/FINAL
QUE ME FAZ SER UM SERVO DO SENHOR.
');
