INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a67287f2-6f88-4243-89ed-c32ca9cc0843', 'Diante do teu altar', 8, 'J.J.G.', 'Básico', 'G', 'Crianças e Adolescentes', 'DIANTE DO TEU ALTAR, SENHOR,
