INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a6ad2973-7ddc-4aae-a5d7-dc00bbfdff17', 'A Esperança', '', '', '', 'C', '', 'DOCE ESPERANÇA, (2X)
BENDITA LUZ DO SENHOR,
POR ISSO LHE DAMOS LOUVOR,
VIRTUDE INSPIRADORA
VICEJAS POR ENTRE ESPINHOS.

A TUA FONTE É A CRUZ,
ONDE EXPIROU JESUS,
MORREU JESUS,
MAS RESSURGIU, AMÉM.
QUEBRANDO OS DUROS
GRILHÕES DO MAL.

LOUVOR E GLÓRIA A JESUS SENHOR,
MAS RESSURGIU, AMÉM,
QUEBRANDO OS DUROS
GRILHÕES DO MAL,
LOUVOR E GLÓRIA A JESUS, SENHOR.

DOCE ESPERANÇA, (2X)
TEU TERNO ENCANTO ME
CONDUZ, DA VIDA AO FIM,
TU ÉS A LUZ DO SENHOR,
POR ISSO LHE DAMOS LOUVOR.

NADA RECEIO, NADA RECEIO,
PORQUE É JESUS O BOM PASTOR
QUE ME CONDUZ,
QUE ME CONDUZ,
O BOM PASTOR QUE ME CONDUZ,
MEU SALVADOR QUE ME CONDUZ
PARA A GLÓRIA.

NADA RECEIO, NADA RECEIO,
POR QUE É JESUS O BOM PASTOR
QUE ME CONDUZ,
QUE ME CONDUZ.
MEU SALVADOR EU SEMPRE TE LOUVAREI,
DOCE ESPERANÇA, (2X)
');
