INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a6c82644-19c6-4b66-870b-977a3ebee082', 'Abra a Porta, Venha Ver', '773', '', 'Marcha', 'F', 'Corinhos', 'ABRA A PORTA, VENHA VER
OS MENSAGEIROS DO SENHOR
QUE ANUNCIAM A PALAVRA,
DE DEUS E SEU AMOR!

ABRA A PORTA E TAMBÉM O CORAÇÃO
PORQUE ENTRE NÓS ESTÁ JESUS
QUE OUTORGA A SALVAÇÃO
GLÓRIA A JESUS!

ABRA A PORTA, VENHA VER
OS MENSAGEIROS DO SENHOR
QUE ANUNCIAM A PALAVRA,
DE DEUS E SEU AMOR!

FINAL
ABRA A PORTA E TAMBÉM O CORAÇÃO
PORQUE ENTRE NÓS ESTÁ JESUS
QUE OUTORGA A SALVAÇÃO
GLÓRIA A JESUS!
');
