INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a6d93cf0-56aa-40ab-9148-b5d1823a98c9', 'Quem Beber da Água que Eu lhe Der', '232', 'Ronaldo Duarte Barroso', 'Básico', 'A', 'Morte, Ressureição e Salvação', 'CANTAR 2X
"QUEM BEBER DA ÁGUA
QUE EU LHE DER,
JAMAIS TERÁ SEDE DE NOVO,
POIS A ÁGUA QUE EU LHE DER
SE FARÁ UMA FONTE PRA VIDA ETERNA."

O SENHOR ESTÁ JUNTO A TI,
PODEROSO PARA TE SALVAR,
SE HOJE OUVIRES SUA DOCE VOZ,
NÃO ENDUREÇAS O TEU CORAÇÃO,
NÃO DIGAS NÃO.

"MAS VEM A MIM,
Ó TU QUE ESTÁS CANSADO,
E DESCANSO EU TE DAREI,
/FINAL 2X
POIS A ÁGUA QUE EU TE DER
SE FARÁ UMA FONTE PRA VIDA ETERNA."
');
