INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a6fddf59-5405-4291-976f-e7a224be436f', 'Eu Confio Em Ti', '', '', '', '', '', 'EU CONFIO EM TI, SENHOR MESMO QUANDO TUDO
NÃO VAI BEM E A ESPERANÇA FUGIR EU OLHAREI
SÓ PRA TI ACALMA O MEU CORAÇÃO
SEGURA A MINHA MÃO E ME FAZ UM VENCEDOR,
SIM, ME FAZ UM VENCEDOR.

PORQUE NUNCA SE OUVIU E NUNCA SE VIU
UM DEUS ALÉM DE TI E EU APRENDI A CONFIAR
NO DEUS PROVEDOR QUE NÃO FALHARÁ.

*CORO
ROCHA INABALÁVEL,
MEU AMIGO E BOM PASTOR
SOCORRO BEM PRESENTE,
MESMO NA TRISTEZA E DOR
EU CONFIO EM TI, SENHOR
EU CONFIO EM TI, SENHOR
JESUS.

EU CONFIO EM TI SENHOR, MEU CAMINHO
PONHO EM TEU ALTAR TUA VOZ EU QUERO OUVIR,
TUA PRESENÇA, SIM, QUERO SENTIR.
ENSINA-ME A CAMINHAR E A TI HONRAR, SENHOR,
E ME FAZ UM VENCEDOR,
SIM, ME FAZ UM VENCEDOR.

PORQUE NUNCA SE OUVIU E NUNCA SE VIU
UM DEUS ALÉM DE TI E EU APRENDI A CONFIAR
NO DEUS PROVEDOR QUE NÃO FALHARÁ.

*CORO
ROCHA INABALÁVEL,
MEU AMIGO E BOM PASTOR
SOCORRO BEM PRESENTE,
MESMO NA TRISTEZA E DOR
EU CONFIO EM TI, SENHOR
EU CONFIO EM TI, SENHOR
JESUS.

ACALMA O MEU CORAÇÃO
SEGURA A MINHA MÃO
E ME FAZ UM VENCEDOR
SIM, ME FAZ UM VENCEDOR.

*CORO
ROCHA INABALÁVEL,
MEU AMIGO E BOM PASTOR
SOCORRO BEM PRESENTE,
MESMO NA TRISTEZA E DOR
EU CONFIO EM TI, SENHOR
EU CONFIO EM TI, SENHOR
JESUS.
');
