INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a74ef4c9-2eff-4905-8590-ee96fc744280', 'Em teu altar senhor', '014', 'Paulo Emanuel dos Santos Teixeira', 'Básico', 'D', 'Clamor', 'CANTAR 2X
EM TEU ALTAR, SENHOR, 
ENTREGO A MINHA VIDA,
EM TEU ALTAR, SENHOR, 
