INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a75abcbe-60f7-468d-abb1-9292bfd6729a', 'Nos prostemos', '580', 'José Elias Simora', 'Básico', 'C', 'Louvor', 'CANTAR 2X
NOS PROSTREMOS AOS SEUS PÉS
ADORANDO A JESUS,
EXALTANDO A SUA GLÓRIA E MAJESTADE.

*CORO
COROAI A JESUS
MINISTRANDO O SEU LOUVOR EM SUA CASA,
COROAI A JESUS
BENDIZENDO E LOUVANDO O SEU NOME.
/INSTRUMENTOS

CANTAR 2X
ENTRONIZADO ESTÁS ENTRE OS LOUVORES,
ASSENTADO NO TEU TRONO,
E TODOS OS ANJOS DE DEUS TE ADORANDO.

*CORO 2X
COROAI A JESUS
MINISTRANDO O SEU LOUVOR EM SUA CASA,
COROAI A JESUS
BENDIZENDO E LOUVANDO O SEU NOME.

FINAL 2X
(O SEU NOME)
BENDIZENDO E LOUVANDO
O SEU NOME.
');
