INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a77b2161-1a62-49d2-ae9b-78a72767a47a', 'Digo Ao Senhor', '', '', '', '', '', 'DIGO AO SENHOR: TU ÉS O MEU
SENHOR, OUTRO BEM NÃO POSSUO
SENÃO A TI SOMENTE;
TU ÉS A PORÇÃO DA MINHA
HERANÇA, DO MEU CÁLICE,
CAEM-ME AS DIVISAS
EM LUGARES AMENOS,
É TÃO LINDA! É TÃO LINDA!
A MINHA HERANÇA.

CANTAR 2X
DIGO AO SENHOR
TU ÉS O MEU SENHOR
OUTRO BEM NÃO POSSUO
SENÃO A TI SOMENTE

TU ÉS A PORÇÃO DA MINHA
HERANÇA, DO MEU CÁLICE,
CAEM-ME AS DIVISAS
EM LUGARES AMENOS.
É TÃO LINDA! É TÃO LINDA!
A MINHA HERANÇA.
/FINAL
É TÃO LINDA! É TÃO LINDA!
A MINHA HERANÇA.
');
