INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a7f11ed8-01c5-40ef-ad4d-ede98d089f56', 'Se Tu Procuras Pela Paz', '250', 'Autor Desconhecido', 'Fox Abafado', 'E', 'Morte, Ressureição e Salvação', 'SE TU PROCURAS PELA PAZ,
SE VAZIO ESTÁ TEU SER;
NUNCA O MUNDO BUSCARÁS,
MAS DEVES A JESUS TEMER.
SE PROCURARES MAIS A CRISTO,
SÓ VERDADE ENCONTRARÁS,
POIS SÓ MEU CRISTO A ALMA SATISFAZ.

*CORO
CRISTO SATISFAZ,
SÓ CRISTO A ALMA SATISFAZ,
E ELE PODE COMPLETAR TEU CORAÇÃO.
DARÁ A PAZ, TÃO DOCE AMOR;
ENFIM NOS CÉUS HABITARÁS,
POIS SÓ MEU CRISTO A ALMA SATISFAZ.

SE FAMA E BENS ALMEJAS TER,
TÃO EM VÃO É O TEU VIVER,
POIS A CRISTO NÃO TERÁS,
A REDENÇÃO SÓ ELE DÁ.
JAMAIS EM BENS CONFIARÁS,
SALVAÇÃO ALI NÃO HÁ,
POIS SÓ MEU CRISTO A ALMA SATISFAZ.

*CORO
CRISTO SATISFAZ,
SÓ CRISTO A ALMA SATISFAZ,
E ELE PODE COMPLETAR TEU CORAÇÃO.
DARÁ A PAZ, TÃO DOCE AMOR;
ENFIM NOS CÉUS HABITARÁS,
POIS SÓ MEU CRISTO A ALMA SATISFAZ.
/FINAL
CRISTO SATISFAZ!
');
