INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a912ad40-3ecc-40ac-bd9e-1518ed1eaf8a', 'Tudo, ó Cristo, a ti entrego', '121', 'Let.: Judson W. Van de Venter; Trad. Salomão Luiz Ginsburg; Mús.: Winfield Scott Weeden', 'Básico', 'D', 'Dedicação', 'TUDO, Ó CRISTO, A TI ENTREGO,
TUDO, SIM, POR TI DAREI;
RESOLUTO, MAS SUBMISSO,
SEMPRE, SEMPRE SEGUIREI.

CORO
TUDO ENTREGAREI, TUDO ENTREGAREI;
SIM, POR TI, JESUS
BENDITO, TUDO DEIXAREI.

TUDO, Ó CRISTO, A TI ENTREGO,
CORPO E ALMA, EIS-ME AQUI;
ESTE MUNDO MAU RENEGO,
Ó JESUS, ACEITA A MIM.

TUDO, Ó CRISTO, A TI ENTREGO,
OH! QUE GOZO MEU SENHOR!
PAZ PERFEITA, PAZ COMPLETA,
GLÓRIA, GLÓRIA AO SALVADOR.
');
