INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('a9e25db0-bbe4-45ff-8b01-f22022d9b36b', 'Eu vi o Senhor', '407', 'Gérson Beluci Miguel', 'Básico', 'A', 'Santificação e Derramamento', 'EU VI O SENHOR NUM ALTO E SUBLIME TRONO
E AS ABAS DE SUAS VESTES ENCHIAM O TEMPLO;
OS ANJOS VOAVAM POR SOBRE O SEU TRONO,
COBRIAM O ROSTO E OS PÉS,
UNS AOS OUTROS CLAMAVAM:

*CORO 2X
SANTO, SANTO, SANTO,
É O SENHOR DOS EXÉRCITOS,
TODA A TERRA ESTÁ CHEIA DA SUA GLÓRIA!
/INSTRUMENTOS

ENTÃO DISSE EU: SOU UM HOMEM IMPURO
E OS MEUS OLHOS VIRAM O REI,
O SENHOR DOS EXÉRCITOS!
COM UMA BRASA DO ALTAR 
OS MEUS LÁBIOS FORAM TOCADOS,
MEU PECADO FOI PERDOADO 
E OUVI A VOZ DO SENHOR:

CANTAR 2X
"A QUEM ENVIAREI,
E QUEM HÁ DE IR POR NÓS?"
DISSE EU: EIS-ME AQUI,
ENVIA- ME A MIM.

*CORO 2X
SANTO, SANTO, SANTO,
É O SENHOR DOS EXÉRCITOS,
TODA A TERRA ESTÁ CHEIA DA SUA GLÓRIA!
');
