INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('aa970a9b-664a-4382-88b6-2157c8b023fa', 'Desejado Das Nações', '', '', '', '', '', 'DESEJADO DAS NAÇÕES, ESPERANÇA
DE ISRAEL, Ó AMADO DA IGREJA FIEL
TE AGUARDAMOS, TE ESPERAMOS
REI DE DIVINA LUZ, E CLAMAMOS:
“ORA VEM, SENHOR JESUS!”

CORO
“VEM! VEM! VEM!
SIM, VEM JESUS!”
O ESPÍRITO E A ESPOSA DIZEM VEM
“VEM! VEM! VEM! AMADO VEM!”
MAJESTOSO, GLORIOSO,
REI JESUS.

DENSAS TREVAS EM REDOR
MAS EM NÓS BRILHA TUA LUZ.
NOSSA MARCA É O SANGUE DE JESUS.
BEM CINGIDOS E CALÇADOS
PREPARADOS PRA PARTIR,
AGUARDAMOS NOSSO REI
QUE HÁ DE VIR.
');
