INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ab31df15-59b6-41e9-abc2-b655423ac14b', 'A minhalma estava longe do caminho do céu', '103', 'G. E. Wright', 'Guarânia', 'A', 'Dedicação', 'A MINH''ALMA ESTAVA LONGE
DO CAMINHO DO CÉU,
EU ERA POBRE, DESPREZÍVEL PECADOR;
MAS JESUS JÁ TRANSFORMOU
MINHAS TREVAS EM LUZ,
QUANDO ESTENDEU A SUA MÃO PARA MIM.

CORO
QUANDO JESUS ESTENDEU A SUA MÃO,
QUANDO ESTENDEU A SUA MÃO PARA MIM,
EU ERA POBRE, PERDIDO,
SEM DEUS, SEM JESUS,
QUANDO ESTENDEU A SUA MÃO PARA MIM.

AGORA ME REGOZIJO DESDE QUE O ACEITEI, 
E NA TEMPESTADE EU POSSO SOSSEGAR,
POIS COM ELE ESTOU LIBERTO
DO PERIGO E DO MAL,
DESDE QUE ESTENDEU
A SUA MÃO PARA MIM.
');
