INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ab918b49-8555-41b5-b383-d38655692850', 'Só uma voz me basta', '311', 'Cláudia Mara Santiago Zoreain', 'Básico', 'G', 'Consolo e Encorajamento', 'SÓ UMA VOZ ME BASTA
