INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ab952c91-770a-48e5-b2ec-7108dda75f72', 'A paz que tu procuras', '', 'Fábio Henrique Barros Ramos, Márcia Castro de Freitas', 'Básico', 'G', 'Morte, Ressureição e Salvação', 'A PAZ QUE TU PROCURAS,
A ALEGRIA QUE ALMEJAS
HOJE PODES ENCONTRAR,
AQUELE QUE POR TI MORREU
HOJE AQUI ESTÁ E QUER TE SALVAR.

*CORO
LOUVAI A JESUS
E JUNTOS EXALTEMOS O SEU NOME,
PROCLAMAI, (MARANATA!)
PROCLAMAI: ELE VOLTARÁ!
/INSTRUMENTOS

ELE ESTÁ A TE CONTEMPLAR
E COM SUA DOCE VOZ IRÁ FALAR
AO TEU CORAÇÃO:
"VEM, FILHO MEU, RECEBE A VIDA
QUE ESTAVAS A PROCURAR."

*CORO 2X
LOUVAI A JESUS
E JUNTOS EXALTEMOS O SEU NOME,
PROCLAMAI, (MARANATA!)
PROCLAMAI: ELE VOLTARÁ!
/FINAL
PROCLAMAI, (MARANATA!),
PROCLAMAI: ELE VOLTARÁ!
');
