INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ab997279-5b64-4290-9cd6-7f260323cfb2', 'Na cidade de Davi nasceu o Salvador', '233', 'E.H.M.R.', 'Fox', 'A', 'Crianças e Adolescentes', 'NA CIDADE DE DAVI NASCEU O SALVADOR,
CRISTO, O SENHOR;
MULTIDÕES DE ANJOS
LOUVARAM A DEUS DIZENDO:

*CORO 2X
GLÓRIA A DEUS NAS ALTURAS,
PAZ NA TERRA,
BOA VONTADE PARA COM OS HOMENS.

JESUS NASCEU NUM LUGAR TÃO SIMPLES,
FOI NO MEU CORAÇÃO;
ACHOU LUGAR PRA NASCER EM MIM
POIS ABRI MEU CORAÇÃO
E AGORA O SIRVO, SIRVO, SIM.

FINAL 2X
GLÓRIA A DEUS NAS ALTURAS,
PAZ NA TERRA,
BOA VONTADE PARA COM OS HOMENS.
');
