INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ac840d42-e7ee-4722-95e2-32f907890f84', 'Jerusalém, Jerusalém', '531', 'Lídia de Souza e Silva', 'Marcha', 'A', 'Volta de Jesus e Eternidade', 'JERUSALÉM, JERUSALÉM,
DO POVO SANTO DO SENHOR,
COM FÉ UM DIA LÁ ESTAREI
RENDENDO GLÓRIA AO MEU SALVADOR.

CORO
ALELUIA, GLÓRIA A DEUS,
ALELUIA, AMÉM, AMÉM,
COM OS ANJOS CANTAREI TODO O LOUVOR;
ALELUIA, GLÓRIA A DEUS,
ALELUIA, AMÉM, AMÉM,
JERUSALÉM DO POVO DO SENHOR.

JERUSALÉM, CIDADE SANTA,
ILUMINADA COM A GLÓRIA DE DEUS,
EM SUAS RUAS EU ANDAREI
COM O CORDEIRO E OS REMIDOS SEUS.
');
