INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ac92b8bd-3594-490c-91ad-6f4958cc03f5', 'Pela fé eu caminho', '125', 'Paulo José Ferreira Marques', 'Balada', 'C', 'Dedicação', 'PELA FÉ EU CAMINHO
OLHANDO SÓ PRA JESUS,
MINHA MÃO PUS NA SUA
E ASSIM SEGURO VOU.

FINAL 2X
COMO A LUZ DA AURORA, MINHA VEREDA
VAI BRILHANDO MAIS E MAIS,
ATÉ O DIA, DIA PERFEITO, CHEGAR.
');
