INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ad01d861-d5d9-4ed2-ab83-5f42dfa3a477', 'Bem sei que tudo podes', '384', 'Jó 42', 'Básico', 'Bm', 'Consolo e Encorajamento', 'BEM SEI QUE TUDO PODES, MEU AMADO.
NENHUM DOS TEUS PLANOS É FRUSTRADO.
AINDA QUE COM PERDAS E COM DOR
EU SEMPRE SEGUIREI A TI, SENHOR.

OS TEUS CAMINHOS POSSO
NÃO ENTENDER, SENHOR,
MAS SEI QUE TUDO
É VISANDO O MEU CRESCER.
SE LUTAS E TRIBULAÇÕES
EU TENHO QUE PASSAR,
TE PEÇO FORÇAS PRA CONTINUAR.

CONTINUAR A CRER E A CONFIAR,
NO GRANDE AMOR QUE TENS, 
MEU PAI, POR MIM.
O MEU DESEJO ETERNO É TE ADORAR,
E AOS TEUS PÉS ME DERRAMAR SEM FIM.

BEM SEI QUE TUDO PODES, MEU AMADO.
NENHUM DOS TEUS PLANOS É FRUSTRADO.
AINDA QUE COM PERDAS E COM DOR
EU SEMPRE SEGUIREI A TI, SENHOR.

OS TEUS CAMINHOS POSSO
NÃO ENTENDER, SENHOR,
MAS SEI QUE TUDO
É VISANDO O MEU CRESCER.
SE LUTAS E TRIBULAÇÕES
EU TENHO QUE PASSAR,
TE PEÇO FORÇAS PRA CONTINUAR.

CONTINUAR A CRER E A CONFIAR,
NO GRANDE AMOR QUE TENS, 
MEU PAI, POR MIM.
O MEU DESEJO ETERNO É TE ADORAR,
E AOS TEUS PÉS ME DERRAMAR SEM FIM.
/FINAL
E AOS TEUS PÉS ME DERRAMAR SEM FIM.
');
