INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ad0eac92-a49d-4bc5-82f8-1d7795a87130', 'Amo ao Senhor porque Ele me ouviu', '122', 'Mariana Martins Barros', 'Básico', 'A', 'Dedicação', 'AMO AO SENHOR PORQUE ELE ME OUVIU,
INCLINOU OS SEUS OUVIDOS
E ASSIM ME ATENDEU;
O SENHOR, QUE É JUSTO E PIEDOSO,
POSSO NELE CONFIAR, CERTAMENTE ME GUIARÁ.

FINAL 2X
ANDAREI PERANTE A SUA FACE,
SOU SEU SERVO, POIS ME LIBERTOU;
LOUVÁ-LO-EI ETERNAMENTE
NOS ÁTRIOS DA SUA CASA,
FAREI A DEUS SACRIFÍCIOS DE LOUVOR.
');
