INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ad3ce117-5366-420e-b23a-ea2058597f8e', 'Quero que me toques, Senhor', '452', 'Nívea Maria de Oliveira Costa', 'Básico', 'G', 'Santificação e Derramamento', 'CANTAR 2X
QUERO QUE ME TOQUES, SENHOR,
COM O TOQUE DO TEU SANTO ESPÍRITO.

*CORO
EIS-ME AQUI, SENHOR (2X)
FALA-ME, SENHOR, USA-ME, SENHOR.

QUERO QUE ME FALES, SENHOR,
O QUE DEVO FAZER PRA TUA OBRA REALIZAR.
ESTOU PRONTO A TE OUVIR
VEM, SENHOR JESUS, MINHA VIDA USAR.

*CORO 2X
EIS-ME AQUI, SENHOR (2X)
FALA-ME, SENHOR, USA-ME, SENHOR.
/FINAL
ESTOU PRONTO A TE OUVIR
VEM, SENHOR JESUS, MINHA VIDA USAR.
');
