INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('aeab0670-2839-4ded-be79-d94f7e20f33e', 'Existe Um Lar', '522', 'Raquel Toscano de Freitas', 'Básico', 'C', 'Volta de Jesus e Eternidade', 'EXISTE UM LAR
QUE COM GRANDE AMOR FOI PREPARADO,
DELE DESFRUTARÁ TODO AQUELE
QUE A JESUS SE ENTREGOU.

