INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('af4a335f-bb24-4e46-abf0-94e2007f0cd1', 'O Rei Da Glória', '', '', '', '', '', 'O REI DA GLÓRIA, O REI DOS REIS,
SENHOR DOS SENHORES,
SOBERANO DEUS É JESUS,
É JESUS, É JESUS!
DESCEU DA GLÓRIA, E HOMEM
SE FEZ, VARÃO DE DORES,
SERVO SOFREDOR;
PADECEU, SIM, JESUS PADECEU.

SIM, CRISTO ENTREGOU SUA VIDA,
DE FORMA ESPOTÂNEA ELE FEZ.
NINGUÉM PODERIA OBRIGÁ-LO,
FOI SEU PRÓPRIO AMOR QUE O MOVEU.

POR ISSO REINA ACIMA DOS CÉUS,
E TEM O NOME CAPAZ DE NOS SALVAR.
É JESUS, SÓ JESUS, SÓ JESUS!
VIRÁ EM BREVE, O REI DOS REIS
VESTIDO EM GLÓRIA,
COM TODO O SEU PODER.
VOLTARÁ, MEU JESUS, VOLTARÁ!
');
