INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('afa4f963-638c-4416-9969-2651e48a048c', 'Quando Mais Ninguém Te Compreende', '369', 'Olcimar Rubens de Carvalho', 'Básico', 'G', 'Consolo e Encorajamento', 'QUANDO MAIS NINGUÉM TE COMPREENDE,
TEUS AMIGOS TE ABANDONARAM,
JESUS TE ABRAÇA E DIZ:
"ESTOU AQUI PRA TE OUVIR".

*CORO
"FALA, FILHO MEU,
CONTA PARA MIM OS TEUS PROBLEMAS,
CLAMA A MIM EM ORAÇÃO, COM SINCERIDADE
E RESPONDER-TE-EI.
FALAREI CONTIGO, SOU O DEUS DA PROVISÃO,
SOU JESUS, A TUA SOLUÇÃO".
/INSTRUMENTOS

"QUANDO INVOCARES O MEU NOME,
DE MADRUGADA ME BUSCARES
E DE JOELHOS TU ORARES, 
ESTAREI ATENTO A TE OUVIR."

*CORO 2X
"FALA, FILHO MEU,
CONTA PARA MIM OS TEUS PROBLEMAS,
CLAMA A MIM EM ORAÇÃO, COM SINCERIDADE
E RESPONDER-TE-EI.
FALAREI CONTIGO, SOU O DEUS DA PROVISÃO,
SOU JESUS, A TUA SOLUÇÃO".
/FINAL
"SOU JESUS, A TUA SOLUÇÃO".
');
