INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b0724d02-b3ea-4880-897c-53f3209355e5', 'Se Tu Pediste um Sinal', '270', 'Paulo Teixeira Martins', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'CORO
SE TU PEDISTE UM SINAL,
DEUS OUVIU TUA VOZ
E TE TROUXE AQUI PARA ABENÇOAR.
SE TUA VIDA É VAZIA, DEUS PODE MUDAR
ELE TE TROUXE AQUI PARA ABENÇOAR.

ENTREGA A TUA VIDA A JESUS
E A SALVAÇÃO TERÁS;
ELE DIZ: "EU SOU O SENHOR,
O REI DOS REIS,
O REI DAS NAÇÕES".
/INSTRUMENTOS

FINAL
ENTREGA A TUA VIDA A JESUS,
ELE VAI TE TRANSFORMAR.
ELE DIZ: "EU SOU O SENHOR,
O REI DOS REIS, O REI DAS NAÇÕES".
ELE DIZ: "EU SOU O SENHOR,
O REI DOS REIS, O REI DAS NAÇÕES".
');
