INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b0895d70-16ac-4aa8-85a5-67f86eea4cda', 'Vozes Lindas Coro Celestial', '051', '', '', '', '', 'VOZES LINDAS NUNCA OUVIDAS,
VEM DESCENDO DAS ALTURAS,
ONDE OS ANJOS CANTAM GLÓRIA,
AO NOSSO CRIADOR.

HARMONIAS SANTAS VIBRAM NOS RENCANTOS,
DAS CELESTIAIS MANSÕES,
E NA TERRA ECÔA, COM DULÇOR IMENSO,
ESSE CORO CELESTIAL.

VOZES LINDAS NUNCA OUVIDAS,
VEM DESCENDO DAS ALTURAS,
ONDE OS ANJOS CANTAM GLÓRIA,
AO NOSSO CRIADOR.

HARMONIAS SANTAS VIBRAM NOS RENCANTOS,
DAS CELESTIAIS MANSÕES,
E NA TERRA ECÔA, COM DULÇOR IMENSO,
ESSE CORO CELESTIAL.

DEUS OFERECE AO PECADOR,
POR MEIO DO SEU FILHO,
SALVAÇÃO DE GRAÇA, NUNCA MERECIDA,
CRISTO PELA CRUZ VIDA ETERNA TRAZ,
GLÓRIA A DEUS PELA REDENÇÃO DO PECADOR,
GLÓRIA A DEUS PORQUE REUNIU
OS FILHOS SEUS.

GRANDES FORAM AS TRANSGRESSÕES,
COMETIDAS PELO PECADOR,
SÓ O AMOR DO BONDOSO DEUS,
PODE AS CULPAS NOS RELEVAR,
PERDOADOS E ARREPENDIDOS,
LIBERTADOS, POIS, DE TODO MAL,
PERTO DE JESUS, NOSSO SALVADOR,
GOZAREMOS DOCE PAZ.

PORTANTO A DEUS SEJAMOS GRATOS,
O SEU AMADO FILHO HONREMOS,
DANDO AO SANTO ESPÍRITO LOUVOR,
ETERNAMENTE AMÉM!
GLÓRIA, GLÓRIA A DEUS,

DANDO AO SANTO ESPÍRITO LOUVOR,
ETERNAMENTE AMÉM! GLÓRIA, GLÓRIA A
DEUS! ETERNAMENTE AMÉM!
GLÓRIA A DEUS!
AMÉM! AMÉM! AMÉM! AMÉM! AMÉM!
');
