INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b08bc611-c0c0-4eca-bee9-0fef51cdd355', 'Cantai alegremente a Deus', '229', 'R.T.F.', 'Fox Abafado', 'C', 'Crianças e Adolescentes', 'CANTAI ALEGREMENTE A DEUS,
CANTAI ALEGREMENTE A DEUS,
CANTAI ALEGREMENTE A DEUS,
CANTAI, CANTAI ALEGREMENTE A DEUS.

TOMAI O SALTÉRIO, O ADUFE,
A HARPA E O ALAÚDE,
TOCAI A TROMBETA,
É HORA DE SOLENIDADE.

CANTAI ALEGREMENTE A DEUS,
CANTAI ALEGREMENTE A DEUS,
CANTAI ALEGREMENTE A DEUS,
CANTAI, CANTAI ALEGREMENTE A DEUS.
');
