INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b0995ded-2234-4b59-a906-a33c8bc77270', 'Salvo de Graça', '', '', '', '', '', 'SALVOS DE GRAÇA POR JESUS,
VIVO FELIZ NA SUA LUZ.
SEI QUE POR MINHA SALVAÇÃO,
ELE PAGOU A REMISSÃO.

CORO
QUERO COM CRISTO SEMPRE ANDAR,
GRATO LOUVOR A DEUS CANTAR.
CRISTO É O AMIGO SEM IGUAL,
GUIA-ME AO LAR CELESTIAL.

QUANTO ME AGRADA A DEUS SERVIR,
HOJE NA LUTA OU NO PORVIR.
SEU EVANGELHO VIDA TRAZ,
GOZO PERFEITO E SANTA PAZ.

QUERO SEGUIR MEU SALVADOR,
SEMPRE LOUVAR O SEU AMOR.
QUANDO O LABOR AQUI FINDAR,
VOU COM JESUS NO CÉU MORAR.
');
