INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b0b08396-94ff-4716-90bf-dfa4399f2333', 'Na areia não quero construir (Firme, sim!)', 39, 'S.G.D.', 'Fox', 'B', 'Crianças e Adolescentes', 'NA AREIA NÃO QUERO CONSTRUIR,
SEI MUITO BEM, A CASA VAI CAIR;
MINHA BÍBLIA JÁ ME DIZ:
É NA ROCHA QUE DEVO CONSTRUIR.

CORO
FIRME, SIM! FIRME, SIM!
MINHA CASA FIRME ESTÁ.
NÃO NA AREIA, SIM NA ROCHA,
E JESUS VAI SUSTENTAR;
FIRME, SIM! FIRME, SIM!
MINHA CASA FIRME ESTÁ.

EM JESUS, ROCHA ETERNA,
MINHA CASA FIRME ESTÁ;
NEM A CHUVA, VENTO OU MAR,
MINHA CASA VAI DERRUBAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('b0b08396-94ff-4716-90bf-dfa4399f2333', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
