INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b11ca4cf-991c-4d03-b191-f6930109981f', 'Vem Maranata, Jesus Vem', '553', 'Jorgemar Souza Madeira', 'Básico', 'G', 'Volta de Jesus e Eternidade', 'VEM! MARANATA! JESUS VEM!
ESTE DIA CHEGARÁ, SUA IGREJA SUBIRÁ.
VAMOS MORAR NA CIDADE ETERNAL,
NA NOVA JERUSALÉM,
ONDE AS RUAS SÃO DE OURO.

LÁ VAMOS CANTAR, 
VAMOS LOUVAR A JESUS CRISTO.
LÁ VAMOS CANTAR,
VAMOS LOUVAR (SÓ ELE É DIGNO)
JUNTOS COM OS ANJOS NO CÉU.

VEM! MARANATA! JESUS VEM!
ESTE DIA CHEGARÁ, SUA IGREJA SUBIRÁ.
VAMOS MORAR NA CIDADE ETERNAL,
NA NOVA JERUSALÉM,
ONDE AS RUAS SÃO DE OURO.

LÁ VAMOS CANTAR, 
VAMOS LOUVAR A JESUS CRISTO.
LÁ VAMOS CANTAR,
VAMOS LOUVAR (SÓ ELE É DIGNO)
JUNTOS COM OS ANJOS NO CÉU.
/FINAL
TODOS LOUVANDO A JESUS, 
NO CÉU, NO CÉU.
');
