INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b18089d9-207b-4d84-9024-09ea55fffd80', 'Finda a Lida Terreal', '536', 'Let.: Benjamim Ruffino Duarte; Mus. Autor Desconhecido', 'Country', 'A', 'Volta de Jesus e Eternidade', 'FINDA A LIDA TERREAL,
QUANDO JÁ DO RIO ALÉM,
NESSA VIDA GLORIOSA ME ENCONTRAR;
SEI QUE LÁ MEU REDENTOR
SORRIDENTE HEI DE VER,
ENTRE A TURBA, O PRIMEIRO A ME CHAMAR.

CORO
HEI DE VER MEU REDENTOR,
REDIMIDO AO SEU LADO HEI DE ESTAR;
HEI DE VER MEU SALVADOR,
EM GLORIOSA E SANTA LUZ CELESTIAL.

OH! DA ALMA MEU ENLEVO
É SEU ROSTO CONTEMPLAR
NESSA AURORA DO DIA ETERNAL;
COMO ENTÃO MEU CORAÇÃO
O NÃO HÁ DE ALI LOUVAR
PELA GRAÇA E FAVOR CELESTIAL?

NESSA PÁTRIA RESPLENDENTE
HEI DE AMIGOS ENCONTRAR,
SIM, AMIGOS MAIS PREZADOS HEI DE TER;
MAS PRIMEIRO QUE TUDO,
QUANDO EU ALI CHEGAR,
MEU JESUS É QUEM EU MAIS ANSEIO VER.

PELAS PORTAS DA CIDADE,
EM VESTES A ALVEJAR,
ALI, ONDE NOITE E PRANTO NÃO ESTARÃO;
ENTRE CANTO ANGELICAL
HÁ MEUS PASSOS DE GUIAR,
PERTO, SIM,
MUI PERTO O HEI DE VER, ENTÃO.
');
