INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b18b0450-797c-430f-b87a-8903d33344c5', 'Somente pela fé', '755', 'João Luís', 'Valsa', 'F', 'Corinhos', '*CORO 2X
SOMENTE PELA FÉ, SOMENTE PELA FÉ
A OBRA DE DEUS VAI CRESCENDO
SOMENTE PELA FÉ.

OS ENFERMOS SÃO CURADOS,
SOMENTE PELA FÉ;
OS MORTOS RESSUSCITADOS,
SOMENTE, PELA FÉ.

*CORO
SOMENTE PELA FÉ, SOMENTE PELA FÉ
A OBRA DE DEUS VAI CRESCENDO
SOMENTE PELA FÉ.

ATÉ OS CEGOS JÁ VEEM,
SOMENTE PELA FÉ;
PELO PODER DE JESUS,
SOMENTE PELA FÉ,

*CORO
SOMENTE PELA FÉ, SOMENTE PELA FÉ
A OBRA DE DEUS VAI CRESCENDO
SOMENTE PELA FÉ.
');
