INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b1efa0d5-2ada-4b4d-b99f-025bc9ca07c2', 'Pai Que Estás No Céu (Coro Masculino)', '', '', '', '', '', 'SANTO, SANTO ÉS SENHOR.
DEUS PODEROSO, SANTO ÉS SENHOR,
SANTO ÉS SENHOR, SENHOR,
SEJA BENDITO O TEU NOME, TEU NOME,
Ó GRANDE DEUS!
PAI QUE ESTÁS NO CÉU, PAI CELESTIAL,
VEM GUIAR OS FILHOS
TEUS ATÉ O DIA FINAL.

ENTÃO NOS CÉUS, BONDOSO DEUS,
LIMPOS DE CORAÇÃO
EM DOCE CANTO DE ADORAÇÃO:
“DEUS PAI, FILHO, ESPÍRITO SANTO”.
CONTRITOS DE CORAÇÃO,
OUVE A SUA ORAÇÃO,
Ó PAI DE AMOR,
Ó GRANDE DEUS DE AMOR!

CONTRITOS DE CORAÇÃO OUVE
A SUA ORAÇÃO, Ó PAI DE AMOR,
“DEUS PAI, FILHO, ESPÍRITO SANTO”.
CONTRITOS DE CORAÇÃO,
OUVE A SUA ORAÇÃO, Ó PAI DE AMOR,
Ó GRANDE DEUS DE AMOR!
CONTRITOS DE CORAÇÃO OUVE
A SUA ORAÇÃO, Ó PAI DE AMOR.
');
