INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b2451fc6-f97f-42ba-9fbf-81c3dd186d83', 'A tua palavra é semente', '174', 'Autor Desconhecido', 'Balada', 'G', 'Crianças e Adolescentes', 'A TUA PALAVRA É SEMENTE
E TU ÉS O SEMEADOR,
O MEU CORAÇÃO É A TERRA
QUE TU SEMEASTE, SENHOR.

CORO
A TUA PALAVRA, A TUA PALAVRA,
A TUA PALAVRA, SENHOR;
A TUA PALAVRA, A TUA PALAVRA,
A TUA PALAVRA É AMOR.

MEDITANDO EU CERTO DIA
NA TUA PALAVRA, SENHOR,
SENTI QUE DO ALTO DESCIA
A GRAÇA DO CONSOLADOR.
');
