INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b24814d2-fff6-4fa3-a6c2-735b2091ec3a', 'Qual madeira', '399', 'Gérson Beluci Miguel; Veimar Jeamond Luz', 'Balada', 'A', 'Santificação e Derramamento', 'QUAL MADEIRA INÚTIL, ASSIM, FUI PLANTADO,
NO DESERTO DO MUNDO CRUEL FUI DEIXADO;
MAS JESUS ME ENCONTROU E ME LIBERTOU;
DE UMA VIDA VAZIA, SEM PAZ, SEM AMOR.
/INSTRUMENTOS

DE MINH''ALMA TIROU O MEU FARDO TÃO PESADO,
QUAL A CASCA DA DURA MADEIRA, MEU PECADO;
/FINAL 2X
TRABALHOU-ME POR INTEIRO, 
COMO UM BOM CARPINTEIRO,
FEZ-ME VASO DE HONRA, DE GLÓRIA E LOUVOR.
