INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b2a77fe5-0f48-4ba3-9c74-99a05c2858ac', 'Hoje é um grande dia', '108', 'I.B.J. / E.H.M.R.', 'Balada', 'D', 'Crianças e Adolescentes', 'HOJE É UM GRANDE DIA, É DIA DE LOUVAR;
LOUVEMOS A JESUS QUE ESTÁ NESTE LUGAR;
HOJE É DIA DE VITÓRIA E VITÓRIA ELE NOS DÁ;
RECEBA JESUS, ELE QUER TE ABENÇOAR.

CORO
VENHAM TODOS JÁ, A JESUS VAMOS LOUVAR!
ACEITEM O SALVADOR
QUE VIDA ETERNA QUER LHES DAR!

HOJE AQUI ESTOU PARA TE LOUVAR
POR TANTAS MARAVILHAS, POR SEMPRE ME AMAR.
TUA OBRA EM MINHA VIDA, VOU ANUNCIAR,
OBRA DE ALEGRIA E ALEGRIA QUE É SEM PAR!
');
