INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b2c1ec21-1aab-47c2-8cdf-184e2e8982bd', 'Exaltai, Exaltai', '241', 'Nívea Maria de Oliveira Costa', 'Marcha', 'Bm', 'Crianças e Adolescentes', 'CANTAR 2X
EXALTAI, EXALTAI,
AQUELE QUE MORREU
NA CRUZ PARA NOS SALVAR
E HOJE VIVO ESTÁ
PARA A VITÓRIA NOS DAR.
/INSTRUMENTOS

CANTAR 2X
ACLAMAI, ACLAMAI,
POIS DIGNO DE ABRIR O LIVRO
O CORDEIRO É;
BREVE JESUS VIRÁ,
SUA IGREJA FIEL LEVARÁ, 
BREVE JESUS VIRÁ.
/FINAL
MARANATA! ALELUIA!
');
