INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b2d48a69-ca6c-4558-ae30-0d1e83b2e91d', 'Perfeito Amor', '685', 'Mike Michaele Kunert Deps', 'Básico', 'E', 'Grupo de Louvor', 'PERFEITO AMOR EU CONHECI,
NÃO IMAGINEI QUE ELE PODERIA EXISTIR;
AMOR FIEL E VERDADEIRO AMOR,
TUDO ELE SUPORTOU, ME AMOU ATÉ O FIM.

FOI, ENTÃO, QUE EU SENTI
COMO É FORTE O AMOR QUE RECEBI;
AMOR FIEL E VERDADEIRO AMOR,
É JESUS, O MEU SENHOR.
TENHO EM MIM O SEU AMOR.

DIFERENTE DO AMOR QUE NO MUNDO ESTÁ,
AMOR PERFEITO É DOM DE DEUS
E SÓ ELE PODE DAR;
COM ESTE AMOR EU POSSO CRER,
TUDO SUPERAR,
SEI QUE EM TODA A MINHA VIDA
ELE NÃO FALHARÁ.

DIFERENTE DO AMOR
(DIFERENTE DO AMOR)
QUE NO MUNDO ESTÁ,
AMOR PERFEITO É DOM DE DEUS
E SÓ ELE PODE DAR;

COM ESTE AMOR EU POSSO CRER,
(COM ESTE AMOR EU POSSO CRER)
TUDO SUPERAR,
SEI QUE EM TODA A MINHA VIDA
ELE NÃO FALHARÁ.
/INSTRUMENTOS

FINAL
AMOR FIEL E VERDADEIRO AMOR,
RECEBI DO MEU SENHOR,
QUE ME AMOU COM ETERNO AMOR.
');
