INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b2dfab21-1796-4d71-95ab-cd0964145a85', 'No dia da grande glória', '766', '', 'Balada', 'C', 'Corinhos', 'NO DIA DA GRANDE GLÓRIA
HAVEMOS DE IR CANTAR LÁ NO CÉU.
HAVEMOS DE ENCONTRAR-NOS
ALÉM DO JORDÃO, QUE ALEGRIA, QUE BOM!

SE TU CHEGARES PRIMEIRO QUE EU
AVISA QUE EU TAMBÉM CHEGO LÁ.
HAVEMOS DE ENCONTRAR-NOS
ALÉM DO JORDÃO, QUE ALEGRIA SERÁ!

HAVEMOS DE ENCONTRAR-NOS
ALÉM DO JORDÃO, QUE BELO SERÁ!
HAVEMOS DE ENCONTRAR-NOS
TAMBÉM COM JESUS QUE ALEGRIA SERÁ!

LÁ NÃO VAI HAVER TRISTEZA;
O PRANTO E A DOR LÁ NÃO TEM LUGAR!
HAVEMOS DE ENCONTRAR-NOS
COM CRISTO NO CÉU QUE ALEGRIA SERÁ!
');
