INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b33e5ce0-9efb-424e-9963-7e0d8e3168f3', 'Vem, Chegou O Tempo De Adorar', '', '', '', '', '', 'NA VIDA HÁ SEMPRE UM TEMPO
PARA TUDO ACONTECER.
PRA TODO PENSAMENTO
DEBAIXO DESTE CÉU,
NÃO PRECISAMOS MAIS
ESTAR TÃO ANSIOSOS,
BASTA-NOS O PRESENTE,
FUTURO DEUS DARÁ.

TEMPO DE AMAR, TEMPO
DE BUSCAR, TEMPO DE CANTAR,
TEMPO DE PERDER
TEMPO DE CHORAR, TEMPO
DE SORRIR, TEMPO DE VIVER,
TEMPO DE FALAR,
TEMPO DE CALAR, TEMPO
DE PLANTAR, TEMPO DE COLHER,
TEMPO DE ORAR, TEMPO DE PEDIR,
TEMPO DE MORRER.

TUDO O QUE DEUS FEZ,
PRA SEMPRE DURARÁ,
NADA SE DEVE POR,
OU MESMO RETIRAR POIS,
PARA O SEU TEMOR A TUDO
DEUS CRIOU HOJE O QUE É JÁ FOI,
E O QUE SERÁ TAMBÉM.
');
