INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b3b8de7c-fa94-4503-a084-a9120306ad61', 'Eu só quero ser, Senhor', '392', 'Jorgemar Souza Madeira', 'Básico', 'Bm', 'Santificação e Derramamento', 'EU SÓ QUERO SER, SENHOR,
UM REMIDO DO TEU GRANDE AMOR;
QUERO SÓ ANDAR NA LUZ
E NO CÉU A CONTEMPLAR JESUS;

POIS NA CRUZ ELE MORREU
E O SEU SANGUE ASSIM VERTEU POR MIM;
QUANTO EU AMO AO MEU SENHOR,
MEU ETERNO SALVADOR, JESUS.

EU SÓ QUERO TER UM LUGAR NO CÉU, SENHOR;
ESTENDE A TUA MÃO, 
DERRAMA O TEU PODER EM MIM;
OUVIR A TUA VOZ
ALMEJA O MEU CORAÇÃO,
EU SÓ QUERO SERVIR A TI.

EU SÓ QUERO SER, SENHOR,
UM REMIDO DO TEU GRANDE AMOR;
QUERO SÓ ANDAR NA LUZ
E NO CÉU A CONTEMPLAR JESUS;

POIS NA CRUZ ELE MORREU
E O SEU SANGUE ASSIM VERTEU POR MIM;
QUANTO EU AMO AO MEU SENHOR,
MEU ETERNO SALVADOR, JESUS.

CANTAR 2X
EU SÓ QUERO TER UM LUGAR NO CÉU, SENHOR;
ESTENDE A TUA MÃO, 
DERRAMA O TEU PODER EM MIM;
OUVIR A TUA VOZ
ALMEJA O MEU CORAÇÃO,
EU SÓ QUERO SERVIR A TI.
/FINAL
EU SÓ QUERO SERVIR A TI.
');
