INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b3d958be-7e00-4d24-9d3d-a82df1313d5d', 'No céu há janelas abertas', '742', 'Autor Desconhecido', 'Balada', 'A', 'Corinhos', 'NO CÉU HÁ JANELAS ABERTAS,
AS BÊNÇÃOS JÁ DESCEM DE LÁ;
O MEU CORAÇÃO REJUBILA
PORQUE JESUS NELE ESTÁ.
TIREI OS ANDRAJOS IMUNDOS,
DE BRANCO VESTIU-ME O SENHOR,
DO PÃO DIVINAL EU ME NUTRO,
BANQUETE DO SEU GRANDE AMOR.
');
