INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b406e303-26ff-49d5-83be-b9bc07b172b0', 'Coroai', '645', 'Marcelo Pontes de Aquino', 'Básico', 'Em', 'Grupo de Louvor', 'COROAI AO QUE É DIGNO
E BENDITO SOBRE A TERRA,
EXALTAI O SEU NOME,
COM LOUVORES DE VITÓRIA;

O SEU NOME
ENTRE TODAS AS NAÇÕES SERÁ LOUVADO;
(O CORDEIRO ENTRE TODAS AS NAÇÕES SERÁ LOUVADO)
OH! JESUS, MEU SENHOR, REINARÁ.

REINARÁ COM PODER E GLÓRIA
SOBRE TODA A TERRA,
TODO HOMEM
DIANTE DO SEU TRONO SE ENCURVARÁ;

CONTEMPLAI O CORDEIRO ETERNO
QUE RESSUSCITOU, 
(DAI LOUVORES AO CORDEIRO ETERNO, QUE RESSUSCITOU)
SOBRE AS NUVENS DESCERÁ E REINARÁ.
/INSTRUMENTOS

REINARÁ COM PODER E GLÓRIA
SOBRE TODA A TERRA,
TODO HOMEM
DIANTE DO SEU TRONO SE ENCURVARÁ;

CONTEMPLAI O CORDEIRO ETERNO
QUE RESSUSCITOU, 
(DAI LOUVORES AO CORDEIRO ETERNO, QUE RESSUSCITOU)
SOBRE AS NUVENS DESCERÁ E REINARÁ.
/FINAL
COROAI.
');
