INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b48e774a-0c4e-460c-97fa-bb6a749cf2c4', 'Jesus te ama', 93, 'P.H.R.', 'Fox', 'D', 'Crianças e Adolescentes', 'CANTAR 2X
JESUS TE AMA,
ELE QUER TE SALVAR.
DEIXE A LUZ
ENTRAR EM TEU CORAÇÃO.

ELE QUER TRANSFORMAR
TEU CHORO EM ALEGRIA,
ELE QUER TE DAR PAZ, 
GOZO E ESPERANÇA.
JESUS TE AMA (JESUS TE AMA),
ELE QUER TE SALVAR.
(ELE QUER TE SALVAR),
DEIXE A LUZ (DEIXE A LUZ)
ENTRAR EM TEU CORAÇÃO.

ELE QUER TRANSFORMAR
TEU CHORO EM ALEGRIA,
ELE QUER TE DAR PAZ,
GOZO E ESPERANÇA.
SE TU QUISERES (SE TU QUISERES)
ACEITAR A CRISTO (ACEITAR A CRISTO),
ABRE HOJE MESMO (ABRE HOJE MESMO)
O TEU CORAÇÃO.

FINAL
JESUS TE CHAMA!
JESUS TE AMA!
JESUS TE AMA!
');
