INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b4bd5cf7-e462-4e89-af4f-6967238581e0', 'Arrebatado fui', '541', 'Wilson de Souza', 'Básico', 'D', 'Volta de Jesus e Eternidade', 'ARREBATADO FUI NO DIA DO SENHOR,
OUVI UMA GRANDE VOZ, A VOZ DO MEU JESUS;
E AOS SEUS PÉS CAÍ, AOS PÉS DO SALVADOR,
AQUELE QUE POR MIM MORREU NA CRUZ.

CORO
E VI UM NOVO CÉU, UMA NOVA TERRA VI,
UMA GRANDE VOZ NO CÉU
SE FEZ ENTÃO OUVIR;
NÃO HAVERÁ MAIS DOR,
NEM PRANTO E NEM CLAMOR;
SÓ HAVERÁ DE DEUS UM GRANDE AMOR.

ONIPOTENTE DEUS
A QUEM VENCER, DARÁ
TUDO O QUE É SEU, NO CÉU,
TUDO HERDARÁ DE DEUS;
"SEREI TEU ETERNO PAI,
SERÁS MEU FILHO, ENTÃO,
POIS QUEM VENCER ALCANÇARÁ PERDÃO."
');
