INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b4d70d09-4121-459c-a887-47725087362a', 'O dia da vitória', '', '', '', '', '', 'ASSIM COMO A NOITE AGUARDA O SOL,
COMO A BRISA SONHA UM DIA SOPRAR
COMO A TERRA SECA ESPERA A CHUVA
COMO O RIO ANSEIA PELO MAR
EU DESEJO TANTO VER O DIA CHEGAR!

*CORO
O DIA DA VITÓRIA
EM QUE VIRÁ MEU SALVADOR
SIM, JESUS CRISTO, O SENHOR,
VIRÁ NAS NUVENS PARA ME LEVAR
SE TORNARÁ VERDADE
TUDO O QUE SEMPRE SONHEI,
TRISTEZAS EU NÃO MAIS TEREI
E TODA LÁGRIMA DO MEU OLHAR
ELE ENXUGARÁ!

BRAÇOS LEVANTADOS, LIVRES DO MAL
IGUALDADE E JUSTIÇA HAVERÁ
JÁ NÃO MAIS TERÁ MORTE OU GUERRA
NOVO CÉU E UMA NOVA TERRA
EU DESEJO TANTO VER O DIA CHEGAR!

*CORO
O DIA DA VITÓRIA
EM QUE VIRÁ MEU SALVADOR
SIM, JESUS CRISTO, O SENHOR,
VIRÁ NAS NUVENS PARA ME LEVAR
SE TORNARÁ VERDADE
TUDO O QUE SEMPRE SONHEI,
TRISTEZAS EU NÃO MAIS TEREI
E TODA LÁGRIMA DO MEU OLHAR
ELE ENXUGARÁ!
/INSTRUMENTOS

*CORO
O DIA DA VITÓRIA
EM QUE VIRÁ MEU SALVADOR
SIM, JESUS CRISTO, O SENHOR,
VIRÁ NAS NUVENS PARA ME LEVAR
SE TORNARÁ VERDADE
TUDO O QUE SEMPRE SONHEI,
TRISTEZAS EU NÃO MAIS TEREI
E TODA LÁGRIMA DO MEU OLHAR
ELE ENXUGARÁ!
');
