INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b4e6fa73-c2a8-49f0-a370-a7912d190c30', 'Nesta Noite Feliz', '076', 'Autor Desconhecido', 'Básico 2', 'D', 'Invocação e Comunhão', 'NESTA NOITE FELIZ, NESTE SANTO LUGAR,
EU MARQUEI UM ENCONTRO COM DEUS;
SEU AMOR É REAL, SUA PAZ GOZAREI,
EU MARQUEI UM ENCONTRO COM DEUS.

EU MARQUEI UM ENCONTRO COM DEUS
NESTE SANTO LUGAR DE ORAÇÃO;
NESTE ENCONTRO DE AMOR,
PEDIREI AO SENHOR
UMA BENÇÃO PARA O MEU CORAÇÃO.
');
