INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b5157ac7-3adf-4a13-ba73-ac38984d4433', 'Deixa Deus Falar ao Teu Coração', '239', 'Sérgio Paulo Ferreira de Matos', 'Fox', 'D', 'Morte, Ressureição e Salvação', 'DEIXA DEUS FALAR AO TEU CORAÇÃO,
ELE QUER SE REVELAR A TI,
SUA VOZ APRENDE A ESCUTAR,
DEIXA DEUS TE FALAR;

BUSCA MAIS SUA PRESENÇA,
VIGIANDO EM ORAÇÃO,
SUA VOZ IRÁS, ENTÃO, OUVIR,
FALANDO AO TEU CORAÇÃO.

TEUS PROBLEMAS DEUS PODE RESOLVER,
DÁ-LHE TUA VIDA SEM TEMER,
SE TEUS PASSOS DEIXAS DEUS GUIAR,
PAZ IRÁS EXPERIMENTAR;

ELE TEM UM PLANO PARA TI
E TE GUIA COM SUA MÃO,
SIM, ESCUTA O QUE ELE AGORA DIZ,
FALANDO AO TEU CORAÇÃO. (2X)
');
