INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b54afd46-009f-44ea-b985-afc3bbfb8218', 'A Deus seja o louvor', '607', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Louvor', 'A DEUS SEJA O LOUVOR
POR TUDO O QUE ELE É,
PERFEIÇÃO ABSOLUTA
EM SANTIDADE E AMOR!
E DAI AO FILHO A GLÓRIA 
POIS ALCANÇOU VITÓRIA,
ELE É VENCEDOR, DE TUDO É O SENHOR!
POR TODO O SEMPRE SE FALARÁ
DAS MARAVILHAS DO SEU AMOR
E TODO O SER SE ENCURVARÁ PRA O ADORAR!
O REI QUE SERVO SE TORNOU,
O DEUS QUE ÀQUELA CRUZ BAIXOU
PARA, POR SEU SANGUE,
O PECADOR RESGATAR.
/FINAL
ÀQUELA CRUZ BAIXOU PARA POR SEU SANGUE,
O PECADOR RESGATAR.
');
