INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b5b6b5f0-727a-40f8-b179-7f5757a5bf25', 'Entrei no tempo de Deus', '398', 'Ezequiel', 'Básico', 'C', 'Santificação e Derramamento', 'CANTAR 2X
ENTREI NO TEMPO DE DEUS,
JÁ VIVO A ETERNIDADE,
VOCÊ TAMBÉM PODE ENTRAR,
(PODE ENTRAR)
SER PARTICIPANTE COMO EU,
O PAI LHE REVELARÁ A ETERNIDADE.

CANTAR 2X
O MEU TEMPO ERA CONTADO PARA A MORTE
MAS APROUVE AO PAI ENVIAR SEU FILHO
E HOJE EU VIVO JÁ
A ETERNIDADE.
/FINAL
A ETERNIDADE.
');
