INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b5ef2735-ab58-406f-a539-d672ac07df83', 'Os céus em breve se abrirão', '702', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'D', 'Volta de Jesus e Eternidade', 'OS CÉUS EM BREVE SE ABRIRÃO
E TODOS TE VERÃO,
Ó FILHO DE DAVI;
OS REIS VIRÃO A TI,
DE JOELHOS ADORAR
AQUELE QUE PRA SEMPRE IRÁ REINAR.

ENTÃO TODOS VERÃO QUEM ÉS,
PROSTRADOS A TEUS PÉS
ENTENDERÃO O AMOR, O VERDADEIRO AMOR
QUE TE LEVOU, JESUS,
A DAR-ME A TUA VIDA NAQUELA CRUZ.

*CORO
NÓS TE SAUDAMOS;
HOSANA AO FILHO DE DAVI!
BENDITO AQUELE QUE VEM
EM NOME DO SENHOR,
HOSANA, HOSANA!

OS CÉUS, DE GOZO, TREMERÃO,
E TODA CRIAÇÃO SE ALEGRARÁ EM TI,
Ó FILHO DE DAVI,
POIS NOVA VIDA E PAZ
AO NOVO CÉU, ENFIM, NOS LEVARÁS!

*CORO
NÓS TE SAUDAMOS;
HOSANA AO FILHO DE DAVI!
BENDITO AQUELE QUE VEM
EM NOME DO SENHOR,
HOSANA, HOSANA!
/FINAL
HOSANA!
');
