INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b60ff272-ed95-42a0-8d28-13883ba0d056', 'Grande Deus, único Deus', 81, 'Raquel Toscano de Freitas', 'Básico', 'C', 'Invocação e Comunhão', 'GRANDE DEUS, ÚNICO DEUS,
CRIADOR DE TUDO QUANTO HÁ
DE MAIS PROFUNDO, DE MAIS VALOR,
O SENHOR, O MEU GRANDE DEUS.

FINAL 2X
PAI, TU QUE ME OUVES
MESMO QUANDO A VOZ NÃO SAI,
MEU GRANDE PAI,
TU ÉS AMIGO, PREFERIDO
MAIS QUE IRMÃO, MEU GRANDE PAI,
TU ÉS AMIGO, MEU PREFERIDO,
DÁ-ME A TUA PAZ.
');
