INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b62d2ca3-d988-4656-8712-5aa555f70966', 'Se Em Teu Viver', '246', 'Armando Filho', 'Balada', 'G', 'Morte, Ressureição e Salvação', 'SE EM TEU VIVER EXISTE UM VAZIO,
SE TU NÃO PODES CANTAR
COM OS QUE CANTAM PRA JESUS,
NÃO TE DETENHAS, NÃO CHORES,
MEU AMIGO,
CRISTO TRANSFORMA AS TREVAS EM PLENA LUZ.

CORO
FELIZ SERÁS, JAMAIS VERÁS
TUA VIDA EM PRANTO SE FINDAR;
FELIZ SERÁS SE AO SENHOR
TEU CORAÇÃO ENTREGAR.

CONTEMPLA AGORA AS BÊNÇÃOS DE CRISTO
QUANDO, EM SORRISOS, TUAS LÁGRIMAS
ELE VAI TRANSFORMAR,
PRA SEMPRE GUIARÁ OS TEUS CAMINHOS
E COM AMOR AO CÉU TE LEVARÁ.
');
