INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b6b3e9c5-7196-49aa-a4d8-a3c313d3d090', 'Senhor, meu Deus o que direi de ti', '454', 'Charles Horst Assunção', 'Valseado', 'D', 'Santificação e Derramamento', 'SENHOR MEU DEUS, O QUE DIREI DE TI?
TU ÉS AQUELE QUE ME AMOU PRIMEIRO!
MAS HOJE FRACO ESTOU,
SINTO SAUDADES DE TI, SENHOR,
E VIM CHORAR DIANTE AOS TEUS PÉS, EM ORAÇÃO.

RENOVA EM MIM VALORES TEUS,
ORDENA OS PENSAMENTOS MEUS
E DÁ-ME, Ó PAI, SAÚDE ESPIRITUAL;
PRA COM PRIMEIRO AMOR TE AMAR,
O AMOR QUE UM DIA CONHECI
QUANDO TOCASTE EM MIM PELA PRIMEIRA VEZ.
/INSTRUMENTOS

SENHOR MEU DEUS, O QUE DIREI DE TI?
TU ÉS AQUELE QUE ME AMOU PRIMEIRO!
MAS HOJE FRACO ESTOU,
SINTO SAUDADES DE TI, SENHOR,
E VIM CHORAR DIANTE AOS TEUS PÉS, EM ORAÇÃO.

RENOVA EM MIM VALORES TEUS,
ORDENA OS PENSAMENTOS MEUS
E DÁ-ME, Ó PAI, SAÚDE ESPIRITUAL;
PRA COM PRIMEIRO AMOR TE AMAR,
O AMOR QUE UM DIA CONHECI
/FINAL 2X
QUANDO TOCASTE EM MIM PELA PRIMEIRA VEZ.
');
