INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b77cf41a-f52c-4e71-9192-d0516f42e72a', 'Jesus, Jesus, Meu Senhor', '', '', '', '', '', 'ESTE É MEU DESEJO SENHOR, TE HONRAR
COM MEU CORAÇÃO, TE ADORAR
TUDO O QUE HÁ EM MIM TE DÁ LOUVOR
SÓ A TI ADORO, MEU SENHOR.

CORO
TOMA O MEU CORAÇÃO E TODA A MINHA ALMA
EU VIVO SÓ PRA TI SEMPRE QUE EU RESPIRAR CADA
VEZ QUE EU ACORDAR FAZE O TEU QUERER EM MIM.

ESTE É MEU DESEJO SENHOR, TE HONRAR
COM MEU CORAÇÃO, TE ADORAR
TUDO O QUE HÁ EM MIM TE DÁ LOUVOR
SÓ A TI ADORO, MEU SENHOR.

FINAL 2X
TOMA O MEU CORAÇÃO E TODA A MINHA ALMA
EU VIVO SÓ PRA TI SEMPRE QUE EU RESPIRAR CADA
VEZ QUE EU ACORDAR FAZE O TEU QUERER EM MIM.
');
