INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b7cc9a94-0203-4a21-9204-590c9f0f9448', 'Alma cansada', '', '', '', '', '', 'ALMA CANSADA, NÃO
DESESPERES, ESPERA EM DEUS,
QUE ELE VEM, QUE ELE VEM
TE SOCORRER; ALMA CANSADA,
NÃO DESESPERES ESPERA EM DEUS,
ESPERA EM DEUS, ESPERA EM
DEUS E NO SEU PODER.

*CORO
OH! ALMA CANSADA, ESPERA
EM DEUS E NO SEU AMOR;
VEM! ALMA CANSADA,
ESPERA EM DEUS,
CONFIA SOMENTE NO SEU AMOR.
/INSTRUMENTOS

ALMA CANSADA,
O TEU LAMENTO NÃO RESOLVERÁ,
A HORA É TRISTE, COM FÉ INSISTE,
DEUS TE OUVIRÁ;
SE TEUS MOMENTOS TRAZEM
TORMENTOS QUE FAZEM CHORAR,
DEUS TE CHAMA AGORA,
Ó VEM SEM DEMORA
EM PAZ DESCANSAR.

*CORO
OH! ALMA CANSADA, ESPERA
EM DEUS E NO SEU AMOR;
VEM! ALMA CANSADA,
ESPERA EM DEUS,
CONFIA SOMENTE NO SEU AMOR.
');
