INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b7d5e55a-0a8a-4637-9563-92fd821b2af4', 'Deus Hoje Quer Te Falar', '234', 'Sérgio Paulo Ferreira de Matos', 'Valseado', 'F', 'Morte, Ressureição e Salvação', 'DEUS HOJE QUER TE FALAR,
ELE BATE AO TEU CORAÇÃO;
SE TU ABRIRES, ELE VAI ENTRAR
E TE DARÁ SALVAÇÃO.

VOZ TÃO SUAVE ELE TEM,
FALANDO COM TANTO AMOR;
POR TI JESUS MORREU NA CRUZ,
ELE É O TEU SALVADOR.

SE HOJE OUVIRES SUA VOZ,
ABRE-LHE TEU CORAÇÃO;
/FINAL 2X
ENTÃO TERÁS AMOR E PAZ
QUE JAMAIS TERMINARÃO.
');
