INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b813c643-26fc-4e6b-a095-0836d8a0528c', 'Pela Via Dolorosa', '', '', '', '', '', 'PELA VIA DOLOROSA,
TRISTE DIA EM JERUSALÉM.
OS SOLDADOS DISPERSAVAM
A MULTIDÃO, QUE CORRIA PARA VER
O HOMEM QUE LEVAVA A SUA CRUZ.

LHE SANGRAVAM AS FERIDAS,
QUE EM SEU DORSO RECEBEU,
COM ESPINHOS COROARAM A JESUS
E EM DOR PODIAM VER
O HOMEM CONDENADO A MORRER.

PELA VIA DOLOROSA
CAMINHOU O SALVADOR.
COMO OVELHA VEIO
O CRISTO, REI, SENHOR.
E ELE FOI QUEM ESCOLHEU DAR
A VIDA POR TI, POR MIM.

PELA VIA DOLOROSA AO CALVÁRIO
SOFREU ASSIM.
LHE SANGRAVAM AS FERIDAS QUE EM
SEU DORSO RECEBEU,
COM ESPINHOS COROARAM A JESUS.
E EM DOR PODIAM VER O HOMEM
CONDENADO A MORRER.

PELA VIA DOLOROSA
CAMINHOU O SALVADOR.
COMO OVELHA VEIO
O CRISTO, REI, SENHOR.
E ELE FOI QUEM ESCOLHEU DAR
A VIDA POR TI, POR MIM.

JESUS SE ENTREGOU, MOSTROU O
SEU AMOR, MORREU NUNCA CRUZ EM JERUSALÉM.
PELA VIA DOLOROSA CAMINHOU O SALVADOR.
COMO OVELHA VEIO O CRISTO, REI, SENHOR.

JESUS SE ENTREGOU, MOSTROU
O SEU AMOR, MORREU NUNCA CRUZ EM JERUSALÉM.
PELA VIA DOLOROSA CAMINHOU O SALVADOR.

COMO OVELHA VEIO O CRISTO, REI, SENHOR.
E ELE FOI QUEM ESCOLHEU DAR
A VIDA POR TI, POR MIM.
PELA VIA DOLOROSA AO CALVÁRIO
SOFREU ASSIM.
');
