INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b983c418-cc93-4460-aa6e-2fb18b4e35da', 'Todo o Meu Ser Te Ama', '190', 'Autor Desconhecido', 'Básico 2', 'D', 'Grupo de Louvor', 'CANTAR 2X
TODO O MEU SER TE AMA
E MINH''ALMA TE ADORA,
TU ÉS MEU PASTOR, SALVADOR,
ÉS O MEU VIVER
E TE AMO MUITO MAIS QUE POSSA DIZER.

TU ÉS REI ACIMA DE TODOS OS REIS,
TUA MORADA É ETERNA, SENHOR;
TU HABITAS DENTRO EM MIM,
BEM MAIOR NÃO POSSO TER,
POIS TU ÉS SANTO, ÉS PODEROSO,
TU ÉS JESUS, SENHOR E REI.

FINAL
TODO O MEU SER TE AMA
E MINH''ALMA TE ADORA,
TU ÉS MEU PASTOR, SALVADOR,
ÉS O MEU VIVER
E TE AMO MUITO MAIS QUE POSSA DIZER.
');
