INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b9921a43-95ce-481e-ab70-218c1d2cf100', 'Feliz, feliz eu sou', '783', 'Wilson Belchior', 'Fox Abafado', 'G', 'Dedicação', 'FELIZ, FELIZ, EU SOU.
TÃO LONGE DO SENHOR ANDAVA,
NÃO TINHA PAZ,
O MUNDO ALVOROÇAVA AO MEU REDOR;
ATÉ AS BELAS FLORES
NÃO TINHAM BELEZA PRA MIM,
VIVIA TRISTE, ERA INFELIZ (ERA INFELIZ).

FINAL 2X
MAS UM DIA A LUZ RAIOU,
JESUS CRISTO ME ALCANÇOU;
E AGORA, FELIZ,
AO LADO DO MEU SENHOR,
QUERO ANDAR SEGURO POR ONDE EU FOR.
(POR ONDE EU FOR)
');
