INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b9c5f8af-e131-4e3d-9551-a61fb3e94f37', 'Eu Aviso Uma Terra Feliz', '528', 'Let.: Sanford Filmore Benett; Trad. William Edwin Entzminger; Mus. Joseph Philbrick Webster', 'Country', 'E', 'Volta de Jesus e Eternidade', 'EU AVISTO UMA TERRA FELIZ,
ONDE IREI PARA SEMPRE MORAR;
HÁ MANSÕES NESSE LINDO PAÍS
QUE JESUS FOI AO CÉU PREPARAR.

CANTAR 2X
VOU MORAR, VOU MORAR
NESSA TERRA CELESTE PORVIR.

CANTAREI NESSE LINDO PAÍS,
BELOS HINOS AO MEU SALVADOR,
POIS ALI VIVEREI BEM FELIZ,
SEM TRISTEZAS, VEXAMES NEM DOR.

CANTAR 2X
VOU CANTAR, VOU CANTAR
NESSA TERRA CELESTE PORVIR.

DEIXAREI ESTE MUNDO AFINAL,
PARA IR A JESUS ADORAR;
NESSA BELA CIDADE FESTAL,
MIL VENTURAS SEM FIM VOU GOZAR.

FINAL 2X
VOU GOZAR, VOU GOZAR
NESSA TERRA CELESTE PORVIR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('b9c5f8af-e131-4e3d-9551-a61fb3e94f37', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
