INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b9ce58e9-9b87-4111-b774-69ec3ad34bf3', 'O Cordeiro que na Cruz Morreu', '051', 'Olcimar Rubens de Carvalho', 'Básico', 'A', 'Clamor', 'O CORDEIRO QUE NA CRUZ MORREU
VIVO ESTÁ ENTRE NÓS,
DERRAMOU SEU SANGUE INOCENTE
PARA NOS PURIFICAR.

CORO
NÓS CLAMAMOS POR ESTE SANGUE,
QUE É ESPÍRITO DE VIDA,
É O NOSSO ESCUDO, NOSSA PROTEÇÃO.
ESTE SANGUE NOS TRAZ O PERDÃO.

DE ALTO A BAIXO O VÉU SE RASGOU
QUANDO JESUS EXPIROU,
PERMITINDO A NOSSA ENTRADA
NO SANTÍSSIMO LUGAR.

FINAL
É O NOSSO ESCUDO, NOSSA PROTEÇÃO.
ESTE SANGUE NOS TRAZ COMUNHÃO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('b9ce58e9-9b87-4111-b774-69ec3ad34bf3', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
