INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('b9edb3d1-9a4d-421c-80a9-ee5ecfec6269', 'Sempre vou lembrar o que fizeste por mim', '177', 'Jorgemar Souza Madeira', 'Básico', 'D', 'Dedicação', 'CANTAR 2X
SEMPRE VOU LEMBRAR
O QUE FIZESTE POR MIM,
NÃO ESQUECEREI 
TEU GRANDE AMOR POR MIM.

*CORO
NÃO FOI EM VÃO
O TEU SANGUE VERTIDO NA CRUZ,
NÃO FOI EM VÃO,
EU TE LOUVO PRA SEMPRE, JESUS.
/INSTRUMENTOS

É TEU MEU LOUVOR, 
MINHA ADORAÇÃO,
ÉS TU MEU PASTOR,
É TEU TODO O MEU CORAÇÃO.

*CORO 2X
NÃO FOI EM VÃO
O TEU SANGUE VERTIDO NA CRUZ,
NÃO FOI EM VÃO,
EU TE LOUVO PRA SEMPRE, JESUS.
/FINAL
EU TE LOUVO PRA SEMPRE, JESUS. (2X)
');
