INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ba0b296e-ee23-4257-bee4-4c569ca1cdf8', 'Eis-me Aqui', '', '', '', '', '', 'EIS-ME AQUI, PRA TE SERVIR,
TUA PRESENÇA ME ALEGRA,
E TEU AMOR ME COMPLETA,
ME RESTAURA, DÁ SENTIDO
AO MEU VIVER.

EIS-ME AQUI PARA OBEDECER A TUA VOZ,
E ANDAR POR ONDE QUERES
E PRA SER O QUE QUISERES,
QUE DAREI A TI SENHOR,
POR TEU INFINITO AMOR.

*CORO
MINHA VIDA TE ENTREGO,
MEU FUTURO É TEU,
TUA VONTADE SERÁ A MINHA,
E O SANGUE DE JESUS
ME ATRAIU, PRA TUA LUZ.

EU QUERO VIVER SÓ PRA TI,
TE AMAR TE SEGUIR ATÉ O FIM;
MINHA VIDA A TI CONSAGRAR,
E QUE NADA DESVIE O MEU OLHAR,
SEI QUE EU NADA SOU,
EU NADA SOU SEM TI.

*CORO
MINHA VIDA TE ENTREGO,
MEU FUTURO É TEU,
TUA VONTADE SERÁ A MINHA,
E O SANGUE DE JESUS
ME ATRAIU, PRA TUA LUZ.

EU QUERO VIVER SÓ PRA TI,
TE AMAR TE SEGUIR ATÉ O FIM;
MINHA VIDA A TI CONSAGRAR,
E QUE NADA DESVIE O MEU OLHAR,
SEI QUE EU NADA SOU,
MAS HOJE DIGO EIS ME AQUI.
SEI QUE NADA SOU,
EU NADA SOU SEM TI.
');
