INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ba287124-e100-487f-91cb-09504ad051a3', 'Clamo a ti', '003', 'Jo.C.F', 'Básico', 'Dm', 'Clamor', '(2X)
CLAMO A TI, Ó MEU SENHOR,
CLAMO A TI, MEU SALVADOR,
PELO TEU SANGUE, QUE É VIDA,
Ó BENDITO, VEM ME LIBERTAR.
QUANDO ALÉM DO VÉU ENTRAR,
IREI TE DAR TODO O MEU SER,
EM TUA PRESENÇA, TE ADORAR, TE BENDIZER.
CLAMO A TI, Ó MEU SENHOR,
CLAMO A TI, MEU SALVADOR,
PELO TEU SANGUE, QUE É VIDA,
Ó BENDITO, VEM ME LIBERTAR.
');
