INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bb2091a6-299e-4048-8868-8c98e0fa2ccf', 'Ó Exaltai Jesus Senhor', '', '', '', '', '', 'O NOME DO SENHOR HÁ DE SER EXALTADO,
A MAJESTADE REVELOU.
O NOME DO SENHOR HÁ DE SER EXALTADO,
NACÕES RENDERÃO LOUVOR

Ó POVOS COM GOZO PROCLAMAI!
E GLÓRIA LHE OUTORGAI
EXALTAI, O SANTO NOME
EXALTAI, EXALTAI,
EXALTAI O SANTO NOME!
EXALTAI, O SANTO NOME!

A FORÇA DO SENHOR HÁ DE SER EXALTADA.
PODER SUPREMO QUIZ MOSTRAR.
A FORÇA DO SENHOR HÁ DE SER EXALTADA.
NAÇÕES ELE QUER SALVAR.
ACEITAI CRISTO SALVADOR E REI
SEU NOME BENDIZEI.

EXALTAI, O SANTO NOME!
EXALTAI, EXALTAI,
EXALTAI O SANTO NOME!
EXALTAI, O SANTO NOME!

O REINO DO SENHOR HÁ DE SER EXALTADO
SEU GRANDE AMOR NÃO FALHARÁ.
O REINO DO SENHOR HÁ DE SER EXALTADO
POIS TUDO ELE VENCERÁ!
ESFORÇAI POR VIVER EM RETIDÃO
E GOZAREIS PERDÃO.

EXALTAI, O SANTO NOME!
EXALTAI, EXALTAI,
EXALTAI O SANTO NOME!
EXALTAI, O SANTO NOME!
/VINDE EXALTAI!
Ó EXALTAI!
VINDE EXALTAI!
');
