INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bb38b7e8-ce7a-4223-ab33-adeaff59a168', 'Jesus Voltará vou me preparar', '', '', '', '', '', 'JESUS VOLTARÁ, VOU ME PREPARAR,
QUE DIA GLORIOSO QUANDO ELE VOLTAR!
JESUS VOLTARÁ, NA GLÓRIA ESTAREI,
COM OS ANJOS CANTANDO
A JESUS LOUVAREI!
INSTRUMENTOS

JESUS REUNIDO COM SUA IGREJA FIEL,
SERÁ UMA FESTA COM TODOS NO CÉU!
JESUS VOLTARÁ, NA GLÓRIA ESTAREI,
COM OS ANJOS CANTANDO
A JESUS LOUVAREI!
FINAL
A JESUS LOUVAREI! A JESUS LOUVAREI!
');
