INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bcaf05ee-04ea-4dfd-9bf5-e67721475aec', 'Somos Teu Povo, Tua Igreja', '216', 'Eloísa Helena Malavasi Ribeiro', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'SOMOS TEU POVO, TUA IGREJA,
MORRESTE POR NÓS, SENDO REI, SENHOR!
QUISESTE SALVAR O MUNDO,
MAS O MUNDO NÃO QUIS.

A TUA IGREJA TE AMA
E FAZ DO TEU SANGUE ESCUDO FORTE.
A TUA PALAVRA É ALIMENTO FORTE
QUE FAZ NOSSA VIDA FELIZ!

FINAL 2X
A TUA IGREJA TE ESPERA, NÃO SE APRESSA,
PORQUE TU, JESUS, VOLTARÁS
E A LEVARÁS PARA UM LAR DE PAZ,
ONDE REINA O AMOR.
');
