INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bcc1e22a-e75e-43d2-b717-42f36335f450', 'Uma voz me disse lá do céu', '394', 'Autor Desconhecido', 'Balada', 'A', 'Santificação e Derramamento', 'UMA VOZ ME DISSE LÁ DO CÉU:
CANTA, CANTA, CANTA PARA MIM;
ORA, ORA, ORA UMA VEZ MAIS;
SEGUE, SEGUE, SEGUE APÓS MIM;
Ó VEM SER FIEL ATÉ À MORTE,
E EU SEREI CONTIGO ATÉ O FIM;

FINAL 2X
LOGO ESTARÁS AQUI NO CÉU
ONDE TENS UMA COROA
PREPARADA PARA TI.
');
