INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bcd176bf-f637-4f0c-b82f-983f1c0c1c6a', 'Eu vou contar uma história (Zaqueu)', '064', 'M.L.M.B.O. & F.B.O.G.', 'Country', 'D', 'Crianças e Adolescentes', 'EU VOU CONTAR UMA HISTÓRIA
PRA VOCÊ NÃO ESQUECER.
A HISTÓRIA DE UM HOMEM
QUE A JESUS QUERIA VER.

SUBIU EM UMA ÁRVORE
PRA VER JESUS PASSAR
POIS ERA TÃO PEQUENO,
NÃO PODIA O AVISTAR.

OLHANDO PARA CIMA
JESUS ENCONTROU,
COM SUA VOZ SUAVE
ENTÃO ELE FALOU:

"ZAQUEU DESCE DEPRESSA
PORQUE HOJE ME CONVÉM
POUSAR EM TUA CASA,
VEM DEPRESSA, Ó SIM, VEM!"

ZAQUEU ENTÃO DESCEU
QUANDO JESUS O CONVIDOU,
JESUS MUDOU SUA VIDA,
EM OUTRO HOMEM SE TORNOU.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('bcd176bf-f637-4f0c-b82f-983f1c0c1c6a', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
