INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bd407d00-54a2-4bc2-862e-d8c6f82f34bb', 'Não há batalhas', '', '', '', '', '', 'NÃO HÁ BATALHAS QUE O SENHOR NÃO POSSA VENCER;
NÃO HÁ PROMESSAS QUE O SENHOR NÃO POSSA CUMPRIR.
NÃO HÁ MILAGRES QUE O SENHOR NÃO POSSA FAZER;
E NÃO HÁ ALMA QUE O SENHOR NÃO POSSA REMIR.

SEU NOME É LEÃO DE JUDÁ,
SEU NOME É RAIZ DE DAVI,
RESPLANDECENTE ESTRELA DA MANHÃ.

*CORO
NÃO HÁ BATALHAS QUE O SENHOR NÃO POSSA VENCER;
NÃO HÁ PROMESSAS QUE O SENHOR NÃO POSSA CUMPRIR.
NÃO HÁ MILAGRES QUE O SENHOR NÃO POSSA FAZER;
E NÃO HÁ ALMA QUE O SENHOR NÃO POSSA REMIR.

O VERBO VIVO, POR NÓS VENCEU;
RESSUSCITOU JESUS O FILHO DE DEUS.
DEUS DO IMPOSSÍVEL PARA O QUE NELE CRÊ,
NÃO HÁ LIMITES DIANTE DO SEU PODER.

*CORO 2X
O SENHOR DESTROÇA OS CARROS,
QUEBRANTA OS ARCOS,
DESFAZ OS GRILHÕES. 
O SENHOR DERRUBA MURALHAS,
VENCE BATALHAS,
DESMANCHA PRISÕES.

SEU NOME É LEÃO DE JUDÁ,
SEU NOME É RAIZ DE DAVI,
RESPLANDECENTE ESTRELA DA MANHÃ.
/FINAL
SEU NOME É
');
