INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bd5492ae-121b-4b13-af3f-6a64a7600478', 'Hoje eu descobri', '', '', '', '', 'Avulsos', 'HOJE EU DESCOBRI A FORMA DE VIVER FELIZ,
A CRISTO EU ENTREGUEI A MINHA VIDA E ESPEREI,
A SOLUÇÃO DOS MEUS PROBLEMAS.
E A RESPOSTA EM CRISTO EU ACHEI.

HOJE EU VIVO BEM E A SUA PAZ EU ENCONTREI,
O FARDO TÃO PESADO
NO CAMINHO EU DEIXEI.
ELE O TOMOU EM SUA CRUZ E DISSE-ME:
“FILHO MEU, TE ALIVIAREI”.

*CORO
FICA SENHOR, EM MEU CORAÇÃO,
MORA SENHOR, EM MEU CORAÇÃO.
/INSTRUMENTOS

HOJE EU VIVO BEM E A SUA PAZ EU ENCONTREI,
O FARDO TÃO PESADO
NO CAMINHO EU DEIXEI.
ELE O TOMOU EM SUA CRUZ E DISSE-ME:
“FILHO MEU, TE ALIVIAREI”.
/FINAL 2X
FICA SENHOR, EM MEU CORAÇÃO,
MORA SENHOR, EM MEU CORAÇÃO.
');
