INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bd6ecb12-69f0-4a89-8c34-03ce5f9a4b07', 'Avante, avante, ó crentes', '719', '', 'Marcha Marcial', 'Ab', 'Grupo de Louvor', 'AVANTE, AVANTE, Ó CRENTES,
SOLDADOS DE JESUS!
ERGUEI SEU ESTANDARTE,
LUTAI POR SUA CRUZ!
E CONTRA OS INIMIGOS,
EM GRANDES MULTIDÕES
O EXCELSO COMANDANTE
DIRIGE OS BATALHÕES.

AVANTE, AVANTE, Ó CRENTES,
POR CRISTO PELEJAI!
VESTI SUA ARMADURA,
EM SEU PODER MARCHAI!
NO POSTO SEMPRE ACHADOS,
VELANDO EM ORAÇÃO,
EM MEIO AOS PERIGOS
SEGUINDO O CAPITÃO!
/INSTRUMENTOS

AVANTE, AVANTE, Ó CRENTES,
A PASSO TRIUNFAL!
APÓS COMBATE HORRENDO;
VIRÁ A PAZ FINAL!
ENTÃO, ETERNAMENTE,
SERÁ O VENCEDOR,
NO CÉU GLORIFICADO
COM CRISTO, O SALVADOR!
');
