INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bd7a12c5-7d86-43d1-842a-fb9f96e458b5', 'O Grande Relógio', '769', '', 'Balada', 'G', 'Corinhos', 'O GRANDE RELÓGIO JÁ DEU O SINAL
DESPERTA QUE É HORA VAMOS TRABALHAR
EM BUSCA DAS ALMAS PERDIDAS QUE ESTÃO
FALANDO BEM ALTO AO SEU CORAÇÃO.

CORO 2X
DESPERTA QUE É HORA, 
O MESTRE JÁ VEM, 
JÁ VEM EM CAMINHO 
DE JERUSALÉM! 

A LUZ SE APAGA O DIA FINAL
NÃO OLHES ATRÁS, POIS É TEMPO AINDA.
NÃO TE DETENHAS, POIS JESUS TE CHAMA.
ELE TE QUER E AINDA TE AMA.

JESUS É O CAMINHO, A VERDADE E A VIDA.
NINGUÉM VAI AO PAI A NÃO SER POR JESUS.
LÁ NO CÉU SÓ ENTRA QUEM FOR ENCONTRADO,
LAVADO NO SANGUE VERTIDO NA CRUZ.
');
