INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bd86318e-56b2-42da-a049-624c7d67353f', 'No caminho eu quero estar', '158', 'C.M.V.C.S.', 'Fox Abafado', 'E', 'Crianças e Adolescentes', 'NO CAMINHO EU QUERO  ESTAR,
AO SENHOR, VOU OBEDECER.
AONDE QUER QUE DEUS MANDAR
ANUNCIAR O SEU AMOR,
ESTOU PRONTO, SENHOR, EU VOU!

TANTAS VIDAS NÃO CONHECEM O SENHOR,
VIVEM TRISTES, TÃO VAZIAS, SEM AMOR,
PRECISANDO RECEBER O SEU PERDÃO,
PARA ASSIM ALCANÇAREM A SALVAÇÃO,

QUE JESUS LÁ NO CALVÁRIO REVELOU,
QUANDO SEU PRECIOSO SANGUE DERRAMOU,
CONCEDENDO VIDA ETERNA AO QUE CRER,
TRANSFORMANDO SUAS VIDAS, QUE PRAZER!

QUE ALEGRIA PODER SERVIR A JESUS,
NOSSO SALVADOR!
EM SUA OBRA TRABALHAR,
ATENDENDO AO SEU CHAMAR,
ESTOU PRONTO, SENHOR, EU VOU! (3X)
');
