INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bda0d463-0036-4e9c-ae7a-78b3ff2df347', 'Chegado a cruz do meu Salvador', '774', '', 'Fox', 'E', 'Corinhos', 'CHEGANDO A CRUZ DO MEU SALVADOR,
PROSTRADO AOS PÉS DO MEU REDENTOR.
ELE ATENDEU AO MEU CLAMOR:
GLÓRIA AO SALVADOR!

CORO
GLÓRIA AO SALVADOR,
GLÓRIA AO SALVADOR!
AGORA SEI QUE ELE ME SALVOU:
GLÓRIA AO SALVADOR!

QUE MARAVILHA, JESUS ME AMOU!
TUDO DE GRAÇA ME PERDOOU.
QUEBROU MEUS LAÇOS E ME LIVROU:
GLÓRIA AO SALVADOR!
');
