INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bdb1375d-c356-4279-87c3-f8c60578896d', 'Estamos aqui, ó Deus', '620', 'Autor Desconhecido', 'Básico', 'G', 'Louvor', 'ESTAMOS AQUI, Ó DEUS,
