INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('be16b3c5-2e4f-46df-9106-b0a87f43f37a', 'Há um lugar pra mim', '538', 'Jorgemar Souza Madeira', 'Básico', 'G', 'Volta de Jesus e Eternidade', 'HÁ UM LUGAR PRA MIM
CHEIO DE AMOR,
COM O MEU JESUS MORAR,
COM OS ANJOS HABITAR.

*CORO
LÁ NÃO TEREI MAIS DOR,
(LÁ NÃO TEREI MAIS DOR)
SÓ GOZO E ALEGRIA,
(VEREI MEU SALVADOR)
ESPERO ANSIOSO
(ESPERO ANSIOSO)
POR VER JESUS UM DIA.

NESSE LUGAR PRA MIM,
DE ETERNA REDENÇÃO,
ENCONTRO PAZ SEM FIM
EM MEU CORAÇÃO.

*CORO 2X
LÁ NÃO TEREI MAIS DOR,
(LÁ NÃO TEREI MAIS DOR)
SÓ GOZO E ALEGRIA,
(VEREI MEU SALVADOR)
ESPERO ANSIOSO
(ESPERO ANSIOSO)
POR VER JESUS UM DIA.

FINAL
ESPERO ANSIOSO
(ESPERO ANSIOSO)
POR VER JESUS UM DIA.
');
