INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('be95ca3f-5bdb-4ce4-bfdf-ca23b98039c7', 'Se Nos Cega o Sol Ardente', '', '', '', '', '', 'SE NOS CEGA O SOL ARDENTE
QUANDO VISTO EM SEU FULGOR,
QUEM CONTEMPLARÁ AQUELE
QUE DO SOL É CRIADOR?
PATRIARCAS E PROFETAS
NÃO PUDERAM O AVISTAR.
SÓ TEVE O PRAZER DE VÊ-LO
ADÃO ANTES DE PECAR.

LUZ PRA QUAL A LUZ É TREVAS,
QUEM TE PODE CONTEMPLAR?
NOSSOS OLHOS NUS, HUMANOS,
NÃO TE PODEM ENCARAR.
FOGO EM CIMA DA ARCA SANTA,
SARÇA ARDENTE NO SINAI,
EIS FIGURAS SÓ DA GLÓRIA DO
SENHOR, DO ETERNO PAI.

PARA TERMOS NÓS COM ELE FRANCA
E DOCE COMUNHÃO, CRISTO, O FILHO
FEZ-SE CARNE, FEZ-SE NOSSA REDENÇÃO
PARA QUE NA GLÓRIA ETERNA,
NÓS VEJAMO-LO SEM VÉU.
CRISTO PADECEU A MORTE,
NOVA ENTRADA ABRINDO AO CÉU.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('be95ca3f-5bdb-4ce4-bfdf-ca23b98039c7', '45ab58b2-d293-45c7-aa75-090fcd968b24');
