INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('befde552-d902-4932-b649-c679ea69e7ce', 'O Meu Viver é Cristo', '710', '', 'Básico', 'Cm', 'Grupo de Louvor', 'O MEU VIVER É CRISTO, MEU SALVADOR,
POIS SE ENTREGOU
PARA A VIDA ETERNA ME DAR.
HOJE VENHO A TI PARA EXPRESSAR.

*CORO
TODA GRATIDÃO A TI JESUS,
PORQUE TU ÉS MARAVILHOSO.
PRA SEMPRE CANTAREI A TI, MEU REI,
POIS TU ME FIZESTE BEM.

MEU VERDADEIRO AMIGO SEMPRE FIEL.
ESCONDERIJO MEU, PARA SEMPRE EMANUEL.
ÉS O MEU SENHOR, A RAZÃO DO MEU VIVER!
HOJE VENHO A TI PARA EXPRESSAR.

*CORO 2X
TODA GRATIDÃO A TI JESUS,
PORQUE TU ÉS MARAVILHOSO.
PRA SEMPRE CANTAREI A TI, MEU REI,
POIS TU ME FIZESTE BEM.
/FINAL
POIS TU ME FIZESTE BEM.
');
