INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bf32dda5-e376-45a4-9909-3cf7023c286e', 'Varão de Guerra é o Senhor', '044', 'Maycon Nascimento', 'Maycon Nascimento', 'Am', 'Avulsos', 'VARÃO DE GUERRA É O SENHOR
QUE VAI À FRENTE DO SEU POVO.
NAS PELEJAS DA ALMA, NAS PROVAÇÕES,
NAS LUTAS CONTRA OS NOSSOS ADVERSÁRIOS.

VARÃO DE GUERRA É O SENHOR
QUE ERGUE A SUA ESPADA,
E COM LABAREDAS DE FOGO,
TOCA NOS SEUS MINISTROS
E OS TORNA CAPAZES PARA AS PELEJAS.

CORO
ESTE É O MEU DEUS,
SOBERANO EM FORÇA E PODER
O ÚNICO QUE SE ASSENTA NO TRONO DA GLÓRIA
E QUE REINARÁ
ETERNAMENTE.

FINAL
ESTE É O MEU DEUS, (ESTE É O MEU DEUS)
SOBERANO EM FORÇA E PODER
JUSTO E CUMPRIDOR DA SUA PALAVRA.
QUE NOS PROMETEU UM REI, JESUS,
PARA REINAR SOBRE NÓS (V)
NA CIDADE SANTA,
ETERNAMENTE.
');
