INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bf52f714-069e-4aed-b72f-5a5a6e96346f', 'Eu Acordei Já Louvando', '', '', '', '', '', 'CANTAR 2X
LOUVANDO A DEUS,
E CAINDO NA GRAÇA
DE TODO O POVO.
/FINAL 2X
E TODOS OS DIAS
ACRESCENTAVA O SENHOR
À IGREJA AQUELES
QUE HAVIAM DE SALVAR.
');
