INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bf7c2565-f12c-4219-b4d0-6a19ce1ddee8', 'Certa vez eu orando', '776', 'Waldemar Bourguignon', 'Balada', 'G', 'Invocação e Comunhão', 'CERTA VEZ EU ORANDO,
OUVI UMA VOZ,
ESTA VOZ ME DIZIA:
"NÃO PEQUES MAIS."
JESUS CRISTO JÁ VEM
EM UMA NUVEM BRANCA,
JESUS CRISTO JÁ VEM,
JESUS CRISTO JÁ VEM,
NÃO PEQUES MAIS.
');
