INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bfa5e345-d65a-44f3-a377-731027d86307', 'Não Há Amor Igual', '220', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Morte, Ressureição e Salvação', 'NÃO HÁ AMOR IGUAL
AO AMOR DE JESUS,
POR MIM MORREU NAQUELA CRUZ;
DEIXOU A SUA GLÓRIA, SOFREU HUMILHAÇÃO
SÓ PRA ME DAR A SALVAÇÃO.

CORO
POR ISSO DEI-LHE O MEU CORAÇÃO
E LHE ENTREGUEI TODO O MEU SER
E UM TRONO LEVANTEI PARA O MEU JESUS
SER REI EM TODO O MEU VIVER.

O QUE ELE VIU EM MIM PARA SE DAR ASSIM
POR MIM, TÃO POBRE PECADOR?
DESCEU DA SUA GLÓRIA,
SOFREU HUMILHAÇÃO
PARA ME DAR A SALVAÇÃO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('bfa5e345-d65a-44f3-a377-731027d86307', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
