INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('bfe6bb8b-e666-4e9e-921f-d5b3d8e25532', 'Como é bom servir a Deus', '046', 'A.S.L.T.', 'Básico', 'A', 'Crianças e Adolescentes', 'COMO É BOM SERVIR A DEUS
CONHECÊ-LO CADA VEZ MAIS
E VIVENDO NO SEU AMOR
SENTIR SUA PROTEÇÃO.

CORO 2X
QUE ME TRAZ SEGURANÇA, VIDA,
AMOR, PAZ E ALEGRIA.

COM MEU DEUS EU SEI QUE SOU
MAIS QUE VENCEDOR.
VOU PASSANDO AS PROVAÇÕES
FIRMADO NO SEU AMOR.
');
