INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c0ab98e3-24f5-4c34-9a95-b43e258871e0', 'Grande é o Senhor', '656', 'Let. e Mús.:Steve McEwan, Trad. Adhemar de Campos', 'Básico', 'G', 'Salmos de Louvor', 'GRANDE É O SENHOR 
E MUI DIGNO DE LOUVOR,
NA CIDADE DO NOSSO DEUS, 
SEU SANTO MONTE, 
ALEGRIA DE TODA A TERRA;

GRANDE É O SENHOR
EM QUEM NÓS TEMOS A VITÓRIA,
QUE NOS AJUDA CONTRA O INIMIGO,
POR ISSO DIANTE DELE NOS PROSTRAMOS.

FINAL 2X
QUEREMOS O TEU NOME ENGRANDECER
E AGRADECER-TE
POR TUA OBRA EM NOSSA VIDA;
CONFIAMOS EM TEU INFINITO AMOR,
POIS SÓ TU ÉS O DEUS ETERNO
SOBRE TODA A TERRA E CÉU.
');
