INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c0d2a301-7956-412d-b386-a04f2833b114', 'Ele Voltará, Sim, Ele Voltará', '492', 'Rose Margareth Silva Mendes', 'Balada', 'A', 'Volta de Jesus e Eternidade', 'ELE VOLTARÁ, (SIM, ELE VOLTARÁ) (2X)
PARA BUSCAR UMA IGREJA 
A QUAL ESTÁ PREPARADA.
/ELE VOLTARÁ, (SIM, ELE VOLTARÁ) (2X)
POVO ESCOLHIDO LUTANDO COM
CRISTO NESTA BATALHA.

MAS ESTA LUTA AGORA JÁ É O FIM,
SOMOS FELIZES PORQUE NÃO ESTAREMOS AQUI;
AS TROMBETAS IRÃO SOAR
E CRISTO EM BREVE VEM NOS BUSCAR
PARA A GLÓRIA ETERNA HERDAR.
/INSTRUMENTOS

ELE VOLTARÁ, (SIM, ELE VOLTARÁ) (2X)
PARA BUSCAR UMA IGREJA 
A QUAL ESTÁ PREPARADA.
/ELE VOLTARÁ, (SIM, ELE VOLTARÁ) (2X)
POVO ESCOLHIDO LUTANDO COM CRISTO
NESTA BATALHA.

MAS ESTA LUTA AGORA JÁ É O FIM,
SOMOS FELIZES PORQUE NÃO ESTAREMOS AQUI;
/FINAL 2X
AS TROMBETAS IRÃO SOAR
E CRISTO EM BREVE VEM NOS BUSCAR
PARA A GLÓRIA ETERNA HERDAR.
');
