INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c113f5a7-682d-4b1b-abda-f7fdce2ecde3', 'Há uma linda morada', '185', 'M.L.M.B.O; F.B.O.G.', 'Fox Abafado', 'D', 'Crianças e Adolescentes', 'HÁ UMA LINDA MORADA PRA MIM NO CÉU
QUE JESUS FOI ALI PREPARAR;
UM LUGAR DE DELÍCIAS E AMOR SEM FIM,
COM JESUS VOU PRA SEMPRE MORAR.

FINAL 2X
NA CIDADE DE DEUS,
NOVA JERUSALÉM,
ONDE O SOL NÃO PRECISA BRILHAR;
O CORDEIRO É A LUZ
QUE ILUMINA A CIDADE
ONDE VOU PARA SEMPRE MORAR.
');
