INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c1d7f547-b242-4e10-aea5-6f97b2157292', 'Jesus Sempre Te Amo', '', '', '', '', '', '(M) JESUS, SEMPRE TE AMO
(M) PORQUE SEI QUE ÉS MEU;
(M) FELIZ EU TE RENDO LOUVOR
(M) QUE É SÓ TEU.
/(H) MEU MESTRE DIVINO,
(H) SENHOR E MEU DEUS,
(H) PRA SEMPRE HEI DE AMAR-TE
(H) MEU CRISTO, MEU REI.

EU TE AMO PORQUE TU MORRESTE POR MIM;
EU TE AMO PORQUE TEU AMOR NÃO TEM FIM.
EM TI CONFIANÇA PRA SEMPRE TEREI;
PRA SEMPRE HEI DE AMAR-TE MEU REI.

EU TE AMO NA VIDA, NA MORTE TAMBÉM;
SEMPRE HEI DE LOUVAR-TE NA GLÓRIA DE ALÉM;
AGORA E PRA SEMPRE POR TI VIVEREI;
SEMPRE HEI DE AMAR-TE,
MEU CRISTO, MEU REI.
SEMPRE HEI DE AMAR-TE,
MEU CRISTO, MEU REI.
');
