INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c21a88ca-0ae8-4564-a1f0-e17a79244474', 'Minh''Alma Cantará', '', '', '', '', '', 'O SENHOR É O MEU PASTOR E NADA ME FALTARÁ
O DESERTO OU O VALE ELE OS TRANSFORMARÁ
EM MANANCIAIS DE ÁGUAS MINHA VIDA FARTARÁ.

MINH’ALMA CANTARÁ E ANUNCIARÁ
O TEU LOUVOR, SENHOR, MEU REI!
MINH’ALMA CANTARÁ E ANUNCIARÁ
O TEU LOUVOR SENHOR MEU REI!

DAVI OROU, LUTOU,
SALMODIOU, VENCEU!
SENHOR MEU ESTOU AQUI
PARA TE HONRAR.

JESUS, FILHO DE DEUS,
O NOSSO BOM PASTOR
NOS RESGATOU PARA HERDARMOS
A GLORIA ETERNA.
/FINAL
O TEU LOUVOR,
SENHOR, MEU REI!
');
