INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c24cb986-e6a1-4eb3-bbd3-6e3c473fee12', 'Existem segredos na tua palavra', '160', 'M.L.M.B.O.', 'Repique', 'D', 'Crianças e Adolescentes', 'EXISTEM SEGREDOS NA TUA PALAVRA
QUE SÓ TEU ESPÍRITO PODE REVELAR.
ENSINOS DE VIDA, DE FELICIDADE,
CAMINHO DE LUZ QUE JESUS VEIO NOS DAR.

É LIVRO SELADO, MISTÉRIO GUARDADO,
QUE O HOMEM SEM DEUS NÃO PODE ALCANÇAR.
É LIVRO ABERTO, CLARO, DESCOBERTO,
/CANTAR 2X
PARA OS SERVOS FIÉIS
QUE COM JESUS VÃO REINAR.
');
