INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c29975e8-b5ab-4ca5-a9ea-568994e0dad6', 'Eis que Estou à Porta', '222', 'Josué Rodrigues', 'Básico', 'C', 'Morte, Ressureição e Salvação', 'CANTAR 2X
EIS QUE ESTOU À PORTA E BATO,
SE ALGUÉM OUVIR MINHA VOZ
E ABRIR A PORTA,
ENTRAREI EM SEU CORAÇÃO.

FINAL 2X
E COM ELE CEAREI E ELE COMIGO;
BASTA ABRIR A PORTA,
ENTRAREI EM SEU CORAÇÃO.
');
