INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c2c9ddb4-4cfd-4f96-b0a4-e1253a926cf9', 'Caminhando vou para Canaã', '771', '', 'Country', 'G', 'Corinhos', 'CAMINHANDO VOU PARA CANAÃ. (3X)
GLÓRIA DEUS, CAMINHANDO VOU PARA CANAÃ.

CORO
SE VOCÊ NÃO VAI, NÃO IMPEÇA A MIM. (3X)
GLÓRIA DEUS, CAMINHANDO VOU PARA CANAÃ.

CAMINHANDO VOU ABRAÇAR JESUS. (3X)
GLÓRIA A DEUS,
CAMINHANDO VOU ABRAÇAR JESUS.
');
