INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c2d9cb24-2421-470b-92f9-3ebfe8718a5a', 'Muitos São Os Que Confiam', '372', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'G', 'Grupo de Louvor', 'MUITOS SÃO OS QUE CONFIAM
EM SUA FORÇA E SEU SABER
E POR ISSO SE ENCURVAM,
CAEM SEM PODER VENCER;

MAS EU FAÇO MENÇÃO DO TEU NOME,
SÓ EM TI CONFIAREI,
E NO DIA DA PELEJA E ANGÚSTIA
COMIGO ESTARÁS, MEU REI!

LEMBRA-TE DA MINHA OFERTA,
OUVE A MINHA PETIÇÃO
E EU ME ALEGRAREI COM JÚBILO
PELA TUA SALVAÇÃO;

FINAL 2X
EM TEU NOME ARVORAREI BANDEIRAS,
POIS COMIGO ESTÁS, SENHOR;
EM TEU NOME SALTAREI BARREIRAS
E SEREI UM VENCEDOR!
');
