INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c31040e8-6efe-458f-ac9e-f3266423248d', 'Minhalma Tem Sede de Ti', '187', 'Let. e Mús.: Autor desconhecido; Trad: Sérgio Paulo Ferreira de Matos', 'Toada', 'E', 'Consolo e Encorajamento', 'MINH''ALMA TEM SEDE DE TI,
TE QUERO COM TODO O MEU SER!
NUMA TERRA SECA E SEM PAZ,
MINHA VOZ CLAMA POR DEUS,
SÓ TUA PRESENÇA, SENHOR, ME SATISFAZ!

CANTAR 2X
POR ISSO VENHO, SENHOR,
AO TEU SANTUÁRIO
TUA GLÓRIA CONTEMPLAR!
TE DOU MEU LOUVOR, TE DOU MEU AMOR,
MINHA VIDA PONHO EM TEU ALTAR,
EU TE AMO, MEU SENHOR!
/FINAL
SENHOR, EU VENHO TE ADORAR!
');
