INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c32f3e18-d4eb-41af-b61d-f6707355d095', 'Meditarei nas maravilhas do Senhor', '658', 'W.A./C/V.', 'Básico', 'E', 'Salmos de Louvor', 'MEDITAREI NAS MARAVILHAS DO SENHOR
E FALAREI DO SEU PODER ENTRE AS NAÇÕES 
CELEBRAREI A MAJESTADE DO SENHOR,
PROCLAMAREI SUA JUSTIÇA SOBRE A TERRA.
PORQUE GRANDES SÃO AS TUAS OBRAS,
TU ÉS FIEL ETERNAMENTE.

CANTAR 2X
EXALTAR-TE-EI, Ó DEUS
POIS TU ÉS MEU REI,
GLORIFICAREI TEU NOME
ENQUANTO EU VIVER.
/FINAL 4X
PERTO ESTÁ O SENHOR
DOS QUE O INVOCAM.
');
