INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c35957c2-b2a8-4309-9e96-740aa4f46118', 'Jesus, O Que Eu Mais Quero No Mundo', '406', 'Sebastião Francisco Pinto Filho', 'Valseado', 'C', 'Santificação e Derramamento', 'JESUS, O QUE EU MAIS QUERO NO MUNDO
É VIVER PARA TI,
TE SERVIR POIS FIZESTE JÁ TUDO POR MIM;
MINHA VIDA MUDASTE
E TEU AMOR ME MOSTRASTE,

MUITAS COISAS EU PUDE, ENTÃO, VER,
GRANDE AMOR INUNDOU O MEU SER,
NÃO REJEITASTE O MEU CORAÇÃO
QUANDO CURVEI-ME A TI EM ORAÇÃO.

*CORO
TUDO NA VIDA DEPENDE DE FÉ,
DE CONFIARMOS EM TI, COMO ÉS;
SEMPRE ME GUIAS, ÉS DEUS DE AMOR;
CRISTO, ÉS TUDO PARA MIM.
/INSTRUMENTOS

*CORO
TUDO NA VIDA DEPENDE DE FÉ,
DE CONFIARMOS EM TI, COMO ÉS;
SEMPRE ME GUIAS, ÉS DEUS DE AMOR;
CRISTO, ÉS TUDO PARA MIM.
/FINAL
CRISTO, ÉS TUDO PARA MIM.
');
