INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c35e5942-cea5-499c-b30b-e105d9c20c95', 'O Que Os Olhos Nunca Viram', '', '', '', '', '', 'O QUE OS OLHOS NUNCA VIRAM
E O CORAÇÃO NUNCA SENTIU
DEUS PREPAROU EM SEU FAVOR
PARA TE ABENÇOAR.
ABRA SEU CORAÇÃO,
E DEIXE QUE A LUZ VENHA BRILHAR
EM SEU VIVER ETERNAMENTE.

*CORO
ENTÃO COMECE A GLORIFICAR
PELO QUE AINDA NÃO VIU.
SE DEUS PROMETEU VAI SE
CUMPRIR SUA BÊNÇÃO VAI CHEGAR.

ABRA SEU CORAÇÃO
E DEIXE QUE A LUZ
VENHA BRILHAR
EM SEU VIVER ETERNAMENTE.

*CORO 2X
ENTÃO COMECE A GLORIFICAR
PELO QUE AINDA NÃO VIU.
SE DEUS PROMETEU VAI SE
CUMPRIR SUA BÊNÇÃO VAI CHEGAR.

CANTAR 2X
DEUS TEM SEMPRE O MELHOR
MESMO QUE A LUZ
NÃO BRILHE EM SEUS OLHOS.
VÊ DEUS AMA VOCÊ
JÁ DECRETOU A SUA VITÓRIA
/FINAL
BASTA CRER, BASTA CRER.
');
