INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c37f8deb-2386-4295-a31f-eb81382b1d3d', 'Jesus, em Tua Presença', '221', 'Asaph Roque de Souza Borba', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'JESUS, EM TUA PRESENÇA,
REUNIMO-NOS AQUI,
CONTEMPLAMOS TUA FACE
E RENDEMO-NOS A TI.
POIS UM DIA A TUA MORTE 
TROUXE VIDA A TODOS NÓS
E NOS DEU COMPLETO ACESSO 
AO CORAÇÃO DO PAI.
/INSTRUMENTOS

JESUS, EM TUA PRESENÇA,
REUNIMO-NOS AQUI,
CONTEMPLAMOS TUA FACE
E RENDEMO-NOS A TI.
POIS UM DIA A TUA MORTE 
TROUXE VIDA A TODOS NÓS
E NOS DEU COMPLETO ACESSO 
AO CORAÇÃO DO PAI.

O VÉU QUE SEPARAVA JÁ NÃO SEPARA MAIS,
A LUZ, QUE OUTRORA APAGADA, AGORA BRILHA
E CADA DIA BRILHA MAIS.

FINAL 2X
SÓ PRA TE ADORAR,
E FAZER TEU NOME GRANDE
E TE DAR O LOUVOR QUE É DEVIDO,
ESTAMOS NÓS AQUI.
');
