INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c3a27d9e-d169-4331-aeca-d5f52cbacf21', 'Nós somos uma voz', '149', 'M.M.B.', 'Marcha Marcial', 'D', 'Crianças e Adolescentes', 'NÓS SOMOS UMA VOZ
QUE CLAMA NO DESERTO,
NESTE MUNDO DE ILUSÕES
PROCLAMAMOS A MENSAGEM DE SALVAÇÃO.

DEUS AMA O QUE SE APRESSA,
ELE AMA O EVANGELISTA,
AMA AQUELE QUE SE APRESSA
PRA ANUNCIAR A SALVAÇÃO
EM NOME DE JESUS.

NÓS SOMOS UMA VOZ
QUE CLAMA NO DESERTO,
NESTE MUNDO DE ILUSÕES
PROCLAMAMOS A MENSAGEM DE SALVAÇÃO.

DEUS AMA O QUE SE APRESSA,
ELE AMA O EVANGELISTA,
AMA AQUELE QUE SE APRESSA
PRA ANUNCIAR A SALVAÇÃO
EM NOME DE JESUS.
');
