INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c3c481dc-0334-4937-8f57-7ba0ea053c4e', 'No céu um dia vamos morar', '206', 'R.C.B.Z.', 'Básico', 'C#', 'Crianças e Adolescentes', 'CANTAR 2X
