INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c3e05813-d2a2-4f41-815b-bc21d3da4b49', 'Restaura', '', '', '', '', '', 'RESTAURA MEU SER
RESTAURA MEU VIVER
RESTAURA MINHA DESILUSÃO
RESTAURA MEU QUEBRANTADO CORAÇÃO
RESTAURA MEUS SONHOS,
RESTAURA OS MEUS PLANOS, SENHOR.

RESTAURA MINHA VIDA POR COMPLETO
PRA QUE TODOS SAIBAM
QUE TU ÉS MEU DEUS.

*CORO
PORQUE TEU É O PODER E O LOUVOR
PORQUE TU ÉS A PAZ E O AMOR
A TI TODA A HONRA E GLÓRIA RENDEMOS,
SENHOR GRANDIOSO É TEU AGIR EM NOSSAS VIDAS.
RESTAURA.

RESTAURA MEUS SONHOS,
RESTAURA OS MEUS PLANOS, SENHOR
RESTAURA MINHA VIDA POR COMPLETO
PRA QUE TODOS SAIBAM QUE TU ÉS MEU DEUS.

*CORO 2X
PORQUE TEU É O PODER E O LOUVOR
PORQUE TU ÉS A PAZ E O AMOR
A TI TODA A HONRA E GLÓRIA RENDEMOS,
SENHOR GRANDIOSO É TEU AGIR EM NOSSAS VIDAS.

FINAL
RESTAURA,
RESTAURA,
RESTAURA.
');
