INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c4209d2f-cd90-419d-8bcf-56399b458d16', 'É teu sangue, meu Senhor Jesus', '007', 'J.J.G.', 'Básico', 'A', 'Crianças e Adolescentes', 'É TEU SANGUE, MEU SENHOR JESUS,
QUE GARANTE A NOSSA COMUNHÃO.
É TEU SANGUE, MEU SENHOR JESUS,
QUE NOS TRAZ LIBERTAÇÃO.
/FINAL 2X
POR ISSO VOU CLAMAR
E O SENHOR VAI ME PURIFICAR
E PRONTO ESTAREI
PRA SERVIR NA CASA DO MEU REI!
');
