INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c498dc79-50d1-41c8-b9cf-ffe012f4f40f', 'Somos cidadãos do céu', '156', 'E.C.', 'Marcha Marcial', 'E', 'Crianças e Adolescentes', 'SOMOS CIDADÃOS, CIDADÃOS DO CÉU.
