INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c4b51273-c53f-46b9-9558-b89ac9a0f8b4', 'Cordeiro eterno', '027', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'E', 'Clamor', 'CORDEIRO ETERNO, VIESTE PRA ME DAR
TUA VIDA, TEU SANGUE,
PRA QUE EU PUDESSE TER
A VIDA ETERNA E O PERDÃO,
A CURA, A PAZ, LIBERTAÇÃO,
CORDEIRO ETERNO DE DEUS.

E HOJE TEU SANGUE
ESTÁ AGINDO EM MIM,
LIMPANDO, CURANDO,
MUDANDO O MEU SER,

CANTAR 2X
OH! QUE PODER E VIDA HÁ
NO SANGUE QUE JESUS VERTEU,
CORDEIRO ETERNO DE DEUS.
/FINAL
CORDEIRO ETERNO DE DEUS.
');
