INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c589495e-bfd7-4d0c-b413-bcb4eaf08e9b', 'Desejei Ardentemente', '444', 'Everaldo Cavalcante Lima', 'Básico', 'Gm', 'Santificação e Derramamento', 'CANTAR 2X
