INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c6430f52-fe3c-475b-960b-81566c0f2cde', 'Vi um novo céu', '478', 'Josué Plantickow Sant’ana; Rodrigo Oliveira Martins', 'Básico', 'D', 'Volta de Jesus e Eternidade', 'CANTAR 2X
VI UM NOVO CÉU, UMA NOVA TERRA,
EU VI A NOVA JERUSALÉM.

VI UM TRONO BRANCO E SOBRE ELE UM SER,
CUJO ROSTO EU NÃO PUDE VER
MAS EU SEI QUE ERA O MEU JESUS.

VI UM CORO CELESTIAL, VI OS ANJOS DE DEUS
QUE CANTAVAM EM UMA SÓ VOZ:
VIVA O REI JESUS!
/INSTRUMENTOS

CANTAR 2X
EM BREVE ESTAREMOS NESSE NOVO LAR,
CANTANDO: VIVA O REI JESUS!
/EM RUAS DE OURO NÓS VAMOS ANDAR,
DA ÁRVORE DA VIDA DESFRUTAR.

(M) E COM JESUS PARA SEMPRE MORAR,
(H) (VOU MORAR)
(M) E COM JESUS PARA SEMPRE MORAR,
(H) (VOU MORAR)
E COM JESUS PARA SEMPRE MORAR.
');
