INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c663eca1-0f22-4f6f-9aa9-889166941c6f', 'Esta canção', '230', 'R.T.F.', 'Básico', 'A', 'Crianças e Adolescentes', 'ESTA CANÇÃO É PARA TI, JESUS,
DO MEU CORAÇÃO
TIREI ESTE LOUVOR:
/CANTAR 2X
MEU DEUS BENDITO,
GLÓRIA, GLÓRIA.

O MEU LOUVOR PERTENCE SÓ A TI,
TEUS ANJOS SEMPRE LOUVAM,
A ELES VOU ME UNIR.

FINAL 2X
PRA SEMPRE, GLÓRIA,
GLÓRIA, GLÓRIA;
');
