INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c67cf32f-6ca8-4faa-85e5-ff0dcd7d2376', 'Deus é Contigo', '327', 'Autor Desconhecido', 'Fox', 'C', 'Consolo e Encorajamento', 'DEUS É CONTIGO, É SÓ A ELE ORAR,
DEUS É CONTIGO, DO MAL TE LIVRARÁ;
MISERICÓRDIA A TI VIRÁ,
DEUS É CONTIGO, SE A ELE ORAR.

CANTAR 2X
DEUS É CONTIGO, TUDO ELE VÊ DOS CÉUS,
E TE PROTEGE DOS INIMIGOS TEUS;
A CADA DIA RENOVA O AMOR,
DEUS É CONTIGO, ELE É O SENHOR.
/FINAL
DEUS É CONTIGO,
DEUS É CONTIGO, ATÉ O FIM.
');
