INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c8244268-e20a-4859-9e46-04b0924f1114', 'Cristo vem me buscar', '498', 'Rosimery Gomes Monteiro de Barros', 'Country', 'Dm', 'Volta de Jesus e Eternidade', 'CANTAR 2X
CRISTO VEM ME BUSCAR,
PARA O CÉU ME LEVARÁ,
O CORDEIRO PROMETIDO VOLTARÁ.

CORO
OH! GLÓRIA, ALELUIA!
MARANATA, VEM JESUS!
ESTOU COBERTO PELO SANGUE DESSA CRUZ;
TENHO O CONSOLADOR,
SUA GLÓRIA E ESPLENDOR,
SOU LIBERTO PELO PODER DO SENHOR.

CANTAR 2X
ELE MANDA ATENTO ESTAR,
VIGIAR E SEMPRE ORAR
PARA O TOQUE DA TROMBETA ESCUTAR.

CANTAR 2X
OH! QUE GOZO VOU SENTIR
COM OS ANJOS A CANTAR,
POIS COM CRISTO PARA SEMPRE VOU MORAR.
');
