INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c8267716-bfe2-4e93-977d-9853023548d7', 'Vem, visita Tua igreja', '077', 'Let.: Henry Maxwel Wright; Mús.:Thomas John Williams', 'Balada', 'Em', 'Invocação e Comunhão', 'VEM, VISITA TUA IGREJA,
Ó BENDITO SALVADOR!
SEM TUA GRAÇA, ELA MURCHA FICARÁ
