INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c8a01855-78a9-4e2e-b987-d424d87480fb', 'Súplica', 80, '', '', '', 'Avulsos', 'QUANDO EU SINTO A TRISTEZA CHEGAR, EU ORO,
QUANDO VEJO MINHA FÉ VACILAR, EU ORO, QUANDO
SINTO QUE NÃO SOU O MESMO, QUANDO PENSO QUE
NINGUÉM EU SOU, NA ORAÇÃO EU ENCONTRO O
REFÚGIO E AFASTA O TEMOR.

*CORO
QUANDO EU ORO EU FALO COM DEUS E DEUS FALA
COMIGO, LOGO ABREM-SE AS PORTAS DO CÉU E EU
NÃO SINTO O PERIGO, A ORAÇÃO É A CHAVE DE
TUDO, A ORAÇÃO DE UM SERVO FIEL, TEM PODER
PRA MOVER FORTEMENTE O CORAÇÃO DE DEUS.
/INSTRUMENTOS

QUANDO VEJO AS ONDAS QUE VÊM, EU ORO,
AJOELHADO À SOMBRA DA CRUZ, EU CHORO,
E DERRAMA O MEU PRANTO OPRIMIDO, SUPLICANDO
A BÊNÇÃO DE DEUS, LOGO EU SINTO INVADINDO
O MEU SER A PRESENÇA DE DEUS.

*CORO
QUANDO EU ORO EU FALO COM DEUS E DEUS FALA
COMIGO, LOGO ABREM-SE AS PORTAS DO CÉU E EU
NÃO SINTO O PERIGO, A ORAÇÃO É A CHAVE DE
TUDO, A ORAÇÃO DE UM SERVO FIEL, TEM PODER
PRA MOVER FORTEMENTE O CORAÇÃO DE DEUS.

FINAL
A ORAÇÃO É A CHAVE DE TUDO, A ORAÇÃO DE
UM SERVO FIEL, TEM PODER PRA MOVER
FORTEMENTE O CORAÇÃO DE DEUS.
');
