INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c8a64894-53d1-4f49-a95e-55b8d542c2d9', 'Digno é Jesus de toda glória', '', '', '', '', '', 'GRAÇAS EU TE DOU, PAI
PELO PREÇO QUE PAGOU
SACRIFÍCIO DE AMOR
QUE ME COMPROU
UNGIDO DO SENHOR.

PELOS CRAVOS EM TUAS MÃOS
GRAÇAS EU TE DOU, Ó MEU SENHOR
LAVOU MINHA MENTE E CORAÇÃO
ME DEU PERDÃO
RESTAUROU-ME A COMUNHÃO.

CORO
DIGNO É O SENHOR
SOBRE O TRONO ESTÁ SOBERANO CRIADOR
VOU SEMPRE TE ADORAR ELEVO MINHAS MÃOS
AO CRISTO QUE VENCEU
CORDEIRO DE DEUS MORREU POR MIM
MAS RESSUSCITOU
DIGNO É O SENHOR.

PELOS CRAVOS EM TUAS MÃOS
GRAÇAS EU TE DOU, Ó MEU SENHOR
LAVOU MINHA MENTE E CORAÇÃO
ME DEU PERDÃO
RESTAUROU-ME A COMUNHÃO.

FINAL
DIGNO É O SENHOR
SOBRE O TRONO ESTÁ SOBERANO CRIADOR
VOU SEMPRE TE ADORAR ELEVO MINHAS MÃOS
AO CRISTO QUE VENCEU
CORDEIRO DE DEUS MORREU POR MIM
MAS RESSUSCITOU
DIGNO É O SENHOR.
ALELUIA!
');
