INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c8be2f1d-56f8-427c-83ba-d48d81822a66', 'Teu nome é pra mim, Senhor', '680', 'Jorgemar Souza Madeira', 'Básico', 'F', 'Grupo de Louvor', '(H) TEU NOME É PRA MIM, SENHOR,
(M) MARAVILHOSO, DEUS FORTE;
(H) TEU NOME É PRA MIM, SENHOR,
(M) MARAVILHOSO, PRÍNCIPE DA PAZ.

*CORO 2X
EMANUEL É DEUS CONOSCO,
CONOSCO ESTÁ, PRA SEMPRE VIVERÁ.

(H) TEU NOME É PRA MIM, SENHOR,
(M) CONSELHEIRO, PAI DA ETERNIDADE;
(H) TEU NOME É PRA MIM, SENHOR,
(M) CONSELHEIRO, PAI DA ETERNIDADE;

*CORO 3X
EMANUEL É DEUS CONOSCO,
CONOSCO ESTÁ, PRA SEMPRE VIVERÁ.
/FINAL
(H) TEU NOME É PRA MIM, SENHOR, 
JESUS.
');
