INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c9173c80-a6e9-4068-8d69-0478523513c2', 'É bastante para mim a Tua graça', '164', 'Autor Desconhecido', 'Fox Abafado', 'C', 'Dedicação', 'É BASTANTE PARA MIM A TUA GRAÇA,
RECEBER A SALVAÇÃO E TEU PERDÃO;
É MARAVILHOSO SABER
QUE, PARA SEMPRE, COM JESUS VOU VIVER;
É BASTANTE, PARA MIM, A TUA GRAÇA.

A TUA GRAÇA É MELHOR QUE A VIDA, (2X)
/CANTAR 2X
MEUS LÁBIOS TE LOUVAM E ASSIM BENDIREI:
EM TEU NOME MINHAS MÃOS LEVANTAREI.

A TUA PRESENÇA ENCHE O MEU CORAÇÃO, (2X)
/FINAL 2X
MEUS LÁBIOS TE LOUVAM E ASSIM BENDIREI,
EM TEU NOME MINHAS MÃOS LEVANTAREI.
');
