INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c9400dfe-473e-450d-902c-7fb3cdb7e9e6', 'Castelo Forte', '469', 'Let. e Mús.: Martin Luther; Trad. Jacob Eduardo Von ML/Trad. Hafe; Adap. Débora Giestas Fernandes', 'Marcha', 'D', 'Consolo e Encorajamento', 'CASTELO FORTE É O NOSSO DEUS,
ESPADA E BOM ESCUDO;
COM SEU PODER DEFENDE OS SEUS,
SOCORRO TRAZ E PROTEÇÃO.

SABEIS QUEM É JESUS?
O QUE VENCEU NA CRUZ,
SENHOR DOS ALTOS CÉUS
E SENDO O PRÓPRIO DEUS
TRIUNFA NA BATALHA.

A NOSSA FORÇA NADA FAZ,
ESTAMOS CONVENCIDOS;
MAS NOSSO DEUS SOCORRO TRAZ
E SOMOS PROTEGIDOS.

SE TEMOS DE PERDER
RIQUEZAS, BENS QUE HOUVER,
EMBORA A VIDA VÁ,
POR NÓS JESUS ESTÁ
E DAR-NOS-Á SEU REINO.

SIM, QUE A PALAVRA FICARÁ
SABEMOS COM CERTEZA;
E NADA NOS ASSUSTARÁ
COM CRISTO POR DEFESA.

SABEIS QUEM É JESUS?
O QUE VENCEU NA CRUZ,
SENHOR DOS ALTOS CÉUS
E SENDO O PRÓPRIO DEUS
TRIUNFA NA BATALHA.
');
