INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c987a671-9d38-469b-af25-579db9b20106', 'Vives muito além do céu', 80, 'Raquel Toscano de Freitas', 'Básico', 'C', 'Invocação e Comunhão', 'VIVES MUITO ALÉM DO CÉU,
MUITO ALÉM DO QUE MEUS OLHOS PODEM ALCANÇAR,
MAS POSSO PELA FÉ TOCAR TUAS VESTES
E RECEBER DE TI GRAÇA E PAZ;
POSSO SEMPRE QUE ORO A TI, JESUS, (2X)

TU DEIXASTE TEU ESPÍRITO CONSOLADOR,
TÃO AMIGO, TÃO FIEL, AJUDADOR,
TÉ QUE VENHAS COM PODER PRA NOS BUSCAR
PRA ENTÃO ETERNAMENTE CONTIGO ESTAR;
/FINAL
JUNTO, SEMPRE, ESTAREI DE TI, JESUS, (2X)
ESTAREI DE TI, JESUS.
');
