INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c9921bba-3ddf-4067-9db4-291369d52898', 'Graças dou', '115', 'Is12:1-3; Adapt. Letr. e Mús.: Dru Stevenson', 'Básico', 'E', 'Dedicação', 'GRAÇAS DOU, Ó SENHOR,
AINDA QUE TE IRASTE CONTRA MIM;
TUA IRA SE RETIROU, TU ME CONSOLASTE.

EIS QUE DEUS É SALVAÇÃO,
CONFIAREI, E NÃO TEMEREI;
O SENHOR, MINHA FORÇA E O MEU LOUVOR;
SE TORNOU MINHA SALVAÇÃO.

*CORO 4X
COM ALEGRIA TIRAREIS ÁGUAS
DAS FONTES DA SALVAÇÃO.
/INSTRUMENTOS
/FINAL
GRAÇAS DOU, Ó SENHOR.
');
