INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c997658b-7c7e-47f1-9796-f0b149623e9b', 'Cristo é meu amigo, é meu amigo', '128', 'Autor Desconhecido', 'Country', 'D', 'Crianças e Adolescentes', 'CANTAR 2X
CRISTO É MEU AMIGO,
É MEU AMIGO,
SEGURA FIRME A MINHA MÃO!

QUANDO EU ANDO BEM,
QUANDO ESTOU DOENTE,
QUANDO ESTOU CONTENTE,
OU TRISTE ESTOU: ALELUIA!

CRISTO É MEU AMIGO,
É MEU AMIGO,
SEGURA FIRME A MINHA MÃO!

CANTAR 2X
CRISTO É MEU AMIGO,
É MEU AMIGO,
SEGURA FIRME A MINHA MÃO!

QUANDO EU ANDO BEM,
QUANDO ESTOU DOENTE,
QUANDO ESTOU CONTENTE,
OU TRISTE ESTOU: ALELUIA!

FINAL
CRISTO É MEU AMIGO,
É MEU AMIGO,
SEGURA FIRME A MINHA MÃO!
');
