INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('c9e90ad0-3fa8-4918-81b8-9c5d7f990df5', 'É Preciso Confiar e Buscar a Deus', '072', 'José Elias Simora', 'Básico', 'A', 'Invocação e Comunhão', 'É PRECISO CONFIAR E BUSCAR A DEUS,
E O SENHOR DOS EXÉRCITOS TE OUVIRÁ.
/O SENHOR TE GUIARÁ,
É PRECISO CONFIAR,
E O SENHOR DOS EXÉRCITOS TE GUIARÁ.

*CORO 2X
BUSCA A DEUS
(BUSCA A DEUS)
QUE ELE TE OUVIRÁ.
/CANTAR 2X
BUSCAI AO SENHOR
ENQUANTO SE PODE ACHAR,
INVOCAI-O ENQUANTO ESTÁ PERTO.

*CORO 2X
BUSCA A DEUS
(BUSCA A DEUS)
QUE ELE TE OUVIRÁ.
/FINAL
É PRECISO CONFIAR,
E O SENHOR DOS EXÉRCITOS TE GUIARÁ.
');
