INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ca3a7759-3ab8-44f3-9c3d-31e6b01ed57f', 'Eis que abro a porta', '727', '', 'Básico', 'A', 'Grupo de Louvor', 'EIS QUE ABRO A PORTA,
PRA DIZER AO POVO MEU:
ENTRA E VEM CEAR,
COM O VOSSO DEUS.
EU VOS DAREI NOVOS CORPOS,
POVO QUE TANTO SOFREU,
SERÃO GLORIFICADOS,
PARA VEREM O VOSSO DEUS.

SERÁ UMA LINDA FESTA,
E ELA NUNCA FINDARÁ.
NUNCA MAIS VAMOS SOFRER,
NUNCA MAIS VAMOS CHORAR.

POIS ALI CONOSCO ESTARÁ,
E VEREMOS FACE A FACE,
E PARA SEMPRE VAMOS ADORAR,
O DEUS A QUEM TANTO BUSCAMOS.
/INSTRUMENTOS

EIS QUE ABRO A PORTA,
PRA DIZER AO POVO MEU:
ENTRA E VEM CEAR,
COM O VOSSO DEUS.
EU VOS DAREI NOVOS CORPOS,
POVO QUE TANTO SOFREU,
SERÃO GLORIFICADOS,
PARA VEREM VOSSO DEUS.

SERÁ UMA LINDA FESTA,
E ELA NUNCA FINDARÁ.
NUNCA MAIS VAMOS SOFRER,
NUNCA MAIS VAMOS CHORAR.

POIS ALI CONOSCO ESTARÁ,
E VEREMOS FACE A FACE,
E PARA SEMPRE VAMOS ADORAR,
O DEUS A QUEM TANTO BUSCAMOS.
/FINAL
E PARA SEMPRE VAMOS ADORAR,
O DEUS A QUEM TANTO BUSCAMOS.
');
