INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('caa511f5-de42-4dee-a4c0-44a64b15de42', 'Motivos tenho pra louvar-te', '639', 'Eliezer de Jesus da Silva', 'Básico', 'A', 'Louvor', 'MOTIVOS TENHO PRA LOUVAR-TE, Ó DEUS,
MOTIVOS TENHO PRA DIZER: GLÓRIA A DEUS!
MOTIVOS TENHO PRA DIZER QUE TU NÃO MUDASTE,
MOTIVOS TENHO PRA FALAR DO TEU AMOR.

PELO QUE TU FIZESTE NA TUA OBRA,
PELO TEU POVO QUE A TI SE DEDICOU,
NA EXISTÊNCIA VIVA DO TEU ESPÍRITO.
/FINAL 2X
POR TUA OBRA E TEU PODER,
PELO TEU POVO SUSTENTADO AQUI.
');
