INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cb3d04c6-af36-4913-938d-a7f04a886266', 'Um Dia Jesus Desceu da Sua Glória', '210', 'Licurgo de Melo França', 'Básico', 'C', 'Morte, Ressureição e Salvação', 'UM DIA JESUS DESCEU DA SUA GLÓRIA
E AQUI VIVEU, ENTRE NÓS, COM AMOR,
FEZ MARAVILHAS, NOS DEU A VITÓRIA,
E COM SEU SANGUE NOS PURIFICOU.

CANTAR 2X
HOSANA, HOSANA AO REI NAS ALTURAS,
HOSANA, HOSANA A JESUS, O SENHOR.

MORREU NA CRUZ PELOS NOSSOS PECADOS,
SOFREU DEMAIS, SÓ PARA NOS SALVAR,
E, NA TRISTEZA, NOS TEM CONSOLADO,
SUBIU AO PAI, MAS VIRÁ NOS BUSCAR.
');
