INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cb5d8a7b-25f4-4401-99fe-2964a0dca51e', 'Eu espero ansioso por meu Deus', '480', 'Jackson de Halley Fernandes Fontes', 'Básico', 'C', 'Volta de Jesus e Eternidade', 'EU ESPERO, ANSIOSO, POR MEU DEUS, (2X)
DE, COM ELE, ESTAR PARA SEMPRE LÁ NO CÉU,
COM MEU DEUS, QUERO ESTAR PARA SEMPRE.

MUITAS LUTAS EU TEREI DE ENFRENTAR,
MUITAS LUTAS EU TEREI DE SUPORTAR,
MAS SEI QUE O MEU SENHOR
NUNCA MAIS VAI ME DEIXAR,
COM MEU DEUS QUERO ESTAR PARA SEMPRE.

COM MEU DEUS EU SOU MUITO FELIZ, (2X)
POIS SEI QUE O MEU SENHOR
NUNCA MAIS VAI ME DEIXAR,
COM MEU DEUS QUERO ESTAR
PARA SEMPRE, PARA SEMPRE, VOU ESTAR.
');
