INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cbe45953-1bed-4ae5-9438-5182b39e5012', 'Tem bom ânimo, pobre pecador', '063', 'S.G.D.', 'Country', 'D', 'Crianças e Adolescentes', 'TEM BOM ÂNIMO POBRE PECADOR,
JESUS ESTÁ PRESENTE PARA TE SALVAR;
SALVOU ZAQUEU, O RICO QUE ERA POBRE,
BUSCOU UM CEGO À BEIRA DO CAMINHO.

BARTIMEU, QUE QUERES QUE EU TE FAÇA?
/"QUE EU VEJA!" 
FOI A RESPOSTA PRONTA;
VENDO AGORA O ROSTO DE JESUS,
LOGO O SEGUIU LOUVANDO ALEGREMENTE.

PODES TER TUDO OU NADA POSSUIR
JESUS PERGUNTA AGORA:
"QUE QUERES QUE EU TE FAÇA?"
RESPONDE DEPRESSA: A TUA SALVAÇÃO;
VIDA ETERNA JESUS TE DÁ AGORA.
');
