INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cc47b5be-0955-48a5-bd2e-d408615719d5', 'Lindo lindo lindo', '526', 'Let.: Carlos Frederico Soares; Mús.: Waldemiro Duque da Silva', 'Básico', 'D', 'Volta de Jesus e Eternidade', '*CORO 2X
LINDO! LINDO! LINDO!
É NOVA JERUSALÉM.
/CIDADE SANTA DO MEU REI E SENHOR,
ANJOS E ARCANJOS HABITAM ALI;
A MORTE E A DOR JAMAIS ENTRARÃO
NESSA CIDADE ETERNA DE GOZO E DE PAZ.

*CORO 2X
LINDO! LINDO! LINDO!
É NOVA JERUSALÉM.
/INSTRUMENTOS

OH! QUANTO ALMEJO ESTAR ALI
NESSA CIDADE DE BRILHO ETERNAL,
PARA CONTEMPLAR O REI JESUS,
AQUELE QUE REVELOU A MIM SUA LUZ.
/*CORO 2X
LINDO! LINDO! LINDO!
É NOVA JERUSALÉM.
');
