INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cce878f0-17b5-4f49-bd1c-373db040aab0', 'Israel saiu do Egito', '108', 'Josué B. Lira', 'Marcha', 'E', 'Dedicação', 'ISRAEL SAIU DO EGITO,
FOI ORDEM QUE DEUS LHE DEU,
CHEGANDO AO MAR VERMELHO, 
TODO O ISRAEL TEMEU;
MONTES ALTOS DE TODOS OS LADOS,
MOISÉS LHES RESPONDEU:
NÃO TEMAS, Ó ISRAEL,
SÓ O SENHOR É DEUS.

CORO
SÓ O SENHOR É DEUS! (2X)
CANTEMOS COM MUITA ALEGRIA,
DIZENDO QUE SÓ O SENHOR É DEUS.

MOISÉS ORDENOU ÀS ÁGUAS DO MAR, 
QUE LHE OBEDECERAM,
POR TERRA SECA PASSARAM, 
PELO PODER DE DEUS;
O EXÉRCITO DE FARAÓ,
PORÉM, NO MAR PERECEU;
MIRIÃ CANTOU DIZENDO:
SÓ O SENHOR É DEUS.

NO DESERTO FALTOU ÁGUA,
ISRAEL SE ENTRISTECEU,
E TODOS SE REVOLTARAM
CONTRA O SERVO DE DEUS;
MOISÉS FEZ A ORAÇÃO, 
JEOVÁ LHE APARECEU,
DA ROCHA BROTOU ÁGUA
PELO PODER DE DEUS.

OS PROFETAS DE BAAL,
EM HOLOCAUSTOS SEUS,
CLAMARAM ATÉ O MEIO-DIA,
BAAL NÃO LHES RESPONDEU.
ELIAS FEZ A ORAÇÃO,
O FOGO DO CÉU DESCEU,
QUEIMANDO TODO O HOLOCAUSTO, 
COM O PODER DE DEUS.
');
