INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cd5d3095-975f-4719-8b77-10968c994850', 'Breve no céu Jesus há de aparecer', '508', 'Let.: Paulo Leivas Macalão, B.E. Warren; Mús.: B.E. Warren', 'Marcha', 'A', 'Volta de Jesus e Eternidade', 'BREVE NO CÉU JESUS HÁ DE APARECER,
EM GLORIOSA LUZ TODOS O HÃO DE VER;
NAQUELE DIA, ENTÃO, EU HEI DE RECEBER
DE CRISTO, O GALARDÃO, OH! QUE PRAZER!

CORO
BREVE VEREI O BOM JESUS
E VIVEREI EM PLENA LUZ;
NO LINDO CÉU, EU GOZAREI,
DE TODA A DOR, POR DEUS, LIVRE SEREI.

NA VINDA DO SENHOR DESFRUTAREI PRAZER,
QUANDO MEU SALVADOR
EM GLÓRIA APARECER;
EIS QUE ELE BREVE VEM, OS SANTOS LEVARÁ
PARA A MANSÃO DE ALÉM, DONDE VIRÁ.
');
