INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cd799802-5d55-4286-9570-f1a655c19924', 'Faze oração', '022', 'Anônimo', 'Balada', 'D', 'Crianças e Adolescentes', 'FAZE ORAÇÃO BEM CEDINHO,
AO MEIO-DIA, SIM, TAMBÉM;
FAZE ORAÇÃO À NOITINHA,
QUE É DEUS QUE TE SUSTÉM.

JÁ DE MANHÃ DEUS ESCUTA,
AO MEIO-DIA, SIM, TAMBÉM;
MESMO TE VÊ À NOITINHA,
DE TUDO TE SUSTÉM.

JÁ DE MANHÃ DEUS RESPONDE,
AO MEIO-DIA, SIM, TAMBÉM;
FAZE ORAÇÃO À NOITINHA,
POIS ELE LOGO VEM.
');
