INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cdbf028a-a5f3-4f03-a858-58047296c8ef', 'Lá no Cimo do Monte', 68, 'Sérgio Paulo Ferreira de Matos', 'Balada', 'D', 'Invocação e Comunhão', 'LÁ NO CIMO DO MONTE,
EU ESTOU ME ENCURVANDO,
BUSCANDO TUA FACE, 
MEU DIVINO SENHOR.

MEU FARDO É PESADO,
ESTOU TÃO CANSADO,
MAS SEI QUE TU ÉS AMOR.
OH! VEM RENOVAR, EM MEU CORAÇÃO,
A FÉ, O PODER, ME DÁ TUA MÃO;
RENOVA, SENHOR.

COMO TERRA SEDENTA, 
A MINH''ALMA ANSEIA
POR TEU SANTO ESPÍRITO, 
QUE DÁ VIDA E PODER.

E QUANDO ME ERGUER,
EU SEI QUE VOU TER
MAIS FORÇA E ALEGRIA;
DE GLÓRIA EM GLÓRIA ME VAIS TRANSFORMANDO,
QUANDO EU, LÁ NO MONTE, 
ESTOU ME ENCURVANDO,
BUSCANDO-TE, Ó DEUS!
');
