INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cdd4fa30-b6b0-4b49-9a28-88ce755a0ec0', 'Somos Um', '', '', '', '', '', 'SENHOR, NADA SOMOS NESTE MUNDO.
SEM TI NADA PODEMOS FAZER.
NEM AS FOLHAS DAS
ÁRVORES SE MOVEM
SE NÃO FOR PELO TEU PODER. (2X)

SENHOR, VEM OPERA MARAVILHAS!
SENHOR, VEM AOS ENFERMOS CURAR!
Ó SENHOR,
SALVA OS POBRES PECADORES
E AOS CRENTES VEM BATIZAR.
Ó SENHOR,
SALVA OS POBRES PECADORES
E AOS CRENTES VEM BATIZAR.
');
