INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ce35f5a2-7ea6-42f7-819e-204ffdf4fbc1', 'Dois Discípulos no Caminho de Emaús', '214', 'Josué B. Lira', 'Guarânia', 'D', 'Morte, Ressureição e Salvação', 'DOIS DISCÍPULOS NO CAMINHO DE EMAÚS,
IAM FALANDO A RESPEITO DE JESUS;
UM VIAJANTE DELES SE APROXIMOU,
NÃO PERCEBERAM QUE ERA O MEIGO SALVADOR.

CORO
FICA CONOSCO, NOSSO AMADO SALVADOR,
FICA CONOSCO PELO TEU IMENSO AMOR,
COMO OS DISCÍPULOS TE PEDIRAM
NO CAMINHO DE EMAÚS,
FICA CONOSCO, NOSSO AMADO E BOM JESUS.

ELES FALAVAM A RESPEITO DE JESUS,
VARÃO PROFETA QUE FOI PODEROSO EM OBRAS
DIANTE DE DEUS E TODO O POVO, ALELUIA,
ESTE JESUS QUE AINDA HOJE NOS CONDUZ.

SENTADO À MESA, TOMANDO O PÃO, ABENÇOOU,
PARTIU E DEU, ELES ENTÃO RECONHECERAM;
CHEIOS DE GOZO EM VER O FILHO DE DEUS,
NO MESMO INSTANTE ELE DESAPARECEU.
');
