INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cea87217-5127-4a84-9d60-c08911bda70c', 'Jerusalém excelsa', '695', 'Let.: Bernard de Cluny; Trad.: Augusto de Souza Pinto Caldeira; Mús.: Alexander C. Ewing', 'Canção', 'Db', 'Grupo de Louvor', 'JERUSALÉM EXCELSA,
GLORIAMO-NOS EM TI;
CONSOLADORA ESPERANÇA
DO TEU REBANHO AQUI;

RADIANTE, BELOS MUROS,
ELE JÁ DE LONGE VÊ
E A GLÓRIA DA CIDADE
CONTEMPLA PELA FÉ.

E A CRUZ QUE TE ALUMIA;
E AO GRANDE REDENTOR,
CORDEIRO, TEU ESPOSO,
TRIBUTAS-LHE LOUVOR.

QUE GOZO QUE ME INSPIRA,
ETERNA HABITAÇÃO,
SABER QUE EM TI
TERMINO A PEREGRINAÇÃO!

Ó DOCE PÁTRIA AMADA,
TEU GOZO SERÁ MEU!
Ó PÁTRIA DESEJADA,
QUE ENCANTO É ESSE TEU;

EXULTA, TU QUE GEMES
NA DOR QUE SE DESFAZ;
COM DEUS, QUE TE REDIME,
FELIZ SEMPRE SERÁS.
');
