INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cef84d9d-a330-41bb-be78-a2a51d90fd1f', 'Descansa ó Alma (Coro Masculino)', '', '', '', '', '', 'DESCANSA, Ó ALMA,
EIS O SENHOR AO LADO;
PACIENTE LEVA,
E SEM QUEIXAR-TE, A CRUZ;

DEIXA O SENHOR TOMAR
DE TI CUIDADO,
É IMUTÁVEL TEU FIEL JESUS!
PROSSEGUE, Ó ALMA,
O AMIGO CELESTIAL PROTEGERÁ
TEUS PASSOS NO ESPINHAL!

PROSSEGUE, Ó ALMA,
O TRILHO É ESTREITO E ESCURO,
MAS, NO PASSADO DEUS
GUIOU-TE ASSIM!
CONFIA AGORA A DEUS O TEU FUTURO,
E O QUE É MISTÉRIO HÁ DE
ACLARAR-SE ENFIM,
CONFIA, Ó ALMA, A SUA MANSA
VOZ AINDA ACALMA O VENTO
E O MAR FEROZ!

CONFIA, Ó ALMA,
A HORA VEM CHEGANDO!
IRÁS COM CRISTO, O TEU SENHOR,
MORAR, SEM DOR, NEM MÁGOAS,
GOZARÁS, CANTANDO
AS ALEGRIAS DO CELESTE LAR!
DESCANSA, Ó ALMA,
AGORA HÁ PRANTO E DOR,
DEPOIS O GOZO, A PAZ,
O CÉU DE AMOR!
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('cef84d9d-a330-41bb-be78-a2a51d90fd1f', '45ab58b2-d293-45c7-aa75-090fcd968b24');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('cef84d9d-a330-41bb-be78-a2a51d90fd1f', 'd369f950-5259-483c-9412-b0a37d90042c');
INSERT INTO praise_materials (id, praise_id, material_kind, type, r2_key, file_path_legacy, source_material_id) VALUES ('be6347b0-6334-4240-ad4d-f8b8fa2c6ad6', 'cef84d9d-a330-41bb-be78-a2a51d90fd1f', 'c2fb644f-697c-4d43-9d5f-22319fa0ce79', 'pdf', 'assets/praises/cef84d9d-a330-41bb-be78-a2a51d90fd1f/be6347b0-6334-4240-ad4d-f8b8fa2c6ad6.pdf', 'Avulsos Migrados/Descansa ó Alma (Coro Masculino)/coro.pdf', NULL);
INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cefec38a-8e6c-4292-bd80-de4f6f517774', 'Redentor Onipotente', '184', 'Let:Henry Maxwell Wright; Mús.Rowland Hugh Prichard', 'Marcha', 'F', 'Dedicação', 'REDENTOR ONIPOTENTE,
PODEROSO SALVADOR,
REI DOS REIS, ONIPRESENTE
É JESUS, MEU BOM SENHOR.

CORO
OH! REFÚGIO DA MINH''ALMA,
TU ÉS TUDO PARA MIM!
TUDO QUANTO EU CAREÇO,
ACHO, JESUS, SÓ EM TI.

ÁGUA VIVA! PÃO DA VIDA!
DOCE SOMBRA NO CALOR,
E AO DESCANSO NOS CONVIDA,
É JESUS, MEU SALVADOR.

O CORDEIRO IMACULADO,
QUE SEU SANGUE DERRAMOU,
MEUS PECADOS EXPIANDO,
A MINH''ALMA RESGATOU.

O CAMINHO QUE, SEGURO,
SEMPRE PARA O CÉU CONDUZ
QUEM A CRISTO PRONTO SEGUE,
QUEM TOMAR A SUA CRUZ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('cefec38a-8e6c-4292-bd80-de4f6f517774', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
