INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cf01385d-9d14-4690-96ae-d6344d323afa', 'Jesus, o bom pastor', '115', 'C.M.V.C.S.', 'Fox', 'E', 'Crianças e Adolescentes', 'JESUS, O BOM PASTOR,
CUIDA DE MIM COM MUITO AMOR.
A PASTOS VERDEJANTES
SEMPRE LEVA-ME O SENHOR
E A ÁGUAS TÃO TRANQUILAS
MANSAMENTE ME CONDUZ.
NAS VEREDAS DA JUSTIÇA,
VIVEREI NA LUZ.

SE MESMO O PERIGO
TIVER QUE ENFRENTAR,
SEI QUE MEU JESUS
COMIGO SEMPRE ESTARÁ.
MEDO NÃO TEREI, 
POIS SINTO SUA MÃO EM MIM.
COM O CAJADO DO SENHOR,
CONSOLO TENHO SIM!

MESA ABUNDANTE HEI DE TER;
ÓLEO DO ESPÍRITO EM MEU VIVER;
CÁLICE TRANSBORDANTE,
VIDA ABUNDANTE,
COM A MISERICÓRDIA DO SENHOR.
E POR LONGOS DIAS VIVEREI
/EM SUA CASA ETERNA HABITAREI. (2X)
');
