INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cf59d53b-2e3a-421b-b294-1f3440b9012f', 'Vou clamar', '043', 'Fárell Farias Oliveira', 'Básico', 'G', 'Clamor', 'CANTAR 2X
VOU CLAMAR POR TEU SANGUE,
Ó JESUS,
PRA TE OFERECER A MINHA VIDA.

CANTAR 2X
E QUEM TIVER TEU SANGUE SOBRE SI,
TERÁ VITÓRIA, VITÓRIA EM TI, JESUS.
/INSTRUMENTOS

FINAL 2X
E QUEM TIVER TEU SANGUE SOBRE SI,
TERÁ VITÓRIA, VITÓRIA EM TI, JESUS.
');
