INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cf5ebaf3-dd45-438b-8e54-50b7f3f4c5d8', 'As parábolas do reino', '', '', '', '', '', 'SAINDO DE CASA NAQUELE DIA,
ASSENTADO JUNTO AO MAR,
JESUS FOI EXPLICAR ÀQUELA MULTIDÃO
E A TODOS QUE O SEGUIAM,
SOBRE AS PARÁBOLAS DE UM REINO QUE VIRIA.

SETE SÃO AS PARÁBOLAS DO REINO:
SEMEADOR, TRIGO E JOIO,
GRÃO DE MOSTARDA, FERMENTO,
TESOURO ESCONDIDO, PÉROLA E REDE.

VAMOS VIGIAR E ORAR,
JESUS BREVE VIRÁ,
IREMOS TODOS COM ELE MORAR.
MARANATA, JESUS VEM!
');
