INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cfa0b20e-1394-4728-a7f4-9ad174d730fb', 'Quero ser fiel ao meu Senhor', '393', 'Jorgemar Souza Madeira', 'Básico', 'C', 'Santificação e Derramamento', 'QUERO SER FIEL AO MEU SENHOR,
SEGUIR COMO ENSINOU ESTE CAMINHO,
LEVAR ESTA MENSAGEM DE AMOR,
SEGUIR AO SALVADOR.

*CORO
QUERO TER A PAZ QUE CRISTO DÁ,
SENTIR O SEU AMOR POR MIM ASSIM,
NÃO TEMER A LUTA QUE VIER,
SENHOR, AJUDA-ME.

E QUANDO ME ENCONTRAR AFLITO ASSIM,
LEMBRAR QUE MEU JESUS
TANTO SOFREU POR MIM,
E VIVO ANSIOSO A ESPERAR
MORAR LÁ NO PORVIR.

*CORO 2X
QUERO TER A PAZ QUE CRISTO DÁ,
SENTIR O SEU AMOR POR MIM ASSIM,
NÃO TEMER A LUTA QUE VIER,
SENHOR, AJUDA-ME.
/FINAL
SENHOR, AJUDA-ME.
');
