INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cfd8e656-3cb6-48c9-b8cc-473a0bd45e1d', 'Deixa Meu Povo Ir', '', '', '', 'D', 'Avulsos', 'VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!

NO EGITO ESTAVA ISRAEL
(DEIXA MEU POVO IR!)
OPRESSO E SEM SUPORTAR
(DEIXA MEU POVO IR!)

*CORO
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!

AO EGITO DESCEU POIS MOISÉS
(DEIXA MEU POVO IR!)
A  FARAÓ PERSUADIU
(DEIXA MEU POVO IR!)

*CORO
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!

ASSIM FALOU DEUS A MOISÉS
(DEIXA MEU POVO IR!)
OS PRIMOGÊNITOS MATAREI
(DEIXA MEU POVO IR!)

*CORO
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!
/INSTRUMENTOS

FINAL
VAI, MOISÉS! VAI POIS À TERRA DO EGITO
DIZE A FARAÓ: DEIXA MEU POVO IR!
VAI, MOISÉS!
DEIXA MEU POVO IR!
');
