INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('cff4104a-d484-429d-93f8-26b9eb74bd90', 'Que consolação', '341', 'Let.: Elisha Albright Hoffmann; Trad. Ricardo Pitrowsky; Mus. Anthony Johnson Showalter', 'Fox Abafado', 'F', 'Consolo e Encorajamento', 'QUE CONSOLAÇÃO TEM MEU CORAÇÃO,
DESCANSANDO NO PODER DE DEUS;
ELE TEM PRAZER EM ME PROTEGER,
DESCANSANDO NO PODER DE DEUS.

CORO
DESCANSANDO
NOS ETERNOS BRAÇOS DO MEU DEUS;
VOU SEGURO,
DESCANSANDO NO PODER DE DEUS.

SEMPRE AVANTE VOU, BEM CONTENTE ESTOU,
DESCANSANDO NO PODER DE DEUS;
TUDO HEI DE VENCER PELO SEU PODER,
DESCANSANDO NO PODER DE DEUS.

NÃO RECEAREI, NADA TEMEREI,
DESCANSANDO NO PODER DE DEUS;
GOZO, PAZ E AMOR JUNTO A MEU SENHOR,
DESCANSANDO NO PODER DE DEUS.
');
