INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d02af84f-4b1e-48f1-a97b-59a448f774d1', 'O Amor de Deus é Grande', '284', 'Márcia Castro de Freitas', 'Balada', 'E', 'Grupo de Louvor', 'O AMOR DE DEUS É GRANDE,
MANDOU SEU FILHO À CRUZ
A MORRER POR MIM E POR TI
E TAMBÉM PARA VENCER,
VENCER A MORTE, VENCER A DOR;
ELE É JESUS, UNIGÊNITO FILHO,
REI, SENHOR, SALVADOR.

CORO
TE CHAMA PRA VIDA,
TE CHAMA PRA LUZ,
VENCEU A MORTE, ELE É JESUS,
QUER TE SALVAR, VIDA TE DAR,
VEM A JESUS.

UM ALTO PREÇO ELE PAGOU
SÓ POR AMOR AO PECADOR,
ALI NA CRUZ JESUS MORREU
E DEPOIS RESSUSCITOU,
VENCEU A MORTE, VENCEU A DOR;
ELE É JESUS, UNIGÊNITO FILHO,
REI, SENHOR, SALVADOR.

FINAL
TE CHAMA PRA VIDA,
(TE CHAMA PRA VIDA)
TE CHAMA PRA LUZ,
(TE CHAMA PRA LUZ)
VENCEU A MORTE, (ELE VENCEU)
ELE É JESUS, (ELE É JESUS)
QUER TE SALVAR, (QUER TE SALVAR)
VIDA TE DAR, 
VEM A JESUS. (2X)
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('d02af84f-4b1e-48f1-a97b-59a448f774d1', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
