INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d04f0ed9-b98d-42ff-8547-6f89ea7a4daa', 'Sansão', '', '', '', '', '', 'SANSÃO ERA UM MENINO NAZIREU
PARA LIVRAR SEUS PAIS DAS MÃOS DOS FILISTEUS.
O MENINO FICOU GRANDE E O SENHOR
O ABENÇOOU.
E VIVIA IMPELIDO PELO ESPÍRITO
DO SENHOR.

SANSÃO MATOU UM LEÃO À MÃO DESARMADA.
E MATOU TAMBÉM MIL HOMENS COM
UMA QUEIXADA.
E COM TREZENTAS RAPOSAS FEZ UMA
GRANDE QUEIMADA,
MAS FICOU UMA RAPOSINHA NO SEU
PEITO ENCERRADA.

O NOME DA RAPOSINHA CHAMA-SE PAIXÃO.
POIS ELA TEM DERROTADO MUITOS IRMÃOS.
SANSÃO ENXERGOU DALILA E LOGO
FOI DERROTADO.
BRINCOU DE SER AMARRADO E FICOU
MESMO AMARRADO.

O SEGREDO DO PODER ESTAVA NO CABELO.
E POR UMA PAIXÃO CARNAL ELE PERDEUO ZELO.
E ACABOU REVELANDO O SEGREDO DO SENHOR.
FOI LEVADO AO CATIVEIRO E OS OLHOS
LHE CUSTOU.

SEM OS OLHOS E CABELOS E AINDA
AMARRADO, TRABALHAVA COMO ESCRAVO
E ERA TORTURADO.
MAS UM DIA ELE SENTIU O CABELO A CRESCER,
PERCEBEU QUE SUA FÉ ESTAVA A REVIVER.

FOI LEVADO PRÁ BRINCAR DIANTE DOS FILISTEUS.
MAS JÁ TINHA O CORAÇÃO VOLTADO PARA DEUS.
LEVANTOU A SUA VOZ E DISSE: Ó GRANDE
DEUS, ESFORÇA-TE SÓ ESTA VEZ,
MORRA EU COM OS FILISTEUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('d04f0ed9-b98d-42ff-8547-6f89ea7a4daa', '45ab58b2-d293-45c7-aa75-090fcd968b24');
