INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d0815328-a642-419c-a5f2-18a0350ecdcd', 'Disse Jesus aos Judeus (Eu trabalho também)', '178', 'A.C.J.', 'Fox', 'E', 'Crianças e Adolescentes', 'DISSE JESUS AOS JUDEUS,
ASSIM JESUS LHES RESPONDEU:
"O MEU PAI TRABALHA ATÉ AGORA,
EU TRABALHO TAMBÉM!

EU TRABALHO TAMBÉM,
EU TRABALHO TAMBÉM,
O MEU PAI TRABALHA ATÉ AGORA,
E EU TRABALHO TAMBÉM!"

CONVÉM QUE EU FAÇA AS MESMAS OBRAS
DAQUELE QUE ME ENVIOU,
ENQUANTO É DIA, A NOITE VEM
QUANTO NÃO SE PODE TRABALHAR,
O MEU PAI TRABALHA ATÉ AGORA,
EU TRABALHO TAMBÉM!

QUERO TRABALHAR TAMBÉM,
QUERO TRABALHAR TAMBÉM,
COM O ESPÍRITO SANTO EM MINHA VIDA,
QUERO TRABALHAR TAMBÉM!
');
