INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d194d209-efb4-4d67-b90e-d809e631dc00', 'Há alguém que cuida de ti', '336', 'Autor Desconhecido', 'Valseado', 'E', 'Consolo e Encorajamento', 'CORO
HÁ ALGUÉM QUE CUIDA DE TI; (2X)
E QUANDO SENTES SOLIDÃO
E UM VAZIO NO CORAÇÃO,
LEMBRA QUE ALGUÉM CUIDA DE TI.

SE AS NUVENS TE ENCOBREM
E NÃO QUEREM PASSAR,
SE O TEU BARCO SE AGITA
COM AS ONDAS DO MAR,
NÃO TE ESQUEÇAS:
ALGUÉM CUIDA DE TI SEM CESSAR,
COM SEU AMOR ELE VEM TE AJUDAR.

QUANDO LEVAS TUDO A ELE EM ORAÇÃO
E COM LÁGRIMAS SINCERAS NO CORAÇÃO,
CRISTO VÊ E SE ALEGRA DE TE AJUDAR
E SUA PAZ ELE VEM DERRAMAR.
');
