INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d1c98212-6bb6-400f-9739-5cb26b1a8bc2', 'A minh’alma engrandece', '624', 'Gérson Beluci Miguel', 'Básico', 'Am', 'Louvor', 'CANTAR 2X
A MINH''ALMA ENGRANDECE
AO MEU SENHOR E REI.

CORO 2X
A QUEM MAIS ENGRANDECEREI
DO QUE A JESUS, O SENHOR?

CANTAR 2X
DEU-ME LÍNGUA NOVA PRA LOUVÁ-LO,
ELE É O SENHOR.

CANTAR 2X
SEI QUE ELE VOLTA PRA BUSCAR-ME,
LEVAR-ME AO CÉU.
');
