INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d2674beb-30d1-4351-9391-7a73bbf2ed1b', 'O meu coração', '660', 'Dênis Bonfim Pereira Pinto', 'Balada', 'D', 'Salmos de Louvor', 'O MEU CORAÇÃO FERVE 
COM PALAVRAS BOAS,
FALO DO QUE TENHO FEITO
NO TOCANTE AO REI;
A MINHA LÍNGUA É A PENA
DE UM DESTRO ESCRITOR,
TU ÉS MAIS FORMOSO
QUE OS FILHOS DOS HOMENS;

A GRAÇA SE DERRAMOU EM TEUS LÁBIOS,
POR ISSO DEUS TE ABENÇOOU PARA SEMPRE;
À COXA CINGE A TUA ESPADA, Ó VALENTE,
COM A TUA GLÓRIA E TUA MAJESTADE.
/INSTRUMENTOS

E NESTE ESPLENDOR TEU
CAVALGA PROSPERAMENTE
PELA VERDADE, JUSTIÇA E A MANSIDÃO;
AS TUAS FLECHAS SÃO AGUDAS NO CORAÇÃO
DOS INIMIGOS DO REI,
E POR ELAS OS POVOS
SE QUEDAM DIANTE DE TI;

O TEU TRONO, Ó DEUS, É ETERNO E PERPÉTUO,
O CETRO DO TEU REINO É DE EQUIDADE,
TU AMAS JUSTIÇA E ODEIAS MALDADE,
POR ISSO O TEU DEUS TE UNGIU COM ALEGRIA.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('d2674beb-30d1-4351-9391-7a73bbf2ed1b', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
