INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d282f949-9a5b-4ea3-adf8-640d080759ac', 'Ó Pai, eu Queria Tanto Ver Autor da Minha Fé', '673', 'Paulo Cézar da Silva', 'Básico', 'C', 'Grupo de Louvor', 'Ó PAI, EU QUERIA TANTO VER
O MEU SENHOR DESCER
VINDO ME ENCONTRAR,
EU POSSO ATÉ IMAGINAR
A REFULGENTE GLÓRIA
DO SENHOR JESUS,

TRANSPONDO AS BRANCAS NUVENS
NO MAIS PURO AZUL
ONDE NEM SUL,
NEM NORTE EXISTIRÁ.

E EM MEIO A LÁGRIMAS,
SORRISOS DE ALEGRIA E DE PRAZER,
EU QUE ERA CEGO AGORA POSSO VER,
CONTEMPLAR, CONTEMPLAR, ENFIM,
POR ISSO EU CANTO GLÓRIA.
/*CORO 2X
GLÓRIA, GLÓRIA
AO AUTOR DA MINHA FÉ,

Ó PAI, EU QUERIA TANTO OUVIR
O SOM QUE VAI ABRIR
O ENCONTRO TRIUNFAL,
REVER AMIGOS QUE
UM DIA EM CRISTO FORAM
FEITOS MEUS IRMÃOS,
E AGORA, SIM, PODEMOS DAR AS MÃOS;

POIS TEMOS TODOS UM, SOMENTE UM,
UM SÓ SENHOR.
E EIS O CONSOLO QUE ENVOLVE A MINHA VIDA,
O MEU SENHOR JESUS
QUE FOI MORTO, SIM, NAQUELA CRUZ,
VOLTARÁ, VOLTARÁ, ENFIM,
POR ISSO EU CANTO GLÓRIA.
/*CORO 2X
GLÓRIA, GLÓRIA
AO AUTOR DA MINHA FÉ,

(ALELUIA) GLÓRIA AO SENHOR, (3X)
(ALELUIA) O AUTOR DA MINHA FÉ.
/FINAL 2X
(ALELUIA) GLÓRIA AO SENHOR, (2X)
(ALELUIA) O AUTOR DA MINHA FÉ.
');
