INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d2a2bb64-8a6b-49fc-875a-508387e0f960', 'Tu és o Cristo, filho do Deus vivo', '072', 'E.H.M.R.', 'Balada', 'A', 'Crianças e Adolescentes', 'CANTAR 2X
TU ÉS O CRISTO,
O FILHO DO DEUS VIVO,
NOSSO SALVADOR, JESUS, NOME DOCE;
MORRESTE NA CRUZ PRA NOS SALVAR,
RESSUSCITASTE E NO CÉU ESTÁS,
VOLTARÁS E NOS LEVARÁS
PARA CONTIGO HABITAR.
');
