INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d35287ce-e57a-4921-8d96-8bda91172f7d', 'Quando entrei neste lugar', '', '', '', '', '', 'QUANDO ENTREI NESTE LUGAR,
SENTI SUA PRESENÇA
EU SABIA AQUI É O LUGAR,
ONDE HABITA O AMOR.

POIS ESTE É O TEMPLO DE DEUS,
JEOVÁ AMADO.
NÓS ESTAMOS EM SUA PRESENÇA
EM SANTO LUGAR.

*CORO
NÓS ESTAMOS EM SANTO LUGAR,
E POSSO SENTIR AQUI HÁ ANJOS AO REDOR.
VAMOS ADORAR A JESUS AGORA,
ESTAMOS REUNIDOS EM SUA
PRESENÇA EM SANTO LUGAR.

NA PRESENÇA DO SENHOR HÁ GOZO
IMENSO, E A SEUS PÉS A PAZ DA ALMA
ENCONTRARÁS.

SE ESTÁS EM DÚVIDA,
EU SEI SÓ ELE É A RESPOSTA.
NÓS ESTAMOS EM SUA PRESENÇA
EM SANTO LUGAR.

*CORO 2X
NÓS ESTAMOS EM SANTO LUGAR
E POSSO SENTIR AQUI HÁ ANJOS
AO REDOR, VAMOS ADORAR A JESUS
AGORA, ESTAMOS REUNIDOS EM SUA
PRESENÇA, EM SANTO LUGAR.
/FINAL 2X
ESTAMOS REUNIDOS EM SUA
PRESENÇA, EM SANTO LUGAR.
');
