INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d3aa914d-4fa6-48b4-b725-1b3436e37be3', 'Não há o que temer (Sei Que Deus é Por Mim)', '024', '', '', '', 'Avulsos', 'NÃO HÁ O QUE TEMER,
O SENHOR, MEU PASTOR,
LIVRA MINH’ALMA DA MORTE
E OS MEUS PÉS CAMINHAM NA LUZ.

AINDA QUE NO VALE EU ANDE,
TU ME ESCONDES
E TUA MÃO ME SUSTENTA;
NÃO TEMEREI, CONFIAREI NO SENHOR.

*CORO
SEI QUE DEUS É POR MIM
E O QUE ME RESTA
É LOUVAR, ADORAR, BENDIZER
PELAS SUAS MISERICÓRDIAS;
NÃO HÁ O QUE TEMER!

NÃO HÁ O QUE TEMER,
TU ÉS MEU REI, SALVADOR;
SE NO ALTO MAR PERDIDO ESTOU,
TU ME CONDUZES, ÉS MINHA LUZ.

AINDA QUE NO ÁRIDO DESERTO
EU ME ENCONTRE,
TU, ALI, ME SACIARÁS; CONFIAREI,
DAS TUAS FONTES ME FARTAREI.

FINAL 2X
SEI QUE DEUS É POR MIM
E O QUE ME RESTA
É LOUVAR, ADORAR, BENDIZER
PELAS SUAS MISERICÓRDIAS;
NÃO HÁ O QUE TEMER!
');
