INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d3e41efc-c0d2-4972-a137-c8933b8130c2', 'Amigo, Não Saia Sem Cristo', '', '', '', '', '', 'AMIGO, NÃO SAIAS SEM CRISTO,
NÃO SAIAS DAQUI SEM JESUS,
ELE QUER HOJE MESMO SALVAR-TE,
POR ISSO MORREU LÁ NA CRUZ;
RECEBE ESTA OFERTA DE GRAÇA,
ACEITA, PORTANTO, O PERDÃO,
AMIGO NÃO SAIAS SEM CRISTO
NO SEU CORAÇÃO.
');
