INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d3f13c2b-0c11-4043-9875-6f740adda6e5', 'Certo Homem Tão Nobre', '215', 'Jorgemar Souza Madeira', 'Valseado', 'D', 'Morte, Ressureição e Salvação', 'CERTO HOMEM TÃO NOBRE NESTE MUNDO DESCEU,
CARREGOU MEUS PECADOS SÓ PORQUE ME AMOU;
O SEU SANGUE TÃO PURO NA CRUZ DERRAMOU,
ESTE HOMEM TÃO NOBRE É JESUS.

*CORO 2X
NOBRE E REI, ELE É NOBRE E REI,
ESTE HOMEM TÃO NOBRE É JESUS.

RESSURGIU DENTRE OS MORTOS
PORQUE É VENCEDOR,
HOJE À DESTRA DO PAI ESTÁ,
CRISTO, MEU SALVADOR;
PROMETEU QUE UM DIA VIRÁ ME BUSCAR,
PARA SEMPRE O SEU NOME VOU LOUVAR.

*CORO 2X
NOBRE E REI, ELE É NOBRE E REI,
ESTE HOMEM TÃO NOBRE É JESUS.
/FINAL
ESTE HOMEM TÃO NOBRE É JESUS.
');
