INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d429bb1e-ecb2-4504-b1c0-170049c7237a', 'Um corpo só, um só Espírito', '426', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'C', 'Santificação e Derramamento', 'UM CORPO SÓ, UM SÓ ESPÍRITO,
UMA ESPERANÇA, UM SÓ SENHOR, UMA FÉ,
UM SÓ BATISMO E UM SÓ DEUS E PAI,
UM CORPO SÓ, UM SÓ ESPÍRITO, (2X)

CRISTO É A CABEÇA, O CORPO É A SUA IGREJA;
COM SEU PODER NOS BATIZOU O SENHOR;
NÃO HÁ NO MUNDO UM POVO UNIDO ASSIM,
UM CORPO SÓ, UM SÓ ESPÍRITO, (2X)

DE SUA GRAÇA CRISTO DERRAMOU,
EM MINISTÉRIOS, DONS E MUITO AMOR,
MAS SOMOS TODOS UM SÓ EM JESUS,
UM CORPO SÓ, UM SÓ ESPÍRITO, (2X)
');
