INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d430019b-ca11-4ba0-9d98-de52acada083', 'O dia do Senhor virá (O sol da justiça)', '070', 'S.G.D.', 'Fox', 'E', 'Crianças e Adolescentes', 'O DIA DO SENHOR VIRÁ
COM JUÍZO SOBRE TODO MAL;
/CANTAR 2X
VEM DEPRESSA, VEM DEPRESSA,
GRANDE BENÇÃO ESTÁ A TE ESPERAR.

O SOL DA JUSTIÇA NASCERÁ
SALVAÇÃO TRARÁ EM SUAS ASAS;
/CANTAR 2X
VEM DEPRESSA, VEM DEPRESSA,
EM SUAS ASAS TE ABRIGAR.

O SOL DA JUSTIÇA NASCERÁ,
SALVAÇÃO E LIBERTAÇÃO;
/CANTAR 2X
SAIREIS E ANUNCIAREIS,
EM SUAS ASAS INDA HÁ LUGAR.

FINAL 2X
VEM DEPRESSA, VEM DEPRESSA,
EM SUAS ASAS TE ABRIGAR.
');
