INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d489ce54-5f0b-45a7-b869-e51720c09f3f', 'Ó Jesus Ó Vera Páscoa', '460', 'Let.: Autor Desconhecido; Mús.: Tomas Cairnos', 'Valseado', 'D', 'Santificação e Derramamento', 'Ó JESUS! Ó VERA PÁSCOA!
SUSPIRADA DOS ANTIGOS!
Ó CORDEIRO ETERNO E MEIGO,
DIGNA-TE ASSISTIR AQUI!

BOM JESUS, Ó PÃO DIVINO!
PELA FÉ TE RECEBEMOS;
ÉS NAS ALMAS O ALIMENTO
QUE SUSTENTA O NOSSO AMOR.

BOM JESUS, Ó VINHO PURO!
DE PERENE GOZO A FONTE!
QUE NOSSA ALMA VIVA SEMPRE
PARA TI, DE TI, EM TI.
/FINAL
AMÉM.
');
