INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d4a87c56-6f72-4bfe-a89c-a4fcd8a522b7', 'Quando falo com Deus', '017', 'M.C.H.O.', 'Novo', 'C', 'Crianças e Adolescentes', 'QUANDO FALO COM DEUS, AS LÁGRIMAS CORREM,
A SUA PRESENÇA ME ENVOLVE TÃO FORTE, 
EM PAZ ME DEITO, PEGO NO SONO,
POIS EM SEUS BRAÇOS EU DESCANSO;
BEM CEDO ACORDO E ME LEVANTO,
POIS SEI QUE JESUS ME SUSTENTOU.
/INSTRUMENTOS

QUANDO FALO COM DEUS, A LUZ ME ENVOLVE,
TRANSPORTO PARA ETERNIDADE,
ESTOU NO PLANO DE DEUS;
PEÇO TODO DIA, AO MEU SENHOR
QUE SALVE A MINHA FAMÍLIA
PRA JUNTOS LOUVARMOS AO BOM PASTOR
QUE CUIDA DE NÓS COM AMOR. (2X)
');
