INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d4ea440a-eeb2-4a87-bba7-397b13f69413', 'Os que confiam no Senhor', '343', 'Raquel Toscano de Freitas', 'Básico', 'Dm', 'Consolo e Encorajamento', 'OS QUE CONFIAM NO SENHOR
SERÃO FORTES E INABALÁVEIS,
NÃO SERÃO CONFUNDIDOS
E EM SEUS BRAÇOS DESCANSARÃO.

FINAL 2X
O SENHOR CUMPRIRÁ SEUS DESEJOS,
OUVIRÁ SEU CLAMOR E OS SALVARÁ,
ELE SERÁ SEU AUXÍLIO
E EM SEUS BRAÇOS DESCANSARÃO.
');
