INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d543897f-70e3-4b96-905d-9215804bf900', 'Pelo Sangue de Jesus', '008', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'G', 'Clamor', 'PELO SANGUE DE JESUS
CLAMO A TI, MEU SENHOR;
NELE HÁ PERDÃO, PAZ, COMUNHÃO,
VIDA PARA O MEU SER!

NOS TEUS ÁTRIOS QUERO ENTRAR
COBERTO POR ESTE SANGUE,
PARA TUA GLÓRIA VER
E TE ADORAR!

PELO SANGUE DE JESUS
CLAMO A TI, MEU SENHOR;
NELE HÁ PERDÃO, PAZ, COMUNHÃO,
VIDA PARA O MEU SER!

NOS TEUS ÁTRIOS QUERO ENTRAR
COBERTO POR ESTE SANGUE,
PARA TUA GLÓRIA VER
E TE ADORAR!
/FINAL
PARA TUA GLÓRIA VER
E TE ADORAR!
');
