INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d6a8f0dc-b6f1-41c1-b800-69a5851a9ef7', 'Mais pureza da-me', '', '', '', '', '', 'MAIS PUREZA DÁ-ME,
REJEIÇÃO AO MAL,
MAIS CALMA NAS LUTAS,
MAIS ALTO IDEAL;
MAIS FÉ NO MEU MESTRE,
MAIS CONSAGRAÇÃO,
MAIS GOZO EM SERVI-LO,
MAIS GRATA ORAÇÃO.

MAIS PRUDENTE FAZE-ME,
MAIS SÁBIO, SENHOR;
MAIS FIRME EM CRISTO,
MAIS FORÇAS NA DOR;
MAIS RETO NA VIDA,
MAIS TRISTE AO PECAR;
MAIS HUMILDE FILHO,
MAIS PRONTO EM AMAR.

MAIS PURO FAZE-ME,
MAIS SANTO EM JESUS;
MAIS DO TEU DOMÍNIO,
MAIS GOZO NA CRUZ.
MAIS RICA ESPERANÇA,
MAIS FÉ E PODER.
MAIS ÂNSIA DO CÉU,
MAIS VIDA EM TI.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('d6a8f0dc-b6f1-41c1-b800-69a5851a9ef7', '45ab58b2-d293-45c7-aa75-090fcd968b24');
