INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d6e5c5dc-bfc2-49aa-a140-9801f05599d9', 'Eis aí o dia aceitável', '330', 'Luciana Monteiro Carneiro Simora', 'Básico', 'C', 'Consolo e Encorajamento', 'EIS AÍ O DIA ACEITÁVEL DO SENHOR!
ELE VEIO CONSOLAR TODOS OS QUE CHORAM
E OS CONTRITOS DE CORAÇÃO;
ELE VAI TE DAR VESTES DE LOUVOR
AO INVÉS DE ESPÍRITO ANGUSTIADO,
ÓLEO DE ALEGRIA AO INVÉS DE PRANTO.

CORO 2X
OUVI A VOZ DO SENHOR,
EU VI OS ANJOS ANUNCIAREM,
SENTI A SUA MÃO A ME TOCAR,
SEU AMOR SOBRE O MEU SER.

AINDA QUE OS TEUS PECADOS
FOSSEM COMO CARMESIM,
O SENHOR PODE OS TORNAR
ALVOS COMO A BRANCA LÃ;
E COMO O NOIVO QUE SE ALEGRA DA NOIVA,
O SENHOR SE ALEGRARÁ DE TI,
ELE VAI TE DAR UMA COROA
AO INVÉS DE PRANTO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('d6e5c5dc-bfc2-49aa-a140-9801f05599d9', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
