INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d7479c3c-425f-4740-8285-921f6445fefb', 'Finda-se este dia', '095', '', '', '', '', 'FINDA-SE ESTE DIA, QUE MEU PAI ME DEU,
SOMBRA VESPERTINAS COBREM JÁ OS CÉUS,
Ó JESUS BENDITO, SE COMIGO ESTÁS,
EU NÃO TEMO A NOITE, VOU DORMIR
EM PAZ.

COM MEUS PECADOS EU TE ENTRISTECI,
MAS PERDÃO TE PEÇO, POR AMOR DE TI.
SOU HUMANO E FRACO, LIVRA-ME DO MAL
E EM SOSSEGO TENHO SONO E PAZ REAL.

GUARDA O MARINHEIRO NO VIOLENTO MAR
E AO QUE SOFRE DORES,
QUEIRAS CONFORTAR.
AO TENTADO ESTENDE TUA MÃO SENHOR,
MANDA AO TRISTE E AFLITO TEU CONSOLADOR.

PELOS PAIS E AMIGOS, PELA SANTA LEI,
PELO AMOR DIVINO GRAÇAS TE DAREI.
Ó JESUS ACEITA MINHA PETIÇÃO,
E SEGURO DURMO SEM PERTUBAÇÃO.
');
