INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d97426b4-cfb6-45c6-8ba5-ba8f86815951', 'Meu Deus vence batalhas', '381', 'L.L.R.A', 'Básico', 'D', 'Consolo e Encorajamento', 'MEU DEUS VENCE BATALHAS,
MEU DEUS QUEBRA MURALHAS,
E QUANDO EU ESTOU A FRAQUEJAR,
SUAS MÃOS ESTÃO A ME SUSTENTAR.

MEU DEUS É MUITO FORTE,
O SEU NOME É EMANUEL,
E QUANDO TUDO PARECE MAL,
A VITÓRIA EU SEI QUE ELE ME DARÁ.

*CORO
CLAMEI NA ANGÚSTIA, E OUVIU O MEU CLAMOR.
MEU DEUS ESTÁ COMIGO, NÃO TEMO O PERIGO,
ELE É O MEU SALVADOR.
NÃO SE COMPARA A PRATA,
NEM SE COMPARA O OURO,
JESUS É O MEU TESOURO,
COM ELE VOU VENCER.

MEU DEUS VENCE BATALHAS,
MEU DEUS QUEBRA MURALHAS,
E QUANDO EU ESTOU A FRAQUEJAR,
SUAS MÃOS ESTÃO A ME SUSTENTAR.

MEU DEUS É MUITO FORTE,
O SEU NOME É EMANUEL,
E QUANDO TUDO PARECE MAL,
A VITÓRIA EU SEI QUE ELE ME DARÁ.

*CORO 2X
CLAMEI NA ANGÚSTIA, E OUVIU O MEU CLAMOR.
MEU DEUS ESTÁ COMIGO, NÃO TEMO O PERIGO,
ELE É O MEU SALVADOR.
NÃO SE COMPARA A PRATA,
NEM SE COMPARA O OURO,
JESUS É O MEU TESOURO,
COM ELE VOU VENCER.
/FINAL
MEU DEUS VENCE BATALHAS.
');
