INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('d9e6ee59-b888-4b2f-863f-db848cb4600b', 'Um Pendão Real Vos Entregou o Rei', '410', 'Let.: Daniel Webster Whittle; Trad. Henry Maxwel Wright; Mús.: James McGranahan', 'Marcha', 'A', 'Santificação e Derramamento', 'UM PENDÃO REAL VOS ENTREGOU O REI 
A VÓS, SOLDADOS SEUS;
CORAJOSOS, POIS, EM TUDO O DEFENDEI
MARCHANDO PARA OS CÉUS.

CORO
COM VALOR! SEM TEMOR!
POR CRISTO PRONTOS A SOFRER;
BEM ALTO ERGUEI O SEU PENDÃO,
FIRMES SEMPRE ATÉ MORRER!

EIS FORMADOS JÁ OS NEGROS BATALHÕES
DO GRANDE USURPADOR;
DECLARAI-VOS, HOJE, BRAVOS CAMPEÕES,
AVANTE, SEM TEMOR!

QUEM RECEIO SENTE NO SEU CORAÇÃO
E FRACO SE MOSTRAR,
NÃO RECEBERÁ O ETERNO GALARDÃO
QUE CRISTO TEM PRA DAR.

POIS SEJAMOS TODOS A JESUS LEAIS
E AO SEU REAL PENDÃO;
OS QUE NA BATALHA SEMPRE SÃO FIÉIS
COM ELE REINARÃO.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('d9e6ee59-b888-4b2f-863f-db848cb4600b', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
