INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('da714e15-c011-40b8-aa24-0c0ebef65cd9', 'Qual foi o preço', '064', 'Elieny Mees Arr. Felippe Proba Soares', 'Balada/Blues', 'A', 'Avulso', 'QUAL FOI O PREÇO QUE MEU JESUS PAGOU
POR ME AMAR TANTO ASSIM?
TAL FOI O PREÇO PELO QUAL SE ENTREGOU
POR ME AMAR, POR TE AMAR!
PREÇO DE AMOR, PROVA DE AMOR,
PREÇO DE AMOR.

HOJE MEU CORAÇÃO VIVE TÃO FELIZ
POR SABER QUE ALGUÉM ME AMA TANTO ASSIM.
E NÃO ME IMPORTO SE ALGO FALHAR.
MESMO ASSIM SEI QUE ELE ME AMA!

MORREU NA CRUZ, PAGOU PREÇO DE SANGUE,
POR ME AMAR, POR TE AMAR!
PREÇO DE AMOR, PROVA DE AMOR,
PREÇO DE AMOR.
/INSTRUMENTOS

PREÇO DE AMOR!
(JESUS ME AMA, ME AMA!)
PROVA DE AMOR, PREÇO DE AMOR!
(JESUS ME AMA, ME AMA, ME AMA!)

/FINAL
JESUS ME AMA, ME AMA,
JESUS ME AMA, ME AMA, ME AMA!
QUAL FOI O PREÇO?
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('da714e15-c011-40b8-aa24-0c0ebef65cd9', '45ab58b2-d293-45c7-aa75-090fcd968b24');
