INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dad533e1-3693-40d2-a699-317067dd8d85', 'Minha Dedicação', '417', 'Raquel Toscano de Freitas', 'Básico', 'C', 'Santificação e Derramamento', 'MINHA DEDICAÇÃO
EU VIM TE OFERECER,
TU ÉS O MEU AMADO SALVADOR;
PEDISTE MAIS DE MIM, 
EIS-ME AQUI, SENHOR,
TENS A MINHA VIDA E MEU LOUVOR.

VIVER SÓ PARA TI
COM TODO O MEU AMOR,
OBEDECER TUA VOZ
EM TODO O MEU VIVER,
SEGUINDO TEUS PASSOS,
OBSERVANDO OS MEUS,
EM TUDO AGRADANDO
A TI, MEU TERNO DEUS.

Ó VINDE, ADOREMOS AO SENHOR,
O GRANDE REI,
JUSTO E PODEROSO, EXCELSO DEUS,
MEU REDENTOR,
TEMEI DIANTE DELE TODA A TERRA,
ADORAI AO REI.

FINAL
ALELUIA, ALELUIA, ALELUIA, ALELUIA, (2X)
TEMEI DIANTE DELE TODA A TERRA,
ADORAI AO REI.
');
