INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('db308fa5-10d0-404e-a583-c830c9738c0e', 'Jesus, ó meu Jesus', '006', 'Iracy Emerick de Araújo', 'Balada', 'E', 'Clamor', 'JESUS, Ó MEU JESUS,
NESTA HORA ME CHEGO A TI
PRA CLAMAR PELO TEU SANGUE
E SENTIR-TE PERTO DE MIM.

FINAL 2X
Ó DÁ-ME LIBERTAÇÃO
E MUITA COMUNHÃO,
E PERMITE, Ó SENHOR,
QUE EU SEJA USADO
EM TUAS MÃOS.
');
