INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('db5e34ea-9525-4d36-ad2a-a4e5c03f3038', 'Quero estar em tua presença, ó Deus', '155', 'J.J.G.', 'Básico', 'G', 'Crianças e Adolescentes', 'QUERO ESTAR EM TUA PRESENÇA,
Ó DEUS,
EM TUA OBRA PROSSEGUIR ATÉ O FIM,
SEM TEMER E SEMPRE CONFIAR
QUE JESUS AO MEU LADO ESTÁ.

CORO
FAZ DE MIM UM VENCEDOR,
NÃO IMPORTA QUAL SEJA A MINHA DOR.
FAZ DE MIM UM ENVIADO TEU,
PARA A TUA OBRA REALIZAR
E DO TEU PODER TESTEMUNHAR
E POR FIM JERUSALÉM ALCANÇAR.

QUERO SER UM SERVO DO SENHOR
E ANDAR SOB A REVELAÇÃO,
PARTILHAR DA SUA COMUNHÃO,
DANDO A ELE SEMPRE O MEU CORAÇÃO.
');
