INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('db87f325-da5a-493f-8dd1-ac7019e28cdf', 'Eis Os Milhões', '', '', '', '', '', 'EIS OS MILHÕES QUE EM TREVAS TÃO
MEDONHAS JAZEM PERDIDOS,
SEM O SALVADOR! OH!
QUEM IRÁ AS NOVAS PROCLAMANDO
QUE DEUS EM CRISTO SALVA O PECADOR?

CORO
TODO PODER O PAI ME DEU.
NA TERRA COMO LÁ NO CÉU!
IDE, POIS, ANUNCIAI O EVANGELHO,
E EIS-ME CONVOSCO SEMPRE.

PORTAS ABERTAS EIS POR TODO O MUNDO!
CRENTES EM CRISTO, SEMPRE AVANTE ANDAI!
E NA PELEJA UNINDO AS VOSSAS FORÇAS
DA ESCAVIDÃO OS POVOS LIBERTAI.
');
