INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('db91540e-b286-4284-a8c2-231e91afa22a', 'Quero ser santo para o Senhor', '165', 'C.M.V.C.S.', 'Balada', 'D', 'Crianças e Adolescentes', 'QUERO SER SANTO PARA O SENHOR,
QUERO SER PURO EM SEU AMOR,
EM TODO O TEMPO TESTEMUNHAR
DE SEU AMOR E GRAÇA SEM PAR.

QUERO LEVAR A MENSAGEM DE SALVAÇÃO
PARA ESTE MUNDO QUE ESTÁ NA ESCURIDÃO.
E QUANDO CRISTO VIER NOS BUSCAR
POSSAMOS TODOS NO CÉU IR MORAR.

QUERO SER SANTO PARA O SENHOR,
QUERO SER PURO EM SEU AMOR,
EM TODO O TEMPO TESTEMUNHAR
DE SEU AMOR E GRAÇA SEM PAR.

QUERO LEVAR A MENSAGEM DE SALVAÇÃO
PARA ESTE MUNDO QUE ESTÁ NA ESCURIDÃO.
E QUANDO CRISTO VIER NOS BUSCAR
POSSAMOS TODOS NO CÉU IR MORAR.
/FINAL
QUERO SER SANTO, QUERO SER PURO
PARA O SENHOR!
');
