INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dc3cfe3c-d7b7-4d6a-8eb8-7ca162c8c9f2', 'Só tu nos fazes vencedores', '730', '', 'Básico', 'Dm', 'Grupo de Louvor', 'SÓ TU NOS FAZES VENCEDORES,
EM TI TEMOS FORÇAS PRA JORNADA;
SACIA A FOME COM TEU SUBLIME AMOR,
DOCE AMOR.

POIS NÓS TE LOUVAMOS,
DIZEMOS: ÉS NOSSA ROCHA ETERNA,
ÉS NOSSO PASTOR, NOSSO JESUS, 
NOSSO SENHOR.

SÓ TU NOS FAZES VENCEDORES,
EM TI TEMOS FORÇAS PRA JORNADA;
SACIA A FOME COM TEU SUBLIME AMOR,
DOCE AMOR.

POIS NÓS TE LOUVAMOS,
DIZEMOS: ÉS NOSSA ROCHA ETERNA,
ÉS NOSSO PASTOR, NOSSO JESUS,
NOSSO SENHOR.
/INSTRUMENTOS

NÓS TE LOUVAMOS,
DIZEMOS: ÉS NOSSA ROCHA ETERNA,
ÉS NOSSO PASTOR, NOSSO JESUS,
NOSSO SENHOR.
/FINAL
NOSSO PASTOR, NOSSO JESUS,
NOSSO SENHOR.
');
