INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dc543ce9-7914-4027-b6d8-9af1ea7036f5', 'Jesus nos prometeu', '196', 'S.G.D.', 'Marcha Marcial', 'D', 'Crianças e Adolescentes', 'JESUS NOS PROMETEU
QUE VIRÁ NOS BUSCAR.
ESTE MUNDO PASSARÁ,
TODO MAL FINDARÁ.

CORO
O TOQUE DA TROMBETA OUVIREMOS,
O ANJO DO SENHOR A TOCARÁ.
NAS NUVENS CELESTIAIS
IREMOS ENCONTRAR JESUS.

QUE GOZO E ALEGRIA HAVERÁ.
A NOIVA DO SENHOR ARREBATADA IRÁ.
COM JESUS PARA SEMPRE ESTARÁ.
');
