INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dc691476-7f94-4630-8642-b18b111e10c8', 'Para os montes olharei', '339', 'Sl.121; Autor Desconhecido', 'Guarânia', 'A', 'Consolo e Encorajamento', 'PARA OS MONTES OLHAREI,
DE ONDE VEM A SALVAÇÃO?
MEU SOCORRO VEM DE DEUS, 
O SENHOR DA CRIAÇÃO.

CORO
O SENHOR É QUEM TE GUARDA,
GUARDARÁ DE TODO MAL; 
TUA ENTRADA E SAÍDA,
DESDE AGORA ATÉ O FINAL.

O SENHOR É QUEM TE GUARDA,
SEMPRE À TUA DESTRA ESTÁ;
NEM DE DIA, NEM DE NOITE,
MAL ALGUM TE OFENDERÁ.

O SENHOR É QUEM TE GUARDA,
NÃO TE DEIXARÁ CAIR;
COMO A ISRAEL GUARDAVA,
NÃO DORMIU NEM VAI DORMIR.
');
