INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dc7a8f2d-ad50-4387-9909-ba225ab92ee2', 'No princípio era o verbo', '151', 'Jayro Trench Gonçalves', 'Básico', 'A', 'Dedicação', 'CRISTO JESUS É O MEU BOM SALVADOR;
DESEJO AMÁ-LO MAIS,
TODOS OS DIAS É MEU SENHOR.

CORO
A CRISTO EU AMO,
OH! QUANTO EU AMO,
POIS POR MIM MORREU;
COM O SEU SANGUE, 
JESUS SALVOU-ME;
EM GRATIDÃO SOU SEU.
/INSTRUMENTOS

BEM CEDO AO CÉU
ELE ME LEVARÁ,
DE-SEJO AMÁ-LO MAIS,
ETERNAMENTE ME GUIARÁ.
');
