INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dc990f77-eb54-40cb-9671-ba724bcef390', 'Ó Venha', '', '', '', 'Fm', 'Avulsos', 'EU QUERO ESTAR AOS PÉS DA CRUZ
DERRAMA SOBRE MIM JESUS
O SANGUE CARMESIM,
VEM ME ENCHER DE TI
TRANSBORDAR TUA GLÓRIA SOBRE NÓS
NOS FAZ AGORA OUVIR TUA VOZ
QUEBRANTA CORAÇÕES,
ESTENDE A TUA MÃO.

PASSEIA NO TEMPLO
COM SUAS VESTES DE PODER
CURANDO AS FERIDAS
RESTAURANDO O MEU SER
TU ÉS REI MEU DEUS,
TU ÉS REI, TU ÉS REI

Ó VEM! Ó VEM!
A TUA IGREJA ANSEIA TE VER
PELOS OLHOS DA FÉ EU JÁ POSSO VER

Ó VENHA! Ó VENHA!
DEUS ESTÁ RESTAURANDO VOCÊ
TOME POSSE DA BENÇÃO
QUE HOJE AQUI, DEUS LHE DEU
/INSTRUMENTOS

EU QUERO ESTAR AOS PÉS DA CRUZ
DERRAMA SOBRE MIM JESUS
