INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dedc47e9-c03e-4e73-a0b7-387c3f302ad1', 'Pelo vale escuro seguirei Jesus', '307', 'Let.: Otoniel de Campos Motta; Mús: Spencer Lane', 'Fox', 'G', 'Consolo e Encorajamento', 'PELO VALE ESCURO SEGUIREI JESUS,
MAS POR TI SEGURO, VENDO A TUA LUZ;
MEUS PASSOS INCERTOS TU DIRIGIRÁS
E AO SENTIR-TE PERTO, NUNCA PERCO A PAZ.

CORO
BREVE A NOITE DESCE, NOITE DE EMAÚS,
E MEU SER CARECE DE TE VER, JESUS,
COMPANHEIRO AMIGO, AO MEU LADO VEM,
FICA, Ó DEUS, COMIGO, INFINITO BEM.

OS ESPINHOS, TANTOS, QUE VÊM NOS SANGRAR
SÃO REMÉDIOS SANTOS PARA NOS CURAR;
ONDE EXISTE A GRAÇA DO BONDOSO DEUS
TUDO O QUE SE PASSA NOS CONDUZ AOS CÉUS.

NÃO HÁ DOR QUE SEJA SEM DIVINO FIM,
FAZE, Ó DEUS,
QUE A IGREJA COMPREENDA ASSIM;
E, APESAR DAS TREVAS, POSSA VER, SENHOR,
QUE TU MESMO A LEVAS COM IMENSO AMOR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('dedc47e9-c03e-4e73-a0b7-387c3f302ad1', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
