INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dfa67bdc-da18-4b2a-a989-c7ec83f328c4', 'Muitos anjos louvam', '632', 'José Elias Simora', 'Valseado', 'G', 'Louvor', 'MUITOS ANJOS LOUVAM
A JESUS, O SALVADOR,
ENTOANDO ALELUIA
ÀQUELE QUE VIVO ESTÁ.

*CORO
SANTO, SANTO, SANTO,
SANTO ÉS, JESUS.
/INSTRUMENTOS

NAS MANSÕES CELESTIAIS
ONDE OS SALVOS POR JESUS
COM UM BRADO DE VITÓRIA
CANTAM EM UMA SÓ VOZ.

*CORO
SANTO, SANTO, SANTO,
SANTO ÉS, JESUS.
/INSTRUMENTOS

NADA PODE COMPARAR
COM A GLÓRIA DO SENHOR,
PARA OS SEUS ESCOLHIDOS
UMA MORADA PREPAROU.

*CORO 2X
SANTO, SANTO, SANTO,
SANTO ÉS, JESUS.
/FINAL
SANTO ÉS, JESUS.
