INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('dfbbd172-ed42-4dac-b479-99d80529f4ae', 'Viver é tão lindo', 58, 'Jackson de Halley Fernandes Fontes', 'Básico', 'D', 'Crianças e Adolescentes', 'VIVER É TÃO LINDO QUANDO SE TEM JESUS,
O MUNDO É TÃO PEQUENO
PARA O QUE EU TENHO EM MIM;
E O QUE EU TENHO
É BEM MAIOR QUE TUDO NA VIDA,
EU TENHO É JESUS.

VIVO A CANTAR, VIVO A SORRIR,
TUDO O QUE EU TENHO
JAMAIS SE ACABARÁ.
');
