INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e00d2b34-ca3b-42d1-911b-83543f62a64d', 'Ó Vem Derramar', '439', 'Jorgemar Souza Madeira', 'Novo', 'E', 'Santificação e Derramamento', 'Ó VEM DERRAMAR, MEU SENHOR,
A PORÇÃO DO TEU SANTO ESPÍRITO
SOBRE MIM, SOBRE MIM.

*CORO
PERMITE ENTRAR NA TUA GLÓRIA,
SENTIR O TOQUE DE JESUS
E EM MISTÉRIO ENTÃO FALAR,
LOUVAR O NOME DE JESUS.

QUERO EM COMUNHÃO TE ADORAR,
TE EXALTAR, Ó TRIUNO DEUS,
TEU AMOR PROCLAMAR.

*CORO 2X
PERMITE ENTRAR NA TUA GLÓRIA,
SENTIR O TOQUE DE JESUS
E EM MISTÉRIO ENTÃO FALAR,
LOUVAR O NOME DE JESUS.
/FINAL
LOUVAR O NOME DE JESUS, (2X)
');
