INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e0368b22-4c78-4cdf-a5d4-fcc54018d830', 'Quem sou eu, Senhor', '', '', '', '', '', 'QUEM SOU EU PRA MERECER TÃO PURO AMOR?
QUEM SOU EU PRA SER A IMAGEM DO MEU DEUS?
QUEM SOU EU PRA TER A MÃO QUE SEGURA?
SOU TÃO POBRE CRIATURA,
QUE NEM MESMO SEI QUEM EU SOU.

*CORO
MAS TU, JESUS, TU ME FIZESTE ENTENDER
QUE PARA TI SOU PRECIOSO,
QUE PARA TI TENHO VALOR,
TU ÉS PODER, TU ÉS VIRTUDE E BELEZA,
TU ÉS O PAI DA NATUREZA,
TU ÉS CONSOLO, TU ÉS AMOR!
/INSTRUMENTOS

QUEM SOU EU PRA MERECER UMA COROA?
QUEM SOU EU PRA SER NA VIDA UM VENCEDOR?
QUEM SOU EU PARA CLAMAR E SER OUVIDO?
E ATRAVÉS DO MEU PEDIDO
MOVER A MÃO DE UM REI SENHOR?

*CORO 2X
MAS TU, JESUS, TU ME FIZESTE ENTENDER
QUE PARA TI SOU PRECIOSO,
QUE PARA TI TENHO VALOR,
TU ÉS PODER, TU ÉS VIRTUDE E BELEZA,
TU ÉS O PAI DA NATUREZA,
TU ÉS CONSOLO, TU ÉS AMOR!
');
