INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e042d372-f903-4214-bd0d-d755056a5792', 'Aquilo que melhor existe', '074', 'S.G.D.', 'Balada', 'C', 'Crianças e Adolescentes', 'AQUILO QUE MELHOR EXISTE
É FALAR DE JESUS.
ELE É O CAMINHO E A VIDA,
A VERDADE E A LUZ.

JESUS, AO APROXIMAR-SE,
JOÃO BATISTA APONTOU:
/CANTAR 2X
"EIS O CORDEIRO DE DEUS,                          
QUE VEIO AO MUNDO NOS DAR SALVAÇÃO".

OS DISCÍPULOS, DESANIMADOS
POR PESCAREM EM VÃO,
JESUS OS MANDA DE VOLTA AO MAR
E MUITOS PEIXES PESCAR.

ALEGRES DESCOBRIRAM: 
"O CORDEIRO DE DEUS 
/CANTAR 2X
ESTÁ VIVO ENTRE NÓS!"
REINA PRA SEMPRE O MEU SALVADOR!
');
