INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e0fcbebb-8ff9-4cd7-a837-8da67fe79e49', 'Eu Sou Pobre e Necessitado', '324', 'Paulo José Ferreira Marques', 'Balada', 'C', 'Consolo e Encorajamento', 'CANTAR 2X
EU SOU POBRE E NECESSITADO
MAS O SENHOR CUIDA DE MIM;
