INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e1303558-5d2c-4b3e-bf8c-6e2f67721860', 'Vivi tão longe do Senhor', '104', 'Let. e Mús.: John Willard Peterson; Trad. Irmangard Rehn, Helena de Morais Teixeira e Joan Larie Sutton', 'Guarânia', 'G', 'Dedicação', 'VIVI TÃO LONGE DO SENHOR,
ASSIM EU QUIS ANDAR;
ATÉ QUE EU ENCONTREI O AMOR
EM SEU GLORIOSO OLHAR.

CORO
SEU MARAVILHOSO OLHAR, (2X)
TRANSFORMOU MEU SER,
TODO O MEU VIVER,
SEU MARAVILHOSO OLHAR.

SEU CORPO VI NA RUDE CRUZ
SOFRENDO ASSIM POR MIM;
E OUVI A VOZ DO MEU JESUS:
"POR TI SOFRI ASSIM."

EM CONTRIÇÃO, ENTÃO, 
VOLTEI À FONTE DESSE AMOR;
PERDÃO E PAZ EM CRISTO ACHEI,
PERTENÇO AO SALVADOR.
');
