INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e231e0b2-0e5e-4ce8-bc8e-dfac4a4c3eed', 'Uma vez mais cantemos', '', '', '', '', '', 'UMA VEZ MAIS CANTEMOS
LOUVEMOS A TI SENHOR
POIS SOMOS MAIS QUE VENCEDORES
LOUVORES A TI DAREMOS.

*CORO
GLÓRIA A TI SENHOR PORQUE ESTOU AQUI
E PODIA ESTAR LARGADO, PELO MUNDO
PERTURBADO, MAIS ESTOU AQUI (ESTOU AQUI)
CHORANDO AOS TEUS PÉS.

A TUA GRAÇA SE MANISFESTOU
SALVOU, CUROU, NOS DEU VITÓRIA
E RENOVADOS HOJE CANTAREMOS
LOUVAREMOS A TUA GLÓRIA.

*CORO
GLÓRIA A TI SENHOR PORQUE ESTOU AQUI
E PODIA ESTAR LARGADO, PELO MUNDO
PERTURBADO, MAIS ESTOU AQUI (ESTOU AQUI)
CHORANDO AOS TEUS PÉS.

HÁ TANTAS COISAS PARA SE DIZER
DO TEU PODER EM NOSSAS VIDAS
OS ANOS PASSAM, MAS TU ÉS FIEL
EM TUDO VEMOS A TUA GLÓRIA.

*CORO 2X
GLÓRIA A TI SENHOR PORQUE ESTOU AQUI
E PODIA ESTAR LARGADO, PELO MUNDO
PERTURBADO, MAIS ESTOU AQUI (ESTOU AQUI)
CHORANDO AOS TEUS PÉS.
');
