INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e2838021-98f9-40a1-ad78-2cbc4f028815', 'A palavra de poder', '065', 'Let./Mús.: Geraldo de Souza Lima Filho', 'Básico', 'Bb', 'Avulso', 'A PALAVRA DE PODER SAIU DO SEU TRONO
ORDENANDO TODA CRIAÇÃO.
HAJA LUZ! (HOUVE LUZ)
HAJA LUA E ESTRELAS!
SUA GLÓRIA ESTENDIDA NO CÉU.

O SEU POVO GUIOU
COM A NUVEM DE DIA
E A NOITE O FOGO NÃO FALTOU.

*CORO
O MAR SE ABRIU, ISRAEL PASSOU,
O SURDO OUVIU, O CEGO ENXERGOU;
TUDO ISSO PELA PALAVRA DO SENHOR.

A PALAVRA DE PODER SAIU DO SEU TRONO
ORDENANDO TODA CRIAÇÃO.
HAJA LUZ! (HOUVE LUZ)
HAJA LUA E ESTRELAS!
SUA GLÓRIA ESTENDIDA NO CÉU.

O SEU POVO GUIOU
COM A NUVEM DE DIA
E A NOITE O FOGO NÃO FALTOU.

*CORO
O MAR SE ABRIU, ISRAEL PASSOU,
O SURDO OUVIU, O CEGO ENXERGOU;
TUDO ISSO PELA PALAVRA DO SENHOR.

CREIA, CRISTO PODE TRANSFORMAR
SUA TRISTEZA EM ALEGRIA,
VIDA NOVA LHE DARÁ.
CREIA, JESUS CRISTO NÃO MUDOU.
ELE É O MESMO EM NOSSOS DIAS,
ELE É O SALVADOR.

*CORO
O MAR SE ABRIU, ISRAEL PASSOU,
O SURDO OUVIU, O CEGO ENXERGOU;
TUDO ISSO PELA PALAVRA DO SENHOR.
/INSTRUMENTOS

*CORO
O MAR SE ABRIU, ISRAEL PASSOU,
O SURDO OUVIU, O CEGO ENXERGOU;
TUDO ISSO PELA PALAVRA DO SENHOR.
/FINAL
TUDO ISSO PELA PALAVRA DO SENHOR.
');
