INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e2f92539-53f7-4da7-919b-132869a1a436', 'Todo ser que tem fôlego', '231', 'C.M.V.', 'Balada', 'E', 'Crianças e Adolescentes', 'TODO SER QUE TEM FÔLEGO LOUVE,
LOUVE AO PAI, O SENHOR DOS SENHORES;
TODO SER QUE TEM FÔLEGO LOUVE,
LOUVE A JESUS, NOSSO REDENTOR.

TODO SER QUE TEM FÔLEGO LOUVE,
LOUVE AO ESPÍRITO SANTO DE DEUS;
/FINAL 2X
LOUVE, LOUVE,
LOUVE COM CÂNTICO NOVO
E TODO SEU SER.
');
