INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e4156019-0d81-48e5-96ff-378f63795468', 'O Poder do Sangue de Jesus', 28, 'Gérson Beluci Miguel', 'Básico', 'D', 'Clamor', 'O PODER DO SANGUE DE JESUS
HÁ DE ME PURIFICAR,
MEU PECADO PERDOAR.
O PODER DO SANGUE DE JESUS
DÁ-ME PLENA COMUNHÃO,
TRAZ-ME A REVELAÇÃO.

*CORO
ESTOU LIBERTO NA PRESENÇA DO SENHOR,
NOS SEUS ÁTRIOS HEI DE ENTRAR,
COM LOUVOR GLORIFICAR;
SUA GLÓRIA RESPLANDECE NO ALTAR,
SEU ESPÍRITO ME ALCANÇA COM AMOR.

O PODER DO SANGUE DE JESUS
FAZ-ME CAMINHAR NA LUZ,
BEM SEGURO ME CONDUZ.

*CORO
ESTOU LIBERTO NA PRESENÇA DO SENHOR,
NOS SEUS ÁTRIOS HEI DE ENTRAR,
COM LOUVOR GLORIFICAR;
SUA GLÓRIA RESPLANDECE NO ALTAR,
SEU ESPÍRITO ME ALCANÇA COM AMOR.
/FINAL 
HÁ PODER NO SANGUE DE JESUS. (2X)
');
