INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e44cc835-1249-448f-982f-9e54c226f071', 'No exílio', '025', '', '', '', '', 'NO EXÍLIO BEM DISTANTE,
MINHA TERRA VOU CANTAR,
É DE TODAS A MAIS BELA,
COM ELA VIVO A SONHAR,
É MAIS SALUBRE O SEU CLIMA
DO QUE DESTA SOLIDÃO.

CORO
EU TENHO SAUDADES DELA
OH! QUANDO IREI PRA SIÃO?
OH! BELA SIÃO, MINHA TERRA É SIÃO;
EU TENHO SAUDADES DELA,
OH! QUANDO IREI PRA SIÃO?

LÁ NÃO HÁ CHORO E NEM GUERRA,
E NEM MESMO REVOLUÇÃO,
PASTA O LOBO COM O CORDEIRO
E O NOVILHO COM O LEÃO,
E O MENINO APASCENTA
COM O CAJADO NA MÃO.

FINAL
OH! QUANDO IREI PRA SIÃO?
');
