INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e47a77af-8f35-4136-b143-fad4dc1cdabb', 'Onde estaria eu', 98, 'Roberto Cézar Fernandes', 'Novo', 'C', 'Dedicação', 'ONDE ESTARIA EU,
NÃO FOSSE A MÃO DO SENHOR?
SOZINHO, SOLITÁRIO NO MUNDO,
JESUS ME ALCANÇOU.

*CORO
QUERO, CADA DIA MAIS,
VIVER PRA TI, Ó MEU SENHOR;
QUERO, CADA DIA MAIS,
OUVIR A TUA VOZ DE AMOR.

HOJE ME SINTO EM PAZ,
SEGURO EM TUA MÃO ESTOU;
CAMINHO PARA A ETERNIDADE,
CANTANDO PARA O CÉU EU VOU.

*CORO 2X
QUERO, CADA DIA MAIS,
VIVER PRA TI, Ó MEU SENHOR;
QUERO, CADA DIA MAIS,
OUVIR A TUA VOZ DE AMOR.
/FINAL
OUVIR A TUA VOZ DE AMOR. (2X)
');
