INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e49bc31e-15c7-4f83-aa50-e88a596f0842', 'Eu me lembro quando Jesus me tocou', '100', 'Jorgemar Souza Madeira', 'Básico', 'A', 'Dedicação', 'EU ME LEMBRO QUANDO JESUS ME TOCOU,
FOI UM TOQUE DE ESPERANÇA E DE AMOR;
CRISTO TRANSFORMOU A MORTE NO VIVER
QUANDO A ELE ENTREGUEI TODO O MEU SER.

CORO
DEUS AMOU O MUNDO DE TAL MANEIRA
QUE ENVIOU SEU FILHO JESUS, UNIGÊNITO,
A MORRER NA CRUZ PRA NOS SALVAR E LIBERTAR-NOS.
/CANTAR 2X
CRISTO VIVE EM MIM, POSSO DIZER,
O SEU TOQUE FEZ MINH''ALMA RENASCER.

EU ME LEMBRO O QUE ELE FEZ POR MIM,
FOI SEU BRAÇO FORTE QUE ME FEZ ASSIM,
A CONHECER A ETERNA REDENÇÃO,
DE BÊNÇÃOS CRISTO ENCHEU MEU CORAÇÃO.
');
