INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e547885e-25cf-41e7-9a15-2a8d62bf9468', 'Na Hora em que eu quiser Falar com Deus', 49, 'Adriano de Souza Andrade', 'Básico', 'A', 'Clamor', 'NA HORA EM QUE EU
QUISER FALAR COM DEUS,
DOBRAR OS MEUS JOELHOS E ORAR,
/CANTAR 2X
EU VOU CLAMAR PRIMEIRO
PELO SANGUE DE JESUS,
SÓ ELE PODE ME PURIFICAR.

CANTAR 2X
SANGUE PRECIOSO,
QUE RENOVA A COMUNHÃO,
DÁ VIDA E PLENA PAZ AO CORAÇÃO.

NA HORA EM QUE EU
QUISER FALAR COM DEUS,
DOBRAR OS MEUS JOELHOS E ORAR,
/CANTAR 2X
EU VOU CLAMAR PRIMEIRO
PELO SANGUE DE JESUS,
SÓ ELE PODE ME PURIFICAR.

FINAL 2X
SANGUE PRECIOSO,
QUE RENOVA A COMUNHÃO,
DÁ VIDA E PLENA PAZ AO CORAÇÃO.
');
