INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e550843d-e08a-48ea-8886-cd1cd5a77f55', 'A Jesus seja dada toda glória', '682', 'Luciana Monteiro Carneiro Simora, Marciel Denadai', 'Básico', 'G', 'Grupo de Louvor', '*CORO
A JESUS SEJA DADA
TODA GLÓRIA E LOUVOR,
A JESUS SEJA DADA
TODA GLÓRIA, HONRA E LOUVOR.

CANTAR 2X
ESTÁ ASSENTADO NO TRONO,
À DIREITA DE DEUS PAI.
/CANTAR 2X
ADORADO POR ANJOS,
ENTRONIZADO ENTRE OS LOUVORES.

*CORO
A JESUS SEJA DADA
TODA GLÓRIA E LOUVOR,
A JESUS SEJA DADA
TODA GLÓRIA, HONRA E LOUVOR.

QUEREMOS TE ADORAR
EM ESPÍRITO E EM VERDADE,
A VERDADEIRA ADORAÇÃO
É A QUE PROCEDE DO CORAÇÃO, DO CORAÇÃO
DOS QUE LOUVAM AO SENHOR.

*CORO 2X
A JESUS SEJA DADA
TODA GLÓRIA E LOUVOR,
A JESUS SEJA DADA
TODA GLÓRIA, HONRA E LOUVOR.
');
