INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e566ae2b-cc87-4d76-bcc6-4a752b072a36', 'Vou caminhando pra Jerusalém', '134', 'E.H.M.R.', 'Country', 'E', 'Crianças e Adolescentes', 'VOU CAMINHANDO PRA JERUSALÉM,
A CADA DIA CHEGO MAIS PERTO,
QUEM ME CONDUZ É O MEU JESUS,
POIS NO CLAMOR SEU SANGUE LIMPA
E ANDO NA LUZ;

E TENHO ARMAS ESPIRITUAIS:
A ORAÇÃO, O LOUVOR,
O JEJUM E MADRUGADA
E A PALAVRA REVELADA
QUE ALIMENTA A ALMA,

E NOS ENSINA A VONTADE DO SENHOR.
VOU CAMINHANDO PRA JERUSALÉM.
SE VOCÊ QUISER, VENHA COMIGO TAMBÉM. (2X)
');
