INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e56c7877-11a2-4e0a-9232-7657fc8316a0', 'Jesus veio e salvou-me', '638', 'Keila Carvalho Klipper', 'Básico', 'E', 'Louvor', 'JESUS VEIO E SALVOU-ME
E ASSIM TRANSFORMOU O MEU VIVER,
AGORA POSSO ADORÁ-LO
E CONFIAR POIS É O MEU SALVADOR.

*CORO
DIGNO, SÓ ELE É DIGNO
DE RECEBER HONRA E LOUVOR,
E COMIGO ELE ESTÁ,
NUNCA VAI ME DEIXAR;
DIGNO É O SENHOR.
/INSTRUMENTOS

VITÓRIAS ELE CONCEDE-ME
E COM BÊNÇÃOS ENVOLVE O MEU SER
E EM MIM RENOVA A CADA DIA
A CERTEZA DA ETERNA SALVAÇÃO.

*CORO 2X
DIGNO, SÓ ELE É DIGNO
DE RECEBER HONRA E LOUVOR,
POIS COMIGO ELE ESTÁ,
NUNCA VAI ME DEIXAR;
DIGNO É O SENHOR.
/FINAL
DIGNO É O SENHOR. (3X)
');
