INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e63b5a58-7057-448c-ac7a-f5043558acac', 'Que vista amável é', '425', 'Sarah Poulton Kalley', 'Balada', 'D', 'Santificação e Derramamento', 'QUE VISTA AMÁVEL É
QUANDO, COM SANTO AMOR,
IRMÃOS UNIDOS PELA FÉ,
ADORAM O SENHOR.

O MUNDO OBSERVARÁ
AQUELA SANTA PAZ,
COMO UM PERFUME SENTIRÁ
O GOZO QUE ELA TRAZ.

ENVIA-NOS, JESUS,
DO TEU MONTE SIÃO,
O SANTO ESPÍRITO QUE PRODUZ
AQUELA DOCE UNIÃO.
');
