INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e64c9ae6-9ac0-4377-b331-bbab82e9dfa3', 'Eis-me aqui, Senhor, em teu altar', '051', 'Adriana Gomes Pereira Muniz', 'Básico', 'E', 'Crianças e Adolescentes', 'CANTAR 2X
EIS-ME AQUI, SENHOR, EM TEU ALTAR,
EIS-ME AQUI, SENHOR, PRONTO A TE ADORAR.

CANTAR 2X
SEI QUE A PRESENÇA DO SENHOR JESUS
NÃO FALHARÁ,
SEI QUE TU ESTÁS AQUI,
PRONTO A ABENÇOAR.
/INSTRUMENTOS

SANTO E GLORIOSO ÉS, CONOSCO ESTÁS,
SANTO E GLORIOSO, VIMOS TE ADORAR,
SANTO E GLORIOSO ÉS, Ó NOSSO AMADO,
DO TEU ESPÍRITO TENS DERRAMADO,
DANDO RENOVO E TRANSFORMANDO;
SANTO E GLORIOSO ÉS,
VEM EM NÓS TRANSBORDAR,
Ó SANTO ESPÍRITO, TOMA O TEU LUGAR.

FINAL 2X
SEI QUE A PRESENÇA DO SENHOR JESUS
NÃO FALHARÁ,
SEI QUE TU ESTÁS AQUI,
PRONTO A ABENÇOAR.
');
