INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e6525b18-8279-478a-8218-1170e021af4c', 'A Jesus irei louvar', '227', 'L.E.C.T.M. & E.H.M.R.', 'Valseado', 'F', 'Crianças e Adolescentes', 'A JESUS IREI LOUVAR,
POIS NA CRUZ SE DEU POR MIM.
O SEU SANGUE DERRAMOU,
MEU PECADO CARREGOU;
TODA DOR ELE LEVOU,
FOI QUEM PRIMEIRO ME AMOU.

FINAL 2X
COM QUERUBINS E SERAFINS
A JESUS IREI LOUVAR,
ALELUIA! GLÓRIA A DEUS!
LÁ NO CÉU EU VOU MORAR.
');
