INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e69cf88f-7773-431e-8a1e-0764fa0f9770', 'Ouvi como que a voz', '561', 'Marta Lílian Marques de Abreu', 'Básico', 'F#m', 'Grupo de Louvor', 'OUVI COMO QUE A VOZ
DE UMA GRANDE MULTIDÃO,
COMO VOZ DE MUITAS ÁGUAS,
COMO VOZ DE GRANDES TROVÕES
QUE DIZIA: ALELUIA!
O SENHOR TODO PODEROSO
REINA, REINA, REINA!

REGOZIJEMO-NOS, ALEGREMO-NOS,
DEMOS-LHE GLÓRIA!
PORQUE VINDAS SÃO AS BODAS DO CORDEIRO

REGOZIJEMO-NOS, ALEGREMO-NOS,
DEMOS-LHE GLÓRIA!
E A SUA ESPOSA JÁ SE PREPAROU.
/INSTRUMENTOS

OUVI COMO QUE A VOZ
DE UMA GRANDE MULTIDÃO,
COMO VOZ DE MUITAS ÁGUAS,
COMO VOZ DE GRANDES TROVÕES
QUE DIZIA: ALELUIA!
O SENHOR TODO PODEROSO
REINA, REINA, REINA!
/FINAL 3X
AMÉM.
');
