INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e69e18f8-2d7e-4336-a23b-c152e4e60e54', 'Senhor suplico a ti em oração', '042', 'Jorgemar Souza Madeira', 'Marcha', 'Em', 'Clamor', 'SENHOR, SUPLICO A TI EM ORAÇÃO:
FAZE DE MIM UM VASO NOVO,
DERRAMA O SANGUE DE JESUS EM MIM.

*CORO
PERMITE-ME QUE ENTRE 
NO SANTO DOS SANTOS,
PERDOA-ME DO VIL PECADO,
ESTENDE A TUA MÃO.

PRECISO CONTEMPLAR A TUA GLÓRIA,
CONCEDE-ME TUA VITÓRIA,
DERRAMA O SANGUE DE JESUS EM MIM.

*CORO
PERMITE-ME QUE ENTRE 
NO SANTO DOS SANTOS,
PERDOA-ME DO VIL PECADO,
ESTENDE A TUA MÃO.
/FINAL
SENHOR, SENHOR.
SENHOR, SENHOR, SENHOR.
');
