INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e7aa4e9a-fa1f-496e-a237-99d8b77e9f5e', 'Forte Deus', 19, 'Emanuel Aleixo Junior', '', '', 'Avulsos', 'FORTE DEUS, TODO-PODEROSO,
A TUA PAZ EXCEDE TODO ENTENDIMENTO.
E A TUA PAZ GUARDARÁ OS NOSSOS CORAÇÕES
E OS NOSSOS PENSAMENTOS
EM CRISTO JESUS.

TODO-PODEROSO DEUS,
DEUS FORTE, MAGNIFICENTE, EMANUEL,
TUA GLÓRIA ENCHERÁ TODA A TERRA;
INCOMPARÁVEIS SÃO AS TUAS OBRAS,
Ó DEUS! GRANDIOSO ÉS!

NOS ENSINASTE, ENTÃO,
TUDO O QUE É VERDADEIRO,
NISSO PENSAI.
O QUE É PURO E JUSTO,
SE HÁ ALGUM LOUVOR, NISSO PENSAI.

À SOMBRA DA MORTE
ANDÁVAMOS PERDIDOS,
E EM MEIO ÀS TREVAS
RESPLANDECEU A LUZ.
E AGORA LIBERTOS,
EXULTAREMOS EM CRISTO,
QUE VEIO AO MUNDO
PARA SALVAÇÃO NOS DAR.

UM MENINO NOS NASCEU
E SOBRE OS SEUS OMBROS
O PRINCIPADO ESTÁ,
E SE CHAMARÁ O SEU NOME:
CONSELHEIRO, MARAVILHOSO,
FORTE DEUS E PRÍNCIPE DA PAZ.

DA ETERNIDADE É PAI,
E O PRINCIPADO ETERNO SUBSISTIRÁ
COM JUÍZO E COM JUSTIÇA,
FIRMADO AGORA E ETERNAMENTE,
PELO ZELO DO SENHOR.

/FINAL
TODO-PODEROSO DEUS,
DEUS FORTE, MAGNIFICENTE, EMANUEL,
TUA GLÓRIA ENCHERÁ TODA A TERRA;
INCOMPARÁVEIS SÃO AS TUAS OBRAS,
GRANDIOSO ÉS.
');
