INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e8544d2c-7e62-4263-88a3-3b3bc733a7b3', 'Escuta-me, Senhor', '052', 'Maghdielly Rubim Cavalcante Lima Mombrini', 'Básico 2', 'G', 'Clamor', 'ESCUTA-ME, SENHOR, 
ESCUTA AS MINHAS SÚPLICAS,
INCLINA OS TEUS OUVIDOS À MINHA VOZ. 
CLAMO, Ó SENHOR,
PELO SANGUE DE JESUS,
VEM ME LIBERTAR E ME TRANSFORMAR.
/INSTRUMENTOS

RENOVA A MINHA VIDA,
ENCHE-ME DE GOZO E DE PAZ,
UNGE-ME A CABEÇA
COM O ÓLEO DO TEU ESPÍRITO
E O MEU CÁLICE TRANSBORDA,
RENOVA-ME, SENHOR.

CLAMO, Ó SENHOR,
PELO SANGUE DE JESUS,
VEM ME LIBERTAR E ME TRANSFORMAR,
RENOVA A MINHA VIDA,
ENCHE-ME DE GOZO E PAZ,
TRANSBORDA EM MIM, SENHOR,
A TUA GRAÇA E TEU AMOR.
');
