INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e8659c2f-3e56-4921-bb81-82005e4be644', 'Quem é Esta Que Aparece', '513', 'Juarez Malavasi', 'Básico', 'Dm', 'Volta de Jesus e Eternidade', 'QUEM É ESTA QUE APARECE
COMO A ALVA DO DIA,
FORMOSA COMO A LUA, PURA COMO O SOL,
FORMIDÁVEL COMO UM EXÉRCITO COM BANDEIRAS!

DESCI AO JARDIM DAS NOGUEIRAS,
PARA MIRAR OS RENOVOS DO VALE,
PARA VER SE BROTAVAM AS VIDES,
SE FLORESCIAM AS ROMEIRAS.
NÃO SEI COMO, IMAGINEI-ME
NO CARRO DO MEU NOBRE POVO!

FINAL 2X
VOLTA, VOLTA, Ó, SULAMITA,
VOLTA, VOLTA,
PRA QUE NÓS TE CONTEMPLEMOS;
POR QUE QUEREIS CONTEMPLAR A SULAMITA,
NA DANÇA DE MAANAIM? (2X)
');
