INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e8934a59-848a-4c31-b5c1-135c217a2d46', 'Louvamos-te, ó Deus', '644', 'Let.: William Panton Mackay; Trad.: James Theodore Houston; Mús.: John Jenkins Husband', 'Valseado', 'F', 'Grupo de Louvor', 'LOUVAMOS-TE, Ó DEUS,
PELO DOM DE JESUS,
QUE POR NÓS, PECADORES,
FOI MORTO NA CRUZ.

CORO
ALELUIA! TODA A GLÓRIA
TE RENDEMOS SEM FIM;
ALELUIA! TUA GRAÇA IMPLORAMOS.
AMÉM.

LOUVAMOS-TE, Ó DEUS,
PELO ESPÍRITO E SUA LUZ,
QUE AS TREVAS DISSIPA,
E A CRISTO CONDUZ.

LOUVAMOS-TE, SENHOR,
Ó CORDEIRO DE DEUS,
FOSTE MORTO, MAS VIVES,
ETERNO, NOS CÉUS.

VEM ENCHER-NOS, Ó DEUS,
DE CELESTE ARDOR
E FAZER-NOS SENTIR
TÃO IMENSO AMOR.
');
