INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e91c543b-87ae-4d4b-87f7-f797ead73144', 'Dobro os meus joelhos', 9, 'A. C. C. C.', 'Básico', 'C', 'Crianças e Adolescentes', 'DOBRO OS MEU JOELHOS
PARA A TI CLAMAR, SENHOR,
TOCA O MEU INTERIOR, 
TOCA-ME SENHOR,
DIANTE DE TI ESTOU PARA TE ADORAR;

GUIA-ME SENHOR, PELO TEU AMOR,     
PAZ E SEGURANÇA QUERO TER
COM JESUS MEU SENHOR.
/INSTRUMENTOS

DOBRO OS MEU JOELHOS
PARA A TI CLAMAR, SENHOR,
TOCA O MEU INTERIOR, 
TOCA-ME SENHOR,
DIANTE DE TI ESTOU PARA TE ADORAR;

GUIA-ME SENHOR, PELO TEU AMOR,     
PAZ E SEGURANÇA QUERO TER
COM JESUS
/FINAL
GUIA-ME SENHOR, PELO TEU AMOR,     
PAZ E SEGURANÇA QUERO TER
COM JESUS, MEU SENHOR.
');
