INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e96ae96b-8e81-4002-9167-97898e29e8e8', 'Ainda Que os Seus Sonhos', '276', 'Leonardo Jundi Eto', 'Básico', 'C', 'Morte, Ressureição e Salvação', 'AINDA QUE OS SEUS SONHOS CAIAM PELO CHÃO
E NÃO ENCONTRE UMA SAÍDA, UMA SOLUÇÃO,
A VIDA PODE SER DIFÍCIL DE RESOLVER;
E NESTA HORA QUE VOCÊ PRECISA RECONHECER.
/INSTRUMENTOS

O MUNDO NÃO O CONHECE, 
POR ISSO ELE PERECE.
JESUS QUER SE DAR A CONHECER.
VENHA A VERDADE RECEBER.

*CORO
O FILHO DO DEUS ETERNO É JESUS.
ELE VEIO TE RESGATAR DAS TREVAS PARA A LUZ,
DAS TREVAS PARA A LUZ.
ABRA AGORA O TEU CORAÇÃO A JESUS.
/INSTRUMENTOS

O MUNDO NÃO O CONHECE, 
POR ISSO ELE PERECE
JESUS QUER SE DAR A CONHECER.
VENHA A VERDADE RECEBER.

*CORO 2X
O FILHO DO DEUS ETERNO É JESUS.
ELE VEIO TE RESGATAR DAS TREVAS PARA A LUZ,
DAS TREVAS PARA A LUZ.
ABRA AGORA O TEU CORAÇÃO A JESUS.
