INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e98e145e-c2bd-438a-8be4-4283977dc0b4', 'O amor de Jesus é grande', '171', 'Jorgemar Souza Madeira', 'Básico', 'E', 'Dedicação', 'CANTAR 2X
O AMOR DE JESUS É GRANDE,
IMENSURÁVEL ESSE AMOR,
NÃO SE PODE COMPARAR, NEM MEDIR,
O INFINITO AMOR DE DEUS.

DEMONSTRADO LÁ NA CRUZ
POR JESUS, MEU REI,
PRA SALVAR O POBRE PECADOR,
OH! QUE GRANDE AMOR.
/INSTRUMENTOS

O AMOR DE JESUS É GRANDE,
IMENSURÁVEL ESSE AMOR,
NÃO SE PODE COMPARAR, NEM MEDIR,
O INFINITO AMOR DE DEUS.

CANTAR 2X
DEMONSTRADO LÁ NA CRUZ
POR JESUS, MEU REI,
PRA SALVAR O POBRE PECADOR,
OH! QUE GRANDE AMOR.
/FINAL
OH! QUE GRANDE AMOR. (2X)
');
