INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e9ad47ba-c27a-40b8-bcaf-a8280ad17cfc', 'Que calor é este em voltado altar', '748', 'Autor Desconhecido', 'Marcha', 'E', 'Corinhos', 'QUE CALOR É ESTE EM VOLTA DO ALTAR? (3X)
É O PODER DE DEUS QUE ESTÁ NESTE LUGAR,
É O PODER DE DEUS QUE ESTÁ NESTE LUGAR.

QUEIMA, QUEIMA,
QUEIMA COM FOGO DA GLÓRIA,
QUEIMA, QUEIMA,
QUEIMA POR DENTRO E POR FORA,
QUEIMA, QUEIMA,
QUEIMA OS PECADOS DE AGORA,

FINAL 2X
QUEIMA COM FOGO DIVINO 
POIS SÓ SEU PODER NOS DÁ A VITÓRIA.
');
