INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('e9eca650-2955-42f8-8c7b-b48dcfba6751', 'Às vezes alguém me pergunta', '131', 'Autor Desconhecido', 'Balada', 'E', 'Dedicação', 'ÀS VEZES, ALGUÉM ME PERGUNTA
PORQUE VIVO A ALEGRE E SEMPRE A CANTAR;
RESPONDO: SOU MUITO FELIZ,
PORQUE JESUS CRISTO VEIO EM MIM MORAR.

CORO
ACHEI A FELICIDADE,
EU NÃO ESPERAVA
QUE A FOSSE ENCONTRAR;
MAS UM DIA ENCONTREI COM JESUS
E A FELICIDADE VEIO EM MIM MORAR.

ÀS VEZES, O MEU CORAÇÃO
FICA PERTURBADO, PERDENDO A PAZ;
AOS PÉS DO MEU SALVADOR,
ACHEI O SEGREDO DA PERFEITA PAZ.
');
