INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ea260d02-e863-47a7-be4d-e657071045c7', 'E tudo posso naquele que me fortalece', '110', 'C.M.V.', 'Marcha', 'C', 'Crianças e Adolescentes', 'CORO 2X
EU TUDO POSSO
NAQUELE QUE ME FORTALECE.

CANTAR 2X
EU VÔO COMO UMA ÁGUIA,
EU CRUZO MONTANHAS E VALES.

CANTAR 2X
EU VENÇO GIGANTES, EU VENÇO LEÕES,
EU VENÇO OS LOBOS DO MUNDO.

CANTAR 2X
EU CREIO NUM DEUS QUE VIVE E REINA,
EU CREIO NUM DEUS QUE VENCE POR MIM.
');
