INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ea3b5b42-773e-4bc9-a9ef-4e16cc108639', 'Cristo, meu mestre, sempre há de amar - me', '142', 'Norman J. Clayton', 'Básico', 'E', 'Dedicação', 'CRISTO, MEU MESTRE, SEMPRE HÁ DE AMAR-ME
E DELE O MAL NÃO PODE AFASTAR-ME;
DEU SUA VIDA PRA ME SALVAR
E AGORA DELE SOU.

*CORO
SOU DE JESUS, MEU MESTRE,
CRISTO JESUS É MEU;
NÃO SÓ NOS DIAS QUE SE VÃO,
MAS, PARA SEMPRE, AMÉM.
/INSTRUMENTOS

PERDIDO, AFEITO AO MAL, DEGRADADO,
ME CONCEDEU PERDÃO DO PECADO;
NÃO ANDO TRISTE, JÁ SOU FELIZ
E AGORA DELE SOU.

*CORO
SOU DE JESUS, MEU MESTRE,
CRISTO JESUS É MEU;
NÃO SÓ NOS DIAS QUE SE VÃO,
MAS, PARA SEMPRE, AMÉM.
/INSTRUMENTOS

EU CANTO DE ALEGRIA DE SALVO,
MEU CORAÇÃO JESUS DEIXOU ALVO,
POIS O SEU SANGUE ME PURIFICOU
E AGORA DELE SOU.

*CORO
SOU DE JESUS, MEU MESTRE,
CRISTO JESUS É MEU;
NÃO SÓ NOS DIAS QUE SE VÃO,
MAS, PARA SEMPRE, AMÉM.
');
