INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ea70ec7b-04ae-4d7f-b0eb-714c3878ffda', 'Oh! Contemplai', '626', 'Paulo Emanuel dos Santos Teixeira', 'Básico', 'D', 'Louvor', 'OH! CONTEMPLAI E VEDE ESTE AMOR,
O AMOR DE JESUS CRISTO POR NÓS,
SE DEU, SE ENTREGOU POR TI E POR MIM,
NOS RESGATOU, COM SEU SANGUE
NOS COMPROU.

DA MORTE ELE É O VENCEDOR,
DA VIDA ETERNA ELE É SENHOR,
PALAVRA DE DEUS É O SEU NOME,
REI DOS REIS, SENHOR DOS SENHORES.

DIGNO É DE RECEBER A GLÓRIA E O LOUVOR
E AÇÕES DE GRAÇAS;
DIGNO É DE RECEBER A HONRA E O PODER
PARA TODO O SEMPRE.
JESUS.

OH! CONTEMPLAI E VEDE ESTE AMOR,
O AMOR DE JESUS CRISTO POR NÓS,
SE DEU, SE ENTREGOU POR TI E POR MIM,
NOS RESGATOU, COM SEU SANGUE
NOS COMPROU.

DA MORTE ELE É O VENCEDOR,
DA VIDA ETERNA ELE É SENHOR,
PALAVRA DE DEUS É O SEU NOME,
REI DOS REIS, SENHOR DOS SENHORES.

FINAL
DIGNO É DE RECEBER A GLÓRIA E O LOUVOR
E AÇÕES DE GRAÇAS;
DIGNO É DE RECEBER A HONRA E O PODER
PARA TODO O SEMPRE.
JESUS.
');
