INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('eab1163a-1c6a-4878-9136-2e965fb558ba', 'Estou aqui pra confessar', '005', 'E.E.M.R.', 'Valseado', 'G', 'Crianças e Adolescentes', 'ESTOU AQUI PRA CONFESSAR
A TI OS MEUS PECADOS
PRECISO DO TEU PERDÃO,
DA TUA COMUNHÃO

ESTOU AQUI PRA TE PEDIR:
LIMPA MEU CORAÇÃO,
COMO A BRANCA LÃ
TORNA-O, SENHOR.

SUSTENTA-ME EM TUAS MÃOS, JESUS,
PROTEGIDO EM TEUS BRAÇOS QUERO ESTAR;
ESCONDE-ME DE TODA A MALDADE
E SEMPRE CONTIGO VOU ANDAR. (2X)
');
