INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('eb020d5f-b75f-449d-91d6-09157a047053', 'Derramarei meu Espírito', '440', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'A', 'Santificação e Derramamento', 'DERRAMAREI MEU ESPÍRITO
SOBRE TODA CARNE E VOSSOS FILHOS
E VOSSAS FILHAS PROFETIZARÃO,
OS VOSSOS VELHOS TERÃO SONHOS,
VOSSOS MANCEBOS VISÕES.

CORO 2X
POIS DERRAMAREI MEU ESPÍRITO
SOBRE TODA A CARNE,

ESPERAI, POIS, A PROMESSA
QUE DE MIM OUVISTES:
JOÃO BATIZOU COM ÁGUA,
MAS EU VOS BATIZO
COM MEU ESPÍRITO, COM MEU PODER;
DE MIM SEREIS TESTEMUNHAS.
');
