INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('eb53c770-a253-497c-a00a-3cbc34b3b1b5', 'Deus Tem Um Plano (Coro Masculino)', '', '', '', '', '', 'DEUS TEM UM PLANO EM CADA CRIATURA,
AOS ASTROS ELE DÁ O CÉU;
A CADA RIO ELE DÁ UM LEITO,
E UM CAMINHO PARA MIM TRAÇOU.

CORO
A MINHA VIDA EU ENTREGO
A DEUS, POIS O SEU FILHO
ENTREGOU POR MIM.
NÃO IMPORTA ONDE FOR,
SEGUIREI MEU SENHOR,
SOBRE TERRA E MAR,
ONDE DEUS MANDAR, IREI.

EM SEU QUERER ENCONTRO PAZ NA VIDA,
E BÊNÇÃOS QUE JAMAIS GOZEI;
EMBORA VENHAM LUTAS E TRISTEZAS,
TENHO FÉ QUE DEUS ME GUIARÁ.
');
