INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ec17178c-365c-4958-a895-002b19cffbad', 'Em Meu Coração', '135', 'Roberto Cézar Fernandes', 'Básico', 'C', 'Dedicação', 'EM MEU CORAÇÃO REINA UMA DOCE PAZ
DE ALGUÉM QUE POR MIM MORREU
PRA ME DAR A SALVAÇÃO.

ESSE ALGUÉM, EU SEI, É JESUS, O REI,
QUE SE FEZ PEQUENO EM MEU LUGAR
PARA A VIDA ETERNA ME DAR.
/INSTRUMENTOS

GLÓRIA E ALELUIA A JESUS CANTAREI,
/FINAL 2X
COM GRATIDÃO E LOUVOR,
PARA TODO O SEMPRE, AMÉM!
');
