INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ec28fc6a-a2e6-4e3f-b4bd-7051a6a5626a', 'Clamor de Ana', '', '', '', '', '', 'MEU SENHOR, OUVE A ORAÇÃO DA TUA SERVA,
QUÃO EMBRIAGADA DE AMARGURA
VEM FAZER UM VOTO EM TEU ALTAR.
OH MEU PAI, VEM E ME ATENDE NESTA
HORA FALEI DO MEU DESGOSTO
ATÉ AGORA ESTOU ATRIBULADA
EM MEU ESPIRITO.

*CORO
AH, O MEU SENHOR LEMBROU
DE MIM QUANDO EU CHOREI DE AFLIÇÃO
E ELE PRA CONSOLO DE MINH’ALMA
RESPONDEU MINHA ORAÇÃO
AH! O MEU SENHOR LEMBROU
DE MIM DAS MINHAS ENTRANHAS
VAI NASCER A BENÇÃO QUE ELE
PREPAROU PARA MIM PRA ALEGRAR
O MEU VIVER.

MEU SENHOR, OUVE A ORAÇÃO
DA TUA SERVA, QUÃO EMBRIAGADA
DE AMARGURA VEM FAZER UM VOTO
EM TEU ALTAR.
OH MEU PAI, VEM E ME ATENDE
NESTA HORA FALEI DO MEU DESGOSTO
ATÉ AGORA ESTOU ATRIBULADA
EM MEU ESPIRITO.

*CORO
AH, O MEU SENHOR LEMBROU
DE MIM QUANDO EU CHOREI
DE AFLIÇÃO E ELE PRA CONSOLO
DE MINH’ALMA RESPONDEU
MINHA ORAÇÃO
AH! O MEU SENHOR LEMBROU
DE MIM DAS MINHAS ENTRANHAS
VAI NASCER A BENÇÃO QUE ELE
PREPAROU PRA MIM PRA ALEGRAR
O MEU VIVER.
');
