INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ec5a9dce-b48a-45e8-a41e-cba042e10f5f', 'Eu sirvo um Deus', '200', 'A.D.', 'Balada', 'C', 'Dedicação', 'EU SIRVO UM DEUS
QUE É TÃO BOM PRA MIM,
EU SIRVO UM DEUS
QUE É MEU TUDO, ENFIM;
EU SIRVO UM DEUS
QUE AO MEU LADO ESTÁ,
EU SIRVO UM DEUS
QUE AO CÉU ME LEVARÁ.

*CORO
OH! ALELUIA NÓS SERVIMOS A UM DEUS VIVO,
QUE NOS LIVRA DOS PERIGOS
E NOS FAZ ASSIM CANTAR;
OH! ALELUIA, NÓS SERVIMOS A UM DEUS VIVO,
ELE É REI, ELE É AMIGO,
COMO O NOSSO DEUS NÃO HÁ.

EU SIRVO UM DEUS
QUE ABRIU O MAR VERMELHO,
EU SIRVO UM DEUS
QUE AMOU O MUNDO INTEIRO,
EU SIRVO UM DEUS
QUE ENVIOU JESUS,
EU SIRVO UM DEUS
QUE É GRAÇA E LUZ.

*CORO
OH! ALELUIA NÓS SERVIMOS A UM DEUS VIVO,
QUE NOS LIVRA DOS PERIGOS
E NOS FAZ ASSIM CANTAR;
OH! ALELUIA, NÓS SERVIMOS A UM DEUS VIVO,
ELE É REI, ELE É AMIGO,
COMO O NOSSO DEUS NÃO HÁ.
/FINAL
NÃO HÁ, NÃO HÁ.
');
