INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ecebd52b-c808-41cb-b30c-be52f0d8455c', 'Somos Teu Povo, Tua Igreja', '', '', '', '', '', 'É TEU POVO AQUI PRESENTE
TODOS NUMA SÓ VOZ,
DECLARANDO QUE SÓ TÚ ÉS GRANDE,
EXALTAMOS TEU DOCE NOME
PELO AMOR, PELA CRUZ,
POR TEU FILHO JESUS.

*CORO 2X
É TEU POVO AQUI PRESENTE TODOS
NUMA SÓ VOZ DECLARANDO
QUE SÓ TÚ ÉS GRANDE.
EXALTAMOS TEU DOCE NOME PELO AMOR,
PELA CRUZ, POR TEU FILHO JESUS.

FINAL 2X
POIS ÉS SANTO, SIM ÉS DIGNO
DE LOUVOR E DE SER ADORADO
ÉS BONDOSO, PAI QUERIDO,
DENTRE TODAS AS COISAS
TÚ ÉS VERDADEIRO SENHOR.
');
