INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ed6b0fa5-b5dd-4d8b-86b7-5e381da6ae25', 'Servo do Senhor eu sou', '159', 'M.L.B.O.', 'Básico', 'C', 'Crianças e Adolescentes', 'SERVO DO SENHOR EU SOU
E POSSO OUVIR SUA VOZ.
SERVO DO SENHOR
E QUERO SERVIR A JESUS.

UMA SÓ VOZ FALA AO MEU CORAÇÃO,
A VOZ DE JESUS, MEU SENHOR.
OUÇO A VOZ DO PERFEITO AMOR,
A VOZ DO MEU BOM SALVADOR.

SE VOCÊ TAMBÉM QUISER,
PODE OUVIR A JESUS.
BASTA ABRIR SEU CORAÇÃO
E DEIXAR ENTRAR SUA LUZ.

E UMA VOZ FALARÁ AO SEU CORAÇÃO,
A VOZ DE JESUS, O SENHOR.
SÓ A DOCE VOZ ENCHERÁ SEU CORAÇÃO
DE PAZ, ALEGRIA E AMOR. (2X)
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('ed6b0fa5-b5dd-4d8b-86b7-5e381da6ae25', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
