INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ed8f4c87-cc08-4068-9d3c-78d1365c3976', 'Deus dos antigos', '669', 'Let.: Daniel Crane Roberts; Trad. João Wilson Faustini; Adap. Débora Giestas Fernandes; Mus. George William Warren', 'Marcha', 'E', 'Grupo de Louvor', 'DEUS DOS ANTIGOS, CUJA FORTE MÃO
REGE E SUSTÉM OS ASTROS DA AMPLIDÃO;
DO CINTILANTE CÉU INSPIRADOR,
COM GRATIDÃO CANTAMOS TEU LOUVOR.

JÁ NO PASSADO FOSTE NOSSA LUZ,
HOJE ÉS FAROL QUE À VIDA NOS CONDUZ;
SÊ NOSSO ESTEIO, GUIA E PROTEÇÃO,
TUA PALAVRA É LEI E DIREÇÃO.

TEU POVO, Ó DEUS, RESTAURA EM SEU LABOR,
TRANSFORMA A NOITE EM DIA DE ESPLENDOR;
AS NOSSAS VIDAS VEM FORTALECER
PARA TEU NOME SEMPRE ENGRANDECER.
AMÉM.
');
