INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ed9427f6-4dae-4942-92e8-f955e94791ec', 'Reunimo - nos aqui', '576', 'Gérson Beluci Miguel', 'Básico', 'B', 'Louvor', 'REUNIMO-NOS AQUI PRA TE ADORAR, SENHOR,
PARA TE OFERTAR O NOSSO CORAÇÃO;
TODO O NOSSO SER SE RENDE A TI;
NOSSA ALMA EXALTA O TEU AMOR
EM PERFEITA E PLENA COMUNHÃO.

HONRA AO PAI DE LUZ,
AO SENHOR JESUS
E AO ESPÍRITO SANTO;
TODA GLÓRIA, PODER, VITÓRIA,
HOJE E ETERNAMENTE.
/INSTRUMENTOS

REUNIMO-NOS AQUI PRA TE ADORAR, SENHOR,
PARA TE OFERTAR O NOSSO CORAÇÃO;
TODO O NOSSO SER SE RENDE A TI;
NOSSA ALMA EXALTA O TEU AMOR
EM PERFEITA E PLENA COMUNHÃO.

HONRA AO PAI DE LUZ,
AO SENHOR JESUS
E AO ESPÍRITO SANTO;
TODA GLÓRIA, PODER, VITÓRIA,
HOJE E ETERNAMENTE.
');
