INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('edce03a8-2eb8-4029-9002-f29af4c40cef', 'A igreja que ora é vitoriosa', '146', 'E.H.M.R.', 'Fox', 'D', 'Crianças e Adolescentes', 'A IGREJA QUE ORA É VITORIOSA,
SEMPRE ESTÁ NA DEPENDÊNCIA DO SENHOR;
A IGREJA QUE ORA É VITORIOSA,
MUITOS MILAGRES ACONTECEM.
/CANTAR 2X
PORQUE É UM CORPO VIVO
ONDE O CABEÇA É JESUS.

SE UMA BENÇÃO QUER
DOBRA OS SEUS JOELHOS,
CLAMA, ORA, BUSCA SUA FACE;
ORANDO, CANTANDO, VERÁS
O FRUTO DO ESPÍRITO SANTO.
');
