INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('edfa2a86-3f13-4f80-a550-20fe371da3a2', 'O Senhor é o Meu Pastor', '', '', '', '', 'Avulsos', 'O SENHOR É O MEU PASTOR, E NADA ME FALTARÁ. (M)
EM VERDES CAMPINAS ME FAZEM POUSAR, (M)
QUE ÁGUAS TRANQUILAS ACHAR. (M)
/O SENHOR É O MEU PASTOR, E NADA ME FALTARÁ. (H)
EM VERDES CAMPINAS ME FAZEM POUSAR, (H)
QUE ÁGUAS TRANQUILAS ACHAR. (H)

GUIA-ME NOS CAMINHOS DA VIDA, (M)
POR AMOR DO SEU SANTO NOME; (M)
/GUIA-ME NOS CAMINHOS DA VIDA, (H)
POR AMOR DO SEU SANTO NOME. (H)

MESMO QUE EU ANDE NO VALE DA MORTE, (H)
NÃO TEMEREI;(H) 
COM TEU CAJADO
TU ME PROTEGES. COM INIMIGOS EU CEAREI.

UNGES MINHA CABEÇA
COM ÓLEO;
TRANSBORDAS MINHA TAÇA DE VINHO.

CERTO ESTOU DA TUA MISERICÓRDIA,
E VIVEREI NO TEU AMOR.
FINAL
E HABITAREI,
HABITAREI
ETERNAMENTE NA CASA DO SENHOR.
/AMÉM
');
