INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ee240b8b-79da-4c6a-85e1-5fe45d682d1d', 'Sei que Cristo voltará', '212', 'Autor Desconhecido', 'Country', 'C', 'Crianças e Adolescentes', 'SEI QUE CRISTO VOLTARÁ,
POIS NA BÍBLIA ESCRITO ESTÁ,
JOÃO CARTOZE, UM, DOIS, TRÊS
LEDE, POIS, E SABEREIS.

SEI QUE ELE VOLTA, (3X)
NA BÍBLIA ESCRITO ESTÁ.
');
