INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ee6e5ab6-1b9e-490a-9155-6f7d840d8341', 'Ele um dia voltará', '491', 'Licurgo de Melo França', 'Básico', 'C', 'Volta de Jesus e Eternidade', 'ELE UM DIA VOLTARÁ, VEM BUSCAR A SUA IGREJA,
MEU JESUS, MEU JESUS VOLTARÁ;
TODA TERRA ESTREMECEU NO DIA DA SUA PARTIDA,
MEU JESUS, MEU JESUS, MINHA VIDA.

NOSSO FARDO ELE CARREGOU,
TODO O SEU AMOR NOS DEU,
NOSSAS DORES CONSIGO LEVOU,
VIDA NOVA NOS OFERECEU;

COMO É BOM SERVIR AO MEU JESUS,
SEU NOME GLORIFICAR;
SUA GLÓRIA NOS CONDUZ
A ANDAR NA SUA LUZ, A JESUS QUERO LOUVAR!

NOSSO FARDO ELE CARREGOU,
TODO O SEU AMOR NOS DEU,
NOSSAS DORES CONSIGO LEVOU,
VIDA NOVA NOS OFERECEU;

COMO É BOM SERVIR AO MEU JESUS,
SEU NOME GLORIFICAR;
SUA GLORIA NOS CONDUZ
A ANDAR NA SUA LUZ, A JESUS QUERO LOUVAR!
/FINAL
LOUVAR, LOUVAR.
');
