INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('eeee8e0d-e260-44a2-a368-b8e8223af612', 'Maranata', '218', 'A.A.F.A.;E.H.M.R.', 'Básico', 'd', 'Crianças e Adolescentes', '*CORO 2X
MARANATA,
MARANATA,
JESUS BREVE VIRÁ!

EU VOU SUBIR, POIS A TROMBETA ESCUTAREI;
E LÁ NAS NUVENS COM JESUS ME ENCONTRAREI.
DESPERTA IGREJA, VAMOS SUBIR!
O TEU LUGAR NÃO É AQUI,
PORQUE EM BREVE JESUS VIRÁ.

*CORO 2X
MARANATA,
MARANATA,
JESUS BREVE VIRÁ!

EU VOU SUBIR, POIS A TROMBETA ESCUTAREI;
E LÁ NAS NUVENS COM JESUS ME ENCONTRAREI.
DESPERTA IGREJA, VAMOS SUBIR!
O TEU LUGAR NÃO É AQUI,
PORQUE EM BREVE JESUS VIRÁ.

FINAL
DESPERTA IGREJA, VAMOS SUBIR!
O TEU LUGAR NÃO É AQUI,
PORQUE EM BREVE JESUS VIRÁ.
');
