INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ef2a1228-f3ea-4227-bac0-671cc5bf66d5', 'Temei a Deus', '484', 'Paulo Emanuel dos Santos Teixeira', 'Básico', 'A', 'Volta de Jesus e Eternidade', '"TEMEI A DEUS E DAI-LHE GLÓRIA,
POIS É CHEGADA A HORA DO SEU JUÍZO;
E ADORAI AQUELE QUE FEZ O CÉU E A TERRA
E O MAR E AS FONTES DAS ÁGUAS."

CANTAR 2X
TUA IGREJA TE ESPERA,
TODOS OS SINAIS SÃO CUMPRIDOS,
DO FIRMAMENTO TU NOS OUVES,
VEM JÁ, JESUS!
/FINAL
VEM JÁ, JESUS!
');
