INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('efe479d1-a3ac-47e9-bf98-931803e71a15', 'O Sentido de Viver', '226', 'José Elias Simora', 'Básico', 'E', 'Morte, Ressureição e Salvação', 'O SENTIDO DE VIVER
ENCONTRAMOS EM JESUS,
ELE É A SALVAÇÃO QUE HOJE PODES TER;
É SÓ ABRIR TEU CORAÇÃO,
DEIXAR CRISTO HABITAR,
A PAZ E A ALEGRIA EM TI IRÃO REINAR.

*CORO 2X
JESUS, O SENTIDO DE VIVER,
(DE VIVER SÓ PRA JESUS)
JESUS, O AMOR, A PAZ REAL,
NÃO HÁ OUTRO AMOR IGUAL.

JESUS CRISTO VAI VOLTAR,
ELE UM DIA PROMETEU,
E SEREMOS TRANSFORMADOS
PARA O ENCONTRO COM O SENHOR;
ESTAREMOS PARA SEMPRE 
COM JESUS, O REDENTOR,
ONDE SÓ HAVERÁ PAZ,
NUNCA HAVERÁ DOR.

*CORO 2X
JESUS, O SENTIDO DE VIVER,
(DE VIVER SÓ PRA JESUS)
JESUS, O AMOR, A PAZ REAL,
NÃO HÁ OUTRO AMOR IGUAL.
/FINAL
JESUS.
');
