INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f007de34-1069-459a-83b7-c21181c24df7', 'Se Anda Triste o Teu Viver', '247', 'Jorgemar Souza Madeira', 'Fox', 'C', 'Morte, Ressureição e Salvação', 'SE ANDA TRISTE O TEU VIVER,
SE ESTÁ VAZIO O TEU CORAÇÃO,
EXISTE ALGUÉM QUE PODE DAR
A PAZ QUE TANTO VENS A PROCURAR.

*CORO
JESUS, ESSE ALGUÉM!
JESUS, PODE DAR ALGO QUE VENS A PROCURAR,
JESUS, BOM AMIGO QUE NÃO PODE FALTAR.

SE ANDAS SEM A SOLUÇÃO,
ANGÚSTIA INVADE O TEU CORAÇÃO,
EXISTE ALGUÉM QUE PODE DAR
A PAZ QUE TANTO VENS A PROCURAR.

*CORO 2X
JESUS, ESSE ALGUÉM!
JESUS, PODE DAR ALGO QUE VENS A PROCURAR,
JESUS, BOM AMIGO QUE NÃO PODE FALTAR.
');
