INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f0394526-446a-4646-8cff-13278d4e35ce', 'Ó Cristo Pão da Vida', '458', 'Let.:Ricardo Holden; Mús.: Hans Leo Hassler; Harm. Johann Sebastian Bach', 'Canção', 'Cm', 'Santificação e Derramamento', 'Ó CRISTO! PÃO DA VIDA,
DESCIDO LÁ DO CÉU,
O PÃO DE NOSSAS ALMAS,
QUE O PAI DE AMOR NOS DEU!
EM TI NOS ALEGRAMOS,
PROVAMOS MESMO AQUI
DO ALENTO E DA DOÇURA,
QUE ACHAMOS SEMPRE EM TI.

DA ETERNA E SANTA VIDA,
DA QUAL TU ÉS O AUTOR,
SUSTENTO E FORTALEZA
ÉS TU TAMBÉM, SENHOR.
SEM TI NÃO NOS ASSISTEM
NEM FORÇAS, NEM PODER;
DE TI, NOSSO ALIMENTO,
QUEREMOS NÓS VIVER.

Ó CRISTO! PÃO DA VIDA!
A TI LOUVAMOS NÓS,
E AO PAI TAMBÉM ERGUEMOS
A NOSSA ALEGRE VOZ.
AGRADECEMOS SEMPRE
O AMOR QUE AQUI NOS DEU,
SUSTENTO VERDADEIRO
NO SANTO PÃO DO CÉU.
/FINAL
AMÉM!
');
