INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f0772d6c-cb87-4b2c-b750-0b3f1e37b1b2', 'O Senhor é o bom pastor', 87, 'A. B. V.', 'Fox', 'G', 'Crianças e Adolescentes', 'O SENHOR É O BOM PASTOR,
ELE É O SALVADOR,
O DEUS DE PAZ E DE ALEGRIA,
O DEUS DE AMOR.

*CORO
ELE VEM ME BUSCAR
E VAI ME LEVAR
PARA A CIDADE CELESTIAL.
VOCÊ TAMBÉM PODE IR,
É SÓ ANDAR NO CAMINHO DE CRISTO JESUS.

ELE CURA E SALVA,
FALA AOS CORAÇÕES,
CUIDA DOS SEUS FILHOS
COM MUITO AMOR.

*CORO 2X
ELE VEM ME BUSCAR
E VAI ME LEVAR
PARA A CIDADE CELESTIAL.
VOCÊ TAMBÉM PODE IR,
É SÓ ANDAR NO CAMINHO DE CRISTO JESUS.
/FINAL
NO CAMINHO DE CRISTO JESUS.
');
