INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f0cafbf7-646a-4590-8883-66b9317f7a4b', 'Deus Preparou', '', '', '', '', '', 'DEUS PREPAROU UMA CIDADE
PARA SUA IGREJA FIEL.
NESTA CIDADE NÃO HAVERÁ DOR,
POIS ELE NÃO PERMITIRÁ.
SEREMOS TIRADOS DESTE
MUNDO CRUEL, PARA
MORARMOS COM ELE NO CÉU.

CORO
EU QUERO ENTRAR NO CÉU COM JESUS,
E CONTEMPLAR AS MANSÕES
QUE DEUS PREPAROU.
QUERO ANDAR NAS RUAS DE OURO
E OUVIR A VOZ DE DEUS
O MEU NOME CHAMAR.

OUVE A VOZ DO REDENTOR,
ELE QUER HOJE SALVAR,
QUER LIBERTAR E PERDOAR,
TUAS FERIDAS CURAR E NÃO TARDARÁ.
CRISTO VEM NOS BUSCAR,
ENTREGA TUA VIDA E ELE TE LEVARÁ.
');
