INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f15fe429-102b-4875-8617-b04e2d2baa2f', 'Grande é o Senhor, Santo e Justo', '', '', '', '', '', 'GRANDE É O SENHOR,
SANTO E JUSTO EM PODER,
HAVEREMOS DE CRER NO AMOR.
GRANDE É O SENHOR,
É FIEL, NOS SALVOU,
PELA GRAÇA PROVOU
QUE É AMOR.

CORO
GRANDE É O SENHOR, É DIGNO DE GLÓRIA!
GRANDE É O SENHOR, DAREMOS LOUVOR!
GRANDE É O SENHOR!
A VOZ LEVANTAI, A VOZ LEVANTAI!
GRANDE É O SENHOR! GRANDE É O SENHOR!

GRANDE É O SENHOR,
SANTO E JUSTO EM PODER,
HAVEREMOS DE CRER NO AMOR.
GRANDE É O SENHOR, É FIEL, NOS SALVOU,
PELA GRAÇA PROVOU QUE É AMOR.

FINAL
GRANDE É O SENHOR, É DIGNO DE GLÓRIA!
GRANDE É O SENHOR, DAREMOS LOUVOR!
GRANDE É O SENHOR!
A VOZ LEVANTAI, A VOZ LEVANTAI
GRANDE É O SENHOR! (5X)
');
