INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f195d8ee-fc27-40e0-9c0a-fa13d80a882e', 'Fui lavado no sangue do Cordeiro', '', '', 'Fox', '', '', '*CORO
FUI LAVADO NO SANGUE DO CORDEIRO,
ALELUIA, GLÓRIA E ALELUIA!
FUI LAVADO NO SANGUE DO CORDEIRO,
ALELUIA, GLÓRIA E ALELUIA!

AGORA ESTOU AQUI
E VOU LOUVAR MEU SALVADOR,
ALELUIA, GLÓRIA A DEUS!

CORO
FUI LAVADO NO SANGUE DO CORDEIRO,
ALELUIA, GLÓRIA E ALELUIA!
FUI LAVADO NO SANGUE DO CORDEIRO,
ALELUIA, GLÓRIA E ALELUIA!
FINAL
A JESUS, HONRA E LOUVOR,
ALELUIA AO MEU SALVADOR!
');
