INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f1b88c4c-122c-43a9-9b92-a36b11610214', 'Há Uma Fonte Aberta no Calvário', '202', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'HÁ UMA FONTE ABERTA NO CALVÁRIO
CONTRA A IMPUREZA E O PECADO;
ÁGUAS DE PERDÃO, PURIFICAÇÃO,
FLUEM DE JESUS CRUCIFICADO.

HÁ UMA FONTE ABERTA NO CALVÁRIO,
ONDE MEU SENHOR FOI TRANSPASSADO,
FONTE DE PODER PRA TODO O QUE CRER,
POR SUAS PISADURAS SER CURADO.

CORO
TE AGRADEÇO, JESUS,
PORQUE FOSTE À CRUZ
PARA ABRIR ESTA FONTE
DE VIDA E LUZ.

PARA QUE EU VIVESSE, TU MORRESTE,
PARA ME CURARES, ENFERMASTE!
CORREM DO TEU LADO, Ó CRUCIFICADO,
ÁGUAS VIVAS COM QUE ME SALVASTE.
');
