INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f1c30f1b-7f5c-4a45-8b67-bf230c353d4e', 'Entrei no tempo de Deus', '398', 'Ezequiel', 'Básico', 'C', 'Santificação e Derramamento', 'CANTAR 2X
ENTREI NO TEMPO DE DEUS,
JÁ VIVO A ETERNIDADE,
VOCÊ TAMBÉM PODE ENTRAR,
(PODE ENTRAR)
SER PARTICIPANTE COMO EU,
O PAI LHE REVELARÁ A ETERNIDADE.

CANTAR 2X
O MEU TEMPO ERA CONTADO PARA A MORTE
MAS APROUVE AO PAI ENVIAR SEU FILHO
E HOJE EU VIVO JÁ
A ETERNIDADE.
/FINAL
A ETERNIDADE.
');
