INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f2712c8b-618c-4889-867a-64a45a588612', 'Vou Guiar-te a uma Rica Fonte', '233', 'Let.: Lúcia Queiroz e Souza; Mús.: Rosângela Couto', 'Básico', 'D', 'Morte, Ressureição e Salvação', 'VOU GUIAR-TE A UMA RICA FONTE
DE ÁGUAS CRISTALINAS,
MATARÁS A TUA SEDE,
SUBIRÁS MUITAS COLINAS,
VOU LEVAR-TE AOS ALTOS MONTES.

SOU O SENHOR, SOU A ROCHA,
FONTE QUE JORRA O AMOR,
SOU A FÉ QUE DESABROCHA
NAQUELE QUE DESSEDENTO.
SOU REAL, SOU O SENHOR!

CANTAR 2X
VENHAM, Ó FILHOS QUERIDOS,
MORAR ALÉM DO HORIZONTE,
SALTAR PARA A ETERNIDADE,
BEBER DA ÁGUA DA VIDA.
/FINAL
ONDE EU, JESUS, SOU A FONTE. (3X)
');
