INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f28e8753-cbe4-49c2-8941-7719d867bedb', 'O Rei e eu', '332', 'Autor Desconhecido', 'Fox', 'G', 'Consolo e Encorajamento', 'O REI E EU
TRILHAMOS NA ESTRADA DA VIDA
ONDE MUITAS ALMAS PASSANDO VÃO;
O GRANDE SER E EU,
UM POBRE MENDIGO, ANDAMOS JUNTOS,
O REI E EU.

CORO
PORQUE ELE CUIDA DE MIM
É UM MISTÉRIO,
ELE TEM O MUNDO EM SUAS MÃOS,
MAS QUEM SOU EU?
ASSIM MINH''ALMA MUITO SE MARAVILHA
DE ESTARMOS JUNTOS, O REI E EU.

O REI E EU, ERA MUITO ESTRANHO,
EU ANDAVA SÓ SEM SABER POR QUÊ,
ATÉ QUE UM DIA SUAS MÃOS ME ABRAÇARAM,
NÃO MAIS ESTRANHOS, JESUS E EU.
');
