INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f2b2840c-a4f9-4e9b-ae8b-6809a38756c0', 'Jesus vê a sua igreja', '133', 'E.H.M.R.', 'Fox', 'G', 'Crianças e Adolescentes', 'JESUS VÊ A SUA IGREJA
COMO FORTE EDIFÍCIO,
FIRME E EDIFICADO PARA MORADA DE DEUS.

CORO 2X
NÃO É FEITA DE TIJOLO 
E MADEIRA, NÃO!
É JESUS BEM VIVO NO CORAÇÃO.

EDIFÍCIO ESPECIAL
DESENHADO POR JESUS,
PARA SEMPRE ERGUIDO
PELO SANTO ESPÍRITO.

VENHA PARA A IGREJA,
VAMOS JUNTOS TRABALHAR.
NESTA OBRA GLORIOSA
ATÉ JESUS VOLTAR.
');
