INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f344f2b0-7552-418e-ab39-4b91c5554821', 'Lá no céu os anjos cantam', '523', 'Jorgemar Souza Madeira', 'Valseado', 'G', 'Volta de Jesus e Eternidade', 'LÁ NO CÉU OS ANJOS CANTAM:
VIVA, VIVA O REI;
LINDO CORO CELESTIAL
NA BELA CIDADE ETERNAL.

*CORO
EM BREVE TAMBÉM ESTAREI
NA SANTA CIDADE DE LUZ,
LOUVANDO SEMPRE O MEU REI,
O MEU PRECIOSO JESUS.

LINDO RIO PURO DE ÁGUA VIVA
QUE VEM DE DEUS PAI;
LÁ NÃO HÁ TRISTEZA E DOR,
SÓ PAZ, ALEGRIA E AMOR.

*CORO 2X
EM BREVE TAMBÉM ESTAREI
NA SANTA CIDADE DE LUZ,
LOUVANDO SEMPRE O MEU REI,
O MEU PRECIOSO JESUS.
/FINAL
O MEU PRECIOSO JESUS.
');
