INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f370074f-cc80-4dad-87a5-bf9242ff20ad', 'Dai glória a Deus', '613', 'Sérgio Paulo Ferreira de Matos', 'Fox Abafado', 'C', 'Louvor', 'DAI GLÓRIA A DEUS! QUEM NÃO O TEMERÁ?
GLÓRIA E PODER SEM FIM DIANTE DELE HÁ!
/EIS O LEÃO DA TRIBO DE JUDÁ,
AQUELE QUE ERA E É, E QUE VOLTARÁ!

ANJOS E QUERUBINS, ARCANJOS E SERAFINS,
DIA E NOITE ADORAM O QUE FOI MORTO
MAS HOJE VIVE E É REI DOS REIS!

DAI GLÓRIA A DEUS,
DAI GLÓRIA A DEUS PAI,
AO FILHO ADORAI,
DAI GLÓRIA A DEUS! (3X)
');
