INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f39ee898-b183-487f-ad56-6c653042d528', 'Te suplico, ó Deus, em oração', '014', 'E.H.M.R.', 'Básico', 'A', 'Crianças e Adolescentes', 'TE SUPLICO, Ó DEUS, EM ORAÇÃO.
POIS DESEJO DE TODO O CORAÇÃO
ENTENDER A TUA PALAVRA,
TER SABEDORIA E TEMOR PARA PRESERVAR-ME
NO TEU CAMINHO, SENHOR.

CANTAR 2X
COMO PRATA E COMO O OURO BUSCAREI.
COMO UM TESOURO ESCONDIDO, PROCURAREI;
A TUA PALAVRA ENTRARÁ EM MEU CORAÇÃO
DANDO-ME A LEVEZA DO PERDÃO
OS TEUS MANDAMENTOS SUAVES SERÃO
E UM LOUVOR DE GRATIDÃO ENTOAREI A TI, SENHOR.
');
