INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f50d6905-ec3f-4e82-b717-209d8b498a92', 'Acende a minha candeia', '', '', '', '', '', 'VEM SEGURA A MINHA MÃO E ENSINA-ME
A TE ADORAR A TE EXALTAR TODO DIA.
CADA INSTANTE, PRECISO MAIS DE TI.
PRECISO MAIS DO TEU AMOR
EU QUERO SER BEM MAIS QUE
UM SIMPLES SEGUIDOR.

*CORO
EU QUERO SER UMA CANDEIA
ACESA REFLETINDO A TI
CHEIA DE ÓLEO TRANSBORDANTE
EU QUERO SER INSTRUMENTO PRONTO
PARA TE SERVIR, EU QUERO SER
ACENDE A MINHA CANDEIA.

VEM SEGURA A MINHA MÃO E ENSINA-ME
A TE ADORAR A TE EXALTAR TODO DIA.
CADA INSTANTE, PRECISO MAIS DE TI.
PRECISO MAIS DO TEU AMOR
EU QUERO SER BEM MAIS QUE
UM SIMPLES SEGUIDOR.

*CORO
EU QUERO SER UMA CANDEIA
ACESA REFLETINDO A TI
CHEIA DE ÓLEO TRANSBORDANTE
EU QUERO SER INSTRUMENTO PRONTO
PARA TE SERVIR, EU QUERO SER
ACENDE A MINHA CANDEIA.

ACENDE COM TEU FOGO,
RESPLANDECE A TUA GLÓRIA EM MEU VIVER,
MAIS DO TEU PODER EU QUERO SENHOR.
QUERO SER UMA CANDEIA
ACESA REFLETINDO A TI...

QUERO SER UMA CANDEIA ACESA REFLETINDO A TI
CHEIA DE ÓLEO TRANSBORDANTE EU QUERO SER
INSTRUMENTO PRONTO PARA TE SERVIR, EU QUERO SER
ACENDE A MINHA CADEIA...
ACENDE COM TEU FOGO...
ACENDE A MINHA CADEIA.
');
