INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f564aca5-d4dd-4430-a888-d482f4cf6e38', 'Uma luz brilhou em meu caminho', '112', 'Elias Maia', 'Balada', 'G', 'Dedicação', 'UMA LUZ BRILHOU EM MEU CAMINHO,
QUANDO EU IA TRISTE E SOZINHO;
QUANDO EU OLHEI PRA CRUZ,
NELA EU VI JESUS,
FOI UM MINUTO SÓ DO SEU OLHAR.

CORO
FOI UM MINUTO SÓ, UM MINUTO SÓ,
FOI UM MINUTO SÓ DO SEU OLHAR;
TUDO EM MIM MUDOU,
TUDO EM MIM CANTOU,
FOI UM MINUTO SÓ DO SEU OLHAR.

JESUS MARCOU A MINHA VIDA,
NUNCA MAIS EU SEREI O MESMO;
FOI SEU DIVINO OLHAR
QUE ME ENSINOU A AMAR,
FOI UM MINUTO SÓ DO SEU OLHAR.
');
