INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f565c6ea-2c1e-4f6d-900a-e032f67f71bc', 'Dependo de Ti, Senhor', '189', 'Paulo Luis de Carvalho', 'Valseado', 'D', 'Santificação e Derramamento', 'DEPENDO DE TI, SENHOR,
QUE SEJAS ASSIM EM MEU VIVER:
TOMA O MEU CORAÇÃO,
TOTALMENTE DOMINA, Ó SENHOR!

NÃO QUERO ANDAR INDEPENDENTE, SENHOR,
POIS TUA VONTADE É VIDA PARA O MEU CORAÇÃO.
/DEPENDO DE TI, SENHOR,
NÃO POSSO ANDAR SEM TEU BRAÇO FORTE;
SEM TUA VONTADE HAVERÁ AGONIA,
TRISTEZA E MORTE.

FINAL 2X
DEPENDO DE TI, SENHOR,
DEPENDO DE TI,
DEPENDO DE TI, AMÉM.
');
