INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f5e90fdd-9f77-4a8a-9083-38217cd95ff1', 'De Hoje em Diante', '', '', '', '', '', 'DE HOJE EM DIANTE ESCOLHO
VIVER COM JESUS
COMO UM BARCO QUE ALCANÇA O PORTO
EU ENCONTREI SUA LUZ
DE HOJE EM DIANTE ESCOLHO AMAR
POIS EU TENHO PAZ
QUE SÓ JESUS PODE DAR
DE HOJE EM DIANTE.

*CORO
SENHOR DO UNIVERSO
ÉS MINHA ESPERANÇA
SANTIFICA OS PROPÓSITOS
DO MEU CORAÇÃO
CONTIGO AO MEU LADO
NÃO TENHO MAIS O QUE TEMER
POIS TU ÉS A RAZÃO
DO MEU VIVER.

ACIMA DE TUDO ESCOLHO
VIVER COM JESUS
EM RESPOSTA AO GRANDE PREÇO
QUE JÁ FOI PAGO NA CRUZ
EU SIGO TEUS PASSOS
PRA NÃO ME PERDER
DESCOBRIR QUE ÉS
MINHA RAZÃO DE VIVER
DE HOJE EM DIANTE.

*CORO 2X
SENHOR DO UNIVERSO
ÉS MINHA ESPERANÇA
SANTIFICA OS PROPÓSITOS
DO MEU CORAÇÃO
CONTIGO AO MEU LADO
NÃO TENHO MAIS O QUE TEMER
POIS TU ÉS A RAZÃO
DO MEU VIVER.

FINAL
POIS TU ÉS A RAZÃO
DO MEU VIVER (A RAZÃO)
TU ÉS A RAZÃO DO MEU... VIVER.
');
