INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f69dfd53-8f04-47e4-ae25-2da6010c7e80', 'Santo é o que está no trono', '602', 'Sérgio Paulo Ferreira de Matos', 'Balada', 'C', 'Louvor', 'SANTO, SANTO, SANTO
É O QUE ESTÁ NO TRONO,
O QUE É REI E SENHOR;
DIGNO, SÓ ELE É DIGNO
DE RECEBER A GLÓRIA E LOUVOR!

(H) QUEM É O QUE BRILHA MAIS QUE O SOL?
(M) É O SENHOR!
(H) QUEM É O QUE BRAMA COMO O LEÃO?
(M) É O SENHOR!
(H) QUEM É O QUE PASSEIA
(H) ENTRE OS SETE CASTIÇAIS?
É O CORDEIRO, É O LEÃO DE JUDÁ.

(M) QUEM É O QUE A MORTE CONQUISTOU?
(H) É O SENHOR!
(M) QUEM É O QUE O MUNDO VAI JULGAR?
(H) É O SENHOR!
(M) QUEM É O QUE VIRÁ A ESPOSA ARREBATAR?
É O CORDEIRO, É O LEÃO DE JUDÁ.

SANTO, SANTO, SANTO
É O QUE ESTÁ NO TRONO,
O QUE É REI E SENHOR;
DIGNO, SÓ ELE É DIGNO
/DE RECEBER A GLÓRIA E LOUVOR! (3X)
');
