INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f6bff8fe-90eb-4e9b-a9e7-7364f77101d2', 'Ouvi o Salvador Dizer', '697', 'Let.: Horatius Bonar; Trad.: Mary Wardiaw; Adap. Jurama Barros Gueiros; Mús. John Bacchus Dykes', 'Canção', 'Gm', 'Grupo de Louvor', 'OUVI O SALVADOR DIZER:
"VEM DESCANSAR EM MIM
E CONFIANTE RECEBER
CONFORTO E PAZ SEM FIM".

FUI A JESUS E LHE ENTREGUEI
MEU TRISTE CORAÇÃO;
ABRIGO E PAZ E GOZO ACHEI,
ACHEI CONSOLAÇÃO.

OUVI O SALVADOR DIZER:
"DE GRAÇA É O MEU AMOR.
AS ÁGUAS VIVAS VEM BEBER;
DA VIDA A FONTE SOU".

FUI A JESUS E ME PROSTREI,
DA FONTE ENFIM BEBI;
JAMAIS A SEDE SENTIREI,
ESTANDO SEMPRE ALI.

OUVI O SALVADOR DIZER:
"DO MUNDO EU SOU A LUZ;
OH! VEM A MIM, POIS SENTIRÁS
QUE TE AMO DESDE A CRUZ".

FUI A JESUS E NELE ACHEI
O SOL QUE BRILHA EM MIM;
E NESSA LUZ EU ANDAREI
ATÉ DA VIDA O FIM. 
/FINAL
AMÉM.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('f6bff8fe-90eb-4e9b-a9e7-7364f77101d2', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
