INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f722aa1f-5842-461f-8542-0346f7646aaf', 'Eis que Jesus vem nas nuvens', '215', 'Let.: William Orcutt Cushing; Trad. William Edwin Entezminger; Mús.George Frederick Root', 'Valseado', 'C', 'Crianças e Adolescentes', 'EIS QUE JESUS VEM NAS NUVENS
BUSCAR SUAS JÓIAS,
SUAS JÓIAS PRECIOSAS
DE MUITO VALOR.

CORO
COMO ESTRELAS DA AURORA
BRILHANDO NA FRONTE
DE JESUS, LÁ NA GLÓRIA,
ADORNO SERÃO.

VEM BUSCÁ-LAS, VAI LEVÁ-LAS
AO REINO CELESTE,
SUAS JÓIAS RESPLANDECENTES
DE MUITO VALOR.

OS MENINOS E AS MENINAS
QUE SERVEM A JESUS,
SÃO-LHES JÓIAS, RICAS JÓIAS
DE MUITO VALOR.
');
