INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f74cd326-903e-4515-9ffa-40af81ffd50e', 'Quem cantar aqui se alegrará', '756', 'Autor Desconhecido', 'Country', 'D', 'Corinhos', 'QUEM CANTAR AQUI SE ALEGRARÁ!
QUEM CANTAR AQUI SE ALEGRARÁ!
/QUEM CANTAR GLÓRIA A JESUS
SUA VIDA ELE CONDUZ.

CANTAR 2X
CANTAREI EM SEU LOUVOR
E OS ENFERMOS SÃO CURADOS
NA PRESENÇA DO SENHOR.

QUEM CANTAR AQUI SE ALEGRARÁ!
QUEM CANTAR AQUI SE ALEGRARÁ!
/QUEM CANTAR GLÓRIA A JESUS
SUA VIDA ELE CONDUZ.

FINAL 2X
CANTAREI EM SEU LOUVOR
E OS ENFERMOS SÃO CURADOS
NA PRESENÇA DO SENHOR.
');
