INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f760faed-6fa6-44d9-9ac0-fb3842f6ad3d', 'O grande amor do meu Senhor', '196', 'E.M.', 'Básico', 'E', 'Dedicação', '(M) O GRANDE AMOR DO MEU SENHOR
(H) O REI DE TODO UNIVERSO!
JESUS, O SOBERANO DEUS,
RESPLANDECENTE ESTRELA DA MANHÃ!

COMO ENTENDER QUE MEU JESUS,
UM DIA OLHOU PRA MIM,
E SEM QUERER NADA EM TROCA,
TÃO GRANDE AMOR ME DEU, 
O MEU SENHOR
VIDA ETERNA DEU, MEU SALVADOR!

CORO
ABENÇOADOR, DEUS DE PAZ,
CONSOLADOR, MEU REI E SENHOR.
HOMEM SE FEZ, MORREU EM MEU LUGAR
MEU REDENTOR, MINHA ESPERANÇA,
MINHA ESPERANÇA É!

COMO ENTENDER QUE MEU JESUS
UM DIA OLHOU PRA MIM, 
E SEM QUERER NADA EM TROCA, 
TÃO GRANDE AMOR ME DEU 
O MEU SENHOR!
VIDA ETERNA DEU, MEU SALVADOR.

A ROCHA FIRME, (A ROCHA FIRME)
REFÚGIO SEGURO, (REFÚGIO SEGURO)
A MINHA ALEGRIA,
MEU LOUVOR É SÓ PRA TI
MEU GRANDE EU SOU!

FINAL
O REI DO UNIVERSO,
(UM DIA OLHOU PRA MIM)
O MEU GRANDE EU SOU, JESUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('f760faed-6fa6-44d9-9ac0-fb3842f6ad3d', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
