INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f76f1e52-5c26-4fe3-afa6-a786680dfbf2', 'Tudo Se Fez Novo', '257', 'Luciana Monteiro Carneiro Simora', 'Básico', 'E', 'Morte, Ressureição e Salvação', 'TUDO SE FEZ NOVO 
E AS COISAS VELHAS JÁ SE PASSARAM,
POIS O SENHOR FARÁ CONTIGO
UMA ALIANÇA ETERNA QUE JAMAIS SE ACABARÁ.

DOS TEUS PECADOS DEUS NÃO MAIS SE LEMBRARÁ,
TUA VIDA ELE VAI TRANSFORMAR,
O TEU FARDO SOBRE SI ELE VAI LEVAR
E AS TUAS LÁGRIMAS ELE VAI ENXUGAR.

*CORO 2X
NÃO SOU EU MAIS QUEM VIVE
MAS CRISTO VIVE EM MIM;
E A VIDA QUE AGORA VIVO,
EU A VIVO PELA FÉ.

ESTE CHAMADO VEM DE DEUS,
NÃO VEM DO HOMEM, MAS VEM DO SENHOR;
NÃO TEMAS, POIS FOI DEUS QUEM TE ESCOLHEU;
NÃO TEMAS, POIS É ELE QUEM DÁ FORÇAS PRA VENCER;
NÃO TEMAS, PORQUE ELE NÃO TE DEIXARÁ;
NÃO TEMAS, POIS O SEU AMOR É GRANDE.

*CORO 2X
NÃO SOU EU MAIS QUEM VIVE
MAS CRISTO VIVE EM MIM;
E A VIDA QUE AGORA VIVO,
EU A VIVO PELA FÉ.
/FINAL
EU A VIVO PELA FÉ.
');
