INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f8be77a5-a99e-494c-ae73-5414cb048794', 'Quem são estes de brancos vestidos', '093', '', '', '', '', 'CANTAR 2X
QUEM SÃO ESTES
DE BRANCOS VESTIDOS?
QUEM SÃO ESTES
DE BRANCOS VESTIDOS?
ESTES SÃO OS QUE LAVARAM 
NO SANGUE DE JESUS
SEUS VESTIDOS, SEUS VESTIDOS.

CANTAR 2X
POR ISSO ESTÃO PERANTE
O TRONO DIZENDO:
SEJAM DADOS GLÓRIA,
FORÇA E PODER AO NOSSO
DEUS PARA TODO O SEMPRE.

FOME E SEDE JAMAIS SUAS ALMAS TERÃO,
A SOMBRA DO CORDEIRO OS COBRIRÁ;
A MANSÃO DOS FIÉIS VOSSA CERTA SERÁ
E TODA A LÁGRIMA DEUS LIMPARÁ,
TODA A LÁGRIMA DEUS LIMPARÁ,
TODA A LÁGRIMA DEUS LIMPARÁ.
');
