INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f8cbbab2-8169-409a-b70b-70260d656050', 'Existe um alguém que cuida de mim', '146', 'Jorgemar Souza Madeira', 'Novo', 'D', 'Dedicação', 'EXISTE UM ALGUÉM QUE CUIDA DE MIM,
TAMBÉM DE VOCÊ,
SEU NOME É DEUS FORTE,
REAL CONSELHEIRO, ELE É O PODER;
ELE É FIEL, EMANUEL, UM BRILHO DE LUZ,
TRANSMITE A PAZ, TAMBÉM SATISFAZ,
SEU NOME É JESUS.

CANTAR 2X
JESUS É A VIDA, 
A FLOR MAIS QUERIDA;
NA HORA DA DOR, 
JESUS É AMOR,
A FONTE DA VIDA.

EXISTE UM ALGUÉM QUE CUIDA DE MIM,
TAMBÉM DE VOCÊ,
SEU NOME É DEUS FORTE,
REAL CONSELHEIRO, ELE É O PODER;
ELE É FIEL, EMANUEL, UM BRILHO DE LUZ,
TRANSMITE A PAZ, TAMBÉM SATISFAZ,
SEU NOME É JESUS.

CANTAR 2X
JESUS É A VIDA, A FLOR MAIS QUERIDA;
NA HORA DA DOR, JESUS É AMOR,
A FONTE DA VIDA.
/FINAL
NA HORA DA DOR, JESUS É AMOR,
A FONTE DA VIDA.
