INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f8e14e5d-414d-430b-b019-2e578aec2ff4', 'A melhor coisa', '', '', 'Balada', 'D', 'Avulso', 'DE TANTAS COISAS
QUE ANDEI FAZENDO,
DE QUASE TODAS ME ARREPENDI.
MAS HOUVE UMA ESPECIAL,
FOI A MAIS CERTA QUE ESCOLHI.

*CORO
A MELHOR COISA QUE EU JÁ FIZ
EM TODA A MINHA VIDA,
POR ISSO SOU FELIZ EM
ACEITAR JESUS, SINCERAMENTE FOI
A MELHOR COISA QUE EU JÁ FIZ.

COISAS ERRADAS ANDEI FAZENDO
NA CONDIÇÃO DE PECADOR,
MAS QUANDO ACHEI-ME
DESFALECENDO,
TOMEI A DECISÃO QUE ME SALVOU.

*CORO 2X
A MELHOR COISA QUE EU JÁ FIZ
EM TODA A MINHA VIDA,
POR ISSO SOU FELIZ EM
ACEITAR JESUS, SINCERAMENTE FOI
A MELHOR COISA QUE EU JÁ FIZ.
');
