INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f8f97492-2c78-41d2-a7f4-fea42fc183ce', 'Vou clamar', '043', 'Fárell Farias Oliveira', 'Básico', 'G', 'Clamor', 'CANTAR 2X
VOU CLAMAR POR TEU SANGUE,
Ó JESUS,
PRA TE OFERECER A MINHA VIDA.

CANTAR 2X
E QUEM TIVER TEU SANGUE SOBRE SI,
TERÁ VITÓRIA, VITÓRIA EM TI, JESUS.
/INSTRUMENTOS

FINAL 2X
E QUEM TIVER TEU SANGUE SOBRE SI,
TERÁ VITÓRIA, VITÓRIA EM TI, JESUS.
');
