INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f97673ed-ee62-4d77-8203-3fc143bea039', 'Oh! Quanto almejo estar', '546', 'Daniele Verona', 'Básico', 'G', 'Volta de Jesus e Eternidade', 'OH! QUANTO ALMEJO ESTAR PERANTE A TUA FACE
E CONTEMPLAR A TUA MAJESTADE;
SEI QUE A VIDA AQUI LOGO VAI PASSAR
E TODA LÁGRIMA DEUS ENXUGARÁ.

*CORO
JERUSALÉM, CIDADE CELESTIAL (JERUSALÉM),
OH! QUANTO ANSEIO ESTAR
JUNTO AO MEU AMIGO E REI,
QUE POR AMOR VERTEU SEU SANGUE 
PARA NOS SALVAR.
MARANATA! (MARANATA), 
ORA VEM, SENHOR JESUS!
/INSTRUMENTOS

EM BREVE IREI MORAR NA BELA CIDADE,
EM RUAS DE OURO SEI QUE VOU ANDAR;
JERUSALÉM, ONDE CRISTO REINARÁ
E PARA SEMPRE COM ELE IREI ESTAR.

*CORO 2X
JERUSALÉM, CIDADE CELESTIAL (JERUSALÉM),
OH! QUANTO ANSEIO ESTAR
JUNTO AO MEU AMIGO E REI,
QUE POR AMOR VERTEU SEU SANGUE 
PARA NOS SALVAR.
MARANATA! (MARANATA), 
ORA VEM, SENHOR JESUS!
/FINAL
MARANATA! ORA VEM SENHOR JESUS!
');
