INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f9cf3190-c558-4942-8304-3be5e8934fc9', 'De madrugada eu busco a face do Senhor', '066', 'Vicente de Paula Barcellos Duarte', 'Country', 'D', 'Invocação e Comunhão', 'DE MADRUGADA EU BUSCO A FACE DO SENHOR
PEDINDO BÊNÇÃOS E BATISMO COM AMOR;
O GALO CANTA, MADRUGADA VAI CHEGAR, 
EU, DE JOELHOS, AO SENHOR VOU ADORAR.

ALELUIA, ALELUIA, MEU JESUS!
TU ÉS A LUZ DO DIA QUE VAI COMEÇAR.
ALELUIA, ALELUIA, MEU JESUS!
EU, DE JOELHOS, AO SENHOR VOU ADORAR.
');
