INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f9de5386-52dc-4034-ab14-f2912db6dac2', 'Junto a Ti suplico , ó Pai', '031', 'Gérson Beluci Miguel', 'Básico', 'D', 'Clamor', 'JUNTO A TI SUPLICO, Ó PAI,
PELO SANGUE DE JESUS;
CURVO-ME DIANTE DE TI,
OUVE-ME, Ó MEU SENHOR.

HÁ EM MIM SINCERIDADE
EM QUERER LIBERTAÇÃO;
LAVA-ME COM ESTE SANGUE,
DÁ-ME PLENA COMUNHÃO.
');
