INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f9df3abc-22bb-4d99-8e35-80d99c478c13', 'Entronizado está entre as nações', '635', 'Marciel Denadai', 'Balada', 'C', 'Louvor', 'ENTRONIZADO ESTÁ ENTRE AS NAÇÕES, (2X)
PROCLAMAI A JESUS, O REI, O LEÃO DE JUDÁ
QUE VENCEU E O LIVRO ABRIRÁ.

*CORO 2X
AO GRANDE REI,
JESUS SENHOR,
EXALTAI.
/INSTRUMENTOS

ANUNCIAI QUE JESUS VIRÁ
E QUEM VENCER TUDO HERDARÁ,
UM NOVO CÉU, UMA COROA DE GLÓRIA
E EM RUAS DE OURO ANDAR.

*CORO 3X
AO GRANDE REI,
JESUS SENHOR,
EXALTAI.
/FINAL
AO GRANDE REI EXALTAI.
');
