INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('f9ed1ea3-aae3-4a50-a792-94d55b97a6df', 'Jesus te entronizamos', '599', 'Olcimar Rubens de Carvalho', 'Básico', 'G', 'Louvor', 'JESUS, TE ENTRONIZAMOS AQUI ENTRE NÓS
PARA TRIBUTARMOS NOSSA ADORAÇÃO;
A TI RENDEMOS GLÓRIA, HONRA E LOUVOR,
EXPRESSÃO DE TODA A GRATIDÃO.

COROAMOS A CRISTO,
(COROAMOS A CRISTO, NOSSO REI)
ELE É O NOSSO REI, SIM, O NOSSO REI.
ERGUEMOS AS VOZES EM CORO,
(HOSANA A TI, JESUS)
CANTANDO HOSANA A JESUS,
E OS ANJOS PROCLAMAM NO CÉU:
VIVA O REI.
/INSTRUMENTOS

TU ÉS DEUS FILHO, O VERBO CRIADOR,
ESTÁS REVESTIDO DE GLÓRIA E ESPLENDOR;
SANTO, SANTO, SANTO, ÉS TU, JESUS,
TODA HONRA SEJA PARA TI.

CANTAR 2X
COROAMOS A CRISTO,
(COROAMOS A CRISTO, NOSSO REI)
ELE É O NOSSO REI, SIM, O NOSSO REI.
ERGUEMOS AS VOZES EM CORO,
(HOSANA A TI, JESUS)
CANTANDO HOSANA A JESUS,
E OS ANJOS PROCLAMAM NO CÉU:
VIVA O REI.
/FINAL
VIVA O REI.
');
