INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fa53f3a4-f1bd-4762-9dd2-2983fb04949a', 'Ao que está no trono', '601', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'B', 'Louvor', 'AO QUE ESTÁ NO TRONO
ENTRE OS QUERUBINS,
AO QUE RESPLANDECE E É FOGO CONSUMIDOR;
DIANTE DELE VOAM ANJOS, SERAFINS,
QUE SEUS ROSTOS COBREM
PERANTE A FACE DO SENHOR.

*CORO
GLÓRIA, FORÇA, GRAÇA E PODER,
SABEDORIA, HONRA E LOUVOR!

AO CORDEIRO MORTO QUE RESSUSCITOU
E QUE AO CÉU SUBIU,
AO REI QUE TÃO BREVE VEM;
À PALAVRA VIVA QUE SE REVELOU,
À LUZ QUE ILUMINA A NOVA JERUSALÉM.

*CORO 2X
GLÓRIA, FORÇA, GRAÇA E PODER,
SABEDORIA, HONRA E LOUVOR!
/FINAL
SANTO É O SENHOR! (3X)
');
