INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fa5b11b8-4993-4681-b18b-83bc9e475b0b', 'Igreja, tu vais subir', '788', 'Waldemar Bourguignon', 'Valseado', 'E', 'Volta de Jesus e Eternidade', 'IGREJA, TU VAIS SUBIR. (2X)
ESPERA MAIS UM POUQUINHO,
QUE O NOIVO HÁ DE VIR.

IGREJA, FOSTE COMPRADA
COM O SANGUE DE JESUS;
/FINAL 2X
IGREJA, FOSTE SELADA
COM O SANGUE DESTA CRUZ.
');
