INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fa671796-12b5-4883-a648-0a3b6dc48d95', 'Te adoramos', '575', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'D', 'Louvor', 'TE ADORAMOS, Ó SENHOR,
PELAS GRANDES MARAVILHAS
QUE TENS FEITO;
NOSSA VIDA TENS GUARDADO,
CADA DIA NOS REVELAS TEU AMOR.

*CORO
ÉS O DEUS EM QUEM PODEMOS CONFIAR,
DEUS FIEL E FORTE QUE NÃO VAI MUDAR;
COM O NOSSO CORAÇÃO CHEIO DE AMOR
TE OFERTAMOS NOSSA ADORAÇÃO, NOSSO LOUVOR.
/INSTRUMENTOS

ÉS REFÚGIO BEM SEGURO,
NOSSO ABRIGO CONTRA A TEMPESTADE E O VENTO;
COMO SOMBRA DE UMA ROCHA
E CORRENTES DE ÁGUA EM LUGAR SEDENTO.

*CORO
ÉS O DEUS EM QUEM PODEMOS CONFIAR,
DEUS FIEL E FORTE QUE NÃO VAI MUDAR;
COM O NOSSO CORAÇÃO CHEIO DE AMOR
TE OFERTAMOS NOSSA ADORAÇÃO, NOSSO LOUVOR.
/FINAL
NOSSA ADORAÇÃO, NOSSO LOUVOR.
');
