INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fa67b402-5407-42e2-bcab-0035e210f535', 'Teu povo clama', 19, 'Autor Desconhecido', 'Balada', 'D', 'Clamor', 'CANTAR 2X
TEU POVO CLAMA EM ORAÇÃO
PELO TEU SANGUE, LIBERTAÇÃO,
PELO PECADO, MISERICÓRDIA,
TEU POVO CLAMA, SENHOR JESUS.
');
