INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fa7b6474-1564-4a18-bd2b-efa60abfd1f0', 'Pelo sangue de Jesus eu vou clamar', 48, '', 'Básico', 'Em', 'Clamor', 'PELO SANGUE DE JESUS EU VOU CLAMAR
E O PERDÃO DOS MEUS PECADOS ALCANÇAR,
POIS SÓ ASSIM A CADA DIA POSSO ENTRAR
PERANTE A TUA FACE, Ó SENHOR.

PURIFICA-ME E LIBERTA-ME, SENHOR
COM O TEU PODER!
PRA TE ADORAR E TE EXALTAR,
OH SENHOR!

FINAL
PURIFICA-ME E LIBERTA-ME, SENHOR
COM O TEU PODER!
AMÉM!
');
