INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fa940663-a6a4-424d-98ba-05c0e6eb5659', 'Verei meu grande Rei', '217', 'E.C.O.R.;N.R.R.A.', 'Básico', 'E', 'Crianças e Adolescentes', 'VEREI MEU GRANDE REI,
UM VENCEDOR SEREI,
VEREI O MEU JESUS!
NOVA JERUSALÉM,
CIDADE DO MEU REI,
ESTAREI COM MEU JESUS!

CORO
OH! QUE GLÓRIA!
SERÁ O ENCONTRO TRIUNFAL!
ALELUIA! VEREI OS CÉUS SE ABRIREM.
E COM OS ANJOS A CANTAR,
NA CIDADE VOU ENTRAR.
"ORA VEM, VEM SENHOR JESUS!"

ELE MORREU NA CRUZ,
PORÉM RESSUSCITOU E VIVO HOJE ESTÁ.
QUANDO ENCONTRAR JESUS, VEREI A SUA LUZ,
OH! QUE GLÓRIA ETERNAL!

FINAL
VEM SENHOR JESUS!
');
