INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fb09fc60-ddec-47fa-bfad-c5325b332e9b', 'Alerta Povo, Está Chegando A Nossa Hora', '510', 'Autor Desconhecido', 'Marcha', 'A', 'Volta de Jesus e Eternidade', 'ALERTA POVO, ESTÁ CHEGANDO A NOSSA HORA
DA VITÓRIA QUE JESUS TEM PRA NOS DAR,
ELE VEM COM PODER E GRANDE GLÓRIA,
DESCENDO AO MUNDO PARA NOS ARREBATAR.

CORO
E NUM ABRIR E FECHAR DE OLHOS,
NÓS ESTAREMOS NAS MANSÕES CELESTIAIS,
E SÓ SE OUVE: GLÓRIA A DEUS E ALELUIA
DOS REMIDOS QUE NO CÉU TÊM SEU LUGAR.

ALI NÃO HÁ MAIS PRANTO NEM DORES,
AS NOSSAS LÁGRIMAS JESUS VAI ENXUGAR,
E BEM NO MEIO ESTÁ A ÁRVORE DA VIDA
QUE TEM SEUS FRUTOS PARA NOS ALIMENTAR.
');
