INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fb4bda1e-a9ed-4c9b-bd88-48691a255d06', 'Quando Israel saiu do Egito', '023', 'J.S.M.', 'Country', 'Dm', 'Crianças e Adolescentes', 'QUANDO ISRAEL SAIU DO EGITO, 
ISRAEL CANTOU, CANTOU:
O SENHOR É A MINHA FORÇA.
/ELE ME FOI POR SALVAÇÃO, 
ESTE É O MEU DEUS,
LHE FAREI UMA HABITAÇÃO.

AO SENHOR TAMBÉM LOUVAREI
PORQUE É A MINHA SALVAÇÃO,
MEU REFÚGIO, MINHA FORTALEZA,
LHE FAREI UMA HABITAÇÃO
NO MEU CORAÇÃO
/INSTRUMENTOS

QUANDO ISRAEL SAIU DO EGITO, 
ISRAEL CANTOU, CANTOU:
O SENHOR É A MINHA FORÇA.
/ELE ME FOI POR SALVAÇÃO, 
ESTE É O MEU DEUS,
LHE FAREI UMA HABITAÇÃO.

AO SENHOR TAMBÉM LOUVAREI
PORQUE É A MINHA SALVAÇÃO,
MEU REFÚGIO, MINHA FORTALEZA,
LHE FAREI UMA HABITAÇÃO
NO MEU CORAÇÃO

FINAL
QUANDO ISRAEL SAIU DO EGITO, 
ISRAEL CANTOU, CANTOU:
O SENHOR É A MINHA FORÇA.
');
