INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fb8fab52-099d-48b4-815b-a67a100b4c46', 'É Teu Sangue', '047', 'Let. e Mús.: Autor desconhecido; Trad: Sérgio Paulo Ferreira de Matos', 'Básico', 'A', 'Clamor', 'É TEU SANGUE QUE ME LIMPA,
É TEU SANGUE QUE VIDA ME DÁ,
ESTE SANGUE DO SACRIFÍCIO, 
DERRAMADO EM MEU LUGAR,
E QUE ME TORNA ALVO MAIS QUE A NEVE,
MEU JESUS, OFERTA PERFEITA NO ALTAR.
/INSTRUMENTOS

POR TEU SANGUE CLAMO AGORA,
POR TEU SANGUE EU OUSO ENTRAR
NO SANTUÁRIO, ONDE O DEUS VIVO
QUER A MIM SE REVELAR.
CORDEIRO ETERNO!
ÉS O HOLOCAUSTO QUE ME SALVOU!
OFERTA PERFEITA NO ALTAR.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('fb8fab52-099d-48b4-815b-a67a100b4c46', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
