INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fb940dbd-dd67-42c8-a238-526980577c0b', 'Quem sou Eu, Senhor', '474', 'M.M.K.D', 'Básico', 'Eb', 'Santificação e Derramamento do Espírito Santo', 'QUEM SOU EU, SENHOR?
PRA TE LEMBRARES DE MIM,
PRA ME TRAZERES ATÉ AQUI
E ME DIZER COISAS TÃO LINDAS.

TU SABES QUEM EU SOU,
O MENOR DE MINHA CASA,
E NO TEU AMOR, SENHOR, 
PROFETIZASTE A MIM
UM CAMINHO NOVO A TRILHAR.

*CORO 2X
ME TOMASTE, SENHOR, DA TUA MALHADA,
DE TRÁS DAS TUAS OVELHAS
ME TIRASTE Ó DEUS,
POR ONDE QUER QUE EU FOR, 
PARA O TEU LOUVOR, 
A TUA PRESENÇA COMIGO IRÁ.
/FINAL
SE MINHA VIDA ABENÇOARES,
PARA SEMPRE ABENÇOADA SERÁ.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('fb940dbd-dd67-42c8-a238-526980577c0b', 'f38126d1-bebc-4906-99b4-edd2cba2f3ca');
