INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fcc5ec50-a714-45fc-9b72-cfb98b681243', 'Oração Do Pastor (Coro Masculino)', '', '', '', '', '', 'DIRIJO A TI, JESUS, MINHA ORAÇÃO
EU SEI QUE TUDO VÊS NO CORAÇÃO
A TI VENHO ADORAR E GRAÇA SUPLICAR
Ó, VEM ME ABENÇOAR, VEM JÁ MEU DEUS.

DIRIJO A TI, JESUS, MINHA ORAÇÃO
DIVINO AMPARO QUE ÉS EM AFLIÇÃO
Ó, VEM ME CONSOLAR,
MINH’ALMA CONFORTAR
E SEMPRE ME GUARDAR DE TODO O MAL.

ATENDE, Ó MEU JESUS, MINHA ORAÇÃO
QUE HUMILDE SOBE A TI COM GRATIDÃO
TU ÉS MEU MEDIADOR, MEU REI E SALVADOR
QUE SEMPRE EM TEU AMOR POSSA EU VIVER
AMÉM.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('fcc5ec50-a714-45fc-9b72-cfb98b681243', '45ab58b2-d293-45c7-aa75-090fcd968b24');
