INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fcdd08e5-5c8a-4b7c-b041-39b78453a3f7', 'Um Milagre É', '275', 'Leonardo Jundi Eto', 'Básico', 'G', 'Morte, Ressureição e Salvação', 'UM MILAGRE É
A MINHA VIDA AQUI NESTE LUGAR,
SEMPRE A TEUS PÉS.
DESDE AQUELE DIA
EM QUE ME ALCANÇOU
EU VIVO PARA AGRADECER
O TEU GRANDE AMOR.

*CORO
ESSE MILAGRE É
A TUA MORTE LÁ NA CRUZ, JESUS,
DANDO-ME A VIDA,
CURANDO TODAS AS MINHAS FERIDAS.

HOJE POSSO OUVIR
A TUA VOZ EM MIM,
EU POSSO TER A TUA DIREÇÃO.
SE VOCÊ QUISER TAMBÉM O PODE TER,
É SÓ ABRIR SEU CORAÇÃO E O RECEBER.

*CORO
ESSE MILAGRE É
A TUA MORTE LÁ NA CRUZ, JESUS,
DANDO-ME A VIDA,
CURANDO TODAS AS MINHAS FERIDAS.
/INSTRUMENTOS

*CORO
ESSE MILAGRE É
A TUA MORTE LÁ NA CRUZ, JESUS,
DANDO-ME A VIDA,
CURANDO TODAS AS MINHAS FERIDAS.
/FINAL
DANDO-ME A VIDA,
CURANDO TODAS AS MINHAS FERIDAS.
');
