INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fce4e0c2-bd04-4743-ad7f-e6ae13d2ed0b', 'Eu quero cantar de gozo e de paz', '623', 'Jorgemar Souza Madeira', 'Básico', 'G', 'Louvor', 'EU QUERO CANTAR DE GOZO E DE PAZ,
SENTIR A ALEGRIA QUE JESUS CRISTO TRAZ;
EU QUERO SENTIR A PRESENÇA DO AMOR,
EM MEU CORAÇÃO, O SALVADOR.

EU QUERO DIZER PARA O MUNDO
QUE O SENHOR DEUS ENVIOU
SEU FILHO A MORRER NUMA CRUZ,
TUDO PORQUE ME AMOU;
EU QUERO CHORAR DE ALEGRIA
E VIVER A CANTAR,
TUDO PORQUE MEU JESUS
MORREU PARA ME SALVAR.
/INSTRUMENTOS

EU QUERO CANTAR DE GOZO E DE PAZ,
SENTIR A ALEGRIA QUE JESUS CRISTO TRAZ;
EU QUERO SENTIR A PRESENÇA DO AMOR,
EM MEU CORAÇÃO, O SALVADOR.

FINAL 2X
EU QUERO DIZER PARA O MUNDO
QUE O SENHOR DEUS ENVIOU
SEU FILHO A MORRER NUMA CRUZ,
TUDO PORQUE ME AMOU;
EU QUERO CHORAR DE ALEGRIA
E VIVER A CANTAR,
TUDO PORQUE MEU JESUS
MORREU PARA ME SALVAR.
');
