INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fd64e158-2e3d-4649-ada0-07a52377c7a8', 'A vitória desta igreja é oração', '768', '', 'Marcha', 'C', 'Corinhos', 'A VITÓRIA DESTA IGREJA É ORAÇÃO. (2X)
JESUS ATENDE TODA NOSSA PETIÇÃO;
DESPERTA AGORA TU QUE DORMES
MEU IRMÃO.

VAMOS ORAR TODOS CRENTES
DESTA IGREJA
PARA QUE JESUS AO NOSSO LADO
SEMPRE ESTEJA.

FINAL 2X
JESUS EM BREVE
VEM BUSCAR A SUA IGREJA, 
POIS QUEM NÃO ORA
JÁ ESTÁ FORA DA PELEJA.
');
