INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fe296940-517d-4128-9595-5dab5b5cf038', 'Sei que na cruz seu sangue verteu', '061', 'L.P.S.', 'Fox', 'D', 'Crianças e Adolescentes', 'SEI QUE NA CRUZ SEU SANGUE VERTEU,
