INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fe3c6f77-03fd-44c3-afa9-c0a3da605418', 'Quem irá (Preciosa semente)', '141', 'S.G.D.', 'Balada', 'Dm', 'Crianças e Adolescentes', 'CANTAR 2X
