INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fe4fd434-3dbc-4304-a827-14fe20459574', 'Vou pra Jerusalém', '192', 'C.M.V.C.S.', 'Balada', 'C', 'Crianças e Adolescentes', 'VOU PRA JERUSALÉM,
A CIDADE DO MEU REI.
ALI VEREI A JESUS, MEU SALVADOR,
O FILHO DE DEUS.
VOU PRA JERUSALÉM.

EM RUAS DE OURO SEI QUE ANDAREI,
DA FONTE CRISTALINA LÁ DESFRUTAREI
E A GLÓRIA ETERNA DE DEUS
ME ILUMINARÁ.

PRA SEMPRE ESTAREI
NA ETERNA MANSÃO,
COM OS ANJOS,
ADORANDO O SALVADOR
QUE EM MEU LUGAR MORREU,
MAS VIVO ELE É.

SENTADO ESTÁ NO TRONO
COM PODER E GLÓRIA,
HONRA E LOUVOR, POR ISSO
VOU PRA JERUSALÉM. (3X)
');
