INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fe59d2c1-963f-4a86-a755-812a352d52ad', 'O Senhor é quem cuida de mim', '114', 'C.M.V.C.S.', 'Balada', 'D', 'Crianças e Adolescentes', 'O SENHOR É QUEM CUIDA DE MIM. (2X)
NADA HEI DE TEMER,
COM JESUS VOU VENCER,
POIS EU SEI QUE ELE CUIDA DE MIM.

A JESUS SERVIREI COM AMOR,
POIS EU SEI QUE ELE É MEU SALVADOR.
AO MEU LADO ESTÁ, NUNCA VAI ME DEIXAR,
POIS EU SEI QUE ELE CUIDA DE MIM.
');
