INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fe5eba03-b1a7-472d-9b54-035b101f7917', 'Os sinais do fim se cumprem', '482', 'Sérgio Paulo Ferreira de Matos', 'Básico', 'E', 'Volta de Jesus e Eternidade', 'OS SINAIS DO FIM SE CUMPREM 
EM NOSSA GERAÇÃO,
TODA TERRA SE ANGUSTIA, 
GEME A CRIAÇÃO,
TREVAS CAEM SOBRE O MUNDO, 
SÓ UM POVO TEM A LUZ,
QUEM TEM SEDE VENHA E BEBA, 
ÁGUA VIVA É JESUS.

*CORO
DEUS É POR NÓS,
QUEM SERÁ CONTRA NÓS?
QUEM PODERÁ SEPARAR-NOS
DO AMOR QUE HÁ EM JESUS?

NÓS TAMBÉM JUNTOS GEMEMOS,
ANSIANDO A PARTIDA,
NÃO GEMEMOS PARA A MORTE,
MAS PELA ETERNA VIDA,
POIS JÁ A LUZ A VISTA ALCANÇA,
NOVO DIA VAI RAIAR,
CUMPRE-SE NOSSA ESPERANÇA,
JESUS CRISTO VAI VOLTAR!

*CORO 2X
DEUS É POR NÓS,
QUEM SERÁ CONTRA NÓS?
QUEM PODERÁ SEPARAR-NOS
DO AMOR QUE HÁ EM JESUS?
');
