INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fed60764-6a52-4be4-89a4-aaa309533716', 'O fio da escarlata é o mistério', '203', 'E.H.M.R.', 'Marcha', 'A', 'Crianças e Adolescentes', 'O FIO DE ESCARLATA É O MISTÉRIO
DA FÉ E DA GRAÇA DO SENHOR.
FOI REVELADO A NÓS E NOS LIGA
À PRESENÇA DE DEUS, O SENHOR.

*CORO
SEGUINDO O FIO DE ESCARLATA
VEREMOS MARANATA.
ORA VEM, SENHOR JESUS!
A IGREJA TRIUNFANTE,
ENTOANDO UM NOVO CANTO,
SUBIRÁ PRA MORAR COM JESUS.

ESTE FIO DE ESCARLATA REPRESENTA
O SANGUE DE JESUS:
NOVA ALIANÇA, VÉU RASGADO,
NOVO CAMINHO PARA O CÉU.

*CORO
SEGUINDO O FIO DE ESCARLATA
VEREMOS MARANATA.
ORA VEM, SENHOR JESUS!
/FINAL 2X
A IGREJA TRIUNFANTE,
ENTOANDO UM NOVO CANTO,
SUBIRÁ PRA MORAR COM JESUS.
');
