INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('fef0d7bf-af37-4a17-b5be-8517c0c3697e', 'Nosso Louvor', '681', 'Luciana Monteiro Carneiro Simora', 'Balada', 'C', 'Grupo de Louvor', 'NOSSO LOUVOR VAMOS TE OFERTAR
PELO QUE ÉS, PELO QUE FARÁS;
NÃO HÁ PALAVRAS QUE POSSAM EXPRESSAR
NOSSA ADORAÇÃO A TI, SENHOR.
/INSTRUMENTOS

COM GRATIDÃO (COM GRATIDÃO)
VAMOS TE ADORAR (ADORAR)
PELO QUE ÉS, PELO QUE FARÁS; (EXPRESSAR)
NÃO HÁ PALAVRAS QUE POSSAM EXPRESSAR
NOSSO AMOR A TI, SENHOR.

*CORO
MAJESTOSO (MAJESTOSO),
PODEROSO ÉS, GRAÇAS TE DAMOS
POR TUA MISERICÓRDIA,
A TI PERTENCE TODO O LOUVOR.
/INSTRUMENTOS

NOSSO REFÚGIO E DIREÇÃO, (ÉS TU, SENHOR)
NOSSO AMPARO E PROTEÇÃO,
NOSSO ABRIGO NO TEMPORAL ÉS TU, SENHOR.
COM GRATIDÃO VAMOS TE ADORAR,
EM TEU ALTAR VAMOS OFERTAR
NOSSO LOUVOR, QUE É FRUTO DO TEU AMOR.

*CORO
MAJESTOSO (MAJESTOSO),
PODEROSO ÉS, GRAÇAS TE DAMOS
POR TUA MISERICÓRDIA,
A TI PERTENCE TODO O LOUVOR.
/FINAL
MAJESTOSO (MAJESTOSO),
PODEROSO ÉS, GRAÇAS TE DAMOS,
A TI PERTENCE TODO O LOUVOR (2X)
');
