INSERT INTO praises (id, name, number, author, rhythm, tonality, category, lyrics) VALUES ('ff3bdf1c-1610-4f09-9919-e560750088c8', 'Deus, Somente Deus (Coro Masculino)', '', '', '', '', '', 'CORO
OLHAR SOMENTE A TI, SENHOR,
OLHAR SOMENTE A TI, SENHOR,
OLHAR SOMENTE A TI, SENHOR,
E NÃO OLHAR ATRÁS;
SEGUIR TEU CAMINHAR, SENHOR,
SEGUIR SEM VACILAR, SENHOR,
PROSTRADO EM TEU ALTAR,
SENHOR, E NÃO OLHAR ATRÁS.

NA MINHA ANGÚSTIA
EU PROCURO ME CHEGAR,
PROCURO SÓ OLHAR
A FACE DO SENHOR;
E QUANDO AS LUTAS VEM
PERTURBAR A MINHA PAZ,
PROPONHO SÓ PRA MIM
OLHAR SOMENTE A TI.

O MUNDO É MUITO BELO
E FARTO DE ILUSÃO,
MAS ISSO NÃO TRADUZ
PRA MIM SATISFAÇÃO;
EU OLHO PARA O CÉU,
AVISTO UMA LUZ,
ENTÃO REPITO ASSIM:
OLHAR SÓ PRA JESUS.
');
INSERT INTO praise_tags (praise_id, tag_id) VALUES ('ff3bdf1c-1610-4f09-9919-e560750088c8', '45ab58b2-d293-45c7-aa75-090fcd968b24');
